@app.template_global()
def school_whatsapp_chat_url(phone_raw):
    """https://wa.me/… click-to-chat link from a school WhatsApp / phone number."""
    if not phone_raw:
        return ''
    digits = re.sub(r'\D', '', str(phone_raw).strip())
    if not digits:
        return ''
    if digits.startswith('0') and len(digits) >= 9:
        digits = '254' + digits[1:]
    elif len(digits) == 9 and not digits.startswith('254'):
        digits = '254' + digits
    return f'https://wa.me/{digits}'


# Employee sub-roles stored in employees.role — must match MySQL ENUM, role switch, and UI
EMPLOYEE_SUB_ROLES = (
    'employee', 'super admin', 'head of institution', 'deputy head of institution', 'curriculum coordinator',
    'teachers', 'accountant', 'secretary', 'librarian', 'warden', 'transport manager', 'store manager', 'technician', 'cateress',
)
EMPLOYEE_SUB_ROLES_SET = frozenset(EMPLOYEE_SUB_ROLES)

# When staff have rows in employee_permissions, check_permission_or_role normally denies
# unspecified keys. Heads and super admins still use role-based staff actions for these keys.
HEAD_OF_INSTITUTION_STAFF_PERMISSION_FALLBACK = frozenset({
    'view_staff', 'add_staff', 'edit_staff', 'delete_staff',
})


def normalize_allocated_role(role: str) -> str:
    """Normalize a role string to a canonical EMPLOYEE_SUB_ROLES value, or '' if invalid."""
    if not role:
        return ''
    r = str(role).strip().lower().replace('-', ' ')
    while '  ' in r:
        r = r.replace('  ', ' ')
    if r == 'teacher':
        r = 'teachers'
    if r in ('principal',):
        r = 'head of institution'
    if r in ('deputy principal',):
        r = 'deputy head of institution'
    if r == 'academic coordinator':
        r = 'curriculum coordinator'
    if r in ('store keeper', 'stores manager'):
        r = 'store manager'
    return r if r in EMPLOYEE_SUB_ROLES_SET else ''


def employee_role_db_match_values(role):
    """Values for SQL IN (...) matching employees.role (handles teacher vs teachers)."""
    canon = normalize_allocated_role(role) or str(role or '').strip().lower().replace('-', ' ')
    if not canon:
        return tuple()
    vals = {canon}
    if canon == 'teachers':
        vals.add('teacher')
    elif canon == 'teacher':
        vals.add('teachers')
    elif not canon.endswith('s'):
        vals.add(canon + 's')
    return tuple(vals)


def _sql_employee_is_teacher(alias='e'):
    """SQL fragment: employee has teacher role (employees.role or employee_roles)."""
    a = alias
    return f"""(
        LOWER(TRIM(REPLACE(REPLACE(COALESCE({a}.role, ''), '-', ' '), '_', ' '))) IN ('teacher', 'teachers')
        OR EXISTS (
            SELECT 1 FROM employee_roles er
            WHERE er.employee_id = {a}.id
              AND LOWER(TRIM(REPLACE(REPLACE(COALESCE(er.role, ''), '-', ' '), '_', ' '))) IN ('teacher', 'teachers')
        )
    )"""


def _sql_employee_is_active_staff(alias='e'):
    """SQL fragment: employee is active (not suspended / left)."""
    a = alias
    return f"COALESCE(LOWER(TRIM({a}.status)), 'active') = 'active'"


def parse_allocated_roles_payload(data, fallback_single_role=None):
    """Parse roles from JSON body: roles[] and/or legacy role string."""
    roles = []
    if isinstance(data, dict):
        raw_list = data.get('roles')
        if isinstance(raw_list, list):
            for item in raw_list:
                nr = normalize_allocated_role(item)
                if nr and nr not in roles:
                    roles.append(nr)
        single = data.get('role') if data.get('role') is not None else fallback_single_role
        if single:
            nr = normalize_allocated_role(single)
            if nr and nr not in roles:
                roles.append(nr)
    elif fallback_single_role:
        nr = normalize_allocated_role(fallback_single_role)
        if nr:
            roles.append(nr)
    return roles


def ensure_employee_roles_schema(cursor):
    """Create employee_roles junction table and backfill from employees.role."""
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS employee_roles (
            id INT AUTO_INCREMENT PRIMARY KEY,
            employee_id INT NOT NULL,
            role VARCHAR(64) NOT NULL,
            is_primary TINYINT(1) NOT NULL DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE KEY uq_employee_role (employee_id, role),
            FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
            INDEX idx_employee_roles_employee (employee_id),
            INDEX idx_employee_roles_role (role)
        )
    """)
    try:
        cursor.execute("""
            INSERT IGNORE INTO employee_roles (employee_id, role, is_primary)
            SELECT e.id, e.role, 1
            FROM employees e
            WHERE e.role IS NOT NULL AND TRIM(e.role) != ''
        """)
    except Exception as backfill_err:
        print(f"Note: employee_roles backfill: {backfill_err}")


def fetch_employee_allocated_roles(cursor, employee_pk_id):
    """Return list of allocated roles for an employee (falls back to employees.role)."""
    ensure_employee_roles_schema(cursor)
    cursor.execute(
        """
        SELECT role FROM employee_roles
        WHERE employee_id = %s
        ORDER BY is_primary DESC, role ASC
        """,
        (employee_pk_id,),
    )
    rows = cursor.fetchall() or []
    roles = []
    for row in rows:
        nr = normalize_allocated_role(row.get('role') if isinstance(row, dict) else row[0])
        if nr and nr not in roles:
            roles.append(nr)
    if roles:
        return roles
    cursor.execute("SELECT role FROM employees WHERE id = %s LIMIT 1", (employee_pk_id,))
    row = cursor.fetchone()
    if row:
        legacy = normalize_allocated_role(row.get('role') if isinstance(row, dict) else row[0])
        if legacy:
            return [legacy]
    return []


def sync_employee_allocated_roles(cursor, employee_pk_id, roles, primary_role=None):
    """Replace allocated roles for an employee; updates employees.role to primary."""
    ensure_employee_roles_schema(cursor)
    cleaned = []
    for r in roles or []:
        nr = normalize_allocated_role(r)
        if nr and nr not in cleaned:
            cleaned.append(nr)
    if not cleaned:
        raise ValueError('At least one valid role is required.')
    primary = normalize_allocated_role(primary_role) if primary_role else cleaned[0]
    if primary not in cleaned:
        primary = cleaned[0]
    cursor.execute("DELETE FROM employee_roles WHERE employee_id = %s", (employee_pk_id,))
    for idx, role in enumerate(cleaned):
        cursor.execute(
            """
            INSERT INTO employee_roles (employee_id, role, is_primary)
            VALUES (%s, %s, %s)
            """,
            (employee_pk_id, role, 1 if role == primary else 0),
        )
    cursor.execute(
        "UPDATE employees SET role = %s, updated_at = CURRENT_TIMESTAMP WHERE id = %s",
        (primary, employee_pk_id),
    )
    return cleaned, primary


def attach_allocated_roles_to_employees(cursor, employees):
    """Attach allocated_roles list to each employee dict in place."""
    if not employees:
        return employees
    ensure_employee_roles_schema(cursor)
    ids = [e['id'] for e in employees if e.get('id') is not None]
    if not ids:
        return employees
    placeholders = ','.join(['%s'] * len(ids))
    cursor.execute(
        f"""
        SELECT employee_id, role, is_primary
        FROM employee_roles
        WHERE employee_id IN ({placeholders})
        ORDER BY is_primary DESC, role ASC
        """,
        tuple(ids),
    )
    by_emp = {}
    for row in cursor.fetchall() or []:
        eid = row.get('employee_id') if isinstance(row, dict) else row[0]
        nr = normalize_allocated_role(row.get('role') if isinstance(row, dict) else row[1])
        if nr:
            by_emp.setdefault(eid, [])
            if nr not in by_emp[eid]:
                by_emp[eid].append(nr)
    for emp in employees:
        eid = emp.get('id')
        roles = by_emp.get(eid)
        if not roles:
            legacy = normalize_allocated_role(emp.get('role'))
            roles = [legacy] if legacy else ['employee']
        emp['allocated_roles'] = roles
    return employees


def complete_employee_login_session(employee, selected_role, remember_me=False):
    """Set Flask session after credentials verified and role chosen."""
    role = normalize_allocated_role(selected_role)
    if not role:
        role = normalize_allocated_role(employee.get('role')) or 'employee'
    session.permanent = bool(remember_me)
    session['user_id'] = employee['id']
    session['email'] = employee['email']
    session['full_name'] = employee['full_name']
    session['role'] = role
    session['employee_id'] = employee['employee_id']
    session['profile_picture'] = employee.get('profile_picture')
    session.pop('auth_pending_employee_pk', None)
    session.pop('auth_pending_remember_me', None)
    register_active_employee_session(employee, role)


# --- Active employee sessions (for technician health-status live list) ---
_ACTIVE_EMPLOYEE_SESSIONS = {}
_ACTIVE_EMPLOYEE_SESSIONS_LOCK = threading.Lock()
_ACTIVE_EMPLOYEE_SESSION_TTL = 45 * 60  # drop after 45 minutes idle
_ACTIVE_EMPLOYEE_TOUCH_MIN_INTERVAL = 15  # seconds between registry writes per browser


def _active_employee_session_payload(employee_or_session, role, sid, logged_in_at=None):
    now = time.time()
    if isinstance(employee_or_session, dict) and 'full_name' in employee_or_session:
        src = employee_or_session
        user_id = src.get('id')
        full_name = (src.get('full_name') or '').strip()
        email = (src.get('email') or '').strip()
        employee_code = (src.get('employee_id') or '').strip()
        profile_picture = src.get('profile_picture')
    else:
        user_id = session.get('user_id')
        full_name = (session.get('full_name') or '').strip()
        email = (session.get('email') or '').strip()
        employee_code = (session.get('employee_id') or '').strip()
        profile_picture = session.get('profile_picture')
    ip = ''
    path = ''
    if has_request_context():
        ip = (request.headers.get('X-Forwarded-For') or request.remote_addr or '').split(',')[0].strip()
        path = (request.environ.get('portal_original_path_info') or request.path or '')[:180]
    return {
        'sid': sid,
        'user_id': user_id,
        'employee_id': employee_code,
        'full_name': full_name or 'Unknown',
        'email': email,
        'role': (role or '').strip().lower() or 'employee',
        'profile_picture': profile_picture,
        'ip': ip,
        'path': path,
        'logged_in_at': float(logged_in_at or now),
        'last_seen': now,
    }


def _active_employee_sessions_redis():
    try:
        from shared_cache import get_redis
        return get_redis()
    except Exception:
        return None


def register_active_employee_session(employee, role):
    """Record an employee browser session after login."""
    if not employee or not employee.get('id'):
        return
    sid = secrets.token_hex(16)
    session['_active_sid'] = sid
    session['_active_sid_touched_at'] = time.time()
    payload = _active_employee_session_payload(employee, role, sid)
    r = _active_employee_sessions_redis()
    if r is not None:
        try:
            key = f'ec:emp_sess:{sid}'
            r.setex(key, _ACTIVE_EMPLOYEE_SESSION_TTL, json.dumps(payload, default=str))
            r.sadd('ec:emp_sess:index', sid)
            return
        except Exception:
            pass
    with _ACTIVE_EMPLOYEE_SESSIONS_LOCK:
        _ACTIVE_EMPLOYEE_SESSIONS[sid] = payload


def unregister_active_employee_session(sid=None, user_id=None):
    """Remove one or all sessions for an employee (logout)."""
    sid = sid or (session.get('_active_sid') if has_request_context() else None)
    user_id = user_id if user_id is not None else (session.get('user_id') if has_request_context() else None)
    r = _active_employee_sessions_redis()
    if r is not None:
        try:
            if sid:
                r.delete(f'ec:emp_sess:{sid}')
                r.srem('ec:emp_sess:index', sid)
            if user_id is not None:
                for member in list(r.smembers('ec:emp_sess:index') or []):
                    raw = r.get(f'ec:emp_sess:{member}')
                    if not raw:
                        r.srem('ec:emp_sess:index', member)
                        continue
                    try:
                        data = json.loads(raw)
                    except Exception:
                        continue
                    if str(data.get('user_id')) == str(user_id):
                        r.delete(f'ec:emp_sess:{member}')
                        r.srem('ec:emp_sess:index', member)
        except Exception:
            pass
    with _ACTIVE_EMPLOYEE_SESSIONS_LOCK:
        if sid:
            _ACTIVE_EMPLOYEE_SESSIONS.pop(sid, None)
        if user_id is not None:
            drop = [k for k, v in _ACTIVE_EMPLOYEE_SESSIONS.items() if str(v.get('user_id')) == str(user_id)]
            for k in drop:
                _ACTIVE_EMPLOYEE_SESSIONS.pop(k, None)


def touch_active_employee_session():
    """Refresh last-seen for the current employee request (throttled)."""
    if not has_request_context():
        return
    role = normalize_allocated_role(session.get('role')) or (session.get('role') or '').strip().lower()
    if not session.get('user_id') or role not in EMPLOYEE_SUB_ROLES_SET:
        return
    now = time.time()
    last_touch = float(session.get('_active_sid_touched_at') or 0)
    sid = session.get('_active_sid')
    if sid and (now - last_touch) < _ACTIVE_EMPLOYEE_TOUCH_MIN_INTERVAL:
        return
    if not sid:
        sid = secrets.token_hex(16)
        session['_active_sid'] = sid
    session['_active_sid_touched_at'] = now

    existing_login = None
    r = _active_employee_sessions_redis()
    if r is not None:
        try:
            raw = r.get(f'ec:emp_sess:{sid}')
            if raw:
                existing_login = (json.loads(raw) or {}).get('logged_in_at')
        except Exception:
            pass
    if existing_login is None:
        with _ACTIVE_EMPLOYEE_SESSIONS_LOCK:
            existing_login = (_ACTIVE_EMPLOYEE_SESSIONS.get(sid) or {}).get('logged_in_at')

    payload = _active_employee_session_payload(None, role, sid, logged_in_at=existing_login)
    if r is not None:
        try:
            r.setex(f'ec:emp_sess:{sid}', _ACTIVE_EMPLOYEE_SESSION_TTL, json.dumps(payload, default=str))
            r.sadd('ec:emp_sess:index', sid)
            return
        except Exception:
            pass
    with _ACTIVE_EMPLOYEE_SESSIONS_LOCK:
        _ACTIVE_EMPLOYEE_SESSIONS[sid] = payload


def list_active_employee_sessions():
    """Return active employee sessions sorted by most recently seen."""
    now = time.time()
    rows = []
    r = _active_employee_sessions_redis()
    if r is not None:
        try:
            members = list(r.smembers('ec:emp_sess:index') or [])
            for sid in members:
                raw = r.get(f'ec:emp_sess:{sid}')
                if not raw:
                    r.srem('ec:emp_sess:index', sid)
                    continue
                try:
                    data = json.loads(raw)
                except Exception:
                    r.srem('ec:emp_sess:index', sid)
                    continue
                last_seen = float(data.get('last_seen') or 0)
                if now - last_seen > _ACTIVE_EMPLOYEE_SESSION_TTL:
                    r.delete(f'ec:emp_sess:{sid}')
                    r.srem('ec:emp_sess:index', sid)
                    continue
                rows.append(data)
        except Exception:
            rows = []
    if not rows:
        with _ACTIVE_EMPLOYEE_SESSIONS_LOCK:
            expired = []
            for sid, data in _ACTIVE_EMPLOYEE_SESSIONS.items():
                last_seen = float(data.get('last_seen') or 0)
                if now - last_seen > _ACTIVE_EMPLOYEE_SESSION_TTL:
                    expired.append(sid)
                    continue
                rows.append(dict(data))
            for sid in expired:
                _ACTIVE_EMPLOYEE_SESSIONS.pop(sid, None)

    def _fmt_ago(ts):
        try:
            ago = int(max(0, now - float(ts)))
        except (TypeError, ValueError):
            return '—'
        if ago < 60:
            return f'{ago}s ago'
        if ago < 3600:
            return f'{ago // 60}m ago'
        return f'{ago // 3600}h ago'

    # Deduplicate by user_id keeping newest last_seen (one row per employee)
    by_user = {}
    for row in rows:
        uid = row.get('user_id')
        prev = by_user.get(uid)
        if not prev or float(row.get('last_seen') or 0) >= float(prev.get('last_seen') or 0):
            by_user[uid] = row
    out = []
    for row in sorted(by_user.values(), key=lambda x: float(x.get('last_seen') or 0), reverse=True):
        out.append({
            'user_id': row.get('user_id'),
            'employee_id': row.get('employee_id') or '',
            'full_name': row.get('full_name') or 'Unknown',
            'email': row.get('email') or '',
            'role': row.get('role') or 'employee',
            'ip': row.get('ip') or '',
            'path': row.get('path') or '',
            'logged_in_at': datetime.fromtimestamp(float(row.get('logged_in_at') or now)).strftime('%Y-%m-%d %H:%M:%S'),
            'last_seen_at': datetime.fromtimestamp(float(row.get('last_seen') or now)).strftime('%Y-%m-%d %H:%M:%S'),
            'last_seen_ago': _fmt_ago(row.get('last_seen')),
            'is_current': bool(
                has_request_context()
                and session.get('user_id') is not None
                and str(session.get('user_id')) == str(row.get('user_id'))
            ),
        })
    return out


def role_to_slug(role: str) -> str:
    """Stable URL segment for a role (spaces → hyphens, lowercased)."""
    if not role:
        return 'employee'
    return role.strip().lower().replace(' ', '-')


def slug_to_role(slug: str) -> str:
    """Map URL role slug (e.g. head-of-institution) back to canonical role name."""
    if not slug:
        return ''
    s = slug.strip().lower()
    for r in EMPLOYEE_SUB_ROLES:
        if role_to_slug(r) == s:
            return r
    if s == 'parent':
        return 'parent'
    if s == 'student':
        return 'student'
    return ''


@app.template_global()
def portal_role_from_request_path() -> str:
    """Role for portal theme from /<role-slug>/… URL when session role differs."""
    if not has_request_context():
        return ''
    # RootRolePathRewriteMiddleware maps /teachers/… → /dashboard/employee/…; keep slug from the browser URL.
    raw_path = (
        request.environ.get('portal_original_path_info')
        or request.path
        or ''
    )
    parts = raw_path.strip('/').split('/')
    if not parts:
        return ''
    if parts[0].lower() == 'dashboard' and len(parts) > 1:
        return slug_to_role(parts[1])
    return slug_to_role(parts[0])


# Slugs allowed in /dashboard/<slug>/... before /dashboard/employee/... rewrite
EMPLOYEE_ROLE_SLUGS = frozenset(role_to_slug(r) for r in EMPLOYEE_SUB_ROLES)


def session_employee_role_slug() -> str:
    """Role slug for staff dashboard URLs: session role, or technician view-as role."""
    if not has_request_context():
        return 'employee'
    ur = (session.get('role') or '').lower().strip()
    ve = (session.get('viewing_as_employee_role') or '').lower().strip()
    if ur == 'technician' and ve:
        raw = ve
    elif ur in EMPLOYEE_SUB_ROLES:
        raw = ur
    else:
        raw = 'employee'
    return role_to_slug(raw)


def normalize_employee_dashboard_content_role(user_role, is_technician, viewing_as_employee_role):
    """Canonical role string for employee dashboard sidebar + home content (hyphens, legacy titles)."""
    ur = (user_role or '').strip().lower().replace('-', ' ')
    while '  ' in ur:
        ur = ur.replace('  ', ' ')
    ve = (viewing_as_employee_role or '').strip().lower().replace('-', ' ')
    while '  ' in ve:
        ve = ve.replace('  ', ' ')
    base = ve if (is_technician and ve) else ur
    if base == 'academic coordinator':
        return 'curriculum coordinator'
    return base or 'employee'


def _technician_portal_preview_role():
    """When a technician opens /teachers, /parent, etc., preview that portal role."""
    if not has_request_context():
        return None
    if (session.get('role') or '').lower().strip() != 'technician':
        return None
    pr = portal_role_from_request_path()
    if pr in ('teacher', 'teachers'):
        return 'teachers'
    if pr == 'parent':
        return 'parent'
    return None


def _fetch_teachers_for_technician_preview(cursor):
    """Active teachers for technician test picker on /teachers."""
    rows = []
    try:
        cursor.execute("""
            SELECT e.id, e.full_name, e.employee_id
            FROM employees e
            WHERE LOWER(TRIM(COALESCE(e.role, ''))) IN ('teachers', 'teacher')
            ORDER BY e.full_name ASC
        """)
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                rows.append({
                    'id': r.get('id'),
                    'full_name': (r.get('full_name') or '').strip(),
                    'employee_id': (r.get('employee_id') or '').strip(),
                })
            else:
                rows.append({
                    'id': r[0] if len(r) > 0 else None,
                    'full_name': (r[1] if len(r) > 1 else '') or '',
                    'employee_id': (r[2] if len(r) > 2 else '') or '',
                })
    except Exception as ex:
        print(f"_fetch_teachers_for_technician_preview: {ex}")
    return rows


def employee_dashboard_path(subpath: str = '') -> str:
    """Build /<role-slug>/[subpath] (public URLs; middleware maps to /dashboard/employee/...)."""
    subpath = (subpath or '').strip('/')
    slug = session_employee_role_slug() if has_request_context() else 'employee'
    tail = '/'.join(quote(seg, safe='') for seg in subpath.split('/') if seg)
    base = f'/{slug}'
    return base + ('/' + tail if tail else '')


@app.template_global()
def employee_staff_settings_url(settings_role: str, **query) -> str:
    """Prefixed staff settings URL: /<session-slug>/settings/<role slug>[?query]; curriculum coordinator timetable uses curriculum-timetable-settings."""
    r = (settings_role or 'employee').strip()
    if role_to_slug(r) == role_to_slug('curriculum coordinator'):
        base = employee_dashboard_path('curriculum-timetable-settings')
    else:
        role_path_segment = role_to_slug(r)
        base = employee_dashboard_path(f'settings/{role_path_segment}')
    filtered = {k: v for k, v in query.items() if v is not None and str(v) != ''}
    if filtered:
        return base + '?' + urlencode(filtered)
    return base


def parent_dashboard_path(subpath: str = '') -> str:
    """Parent user dashboard URLs: /parent/..."""
    subpath = (subpath or '').strip('/')
    base = '/parent'
    return base + ('/' + subpath if subpath else '')


def student_dashboard_path(subpath: str = '') -> str:
    """Student user dashboard URLs: /student/..."""
    subpath = (subpath or '').strip('/')
    base = '/student'
    return base + ('/' + subpath if subpath else '')


@app.template_global()
def dashboard_home_url():
    """Single “Dashboard” home link for header/menu from session role (incl. technician view-as)."""
    if not has_request_context():
        return '/'
    r = (session.get('role') or '').lower().strip()
    viewing = (session.get('viewing_as_role') or '').lower().strip()
    if viewing == 'parent' or r == 'parent':
        return parent_dashboard_path()
    if viewing == 'student' or r == 'student':
        return student_dashboard_path()
    if r in EMPLOYEE_SUB_ROLES:
        return employee_dashboard_path()
    return '/'


@app.template_global()
def sidebar_profile_url():
    """Profile page URL for the signed-in user (employee / parent / student; incl. technician view-as)."""
    if not has_request_context():
        return '/'
    r = (session.get('role') or '').lower().strip()
    viewing = (session.get('viewing_as_role') or '').lower().strip()
    if viewing == 'parent' or r == 'parent':
        return url_for('profile', role='parent')
    if viewing == 'student' or r == 'student':
        return url_for('profile', role='student')
    return url_for('profile', role='employee')


@app.template_global()
def sidebar_settings_url():
    """Account / role settings URL for sidebar (school system settings for super admin & bare technician)."""
    if not has_request_context():
        return '/'
    r = (session.get('role') or '').lower().strip()
    ve = (session.get('viewing_as_employee_role') or '').lower().strip()
    viewing = (session.get('viewing_as_role') or '').lower().strip()
    if viewing == 'parent' or r == 'parent':
        return url_for('settings', role='parent')
    if viewing == 'student' or r == 'student':
        return url_for('settings', role='student')
    if r == 'technician' and not ve:
        return employee_dashboard_path('system-settings')
    eff = ve if r == 'technician' and ve else r
    if eff == 'super admin':
        return employee_dashboard_path('system-settings')
    if eff == 'head of institution':
        return employee_staff_settings_url('head of institution')
    if eff == 'deputy head of institution':
        return employee_staff_settings_url('deputy head of institution')
    if eff == 'curriculum coordinator':
        return employee_staff_settings_url('curriculum coordinator')
    return employee_staff_settings_url('employee')


# First path segment → internal dashboard (must not collide with other top-level routes)
ROOT_DASHBOARD_PREFIXES = frozenset(EMPLOYEE_ROLE_SLUGS) | frozenset({'parent', 'student'})

# After /<employee-role-slug>/, first segment of the remainder: routes that live at site root (not /dashboard/employee/…)
EMPLOYEE_SCOPED_ROOT_SEGMENTS = frozenset({
    'staff-management', 'student-management', 'users-roles', 'system-settings', 'database',
    'health-status',
    'assign-roles-approve', 'approve-employee', 'update-employee', 'delete-employee',
    'toggle-suspend-employee', 'get-employee', 'get-student', 'check-student-id',
    'check-staff-number',
    'update-student', 'delete-student', 'approve-student', 'profile', 'settings',
    'switch-role', 'role-switch', 'switch-employee', 'admission', 'register-employee',
    'check-employee-id', 'login', 'login-select-role', 'logout', 'terms-and-conditions', 'api',
})

# /parent/<segment> public routes (not rewritten to /dashboard/parent/…)
PARENT_PUBLIC_SEGMENTS = frozenset({
    'portal-setup',
    'forgot-password',
    'reset-password',
})

# /student/<segment> public account-recovery routes
STUDENT_PUBLIC_SEGMENTS = frozenset({
    'forgot-password',
    'reset-password',
})

# /<employee-role-slug>/<segment> public account-recovery routes
EMPLOYEE_PUBLIC_SEGMENTS = frozenset({
    'forgot-password',
    'reset-password',
})


class RootRolePathRewriteMiddleware:
    """Rewrite /<role-slug>/... → real Flask paths (dashboard, parent/student, or root-level app URLs)."""
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        path = environ.get('PATH_INFO', '') or ''
        if not path or path == '/':
            return self.app(environ, start_response)
        if path.startswith('/dashboard/'):
            return self.app(environ, start_response)
        parts = [p for p in path.split('/') if p]
        if not parts:
            return self.app(environ, start_response)
        seg = parts[0].lower()
        if seg not in ROOT_DASHBOARD_PREFIXES:
            return self.app(environ, start_response)
        rest = '/'.join(parts[1:]) if len(parts) > 1 else ''
        if seg == 'parent':
            rest_first = rest.split('/')[0].lower() if rest else ''
            if rest_first in PARENT_PUBLIC_SEGMENTS:
                return self.app(environ, start_response)
            new_path = '/dashboard/parent' + ('/' + rest if rest else '')
        elif seg == 'student':
            rest_first = rest.split('/')[0].lower() if rest else ''
            if rest_first in STUDENT_PUBLIC_SEGMENTS:
                return self.app(environ, start_response)
            new_path = '/dashboard/student' + ('/' + rest if rest else '')
        elif not rest:
            new_path = '/dashboard/employee'
        else:
            rest_first = rest.split('/')[0].lower()
            if rest_first in EMPLOYEE_PUBLIC_SEGMENTS:
                return self.app(environ, start_response)
            if rest_first in EMPLOYEE_SCOPED_ROOT_SEGMENTS:
                new_path = '/' + rest
            else:
                new_path = '/dashboard/employee/' + rest
        environ = dict(environ)
        environ['portal_original_path_info'] = path
        environ['PATH_INFO'] = new_path
        return self.app(environ, start_response)


class DashboardRolePathRewriteMiddleware:
    """Rewrite /dashboard/<role-slug>/... → /dashboard/employee/... so existing routes match."""
    def __init__(self, app):
        self.app = app

    def __call__(self, environ, start_response):
        path = environ.get('PATH_INFO', '') or ''
        if path.startswith('/dashboard/'):
            parts = [p for p in path.split('/') if p]
            if len(parts) >= 2 and parts[0] == 'dashboard':
                seg = parts[1].lower()
                if seg in EMPLOYEE_ROLE_SLUGS and seg != 'employee':
                    rest = '/'.join(parts[2:]) if len(parts) > 2 else ''
                    new_path = '/dashboard/employee' + ('/' + rest if rest else '')
                    environ = dict(environ)
                    environ['portal_original_path_info'] = path
                    environ['PATH_INFO'] = new_path
        return self.app(environ, start_response)


