def allowed_communication_attachment(filename):
    """Attachments for communication centre broadcasts."""
    if not filename or '.' not in filename:
        return False
    return filename.rsplit('.', 1)[1].lower() in ALLOWED_COMMUNICATION_EXTENSIONS


def allowed_teaching_resource_file(filename):
    """Uploaded files for teacher class/subject learning resources."""
    if not filename or '.' not in filename:
        return False
    return filename.rsplit('.', 1)[1].lower() in ALLOWED_TEACHING_RESOURCE_EXTENSIONS

def allowed_file(filename):
    """Check if file extension is allowed"""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS


def _save_optimized_image(file_storage, folder, filename_stem, preset='profile'):
    """
    Save an uploaded image with resize/compress. folder is e.g. static/uploads/profiles.
    Returns static-relative path (uploads/...) or None.
    """
    if not file_storage or not getattr(file_storage, 'filename', None):
        return None
    filename = (file_storage.filename or '').strip()
    if not filename or not allowed_file(filename):
        return None
    stem = secure_filename(filename_stem or 'image') or 'image'
    dest_path = os.path.join(folder, f'{stem}.jpg')
    saved_path = optimize_and_save(file_storage, dest_path, preset=preset)
    if not saved_path:
        return None
    return static_relative_path(saved_path)


_STUDENT_PROFILE_IMAGE_COLUMN_READY = False


def ensure_student_profile_image_column(cursor):
    """Ensure students.profile_image exists (reports, parent portal, student management)."""
    global _STUDENT_PROFILE_IMAGE_COLUMN_READY
    if _STUDENT_PROFILE_IMAGE_COLUMN_READY:
        return True
    if _table_has_column(cursor, 'students', 'profile_image'):
        _STUDENT_PROFILE_IMAGE_COLUMN_READY = True
        return True
    try:
        cursor.execute(
            """
            ALTER TABLE students
            ADD COLUMN profile_image VARCHAR(500) NULL
            AFTER special_needs
            """
        )
        _STUDENT_PROFILE_IMAGE_COLUMN_READY = True
        return True
    except Exception as e:
        print(f"ensure_student_profile_image_column: {e}")
        return False


def ensure_student_parent_info_verified_columns(cursor):
    """Track when a parent has reviewed and confirmed student records during portal setup."""
    ok = True
    if not _table_has_column(cursor, 'students', 'parent_info_verified'):
        try:
            after_col = 'profile_image' if _table_has_column(cursor, 'students', 'profile_image') else 'special_needs'
            cursor.execute(
                f"""
                ALTER TABLE students
                ADD COLUMN parent_info_verified TINYINT(1) NOT NULL DEFAULT 0
                AFTER {after_col}
                """
            )
        except Exception as e:
            print(f"ensure_student_parent_info_verified_columns verified: {e}")
            ok = False
    if not _table_has_column(cursor, 'students', 'parent_info_verified_at'):
        try:
            cursor.execute(
                """
                ALTER TABLE students
                ADD COLUMN parent_info_verified_at DATETIME NULL
                AFTER parent_info_verified
                """
            )
        except Exception as e:
            print(f"ensure_student_parent_info_verified_columns verified_at: {e}")
            ok = False
    return ok


def _format_date_input_value(value):
    if not value:
        return ''
    if hasattr(value, 'strftime'):
        return value.strftime('%Y-%m-%d')
    return str(value)[:10]


def _serialize_parent_setup_student_row(row):
    """Normalize DB row for parent student-info forms (dates as YYYY-MM-DD strings)."""
    if not row:
        return None
    out = dict(row)
    out['date_of_birth_input'] = _format_date_input_value(out.get('date_of_birth'))
    out['parent_info_verified'] = bool(int(out.get('parent_info_verified') or 0))
    prof = (out.get('profile_image') or '').strip()
    out['profile_image_url'] = _student_profile_image_url(prof) if prof else ''
    return out


