# Function to detect if running on hosted server
def is_hosted():
    """Check if the application is running on the hosted server"""
    # Check if we're in a typical cPanel / production path
    current_path = os.path.abspath(os.getcwd()).replace('\\', '/')
    hosted_path_markers = (
        '/home1/',
        '/home2/',
        '/home/',
        '/elimu_centric',
        '/project_lucas',
        '/PROJECT_LUCAS_SCHOOL',
        '/project_lucas_git',
        '/kwetude',
        '/kanyakine',
        '/SCHOOL',
    )
    # Local Windows drives are never hosted
    if not (len(current_path) >= 2 and current_path[1] == ':'):
        if any(m in current_path for m in hosted_path_markers):
            return True

    # Check for environment variable that indicates hosting
    if os.environ.get('IS_HOSTED', '').lower() in ['true', '1', 'yes', 'on']:
        return True

    # Check if DB_HOST is set to something other than localhost (indicates hosted)
    db_host = os.environ.get('DB_HOST', 'localhost')
    if db_host not in ('localhost', '127.0.0.1', ''):
        return True

    return False

# Database configuration - automatically detect hosted vs local
# Hosted: keep timeouts under typical Passenger/Apache request limits so the
# app fails fast instead of hanging until the proxy returns 503.
_DB_CONNECT_TIMEOUT = max(1, _env_int('DB_CONNECT_TIMEOUT', 5))
_DB_READ_TIMEOUT = max(5, _env_int(
    'DB_READ_TIMEOUT',
    45 if is_hosted() else 120,
))
_DB_WRITE_TIMEOUT = max(5, _env_int(
    'DB_WRITE_TIMEOUT',
    45 if is_hosted() else 120,
))

_DB_CONFIG_BASE = {
    'host': os.environ.get('DB_HOST', 'localhost'),
    'user': os.environ.get(
        'DB_USER',
        'elimucentric_school' if is_hosted() else 'root',
    ),
    'password': os.environ.get('DB_PASSWORD', ''),
    'database': os.environ.get(
        'DB_NAME',
        'elimucentric_school' if is_hosted() else 'modern_school',
    ),
    'charset': 'utf8mb4',
    'cursorclass': pymysql.cursors.DictCursor,
    'connect_timeout': _DB_CONNECT_TIMEOUT,
    'read_timeout': _DB_READ_TIMEOUT,
    'write_timeout': _DB_WRITE_TIMEOUT,
    'autocommit': False,
}
# Optional session init (some shared hosts reject SET SESSION wait_timeout).
_DB_INIT_COMMAND = (os.environ.get('DB_INIT_COMMAND') or '').strip()
if _DB_INIT_COMMAND:
    _DB_CONFIG_BASE['init_command'] = _DB_INIT_COMMAND
DB_CONFIG = dict(_DB_CONFIG_BASE)

# Startup identity (no password) — confirms which env/credentials the process is using.
try:
    print(
        f"Env file: {env_file_label()} | hosted={is_hosted()} | "
        f"MySQL {DB_CONFIG.get('user')}@{DB_CONFIG.get('host')}/{DB_CONFIG.get('database')}"
    )
except Exception:
    pass

# Long cache for /static on production hosts (repeat visits skip re-downloading CSS/JS)
if is_hosted():
    app.config['SEND_FILE_MAX_AGE_DEFAULT'] = _env_int('STATIC_MAX_AGE', 86400)

def _mysql_errno(exc):
    """Best-effort MySQL errno from pymysql / MariaDB exceptions."""
    args = getattr(exc, 'args', None) or ()
    if args and isinstance(args[0], int):
        return args[0]
    return None


def _is_benign_schema_error(exc):
    """
    True for expected idempotent-schema failures (column/key/constraint already present).
    Keeps startup logs clean when init_db re-runs ALTER/ADD on an existing DB.
    """
    errno = _mysql_errno(exc)
    # 1060 duplicate column, 1061 duplicate key name, 1050 table exists,
    # 1022/121 duplicate key on write (FK/constraint name clash), 1826 duplicate FK
    if errno in (1050, 1060, 1061, 1022, 121, 1826):
        return True
    msg = str(exc).lower()
    markers = (
        'duplicate column',
        'duplicate key name',
        'duplicate key on write',
        'already exists',
        'errno: 121',
        'multiple primary key',
        'check that column/key exists',
        "can't drop",  # DROP INDEX when missing
        'check that it exists',
    )
    return any(m in msg for m in markers)


def _schema_ignore_existing(exc, label=None):
    """Swallow duplicate-schema errors; log unexpected ones only."""
    if _is_benign_schema_error(exc):
        return
    if label:
        print(f"Schema note ({label}): {exc}")
    else:
        print(f"Schema note: {exc}")


def _row_count_value(row):
    """Read COUNT(*) / count from a cursor row (dict or tuple)."""
    if row is None:
        return None
    if isinstance(row, dict):
        if 'count' in row:
            return row['count']
        if 'COUNT(*)' in row:
            return row['COUNT(*)']
        return next(iter(row.values()), None)
    return row[0]


def ensure_database_exists():
    """Check if database exists, create it if it doesn't"""
    db_name = DB_CONFIG['database']
    # Connect without specifying database
    config_without_db = {k: v for k, v in DB_CONFIG.items() if k != 'database'}
    
    try:
        connection = pymysql.connect(**config_without_db)
        with connection.cursor() as cursor:
            # Check if database exists
            cursor.execute(f"SHOW DATABASES LIKE '{db_name}'")
            result = cursor.fetchone()
            
            if not result:
                # Database doesn't exist, create it
                cursor.execute(f"CREATE DATABASE {db_name} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci")
                connection.commit()
                print(f"Database '{db_name}' created successfully.")
        connection.close()
        return True
    except Exception as e:
        print(f"Error ensuring database exists: {e}")
        return False

def check_table_exists(connection, table_name):
    """Check if a table exists in the database"""
    try:
        with connection.cursor() as cursor:
            cursor.execute(f"""
                SELECT COUNT(*) as count 
                FROM information_schema.tables 
                WHERE table_schema = %s AND table_name = %s
            """, (DB_CONFIG['database'], table_name))
            result = cursor.fetchone()
            return result['count'] > 0
    except Exception as e:
        print(f"Error checking table existence: {e}")
        return False

def generate_student_id(connection):
    """Generate a unique student ID using format from school_settings (prefix + padded number)."""
    try:
        with connection.cursor() as cursor:
            # Get prefix and digit count from school_settings (columns added by migration 007)
            prefix = 'STU'
            digits = 3
            try:
                cursor.execute("""
                    SELECT student_id_prefix, student_id_digits 
                    FROM school_settings ORDER BY id DESC LIMIT 1
                """)
                settings = cursor.fetchone()
            except Exception:
                settings = None
            if settings:
                p = (settings.get('student_id_prefix') if isinstance(settings, dict) else (settings[0] if len(settings) > 0 else None))
                d = settings.get('student_id_digits') if isinstance(settings, dict) else (settings[1] if len(settings) > 1 else None)
                if p and isinstance(p, str) and p.strip():
                    prefix = str(p).strip().upper()[:10]  # Max 10 chars, uppercase
                if d is not None:
                    try:
                        digits = max(1, min(6, int(d)))  # Between 1 and 6 digits
                    except (TypeError, ValueError):
                        pass
            
            prefix_len = len(prefix)
            # Get the highest student ID number for this prefix
            cursor.execute("""
                SELECT student_id FROM students 
                WHERE student_id LIKE %s 
                ORDER BY CAST(SUBSTRING(student_id, %s) AS UNSIGNED) DESC 
                LIMIT 1
            """, (prefix + '%', prefix_len + 1))
            result = cursor.fetchone()
            
            if result:
                sid = result['student_id'] if isinstance(result, dict) else result[0]
                num_part = sid[prefix_len:] if len(sid) > prefix_len else ''
                try:
                    last_number = int(num_part) if num_part.isdigit() else 0
                except ValueError:
                    last_number = 0
                new_number = last_number + 1
            else:
                new_number = 1
            
            student_id = f"{prefix}{new_number:0{digits}d}"
            return student_id
    except Exception as e:
        print(f"Error generating student ID: {e}")
        return f"STU{int(datetime.now().timestamp()) % 100000:05d}"


