def subject_exam_max_raw_marks(exam_total_marks_value):
    """Positive maximum raw marks for exam entry; default 100 when unset, zero, or invalid."""
    try:
        v = float(exam_total_marks_value)
        if v > 0:
            return v
    except (TypeError, ValueError):
        pass
    return 100.0


def raw_mark_to_percentage(raw_marks, exam_total_marks_value):
    """Scale raw marks to a 0–100 percentage (nearest whole number, no decimals)."""
    mx = subject_exam_max_raw_marks(exam_total_marks_value)
    if raw_marks is None:
        return None
    try:
        r = float(raw_marks)
    except (TypeError, ValueError):
        return None
    if mx <= 0:
        return None
    return int(round(100.0 * r / mx))


def combined_papers_percentage(raw_and_max_pairs):
    """
    Combined % for papers with possibly different totals (e.g. /30 and /50).

    Formula:  Σ(raw_i) / Σ(max_i) × 100, rounded to the nearest whole number.
    Equivalent to a max-weighted mean of each paper's own percentage.
    Example: 25/30 and 40/50 → (25+40)/(30+50)×100 = 81%
    (not the unweighted mean of 83% and 80%).
    Members without a mark are skipped (not treated as zero).
    """
    raw_sum = 0.0
    max_sum = 0.0
    for pair in raw_and_max_pairs or []:
        if not pair or len(pair) < 2:
            continue
        raw_val, max_val = pair[0], pair[1]
        if raw_val is None:
            continue
        try:
            r = float(raw_val)
            mx = float(max_val)
        except (TypeError, ValueError):
            continue
        if mx <= 0:
            continue
        raw_sum += r
        max_sum += mx
    if max_sum <= 0:
        return None
    return int(round((100.0 * raw_sum) / max_sum))


def combined_papers_percentage_from_scaled(pct_and_max_pairs):
    """
    Same combined % as combined_papers_percentage, when each paper is already 0–100%.
    Weight = that paper's exam total (max marks). Result is nearest whole number.
    """
    weighted_sum = 0.0
    weight_sum = 0.0
    for pair in pct_and_max_pairs or []:
        if not pair or len(pair) < 2:
            continue
        pct_val, max_val = pair[0], pair[1]
        if pct_val is None:
            continue
        try:
            p = float(pct_val)
            w = float(max_val)
        except (TypeError, ValueError):
            continue
        if w <= 0:
            continue
        weighted_sum += p * w
        weight_sum += w
    if weight_sum <= 0:
        return None
    return int(round(weighted_sum / weight_sum))


def round_mark_display(value):
    """Whole-number rounding for scaled marks, means, and totals shown on reports."""
    if value is None or value == '':
        return None
    try:
        return int(round(float(value)))
    except (TypeError, ValueError):
        return None


def pct_value_for_grade_band_match(marks_value):
    """Map a percentage to the integer scale used by grade_registrations start/end bands."""
    try:
        return int(math.floor(float(marks_value) + 1e-9))
    except (TypeError, ValueError):
        return None


def match_grade_band(marks_value, bands):
    """Return the first band whose [start, end] contains the floored percentage, or None."""
    mv = pct_value_for_grade_band_match(marks_value)
    if mv is None:
        return None
    for band in bands or []:
        try:
            start = float(band.get('start', 0))
            end = float(band.get('end', 0))
        except (TypeError, ValueError):
            continue
        if mv >= start and mv <= end:
            return band
    return None


def subject_display_label(subject_code=None, subject_name=None, fallback='SUBJECT'):
    """Prefer subject_code for marks sheets, reports, and timetables; fall back to name."""
    code = str(subject_code or '').strip()
    if code:
        return code
    name = str(subject_name or '').strip()
    if name and name.upper() not in ('N/A', '-'):
        return name
    if name:
        return name
    return fallback


def grade_code_and_points_from_pct(marks_value, bands):
    """Return (code, points) for a percentage using Grades Registration bands."""
    band = match_grade_band(marks_value, bands)
    if not band:
        return '', None
    code = (band.get('code') or band.get('label') or '').strip()
    points = None
    ap = band.get('allocation_points')
    if ap is not None and ap != '':
        try:
            f = float(ap)
            points = int(round(f)) if abs(f - round(f)) < 1e-9 else round(f, 2)
        except (TypeError, ValueError):
            points = None
    return code, points


def ensure_grade_setting_profile_tables(cursor):
    """Reusable grading settings (profiles) assignable to one or more classes."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS grade_setting_profiles (
                id INT AUTO_INCREMENT PRIMARY KEY,
                name VARCHAR(255) NOT NULL,
                description TEXT NULL,
                created_by INT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (created_by) REFERENCES employees(id) ON DELETE SET NULL,
                UNIQUE KEY uniq_grade_setting_profile_name (name),
                INDEX idx_grade_setting_profile_name (name)
            )
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS grade_setting_profile_bands (
                id INT AUTO_INCREMENT PRIMARY KEY,
                profile_id INT NOT NULL,
                code VARCHAR(20) NOT NULL,
                level_label VARCHAR(255) NULL,
                meaning VARCHAR(255) NULL,
                start_mark DECIMAL(5,2) NOT NULL,
                end_mark DECIMAL(5,2) NOT NULL,
                allocation_points DECIMAL(6,2) NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (profile_id) REFERENCES grade_setting_profiles(id) ON DELETE CASCADE,
                UNIQUE KEY uniq_profile_band_code (profile_id, code),
                INDEX idx_profile_band_profile (profile_id)
            )
        """)
        try:
            cursor.execute(
                "ALTER TABLE grade_setting_profile_bands ADD COLUMN rank_order INT NULL AFTER profile_id"
            )
        except Exception:
            pass
        try:
            cursor.execute(
                "ALTER TABLE grade_setting_profile_bands ADD COLUMN description TEXT NULL AFTER meaning"
            )
        except Exception:
            pass
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS class_grade_setting_assignments (
                academic_level_id INT NOT NULL PRIMARY KEY,
                profile_id INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (academic_level_id) REFERENCES academic_levels(id) ON DELETE CASCADE,
                FOREIGN KEY (profile_id) REFERENCES grade_setting_profiles(id) ON DELETE CASCADE,
                INDEX idx_class_grade_setting_profile (profile_id)
            )
        """)
    except Exception as e:
        print(f"ensure_grade_setting_profile_tables: {e}")


