def _lesson_plan_has_content(plan_fields):
    if not plan_fields:
        return False
    return any(str(plan_fields.get(f) or '').strip() for f in ATTENDANCE_LESSON_PLAN_FIELDS)


def _attendance_session_date_display(date_val):
    """Human-readable date for lesson plan / attendance headers."""
    d = _coerce_date_only(date_val)
    if not d:
        return str(date_val or '').strip()
    return d.strftime('%A, %d %B %Y')


def _attendance_learning_area_label(subject_name='', subject_code=''):
    """CBC learning area label from subject allocation."""
    name = (subject_name or '').strip()
    code = (subject_code or '').strip()
    if name and code and code.upper() not in name.upper():
        return f'{name} ({code})'
    return name or code or '—'


def _attendance_teacher_display_name(cursor, teacher_id):
    if not teacher_id:
        return ''
    try:
        cursor.execute(
            "SELECT full_name FROM employees WHERE id = %s LIMIT 1",
            (int(teacher_id),),
        )
        row = cursor.fetchone()
        if row:
            return (row.get('full_name') if isinstance(row, dict) else row[0]) or ''
    except Exception:
        pass
    return ''


def _fetch_timetable_session_times(cursor, teacher_id, term_id, level_id, weekday_name):
    """Map subject_id -> comma-separated time_slot for one teacher/level/day."""
    out = {}
    if not teacher_id or not term_id or not level_id or not weekday_name:
        return out
    try:
        cursor.execute(
            """
            SELECT t.subject_id,
                   GROUP_CONCAT(DISTINCT t.time_slot ORDER BY t.time_slot SEPARATOR ', ') AS session_times
            FROM timetables t
            WHERE t.term_id = %s AND t.academic_level_id = %s AND t.teacher_id = %s
              AND t.day_of_week = %s AND t.subject_id IS NOT NULL
            GROUP BY t.subject_id
            """,
            (int(term_id), int(level_id), int(teacher_id), str(weekday_name)),
        )
        for row in cursor.fetchall() or []:
            sid = row.get('subject_id') if isinstance(row, dict) else row[0]
            times = row.get('session_times') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
            if sid:
                out[int(sid)] = (times or '').strip()
    except Exception as ex:
        print(f"_fetch_timetable_session_times: {ex}")
    return out


def _enrich_attendance_sessions_with_times(cursor, teacher_id, term_id, sessions):
    """Attach session_time to session dicts using the teacher timetable."""
    if not sessions:
        return sessions
    cache = {}
    for entry in sessions:
        d = _coerce_date_only(entry.get('session_date'))
        lid = entry.get('academic_level_id')
        sid = entry.get('subject_id')
        if not d or not lid or not sid:
            entry.setdefault('session_time', '')
            continue
        weekday = d.strftime('%A')
        cache_key = (int(lid), weekday)
        if cache_key not in cache:
            cache[cache_key] = _fetch_timetable_session_times(
                cursor, teacher_id, term_id, int(lid), weekday,
            )
        entry['session_time'] = cache[cache_key].get(int(sid), '')
        entry['learning_area'] = _attendance_learning_area_label(
            entry.get('subject_name'), entry.get('subject_code'),
        )
        if not entry.get('session_date_display'):
            entry['session_date_display'] = _attendance_session_date_display(d)
    return sessions


def _fetch_teacher_lesson_plans_attendance_report(
    cursor, teacher_id, term_id, date_start=None, date_end=None, level_id=None, subject_id=None,
):
    """Sessions with lesson plans and/or subject attendance for one teacher in a term."""
    rows_out = []
    summary = {
        'sessions': 0,
        'with_lesson_plan': 0,
        'with_attendance': 0,
        'students_present': 0,
        'students_absent': 0,
    }
    if not teacher_id or not term_id:
        return rows_out, summary
    try:
        teacher_id = int(teacher_id)
        term_id = int(term_id)
    except (TypeError, ValueError):
        return rows_out, summary

    ensure_student_attendance_schema(cursor)
    ensure_subject_attendance_lesson_plans_teacher_scope(cursor)
    term_start, term_end = _get_term_date_bounds(cursor, term_id)
    if not term_start or not term_end:
        return rows_out, summary

    range_start = _coerce_date_only(date_start) or term_start
    range_end = _coerce_date_only(date_end) or term_end
    if range_start < term_start:
        range_start = term_start
    if range_end > term_end:
        range_end = term_end
    if range_end < range_start:
        return rows_out, summary

    level_filter_sql = ''
    subject_filter_sql = ''
    extra_params_tail = []
    if level_id:
        try:
            level_filter_sql = ' AND sar.academic_level_id = %s'
            extra_params_tail.append(int(level_id))
        except (TypeError, ValueError):
            level_id = None
    if subject_id:
        try:
            subject_filter_sql = ' AND sar.subject_id = %s'
            extra_params_tail.append(int(subject_id))
        except (TypeError, ValueError):
            subject_id = None

    attended_predicate = _tpad_teacher_attended_records_predicate()
    teacher_att_sql = _attendance_belongs_to_teacher_sql('sar', '%s')
    lp_teacher_sql = _lesson_plan_belongs_to_teacher_sql('lp', '%s')
    sessions = {}

    def _session_key(d_str, lid, sid):
        return (str(d_str), int(lid or 0), int(sid or 0))

    try:
        cursor.execute(
            f"""
            SELECT sar.attendance_date, sar.academic_level_id, sar.subject_id,
                   COALESCE(al.level_name, '') AS level_name,
                   COALESCE(s.subject_name, '') AS subject_name,
                   COALESCE(s.subject_code, '') AS subject_code
            FROM student_attendance_records sar
            LEFT JOIN academic_levels al ON al.id = sar.academic_level_id
            LEFT JOIN subjects s ON s.id = sar.subject_id
            WHERE sar.term_id = %s
              AND sar.attendance_date >= %s AND sar.attendance_date <= %s
              AND sar.subject_id > 0
              AND {attended_predicate}
              AND {teacher_att_sql}
              {level_filter_sql}
              {subject_filter_sql}
            GROUP BY sar.attendance_date, sar.academic_level_id, sar.subject_id,
                     al.level_name, s.subject_name, s.subject_code
            ORDER BY sar.attendance_date DESC, al.level_name ASC, s.subject_name ASC
            """,
            tuple([term_id, range_start, range_end, teacher_id, *_attendance_teacher_bind_params(teacher_id), *extra_params_tail]),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                d_val = row.get('attendance_date')
                lid = row.get('academic_level_id')
                sid = row.get('subject_id')
                meta = {
                    'level_name': row.get('level_name') or '',
                    'subject_name': row.get('subject_name') or '',
                    'subject_code': row.get('subject_code') or '',
                }
            else:
                d_val = row[0]
                lid = row[1]
                sid = row[2]
                meta = {
                    'level_name': row[3] or '',
                    'subject_name': row[4] or '',
                    'subject_code': row[5] or '',
                }
            d = _coerce_date_only(d_val)
            if not d or not lid or not sid:
                continue
            key = _session_key(d.isoformat(), lid, sid)
            sessions[key] = {
                'session_date': d.isoformat(),
                'session_date_display': d.strftime('%a, %d %b %Y'),
                'academic_level_id': int(lid),
                'subject_id': int(sid),
                'level_name': meta['level_name'],
                'subject_name': meta['subject_name'],
                'subject_code': meta['subject_code'],
                'has_attendance': True,
                'has_lesson_plan': False,
            }
    except Exception as ex:
        print(f"_fetch_teacher_lesson_plans_attendance_report attendance sessions: {ex}")

    lp_level_sql = ''
    lp_subject_sql = ''
    lp_params_tail = []
    if level_id:
        lp_level_sql = ' AND lp.academic_level_id = %s'
        lp_params_tail.append(int(level_id))
    if subject_id:
        lp_subject_sql = ' AND lp.subject_id = %s'
        lp_params_tail.append(int(subject_id))

    lp_cols = ', '.join(f'lp.{c}' for c in ATTENDANCE_LESSON_PLAN_FIELDS)
    try:
        cursor.execute(
            f"""
            SELECT lp.session_date, lp.academic_level_id, lp.subject_id,
                   COALESCE(al.level_name, '') AS level_name,
                   COALESCE(s.subject_name, '') AS subject_name,
                   COALESCE(s.subject_code, '') AS subject_code,
                   {lp_cols}
            FROM subject_attendance_lesson_plans lp
            LEFT JOIN academic_levels al ON al.id = lp.academic_level_id
            LEFT JOIN subjects s ON s.id = lp.subject_id
            WHERE lp.term_id = %s
              AND lp.session_date >= %s AND lp.session_date <= %s
              AND {lp_teacher_sql}
              {lp_level_sql}
              {lp_subject_sql}
            ORDER BY lp.session_date DESC, al.level_name ASC, s.subject_name ASC
            """,
            tuple([term_id, range_start, range_end, *_lesson_plan_teacher_bind_params(teacher_id), *lp_params_tail]),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                d_val = row.get('session_date')
                lid = row.get('academic_level_id')
                sid = row.get('subject_id')
                plan = {f: (row.get(f) or '') for f in ATTENDANCE_LESSON_PLAN_FIELDS}
                meta = {
                    'level_name': row.get('level_name') or '',
                    'subject_name': row.get('subject_name') or '',
                    'subject_code': row.get('subject_code') or '',
                }
            else:
                d_val = row[0]
                lid = row[1]
                sid = row[2]
                meta = {
                    'level_name': row[3] or '',
                    'subject_name': row[4] or '',
                    'subject_code': row[5] or '',
                }
                plan = {f: (row[i + 6] or '') for i, f in enumerate(ATTENDANCE_LESSON_PLAN_FIELDS)}
            d = _coerce_date_only(d_val)
            if not d or not lid or not sid:
                continue
            if not _lesson_plan_has_content(plan):
                continue
            key = _session_key(d.isoformat(), lid, sid)
            entry = sessions.get(key) or {
                'session_date': d.isoformat(),
                'session_date_display': d.strftime('%a, %d %b %Y'),
                'academic_level_id': int(lid),
                'subject_id': int(sid),
                'level_name': meta['level_name'],
                'subject_name': meta['subject_name'],
                'subject_code': meta['subject_code'],
                'has_attendance': False,
                'has_lesson_plan': False,
            }
            entry['lesson_plan'] = plan
            entry['has_lesson_plan'] = True
            sessions[key] = entry
    except Exception as ex:
        print(f"_fetch_teacher_lesson_plans_attendance_report lesson plans: {ex}")

    for key, entry in sessions.items():
        d_str, lid, sid = key
        plan = entry.get('lesson_plan')
        if not plan:
            cursor.execute(
                f"""
                SELECT {', '.join(ATTENDANCE_LESSON_PLAN_FIELDS)}
                FROM subject_attendance_lesson_plans lp
                WHERE lp.term_id = %s AND lp.academic_level_id = %s AND lp.subject_id = %s AND lp.session_date = %s
                  AND {_lesson_plan_belongs_to_teacher_sql('lp', '%s')}
                LIMIT 1
                """,
                (term_id, lid, sid, d_str, *_lesson_plan_teacher_bind_params(teacher_id)),
            )
            prow = cursor.fetchone()
            if prow:
                if isinstance(prow, dict):
                    plan = {f: (prow.get(f) or '') for f in ATTENDANCE_LESSON_PLAN_FIELDS}
                else:
                    plan = {f: (prow[i] or '') for i, f in enumerate(ATTENDANCE_LESSON_PLAN_FIELDS)}
                entry['lesson_plan'] = plan
                entry['has_lesson_plan'] = _lesson_plan_has_content(plan)

        present_rows = []
        absent_rows = []
        try:
            cursor.execute(
                f"""
                SELECT s.student_id, s.full_name, sar.present
                FROM student_attendance_records sar
                INNER JOIN students s ON s.student_id = sar.student_id
                WHERE sar.term_id = %s AND sar.academic_level_id = %s AND sar.subject_id = %s
                  AND sar.attendance_date = %s
                  AND {_attendance_belongs_to_teacher_sql('sar', '%s')}
                ORDER BY s.full_name ASC
                """,
                (term_id, lid, sid, d_str, *_attendance_teacher_bind_params(teacher_id)),
            )
            for srow in cursor.fetchall() or []:
                if isinstance(srow, dict):
                    sid_st = srow.get('student_id')
                    name = srow.get('full_name') or ''
                    present = bool(srow.get('present'))
                else:
                    sid_st = srow[0]
                    name = srow[1] or ''
                    present = bool(srow[2])
                item = {'student_id': sid_st, 'full_name': name, 'present': present}
                if present:
                    present_rows.append(item)
                else:
                    absent_rows.append(item)
        except Exception as ex:
            print(f"_fetch_teacher_lesson_plans_attendance_report students: {ex}")

        student_rows = present_rows + absent_rows
        student_rows.sort(key=lambda s: (s.get('full_name') or '').lower())

        total = len(student_rows)
        entry['attendance'] = {
            'present': len(present_rows),
            'absent': len(absent_rows),
            'total': total,
            'pct': round(100 * len(present_rows) / total, 1) if total else None,
            'students': student_rows,
            'present_students': present_rows,
            'absent_students': absent_rows,
        }
        entry['has_attendance'] = total > 0
        if entry['has_attendance']:
            summary['with_attendance'] += 1
            summary['students_present'] += len(present_rows)
            summary['students_absent'] += len(absent_rows)
        if entry.get('has_lesson_plan'):
            summary['with_lesson_plan'] += 1
        rows_out.append(entry)

    _enrich_attendance_sessions_with_times(cursor, teacher_id, term_id, rows_out)
    teacher_display = _attendance_teacher_display_name(cursor, teacher_id)
    filtered_rows = []
    for entry in rows_out:
        entry['teacher_name'] = teacher_display
        if not entry.get('learning_area'):
            entry['learning_area'] = _attendance_learning_area_label(
                entry.get('subject_name'), entry.get('subject_code'),
            )
        if entry.get('has_lesson_plan') or entry.get('has_attendance'):
            filtered_rows.append(entry)
    rows_out = filtered_rows

    rows_out.sort(key=lambda r: (r.get('session_date') or '', r.get('level_name') or '', r.get('subject_name') or ''), reverse=True)
    summary['sessions'] = len(rows_out)
    return rows_out, summary


def _teacher_report_session_key(entry):
    """Stable id for selecting/previewing one teacher report session."""
    d = (entry.get('session_date') or '')[:10]
    lid = int(entry.get('academic_level_id') or 0)
    sid = int(entry.get('subject_id') or 0)
    return f"{d}__{lid}__{sid}"


def _enrich_teacher_report_rows_for_ui(rows):
    """Add session_key and list labels (strand, substrand, date) for pick/print UI."""
    for entry in rows or []:
        entry['session_key'] = _teacher_report_session_key(entry)
        plan = entry.get('lesson_plan') or {}
        strand = (plan.get('strand') or '').strip()
        substrand = (plan.get('substrand') or '').strip()
        entry['strand'] = strand or '—'
        entry['substrand'] = substrand or '—'
        date_label = entry.get('session_date_display') or entry.get('session_date') or '—'
        subject_bit = entry.get('learning_area') or entry.get('subject_name') or ''
        class_bit = entry.get('level_name') or ''
        context_bit = ' · '.join(x for x in (class_bit, subject_bit) if x)
        entry['pick_title'] = ' · '.join(x for x in (strand if strand else 'No strand', substrand if substrand else 'No substrand', date_label) if x)
        entry['pick_subtitle'] = context_bit
        att = entry.get('attendance') or {}
        entry['att_present'] = att.get('present', 0) or 0
        entry['att_absent'] = att.get('absent', 0) or 0
        entry['att_total'] = att.get('total', 0) or 0
        entry['att_pct'] = att.get('pct')
        entry['att_pick_label'] = date_label
    return rows


_SCHEMA_COLUMN_CACHE = {}


def _table_has_column(cursor, table_name, column_name):
    cache_key = (str(table_name or ''), str(column_name or ''))
    if cache_key in _SCHEMA_COLUMN_CACHE:
        return _SCHEMA_COLUMN_CACHE[cache_key]
    try:
        cursor.execute(
            """
            SELECT 1 FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME = %s AND COLUMN_NAME = %s
            LIMIT 1
            """,
            (table_name, column_name),
        )
        found = cursor.fetchone() is not None
        _SCHEMA_COLUMN_CACHE[cache_key] = found
        return found
    except Exception:
        _SCHEMA_COLUMN_CACHE[cache_key] = False
        return False


def ensure_student_attendance_subject_column(cursor):
    """Per-subject attendance cells (subject_id=0 = legacy whole-day column)."""
    ensure_student_attendance_records_table(cursor)
    if not _table_has_column(cursor, 'student_attendance_records', 'subject_id'):
        try:
            cursor.execute("""
                ALTER TABLE student_attendance_records
                ADD COLUMN subject_id INT NOT NULL DEFAULT 0
            """)
        except Exception as e:
            _schema_ignore_existing(e, 'student_attendance subject_id')
    try:
        cursor.execute("""
            ALTER TABLE student_attendance_records
            DROP INDEX unique_student_date_level_term
        """)
    except Exception:
        pass
    if _table_has_column(cursor, 'student_attendance_records', 'session_slot'):
        idx_name = 'unique_student_date_level_term_subject_slot'
        idx_cols = '(student_id, attendance_date, academic_level_id, term_id, subject_id, session_slot)'
    else:
        idx_name = 'unique_student_date_level_term_subject'
        idx_cols = '(student_id, attendance_date, academic_level_id, term_id, subject_id)'
    try:
        cursor.execute(f"""
            ALTER TABLE student_attendance_records
            DROP INDEX unique_student_date_level_term_subject
        """)
    except Exception:
        pass
    try:
        cursor.execute(f"""
            ALTER TABLE student_attendance_records
            DROP INDEX unique_student_date_level_term_subject_slot
        """)
    except Exception:
        pass
    try:
        cursor.execute(f"""
            ALTER TABLE student_attendance_records
            ADD UNIQUE KEY {idx_name} {idx_cols}
        """)
    except Exception:
        pass


CLASS_ATTENDANCE_SESSION_SLOTS = (
    ('morning', 'Morning'),
    ('afternoon', 'Afternoon'),
    ('evening', 'Evening'),
)


def ensure_student_attendance_session_slot_column(cursor):
    """Morning / afternoon / evening slots for class-day attendance (subject_id=0)."""
    ensure_student_attendance_subject_column(cursor)
    if not _table_has_column(cursor, 'student_attendance_records', 'session_slot'):
        try:
            cursor.execute("""
                ALTER TABLE student_attendance_records
                ADD COLUMN session_slot VARCHAR(20) NOT NULL DEFAULT ''
            """)
        except Exception as e:
            _schema_ignore_existing(e, 'student_attendance session_slot')
    try:
        cursor.execute("""
            ALTER TABLE student_attendance_records
            DROP INDEX unique_student_date_level_term_subject
        """)
    except Exception:
        pass
    try:
        cursor.execute("""
            ALTER TABLE student_attendance_records
            ADD UNIQUE KEY unique_student_date_level_term_subject_slot (
                student_id, attendance_date, academic_level_id, term_id, subject_id, session_slot
            )
        """)
    except Exception as e:
        _schema_ignore_existing(e, 'student_attendance unique key')


def ensure_student_attendance_schema(cursor):
    """Ensure attendance table has subject_id and session_slot before queries."""
    ensure_student_attendance_session_slot_column(cursor)


def _build_class_session_attendance_columns(selected_week_days):
    """Three check columns per day: morning, afternoon, evening."""
    columns = []
    for day in selected_week_days or []:
        date_str = day.get('date_str', '')
        day_label = day.get('label', '')
        for slot_key, slot_label in CLASS_ATTENDANCE_SESSION_SLOTS:
            columns.append({
                'date_str': date_str,
                'label': day_label,
                'session_slot': slot_key,
                'subject_id': 0,
                'header_label': f'{day_label} · {slot_label}',
            })
    return columns


def ensure_class_teacher_assignments_table(cursor):
    """One class teacher per academic level per academic year."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS class_teacher_assignments (
                id INT AUTO_INCREMENT PRIMARY KEY,
                academic_level_id INT NOT NULL,
                academic_year_id INT NOT NULL,
                teacher_id INT NOT NULL,
                created_by INT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY unique_class_teacher_level_year (academic_level_id, academic_year_id),
                INDEX idx_cta_teacher (teacher_id),
                INDEX idx_cta_year (academic_year_id),
                FOREIGN KEY (academic_level_id) REFERENCES academic_levels(id) ON DELETE CASCADE,
                FOREIGN KEY (academic_year_id) REFERENCES academic_years(id) ON DELETE CASCADE,
                FOREIGN KEY (teacher_id) REFERENCES employees(id) ON DELETE CASCADE,
                FOREIGN KEY (created_by) REFERENCES employees(id) ON DELETE SET NULL
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
    except Exception as e:
        print(f"ensure_class_teacher_assignments_table: {e}")


def ensure_academic_calendar_activities_table(cursor):
    """School-wide academic calendar events per academic year."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS academic_calendar_activities (
                id INT AUTO_INCREMENT PRIMARY KEY,
                academic_year_id INT NOT NULL,
                term_id INT NULL,
                activity_title VARCHAR(255) NOT NULL,
                activity_date DATE NOT NULL,
                end_date DATE NULL,
                category VARCHAR(64) NOT NULL DEFAULT 'event',
                description TEXT NULL,
                status VARCHAR(32) NOT NULL DEFAULT 'active',
                created_by INT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                INDEX idx_acal_year_date (academic_year_id, activity_date),
                INDEX idx_acal_year_term (academic_year_id, term_id),
                INDEX idx_acal_status (status),
                FOREIGN KEY (academic_year_id) REFERENCES academic_years(id) ON DELETE CASCADE,
                FOREIGN KEY (term_id) REFERENCES terms(id) ON DELETE SET NULL,
                FOREIGN KEY (created_by) REFERENCES employees(id) ON DELETE SET NULL
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
        cursor.execute("SHOW COLUMNS FROM academic_calendar_activities LIKE 'term_id'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE academic_calendar_activities
                ADD COLUMN term_id INT NULL AFTER academic_year_id,
                ADD INDEX idx_acal_year_term (academic_year_id, term_id)
            """)
            try:
                cursor.execute("""
                    ALTER TABLE academic_calendar_activities
                    ADD CONSTRAINT fk_acal_term FOREIGN KEY (term_id) REFERENCES terms(id) ON DELETE SET NULL
                """)
            except Exception:
                pass
        cursor.execute("SHOW COLUMNS FROM academic_calendar_activities LIKE 'activity_about'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE academic_calendar_activities
                ADD COLUMN activity_about TEXT NULL AFTER category
            """)
            try:
                cursor.execute("""
                    UPDATE academic_calendar_activities
                    SET activity_about = description
                    WHERE activity_about IS NULL AND description IS NOT NULL AND TRIM(description) != ''
                """)
            except Exception:
                pass
        cursor.execute("SHOW COLUMNS FROM academic_calendar_activities LIKE 'notify_parents'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE academic_calendar_activities
                ADD COLUMN notify_parents TINYINT(1) NOT NULL DEFAULT 1 AFTER activity_about
            """)
        cursor.execute("SHOW COLUMNS FROM academic_calendar_activities LIKE 'image_path'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE academic_calendar_activities
                ADD COLUMN image_path VARCHAR(500) NULL AFTER notify_parents
            """)
    except Exception as e:
        print(f"ensure_academic_calendar_activities_table: {e}")


def ensure_academic_calendar_activity_levels_table(cursor):
    """Junction: calendar activities → academic levels (empty = all levels)."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS academic_calendar_activity_levels (
                id INT AUTO_INCREMENT PRIMARY KEY,
                activity_id INT NOT NULL,
                academic_level_id INT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY uniq_acal_activity_level (activity_id, academic_level_id),
                INDEX idx_acal_level_activity (academic_level_id, activity_id),
                FOREIGN KEY (activity_id) REFERENCES academic_calendar_activities(id) ON DELETE CASCADE,
                FOREIGN KEY (academic_level_id) REFERENCES academic_levels(id) ON DELETE CASCADE
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
    except Exception as e:
        print(f"ensure_academic_calendar_activity_levels_table: {e}")


def _parse_calendar_activity_levels_form(form):
    """Parse affects-all vs specific academic levels from POST."""
    raw_all = (form.get('affects_all_levels') or '').strip().lower()
    affects_all = raw_all in ('1', 'on', 'true', 'yes')
    if affects_all:
        return True, [], None
    level_ids = _parse_finance_account_level_ids(form)
    if not level_ids:
        return False, [], 'Select at least one academic level, or leave “All levels” checked.'
    return False, level_ids, None


def _save_calendar_activity_levels(cursor, activity_id, affects_all, level_ids):
    ensure_academic_calendar_activity_levels_table(cursor)
    activity_id = int(activity_id)
    cursor.execute(
        "DELETE FROM academic_calendar_activity_levels WHERE activity_id = %s",
        (activity_id,),
    )
    if affects_all:
        return
    valid_ids = _filter_valid_academic_level_ids(cursor, level_ids or [])
    for lid in valid_ids:
        cursor.execute(
            """
            INSERT IGNORE INTO academic_calendar_activity_levels
                (activity_id, academic_level_id)
            VALUES (%s, %s)
            """,
            (activity_id, int(lid)),
        )


def _fetch_calendar_activity_levels_map(cursor, activity_ids):
    if not activity_ids:
        return {}
    ensure_academic_calendar_activity_levels_table(cursor)
    ids = []
    for raw in activity_ids:
        try:
            ids.append(int(raw))
        except (TypeError, ValueError):
            continue
    if not ids:
        return {}
    placeholders = ','.join(['%s'] * len(ids))
    out = {}
    try:
        cursor.execute(
            f"""
            SELECT cal.activity_id, al.id, al.level_name
            FROM academic_calendar_activity_levels cal
            INNER JOIN academic_levels al ON al.id = cal.academic_level_id
            WHERE cal.activity_id IN ({placeholders})
            ORDER BY al.level_name ASC
            """,
            tuple(ids),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                aid = row.get('activity_id')
                lid = row.get('id')
                lname = row.get('level_name') or ''
            else:
                aid = row[0] if len(row) > 0 else None
                lid = row[1] if len(row) > 1 else None
                lname = (row[2] if len(row) > 2 else '') or ''
            if aid is None or lid is None:
                continue
            out.setdefault(int(aid), []).append({
                'id': int(lid),
                'level_name': (lname or '').strip(),
            })
    except Exception as e:
        print(f"_fetch_calendar_activity_levels_map: {e}")
    return out


def _attach_calendar_activity_levels(cursor, activities):
    if not activities:
        return activities
    level_map = _fetch_calendar_activity_levels_map(
        cursor,
        [a.get('id') for a in activities if a.get('id')],
    )
    for act in activities:
        try:
            aid = int(act.get('id') or 0)
        except (TypeError, ValueError):
            aid = 0
        levels = level_map.get(aid, [])
        act['academic_level_ids'] = [lv['id'] for lv in levels]
        act['academic_levels'] = levels
        act['affects_all_levels'] = not levels
        act['levels_affected_label'] = (
            'All levels'
            if not levels
            else _format_levels_affected_label([lv['level_name'] for lv in levels])
        )
    return activities


def _filter_calendar_activities_for_level(activities, academic_level_id):
    if not activities:
        return activities
    if not academic_level_id:
        return activities
    try:
        lid = int(academic_level_id)
    except (TypeError, ValueError):
        return activities
    filtered = []
    for act in activities:
        if act.get('affects_all_levels', True):
            filtered.append(act)
        elif lid in (act.get('academic_level_ids') or []):
            filtered.append(act)
    return filtered


def _resolve_academic_level_id_from_grade(cursor, current_grade):
    grade = (current_grade or '').strip()
    if not grade:
        return None
    level_map = _level_name_to_id_map(cursor)
    if grade in level_map:
        return level_map[grade]
    return level_map.get(grade.upper()) or level_map.get(grade.lower())


def _student_academic_level_id(cursor, student_id):
    """Resolve academic_level_id from a student_id without requiring parents table."""
    sid = (student_id or '').strip()
    if not sid:
        return None
    try:
        cursor.execute(
            """
            SELECT s.current_grade
            FROM students s
            WHERE LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
              AND LOWER(TRIM(COALESCE(s.status, 'in session'))) IN ('in session', 'active', '')
            LIMIT 1
            """,
            (sid,),
        )
        row = cursor.fetchone()
        if not row:
            return None
        grade = row.get('current_grade') if isinstance(row, dict) else (row[0] if row else None)
        return _resolve_academic_level_id_from_grade(cursor, grade)
    except Exception as e:
        print(f"_student_academic_level_id: {e}")
        return None


def _parent_linked_children_level_ids(cursor, parent_email, student_id=None, user_id=None):
    """Academic level ids for a parent's in-session child(ren)."""
    level_ids = set()
    if student_id:
        lid = _student_academic_level_id(cursor, student_id)
        if lid:
            level_ids.add(lid)
        if level_ids:
            return level_ids
    if parent_email:
        level_map = _level_name_to_id_map(cursor)
        cursor.execute(
            """
            SELECT DISTINCT s.current_grade
            FROM students s
            INNER JOIN parents p ON s.student_id = p.student_id
            WHERE p.email = %s AND s.status = 'in session'
            """,
            (parent_email,),
        )
        for row in cursor.fetchall() or []:
            grade = row.get('current_grade') if isinstance(row, dict) else (row[0] if row else None)
            lid = _resolve_academic_level_id_from_grade(cursor, grade)
            if lid:
                level_ids.add(lid)
    if not level_ids and user_id:
        try:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (int(user_id),),
            )
            ur = cursor.fetchone()
            usid = (ur.get('student_id') or '').strip() if ur else ''
            if usid:
                lid = _student_academic_level_id(cursor, usid)
                if lid:
                    level_ids.add(lid)
        except Exception as e:
            print(f"_parent_linked_children_level_ids users: {e}")
    return level_ids


def _fetch_parent_calendar_notifications(cursor, parent_email, student_id=None, user_id=None, limit=8):
    """Upcoming academic calendar items relevant to a parent's child(ren)."""
    limit = max(1, min(int(limit or 8), 30))
    child_level_ids = _parent_linked_children_level_ids(
        cursor, parent_email, student_id, user_id=user_id,
    )
    selected_year_id, _years = _resolve_calendar_year_id(cursor, None)
    if not selected_year_id:
        return []
    activities = _fetch_academic_calendar_activities(cursor, selected_year_id)
    activities = _attach_calendar_activity_levels(cursor, activities)
    today = date_cls.today()
    cutoff = today - timedelta(days=3)
    relevant = []
    for act in activities:
        if not act.get('notify_parents', True):
            continue
        if not act.get('affects_all_levels'):
            act_levels = set(act.get('academic_level_ids') or [])
            if child_level_ids:
                if not act_levels.intersection(child_level_ids):
                    continue
            elif student_id or parent_email or user_id:
                continue
        start = _coerce_to_date(act.get('activity_date'))
        end = _coerce_to_date(act.get('end_date')) or start
        if not start:
            continue
        if end and end < cutoff:
            continue
        if start < cutoff and (not end or end < today):
            continue
        relevant.append(act)
    relevant.sort(
        key=lambda x: (
            _coerce_to_date(x.get('activity_date')) or date_cls.max,
            x.get('id') or 0,
        ),
    )
    return relevant[:limit]


def _parent_notification_student_ids(cursor, parent_email=None, student_id=None, user_id=None):
    """Student ids to include in parent hub notifications."""
    sids = []
    seen = set()

    def _add(raw):
        sid = (raw or '').strip()
        key = sid.lower()
        if sid and key not in seen:
            seen.add(key)
            sids.append(sid)

    if student_id:
        _add(student_id)
        if sids:
            return sids

    pem = (parent_email or '').strip()
    if pem:
        try:
            cursor.execute(
                """
                SELECT DISTINCT s.student_id
                FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE p.email = %s
                  AND LOWER(TRIM(COALESCE(s.status, 'in session'))) IN ('in session', 'active', '')
                """,
                (pem,),
            )
            for row in cursor.fetchall() or []:
                sid = row.get('student_id') if isinstance(row, dict) else (row[0] if row else None)
                _add(sid)
        except Exception as e:
            print(f"_parent_notification_student_ids parents: {e}")

    if user_id:
        try:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (int(user_id),),
            )
            ur = cursor.fetchone()
            if ur:
                _add(ur.get('student_id') if isinstance(ur, dict) else ur[0])
        except Exception as e:
            print(f"_parent_notification_student_ids users: {e}")

    return sids


def _fetch_parent_fee_deadline_notification_for_student(cursor, student_id):
    """Fee payment deadline alert for one student (parent hub)."""
    detail = _fetch_parent_child_fee_details(cursor, student_id)
    if not detail:
        return None
    fs = detail.get('fee_structure')
    if not fs:
        return None
    deadline = _coerce_to_date(fs.get('payment_deadline'))
    if not deadline:
        return None
    balance = float(detail.get('balance') or 0)
    if balance <= 0:
        return None

    today = date_cls.today()
    days_until = (deadline - today).days
    payment_status = detail.get('payment_status') or 'pending'
    fee_name = (fs.get('fee_name') or 'School fees').strip()
    deadline_display = fs.get('payment_deadline_formatted') or _format_parent_portal_date(deadline)
    student_name = (detail.get('full_name') or 'Your child').strip()
    balance_display = f'KES {balance:,.2f}'

    if payment_status == 'overdue' or days_until < 0:
        urgency = 'overdue'
        title = 'FEE PAYMENT OVERDUE'
        subtitle = f'Deadline was {deadline_display} · {balance_display} outstanding'
    elif days_until == 0:
        urgency = 'due_soon'
        title = 'FEE PAYMENT DUE TODAY'
        subtitle = f'{fee_name} · {balance_display} outstanding'
    elif days_until <= 7:
        urgency = 'due_soon'
        day_word = 'day' if days_until == 1 else 'days'
        title = 'FEE PAYMENT DUE SOON'
        subtitle = f'Due in {days_until} {day_word} ({deadline_display}) · {balance_display} outstanding'
    else:
        urgency = 'upcoming'
        title = 'FEE PAYMENT DEADLINE'
        subtitle = f'Due {deadline_display} · {balance_display} outstanding'

    return {
        'type': 'fee_deadline',
        'urgency': urgency,
        'title': title,
        'subtitle': subtitle,
        'student_id': detail.get('student_id'),
        'student_name': student_name,
        'fee_name': fee_name,
        'payment_deadline': deadline,
        'payment_deadline_display': deadline_display,
        'balance': balance,
        'balance_display': balance_display,
        'payment_status': payment_status,
        'payment_status_label': detail.get('payment_status_label') or '',
        'days_until': days_until,
    }


def _fetch_parent_fee_deadline_notifications(
    cursor, parent_email=None, student_id=None, user_id=None,
):
    """Fee deadline alerts for a parent's child(ren) with outstanding balances."""
    notes = []
    for sid in _parent_notification_student_ids(cursor, parent_email, student_id, user_id):
        note = _fetch_parent_fee_deadline_notification_for_student(cursor, sid)
        if note:
            notes.append(note)
    notes.sort(
        key=lambda n: (
            0 if n.get('urgency') == 'overdue' else 1 if n.get('urgency') == 'due_soon' else 2,
            n.get('payment_deadline') or date_cls.max,
        ),
    )
    return notes


def _sql_exam_gazetted_only_clause(exam_alias='e'):
    """SQL fragment: only exams whose results were officially gazetted."""
    alias = (exam_alias or 'e').strip() or 'e'
    return f" AND LOWER(TRIM(COALESCE({alias}.status, ''))) = 'gazetted' "


def _fetch_parent_gazetted_exam_notifications(
    cursor, parent_email=None, student_id=None, user_id=None, limit=8,
):
    """Notify parents when deputy head gazettes exam results for their child(ren)."""
    ensure_exams_gazetted_status_enum(cursor)
    ensure_exams_results_gazetted_columns(cursor)
    sids = _parent_notification_student_ids(cursor, parent_email, student_id, user_id)
    if not sids:
        return []
    limit = max(1, min(int(limit or 8), 20))
    placeholders = ','.join(['%s'] * len(sids))
    try:
        cursor.execute(
            f"""
            SELECT
                sm.student_id,
                s.full_name AS student_name,
                e.exam_name,
                e.exam_type,
                e.academic_year_id,
                e.term_id,
                ay.year_name,
                t.term_name,
                MAX(e.results_gazetted_at) AS gazetted_at
            FROM student_marks sm
            INNER JOIN exams e ON sm.exam_id = e.id
            INNER JOIN students s ON sm.student_id = s.student_id
            LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
            LEFT JOIN terms t ON e.term_id = t.id
            WHERE TRIM(sm.student_id) IN ({placeholders})
              AND LOWER(TRIM(COALESCE(e.status, ''))) = 'gazetted'
            GROUP BY sm.student_id, s.full_name, e.exam_name, e.exam_type,
                     e.academic_year_id, e.term_id, ay.year_name, t.term_name
            ORDER BY gazetted_at DESC
            LIMIT %s
            """,
            tuple(sids) + (limit,),
        )
        rows = cursor.fetchall() or []
    except Exception as e:
        print(f"_fetch_parent_gazetted_exam_notifications: {e}")
        return []

    notes = []
    for row in rows:
        if isinstance(row, dict):
            sid = row.get('student_id')
            student_name = (row.get('student_name') or 'Your child').strip()
            exam_name = (row.get('exam_name') or 'Exam').strip()
            exam_type = (row.get('exam_type') or '').strip()
            year_name = (row.get('year_name') or '').strip()
            term_name = (row.get('term_name') or '').strip()
            gazetted_at = row.get('gazetted_at')
        else:
            sid = row[0] if row else None
            student_name = (row[1] if len(row) > 1 else 'Your child') or 'Your child'
            exam_name = (row[2] if len(row) > 2 else 'Exam') or 'Exam'
            exam_type = (row[3] if len(row) > 3 else '') or ''
            year_name = (row[6] if len(row) > 6 else '') or ''
            term_name = (row[7] if len(row) > 7 else '') or ''
            gazetted_at = row[8] if len(row) > 8 else None
        if not sid:
            continue
        period_bits = [x for x in (year_name, term_name) if x]
        period_label = ' · '.join(period_bits) if period_bits else ''
        subtitle_parts = [x for x in (period_label, exam_type) if x]
        if gazetted_at and hasattr(gazetted_at, 'strftime'):
            released_display = gazetted_at.strftime('%d %b %Y')
        elif gazetted_at:
            released_display = str(gazetted_at)[:10]
        else:
            released_display = ''
        notes.append({
            'type': 'exam_results',
            'title': 'EXAM RESULTS RELEASED',
            'exam_name': exam_name,
            'exam_type': exam_type,
            'student_id': sid,
            'student_name': student_name,
            'year_name': year_name,
            'term_name': term_name,
            'period_label': period_label,
            'subtitle': ' · '.join(subtitle_parts) if subtitle_parts else 'Official results are now available',
            'gazetted_at': gazetted_at,
            'gazetted_at_display': released_display,
        })
    return notes


def _fetch_parent_hub_notifications(
    cursor, parent_email=None, student_id=None, user_id=None, limit=12,
):
    """Merged parent hub feed: fee deadlines + gazetted exam results + academic calendar updates."""
    if not school_notifications_enabled() or not notification_mode_enabled('app'):
        return []
    limit = max(1, min(int(limit or 12), 30))
    items = []

    for note in _fetch_portal_notifications_for_recipient(
        cursor, parent_email=parent_email, user_id=user_id, recipient_type='parent', limit=limit,
    ):
        items.append(note)

    for note in _fetch_parent_fee_deadline_notifications(
        cursor, parent_email, student_id, user_id,
    ):
        items.append(note)

    for note in _fetch_parent_gazetted_exam_notifications(
        cursor, parent_email, student_id, user_id, limit=limit,
    ):
        items.append(note)

    for act in _fetch_parent_calendar_notifications(
        cursor, parent_email, student_id, user_id=user_id, limit=limit,
    ):
        entry = dict(act)
        entry['type'] = 'calendar'
        items.append(entry)

    def _hub_sort_key(item):
        if item.get('type') == 'fee_deadline':
            urgency = item.get('urgency') or 'upcoming'
            prio = {'overdue': 0, 'due_soon': 1, 'upcoming': 2}.get(urgency, 2)
            return (prio, item.get('payment_deadline') or date_cls.max)
        if item.get('type') == 'exam_results':
            ga = item.get('gazetted_at')
            sort_dt = _coerce_to_date(ga) if not hasattr(ga, 'year') else ga.date() if hasattr(ga, 'date') else ga
            return (2, sort_dt or date_cls.min, item.get('exam_name') or '')
        if item.get('type') == 'portal':
            return (1, item.get('gazetted_at_display') or '', item.get('id') or 0)
        return (
            3,
            _coerce_to_date(item.get('activity_date')) or date_cls.max,
            item.get('id') or 0,
        )

    items.sort(key=_hub_sort_key)
    items = items[:limit]
    return _enrich_hub_notifications_with_read_state(cursor, user_id, items)


def _fetch_student_hub_notifications(cursor, student_id=None, user_id=None, limit=12):
    """Merged student hub feed: portal alerts + fee deadlines + exam results + calendar."""
    if not school_notifications_enabled() or not notification_mode_enabled('app'):
        return []
    limit = max(1, min(int(limit or 12), 30))
    items = []
    sid = (student_id or '').strip()

    if user_id:
        for note in _fetch_portal_notifications_for_recipient(
            cursor, user_id=user_id, recipient_type='student', limit=limit,
        ):
            items.append(note)

    if sid:
        note = _fetch_parent_fee_deadline_notification_for_student(cursor, sid)
        if note:
            items.append(note)

        for note in _fetch_parent_gazetted_exam_notifications(
            cursor, student_id=sid, limit=limit,
        ):
            items.append(note)

        for act in _fetch_parent_calendar_notifications(
            cursor, parent_email=None, student_id=sid, limit=limit,
        ):
            entry = dict(act)
            entry['type'] = 'calendar'
            items.append(entry)

    def _hub_sort_key(item):
        if item.get('type') == 'fee_deadline':
            urgency = item.get('urgency') or 'upcoming'
            prio = {'overdue': 0, 'due_soon': 1, 'upcoming': 2}.get(urgency, 2)
            return (prio, item.get('payment_deadline') or date_cls.max)
        if item.get('type') == 'exam_results':
            ga = item.get('gazetted_at')
            sort_dt = _coerce_to_date(ga) if not hasattr(ga, 'year') else ga.date() if hasattr(ga, 'date') else ga
            return (2, sort_dt or date_cls.min, item.get('exam_name') or '')
        if item.get('type') == 'portal':
            return (1, item.get('gazetted_at_display') or '', item.get('id') or 0)
        return (
            3,
            _coerce_to_date(item.get('activity_date')) or date_cls.max,
            item.get('id') or 0,
        )

    items.sort(key=_hub_sort_key)
    items = items[:limit]
    return _enrich_hub_notifications_with_read_state(cursor, user_id, items)


def ensure_portal_hub_notification_reads_table(cursor):
    """Tracks read/dismissed state for computed hub alerts (fees, exams, calendar)."""
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS portal_hub_notification_reads (
            id INT AUTO_INCREMENT PRIMARY KEY,
            user_id INT NOT NULL,
            notification_key VARCHAR(191) NOT NULL,
            read_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            UNIQUE KEY uniq_user_hub_notif (user_id, notification_key),
            INDEX idx_hub_notif_user (user_id)
        )
        """
    )


def _hub_notification_key(note):
    """Stable key for marking hub notification read state."""
    if not note:
        return 'unknown'
    ntype = note.get('type') or 'unknown'
    if ntype == 'portal':
        nid = note.get('id')
        return f'portal:{nid}' if nid else 'portal:unknown'
    if ntype == 'fee_deadline':
        sid = (note.get('student_id') or '').strip()
        dl = note.get('payment_deadline')
        if hasattr(dl, 'isoformat'):
            dl_str = dl.isoformat()
        else:
            dl_str = str(dl or '')
        return f'fee_deadline:{sid}:{dl_str}'
    if ntype == 'exam_results':
        sid = (note.get('student_id') or '').strip()
        exam = (note.get('exam_name') or '').strip()
        ga = note.get('gazetted_at')
        if hasattr(ga, 'isoformat'):
            ga_str = ga.isoformat()[:19]
        else:
            ga_str = str(ga or '')[:19]
        return f'exam_results:{sid}:{exam}:{ga_str}'
    act_id = note.get('id')
    if act_id:
        return f'calendar:{act_id}'
    title = (note.get('activity_title') or note.get('title') or '')[:48]
    return f'{ntype}:{title}'


def _user_read_hub_notification_keys(cursor, user_id):
    """Set of notification keys already read by this portal user."""
    if not user_id:
        return set()
    keys = set()
    ensure_portal_hub_notification_reads_table(cursor)
    try:
        cursor.execute(
            "SELECT notification_key FROM portal_hub_notification_reads WHERE user_id = %s",
            (int(user_id),),
        )
        for row in cursor.fetchall() or []:
            k = row.get('notification_key') if isinstance(row, dict) else row[0]
            if k:
                keys.add(k)
    except Exception as ex:
        print(f"_user_read_hub_notification_keys hub: {ex}")

    ensure_portal_notifications_table(cursor)
    try:
        cursor.execute(
            """
            SELECT id FROM portal_notifications
            WHERE recipient_user_id = %s AND read_at IS NOT NULL
            """,
            (int(user_id),),
        )
        for row in cursor.fetchall() or []:
            nid = row.get('id') if isinstance(row, dict) else row[0]
            if nid:
                keys.add(f'portal:{nid}')
    except Exception as ex:
        print(f"_user_read_hub_notification_keys portal: {ex}")
    return keys


def _enrich_hub_notifications_with_read_state(cursor, user_id, items):
    if not items:
        return items
    read_keys = _user_read_hub_notification_keys(cursor, user_id) if user_id else set()
    for note in items:
        key = _hub_notification_key(note)
        note['notification_key'] = key
        note['is_read'] = key in read_keys
    return items


def _sort_hub_notifications_for_page(items):
    """Unread first, then by existing hub priority."""

    def _sort_key(item):
        read_rank = 1 if item.get('is_read') else 0
        if item.get('type') == 'fee_deadline':
            urgency = item.get('urgency') or 'upcoming'
            prio = {'overdue': 0, 'due_soon': 1, 'upcoming': 2}.get(urgency, 2)
            return (read_rank, prio, item.get('payment_deadline') or date_cls.max)
        if item.get('type') == 'exam_results':
            ga = item.get('gazetted_at')
            sort_dt = _coerce_to_date(ga) if ga and not hasattr(ga, 'year') else (
                ga.date() if hasattr(ga, 'date') else ga
            )
            return (read_rank, 2, sort_dt or date_cls.min, item.get('exam_name') or '')
        if item.get('type') == 'portal':
            return (read_rank, 1, item.get('gazetted_at_display') or '', item.get('id') or 0)
        return (
            read_rank,
            3,
            _coerce_to_date(item.get('activity_date')) or date_cls.max,
            item.get('id') or 0,
        )

    items.sort(key=_sort_key)
    return items


def _mark_hub_notification_read(cursor, user_id, notification_key):
    """Mark one hub notification read for the signed-in user."""
    uid = int(user_id)
    key = (notification_key or '').strip()[:191]
    if not key:
        return False

    if key.startswith('portal:'):
        try:
            nid = int(key.split(':', 1)[1])
        except (TypeError, ValueError):
            nid = None
        if nid:
            ensure_portal_notifications_table(cursor)
            cursor.execute(
                """
                UPDATE portal_notifications
                SET read_at = COALESCE(read_at, NOW())
                WHERE id = %s
                  AND (recipient_user_id = %s OR recipient_user_id IS NULL)
                """,
                (nid, uid),
            )
            ensure_communication_broadcast_tables(cursor)
            cursor.execute(
                """
                UPDATE communication_broadcast_recipients
                SET read_at = COALESCE(read_at, NOW())
                WHERE portal_notification_id = %s
                """,
                (nid,),
            )

    ensure_portal_hub_notification_reads_table(cursor)
    cursor.execute(
        """
        INSERT INTO portal_hub_notification_reads (user_id, notification_key, read_at)
        VALUES (%s, %s, NOW())
        ON DUPLICATE KEY UPDATE read_at = COALESCE(read_at, NOW())
        """,
        (uid, key),
    )
    return True


def _count_unread_hub_notifications(items):
    return sum(1 for n in (items or []) if not n.get('is_read'))


def _session_portal_notification_badge():
    """
    Unread hub notification count + link for the signed-in student/parent portal user.
    Matches the notifications hub feed (portal alerts, fees, exams, calendar).
    """
    empty = {'portal_unread_notification_count': 0, 'portal_notifications_hub_url': '', 'show_portal_notification_badge': False}
    if not has_request_context() or not session.get('user_id'):
        return empty
    path_role = portal_role_from_request_path()
    if path_role not in ('parent', 'student'):
        return empty
    if not school_notifications_enabled() or not notification_mode_enabled('app'):
        return {**empty, 'show_portal_notification_badge': True}

    user_id = session.get('user_id')
    user_role = (session.get('role') or '').lower()
    viewing = (session.get('viewing_as_role') or '').lower()
    connection = get_db_connection()
    if not connection:
        return {**empty, 'show_portal_notification_badge': True}

    count = 0
    hub_url = student_dashboard_path('notifications') if path_role == 'student' else parent_dashboard_path('notifications')
    try:
        with connection.cursor() as cursor:
            if path_role == 'student':
                student_id = ''
                if user_role == 'technician' and viewing == 'student':
                    student_id = (session.get('student_view_student_id') or '').strip()
                else:
                    cursor.execute(
                        "SELECT student_id FROM users WHERE id = %s LIMIT 1",
                        (int(user_id),),
                    )
                    ur = cursor.fetchone()
                    if ur:
                        student_id = str(
                            ur.get('student_id') if isinstance(ur, dict) else ur[0] or ''
                        ).strip()
                items = _fetch_student_hub_notifications(
                    cursor, student_id=student_id or None, user_id=user_id,
                )
                count = _count_unread_hub_notifications(items)
                hub_url = student_dashboard_path('notifications')
                if student_id and user_role == 'technician':
                    hub_url += '?' + urlencode({'student_id': student_id})
            else:
                parent_email = session.get('email', '')
                student_id = (session.get('parent_view_student_id') or '').strip()
                if user_role == 'technician' and viewing == 'parent' and student_id:
                    cursor.execute(
                        "SELECT p.email FROM parents p WHERE p.student_id = %s LIMIT 1",
                        (student_id,),
                    )
                    pr = cursor.fetchone()
                    if pr:
                        parent_email = pr.get('email', '') if isinstance(pr, dict) else pr[0]
                items = _fetch_parent_hub_notifications(
                    cursor,
                    parent_email=parent_email,
                    student_id=student_id or None,
                    user_id=user_id,
                )
                count = _count_unread_hub_notifications(items)
                hub_url = parent_dashboard_path('notifications')
                if student_id:
                    hub_url += '?' + urlencode({'student_id': student_id})
    except Exception as ex:
        print(f"_session_portal_notification_badge: {ex}")
    finally:
        try:
            connection.close()
        except Exception:
            pass

    return {
        'portal_unread_notification_count': count,
        'portal_notifications_hub_url': hub_url,
        'show_portal_notification_badge': True,
    }


ACADEMIC_CALENDAR_CATEGORY_LABELS = {
    'term': 'Term dates',
    'holiday': 'Holiday',
    'exam': 'Exams',
    'event': 'School event',
    'meeting': 'Meeting',
    'other': 'Other',
}

ACADEMIC_CALENDAR_CATEGORY_COLORS = {
    'term': {'badge': '#2563eb', 'bg': '#dbeafe', 'text': '#1e3a8a'},
    'holiday': {'badge': '#059669', 'bg': '#d1fae5', 'text': '#065f46'},
    'exam': {'badge': '#e11d48', 'bg': '#ffe4e6', 'text': '#9f1239'},
    'event': {'badge': '#7c3aed', 'bg': '#ede9fe', 'text': '#5b21b6'},
    'meeting': {'badge': '#d97706', 'bg': '#fef3c7', 'text': '#92400e'},
    'other': {'badge': '#64748b', 'bg': '#f1f5f9', 'text': '#334155'},
}


def _calendar_category_colors(category):
    return ACADEMIC_CALENDAR_CATEGORY_COLORS.get(
        (category or 'event').strip().lower(),
        ACADEMIC_CALENDAR_CATEGORY_COLORS['other'],
    )


def _prepare_academic_calendar_view(activities, selected_year=None, selected_term=None):
    """Assign ref numbers, colors, and a date→activities map for the calendar grid."""
    today = date_cls.today()
    range_start = None
    range_end = None
    if selected_year:
        range_start = _coerce_to_date(selected_year.get('start_date'))
        range_end = _coerce_to_date(selected_year.get('end_date'))

    sorted_acts = sorted(
        activities or [],
        key=lambda x: (
            _coerce_to_date(x.get('activity_date')) or date_cls.min,
            x.get('id') or 0,
        ),
    )

    if not range_start:
        range_start = today.replace(month=1, day=1)
    if not range_end:
        range_end = today.replace(month=12, day=31)
    if range_end < range_start:
        range_start, range_end = range_end, range_start

    enriched = []
    date_map = {}
    for idx, act in enumerate(sorted_acts, start=1):
        category = (act.get('category') or 'event').strip().lower()
        colors = _calendar_category_colors(category)
        entry = dict(act)
        entry['ref'] = idx
        entry['color_badge'] = colors['badge']
        entry['color_bg'] = colors['bg']
        entry['color_text'] = colors['text']
        enriched.append(entry)

        start = _coerce_to_date(act.get('activity_date'))
        end = _coerce_to_date(act.get('end_date')) or start
        if not start:
            continue
        if not end:
            end = start
        if end < start:
            start, end = end, start
        d = start
        marker = {
            'ref': idx,
            'title': act.get('activity_title') or '',
            'color_badge': colors['badge'],
            'color_bg': colors['bg'],
            'color_text': colors['text'],
        }
        while d <= end:
            key = d.strftime('%Y-%m-%d')
            date_map.setdefault(key, []).append(marker)
            d += timedelta(days=1)

    initial_month = today.strftime('%Y-%m')
    if today < range_start:
        initial_month = range_start.strftime('%Y-%m')
    elif today > range_end:
        initial_month = range_end.strftime('%Y-%m')

    year_label = ''
    if selected_year and selected_year.get('year_name'):
        year_label = selected_year['year_name']
    elif range_start and range_end:
        year_label = (
            f"{range_start.strftime('%d %b %Y')} – {range_end.strftime('%d %b %Y')}"
        )

    return {
        'activities': enriched,
        'date_map': date_map,
        'range_start': range_start.strftime('%Y-%m-%d'),
        'range_end': range_end.strftime('%Y-%m-%d'),
        'initial_month': initial_month,
        'year_label': year_label,
    }


def _build_calendar_month_grid(view_year, view_month, date_map=None, range_start=None, range_end=None):
    """Build a 6-week Monday-start grid for one calendar month."""
    import calendar as cal_mod

    date_map = date_map or {}
    today = date_cls.today()
    today_key = today.strftime('%Y-%m-%d')
    rs = _coerce_to_date(range_start)
    re = _coerce_to_date(range_end)
    view_year = int(view_year)
    view_month = int(view_month)

    first = date_cls(view_year, view_month, 1)
    start_pad = first.weekday()
    days_in_month = cal_mod.monthrange(view_year, view_month)[1]
    if view_month == 1:
        prev_month, prev_year = 12, view_year - 1
    else:
        prev_month, prev_year = view_month - 1, view_year
    prev_month_days = cal_mod.monthrange(prev_year, prev_month)[1]

    def build_cell(y, m, d, other_month):
        d_obj = date_cls(int(y), int(m), int(d))
        key = d_obj.strftime('%Y-%m-%d')
        markers = list(date_map.get(key) or [])
        primary = markers[0] if markers else None
        in_range = True
        if rs and d_obj < rs:
            in_range = False
        if re and d_obj > re:
            in_range = False
        cell = {
            'day': d,
            'key': key,
            'other_month': other_month,
            'in_range': in_range,
            'is_today': key == today_key,
            'markers': markers,
            'has_activity': bool(markers),
            'shade_bg': (primary or {}).get('color_bg') or '',
            'shade_border': (primary or {}).get('color_badge') or '',
            'weekday': d_obj.strftime('%a'),
            'date_short': d_obj.strftime('%d %b'),
            'date_full': d_obj.strftime('%A, %d %B %Y'),
            'cell_style': '',
        }
        if cell['has_activity']:
            style = f"background:{cell['shade_bg']};border-color:{cell['shade_border']};"
            if len(markers) > 1:
                style += f"box-shadow:inset 0 0 0 1px {cell['shade_border']}55;"
            cell['cell_style'] = style
        return cell

    cells = []
    for i in range(start_pad - 1, -1, -1):
        day = prev_month_days - i
        cells.append(build_cell(prev_year, prev_month, day, True))
    for day in range(1, days_in_month + 1):
        cells.append(build_cell(view_year, view_month, day, False))
    if view_month == 12:
        next_month, next_year = 1, view_year + 1
    else:
        next_month, next_year = view_month + 1, view_year
    next_day = 1
    while len(cells) < 42:
        cells.append(build_cell(next_year, next_month, next_day, True))
        next_day += 1
    return cells


def _shift_calendar_month(year, month, delta):
    month += delta
    while month < 1:
        month += 12
        year -= 1
    while month > 12:
        month -= 12
        year += 1
    return year, month


def _calendar_months_in_range(range_start, range_end):
    """Inclusive (year, month) pairs from range_start through range_end."""
    rs = _coerce_to_date(range_start)
    re = _coerce_to_date(range_end)
    if not rs:
        return []
    if not re:
        re = rs
    if re < rs:
        rs, re = re, rs
    months = []
    y, m = rs.year, rs.month
    end_y, end_m = re.year, re.month
    while (y, m) <= (end_y, end_m):
        months.append((y, m))
        m += 1
        if m > 12:
            m = 1
            y += 1
    return months


def _build_academic_calendar_report_months(calendar_view):
    """One mini calendar grid per month in the academic year range."""
    date_map = calendar_view.get('date_map') or {}
    range_start = calendar_view.get('range_start')
    range_end = calendar_view.get('range_end')
    out = []
    for y, m in _calendar_months_in_range(range_start, range_end):
        grid = _build_calendar_month_grid(y, m, date_map, range_start, range_end)
        out.append({
            'year': y,
            'month': m,
            'key': f'{y}-{m:02d}',
            'label': date_cls(y, m, 1).strftime('%B %Y'),
            'grid': grid,
        })
    return out


def _enrich_calendar_report_term_rows(terms):
    out = []
    for t in terms or []:
        row = dict(t)
        row['start_date_display'] = _format_date_short(t.get('start_date')) or '—'
        row['end_date_display'] = _format_date_short(t.get('end_date')) or '—'
        out.append(row)
    return out


def _format_finance_payment_method_calendar_row(method_row):
    """Structured payment method row for the academic calendar report."""
    mode = (method_row.get('payment_mode') or '').lower()
    fields = []
    category = 'Other'
    category_order = 99
    mode_label = _finance_payment_mode_label(method_row)

    if mode == 'mpesa':
        mt = (method_row.get('mpesa_type') or '').lower()
        category = 'Mobile money (M-PESA)'
        category_order = 1
        biz = (method_row.get('business_name') or '').strip() or '—'
        num = (method_row.get('account_number') or '').strip()
        shortcode = (method_row.get('mpesa_shortcode') or '').strip()
        fields.append({'label': 'Business / institution name', 'value': biz})
        if mt == 'paybill':
            if num:
                fields.append({'label': 'Paybill number', 'value': num})
            ref = _finance_mpesa_paybill_account_display()
            if ref:
                fields.append({'label': 'Account reference', 'value': ref})
        elif mt == 'till':
            if num:
                fields.append({'label': 'Till number', 'value': num})
        elif num:
            fields.append({'label': 'Number', 'value': num})
        if shortcode and shortcode != num:
            fields.append({'label': 'M-PESA shortcode', 'value': shortcode})
    elif mode == 'bank':
        category = 'Bank transfer'
        category_order = 2
        bn = (method_row.get('bank_name') or '').strip() or '—'
        ac = (method_row.get('account_number') or '').strip() or '—'
        fields.append({'label': 'Bank / company name', 'value': bn})
        fields.append({'label': 'Account number', 'value': ac})
    elif mode == 'cash':
        category = 'In person'
        category_order = 3
        fields.append({
            'label': 'Instructions',
            'value': 'Pay at the school finance office during official office hours.',
        })
    elif mode == 'cheque':
        category = 'In person'
        category_order = 3
        fields.append({
            'label': 'Instructions',
            'value': 'Cheques should be made payable to the school name shown on this report.',
        })
    else:
        fields.append({'label': 'Details', 'value': 'Contact the finance office for payment instructions.'})

    return {
        'category': category,
        'category_order': category_order,
        'mode_label': mode_label,
        'mode_key': mode or 'other',
        'fields': fields,
    }


def _group_calendar_payment_methods(method_rows):
    """Group structured calendar payment methods by category for display."""
    groups = {}
    seen = set()
    for raw in method_rows or []:
        row = _format_finance_payment_method_calendar_row(raw)
        dedupe = (
            row.get('mode_label'),
            tuple((f.get('label'), f.get('value')) for f in row.get('fields') or []),
        )
        if dedupe in seen:
            continue
        seen.add(dedupe)
        cat = row.get('category') or 'Other'
        if cat not in groups:
            groups[cat] = {
                'category': cat,
                'category_order': row.get('category_order') or 99,
                'methods': [],
            }
        groups[cat]['methods'].append(row)
    return sorted(groups.values(), key=lambda g: (g.get('category_order') or 99, g.get('category') or ''))


def _fetch_academic_calendar_report_fee_sections(cursor, academic_year_id, term_id=None):
    """School-fee payment methods and deadlines for the printable calendar report."""
    ensure_fee_structures_finance_account_column(cursor)
    try:
        academic_year_id = int(academic_year_id)
    except (TypeError, ValueError):
        return {'payment_methods': [], 'payment_method_groups': [], 'fee_deadlines': []}

    where = ["fs.status = 'active'", 'fs.academic_year_id = %s']
    params = [academic_year_id]
    if term_id:
        try:
            where.append('fs.term_id = %s')
            params.append(int(term_id))
        except (TypeError, ValueError):
            pass

    cursor.execute(
        f"""
        SELECT fs.fee_name, fs.category, fs.payment_deadline, fs.total_amount,
               fs.finance_account_id, t.term_name, al.level_name
        FROM fee_structures fs
        LEFT JOIN terms t ON t.id = fs.term_id
        LEFT JOIN academic_levels al ON al.id = fs.academic_level_id
        WHERE {' AND '.join(where)}
        ORDER BY COALESCE(t.start_date, '1900-01-01'), COALESCE(fs.payment_deadline, '9999-12-31'),
                 fs.fee_name, al.level_name
        """,
        tuple(params),
    )
    rows = cursor.fetchall() or []
    account_ids = []
    deadlines = []
    seen_deadline_keys = set()
    for r in rows:
        if isinstance(r, dict):
            fid = r.get('finance_account_id')
            fee_name = r.get('fee_name') or 'Fees'
            term_name = r.get('term_name') or '—'
            level_name = r.get('level_name') or '—'
            deadline = r.get('payment_deadline')
            total = r.get('total_amount')
            category = r.get('category') or ''
        else:
            fid = r[4] if len(r) > 4 else None
            fee_name = r[0] if len(r) > 0 else 'Fees'
            term_name = r[5] if len(r) > 5 else '—'
            level_name = r[6] if len(r) > 6 else '—'
            deadline = r[2] if len(r) > 2 else None
            total = r[3] if len(r) > 3 else None
            category = r[1] if len(r) > 1 else ''
        if fid:
            try:
                account_ids.append(int(fid))
            except (TypeError, ValueError):
                pass
        dk = (term_name, fee_name, level_name, str(deadline))
        if dk in seen_deadline_keys:
            continue
        seen_deadline_keys.add(dk)
        deadlines.append({
            'term_name': term_name,
            'fee_name': fee_name,
            'level_name': level_name,
            'category': category,
            'payment_deadline_display': _format_date_short(deadline) or '—',
            'total_amount_display': _format_kes_amount(float(total or 0)) if total is not None else '—',
        })

    payment_methods = []
    payment_method_groups = []
    seen_pm = set()
    if account_ids:
        pmap = _fetch_finance_account_payment_methods_map(cursor, list(set(account_ids)))
        raw_methods = []
        for aid in sorted(set(account_ids)):
            raw_methods.extend(pmap.get(aid) or [])
        payment_method_groups = _group_calendar_payment_methods(raw_methods)
        for group in payment_method_groups:
            for method in group.get('methods') or []:
                key = (
                    method.get('mode_label'),
                    tuple((f.get('label'), f.get('value')) for f in method.get('fields') or []),
                )
                if key in seen_pm:
                    continue
                seen_pm.add(key)
                payment_methods.append(method)

    return {
        'payment_methods': payment_methods,
        'payment_method_groups': payment_method_groups,
        'fee_deadlines': deadlines,
    }


def _calendar_view_query(academic_year_id, term_id=None, month=None):
    qs = f'academic_year_id={int(academic_year_id)}'
    if term_id:
        qs += f'&term_id={int(term_id)}'
    else:
        qs += '&term_id=0'
    if month:
        qs += f'&month={month}'
    return qs

