def _academic_calendar_can_manage():
    user_role = (session.get('role') or '').lower()
    viewing_as = (session.get('viewing_as_employee_role') or '').lower()
    if user_role == 'technician':
        return True
    allowed = (
        'head of institution',
        'deputy head of institution',
        'secretary',
        'curriculum coordinator',
    )
    return user_role in allowed or viewing_as in allowed


def _fetch_academic_years_for_calendar(cursor):
    years = []
    try:
        cursor.execute("""
            SELECT id, year_name, start_date, end_date, is_current, status
            FROM academic_years
            WHERE COALESCE(status, 'active') IN ('active', 'draft', 'closed')
            ORDER BY COALESCE(start_date, '1900-01-01') DESC, id DESC
        """)
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                years.append({
                    'id': row.get('id'),
                    'year_name': row.get('year_name') or '',
                    'start_date': row.get('start_date'),
                    'end_date': row.get('end_date'),
                    'is_current': bool(row.get('is_current')),
                    'status': row.get('status') or '',
                })
            else:
                years.append({
                    'id': row[0] if len(row) > 0 else None,
                    'year_name': row[1] if len(row) > 1 else '',
                    'start_date': row[2] if len(row) > 2 else None,
                    'end_date': row[3] if len(row) > 3 else None,
                    'is_current': bool(row[4]) if len(row) > 4 else False,
                    'status': row[5] if len(row) > 5 else '',
                })
    except Exception as e:
        print(f"_fetch_academic_years_for_calendar: {e}")
    return years


def _fetch_terms_for_calendar_year(cursor, academic_year_id):
    terms = []
    if not academic_year_id:
        return terms
    try:
        cursor.execute(
            """
            SELECT id, term_name, start_date, end_date, is_current, status
            FROM terms
            WHERE academic_year_id = %s
              AND COALESCE(status, 'active') IN ('active', 'draft', 'closed')
            ORDER BY COALESCE(start_date, '1900-01-01') ASC, id ASC
            """,
            (int(academic_year_id),),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                terms.append({
                    'id': row.get('id'),
                    'term_name': row.get('term_name') or '',
                    'start_date': row.get('start_date'),
                    'end_date': row.get('end_date'),
                    'is_current': bool(row.get('is_current')),
                    'status': row.get('status') or '',
                })
            else:
                terms.append({
                    'id': row[0] if len(row) > 0 else None,
                    'term_name': row[1] if len(row) > 1 else '',
                    'start_date': row[2] if len(row) > 2 else None,
                    'end_date': row[3] if len(row) > 3 else None,
                    'is_current': bool(row[4]) if len(row) > 4 else False,
                    'status': row[5] if len(row) > 5 else '',
                })
    except Exception as e:
        print(f"_fetch_terms_for_calendar_year: {e}")
    return terms


def _calendar_activity_row_dict(row):
    if isinstance(row, dict):
        activity_date = row.get('activity_date')
        end_date = row.get('end_date')
        category = (row.get('category') or 'event').strip().lower()
        term_name = (row.get('term_name') or '').strip()
        about = (row.get('activity_about') or row.get('description') or '').strip()
        notify_raw = row.get('notify_parents')
        notify_parents = True if notify_raw is None else bool(int(notify_raw))
        image_path = (row.get('image_path') or '').strip()
        title = (row.get('activity_title') or '').strip().upper()
        return {
            'id': row.get('id'),
            'academic_year_id': row.get('academic_year_id'),
            'term_id': row.get('term_id'),
            'term_name': term_name,
            'term_label': term_name or 'Whole year',
            'activity_title': title,
            'activity_date': activity_date,
            'activity_date_display': _format_date_short(activity_date) or '',
            'end_date': end_date,
            'end_date_display': _format_date_short(end_date) or '',
            'category': category,
            'category_label': ACADEMIC_CALENDAR_CATEGORY_LABELS.get(category, category.title()),
            'activity_about': about,
            'notify_parents': notify_parents,
            'image_path': image_path,
            'image_url': _academic_calendar_image_public_url(image_path),
            'activity_date_input': _calendar_date_input_value(activity_date),
            'end_date_input': _calendar_date_input_value(end_date),
        }
    term_name = (row[10] if len(row) > 10 else '') or ''
    category = (row[6] if len(row) > 6 else 'event') or 'event'
    activity_date_val = row[4] if len(row) > 4 else None
    end_date_val = row[5] if len(row) > 5 else None
    about = ((row[7] if len(row) > 7 else '') or '').strip()
    notify_raw = row[8] if len(row) > 8 else 1
    notify_parents = True if notify_raw is None else bool(int(notify_raw))
    image_path = ((row[9] if len(row) > 9 else '') or '').strip()
    title = ((row[3] if len(row) > 3 else '') or '').strip().upper()
    return {
        'id': row[0] if len(row) > 0 else None,
        'academic_year_id': row[1] if len(row) > 1 else None,
        'term_id': row[2] if len(row) > 2 else None,
        'term_name': term_name,
        'term_label': term_name or 'Whole year',
        'activity_title': title,
        'activity_date': activity_date_val,
        'activity_date_display': _format_date_short(activity_date_val) or '',
        'activity_date_input': _calendar_date_input_value(activity_date_val),
        'end_date': end_date_val,
        'end_date_display': _format_date_short(end_date_val) or '',
        'end_date_input': _calendar_date_input_value(end_date_val),
        'category': category,
        'category_label': ACADEMIC_CALENDAR_CATEGORY_LABELS.get(category, category.title()),
        'activity_about': about,
        'notify_parents': notify_parents,
        'image_path': image_path,
        'image_url': _academic_calendar_image_public_url(image_path),
    }


def _calendar_date_input_value(value):
    d = _coerce_to_date(value)
    return d.strftime('%Y-%m-%d') if d else ''


def _parse_calendar_activity_form(form):
    """Parse academic calendar activity fields from a request form."""
    title = (form.get('activity_title') or '').strip().upper()
    activity_date = (form.get('activity_date') or '').strip()
    end_date = (form.get('end_date') or '').strip() or None
    category = (form.get('category') or 'event').strip().lower()
    activity_about = (form.get('activity_about') or '').strip()
    notify_raw = (form.get('notify_parents') or '').strip().lower()
    notify_parents = notify_raw in ('1', 'on', 'true', 'yes')
    term_id_raw = form.get('term_id', type=int)
    year_id = form.get('academic_year_id', type=int)
    if category not in ACADEMIC_CALENDAR_CATEGORY_LABELS:
        category = 'event'
    if not year_id or not title or not activity_date:
        return None, 'Title, date, and academic year are required.'
    try:
        datetime.strptime(activity_date, '%Y-%m-%d')
        if end_date:
            datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        return None, 'Please enter valid dates.'
    return {
        'year_id': int(year_id),
        'term_id_raw': term_id_raw,
        'title': title,
        'activity_date': activity_date,
        'end_date': end_date,
        'category': category,
        'activity_about': activity_about or None,
        'notify_parents': notify_parents,
    }, None


def _validate_calendar_activity_term(cursor, term_id_raw, year_id):
    if not term_id_raw:
        return True, term_id_raw
    cursor.execute(
        """
        SELECT id FROM terms
        WHERE id = %s AND academic_year_id = %s
        LIMIT 1
        """,
        (int(term_id_raw), int(year_id)),
    )
    if not cursor.fetchone():
        return False, None
    return True, int(term_id_raw)


def _fetch_academic_calendar_activities(cursor, academic_year_id, term_id=None):
    try:
        academic_year_id = int(academic_year_id)
    except (TypeError, ValueError):
        return []
    query = """
        SELECT a.id, a.academic_year_id, a.term_id, a.activity_title, a.activity_date, a.end_date,
               a.category, a.activity_about, a.notify_parents, a.image_path, t.term_name
        FROM academic_calendar_activities a
        LEFT JOIN terms t ON t.id = a.term_id
        WHERE a.academic_year_id = %s AND COALESCE(a.status, 'active') = 'active'
    """
    params = [academic_year_id]
    if term_id:
        try:
            term_id = int(term_id)
            query += " AND (a.term_id IS NULL OR a.term_id = %s)"
            params.append(term_id)
        except (TypeError, ValueError):
            pass
    query += " ORDER BY a.activity_date ASC, a.id ASC"
    cursor.execute(query, tuple(params))
    return [_calendar_activity_row_dict(r) for r in (cursor.fetchall() or [])]


def _synthesize_term_calendar_activities(cursor, academic_year_id):
    """Build term-date rows from the terms table for public calendar display."""
    activities = []
    for term in _fetch_terms_for_calendar_year(cursor, academic_year_id):
        start = _coerce_to_date(term.get('start_date'))
        if not start:
            continue
        end = _coerce_to_date(term.get('end_date'))
        term_name = (term.get('term_name') or '').strip()
        term_id = term.get('id')
        try:
            synthetic_id = -int(term_id) if term_id is not None else None
        except (TypeError, ValueError):
            synthetic_id = None
        activities.append({
            'id': synthetic_id,
            'academic_year_id': int(academic_year_id),
            'term_id': term_id,
            'term_name': term_name,
            'term_label': term_name or 'Whole year',
            'activity_title': term_name or 'Term dates',
            'activity_date': start,
            'activity_date_display': _format_date_short(start) or '',
            'end_date': end,
            'end_date_display': _format_date_short(end) or '',
            'category': 'term',
            'category_label': ACADEMIC_CALENDAR_CATEGORY_LABELS.get('term', 'Term dates'),
            'activity_about': 'Official term dates for this academic year.',
            'notify_parents': True,
            'activity_date_input': _calendar_date_input_value(start),
            'end_date_input': _calendar_date_input_value(end),
            'is_synthetic_term': True,
        })
    return activities


def _merge_term_dates_into_calendar_activities(cursor, academic_year_id, activities):
    """Include published term dates when building the public academic calendar feed."""
    merged = list(activities or [])
    covered_term_ids = set()
    for act in merged:
        if (act.get('category') or '').strip().lower() != 'term':
            continue
        try:
            tid = int(act.get('term_id') or 0)
        except (TypeError, ValueError):
            tid = 0
        if tid:
            covered_term_ids.add(tid)
    for row in _synthesize_term_calendar_activities(cursor, academic_year_id):
        try:
            tid = int(row.get('term_id') or 0)
        except (TypeError, ValueError):
            tid = 0
        if tid and tid in covered_term_ids:
            continue
        merged.append(row)
    merged.sort(
        key=lambda x: (
            _coerce_to_date(x.get('activity_date')) or date_cls.min,
            x.get('id') or 0,
        ),
    )
    return merged


def _group_calendar_activities_by_month(activities):
    from collections import OrderedDict
    groups = OrderedDict()
    for item in activities or []:
        d = _coerce_to_date(item.get('activity_date'))
        if d:
            key = d.strftime('%Y-%m')
            label = d.strftime('%B %Y')
        else:
            key = 'unknown'
            label = 'Other'
        if key not in groups:
            groups[key] = {'label': label, 'items': []}
        groups[key]['items'].append(item)
    return list(groups.values())


def _build_calendar_branch_tree(activities, selected_year=None):
    """Build opening → events → closing branch layout for the public News page."""
    today = date_cls.today()
    year_start = year_end = None
    year_name = ''
    if selected_year:
        year_start = _coerce_to_date(selected_year.get('start_date'))
        year_end = _coerce_to_date(selected_year.get('end_date'))
        year_name = (selected_year.get('year_name') or '').strip()

    event_starts = []
    event_ends = []
    for act in activities or []:
        s = _coerce_to_date(act.get('sort_date') or act.get('activity_date'))
        e = _coerce_to_date(act.get('end_date') or act.get('iso_end_date')) or s
        if s:
            event_starts.append(s)
        if e:
            event_ends.append(e)

    if not year_start and event_starts:
        year_start = min(event_starts)
    if not year_end and event_ends:
        year_end = max(event_ends)
    if not year_start or not year_end:
        return None
    if year_end < year_start:
        year_start, year_end = year_end, year_start

    total_days = max((year_end - year_start).days, 1)

    def _position_pct(d):
        if not d:
            return 50.0
        offset = (d - year_start).days
        return round(max(0.0, min(100.0, (offset / total_days) * 100)), 2)

    def _anchor_node(label, d, position_pct):
        return {
            'label': label,
            'date_label': _format_date_short(d),
            'iso_date': d.strftime('%Y-%m-%d'),
            'position_pct': position_pct,
            'is_past': d < today,
            'is_today': d == today,
        }

    trunk = {
        'opening': _anchor_node('Opening day', year_start, 0),
        'closing': _anchor_node('Closing day', year_end, 100),
        'year_name': year_name,
        'total_days': total_days + 1,
        'span_label': f"{_format_date_short(year_start)} – {_format_date_short(year_end)}",
    }

    branches = []
    for idx, act in enumerate(activities or []):
        start = _coerce_to_date(act.get('sort_date') or act.get('activity_date'))
        end = _coerce_to_date(act.get('end_date') or act.get('iso_end_date')) or start
        if start and end and end < start:
            start, end = end, start
        if not start:
            continue
        start_pct = _position_pct(start)
        end_pct = _position_pct(end or start)
        span_pct = max(end_pct - start_pct, 1.5)
        branches.append({
            'item': act,
            'side': 'left' if idx % 2 == 0 else 'right',
            'start_pct': start_pct,
            'end_pct': end_pct,
            'span_pct': span_pct,
            'mid_pct': round((start_pct + end_pct) / 2, 2),
            'opening_label': act.get('opening_date_label') or _format_date_short(start),
            'closing_label': act.get('closing_date_label') or _format_date_short(end or start),
            'is_spanning': bool(end and start and end > start),
        })

    return {'trunk': trunk, 'branches': branches}


