def _prepare_public_calendar_news(activities, selected_year=None):
    """Enrich academic calendar rows for the public News page."""
    today = date_cls.today()
    sorted_acts = sorted(
        activities or [],
        key=lambda x: (
            _coerce_to_date(x.get('activity_date')) or date_cls.min,
            x.get('id') or 0,
        ),
    )
    enriched = []
    category_counts = {}
    for act in sorted_acts:
        category = (act.get('category') or 'event').strip().lower()
        colors = _calendar_category_colors(category)
        start = _coerce_to_date(act.get('activity_date'))
        end = _coerce_to_date(act.get('end_date')) or start
        if end and start and end < start:
            start, end = end, start
        entry = dict(act)
        entry['category'] = category
        entry['color_badge'] = colors['badge']
        entry['color_bg'] = colors['bg']
        entry['color_text'] = colors['text']
        entry['category_icon'] = ACADEMIC_CALENDAR_CATEGORY_ICONS.get(category, 'fa-bell')
        image_url = (act.get('image_url') or '').strip()
        default_cover = ACADEMIC_CALENDAR_CATEGORY_COVERS.get(
            category, ACADEMIC_CALENDAR_CATEGORY_COVERS['other'],
        )
        entry['has_custom_image'] = bool(image_url)
        entry['cover_image'] = image_url or default_cover
        if start:
            entry['date_day'] = start.day
            entry['date_month'] = start.strftime('%b').upper()
            entry['date_year'] = start.year
            entry['sort_date'] = start
            entry['iso_date'] = start.strftime('%Y-%m-%d')
        else:
            entry['date_day'] = None
            entry['date_month'] = ''
            entry['date_year'] = ''
            entry['sort_date'] = None
            entry['iso_date'] = ''
        if start and end and end > start:
            entry['date_range_label'] = f"{_format_date_short(start)} – {_format_date_short(end)}"
            entry['duration_days'] = (end - start).days + 1
        elif start:
            entry['date_range_label'] = _format_date_short(start)
            entry['duration_days'] = 1
        else:
            entry['date_range_label'] = 'Date to be confirmed'
            entry['duration_days'] = 0
        entry['opening_date_label'] = _format_date_short(start) if start else ''
        entry['closing_date_label'] = (
            _format_date_short(end) if end else (entry['opening_date_label'] or '')
        )
        if end:
            entry['iso_end_date'] = end.strftime('%Y-%m-%d')
        else:
            entry['iso_end_date'] = entry.get('iso_date') or ''
        end_cmp = end or start
        entry['is_upcoming'] = bool(end_cmp and end_cmp >= today)
        entry['is_today'] = bool(
            start and end_cmp and start <= today <= end_cmp
        )
        if start and start > today:
            entry['days_until'] = (start - today).days
        elif entry['is_today']:
            entry['days_until'] = 0
        else:
            entry['days_until'] = None
        enriched.append(entry)
        category_counts[category] = category_counts.get(category, 0) + 1

    upcoming = [a for a in enriched if a.get('is_upcoming')]
    past = [a for a in enriched if not a.get('is_upcoming')]
    past.reverse()

    spotlight = None
    for candidate in upcoming:
        if candidate.get('is_today'):
            spotlight = candidate
            break
    if not spotlight:
        for candidate in upcoming:
            if candidate.get('has_custom_image'):
                spotlight = candidate
                break
    if not spotlight and upcoming:
        spotlight = upcoming[0]

    photo_highlights = [a for a in enriched if a.get('has_custom_image')]

    year_label = ''
    if selected_year and selected_year.get('year_name'):
        year_label = selected_year['year_name']

    this_month_key = today.strftime('%Y-%m')
    this_month_count = sum(
        1 for a in enriched
        if a.get('iso_date', '').startswith(this_month_key)
    )

    return {
        'activities': enriched,
        'upcoming_activities': upcoming,
        'past_activities': past,
        'month_groups': _group_calendar_activities_by_month(enriched),
        'branch_tree': _build_calendar_branch_tree(enriched, selected_year),
        'year_label': year_label,
        'upcoming_count': len(upcoming),
        'past_count': len(past),
        'total_count': len(enriched),
        'spotlight': spotlight,
        'photo_highlights': photo_highlights,
        'category_counts': category_counts,
        'this_month_count': this_month_count,
    }


def _resolve_calendar_term_id(cursor, academic_year_id, requested_term_id=None, default_to_current=False):
    """Resolve term filter. None = all terms; default_to_current picks is_current when no id given."""
    terms = _fetch_terms_for_calendar_year(cursor, academic_year_id)
    if not terms:
        return None, terms, None
    if requested_term_id == 0:
        return None, terms, None
    if requested_term_id:
        for t in terms:
            if str(t.get('id')) == str(requested_term_id):
                return int(t['id']), terms, t
        return None, terms, None
    if default_to_current:
        for t in terms:
            if t.get('is_current'):
                return int(t['id']), terms, t
    return None, terms, None


def _calendar_manage_redirect_query(year_id, term_id=None):
    qs = f'academic_year_id={int(year_id)}'
    if term_id:
        qs += f'&term_id={int(term_id)}'
    return qs


def _resolve_calendar_year_id(cursor, requested_year_id=None):
    years = _fetch_academic_years_for_calendar(cursor)
    if not years:
        return None, years
    if requested_year_id:
        for y in years:
            if str(y.get('id')) == str(requested_year_id):
                return int(y['id']), years
    for y in years:
        if y.get('is_current'):
            return int(y['id']), years
    return int(years[0]['id']), years


def _attendance_class_day_sql(alias='sar'):
    """Whole-day class attendance only (subject_id = 0), not per-subject cells."""
    col = f"COALESCE({alias}.subject_id, 0)" if alias else 'COALESCE(subject_id, 0)'
    return f"{col} = 0"


def _resolve_current_academic_year_id(cursor):
    try:
        cursor.execute("""
            SELECT id FROM academic_years
            WHERE COALESCE(is_current, 0) = 1
            ORDER BY id DESC LIMIT 1
        """)
        row = cursor.fetchone()
        if row:
            return int(row.get('id') if isinstance(row, dict) else row[0])
        cursor.execute("SELECT id FROM academic_years ORDER BY id DESC LIMIT 1")
        row = cursor.fetchone()
        if row:
            return int(row.get('id') if isinstance(row, dict) else row[0])
    except Exception as e:
        print(f"_resolve_current_academic_year_id: {e}")
    return None


def _fetch_class_teacher_level_names(cursor, teacher_id, academic_year_id=None):
    """Level names where teacher is assigned as class teacher for the given year."""
    names = []
    try:
        teacher_id = int(teacher_id)
    except (TypeError, ValueError):
        return names
    if not teacher_id:
        return names
    ensure_class_teacher_assignments_table(cursor)
    if not academic_year_id:
        academic_year_id = _resolve_current_academic_year_id(cursor)
    if not academic_year_id:
        return names
    try:
        cursor.execute("""
            SELECT al.level_name
            FROM class_teacher_assignments cta
            INNER JOIN academic_levels al ON al.id = cta.academic_level_id
            WHERE cta.teacher_id = %s AND cta.academic_year_id = %s
            ORDER BY al.level_name ASC
        """, (teacher_id, int(academic_year_id)))
        for row in cursor.fetchall() or []:
            ln = (row.get('level_name') if isinstance(row, dict) else row[0]) or ''
            ln = str(ln).strip()
            if ln and ln not in names:
                names.append(ln)
    except Exception as e:
        print(f"_fetch_class_teacher_level_names: {e}")
    return names


def _teacher_has_class_teacher_assignment(teacher_id, academic_year_id=None):
    connection = get_db_connection()
    if not connection:
        return False
    try:
        with connection.cursor() as cursor:
            names = _fetch_class_teacher_level_names(cursor, teacher_id, academic_year_id)
            return len(names) > 0
    except Exception:
        return False
    finally:
        try:
            connection.close()
        except Exception:
            pass


def _get_class_teacher_class_level_options(teacher_id, academic_year_id=None):
    connection = get_db_connection()
    if not connection:
        return []
    try:
        with connection.cursor() as cursor:
            return _fetch_class_teacher_level_names(cursor, teacher_id, academic_year_id)
    finally:
        try:
            connection.close()
        except Exception:
            pass


def _fetch_class_teacher_assignments_map(cursor, academic_year_id):
    """Return {level_id: {teacher_id, teacher_name, employee_id, credentials, level_name, ...}}."""
    out = {}
    ensure_class_teacher_assignments_table(cursor)
    if not academic_year_id:
        academic_year_id = _resolve_current_academic_year_id(cursor)
    if not academic_year_id:
        return out
    try:
        staff_sql = _employee_staff_identity_sql('e')
        cursor.execute(f"""
            SELECT cta.academic_level_id, cta.teacher_id,
                   al.level_name, al.level_category,
                   e.full_name AS teacher_name, e.employee_id,
                   {staff_sql} AS staff_number
            FROM class_teacher_assignments cta
            INNER JOIN academic_levels al ON al.id = cta.academic_level_id
            LEFT JOIN employees e ON e.id = cta.teacher_id
            WHERE cta.academic_year_id = %s
        """, (int(academic_year_id),))
        for row in cursor.fetchall() or []:
            lid = row.get('academic_level_id') if isinstance(row, dict) else row[0]
            if lid is None:
                continue
            teacher_name = (row.get('teacher_name') if isinstance(row, dict) else row[4]) or ''
            employee_code = (row.get('employee_id') if isinstance(row, dict) else row[5]) or ''
            staff_number = ''
            if isinstance(row, dict):
                staff_number = row.get('staff_number') or ''
            elif len(row) > 6:
                staff_number = row[6] or ''
            credentials = (str(staff_number).strip() or str(employee_code).strip())
            out[int(lid)] = {
                'academic_level_id': int(lid),
                'teacher_id': row.get('teacher_id') if isinstance(row, dict) else row[1],
                'level_name': (row.get('level_name') if isinstance(row, dict) else row[2]) or '',
                'level_category': (row.get('level_category') if isinstance(row, dict) else row[3]) or '',
                'teacher_name': teacher_name,
                'employee_id': employee_code,
                'credentials': credentials,
            }
    except Exception as e:
        print(f"_fetch_class_teacher_assignments_map: {e}")
    return out


def _fetch_head_of_institution_signatory(cursor):
    """Active head of institution name + staff credentials for report signatures."""
    try:
        staff_sql = _employee_staff_identity_sql('e')
        cursor.execute(
            f"""
            SELECT e.full_name, e.employee_id, {staff_sql} AS staff_number
            FROM employees e
            WHERE e.role = 'head of institution' AND e.status = 'active'
            ORDER BY e.id ASC
            LIMIT 1
            """
        )
        row = cursor.fetchone()
        if not row:
            return {'name': '', 'employee_id': '', 'credentials': ''}
        if isinstance(row, dict):
            name = (row.get('full_name') or '').strip()
            employee_code = (row.get('employee_id') or '').strip()
            staff_number = (row.get('staff_number') or '').strip()
        else:
            name = (row[0] or '').strip() if len(row) > 0 else ''
            employee_code = (row[1] or '').strip() if len(row) > 1 else ''
            staff_number = (row[2] or '').strip() if len(row) > 2 else ''
        return {
            'name': name,
            'employee_id': employee_code,
            'credentials': staff_number or employee_code,
        }
    except Exception as e:
        print(f"_fetch_head_of_institution_signatory: {e}")
        return {'name': '', 'employee_id': '', 'credentials': ''}


def _fetch_head_of_institution_name(cursor):
    """Active head of institution name for document sign-off hints."""
    try:
        info = _fetch_head_of_institution_signatory(cursor)
        return (info.get('name') or '').strip()
    except Exception as e:
        print(f"_fetch_head_of_institution_name: {e}")
        return ''


def _get_current_academic_year_and_term(cursor):
    """Return (year_id, year_name, term_id, term_name) for the active year/term, or Nones."""
    cursor.execute("""
        SELECT id, year_name FROM academic_years
        WHERE is_current = TRUE AND status = 'active'
        LIMIT 1
    """)
    year_row = cursor.fetchone()
    if not year_row:
        return None, None, None, None
    year_id = year_row.get('id') if isinstance(year_row, dict) else year_row[0]
    year_name = (year_row.get('year_name', '') if isinstance(year_row, dict) else (year_row[1] if len(year_row) > 1 else '')) or ''
    cursor.execute("""
        SELECT id, term_name FROM terms
        WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
        LIMIT 1
    """, (year_id,))
    term_row = cursor.fetchone()
    if not term_row:
        return year_id, year_name, None, None
    term_id = term_row.get('id') if isinstance(term_row, dict) else term_row[0]
    term_name = (term_row.get('term_name', '') if isinstance(term_row, dict) else (term_row[1] if len(term_row) > 1 else '')) or ''
    return year_id, year_name, term_id, term_name


def _coerce_to_date(value):
    """Normalize DB date/datetime/str values to datetime.date."""
    if value is None:
        return None
    if isinstance(value, date_cls):
        return value
    if isinstance(value, datetime):
        return value.date()
    text = str(value).strip()
    if not text:
        return None
    try:
        return datetime.strptime(text[:10], '%Y-%m-%d').date()
    except ValueError:
        return None


def _term_teaching_weeks_from_dates(start_date, end_date):
    """Inclusive calendar weeks between term start and end (minimum 1 when valid)."""
    start = _coerce_to_date(start_date)
    end = _coerce_to_date(end_date)
    if not start or not end:
        return 0
    if end < start:
        start, end = end, start
    days = (end - start).days + 1
    return max(1, (days + 6) // 7)


def _format_date_short(value):
    d = _coerce_to_date(value)
    if not d:
        return None
    return d.strftime('%d %b %Y')


