def _migrate_legacy_class_grade_overrides_to_profiles(cursor):
    """One-time style migration: per-class overrides -> named profile + assignment."""
    try:
        cursor.execute("SHOW TABLES LIKE 'class_grade_mark_overrides'")
        if not cursor.fetchone():
            return
        cursor.execute("""
            SELECT DISTINCT cgo.academic_level_id, al.level_name
            FROM class_grade_mark_overrides cgo
            LEFT JOIN academic_levels al ON al.id = cgo.academic_level_id
            WHERE cgo.academic_level_id IS NOT NULL
        """)
        legacy_levels = cursor.fetchall() or []
        for row in legacy_levels:
            if isinstance(row, dict):
                lid = int(row.get('academic_level_id') or 0)
                lname = (row.get('level_name') or '').strip() or f'Class {lid}'
            else:
                lid = int(row[0] or 0)
                lname = (row[1] if len(row) > 1 else '').strip() or f'Class {lid}'
            if lid <= 0:
                continue
            cursor.execute(
                "SELECT 1 FROM class_grade_setting_assignments WHERE academic_level_id = %s LIMIT 1",
                (lid,),
            )
            if cursor.fetchone():
                continue
            pname = f'{lname} (migrated)'[:255]
            cursor.execute(
                "SELECT id FROM grade_setting_profiles WHERE name = %s LIMIT 1",
                (pname,),
            )
            existing = cursor.fetchone()
            if existing:
                pid = existing.get('id') if isinstance(existing, dict) else existing[0]
            else:
                cursor.execute(
                    "INSERT INTO grade_setting_profiles (name, description, created_by) VALUES (%s, %s, %s)",
                    (pname, 'Migrated from per-class grade overrides', session.get('user_id')),
                )
                pid = cursor.lastrowid
                cursor.execute("""
                    SELECT code, level_label, meaning, start_mark, end_mark, allocation_points
                    FROM class_grade_mark_overrides
                    WHERE academic_level_id = %s
                    ORDER BY COALESCE(start_mark, -1) DESC, COALESCE(end_mark, -1) DESC, code
                """, (lid,))
                for brow in (cursor.fetchall() or []):
                    if isinstance(brow, dict):
                        c = brow.get('code')
                        ll = brow.get('level_label')
                        mn = brow.get('meaning')
                        sm = brow.get('start_mark')
                        em = brow.get('end_mark')
                        ap = brow.get('allocation_points')
                    else:
                        c = brow[0]
                        ll = brow[1] if len(brow) > 1 else None
                        mn = brow[2] if len(brow) > 2 else None
                        sm = brow[3] if len(brow) > 3 else None
                        em = brow[4] if len(brow) > 4 else None
                        ap = brow[5] if len(brow) > 5 else None
                    if not c or sm is None or em is None:
                        continue
                    cursor.execute("""
                        INSERT INTO grade_setting_profile_bands (
                            profile_id, code, level_label, meaning, start_mark, end_mark,
                            allocation_points, rank_order, description
                        )
                        VALUES (%s, %s, %s, %s, %s, %s, %s, NULL, NULL)
                    """, (pid, (c or '').strip().upper(), ll, mn, sm, em, ap))
            cursor.execute("""
                INSERT INTO class_grade_setting_assignments (academic_level_id, profile_id)
                VALUES (%s, %s)
                ON DUPLICATE KEY UPDATE profile_id = VALUES(profile_id)
            """, (lid, pid))
    except Exception as e:
        _schema_ignore_existing(e, 'legacy class grade override migration skipped')


def build_class_grade_bands_from_profiles(cursor):
    """Map academic_level_id -> runtime grade bands from assigned grading settings."""
    class_grade_bands = {}
    try:
        ensure_grade_setting_profile_tables(cursor)
        cursor.execute("""
            SELECT a.academic_level_id, b.code, b.level_label, b.start_mark, b.end_mark, b.allocation_points
            FROM class_grade_setting_assignments a
            INNER JOIN grade_setting_profile_bands b ON b.profile_id = a.profile_id
            WHERE b.start_mark IS NOT NULL AND b.end_mark IS NOT NULL
            ORDER BY a.academic_level_id ASC,
                     COALESCE(b.rank_order, 9999) ASC, b.start_mark DESC, b.end_mark DESC, b.code
        """)
        for row in (cursor.fetchall() or []):
            if isinstance(row, dict):
                lid = int(row.get('academic_level_id') or 0)
                band = _grade_band_dict_for_runtime(
                    row.get('code'), row.get('level_label'),
                    row.get('start_mark'), row.get('end_mark'), row.get('allocation_points'),
                )
            else:
                lid = int(row[0] or 0)
                band = _grade_band_dict_for_runtime(row[1], row[2], row[3], row[4], row[5] if len(row) > 5 else None)
            if lid <= 0:
                continue
            class_grade_bands.setdefault(lid, []).append(band)
    except Exception as e:
        _schema_ignore_existing(e, 'class grade setting profiles lookup skipped')
    return class_grade_bands


def load_grade_setting_profiles_for_page(cursor, default_bands_template=None):
    """Profiles with bands and assigned class names for the grades registration UI."""
    ensure_grade_setting_profile_tables(cursor)
    _migrate_legacy_class_grade_overrides_to_profiles(cursor)
    profiles = []
    cursor.execute("""
        SELECT id, name, description
        FROM grade_setting_profiles
        ORDER BY name ASC
    """)
    profile_rows = cursor.fetchall() or []
    if not profile_rows:
        return profiles

    profile_ids = []
    profile_meta = {}
    for row in profile_rows:
        if isinstance(row, dict):
            pid = int(row.get('id') or 0)
            profile_meta[pid] = {
                'id': pid,
                'name': row.get('name') or '',
                'description': row.get('description') or '',
            }
        else:
            pid = int(row[0] or 0)
            profile_meta[pid] = {
                'id': pid,
                'name': row[1] if len(row) > 1 else '',
                'description': row[2] if len(row) > 2 else '',
            }
        if pid > 0:
            profile_ids.append(pid)

    bands_by_profile = {pid: [] for pid in profile_ids}
    if profile_ids:
        ph = ','.join(['%s'] * len(profile_ids))
        cursor.execute(f"""
            SELECT profile_id, rank_order, code, level_label, meaning, description,
                   start_mark, end_mark, allocation_points
            FROM grade_setting_profile_bands
            WHERE profile_id IN ({ph})
            ORDER BY profile_id, COALESCE(rank_order, 9999) ASC,
                     COALESCE(start_mark, -1) DESC, COALESCE(end_mark, -1) DESC, code
        """, tuple(profile_ids))
        for brow in (cursor.fetchall() or []):
            if isinstance(brow, dict):
                pid = int(brow.get('profile_id') or 0)
                bands_by_profile.setdefault(pid, []).append(_grade_band_dict_for_template(
                    brow.get('code'), brow.get('level_label'), brow.get('meaning'),
                    brow.get('start_mark'), brow.get('end_mark'), brow.get('allocation_points'),
                    brow.get('rank_order'), brow.get('description'),
                ))
            else:
                pid = int(brow[0] or 0)
                bands_by_profile.setdefault(pid, []).append(_grade_band_dict_for_template(
                    brow[2] if len(brow) > 2 else None,
                    brow[3] if len(brow) > 3 else None,
                    brow[4] if len(brow) > 4 else None,
                    brow[6] if len(brow) > 6 else None,
                    brow[7] if len(brow) > 7 else None,
                    brow[8] if len(brow) > 8 else None,
                    brow[1] if len(brow) > 1 else None,
                    brow[5] if len(brow) > 5 else None,
                ))

    classes_by_profile = {pid: [] for pid in profile_ids}
    cursor.execute("""
        SELECT a.profile_id, al.level_name, al.level_category
        FROM class_grade_setting_assignments a
        INNER JOIN academic_levels al ON al.id = a.academic_level_id
        ORDER BY al.level_category, al.level_name
    """)
    for row in (cursor.fetchall() or []):
        if isinstance(row, dict):
            pid = int(row.get('profile_id') or 0)
            lname = row.get('level_name') or ''
            lcat = row.get('level_category') or ''
        else:
            pid = int(row[0] or 0)
            lname = row[1] if len(row) > 1 else ''
            lcat = row[2] if len(row) > 2 else ''
        if pid > 0:
            classes_by_profile.setdefault(pid, []).append({'level_name': lname, 'level_category': lcat})

    for pid in profile_ids:
        meta = profile_meta.get(pid, {})
        profiles.append({
            'id': pid,
            'name': meta.get('name') or '',
            'description': meta.get('description') or '',
            'bands': bands_by_profile.get(pid) or [],
            'default_bands': default_bands_template or [],
            'assigned_classes': classes_by_profile.get(pid) or [],
            'class_count': len(classes_by_profile.get(pid) or []),
        })
    return profiles


def load_class_grade_setting_assignments_map(cursor):
    """academic_level_id -> profile_id."""
    ensure_grade_setting_profile_tables(cursor)
    out = {}
    try:
        cursor.execute("""
            SELECT academic_level_id, profile_id
            FROM class_grade_setting_assignments
        """)
        for row in (cursor.fetchall() or []):
            if isinstance(row, dict):
                lid = int(row.get('academic_level_id') or 0)
                pid = int(row.get('profile_id') or 0)
            else:
                lid = int(row[0] or 0)
                pid = int(row[1] or 0)
            if lid > 0 and pid > 0:
                out[lid] = pid
    except Exception as e:
        _schema_ignore_existing(e, 'class_grade_setting_assignments lookup skipped')
    return out


def parse_grade_band_rows_from_form():
    """Parse parallel form lists into validated grade band rows (full custom labels)."""
    codes = request.form.getlist('code')
    level_labels = request.form.getlist('level_label')
    meanings = request.form.getlist('meaning')
    descriptions = request.form.getlist('description')
    start_marks = request.form.getlist('start_mark')
    end_marks = request.form.getlist('end_mark')
    allocation_points_list = request.form.getlist('allocation_points')
    rank_orders = request.form.getlist('rank_order')
    if not (codes and len(codes) == len(start_marks) == len(end_marks)):
        raise ValueError('invalid_payload')
    if not (len(level_labels) == len(meanings) == len(codes)):
        raise ValueError('invalid_payload')
    if len(allocation_points_list) < len(codes):
        allocation_points_list = list(allocation_points_list) + [''] * (len(codes) - len(allocation_points_list))
    if len(level_labels) < len(codes):
        level_labels = list(level_labels) + [''] * (len(codes) - len(level_labels))
    if len(meanings) < len(codes):
        meanings = list(meanings) + [''] * (len(codes) - len(meanings))
    if len(descriptions) < len(codes):
        descriptions = list(descriptions) + [''] * (len(codes) - len(descriptions))
    if len(rank_orders) < len(codes):
        rank_orders = list(rank_orders) + [''] * (len(codes) - len(rank_orders))

    rows = []
    seen_codes = set()
    for idx, code in enumerate(codes):
        c = (code or '').strip().upper()
        sm = float((start_marks[idx] or '').strip())
        em = float((end_marks[idx] or '').strip())
        level_label = (level_labels[idx] if idx < len(level_labels) else '').strip()
        meaning = (meanings[idx] if idx < len(meanings) else '').strip()
        desc = (descriptions[idx] if idx < len(descriptions) else '').strip() or None
        if not c:
            raise ValueError('missing_code')
        if c in seen_codes:
            raise ValueError('duplicate_code')
        seen_codes.add(c)
        if sm > em:
            raise ValueError('mark_range')
        if not (level_label and meaning):
            raise ValueError('missing_label')
        ap_raw = (allocation_points_list[idx] if idx < len(allocation_points_list) else '').strip()
        ap = None
        if ap_raw:
            ap = float(ap_raw)
        rk_raw = (rank_orders[idx] if idx < len(rank_orders) else '').strip()
        rk = None
        if rk_raw:
            try:
                rk = int(float(rk_raw))
            except (TypeError, ValueError):
                raise ValueError('invalid_rank')
        rows.append((c, level_label.upper(), meaning.upper(), sm, em, ap, rk, desc))
    return rows


def resolve_grade_bands(level_id, class_grade_bands, default_grade_bands):
    """Use the class's assigned grading setting when present; otherwise school default bands."""
    try:
        lid = int(level_id or 0)
    except (TypeError, ValueError):
        lid = 0
    if lid and class_grade_bands and class_grade_bands.get(lid):
        return class_grade_bands[lid]
    return default_grade_bands or []


def grade_bands_for_level(level_id, class_grade_bands, default_grade_bands):
    """Alias for templates and reports (allocated profile overrides default)."""
    return resolve_grade_bands(level_id, class_grade_bands, default_grade_bands)


def fetch_grade_bands_for_marks_sheet(
    level_id, exam_name=None, academic_year_id=None, term_id=None, exam_type=None,
):
    """
    Load grading bands for an exams-assessments class marks sheet.
    Registered current exam uses live settings; past exams use frozen snapshots.
    """
    connection = get_db_connection()
    if not connection:
        return [], [], {}, {}, False, None
    try:
        with connection.cursor() as cursor:
            registered_current = load_registered_current_exam_dict(cursor)
            default_grade_bands, subject_grade_bands, class_grade_bands = load_grade_bands_for_exam_context(
                cursor, exam_name, academic_year_id, term_id, level_id,
                registered_current=registered_current, exam_type=exam_type,
            )
            active_grade_bands = grade_bands_for_level(level_id, class_grade_bands, default_grade_bands)
            try:
                lid = int(level_id or 0)
            except (TypeError, ValueError):
                lid = 0
            uses_class = bool(lid and class_grade_bands.get(lid))
            grading_setting_name = None
            if _should_use_live_exam_settings(
                exam_name, academic_year_id, term_id, registered_current, exam_type,
            ):
                if uses_class:
                    assignments = load_class_grade_setting_assignments_map(cursor)
                    pid = assignments.get(lid)
                    if pid:
                        cursor.execute(
                            "SELECT name FROM grade_setting_profiles WHERE id = %s",
                            (pid,),
                        )
                        row = cursor.fetchone()
                        if row:
                            grading_setting_name = (
                                row.get('name') if isinstance(row, dict) else row[0]
                            )
                if not grading_setting_name:
                    grading_setting_name = 'Current exam (live settings)'
            else:
                snap = get_exam_context_settings_snapshot(
                    cursor, exam_name, academic_year_id, term_id, level_id,
                ) if exam_name and academic_year_id and term_id and level_id else None
                if snap:
                    grading_setting_name = 'Frozen exam settings'
                elif uses_class:
                    assignments = load_class_grade_setting_assignments_map(cursor)
                    pid = assignments.get(lid)
                    if pid:
                        cursor.execute(
                            "SELECT name FROM grade_setting_profiles WHERE id = %s",
                            (pid,),
                        )
                        row = cursor.fetchone()
                        if row:
                            grading_setting_name = (
                                row.get('name') if isinstance(row, dict) else row[0]
                            )
            class_grade_bands_json = {str(k): v for k, v in (class_grade_bands or {}).items()}
            return (
                active_grade_bands,
                default_grade_bands,
                subject_grade_bands,
                class_grade_bands_json,
                uses_class,
                grading_setting_name,
            )
    except Exception as e:
        print(f"Error loading grade bands for marks sheet level {level_id}: {e}")
        return [], [], {}, {}, False, None
    finally:
        connection.close()


def load_grade_bands_from_db(cursor):
    """Load default, per-class, and per-subject grade bands (marks sheet / reports)."""
    default_grade_bands = []
    subject_grade_bands = {}
    class_grade_bands = {}
    try:
        cursor.execute("""
            SELECT code, level_label, start_mark, end_mark, allocation_points
            FROM grade_registrations
            WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
            ORDER BY start_mark DESC, end_mark DESC
        """)
        for grow in (cursor.fetchall() or []):
            if isinstance(grow, dict):
                ap = grow.get('allocation_points')
                default_grade_bands.append({
                    'code': (grow.get('code') or '').strip(),
                    'label': (grow.get('level_label') or '').strip(),
                    'start': float(grow.get('start_mark') or 0),
                    'end': float(grow.get('end_mark') or 0),
                    'allocation_points': float(ap) if ap is not None else None,
                })
            else:
                apv = grow[4] if len(grow) > 4 else None
                default_grade_bands.append({
                    'code': ((grow[0] if len(grow) > 0 else '') or '').strip(),
                    'label': ((grow[1] if len(grow) > 1 else '') or '').strip(),
                    'start': float(grow[2] or 0) if len(grow) > 2 else 0.0,
                    'end': float(grow[3] or 0) if len(grow) > 3 else 0.0,
                    'allocation_points': float(apv) if apv is not None else None,
                })
    except Exception as ge:
        print(f"Note: grade_registrations lookup skipped: {ge}")
    try:
        cursor.execute("""
            SELECT subject_id, code, level_label, start_mark, end_mark, allocation_points
            FROM subject_grade_mark_overrides
            WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
            ORDER BY subject_id ASC, start_mark DESC, end_mark DESC
        """)
        for srow in (cursor.fetchall() or []):
            if isinstance(srow, dict):
                sid = int(srow.get('subject_id') or 0)
                ap = srow.get('allocation_points')
                band = {
                    'code': (srow.get('code') or '').strip(),
                    'label': (srow.get('level_label') or '').strip(),
                    'start': float(srow.get('start_mark') or 0),
                    'end': float(srow.get('end_mark') or 0),
                    'allocation_points': float(ap) if ap is not None else None,
                }
            else:
                sid = int(srow[0] or 0) if len(srow) > 0 else 0
                apv = srow[5] if len(srow) > 5 else None
                band = {
                    'code': ((srow[1] if len(srow) > 1 else '') or '').strip(),
                    'label': ((srow[2] if len(srow) > 2 else '') or '').strip(),
                    'start': float(srow[3] or 0) if len(srow) > 3 else 0.0,
                    'end': float(srow[4] or 0) if len(srow) > 4 else 0.0,
                    'allocation_points': float(apv) if apv is not None else None,
                }
            if sid <= 0:
                continue
            subject_grade_bands.setdefault(sid, []).append(band)
    except Exception as se:
        print(f"Note: subject_grade_mark_overrides lookup skipped: {se}")
    class_grade_bands = build_class_grade_bands_from_profiles(cursor)
    return default_grade_bands, subject_grade_bands, class_grade_bands


def ensure_grade_code_remarks_table(cursor):
    """Store per-grade remarks for a given exam context (used on report cards)."""
    try:
        cursor.execute("SHOW TABLES LIKE 'grade_code_remarks'")
        if not cursor.fetchone():
            cursor.execute(
                """
                CREATE TABLE IF NOT EXISTS grade_code_remarks (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    academic_year_id INT NULL,
                    term_id INT NULL,
                    academic_level_id INT NOT NULL,
                    exam_name VARCHAR(255) NOT NULL,
                    grade_code VARCHAR(32) NOT NULL,
                    remark_text TEXT NULL,
                    updated_by_employee_id INT NULL,
                    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    UNIQUE KEY uniq_grade_code_remark_ctx (academic_year_id, term_id, academic_level_id, exam_name, grade_code),
                    INDEX idx_grade_code_remark_level (academic_level_id),
                    INDEX idx_grade_code_remark_exam (exam_name)
                )
                """
            )
            print("OK: Created grade_code_remarks table")
    except Exception as e:
        _schema_ignore_existing(e, 'ensure_grade_code_remarks_table skipped')


def _coerce_int_or_none(v):
    try:
        if v is None:
            return None
        s = str(v).strip()
        if not s:
            return None
        return int(s)
    except Exception:
        return None


def fetch_grade_code_remarks_map(cursor, academic_year_id, term_id, academic_level_ids, exam_name):
    """
    Return {(academic_level_id, grade_code): remark_text} for a given exam context.
    """
    ay = _coerce_int_or_none(academic_year_id)
    tid = _coerce_int_or_none(term_id)
    exn = (exam_name or '').strip()
    if not exn or not academic_level_ids:
        return {}
    lvl_ids = []
    for x in academic_level_ids or []:
        try:
            lvl_ids.append(int(x))
        except Exception:
            continue
    if not lvl_ids:
        return {}
    where = " WHERE academic_level_id IN ({}) AND exam_name = %s".format(",".join(["%s"] * len(lvl_ids)))
    params = list(lvl_ids) + [exn]
    if ay is not None:
        where += " AND academic_year_id = %s"
        params.append(ay)
    else:
        where += " AND academic_year_id IS NULL"
    if tid is not None:
        where += " AND term_id = %s"
        params.append(tid)
    else:
        where += " AND term_id IS NULL"
    out = {}
    try:
        cursor.execute(
            "SELECT academic_level_id, grade_code, remark_text FROM grade_code_remarks" + where,
            params,
        )
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                lid = r.get('academic_level_id')
                gc = (r.get('grade_code') or '').strip().upper()
                txt = (r.get('remark_text') or '').strip()
            else:
                lid = r[0] if len(r) > 0 else None
                gc = ((r[1] if len(r) > 1 else '') or '').strip().upper()
                txt = ((r[2] if len(r) > 2 else '') or '').strip()
            try:
                lid = int(lid)
            except Exception:
                continue
            if not gc:
                continue
            out[(lid, gc)] = txt
    except Exception as e:
        print(f"fetch_grade_code_remarks_map: {e}")
    return out


def sql_scaled_exam_mark_pct(sm_alias='sm', sub_alias='sub'):
    """SQL expression: student_marks.marks as 0–100 % (nearest whole number)."""
    return (
        f"ROUND((100 * CAST({sm_alias}.marks AS DECIMAL(16,8))) "
        f"/ COALESCE(NULLIF({sub_alias}.exam_total_marks, 0), 100))"
    )


def ensure_subject_exam_combination_tables(cursor):
    """Groups of subjects shown as one marks column (combined label); marks stored per member subject."""
    try:
        cursor.execute("SHOW TABLES LIKE 'subject_exam_combinations'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS subject_exam_combinations (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            print("OK: Created subject_exam_combinations table")
        cursor.execute("SHOW TABLES LIKE 'subject_exam_combination_members'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS subject_exam_combination_members (
                    combination_id INT NOT NULL,
                    subject_id INT NOT NULL,
                    sort_order INT NOT NULL DEFAULT 0,
                    PRIMARY KEY (combination_id, subject_id),
                    INDEX idx_subject_exam_combo_member_subject (subject_id)
                )
            """)
            print("OK: Created subject_exam_combination_members table")
        try:
            cursor.execute("SHOW COLUMNS FROM subject_exam_combinations LIKE 'totals_snapshot_json'")
            if not cursor.fetchone():
                cursor.execute(
                    """
                    ALTER TABLE subject_exam_combinations
                    ADD COLUMN totals_snapshot_json TEXT NULL
                    COMMENT 'JSON snapshot of subjects.exam_total_marks before proportional rescale to sum 100'
                    AFTER created_at
                    """
                )
                print("OK: Added subject_exam_combinations.totals_snapshot_json")
        except Exception as e:
            print(f"ensure_subject_exam_combination_tables (totals_snapshot_json): {e}")
        for col_name, col_def in (
            ('codes_snapshot_json', 'TEXT NULL'),
            ('combined_code', 'VARCHAR(64) NULL'),
            ('display_order', 'INT NULL'),
        ):
            try:
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c FROM information_schema.COLUMNS
                    WHERE TABLE_SCHEMA = DATABASE()
                      AND TABLE_NAME = 'subject_exam_combinations'
                      AND COLUMN_NAME = %s
                    """,
                    (col_name,),
                )
                chk = cursor.fetchone()
                n = chk.get('c', 0) if isinstance(chk, dict) else (chk[0] if chk else 0)
                if not int(n or 0):
                    cursor.execute(
                        f"ALTER TABLE subject_exam_combinations ADD COLUMN {col_name} {col_def}"
                    )
                    print(f"OK: Added subject_exam_combinations.{col_name}")
            except Exception as e:
                print(f"ensure_subject_exam_combination_tables ({col_name}): {e}")
    except Exception as e:
        print(f"ensure_subject_exam_combination_tables: {e}")


def ensure_subject_exam_combination_schema(cursor):
    """Tables + columns required for combined exam subject codes (safe to call on every request)."""
    ensure_subject_exam_combination_tables(cursor)
    ensure_subject_exam_display_order_columns(cursor)


def _exam_total_marks_snapshot_value(db_val):
    """JSON-safe prior exam_total_marks for restore (NULL stays None)."""
    if db_val is None:
        return None
    try:
        return round(float(db_val), 2)
    except (TypeError, ValueError):
        return None


def normalize_subject_totals_for_exam_combination(cursor, subject_ids_ordered):
    """
    Capture current subjects.exam_total_marks for a combination snapshot.
    This snapshot is stored in totals_snapshot_json and can be used on combination delete.

    IMPORTANT: We do NOT rescale or modify exam totals during combination creation.
    """
    if not subject_ids_ordered or len(subject_ids_ordered) < 2:
        return []
    placeholders = ','.join(['%s'] * len(subject_ids_ordered))
    cursor.execute(
        f"SELECT id, exam_total_marks FROM subjects WHERE id IN ({placeholders})",
        tuple(subject_ids_ordered),
    )
    rows = cursor.fetchall() or []
    by_id = {}
    for r in rows:
        sid = r.get('id') if isinstance(r, dict) else r[0]
        etm = r.get('exam_total_marks') if isinstance(r, dict) else r[1]
        by_id[int(sid)] = etm

    snapshot = []
    for sid in subject_ids_ordered:
        sid = int(sid)
        etm_before = by_id.get(sid)
        snapshot.append({
            'subject_id': sid,
            'exam_total_marks': _exam_total_marks_snapshot_value(etm_before),
        })
    return snapshot


def _subject_code_snapshot_value(db_val):
    """JSON-safe prior subject_code for restore (NULL/empty stays None)."""
    if db_val is None:
        return None
    s = str(db_val).strip()
    return s if s else None


def normalize_subject_codes_for_exam_combination(cursor, subject_ids_ordered):
    """Capture current subjects.subject_code for restore when a combination is removed."""
    if not subject_ids_ordered or len(subject_ids_ordered) < 2:
        return []
    placeholders = ','.join(['%s'] * len(subject_ids_ordered))
    cursor.execute(
        f"SELECT id, subject_code FROM subjects WHERE id IN ({placeholders})",
        tuple(subject_ids_ordered),
    )
    rows = cursor.fetchall() or []
    by_id = {}
    for r in rows:
        sid = r.get('id') if isinstance(r, dict) else r[0]
        sc = r.get('subject_code') if isinstance(r, dict) else r[1]
        by_id[int(sid)] = sc

    snapshot = []
    for sid in subject_ids_ordered:
        sid = int(sid)
        snapshot.append({
            'subject_id': sid,
            'subject_code': _subject_code_snapshot_value(by_id.get(sid)),
        })
    return snapshot


def restore_subject_codes_from_combination_snapshot(cursor, snapshot_json_str):
    """Apply stored subject_code per subject; ignores invalid entries."""
    if not snapshot_json_str:
        return
    try:
        entries = json.loads(snapshot_json_str)
    except (TypeError, ValueError, json.JSONDecodeError) as e:
        print(f"restore_subject_codes_from_combination_snapshot: bad JSON: {e}")
        return
    if not isinstance(entries, list):
        return
    for ent in entries:
        if not isinstance(ent, dict):
            continue
        sid = ent.get('subject_id')
        if sid is None:
            continue
        try:
            sid = int(sid)
        except (TypeError, ValueError):
            continue
        sc = ent.get('subject_code')
        if sc is None:
            cursor.execute(
                "UPDATE subjects SET subject_code = NULL WHERE id = %s",
                (sid,),
            )
        else:
            cursor.execute(
                "UPDATE subjects SET subject_code = %s WHERE id = %s",
                (str(sc).strip()[:64], sid),
            )


def auto_combined_subject_code_from_members(member_infos, sep='/'):
    """Build default combined code from member subject rows (id -> dict with subject_code/name)."""
    parts = []
    for info in member_infos or []:
        if not info:
            parts.append('—')
            continue
        cd = (info.get('subject_code') or '').strip()
        if not cd:
            cd = ((info.get('subject_name') or '')[:12] or '—')
        parts.append(cd if cd else '—')
    return sep.join(parts) if parts else ''


def normalize_combined_subject_code(raw, fallback=''):
    """Trim combined code; use fallback when empty; cap length."""
    code = (raw or '').strip()
    if not code:
        code = (fallback or '').strip()
    if not code:
        return None
    return code[:64]


def restore_subject_totals_from_combination_snapshot(cursor, snapshot_json_str):
    """Apply stored exam_total_marks per subject; ignores invalid entries."""
    if not snapshot_json_str:
        return
    try:
        entries = json.loads(snapshot_json_str)
    except (TypeError, ValueError, json.JSONDecodeError) as e:
        print(f"restore_subject_totals_from_combination_snapshot: bad JSON: {e}")
        return
    if not isinstance(entries, list):
        return
    for ent in entries:
        if not isinstance(ent, dict):
            continue
        sid = ent.get('subject_id')
        if sid is None:
            continue
        try:
            sid = int(sid)
        except (TypeError, ValueError):
            continue
        etm = ent.get('exam_total_marks')
        if etm is None:
            cursor.execute(
                "UPDATE subjects SET exam_total_marks = NULL WHERE id = %s",
                (sid,),
            )
        else:
            try:
                cursor.execute(
                    "UPDATE subjects SET exam_total_marks = %s WHERE id = %s",
                    (round(float(etm), 2), sid),
                )
            except (TypeError, ValueError):
                cursor.execute(
                    "UPDATE subjects SET exam_total_marks = NULL WHERE id = %s",
                    (sid,),
                )


def fetch_subject_exam_combinations(cursor):
    """Return [{'id', 'member_subject_ids', 'display_order', 'combined_code'?}, ...]."""
    ensure_subject_exam_combination_tables(cursor)
    ensure_subject_exam_display_order_columns(cursor)
    cursor.execute(
        """
        SELECT m.combination_id, m.subject_id, m.sort_order, c.display_order, c.combined_code
        FROM subject_exam_combination_members m
        INNER JOIN subject_exam_combinations c ON c.id = m.combination_id
        ORDER BY COALESCE(c.display_order, c.id) ASC, c.id ASC, m.sort_order ASC, m.subject_id ASC
        """
    )
    grouped = {}
    disp = {}
    codes = {}
    for row in cursor.fetchall() or []:
        cid = row.get('combination_id') if isinstance(row, dict) else row[0]
        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
        dord = row.get('display_order') if isinstance(row, dict) else (row[3] if len(row) > 3 else None)
        ccode = row.get('combined_code') if isinstance(row, dict) else (row[4] if len(row) > 4 else None)
        if cid is None or sid is None:
            continue
        cid = int(cid)
        sid = int(sid)
        grouped.setdefault(cid, []).append(sid)
        if dord is not None:
            try:
                disp[cid] = int(dord)
            except (TypeError, ValueError):
                pass
        if ccode and str(ccode).strip():
            codes[cid] = str(ccode).strip()
    def _combo_key(item):
        cid, mids = item
        return (disp.get(cid) if cid in disp else 10**9 + cid, cid)

    out = []
    for cid, mids in sorted(grouped.items(), key=_combo_key):
        row = {
            'id': cid,
            'member_subject_ids': mids,
            'display_order': disp.get(cid),
        }
        if codes.get(cid):
            row['combined_code'] = codes[cid]
        out.append(row)
    return out


EXAM_CONTEXT_SETTINGS_VERSION = 2


def ensure_exam_context_settings_table(cursor):
    """Per-exam frozen settings (grades, totals, combinations) when global settings change."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS exam_context_settings (
                id INT AUTO_INCREMENT PRIMARY KEY,
                exam_name VARCHAR(255) NOT NULL,
                academic_year_id INT NOT NULL,
                term_id INT NOT NULL,
                academic_level_id INT NOT NULL,
                settings_json LONGTEXT NOT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                UNIQUE KEY uniq_exam_context (
                    exam_name, academic_year_id, term_id, academic_level_id
                ),
                INDEX idx_exam_ctx_level (academic_level_id),
                INDEX idx_exam_ctx_year_term (academic_year_id, term_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
        """)
    except Exception as e:
        print(f"ensure_exam_context_settings_table: {e}")


def _parse_exam_context_key(exam_name, academic_year_id, term_id, academic_level_id):
    try:
        en = str(exam_name or '').strip().upper()
        ay = int(academic_year_id)
        tid = int(term_id)
        lid = int(academic_level_id)
        if not en or ay <= 0 or tid <= 0 or lid <= 0:
            return None
        return en, ay, tid, lid
    except (TypeError, ValueError):
        return None


def _exam_context_dict(exam_name, academic_year_id, term_id, academic_level_id=None):
    key = _parse_exam_context_key(exam_name, academic_year_id, term_id, academic_level_id)
    if not key:
        return None
    return {
        'exam_name': key[0],
        'academic_year_id': key[1],
        'term_id': key[2],
        'academic_level_id': key[3],
    }


def _fetch_live_subject_exam_combinations_full(cursor):
    """Live combinations including combined_code (for snapshots and display)."""
    ensure_subject_exam_combination_tables(cursor)
    ensure_subject_exam_display_order_columns(cursor)
    cursor.execute(
        """
        SELECT m.combination_id, m.subject_id, m.sort_order,
               c.display_order, c.combined_code
        FROM subject_exam_combination_members m
        INNER JOIN subject_exam_combinations c ON c.id = m.combination_id
        ORDER BY COALESCE(c.display_order, c.id) ASC, c.id ASC,
                 m.sort_order ASC, m.subject_id ASC
        """
    )
    grouped = {}
    disp = {}
    codes = {}
    for row in cursor.fetchall() or []:
        cid = row.get('combination_id') if isinstance(row, dict) else row[0]
        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
        dord = row.get('display_order') if isinstance(row, dict) else (row[3] if len(row) > 3 else None)
        ccode = row.get('combined_code') if isinstance(row, dict) else (row[4] if len(row) > 4 else None)
        if cid is None or sid is None:
            continue
        cid = int(cid)
        sid = int(sid)
        grouped.setdefault(cid, []).append(sid)
        if dord is not None:
            try:
                disp[cid] = int(dord)
            except (TypeError, ValueError):
                pass
        if ccode:
            codes[cid] = str(ccode).strip()

    def _combo_key(item):
        cid, mids = item
        return (disp.get(cid) if cid in disp else 10**9 + cid, cid)

    out = []
    for cid, mids in sorted(grouped.items(), key=_combo_key):
        row = {
            'id': cid,
            'member_subject_ids': mids,
            'display_order': disp.get(cid),
        }
        if codes.get(cid):
            row['combined_code'] = codes[cid]
        out.append(row)
    return out


def capture_live_exam_context_settings(cursor):
    """Snapshot current school-wide exam display and grading settings."""
    default_grade_bands, subject_grade_bands, class_grade_bands = load_grade_bands_from_db(cursor)
    combinations = _fetch_live_subject_exam_combinations_full(cursor)
    subject_exam_totals = {}
    subject_exam_display_order = {}
    try:
        cursor.execute("""
            SELECT id, exam_total_marks, exam_display_order
            FROM subjects
            WHERE COALESCE(status, 'active') = 'active'
        """)
        for row in cursor.fetchall() or []:
            sid = int(row.get('id') if isinstance(row, dict) else row[0])
            etm = row.get('exam_total_marks') if isinstance(row, dict) else (row[1] if len(row) > 1 else None)
            edo = row.get('exam_display_order') if isinstance(row, dict) else (row[2] if len(row) > 2 else None)
            if etm is not None:
                try:
                    subject_exam_totals[str(sid)] = round(float(etm), 2)
                except (TypeError, ValueError):
                    pass
            if edo is not None:
                try:
                    subject_exam_display_order[str(sid)] = int(edo)
                except (TypeError, ValueError):
                    pass
    except Exception as e:
        print(f"capture_live_exam_context_settings subject totals: {e}")

    subject_id_to_group_category = {}
    base_category_order = []
    academic_level_combinations = []
    try:
        cursor.execute("""
            SELECT id FROM subjects WHERE COALESCE(status, 'active') = 'active'
        """)
        all_sids = []
        for row in cursor.fetchall() or []:
            try:
                all_sids.append(int(row.get('id') if isinstance(row, dict) else row[0]))
            except (TypeError, ValueError):
                continue
        if all_sids:
            for sid, gc in fetch_subject_id_to_exam_group_category(cursor, all_sids).items():
                subject_id_to_group_category[str(int(sid))] = gc
        base_category_order = fetch_base_academic_level_category_order(cursor)
        academic_level_combinations = fetch_academic_level_combinations(cursor)
    except Exception as e:
        print(f"capture_live_exam_context_settings column meta: {e}")

    return {
        'version': EXAM_CONTEXT_SETTINGS_VERSION,
        'default_grade_bands': default_grade_bands,
        'class_grade_bands': {str(k): v for k, v in (class_grade_bands or {}).items()},
        'subject_grade_bands': {str(k): v for k, v in (subject_grade_bands or {}).items()},
        'subject_combinations': combinations,
        'subject_exam_totals': subject_exam_totals,
        'subject_exam_display_order': subject_exam_display_order,
        'subject_id_to_group_category': subject_id_to_group_category,
        'base_category_order': base_category_order,
        'academic_level_combinations': academic_level_combinations,
    }


def get_exam_context_settings_snapshot(cursor, exam_name, academic_year_id, term_id, academic_level_id):
    """Return parsed settings dict for one exam context, or None if not frozen."""
    key = _parse_exam_context_key(exam_name, academic_year_id, term_id, academic_level_id)
    if not key:
        return None
    ensure_exam_context_settings_table(cursor)
    try:
        cursor.execute(
            """
            SELECT settings_json
            FROM exam_context_settings
            WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
              AND academic_level_id = %s
            LIMIT 1
            """,
            key,
        )
        row = cursor.fetchone()
        if not row:
            return None
        raw = row.get('settings_json') if isinstance(row, dict) else row[0]
        if not raw:
            return None
        data = json.loads(raw)
        return data if isinstance(data, dict) else None
    except Exception as e:
        print(f"get_exam_context_settings_snapshot: {e}")
        return None


def _is_registered_current_exam_context(
    exam_name, academic_year_id, term_id, registered_current, exam_type=None,
):
    """True when this exam group is the school-wide registered current exam."""
    if not registered_current:
        return False
    key = _parse_exam_context_key(exam_name, academic_year_id, term_id, 1)
    if not key:
        return False
    reg_name = (registered_current.get('exam_name') or '').strip().upper()
    try:
        reg_ay = int(registered_current.get('academic_year_id') or 0)
        reg_tid = int(registered_current.get('term_id') or 0)
    except (TypeError, ValueError):
        return False
    if key[0] != reg_name or key[1] != reg_ay or key[2] != reg_tid:
        return False
    reg_type = registered_current.get('exam_type')
    if reg_type is None:
        return True
    want = (exam_type or '').strip().upper()
    return want == str(reg_type or '').strip().upper()


def _should_use_live_exam_settings(
    exam_name, academic_year_id, term_id, registered_current, exam_type=None,
):
    """Registered current exam always uses the latest global settings."""
    return _is_registered_current_exam_context(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    )


def _insert_exam_context_snapshot_rows(cursor, contexts, snapshot_json, registered_current=None):
    """Insert snapshots for exam contexts that do not already have one."""
    created = 0
    for row in contexts or []:
        if isinstance(row, dict):
            en = row.get('exam_name')
            ay = row.get('academic_year_id')
            tid = row.get('term_id')
            lid = row.get('academic_level_id')
            et = row.get('exam_type')
        else:
            en = row[0] if len(row) > 0 else None
            ay = row[1] if len(row) > 1 else None
            tid = row[2] if len(row) > 2 else None
            lid = row[3] if len(row) > 3 else None
            et = row[4] if len(row) > 4 else None
        key = _parse_exam_context_key(en, ay, tid, lid)
        if not key:
            continue
        if _should_use_live_exam_settings(en, ay, tid, registered_current, et):
            continue
        cursor.execute(
            """
            SELECT id FROM exam_context_settings
            WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
              AND academic_level_id = %s
            LIMIT 1
            """,
            key,
        )
        if cursor.fetchone():
            continue
        cursor.execute(
            """
            INSERT INTO exam_context_settings
                (exam_name, academic_year_id, term_id, academic_level_id, settings_json)
            VALUES (%s, %s, %s, %s, %s)
            """,
            key + (snapshot_json,),
        )
        created += 1
    return created


def freeze_exam_contexts_with_marks_for_group(
    cursor, exam_name, academic_year_id, term_id, exam_type=None, registered_current=None,
):
    """Freeze all class contexts that have marks for one exam group (name + year + term)."""
    ensure_exam_context_settings_table(cursor)
    en = (exam_name or '').strip().upper()
    try:
        ay = int(academic_year_id)
        tid = int(term_id)
    except (TypeError, ValueError):
        return 0
    if not en or ay <= 0 or tid <= 0:
        return 0
    if _should_use_live_exam_settings(en, ay, tid, registered_current, exam_type):
        return 0
    snapshot_json = json.dumps(capture_live_exam_context_settings(cursor))
    params = [en, ay, tid]
    type_sql = ''
    if exam_type is not None and str(exam_type).strip() != '':
        type_sql = " AND UPPER(TRIM(COALESCE(e.exam_type, ''))) = %s "
        params.append(str(exam_type).strip().upper())
    cursor.execute(
        f"""
        SELECT DISTINCT e.exam_name, e.academic_year_id, e.term_id, e.academic_level_id,
               e.exam_type
        FROM student_marks sm
        INNER JOIN exams e ON e.id = sm.exam_id
        WHERE UPPER(TRIM(e.exam_name)) = %s
          AND e.academic_year_id = %s
          AND e.term_id = %s
          {type_sql}
        """,
        tuple(params),
    )
    return _insert_exam_context_snapshot_rows(
        cursor, cursor.fetchall() or [], snapshot_json, registered_current,
    )


def ensure_exam_context_snapshot_if_missing(
    cursor, exam_name, academic_year_id, term_id, academic_level_id,
    registered_current=None, exam_type=None,
):
    """Snapshot settings for a past exam context (e.g. first mark save or lock)."""
    if _should_use_live_exam_settings(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    ):
        return False
    key = _parse_exam_context_key(exam_name, academic_year_id, term_id, academic_level_id)
    if not key:
        return False
    ensure_exam_context_settings_table(cursor)
    cursor.execute(
        """
        SELECT id FROM exam_context_settings
        WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
          AND academic_level_id = %s
        LIMIT 1
        """,
        key,
    )
    if cursor.fetchone():
        return False
    snapshot_json = json.dumps(capture_live_exam_context_settings(cursor))
    cursor.execute(
        """
        INSERT INTO exam_context_settings
            (exam_name, academic_year_id, term_id, academic_level_id, settings_json)
        VALUES (%s, %s, %s, %s, %s)
        """,
        key + (snapshot_json,),
    )
    return True


def freeze_exam_context_settings_before_global_change(cursor):
    """
    Before changing global exam settings: freeze current settings for each exam context
    that already has student marks but no snapshot yet.
    Skips the school registered current exam — that exam keeps using live settings.
    Returns the number of new snapshots created.
    """
    ensure_exam_context_settings_table(cursor)
    registered_current = load_registered_current_exam_dict(cursor)
    snapshot_json = json.dumps(capture_live_exam_context_settings(cursor))
    try:
        cursor.execute("""
            SELECT DISTINCT e.exam_name, e.academic_year_id, e.term_id, e.academic_level_id,
                   e.exam_type
            FROM student_marks sm
            INNER JOIN exams e ON e.id = sm.exam_id
        """)
        contexts = cursor.fetchall() or []
    except Exception as e:
        print(f"freeze_exam_context_settings_before_global_change list: {e}")
        return 0

    return _insert_exam_context_snapshot_rows(
        cursor, contexts, snapshot_json, registered_current,
    )


def _exam_settings_freeze_suffix(frozen_count, cursor=None):
    """User-facing note when prior exams keep frozen settings."""
    try:
        n = int(frozen_count or 0)
    except (TypeError, ValueError):
        n = 0
    if n <= 0:
        return ''
    has_registered_current = True
    if cursor is not None:
        try:
            has_registered_current = bool(load_registered_current_exam_dict(cursor))
        except Exception:
            has_registered_current = True
    word = 'exam' if n == 1 else 'exams'
    if has_registered_current:
        return (
            f' {n} past {word} with marks will keep their previous settings. '
            'The registered current exam uses the new settings.'
        )
    return (
        f' {n} {word} with marks were frozen at the previous settings. '
        'Set the registered current exam on Exam Evaluation before your next settings change '
        'so only the active exam picks up new grading rules.'
    )


def _grade_band_maps_from_snapshot(snapshot):
    """Convert snapshot JSON to runtime band maps (int keys for class/subject)."""
    if not snapshot:
        return None
    default_grade_bands = snapshot.get('default_grade_bands') or []
    subject_grade_bands = {}
    for k, bands in (snapshot.get('subject_grade_bands') or {}).items():
        try:
            subject_grade_bands[int(k)] = bands
        except (TypeError, ValueError):
            continue
    class_grade_bands = {}
    for k, bands in (snapshot.get('class_grade_bands') or {}).items():
        try:
            class_grade_bands[int(k)] = bands
        except (TypeError, ValueError):
            continue
    return default_grade_bands, subject_grade_bands, class_grade_bands


def load_grade_bands_for_exam_context(
    cursor, exam_name=None, academic_year_id=None, term_id=None, academic_level_id=None,
    registered_current=None, exam_type=None,
):
    """Grade bands for an exam: live for registered current; else frozen snapshot when present."""
    if _should_use_live_exam_settings(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    ):
        return load_grade_bands_from_db(cursor)
    snap = None
    if exam_name and academic_year_id and term_id and academic_level_id:
        snap = get_exam_context_settings_snapshot(
            cursor, exam_name, academic_year_id, term_id, academic_level_id,
        )
    parsed = _grade_band_maps_from_snapshot(snap)
    if parsed:
        return parsed
    return load_grade_bands_from_db(cursor)


def fetch_subject_exam_combinations_for_context(
    cursor, exam_name=None, academic_year_id=None, term_id=None, academic_level_id=None,
    registered_current=None, exam_type=None,
):
    """Subject combinations for an exam context (snapshot or live)."""
    if _should_use_live_exam_settings(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    ):
        return _fetch_live_subject_exam_combinations_full(cursor)
    snap = None
    if exam_name and academic_year_id and term_id and academic_level_id:
        snap = get_exam_context_settings_snapshot(
            cursor, exam_name, academic_year_id, term_id, academic_level_id,
        )
    if snap and snap.get('subject_combinations') is not None:
        return snap.get('subject_combinations') or []
    combos = _fetch_live_subject_exam_combinations_full(cursor)
    for c in combos:
        if 'combined_code' not in c:
            c['combined_code'] = None
    return combos


def subject_exam_total_for_context(
    cursor, subject_id, exam_name=None, academic_year_id=None, term_id=None,
    academic_level_id=None, live_fallback=None, registered_current=None, exam_type=None,
):
    """Exam total for a subject: snapshot value when exam is frozen, else live."""
    if _should_use_live_exam_settings(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    ):
        return live_fallback
    snap = None
    if exam_name and academic_year_id and term_id and academic_level_id:
        snap = get_exam_context_settings_snapshot(
            cursor, exam_name, academic_year_id, term_id, academic_level_id,
        )
    if snap:
        totals = snap.get('subject_exam_totals') or {}
        val = totals.get(str(int(subject_id)))
        if val is not None:
            return val
    return live_fallback


def _exam_context_snapshot_for_display(
    cursor, exam_name=None, academic_year_id=None, term_id=None, academic_level_id=None,
    registered_current=None, exam_type=None,
):
    """Frozen settings dict for an exam context, or None when live settings apply."""
    if _should_use_live_exam_settings(
        exam_name, academic_year_id, term_id, registered_current, exam_type,
    ):
        return None
    if exam_name and academic_year_id and term_id and academic_level_id:
        return get_exam_context_settings_snapshot(
            cursor, exam_name, academic_year_id, term_id, academic_level_id,
        )
    return None


def fetch_academic_level_combinations_for_context(
    cursor, exam_name=None, academic_year_id=None, term_id=None, academic_level_id=None,
    registered_current=None, exam_type=None,
):
    """Combined class groups for reports/analytics: frozen for past exams, live for current."""
    snap = _exam_context_snapshot_for_display(
        cursor, exam_name, academic_year_id, term_id, academic_level_id,
        registered_current, exam_type,
    )
    if snap is not None and snap.get('academic_level_combinations') is not None:
        return snap.get('academic_level_combinations') or []
    return fetch_academic_level_combinations(cursor)


def sort_subjects_list_for_exam_columns_for_context(
    cursor, subjects, exam_name=None, academic_year_id=None, term_id=None,
    academic_level_id=None, registered_current=None, exam_type=None,
    force_group_category=None,
):
    """
    Sort subject columns using frozen exam-subject-settings when exam is not current.
    Mutates subjects in place (same as sort_subjects_list_for_exam_columns).
    """
    snap = _exam_context_snapshot_for_display(
        cursor, exam_name, academic_year_id, term_id, academic_level_id,
        registered_current, exam_type,
    )
    forced = (force_group_category or '').strip() or None
    if not snap:
        return sort_subjects_list_for_exam_columns(
            cursor, subjects, force_group_category=forced,
        )

    edo_map = snap.get('subject_exam_display_order') or {}
    if snap.get('version', 1) < 2 or 'subject_id_to_group_category' not in snap:
        id_to_gc, section_order = sort_subjects_list_for_exam_columns(
            cursor, subjects, force_group_category=forced,
        )
        if edo_map:
            for s in subjects or []:
                try:
                    sk = str(int(s.get('id')))
                except (TypeError, ValueError):
                    continue
                if sk in edo_map:
                    s['exam_display_order'] = edo_map[sk]
            subjects.sort(key=lambda s: exam_subject_column_sort_key(s, section_order))
        return id_to_gc, section_order

    gc_map = snap.get('subject_id_to_group_category') or {}
    base = snap.get('base_category_order') or fetch_base_academic_level_category_order(cursor)
    id_to_gc = {}
    for s in subjects or []:
        try:
            sid = int(s.get('id'))
        except (TypeError, ValueError):
            s['group_category'] = forced or 'Uncategorized'
            continue
        if sid <= 0:
            s['group_category'] = forced or 'Uncategorized'
            continue
        sk = str(sid)
        if sk in edo_map:
            s['exam_display_order'] = edo_map[sk]
        if forced:
            id_to_gc[sid] = forced
            s['group_category'] = forced
        else:
            id_to_gc[sid] = gc_map.get(sk) or 'Uncategorized'
            s['group_category'] = id_to_gc[sid]
    if not forced:
        missing = [
            s.get('id') for s in (subjects or [])
            if int(s.get('id') or 0) > 0 and int(s.get('id')) not in id_to_gc
        ]
        if missing:
            for sid, gc in fetch_subject_id_to_exam_group_category(cursor, missing).items():
                id_to_gc[int(sid)] = gc
        for s in subjects or []:
            try:
                sid = int(s.get('id'))
                if sid > 0:
                    s['group_category'] = id_to_gc.get(sid, s.get('group_category') or 'Uncategorized')
            except (TypeError, ValueError):
                pass
        section_order = build_exam_subject_section_order(
            set(id_to_gc.values()) or {'Uncategorized'}, base,
        )
    else:
        section_order = [forced]
    subjects.sort(key=lambda s: exam_subject_column_sort_key(s, section_order))
    return id_to_gc, section_order


def ensure_academic_level_combination_tables(cursor):
    """Groups of academic levels treated as one combined level in reports and analytics."""
    try:
        cursor.execute("SHOW TABLES LIKE 'academic_level_combinations'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS academic_level_combinations (
                    id INT AUTO_INCREMENT PRIMARY KEY,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
            """)
            print("OK: Created academic_level_combinations table")
        cursor.execute("SHOW TABLES LIKE 'academic_level_combination_members'")
        if not cursor.fetchone():
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS academic_level_combination_members (
                    combination_id INT NOT NULL,
                    academic_level_id INT NOT NULL,
                    sort_order INT NOT NULL DEFAULT 0,
                    PRIMARY KEY (combination_id, academic_level_id),
                    INDEX idx_academic_level_combo_member_level (academic_level_id)
                )
            """)
            print("OK: Created academic_level_combination_members table")
    except Exception as e:
        print(f"ensure_academic_level_combination_tables: {e}")


def fetch_academic_level_combinations(cursor):
    """Return [{'id': combo_id, 'member_level_ids': [..ordered..]}, ...]."""
    ensure_academic_level_combination_tables(cursor)
    cursor.execute(
        """
        SELECT m.combination_id, m.academic_level_id, m.sort_order
        FROM academic_level_combination_members m
        INNER JOIN academic_level_combinations c ON c.id = m.combination_id
        ORDER BY c.id ASC, m.sort_order ASC, m.academic_level_id ASC
        """
    )
    grouped = {}
    for row in cursor.fetchall() or []:
        cid = row.get('combination_id') if isinstance(row, dict) else row[0]
        lid = row.get('academic_level_id') if isinstance(row, dict) else row[1]
        if cid is None or lid is None:
            continue
        grouped.setdefault(int(cid), []).append(int(lid))
    return [{'id': cid, 'member_level_ids': mids} for cid, mids in sorted(grouped.items())]


def build_academic_levels_picker_grouping(academic_levels, cursor):
    """
    Group active academic levels by category and surface combined groups
    (same layout as curriculum coordinator combined-academic-levels).
    Returns (levels_by_category, level_combinations_display, member_level_ids).
    """
    level_meta = {}
    for level in academic_levels or []:
        try:
            lid = int(level.get('id'))
        except (TypeError, ValueError):
            continue
        level_meta[lid] = level

    member_level_ids = set()
    level_combinations_display = []
    try:
        combos = fetch_academic_level_combinations(cursor)
        for combo in combos or []:
            mids = [int(x) for x in (combo.get('member_level_ids') or [])]
            for mid in mids:
                member_level_ids.add(mid)
            names = [
                (level_meta.get(mid, {}).get('level_name') or '—').strip()
                for mid in mids
            ]
            cats = sorted({
                (level_meta.get(mid, {}).get('level_category') or 'Uncategorized').strip()
                or 'Uncategorized'
                for mid in mids
            })
            level_combinations_display.append({
                'id': int(combo['id']),
                'label_name': ' / '.join(names),
                'categories': ', '.join(cats),
                'member_level_ids': mids,
                'member_count': len(mids),
            })
    except Exception as e:
        print(f"build_academic_levels_picker_grouping combinations: {e}")

    by_cat = {}
    for level in academic_levels or []:
        try:
            lid = int(level.get('id'))
        except (TypeError, ValueError):
            continue
        if lid in member_level_ids:
            continue
        cat = (level.get('level_category') or '').strip() or 'Uncategorized'
        by_cat.setdefault(cat, []).append({
            'id': lid,
            'level_name': (level.get('level_name') or '').strip(),
            'level_code': (level.get('level_code') or '').strip(),
            'level_category': cat,
        })

    levels_by_category = [
        {
            'category': cat,
            'levels': sorted(lvls, key=lambda x: (x.get('level_name') or '').lower()),
        }
        for cat, lvls in sorted(by_cat.items(), key=lambda x: x[0].lower())
    ]
    return levels_by_category, level_combinations_display, member_level_ids


def merge_subjects_with_exam_combinations(subjects, combinations, id_to_gc=None, section_order=None):
    """
    Replace member subjects with one synthetic column per applicable combination (view-only sheets).
    Synthetic row uses negative id -combo_id. Combined % is computed live as
    Σ(pct×max)/Σ(max) from each member's exam_total_marks — not entered as a single cell.
    Editors (teachers/principals) use expand_teacher_marks_sheet_subjects instead so each
    paper keeps its own out-of and the Σ column stays read-only.
    """
    if not subjects:
        return subjects
    if not combinations:
        return subjects

    def _sub_sort_key(s):
        sid = int(s['id'])
        eo = s.get('exam_display_order')
        try:
            eo_n = int(eo)
        except (TypeError, ValueError):
            eo_n = None
        if eo_n is None:
            return (1, 10**9 + sid, str(s.get('subject_name') or '').lower(), sid)
        return (0, eo_n, str(s.get('subject_name') or '').lower(), sid)

    if id_to_gc is not None and section_order is not None:
        def _cat_key(s):
            sc = dict(s)
            try:
                sid = int(sc['id'])
                if sid > 0:
                    sc.setdefault('group_category', id_to_gc.get(sid, 'Uncategorized'))
            except (TypeError, ValueError, KeyError):
                sc.setdefault('group_category', 'Uncategorized')
            return exam_subject_column_sort_key(sc, section_order)

        subjects = sorted((dict(s) for s in subjects), key=_cat_key)
    else:
        subjects = sorted((dict(s) for s in subjects), key=_sub_sort_key)
    by_id = {int(s['id']): dict(s) for s in subjects}
    original_order = [int(s['id']) for s in subjects]
    id_set = set(original_order)
    subject_to_combo = {}
    combo_members_by_id = {}
    combo_code_by_id = {}
    for c in combinations:
        mids = [int(x) for x in (c.get('member_subject_ids') or [])]
        if len(mids) < 2:
            continue
        if not all(m in id_set for m in mids):
            continue
        cid = int(c['id'])
        combo_members_by_id[cid] = mids
        ccode = (c.get('combined_code') or '').strip()
        if ccode:
            combo_code_by_id[cid] = ccode
        conflict = False
        for mid in mids:
            if mid in subject_to_combo:
                conflict = True
                break
        if conflict:
            continue
        for mid in mids:
            subject_to_combo[mid] = cid

    sep = '/'
    out = []
    consumed = set()
    for sid in original_order:
        if sid in consumed:
            continue
        if sid not in subject_to_combo:
            out.append(by_id[sid])
            continue
        cid = subject_to_combo[sid]
        mids = combo_members_by_id.get(cid)
        if not mids:
            out.append(by_id[sid])
            continue
        anchor = min(mids, key=lambda m: original_order.index(m))
        if sid != anchor:
            continue
        names = sep.join((by_id[mid].get('subject_name') or '').strip() or '—' for mid in mids)
        code_parts = []
        for mid in mids:
            cd = (by_id[mid].get('subject_code') or '').strip()
            code_parts.append(cd if cd else ((by_id[mid].get('subject_name') or '')[:12] or '—'))
        custom_code = combo_code_by_id.get(cid, '')
        combo_ord_vals = []
        for mid in mids:
            eo_m = by_id.get(mid, {}).get('exam_display_order')
            try:
                combo_ord_vals.append(int(eo_m))
            except (TypeError, ValueError):
                combo_ord_vals.append(10**9 + int(mid))
        combo_row = {
            'id': -cid,
            'subject_name': names,
            'subject_code': custom_code if custom_code else sep.join(code_parts),
            'description': '',
            'status': 'active',
            'exam_total_marks': 100.0,
            'combination_id': cid,
            'member_subject_ids': list(mids),
            'exam_display_order': min(combo_ord_vals) if combo_ord_vals else (10**9 + cid),
        }
        if id_to_gc is not None and section_order is not None:
            combo_row['group_category'] = _combo_exam_group_category(mids, id_to_gc, section_order)
        out.append(combo_row)
        for mid in mids:
            consumed.add(mid)
    return out


def _teacher_marks_subject_ids_for_load(teacher_subject_ids, combinations):
    """Subject IDs whose marks to load: teacher allocations plus combo partners."""
    base = {int(x) for x in (teacher_subject_ids or []) if x is not None}
    try:
        base = {int(x) for x in base}
    except (TypeError, ValueError):
        base = set()
    if not base:
        return []
    out = set(base)
    for c in combinations or []:
        mids = []
        for x in c.get('member_subject_ids') or []:
            try:
                mids.append(int(x))
            except (TypeError, ValueError):
                continue
        if len(mids) < 2:
            continue
        if any(m in base for m in mids):
            out.update(mids)
    return sorted(out)


def expand_teacher_marks_sheet_subjects(subjects_flat, combinations, teacher_subject_ids, cursor):
    """
    Teachers see every paper in a combined exam group they teach, plus a live total column.
    Partner subjects are read-only; only allocated subjects are editable.
    """
    if not subjects_flat:
        return [], {}, set()

    teacher_set = set()
    for x in teacher_subject_ids or []:
        try:
            teacher_set.add(int(x))
        except (TypeError, ValueError):
            continue

    by_id = {}
    for s in subjects_flat:
        try:
            by_id[int(s['id'])] = dict(s)
        except (TypeError, ValueError):
            continue

    relevant = []
    member_to_combo = {}
    all_combo_members = set()
    for c in combinations or []:
        mids = []
        for x in c.get('member_subject_ids') or []:
            try:
                mids.append(int(x))
            except (TypeError, ValueError):
                continue
        if len(mids) < 2:
            continue
        if not any(m in teacher_set for m in mids):
            continue
        cid = int(c['id'])
        relevant.append({
            'id': cid,
            'member_subject_ids': mids,
            'combined_code': (c.get('combined_code') or '').strip(),
        })
        for mid in mids:
            member_to_combo[mid] = cid
            all_combo_members.add(mid)

    if not relevant:
        editable = {int(s['id']) for s in subjects_flat if int(s.get('id') or 0) in teacher_set}
        return list(subjects_flat), {}, editable

    missing = [mid for mid in all_combo_members if mid not in by_id]
    if missing:
        try:
            ph = ','.join(['%s'] * len(missing))
            cursor.execute(
                f"""
                SELECT id, subject_name, subject_code, description, status, exam_total_marks, exam_display_order
                FROM subjects
                WHERE id IN ({ph}) AND COALESCE(status, 'active') = 'active'
                """,
                tuple(missing),
            )
            for row in cursor.fetchall() or []:
                sid = int(row.get('id') if isinstance(row, dict) else row[0])
                by_id[sid] = {
                    'id': sid,
                    'subject_name': row.get('subject_name') if isinstance(row, dict) else row[1],
                    'subject_code': row.get('subject_code') if isinstance(row, dict) else row[2],
                    'description': row.get('description') if isinstance(row, dict) else row[3],
                    'status': row.get('status') if isinstance(row, dict) else row[4],
                    'exam_total_marks': row.get('exam_total_marks') if isinstance(row, dict) else (row[5] if len(row) > 5 else None),
                    'exam_display_order': row.get('exam_display_order') if isinstance(row, dict) else (row[6] if len(row) > 6 else None),
                }
        except Exception as e:
            print(f"expand_teacher_marks_sheet_subjects fetch: {e}")

    combo_by_id = {c['id']: c for c in relevant}
    flat_order = [int(s['id']) for s in subjects_flat]
    for mid in all_combo_members:
        if mid not in flat_order:
            flat_order.append(mid)

    out = []
    added_combos = set()
    added_ids = set()
    combination_column_members = {}
    sep = '/'

    for sid in flat_order:
        if sid in all_combo_members:
            cid = member_to_combo.get(sid)
            if cid is None or cid in added_combos:
                continue
            added_combos.add(cid)
            combo = combo_by_id[cid]
            mids = list(combo['member_subject_ids'])
            mids.sort(key=lambda m: flat_order.index(m) if m in flat_order else 9999)
            code_parts = []
            names = []
            for mid in mids:
                info = by_id.get(mid) or {}
                names.append((info.get('subject_name') or '').strip() or '—')
                cd = (info.get('subject_code') or '').strip()
                code_parts.append(cd if cd else ((info.get('subject_name') or '')[:12] or '—'))
                row = dict(info)
                row.update({
                    'id': mid,
                    'combination_id': cid,
                    'combination_role': 'member',
                    'member_subject_ids': mids,
                    'is_teacher_editable': mid in teacher_set,
                })
                out.append(row)
                added_ids.add(mid)
            custom_code = combo.get('combined_code') or ''
            total_row = {
                'id': -cid,
                'subject_name': sep.join(names),
                'subject_code': custom_code if custom_code else sep.join(code_parts),
                'description': '',
                'status': 'active',
                'exam_total_marks': 100.0,
                'combination_id': cid,
                'combination_role': 'total',
                'member_subject_ids': mids,
                'is_teacher_editable': False,
            }
            out.append(total_row)
            combination_column_members[str(-cid)] = mids
            added_ids.add(-cid)
        elif sid not in added_ids and sid in by_id:
            row = dict(by_id[sid])
            row['is_teacher_editable'] = sid in teacher_set
            out.append(row)
            added_ids.add(sid)

    return out, combination_column_members, teacher_set


def fetch_base_academic_level_category_order(cursor):
    """Ordered list of distinct level_category values (same ordering intent as exam-subject-settings)."""
    base_category_order = []
    try:
        cursor.execute(
            """
            SELECT DISTINCT al.level_category AS lc
            FROM academic_levels al
            WHERE COALESCE(al.level_status, 'active') = 'active'
              AND TRIM(COALESCE(al.level_category, '')) <> ''
            ORDER BY al.level_category ASC
            """
        )
        for cr in cursor.fetchall() or []:
            lc = cr.get('lc') if isinstance(cr, dict) else cr[0]
            if lc and str(lc).strip():
                base_category_order.append(str(lc).strip())
    except Exception:
        base_category_order = []
    return base_category_order


def build_exam_subject_section_order(keys_set, base_category_order):
    """Order category *tabs* like exam-subject-settings: known school order first, then alpha, Uncategorized last."""
    keys_set = set(keys_set or [])
    section_order = [k for k in (base_category_order or []) if k in keys_set]
    section_order.extend(
        sorted(k for k in keys_set if k not in section_order and k != 'Uncategorized')
    )
    if 'Uncategorized' in keys_set:
        section_order.append('Uncategorized')
    return section_order


def fetch_subject_id_to_exam_group_category(cursor, subject_ids):
    """Map subject id -> group_category using the same rules as exam_subject_settings."""
    normalized_ids = []
    seen = set()
    for x in subject_ids or []:
        try:
            sid = int(x)
        except (TypeError, ValueError):
            continue
        if sid > 0 and sid not in seen:
            seen.add(sid)
            normalized_ids.append(sid)
    if not normalized_ids:
        return {}
    base_category_order = fetch_base_academic_level_category_order(cursor)
    placeholders = ','.join(['%s'] * len(normalized_ids))
    cursor.execute(
        f"""
        SELECT s.id,
               GROUP_CONCAT(DISTINCT al.level_category ORDER BY al.level_category SEPARATOR '|') AS cat_blob
        FROM subjects s
        LEFT JOIN subject_academic_levels sal ON sal.subject_id = s.id
        LEFT JOIN academic_levels al ON al.id = sal.academic_level_id
            AND COALESCE(al.level_status, 'active') = 'active'
        WHERE s.id IN ({placeholders})
        GROUP BY s.id
        """,
        tuple(normalized_ids),
    )
    id_to_gc = {}
    for row in cursor.fetchall() or []:
        sid = int(row.get('id') if isinstance(row, dict) else row[0])
        cat_blob = row.get('cat_blob') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
        seen_c = set()
        level_categories = []
        for part in str(cat_blob or '').split('|'):
            c = part.strip()
            if c and c not in seen_c:
                seen_c.add(c)
                level_categories.append(c)
        assigned = None
        for c in base_category_order:
            if c in seen_c:
                assigned = c
                break
        if assigned is None:
            if level_categories:
                assigned = sorted(level_categories)[0]
            else:
                assigned = 'Uncategorized'
        id_to_gc[sid] = assigned
    return id_to_gc


def _coerce_exam_display_order(eo, default=1000000000):
    """Parse exam_display_order from DB/JSON (int, Decimal, '10', '10.0')."""
    if eo is None or eo == '':
        return default
    try:
        return int(eo)
    except (TypeError, ValueError):
        pass
    try:
        return int(float(eo))
    except (TypeError, ValueError):
        return default


def exam_subject_column_sort_key(subject_row, section_order):
    """Sort tuple: category section, exam_display_order, name, id (matches marks sheet / reports)."""
    gc = (subject_row or {}).get('group_category') or 'Uncategorized'
    try:
        cat_i = section_order.index(gc)
    except ValueError:
        cat_i = len(section_order)
    eo_n = _coerce_exam_display_order((subject_row or {}).get('exam_display_order'))
    try:
        sid = int((subject_row or {}).get('id'))
    except (TypeError, ValueError):
        sid = 0
    name = str((subject_row or {}).get('subject_name') or '').lower()
    return (cat_i, eo_n, name, sid)


def sort_subjects_list_for_exam_columns(cursor, subjects, force_group_category=None):
    """
    Mutates subjects (each dict must have 'id'): sets group_category, sorts by
    exam-subject-settings category order then exam_display_order.
    When force_group_category is set (per-class marks sheet / reports), all subjects
    use that category so the saved exam_display_order sequence is preserved.
    Returns (id_to_gc, section_order).
    """
    if not subjects:
        return {}, []
    forced = (force_group_category or '').strip() or None
    if forced:
        id_to_gc = {}
        for s in subjects:
            try:
                sid = int(s.get('id'))
            except (TypeError, ValueError):
                s['group_category'] = forced
                continue
            if sid > 0:
                id_to_gc[sid] = forced
                s['group_category'] = forced
            else:
                s['group_category'] = forced
        section_order = [forced]
        subjects.sort(key=lambda s: exam_subject_column_sort_key(s, section_order))
        return id_to_gc, section_order

    id_to_gc = fetch_subject_id_to_exam_group_category(cursor, [s.get('id') for s in subjects])
    base = fetch_base_academic_level_category_order(cursor)
    section_order = build_exam_subject_section_order(set(id_to_gc.values()) or {'Uncategorized'}, base)
    for s in subjects:
        try:
            sid = int(s.get('id'))
            if sid > 0:
                s['group_category'] = id_to_gc.get(sid, 'Uncategorized')
        except (TypeError, ValueError):
            s['group_category'] = 'Uncategorized'
    subjects.sort(key=lambda s: exam_subject_column_sort_key(s, section_order))
    return id_to_gc, section_order


def _combo_exam_group_category(member_ids, id_to_gc, section_order):
    """Pick one representative category for a combined exam column (earliest section wins)."""
    best_gc = 'Uncategorized'
    best_i = len(section_order) + 1
    for mid in member_ids or []:
        try:
            mid_i = int(mid)
        except (TypeError, ValueError):
            continue
        gc = id_to_gc.get(mid_i, 'Uncategorized')
        try:
            ci = section_order.index(gc)
        except ValueError:
            ci = len(section_order)
        if ci < best_i:
            best_i = ci
            best_gc = gc
    return best_gc


def _build_exam_column_order_slots(name_map, combinations_raw, base_category_order=None):
    """Flat list for UI: standalone subjects + combined groups (one row per combination)."""
    member_set = set()
    for c in combinations_raw or []:
        for mid in c.get('member_subject_ids') or []:
            try:
                member_set.add(int(mid))
            except (TypeError, ValueError):
                continue
    gcs = set()
    for sid, info in (name_map or {}).items():
        try:
            int(sid)
        except (TypeError, ValueError):
            continue
        gcs.add((info or {}).get('group_category') or 'Uncategorized')
    for c in combinations_raw or []:
        for mid in c.get('member_subject_ids') or []:
            inf = name_map.get(int(mid)) if mid is not None else None
            gcs.add((inf or {}).get('group_category') or 'Uncategorized')
    section_order = build_exam_subject_section_order(gcs, base_category_order or [])

    slots = []
    for sid, info in name_map.items():
        sid = int(sid)
        if sid in member_set:
            continue
        eo = info.get('exam_display_order')
        try:
            o = int(eo)
        except (TypeError, ValueError):
            o = 10**9 + sid
        gc = info.get('group_category') or 'Uncategorized'
        try:
            cat_i = section_order.index(gc)
        except ValueError:
            cat_i = len(section_order)
        slots.append(
            {
                'type': 'subject',
                'id': sid,
                'label': (info.get('subject_name') or '').strip() or '—',
                '_ord': o,
                '_cat_i': cat_i,
            }
        )
    for c in combinations_raw or []:
        mids = c.get('member_subject_ids') or []
        if len(mids) < 2:
            continue
        try:
            cid = int(c['id'])
        except (TypeError, ValueError):
            continue
        label_parts = []
        code_parts = []
        for mid in mids:
            inf = name_map.get(int(mid))
            label_parts.append((inf.get('subject_name') or '').strip() or '—' if inf else '—')
            if inf:
                cd = (inf.get('subject_code') or '').strip()
                code_parts.append(cd if cd else (((inf.get('subject_name') or '')[:12]) or '—'))
            else:
                code_parts.append('—')
        members_label = '/'.join(label_parts)
        auto_code = '/'.join(code_parts)
        custom_code = (c.get('combined_code') or '').strip()
        # Prefer saved combined code (used on marks sheets / reports); fall back to joined names.
        label = custom_code or members_label
        dord = c.get('display_order')
        try:
            o = int(dord) if dord is not None else None
        except (TypeError, ValueError):
            o = None
        if o is None:
            ovals = []
            for mid in mids:
                inf = name_map.get(int(mid))
                ev = inf.get('exam_display_order') if inf else None
                try:
                    ovals.append(int(ev))
                except (TypeError, ValueError):
                    ovals.append(10**9 + int(mid))
            o = min(ovals) if ovals else 10**9 + cid
        id_gc = {int(mid): (name_map.get(int(mid)) or {}).get('group_category') or 'Uncategorized' for mid in mids}
        combo_gc = _combo_exam_group_category(mids, id_gc, section_order)
        try:
            cat_i = section_order.index(combo_gc)
        except ValueError:
            cat_i = len(section_order)
        slots.append({
            'type': 'combo',
            'id': cid,
            'label': label,
            'members_label': members_label,
            'combined_code': custom_code or auto_code,
            'default_code': auto_code,
            '_ord': o,
            '_cat_i': cat_i,
        })
    slots.sort(key=lambda z: (z['_cat_i'], z['_ord'], str(z.get('label') or '').lower()))
    for s in slots:
        s.pop('_ord', None)
        cat_i = s.pop('_cat_i', None)
        s['group_category'] = section_order[cat_i] if cat_i is not None and 0 <= cat_i < len(section_order) else 'Uncategorized'
        if s.get('type') == 'subject':
            inf = name_map.get(int(s.get('id') or 0)) or {}
            s['level_categories'] = list(inf.get('level_categories') or [])
        elif s.get('type') == 'combo':
            cid = s.get('id')
            combo = next((c for c in (combinations_raw or []) if int(c.get('id') or 0) == int(cid or 0)), None)
            lc_seen = []
            for mid in (combo.get('member_subject_ids') if combo else []) or []:
                inf = name_map.get(int(mid)) or {}
                for lc in inf.get('level_categories') or []:
                    if lc and lc not in lc_seen:
                        lc_seen.append(lc)
            s['level_categories'] = lc_seen
    return slots


def _build_exam_column_order_by_category(name_map, combinations_raw, base_category_order=None):
    """Column-order UI sections grouped by academic level category (Primary, JSS, etc.)."""
    slots = _build_exam_column_order_slots(name_map, combinations_raw, base_category_order)
    if not slots:
        return []
    by_cat = defaultdict(list)
    for slot in slots:
        gc = (slot.get('group_category') or 'Uncategorized').strip() or 'Uncategorized'
        by_cat[gc].append(slot)
    section_order = build_exam_subject_section_order(set(by_cat.keys()), base_category_order or [])
    return [{'category': cat, 'slots': by_cat[cat]} for cat in section_order if by_cat.get(cat)]


def ensure_exams_marks_lock_at_column(cursor):
    """Adds marks_lock_at (optional deadline after which teachers may not change marks)."""
    try:
        cursor.execute("ALTER TABLE exams ADD COLUMN marks_lock_at DATETIME NULL")
    except Exception as e:
        _schema_ignore_existing(e, 'exams.marks_lock_at column')


def ensure_exams_submitted_status_enum(cursor):
    """Allow exams.status = 'submitted' when curriculum coordinator authorizes release."""
    ensure_exams_gazetted_status_enum(cursor)


def ensure_exams_gazetted_status_enum(cursor):
    """Allow exams.status = 'submitted' and 'gazetted' (deputy gazettement)."""
    try:
        cursor.execute("""
            ALTER TABLE exams
            MODIFY COLUMN status ENUM(
                'scheduled', 'ongoing', 'completed', 'cancelled', 'submitted', 'gazetted'
            ) DEFAULT 'scheduled'
        """)
    except Exception as e:
        _schema_ignore_existing(e, 'exams.status gazetted enum')


def ensure_exams_results_gazetted_columns(cursor):
    """Audit columns when deputy head gazettes (releases) exam results."""
    try:
        cursor.execute("ALTER TABLE exams ADD COLUMN results_gazetted_at DATETIME NULL")
    except Exception as e:
        _schema_ignore_existing(e, 'exams.results_gazetted_at')
    try:
        cursor.execute("ALTER TABLE exams ADD COLUMN results_gazetted_by INT NULL")
    except Exception as e:
        _schema_ignore_existing(e, 'exams.results_gazetted_by')


def _exam_group_is_submitted(cursor, exam_name, academic_year_id, term_id):
    """True when CC has authorized release (submitted or gazetted by deputy)."""
    cursor.execute("""
        SELECT 1 FROM exams
        WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
          AND status IN ('submitted', 'gazetted')
        LIMIT 1
    """, (exam_name, academic_year_id, term_id))
    return cursor.fetchone() is not None


def _exam_group_is_gazetted(cursor, exam_name, academic_year_id, term_id):
    cursor.execute("""
        SELECT 1 FROM exams
        WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
          AND status = 'gazetted'
        LIMIT 1
    """, (exam_name, academic_year_id, term_id))
    return cursor.fetchone() is not None


def _exam_group_ready_for_gazette(cursor, exam_name, academic_year_id, term_id):
    """All allocation rows submitted and not yet gazetted."""
    cursor.execute("""
        SELECT
            COUNT(*) AS total,
            SUM(CASE WHEN status = 'submitted' THEN 1 ELSE 0 END) AS submitted_cnt,
            SUM(CASE WHEN status = 'gazetted' THEN 1 ELSE 0 END) AS gazetted_cnt
        FROM exams
        WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
    """, (exam_name, academic_year_id, term_id))
    row = cursor.fetchone()
    if not row:
        return False
    if isinstance(row, dict):
        total = int(row.get('total') or 0)
        submitted_cnt = int(row.get('submitted_cnt') or 0)
        gazetted_cnt = int(row.get('gazetted_cnt') or 0)
    else:
        total = int(row[0] or 0)
        submitted_cnt = int(row[1] or 0)
        gazetted_cnt = int(row[2] or 0) if len(row) > 2 else 0
    return total > 0 and gazetted_cnt == 0 and submitted_cnt == total


def _exam_group_can_return(cursor, exam_name, academic_year_id, term_id):
    """True when exam is submitted or gazetted and may be returned for CC editing."""
    return _exam_group_is_submitted(cursor, exam_name, academic_year_id, term_id)


def _aggregate_exam_group_status(statuses):
    """Pick a single display status for a registered exam group."""
    normalized = [str(s or 'scheduled').strip().lower() for s in (statuses or []) if s is not None]
    if not normalized:
        return 'scheduled'
    if any(s == 'gazetted' for s in normalized):
        return 'gazetted'
    if any(s == 'submitted' for s in normalized):
        return 'submitted'
    if all(s == 'cancelled' for s in normalized):
        return 'cancelled'
    if all(s == 'completed' for s in normalized):
        return 'completed'
    if any(s == 'ongoing' for s in normalized):
        return 'ongoing'
    if any(s == 'completed' for s in normalized):
        return 'completed'
    return 'scheduled'


def fetch_registered_exam_groups_overview(cursor):
    """
    Registered exams grouped by exam_name + exam_type + academic_year_id + term_id.
    Returns list of dicts sorted by latest exam_date desc.
    """
    ensure_exams_marks_lock_at_column(cursor)
    ensure_exams_gazetted_status_enum(cursor)
    ensure_exams_results_gazetted_columns(cursor)
    cursor.execute("""
        SELECT e.id, e.exam_name, e.exam_type, e.exam_date, e.status,
               e.academic_year_id, e.term_id,
               COALESCE(e.is_locked, 0) AS is_locked, e.locked_at, e.marks_lock_at,
               e.results_gazetted_at,
               ay.year_name, t.term_name
        FROM exams e
        LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
        LEFT JOIN terms t ON e.term_id = t.id
        ORDER BY e.exam_date DESC, e.exam_name ASC, e.id ASC
    """)
    rows = cursor.fetchall() or []
    groups = {}
    for row in rows:
        if isinstance(row, dict):
            exam_name = (row.get('exam_name') or '').strip()
            exam_type = (row.get('exam_type') or '').strip().upper()
            ay_id = row.get('academic_year_id')
            term_id = row.get('term_id')
            exam_date = row.get('exam_date')
            status = row.get('status')
            is_locked = bool(row.get('is_locked'))
            locked_at = row.get('locked_at')
            marks_lock_at = row.get('marks_lock_at')
            results_gazetted_at = row.get('results_gazetted_at')
            year_name = row.get('year_name') or ''
            term_name = row.get('term_name') or ''
            row_id = row.get('id')
        else:
            exam_name = (row[1] or '').strip()
            exam_type = (row[2] or '').strip().upper()
            ay_id = row[5] if len(row) > 5 else None
            term_id = row[6] if len(row) > 6 else None
            exam_date = row[3] if len(row) > 3 else None
            status = row[4] if len(row) > 4 else 'scheduled'
            is_locked = bool(row[7]) if len(row) > 7 else False
            locked_at = row[8] if len(row) > 8 else None
            marks_lock_at = row[9] if len(row) > 9 else None
            results_gazetted_at = row[10] if len(row) > 10 else None
            year_name = row[11] if len(row) > 11 else ''
            term_name = row[12] if len(row) > 12 else ''
            row_id = row[0]

        if not exam_name or ay_id is None or term_id is None:
            continue
        key = f"{exam_name}|{exam_type}|{ay_id}|{term_id}"
        if exam_date and hasattr(exam_date, 'strftime'):
            exam_date_str = exam_date.strftime('%Y-%m-%d')
        else:
            exam_date_str = str(exam_date) if exam_date else ''

        if key not in groups:
            groups[key] = {
                'id': row_id,
                'exam_name': exam_name,
                'exam_type': exam_type,
                'academic_year_id': int(ay_id),
                'term_id': int(term_id),
                'year_name': year_name,
                'term_name': term_name,
                'allocation_count': 0,
                'statuses': [],
                'is_locked': False,
                'locked_at': None,
                'marks_lock_at': None,
                'results_gazetted_at': None,
                'earliest_date': exam_date_str,
                'latest_date': exam_date_str,
            }
        g = groups[key]
        g['allocation_count'] += 1
        g['statuses'].append(status)
        g['is_locked'] = g['is_locked'] or is_locked
        if locked_at and (not g['locked_at'] or str(locked_at) > str(g['locked_at'])):
            g['locked_at'] = locked_at
        if marks_lock_at:
            cur = g['marks_lock_at']
            if not cur or str(marks_lock_at) > str(cur):
                g['marks_lock_at'] = marks_lock_at
        if results_gazetted_at:
            cur_g = g['results_gazetted_at']
            if not cur_g or str(results_gazetted_at) > str(cur_g):
                g['results_gazetted_at'] = results_gazetted_at
        if exam_date_str:
            if not g['earliest_date'] or exam_date_str < g['earliest_date']:
                g['earliest_date'] = exam_date_str
            if not g['latest_date'] or exam_date_str > g['latest_date']:
                g['latest_date'] = exam_date_str

    out = []
    for g in groups.values():
        locked_at = g.pop('locked_at', None)
        marks_lock_at = g.pop('marks_lock_at', None)
        gazetted_at = g.pop('results_gazetted_at', None)
        statuses = g.pop('statuses', [])
        g['status'] = _aggregate_exam_group_status(statuses)
        g['is_gazetted'] = g['status'] == 'gazetted'
        g['is_submitted'] = g['status'] == 'submitted'
        g['can_gazette'] = g['status'] == 'submitted'
        g['can_return'] = g['status'] in ('submitted', 'gazetted')
        if locked_at and hasattr(locked_at, 'strftime'):
            g['locked_at'] = locked_at.strftime('%Y-%m-%d %H:%M')
        elif locked_at:
            g['locked_at'] = str(locked_at)
        else:
            g['locked_at'] = None
        if marks_lock_at and hasattr(marks_lock_at, 'strftime'):
            g['marks_lock_at'] = marks_lock_at.strftime('%Y-%m-%d %H:%M')
        elif marks_lock_at:
            g['marks_lock_at'] = str(marks_lock_at)
        else:
            g['marks_lock_at'] = None
        if gazetted_at and hasattr(gazetted_at, 'strftime'):
            g['results_gazetted_at'] = gazetted_at.strftime('%Y-%m-%d %H:%M')
        elif gazetted_at:
            g['results_gazetted_at'] = str(gazetted_at)
        else:
            g['results_gazetted_at'] = None
        out.append(g)
    out.sort(key=lambda x: (x.get('latest_date') or '', x.get('exam_name') or ''), reverse=True)
    return out


def fetch_exam_group_classes(cursor, exam_name, academic_year_id, term_id, exam_type=None):
    """Academic levels (classes) that have allocations for a registered exam group."""
    exam_name = (exam_name or '').strip().upper()
    if not exam_name or not academic_year_id or not term_id:
        return None, []
    filter_type = exam_type is not None and str(exam_type).strip() != ''
    exam_type_key = (exam_type or '').strip().upper() if filter_type else None
    params = [exam_name, int(academic_year_id), int(term_id)]
    type_clause = ''
    if filter_type:
        type_clause = " AND UPPER(TRIM(COALESCE(e.exam_type, ''))) = %s"
        params.append(exam_type_key)
    cursor.execute(f"""
        SELECT e.academic_level_id,
               MIN(e.id) AS exam_row_id,
               COUNT(*) AS subject_slots,
               al.level_name, al.level_category
        FROM exams e
        INNER JOIN academic_levels al ON al.id = e.academic_level_id
        WHERE e.exam_name = %s
          AND e.academic_year_id = %s
          AND e.term_id = %s
          {type_clause}
        GROUP BY e.academic_level_id, al.level_name, al.level_category
        ORDER BY al.level_name ASC, al.level_category ASC
    """, tuple(params))
    rows = cursor.fetchall() or []
    classes = []
    for row in rows:
        if isinstance(row, dict):
            level_id = row.get('academic_level_id')
            level_name = row.get('level_name') or ''
            level_category = row.get('level_category') or ''
            exam_row_id = row.get('exam_row_id')
            subject_slots = int(row.get('subject_slots') or 0)
        else:
            level_id = row[0]
            exam_row_id = row[1]
            subject_slots = int(row[2] or 0)
            level_name = row[3] if len(row) > 3 else ''
            level_category = row[4] if len(row) > 4 else ''
        student_count = 0
        if level_name:
            cursor.execute(
                "SELECT COUNT(*) AS cnt FROM students WHERE current_grade = %s",
                (level_name,),
            )
            sr = cursor.fetchone()
            student_count = int((sr.get('cnt') if isinstance(sr, dict) else sr[0]) or 0)
        classes.append({
            'academic_level_id': int(level_id),
            'level_name': level_name,
            'level_category': level_category,
            'exam_row_id': int(exam_row_id) if exam_row_id else None,
            'subject_slots': subject_slots,
            'student_count': student_count,
        })
    meta = {
        'exam_name': exam_name,
        'exam_type': exam_type_key or '',
        'academic_year_id': int(academic_year_id),
        'term_id': int(term_id),
    }
    cursor.execute(
        "SELECT year_name FROM academic_years WHERE id = %s LIMIT 1",
        (int(academic_year_id),),
    )
    yr = cursor.fetchone()
    meta['year_name'] = (yr.get('year_name') if isinstance(yr, dict) else (yr[0] if yr else '')) or ''
    cursor.execute(
        "SELECT term_name FROM terms WHERE id = %s LIMIT 1",
        (int(term_id),),
    )
    tr = cursor.fetchone()
    meta['term_name'] = (tr.get('term_name') if isinstance(tr, dict) else (tr[0] if tr else '')) or ''
    return meta, classes


def _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id):
    """
    Allocation lock and marks-entry deadline are shared across all subject rows
    for the same level + exam_name + academic_year_id + term_id.
    Returns (max_is_locked: int 0|1, marks_lock_at: datetime|None).
    """
    cursor.execute("""
        SELECT academic_level_id, exam_name, academic_year_id, term_id
        FROM exams WHERE id = %s LIMIT 1
    """, (exam_id,))
    g = cursor.fetchone()
    if not g:
        return 0, None
    if isinstance(g, dict):
        lvl = g.get('academic_level_id')
        name = (g.get('exam_name') or '').strip()
        ay = g.get('academic_year_id')
        term = g.get('term_id')
    else:
        lvl, name, ay, term = g[0], (g[1] or '').strip(), g[2], g[3]
    if not name or ay is None or term is None:
        return 0, None
    cursor.execute("""
        SELECT MAX(COALESCE(is_locked, 0)) AS mx, MAX(marks_lock_at) AS mla
        FROM exams
        WHERE academic_level_id = %s AND exam_name = %s AND academic_year_id = %s AND term_id = %s
    """, (lvl, name, ay, term))
    r = cursor.fetchone()
    if not r:
        return 0, None
    if isinstance(r, dict):
        mx = int(r.get('mx') or 0)
        mla = r.get('mla')
    else:
        mx = int(r[0] or 0)
        mla = r[1] if len(r) > 1 else None
    return (1 if mx else 0), mla


def _marks_lock_deadline_passed(marks_lock_at):
    if not marks_lock_at:
        return False
    try:
        now = datetime.now()
        dt = marks_lock_at
        if isinstance(dt, date_cls) and not isinstance(dt, datetime):
            dt = datetime.combine(dt, datetime.min.time())
        if getattr(dt, 'tzinfo', None) is not None and dt.tzinfo is not None:
            dt = dt.replace(tzinfo=None)
        return dt <= now
    except Exception:
        return False


def ensure_registered_current_exam_column(cursor):
    try:
        cursor.execute(
            "ALTER TABLE school_settings ADD COLUMN registered_current_exam_json TEXT NULL "
            "COMMENT 'JSON: exam_name, academic_year_id, term_id for school-wide current exam'"
        )
    except Exception as e:
        msg = str(e).lower()
        if 'duplicate' not in msg and 'already exists' not in msg:
            print(f"ensure_registered_current_exam_column: {e}")


def load_registered_current_exam_dict(cursor):
    """Returns dict exam_name (upper), exam_type (upper str or None if legacy JSON), academic_year_id, term_id or None."""
    try:
        ensure_registered_current_exam_column(cursor)
        cursor.execute(
            "SELECT registered_current_exam_json FROM school_settings ORDER BY id DESC LIMIT 1"
        )
        row = cursor.fetchone()
        if not row:
            return None
        raw = row.get('registered_current_exam_json') if isinstance(row, dict) else (row[0] if row else None)
        if raw is None or (isinstance(raw, str) and not str(raw).strip()):
            return None
        j = json.loads(raw) if isinstance(raw, str) else raw
        if not isinstance(j, dict):
            return None
        name = (j.get('exam_name') or '').strip().upper()
        try:
            ay = int(j.get('academic_year_id') or 0)
            tid = int(j.get('term_id') or 0)
        except (TypeError, ValueError):
            return None
        if not name or ay <= 0 or tid <= 0:
            return None
        out = {'exam_name': name, 'academic_year_id': ay, 'term_id': tid}
        if 'exam_type' in j:
            out['exam_type'] = (j.get('exam_type') or '').strip().upper()
        else:
            out['exam_type'] = None
        return out
    except Exception as e:
        print(f"load_registered_current_exam_dict: {e}")
        return None


def apply_marks_lock_deadline_auto_lock(cursor):
    """
    When marks_lock_at is in the past, set allocation lock so the exam row matches
    the closed marks window (coordinators can still unlock manually if needed).
    """
    try:
        ensure_exams_marks_lock_at_column(cursor)
        cursor.execute("""
            UPDATE exams
            SET is_locked = 1,
                locked_at = CURRENT_TIMESTAMP
            WHERE marks_lock_at IS NOT NULL
              AND marks_lock_at <= NOW()
              AND COALESCE(is_locked, 0) = 0
        """)
    except Exception as e:
        print(f"apply_marks_lock_deadline_auto_lock: {e}")


def _default_exam_session_presets():
    return {
        'MORNING': ('08:00:00', '11:00:00'),
        'MIDDAY': ('11:30:00', '13:30:00'),
        'AFTERNOON': ('14:00:00', '16:00:00'),
        'EVENING': ('17:00:00', '19:00:00'),
    }


def _parse_exam_session_settings_json(raw_json: str):
    """
    Returns dict like { 'MORNING': ('08:00:00','11:00:00'), ... }.
    Falls back to defaults on any validation failure.
    """
    import json
    presets = _default_exam_session_presets()
    if not raw_json:
        return presets
    try:
        data = json.loads(raw_json)
        if not isinstance(data, dict):
            return presets
    except Exception:
        return presets

    def _norm_hm(s):
        s = (s or '').strip()
        parts = s.split(':')
        if len(parts) < 2:
            return None
        try:
            h = int(parts[0]); m = int(parts[1])
        except Exception:
            return None
        if h < 0 or h > 23 or m < 0 or m > 59:
            return None
        return f"{h:02d}:{m:02d}:00"

    def _to_minutes(hms):
        if not hms:
            return None
        parts = str(hms).split(':')
        if len(parts) < 2:
            return None
        try:
            return int(parts[0]) * 60 + int(parts[1])
        except Exception:
            return None

    def _from_minutes(total_minutes):
        total_minutes = total_minutes % (24 * 60)
        return f"{total_minutes // 60:02d}:{total_minutes % 60:02d}:00"

    for key in ['MORNING', 'MIDDAY', 'AFTERNOON', 'EVENING']:
        row = data.get(key)
        if not isinstance(row, dict):
            continue
        st = _norm_hm(row.get('start') or row.get('start_time') or '')
        try:
            dur = int(row.get('duration_minutes', 0) or 0)
        except Exception:
            dur = 0
        if not st or dur <= 0:
            continue
        sm = _to_minutes(st)
        if sm is None:
            continue
        presets[key] = (st, _from_minutes(sm + dur))

    return presets


def _load_exam_session_presets_from_db(cursor):
    """Load session presets from latest school_settings row (or defaults)."""
    presets = _default_exam_session_presets()
    try:
        cursor.execute("SHOW COLUMNS FROM school_settings LIKE 'exam_session_settings'")
        if not cursor.fetchone():
            return presets
        cursor.execute("SELECT exam_session_settings FROM school_settings ORDER BY id DESC LIMIT 1")
        row = cursor.fetchone()
        raw = None
        if row:
            raw = row.get('exam_session_settings') if isinstance(row, dict) else row[0]
        return _parse_exam_session_settings_json(raw or '')
    except Exception:
        return presets


def _fetch_exam_supervisor_allocation_maps(cursor, level_ids):
    """
    Supervisor eligibility from teacher_subject_assignments:
    - teachers_by_level: teachers allocated to teach at least one subject at each level
    - excluded_by_ls: subject teachers who cannot supervise that paper at that level
  """
    from collections import defaultdict

    level_ids = sorted({int(x) for x in (level_ids or []) if int(x) > 0})
    teachers_by_level = defaultdict(set)
    subjects_by_level = defaultdict(set)
    excluded_by_ls = defaultdict(set)
    subject_name_by_id = {}
    if not level_ids:
        return {
            'teachers_by_level': teachers_by_level,
            'subjects_by_level': subjects_by_level,
            'excluded_by_ls': excluded_by_ls,
            'subject_name_by_id': subject_name_by_id,
        }

    ph = ','.join(['%s'] * len(level_ids))
    cursor.execute(f"""
        SELECT tsa.academic_level_id, tsa.subject_id, tsa.teacher_id, s.subject_name
        FROM teacher_subject_assignments tsa
        INNER JOIN subjects s ON s.id = tsa.subject_id AND s.status = 'active'
        INNER JOIN academic_levels al ON al.id = tsa.academic_level_id AND al.level_status = 'active'
        INNER JOIN employees emp ON emp.id = tsa.teacher_id
            AND emp.status = 'active'
            AND (emp.role = 'teachers' OR emp.role = 'teacher')
        WHERE tsa.academic_level_id IN ({ph})
    """, tuple(level_ids))

    for row in cursor.fetchall() or []:
        lid = row.get('academic_level_id') if isinstance(row, dict) else row[0]
        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
        tid = row.get('teacher_id') if isinstance(row, dict) else row[2]
        sname = row.get('subject_name', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')
        if lid and sid:
            lid_i = int(lid)
            sid_i = int(sid)
            subjects_by_level[lid_i].add(sid_i)
            if sname:
                subject_name_by_id[sid_i] = str(sname)
        if lid and tid:
            teachers_by_level[int(lid)].add(int(tid))
        if lid and sid and tid:
            excluded_by_ls[(int(lid), int(sid))].add(int(tid))

    return {
        'teachers_by_level': teachers_by_level,
        'subjects_by_level': subjects_by_level,
        'excluded_by_ls': excluded_by_ls,
        'subject_name_by_id': subject_name_by_id,
    }


def _eligible_exam_supervisor_ids(teachers_by_level, excluded_by_ls, level_id, subject_id):
    """Teachers at this academic level who do not teach this subject in that class."""
    level_teachers = teachers_by_level.get(int(level_id), set()) or set()
    excluded = excluded_by_ls.get((int(level_id), int(subject_id)), set()) or set()
    return level_teachers.difference(excluded)


def ensure_student_marks_foreign_keys(cursor):
    """
    Add InnoDB foreign keys to student_marks if possible.

    Inline FKs on CREATE TABLE often fail with errno 150 on shared hosting when parent
    tables are not InnoDB or when VARCHAR charset/collation does not match exactly.
    Creating the table first (indexes + unique only) then ALTER ... ADD CONSTRAINT
    avoids blocking init_db; constraints are applied when the server allows them.
    """
    cursor.execute("SHOW TABLES LIKE 'student_marks'")
    if not cursor.fetchone():
        return
    alters = [
        (
            "fk_student_marks_student",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_student
            FOREIGN KEY (student_id) REFERENCES students(student_id) ON DELETE CASCADE
            """,
        ),
        (
            "fk_student_marks_subject",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_subject
            FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE CASCADE
            """,
        ),
        (
            "fk_student_marks_exam",
            """
            ALTER TABLE student_marks
            ADD CONSTRAINT fk_student_marks_exam
            FOREIGN KEY (exam_id) REFERENCES exams(id) ON DELETE CASCADE
            """,
        ),
    ]
    for constraint_name, sql in alters:
        try:
            cursor.execute(
                """
                SELECT 1 FROM information_schema.TABLE_CONSTRAINTS
                WHERE TABLE_SCHEMA = DATABASE()
                  AND TABLE_NAME = 'student_marks'
                  AND CONSTRAINT_NAME = %s
                LIMIT 1
                """,
                (constraint_name,),
            )
            if cursor.fetchone():
                continue
            cursor.execute(sql)
            print(f"OK: Added constraint {constraint_name} on student_marks")
        except Exception as e:
            _schema_ignore_existing(e, f'student_marks {constraint_name}')


def ensure_exam_marks_audit_table(cursor):
    """Audit log for exam marks changes (used to surface non-allocated-teacher edits)."""
    cursor.execute("SHOW TABLES LIKE 'exam_marks_audit'")
    if cursor.fetchone():
        return
    cursor.execute("""
        CREATE TABLE IF NOT EXISTS exam_marks_audit (
            id INT AUTO_INCREMENT PRIMARY KEY,
            student_id VARCHAR(20) NOT NULL,
            subject_id INT NOT NULL,
            exam_id INT NOT NULL,
            academic_level_id INT NOT NULL,
            exam_name VARCHAR(255),
            action_type ENUM('INSERT', 'UPDATE', 'DELETE') NOT NULL,
            old_marks DECIMAL(10, 2),
            new_marks DECIMAL(10, 2),
            changed_by INT,
            changed_by_role VARCHAR(80),
            changed_by_name VARCHAR(255),
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_student_id (student_id),
            INDEX idx_subject_id (subject_id),
            INDEX idx_exam_id (exam_id),
            INDEX idx_academic_level_id (academic_level_id),
            INDEX idx_changed_by (changed_by),
            INDEX idx_created_at (created_at)
        ) ENGINE=InnoDB
    """)


def _exam_marks_audit_actor():
    """Employee id, role label, and display name for the current session."""
    user_role = (session.get('role') or '').lower()
    viewing_as_role = (session.get('viewing_as_employee_role') or '').lower()
    is_technician = user_role == 'technician'
    if is_technician and session.get('viewing_as_employee_id'):
        changed_by = session.get('viewing_as_employee_id')
        role = viewing_as_role or user_role
    else:
        changed_by = session.get('employee_id') or session.get('user_id')
        role = viewing_as_role or user_role
    name = (session.get('full_name') or session.get('username') or 'Staff').strip()
    return changed_by, role, name


def _log_exam_marks_audit(
    cursor,
    *,
    student_id,
    subject_id,
    exam_id,
    academic_level_id,
    exam_name,
    action_type,
    old_marks,
    new_marks,
    changed_by,
    changed_by_role,
    changed_by_name,
):
    ensure_exam_marks_audit_table(cursor)
    cursor.execute("""
        INSERT INTO exam_marks_audit
        (student_id, subject_id, exam_id, academic_level_id, exam_name, action_type,
         old_marks, new_marks, changed_by, changed_by_role, changed_by_name)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
    """, (
        student_id, subject_id, exam_id, academic_level_id, exam_name, action_type,
        old_marks, new_marks, changed_by, changed_by_role, changed_by_name,
    ))


def _marks_audit_values_equal(a, b):
    if a is None and b is None:
        return True
    if a is None or b is None:
        return False
    try:
        return abs(float(a) - float(b)) < 1e-9
    except (TypeError, ValueError):
        return str(a) == str(b)


_library_books_schema_ensuring = False


def ensure_library_books_table(cursor):
    """Librarian catalog: titles with book category, academic category (level_category), subject, buying price."""
    global _library_books_schema_ensuring
    if _library_books_schema_ensuring:
        return
    _library_books_schema_ensuring = True
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS library_books (
                id INT AUTO_INCREMENT PRIMARY KEY,
                book_category VARCHAR(120) NOT NULL,
                book_name VARCHAR(255) NOT NULL,
                description TEXT,
                buying_price DECIMAL(12,2) NOT NULL DEFAULT 0.00,
                academic_category VARCHAR(255) NOT NULL,
                subject_id INT NOT NULL,
                library_status ENUM('active', 'suspended') NOT NULL DEFAULT 'active',
                allocation_status ENUM('unallocated', 'allocated') NOT NULL DEFAULT 'unallocated',
                copies_total INT NOT NULL DEFAULT 1,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE RESTRICT,
                INDEX idx_library_books_academic_category (academic_category(100)),
                INDEX idx_library_books_subject (subject_id)
            )
        """)
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'buying_price'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE library_books
                ADD COLUMN buying_price DECIMAL(12,2) NOT NULL DEFAULT 0.00 AFTER description
            """)
            print("OK: Added library_books.buying_price")
        migrate_library_books_academic_category_schema(cursor)
        migrate_library_books_status_columns(cursor)
        ensure_library_book_allocations_table(cursor)
        migrate_library_books_copies_and_allocation_qty(cursor)
        ensure_library_book_stock_movements_table(cursor)
        ensure_library_book_copy_units_table(cursor)
        ensure_library_book_suppliers_table(cursor)
        ensure_library_book_teacher_distributions_table(cursor)
        ensure_library_book_student_issues_table(cursor)
        migrate_library_books_store_department_link(cursor)
    except Exception as e:
        print(f"ensure_library_books_table: {e}")
    finally:
        _library_books_schema_ensuring = False


def migrate_library_books_store_department_link(cursor):
    """Link library titles to store catalog; allow pending subject until librarian completes setup."""
    try:
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'store_item_id'")
        if not cursor.fetchone():
            cursor.execute("""
                ALTER TABLE library_books
                ADD COLUMN store_item_id INT NULL AFTER copies_total
            """)
            print("OK: Added library_books.store_item_id")
        cursor.execute("""
            SELECT 1 FROM information_schema.STATISTICS
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME = 'library_books'
              AND INDEX_NAME = 'uq_library_book_store_item'
            LIMIT 1
        """)
        if not cursor.fetchone():
            try:
                cursor.execute("""
                    ALTER TABLE library_books
                    ADD UNIQUE KEY uq_library_book_store_item (store_item_id)
                """)
            except Exception as idx_err:
                print(f"migrate_library_books_store_department_link index: {idx_err}")
        cursor.execute("""
            SELECT IS_NULLABLE
            FROM information_schema.COLUMNS
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME = 'library_books'
              AND COLUMN_NAME = 'subject_id'
        """)
        sub_col = cursor.fetchone()
        sub_nullable = (
            (sub_col.get('IS_NULLABLE') if isinstance(sub_col, dict) else sub_col[0])
            if sub_col else 'NO'
        )
        if (sub_nullable or '').upper() == 'NO':
            _library_books_drop_fk_on_column(cursor, 'library_books', 'subject_id')
            cursor.execute("ALTER TABLE library_books MODIFY subject_id INT NULL")
            try:
                cursor.execute("""
                    ALTER TABLE library_books
                    ADD CONSTRAINT fk_library_books_subject
                    FOREIGN KEY (subject_id) REFERENCES subjects(id) ON DELETE RESTRICT
                """)
            except Exception as fk_err:
                print(f"migrate_library_books_store_department_link subject fk: {fk_err}")
            print("OK: library_books.subject_id allows NULL for store-originated titles")
    except Exception as e:
        print(f"migrate_library_books_store_department_link: {e}")


def _library_books_drop_fk_on_column(cursor, table, column_name):
    try:
        cursor.execute(
            """
            SELECT CONSTRAINT_NAME
            FROM information_schema.KEY_COLUMN_USAGE
            WHERE TABLE_SCHEMA = DATABASE()
              AND TABLE_NAME = %s
              AND COLUMN_NAME = %s
              AND REFERENCED_TABLE_NAME IS NOT NULL
            """,
            (table, column_name),
        )
        row = cursor.fetchone()
        if not row:
            return
        cname = row.get('CONSTRAINT_NAME') if isinstance(row, dict) else row[0]
        if cname:
            cursor.execute(f"ALTER TABLE `{table}` DROP FOREIGN KEY `{cname}`")
    except Exception as e:
        print(f"_library_books_drop_fk_on_column ({table}.{column_name}): {e}")


def migrate_library_books_academic_category_schema(cursor):
    """Replace academic_level_id with academic_category (from academic_levels.level_category)."""
    try:
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'academic_category'")
        has_cat = bool(cursor.fetchone())
        cursor.execute("SHOW COLUMNS FROM library_books LIKE 'academic_level_id'")
        has_level = bool(cursor.fetchone())

        if has_level and not has_cat:
            cursor.execute(
                "ALTER TABLE library_books ADD COLUMN academic_category VARCHAR(255) NULL AFTER buying_price"
            )
            cursor.execute("""
                UPDATE library_books lb
                INNER JOIN academic_levels al ON al.id = lb.academic_level_id
                SET lb.academic_category = UPPER(TRIM(al.level_category))
            """)
            has_cat = True

        if has_level and has_cat:
            cursor.execute("""
                UPDATE library_books lb
                INNER JOIN academic_levels al ON al.id = lb.academic_level_id
                SET lb.academic_category = UPPER(TRIM(al.level_category))
                WHERE lb.academic_category IS NULL OR TRIM(lb.academic_category) = ''
            """)
            _library_books_drop_fk_on_column(cursor, 'library_books', 'academic_level_id')
            try:
                cursor.execute("ALTER TABLE library_books DROP INDEX idx_library_books_level")
            except Exception:
                pass
            try:
                cursor.execute("ALTER TABLE library_books DROP COLUMN academic_level_id")
            except Exception as e:
                print(f"migrate_library_books: drop academic_level_id: {e}")

        if not has_cat:
            cursor.execute(
                "ALTER TABLE library_books ADD COLUMN academic_category VARCHAR(255) NOT NULL DEFAULT ''"
            )

        cursor.execute(
            "UPDATE library_books SET academic_category = UPPER(TRIM(academic_category)) WHERE academic_category IS NOT NULL"
        )
        cursor.execute("""
            UPDATE library_books
            SET academic_category = 'UNKNOWN'
            WHERE academic_category IS NULL OR TRIM(academic_category) = ''
        """)
        try:
            cursor.execute(
                "ALTER TABLE library_books MODIFY COLUMN academic_category VARCHAR(255) NOT NULL"
            )
        except Exception as e:
            print(f"migrate_library_books: modify academic_category NOT NULL: {e}")

        cursor.execute("SHOW INDEX FROM library_books WHERE Key_name = 'idx_library_books_academic_category'")
        if not cursor.fetchone():
            try:
                cursor.execute(
                    "ALTER TABLE library_books ADD INDEX idx_library_books_academic_category (academic_category(100))"
                )
            except Exception as e:
                print(f"migrate_library_books: add index academic_category: {e}")
    except Exception as e:
        print(f"migrate_library_books_academic_category_schema: {e}")


