def _teacher_resources_subjects_for_level(cursor, teacher_id, level_id, with_counts=False):
    """Subjects the teacher teaches at the given academic level."""
    rows = []
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return rows
    cursor.execute(
        """
        SELECT DISTINCT s.id, s.subject_name, s.subject_code
        FROM teacher_subject_assignments tsa
        INNER JOIN subjects s ON s.id = tsa.subject_id
        WHERE tsa.teacher_id = %s
          AND tsa.academic_level_id = %s
          AND COALESCE(s.status, 'active') = 'active'
        ORDER BY s.subject_name ASC
        """,
        (teacher_id, level_id),
    )
    subject_counts = _teacher_resources_subject_resource_counts(cursor, teacher_id, level_id) if with_counts else {}
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            sid = int(row.get('id') or 0)
            item = {
                'id': sid,
                'subject_name': (row.get('subject_name') or '').strip(),
                'subject_code': (row.get('subject_code') or '').strip(),
            }
        else:
            sid = int(row[0] or 0)
            item = {
                'id': sid,
                'subject_name': (row[1] or '').strip(),
                'subject_code': (row[2] or '').strip(),
            }
        if with_counts:
            item['resource_count'] = subject_counts.get(sid, 0)
        rows.append(item)
    return rows


def _teacher_resources_row_to_dict(row):
    """Normalize DB row for teaching resource JSON/template."""
    if isinstance(row, dict):
        return {
            'id': int(row.get('id') or 0),
            'teacher_id': int(row.get('teacher_id') or 0),
            'academic_level_id': int(row.get('academic_level_id') or 0),
            'subject_id': int(row.get('subject_id') or 0),
            'title': (row.get('title') or '').strip(),
            'description': (row.get('description') or '').strip(),
            'file_path': (row.get('file_path') or '').strip(),
            'original_filename': (row.get('original_filename') or '').strip(),
            'mime_type': (row.get('mime_type') or '').strip(),
            'file_size': int(row.get('file_size') or 0),
            'is_published': bool(row.get('is_published')),
            'teacher_name': (row.get('teacher_name') or '').strip(),
            'subject_name': (row.get('subject_name') or '').strip(),
            'subject_code': (row.get('subject_code') or '').strip(),
            'created_at': row.get('created_at'),
        }
    return {
        'id': int(row[0] or 0),
        'teacher_id': int(row[1] or 0),
        'academic_level_id': int(row[2] or 0),
        'subject_id': int(row[3] or 0),
        'title': (row[4] or '').strip(),
        'description': (row[5] or '').strip(),
        'file_path': (row[6] or '').strip(),
        'original_filename': (row[7] or '').strip(),
        'mime_type': (row[8] or '').strip() if len(row) > 8 else '',
        'file_size': int(row[9] or 0) if len(row) > 9 else 0,
        'is_published': bool(row[10]) if len(row) > 10 else True,
        'created_at': row[11] if len(row) > 11 else None,
        'teacher_name': (row[12] or '').strip() if len(row) > 12 else '',
        'subject_name': (row[13] or '').strip() if len(row) > 13 else '',
        'subject_code': (row[14] or '').strip() if len(row) > 14 else '',
    }


def _teacher_resources_fetch_list(cursor, level_id, subject_id, teacher_id=None, published_only=False):
    """List teaching resources for a class and subject."""
    ensure_teacher_teaching_resources_table(cursor)
    try:
        level_id = int(level_id)
        subject_id = int(subject_id)
    except (TypeError, ValueError):
        return []
    clauses = ['r.academic_level_id = %s', 'r.subject_id = %s']
    params = [level_id, subject_id]
    if teacher_id is not None:
        try:
            teacher_id = int(teacher_id)
            clauses.append('r.teacher_id = %s')
            params.append(teacher_id)
        except (TypeError, ValueError):
            return []
    if published_only:
        clauses.append('r.is_published = 1')
    where = ' AND '.join(clauses)
    cursor.execute(
        f"""
        SELECT
            r.id, r.teacher_id, r.academic_level_id, r.subject_id,
            r.title, r.description, r.file_path, r.original_filename,
            r.mime_type, r.file_size, r.is_published, r.created_at,
            UPPER(TRIM(e.full_name)) AS teacher_name,
            UPPER(TRIM(s.subject_name)) AS subject_name,
            UPPER(TRIM(s.subject_code)) AS subject_code
        FROM teacher_teaching_resources r
        LEFT JOIN employees e ON e.id = r.teacher_id
        LEFT JOIN subjects s ON s.id = r.subject_id
        WHERE {where}
        ORDER BY r.created_at DESC, r.id DESC
        """,
        tuple(params),
    )
    out = []
    for row in cursor.fetchall() or []:
        item = _teacher_resources_row_to_dict(row)
        fp = item.get('file_path') or ''
        if fp and not fp.startswith('/'):
            item['download_url'] = '/' + fp.lstrip('/')
        else:
            item['download_url'] = fp or '#'
        if item.get('created_at') and hasattr(item['created_at'], 'strftime'):
            item['created_at_label'] = item['created_at'].strftime('%d %b %Y %H:%M')
        else:
            item['created_at_label'] = ''
        out.append(item)
    return out


def _save_teaching_resource_file(upload_file):
    """Persist uploaded teaching resource; return (path, original_name, mime) or (None, None, err)."""
    if not upload_file or not getattr(upload_file, 'filename', None):
        return None, None, None
    fn = secure_filename(upload_file.filename)
    if not fn or not allowed_teaching_resource_file(fn):
        return None, None, 'Invalid file type. Use PDF, Word, Excel, PowerPoint, image, text, or ZIP.'
    ext = fn.rsplit('.', 1)[1].lower()
    if is_image_filename(fn):
        rel = _save_optimized_image(
            upload_file,
            TEACHING_RESOURCES_UPLOAD_FOLDER,
            f'tr_{secrets.token_hex(8)}',
            preset='attachment',
        )
        if not rel:
            return None, None, 'Could not save image file.'
        path = os.path.join('static', rel)
        mime = 'image/png' if rel.lower().endswith('.png') else 'image/jpeg'
        return path, fn, mime
    stored = f"tr_{secrets.token_hex(8)}.{ext}"
    path = os.path.join(TEACHING_RESOURCES_UPLOAD_FOLDER, stored)
    upload_file.save(path)
    mime_map = {
        'pdf': 'application/pdf',
        'png': 'image/png',
        'jpg': 'image/jpeg',
        'jpeg': 'image/jpeg',
        'gif': 'image/gif',
        'doc': 'application/msword',
        'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'xls': 'application/vnd.ms-excel',
        'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'ppt': 'application/vnd.ms-powerpoint',
        'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
        'txt': 'text/plain',
        'csv': 'text/csv',
        'zip': 'application/zip',
    }
    return path, fn, mime_map.get(ext, 'application/octet-stream')


def _student_teaching_resources_by_subject(cursor, student_id, class_subjects=None):
    """Per-subject learning resource links for a student's class."""
    level_id = _student_academic_level_id(cursor, student_id)
    if not level_id:
        return []
    ensure_teacher_teaching_resources_table(cursor)
    counts = {}
    cursor.execute(
        """
        SELECT subject_id, COUNT(*) AS resource_count
        FROM teacher_teaching_resources
        WHERE academic_level_id = %s AND is_published = 1
        GROUP BY subject_id
        """,
        (level_id,),
    )
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            sid = int(row.get('subject_id') or 0)
            counts[sid] = int(row.get('resource_count') or 0)
        else:
            counts[int(row[0] or 0)] = int(row[1] or 0)

    def _append_subject(subjects_out, seen, subj_id, subject_name, subject_code):
        if not subj_id or subj_id in seen:
            return
        seen.add(subj_id)
        subjects_out.append({
            'subject_id': int(subj_id),
            'subject_name': (subject_name or 'Subject').strip(),
            'subject_code': (subject_code or '').strip(),
            'resource_count': counts.get(int(subj_id), 0),
        })

    subjects_out = []
    seen = set()
    for subj in class_subjects or []:
        _append_subject(
            subjects_out, seen,
            subj.get('subject_id'),
            subj.get('subject_name'),
            subj.get('subject_code'),
        )

    if not subjects_out:
        cursor.execute(
            """
            SELECT DISTINCT s.id AS subject_id,
                UPPER(TRIM(s.subject_name)) AS subject_name,
                UPPER(TRIM(s.subject_code)) AS subject_code
            FROM subject_academic_levels sal
            INNER JOIN subjects s ON s.id = sal.subject_id
            WHERE sal.academic_level_id = %s
              AND COALESCE(s.status, 'active') = 'active'
            ORDER BY s.subject_name ASC
            """,
            (level_id,),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                _append_subject(
                    subjects_out, seen,
                    row.get('subject_id'),
                    row.get('subject_name'),
                    row.get('subject_code'),
                )
            else:
                _append_subject(subjects_out, seen, row[0], row[1], row[2])

    if not subjects_out:
        cursor.execute(
            """
            SELECT DISTINCT s.id AS subject_id,
                UPPER(TRIM(s.subject_name)) AS subject_name,
                UPPER(TRIM(s.subject_code)) AS subject_code
            FROM teacher_subject_assignments tsa
            INNER JOIN subjects s ON s.id = tsa.subject_id
            WHERE tsa.academic_level_id = %s
              AND COALESCE(s.status, 'active') = 'active'
            ORDER BY s.subject_name ASC
            """,
            (level_id,),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                _append_subject(
                    subjects_out, seen,
                    row.get('subject_id'),
                    row.get('subject_name'),
                    row.get('subject_code'),
                )
            else:
                _append_subject(subjects_out, seen, row[0], row[1], row[2])

    for subj_id, cnt in counts.items():
        if subj_id in seen:
            continue
        cursor.execute(
            """
            SELECT UPPER(TRIM(subject_name)) AS subject_name,
                   UPPER(TRIM(subject_code)) AS subject_code
            FROM subjects WHERE id = %s LIMIT 1
            """,
            (subj_id,),
        )
        row = cursor.fetchone()
        if not row:
            continue
        subjects_out.append({
            'subject_id': subj_id,
            'subject_name': (row.get('subject_name') if isinstance(row, dict) else row[0] or 'Subject').strip(),
            'subject_code': (row.get('subject_code') if isinstance(row, dict) else row[1] or '').strip(),
            'resource_count': cnt,
        })
        seen.add(subj_id)

    subjects_out.sort(key=lambda s: (s.get('subject_name') or '').lower())
    return subjects_out


def _student_teaching_resources_bundle(cursor, student_id):
    """Subjects for student's class with published resource lists per subject."""
    level_id = _student_academic_level_id(cursor, student_id)
    if not level_id:
        return [], {}
    ensure_teacher_teaching_resources_table(cursor)
    _yid, _yname, term_id, term_name = _get_current_academic_year_and_term(cursor)
    try:
        class_progress = _parent_class_subject_progress_bundle(
            cursor, student_id, term_id, term_name,
        )
    except Exception:
        class_progress = {'subjects': []}
    subjects = _student_teaching_resources_by_subject(
        cursor,
        student_id,
        (class_progress or {}).get('subjects') or [],
    )
    resources_by_subject = {}
    for sub in subjects:
        subj_id = sub.get('subject_id')
        if not subj_id:
            continue
        items = _teacher_resources_fetch_list(
            cursor, level_id, subj_id, published_only=True,
        )
        resources_by_subject[str(subj_id)] = items
    return subjects, resources_by_subject


def _teacher_library_teacher_book_quota(cursor, teacher_id, level_id):
    """Map library_book_id -> total copies allocated to teacher at level."""
    ensure_library_book_teacher_distributions_table(cursor)
    out = {}
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return out
    cursor.execute(
        """
        SELECT library_book_id, SUM(quantity) AS qty
        FROM library_book_teacher_distributions
        WHERE teacher_id = %s AND academic_level_id = %s
        GROUP BY library_book_id
        """,
        (teacher_id, level_id),
    )
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            bid = int(row.get('library_book_id') or 0)
            qty = int(row.get('qty') or 0)
        else:
            bid = int(row[0] or 0)
            qty = int(row[1] or 0)
        if bid:
            out[bid] = qty
    return out


def _teacher_library_teacher_issued_counts(cursor, teacher_id, level_id):
    """Map library_book_id -> active issues count for teacher at level."""
    ensure_library_book_student_issues_table(cursor)
    out = {}
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return out
    cursor.execute(
        """
        SELECT library_book_id, COUNT(*) AS cnt
        FROM library_book_student_issues
        WHERE teacher_id = %s AND academic_level_id = %s AND status = 'issued'
        GROUP BY library_book_id
        """,
        (teacher_id, level_id),
    )
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            out[int(row.get('library_book_id') or 0)] = int(row.get('cnt') or 0)
        else:
            out[int(row[0] or 0)] = int(row[1] or 0)
    return out


def _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, book_id=None):
    """Stock-in movement IDs for copies allocated to this teacher at a class."""
    ensure_library_book_teacher_distributions_table(cursor)
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return []
    sql = """
        SELECT DISTINCT stock_movement_id
        FROM library_book_teacher_distributions
        WHERE teacher_id = %s AND academic_level_id = %s
          AND stock_movement_id IS NOT NULL
    """
    params = [teacher_id, level_id]
    if book_id is not None:
        try:
            book_id = int(book_id)
            sql += ' AND library_book_id = %s'
            params.append(book_id)
        except (TypeError, ValueError):
            pass
    cursor.execute(sql, tuple(params))
    out = []
    for row in cursor.fetchall() or []:
        mid = row.get('stock_movement_id') if isinstance(row, dict) else row[0]
        if mid is not None:
            try:
                out.append(int(mid))
            except (TypeError, ValueError):
                pass
    return out


def _teacher_library_count_teacher_batch_copy_units(cursor, teacher_id, level_id, book_id):
    """Count copy units linked to this teacher's stock-in batches for a book at a class."""
    mov_ids = _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, book_id)
    if not mov_ids:
        return 0
    ensure_library_book_copy_units_table(cursor)
    placeholders = ','.join(['%s'] * len(mov_ids))
    cursor.execute(
        f"""
        SELECT COUNT(*) AS c FROM library_book_copy_units
        WHERE library_book_id = %s AND academic_level_id = %s
          AND stock_in_movement_id IN ({placeholders})
        """,
        (int(book_id), int(level_id), *mov_ids),
    )
    row = cursor.fetchone()
    if isinstance(row, dict):
        return int(row.get('c') or 0)
    return int(row[0] or 0) if row else 0


def _teacher_library_count_teacher_batch_in_stock(cursor, teacher_id, level_id, book_id):
    """In-stock copy units in this teacher's batches for a book at a class."""
    mov_ids = _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, book_id)
    if not mov_ids:
        return 0
    ensure_library_book_copy_units_table(cursor)
    placeholders = ','.join(['%s'] * len(mov_ids))
    cursor.execute(
        f"""
        SELECT COUNT(*) AS c FROM library_book_copy_units
        WHERE library_book_id = %s AND academic_level_id = %s
          AND status = 'in_stock'
          AND stock_in_movement_id IN ({placeholders})
        """,
        (int(book_id), int(level_id), *mov_ids),
    )
    row = cursor.fetchone()
    if isinstance(row, dict):
        return int(row.get('c') or 0)
    return int(row[0] or 0) if row else 0


def _teacher_library_auto_register_copy_unit(cursor, teacher_id, level_id, book_id, copy_code):
    """
    Register a copy reference in the teacher's allocated batch when it is not yet in the system.
    Returns (True, payload dict) or (False, error message).
    """
    code = (copy_code or '').strip().upper()
    if not code:
        return False, 'Enter a book reference number.'
    if _library_parse_copy_code_index(code) is None:
        return False, f'Reference {code} is invalid (use format A001–Z999).'
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
        book_id = int(book_id)
    except (TypeError, ValueError):
        return False, 'Invalid teacher, class, or book.'
    quota = _teacher_library_teacher_book_quota(cursor, teacher_id, level_id)
    allocated = quota.get(book_id, 0)
    if allocated < 1:
        return False, 'No copies of this book were allocated to you by the library.'
    mov_ids = _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, book_id)
    if not mov_ids:
        return False, 'Could not find your library allocation batch for this book.'
    movement_id = mov_ids[0]
    ensure_library_book_copy_units_table(cursor)
    cursor.execute(
        """
        SELECT id, library_book_id, academic_level_id, status, stock_in_movement_id
        FROM library_book_copy_units
        WHERE UPPER(TRIM(copy_code)) = %s
        LIMIT 1
        """,
        (code,),
    )
    existing = cursor.fetchone()
    if existing:
        if isinstance(existing, dict):
            ex_book = int(existing.get('library_book_id') or 0)
            ex_level = int(existing.get('academic_level_id') or 0)
            ex_status = (existing.get('status') or '').strip()
            ex_mov = existing.get('stock_in_movement_id')
        else:
            ex_book = int(existing[1] or 0)
            ex_level = int(existing[2] or 0)
            ex_status = (existing[3] or '').strip()
            ex_mov = existing[4] if len(existing) > 4 else None
        try:
            ex_mov = int(ex_mov) if ex_mov is not None else None
        except (TypeError, ValueError):
            ex_mov = None
        if ex_book != book_id or ex_level != level_id:
            return False, f'Reference {code} is already registered to another book or class.'
        if ex_mov in mov_ids:
            if ex_status == 'in_stock':
                return True, {'copy_code': code, 'auto_registered': False, 'already_registered': True}
            if ex_status == 'issued':
                return False, f'Reference {code} is already issued to a student.'
            return False, f'Reference {code} is not available (status: {ex_status or "unknown"}).'
        return False, (
            f'Reference {code} is registered in the library but not in your allocated batch. '
            f'Ask the librarian to allocate it to you.'
        )
    batch_count = _teacher_library_count_teacher_batch_copy_units(
        cursor, teacher_id, level_id, book_id,
    )
    if batch_count >= allocated:
        in_stock = _teacher_library_count_teacher_batch_in_stock(
            cursor, teacher_id, level_id, book_id,
        )
        if in_stock < 1:
            return False, (
                f'All {allocated} copies in your allocation are already registered and issued. '
                f'No copies are available to issue. Record a return first if a student returned a book.'
            )
        return False, (
            f'All {allocated} copy references in your allocation are already registered. '
            f'Use one of your {in_stock} available reference(s) still in stock, or record a return first.'
        )
    cursor.execute(
        """
        INSERT INTO library_book_copy_units
            (copy_code, library_book_id, academic_level_id, status, stock_in_movement_id)
        VALUES (%s, %s, %s, 'in_stock', %s)
        """,
        (code, book_id, level_id, movement_id),
    )
    return True, {
        'copy_code': code,
        'auto_registered': True,
        'book_id': book_id,
        'movement_id': movement_id,
    }


def _teacher_library_teacher_can_issue_copy(cursor, teacher_id, level_id, book_id, copy_code):
    """True if this copy belongs to a stock-in batch allocated to the teacher."""
    code = (copy_code or '').strip().upper()
    if not code:
        return False
    mov_ids = _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, book_id)
    if not mov_ids:
        return False
    ensure_library_book_copy_units_table(cursor)
    placeholders = ','.join(['%s'] * len(mov_ids))
    cursor.execute(
        f"""
        SELECT 1 FROM library_book_copy_units
        WHERE UPPER(TRIM(copy_code)) = %s
          AND library_book_id = %s
          AND academic_level_id = %s
          AND stock_in_movement_id IN ({placeholders})
        LIMIT 1
        """,
        (code, int(book_id), int(level_id), *mov_ids),
    )
    return bool(cursor.fetchone())


def _teacher_library_books_for_level(cursor, teacher_id, level_id):
    """Books allocated to this teacher at this class (current session), with copy refs."""
    ensure_library_book_teacher_distributions_table(cursor)
    ensure_library_book_copy_units_table(cursor)
    ensure_library_book_student_issues_table(cursor)
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return []
    quota = _teacher_library_teacher_book_quota(cursor, teacher_id, level_id)
    if not quota:
        return []
    issued_map = _teacher_library_teacher_issued_counts(cursor, teacher_id, level_id)
    book_ids = sorted(quota.keys())
    placeholders = ','.join(['%s'] * len(book_ids))
    cursor.execute(
        f"""
        SELECT lb.id AS book_id,
               UPPER(TRIM(lb.book_name)) AS book_name,
               lb.subject_id,
               UPPER(TRIM(COALESCE(s.subject_name, ''))) AS subject_name,
               UPPER(TRIM(COALESCE(s.subject_code, ''))) AS subject_code
        FROM library_books lb
        LEFT JOIN subjects s ON s.id = lb.subject_id
        WHERE lb.id IN ({placeholders})
          AND COALESCE(lb.library_status, 'active') = 'active'
        ORDER BY lb.book_name ASC
        """,
        tuple(book_ids),
    )
    books = []
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            bid = int(row.get('book_id') or 0)
            book_name = (row.get('book_name') or '').strip()
            subject_id = row.get('subject_id')
            subject_name = (row.get('subject_name') or '').strip()
            subject_code = (row.get('subject_code') or '').strip()
        else:
            bid = int(row[0] or 0)
            book_name = (row[1] or '').strip()
            subject_id = row[2] if len(row) > 2 else None
            subject_name = (row[3] or '').strip() if len(row) > 3 else ''
            subject_code = (row[4] or '').strip() if len(row) > 4 else ''
        if not bid:
            continue
        teacher_allocated = quota.get(bid, 0)
        issued_count = issued_map.get(bid, 0)
        available_slots = max(0, teacher_allocated - issued_count)
        mov_ids = _teacher_library_teacher_movement_ids(cursor, teacher_id, level_id, bid)
        copies = []
        if mov_ids:
            placeholders = ','.join(['%s'] * len(mov_ids))
            cursor.execute(
                f"""
                SELECT id, UPPER(TRIM(copy_code)) AS copy_code, status
                FROM library_book_copy_units
                WHERE library_book_id = %s AND academic_level_id = %s
                  AND stock_in_movement_id IN ({placeholders})
                ORDER BY copy_code ASC
                """,
                (bid, level_id, *mov_ids),
            )
            for crow in cursor.fetchall() or []:
                if isinstance(crow, dict):
                    copies.append({
                        'id': int(crow.get('id') or 0),
                        'copy_code': (crow.get('copy_code') or '').strip(),
                        'status': (crow.get('status') or '').strip(),
                    })
                else:
                    copies.append({
                        'id': int(crow[0] or 0),
                        'copy_code': (crow[1] or '').strip(),
                        'status': (crow[2] or '').strip(),
                    })
        copies_in_stock_all = [c for c in copies if c.get('status') == 'in_stock']
        cursor.execute(
            """
            SELECT si.id, si.copy_code, si.student_id, si.issued_at,
                   UPPER(TRIM(st.full_name)) AS student_name
            FROM library_book_student_issues si
            INNER JOIN students st ON st.student_id = si.student_id
            WHERE si.library_book_id = %s AND si.academic_level_id = %s
              AND si.teacher_id = %s AND si.status = 'issued'
            ORDER BY si.issued_at DESC, si.copy_code ASC
            """,
            (bid, level_id, teacher_id),
        )
        active_issues = []
        issued_codes = set()
        for irow in cursor.fetchall() or []:
            if isinstance(irow, dict):
                code = (irow.get('copy_code') or '').strip()
                active_issues.append({
                    'issue_id': int(irow.get('id') or 0),
                    'copy_code': code,
                    'student_id': (irow.get('student_id') or '').strip(),
                    'student_name': (irow.get('student_name') or '').strip(),
                    'issued_at': irow.get('issued_at'),
                    'can_return': True,
                })
            else:
                code = (irow[1] or '').strip()
                active_issues.append({
                    'issue_id': int(irow[0] or 0),
                    'copy_code': code,
                    'student_id': (irow[2] or '').strip(),
                    'student_name': (irow[3] or '').strip() if len(irow) > 3 else '',
                    'issued_at': irow[4] if len(irow) > 4 else None,
                    'can_return': True,
                })
            issued_codes.add(code)
        copies_issued_by_you = [
            {'copy_code': c['copy_code'], 'status': 'issued'}
            for c in copies if c.get('status') == 'issued' and c.get('copy_code') in issued_codes
        ]
        # Only show copy refs within this teacher's allocated pool at this class.
        copies_in_stock = copies_in_stock_all[:available_slots] if available_slots > 0 else []
        copy_code_list = [c['copy_code'] for c in copies_in_stock if c.get('copy_code')]
        books.append({
            'book_id': bid,
            'book_name': book_name,
            'subject_id': subject_id,
            'subject_name': subject_name,
            'subject_code': subject_code,
            'teacher_allocated': teacher_allocated,
            'issued_count': issued_count,
            'available_slots': available_slots,
            'can_issue': available_slots > 0 and len(copy_code_list) > 0,
            'copies_in_stock': copy_code_list,
            'copies_issued': copies_issued_by_you,
            'all_copy_codes': copy_code_list + [i['copy_code'] for i in active_issues],
            'copy_count': teacher_allocated,
            'in_stock_count': len(copy_code_list),
            'active_issues': active_issues,
        })
    return books


def _teacher_books_for_issue(cursor, teacher_id, level_id):
    """Teacher pool at a class, shaped for book-select + ref-code-per-student UI."""
    books_raw = _teacher_library_books_for_level(cursor, teacher_id, level_id)
    out = []
    for book in books_raw:
        bid = int(book.get('book_id') or 0)
        if not bid:
            continue
        copies_in_stock = [
            (c if isinstance(c, str) else (c.get('copy_code') or '')).strip()
            for c in (book.get('copies_in_stock') or [])
            if (c if isinstance(c, str) else (c.get('copy_code') or '')).strip()
        ]
        issues_by_student = {}
        for issue in book.get('active_issues') or []:
            sid = (issue.get('student_id') or '').strip()
            if not sid:
                continue
            issues_by_student[sid.upper()] = {
                'issue_id': int(issue.get('issue_id') or 0),
                'student_id': sid,
                'student_name': (issue.get('student_name') or '').strip(),
                'copy_code': (issue.get('copy_code') or '').strip(),
                'status': 'issued',
                'issued_at': issue.get('issued_at'),
            }
        allocated = int(book.get('teacher_allocated') or 0)
        active = int(book.get('issued_count') or 0)
        copies_issued = [
            (info.get('copy_code') or '').strip()
            for info in issues_by_student.values()
            if (info.get('copy_code') or '').strip()
        ]
        out.append({
            'book_id': bid,
            'book_name': book.get('book_name') or '',
            'subject_name': book.get('subject_name') or '',
            'subject_code': book.get('subject_code') or '',
            'allocated': allocated,
            'active_issues': active,
            'available': max(0, int(book.get('available_slots') or 0)),
            'copies_in_stock': copies_in_stock,
            'copies_issued': copies_issued,
            'issues_by_student': issues_by_student,
            'in_stock_count': len(copies_in_stock),
        })
    return out


def _teacher_library_subject_id_for_copy(cursor, copy_code, level_id):
    """Resolve subject for a copy reference at this class."""
    code = (copy_code or '').strip().upper()
    if not code:
        return None
    try:
        level_id = int(level_id)
    except (TypeError, ValueError):
        return None
    cursor.execute(
        """
        SELECT lb.subject_id
        FROM library_book_copy_units cu
        INNER JOIN library_books lb ON lb.id = cu.library_book_id
        WHERE UPPER(TRIM(cu.copy_code)) = %s AND cu.academic_level_id = %s
        LIMIT 1
        """,
        (code, level_id),
    )
    row = cursor.fetchone()
    if not row:
        return None
    sid = row.get('subject_id') if isinstance(row, dict) else row[0]
    try:
        return int(sid) if sid is not None else None
    except (TypeError, ValueError):
        return None


def _teacher_library_students_with_subject_book(cursor, level_id, subject_id):
    """Student IDs (uppercase) with an active issue for this subject at this class."""
    if subject_id is None:
        return set()
    try:
        level_id = int(level_id)
        subject_id = int(subject_id)
    except (TypeError, ValueError):
        return set()
    ensure_library_book_student_issues_table(cursor)
    cursor.execute(
        """
        SELECT DISTINCT UPPER(TRIM(si.student_id)) AS sid
        FROM library_book_student_issues si
        LEFT JOIN library_books lb ON lb.id = si.library_book_id
        WHERE si.academic_level_id = %s AND si.status = 'issued'
          AND COALESCE(si.subject_id, lb.subject_id) = %s
        """,
        (level_id, subject_id),
    )
    return {
        ((row.get('sid') if isinstance(row, dict) else row[0]) or '').strip()
        for row in (cursor.fetchall() or [])
        if (row.get('sid') if isinstance(row, dict) else row[0])
    }


def _teacher_library_rows_from_books(books, cursor=None, level_id=None):
    """Flat rows: book, subject, copy ref, student issued to (one row per copy in teacher pool)."""
    rows = []
    subject_student_map = {}
    if cursor is not None and level_id is not None:
        subject_ids = {b.get('subject_id') for b in books if b.get('subject_id') is not None}
        for subj_id in subject_ids:
            try:
                subject_student_map[int(subj_id)] = _teacher_library_students_with_subject_book(
                    cursor, level_id, subj_id,
                )
            except (TypeError, ValueError):
                subject_student_map[int(subj_id)] = set()
    for book in books:
        subject_label = (book.get('subject_name') or '').strip()
        code = (book.get('subject_code') or '').strip()
        if subject_label and code:
            subject_label = f'{subject_label} · {code}'
        elif not subject_label:
            subject_label = '—'
        subj_id = book.get('subject_id')
        already_in_subject = subject_student_map.get(int(subj_id), set()) if subj_id is not None else set()
        for issue in book.get('active_issues') or []:
            stu_key = (issue.get('student_id') or '').strip().upper()
            rows.append({
                'book_id': book.get('book_id'),
                'book_name': book.get('book_name') or '',
                'subject_label': subject_label,
                'copy_code': issue.get('copy_code') or '',
                'student_id': issue.get('student_id') or '',
                'student_name': issue.get('student_name') or '',
                'issue_id': issue.get('issue_id'),
                'is_available': False,
                'has_subject_book': bool(stu_key and stu_key in already_in_subject),
            })
        for copy in book.get('copies_in_stock') or []:
            rows.append({
                'book_id': book.get('book_id'),
                'book_name': book.get('book_name') or '',
                'subject_label': subject_label,
                'copy_code': copy.get('copy_code') or '',
                'student_id': '',
                'student_name': '',
                'issue_id': None,
                'is_available': True,
                'has_subject_book': False,
            })
    rows.sort(key=lambda r: ((r.get('book_name') or '').lower(), (r.get('copy_code') or '').lower()))
    return rows


def _teacher_library_student_search_hint(cursor, level_id, query):
    """If query matches a student in another class, return a helpful message."""
    q = (query or '').strip()
    if len(q) < 1:
        return None
    level_name = _teacher_library_level_name(cursor, level_id)
    if not level_name:
        return None
    like_pat = '%' + q.replace('%', '').replace('_', '') + '%'
    cursor.execute(
        """
        SELECT student_id, UPPER(TRIM(full_name)) AS full_name,
               TRIM(COALESCE(current_grade, '')) AS current_grade
        FROM students
        WHERE UPPER(TRIM(student_id)) = UPPER(%s)
           OR UPPER(TRIM(student_id)) LIKE UPPER(%s)
        ORDER BY CASE WHEN UPPER(TRIM(student_id)) = UPPER(%s) THEN 0 ELSE 1 END
        LIMIT 5
        """,
        (q, like_pat, q),
    )
    rows = cursor.fetchall() or []
    if not rows:
        return None
    for row in rows:
        if isinstance(row, dict):
            sid = (row.get('student_id') or '').strip()
            name = (row.get('full_name') or '').strip()
            grade = (row.get('current_grade') or '').strip()
        else:
            sid = (row[0] or '').strip()
            name = (row[1] or '').strip()
            grade = (row[2] or '').strip() if len(row) > 2 else ''
        if not sid:
            continue
        if grade == level_name:
            continue
        return (
            f'{name} ({sid}) is in class {grade or "unknown"}, not {level_name}. '
            f'Open Class books for that class to issue to this student.'
        )
    return None


def _teacher_library_search_students_for_level(cursor, level_id, query, limit=20, subject_id=None):
    """Students in this class matching admission number or name (live search)."""
    q = (query or '').strip()
    if not q:
        return []
    level_name = _teacher_library_level_name(cursor, level_id)
    if not level_name:
        return []
    like_pat = '%' + q.replace('%', '').replace('_', '') + '%'
    prefix_pat = q.replace('%', '').replace('_', '') + '%'
    cursor.execute(
        """
        SELECT s.student_id, UPPER(TRIM(s.full_name)) AS full_name,
               TRIM(COALESCE(s.current_grade, '')) AS current_grade
        FROM students s
        WHERE TRIM(s.current_grade) = %s
          AND (
                UPPER(TRIM(s.student_id)) LIKE UPPER(%s)
                OR UPPER(TRIM(s.full_name)) LIKE UPPER(%s)
              )
        ORDER BY
            CASE WHEN UPPER(TRIM(s.student_id)) LIKE UPPER(%s) THEN 0 ELSE 1 END,
            s.full_name ASC, s.student_id ASC
        LIMIT %s
        """,
        (level_name, like_pat, like_pat, prefix_pat, int(limit)),
    )
    rows = cursor.fetchall() or []
    already_in_subject = (
        _teacher_library_students_with_subject_book(cursor, level_id, subject_id)
        if subject_id is not None else set()
    )
    out = []
    for row in rows:
        if isinstance(row, dict):
            sid = (row.get('student_id') or '').strip()
            out.append({
                'student_id': sid,
                'full_name': (row.get('full_name') or '').strip(),
                'current_grade': (row.get('current_grade') or '').strip(),
                'has_subject_book': sid.upper() in already_in_subject,
            })
        else:
            sid = (row[0] or '').strip()
            out.append({
                'student_id': sid,
                'full_name': (row[1] or '').strip(),
                'current_grade': (row[2] or '').strip() if len(row) > 2 else '',
                'has_subject_book': sid.upper() in already_in_subject,
            })
    return out


def _teacher_library_lookup_student_for_level(cursor, student_id_raw, level_id, subject_id=None):
    """Resolve student by ID if enrolled in this class (current_grade = level_name)."""
    student_id = (student_id_raw or '').strip().upper()
    if not student_id:
        return None, 'Enter a student ID number.'
    level_name = _teacher_library_level_name(cursor, level_id)
    if not level_name:
        return None, 'Class not found.'
    cursor.execute(
        """
        SELECT student_id, UPPER(TRIM(full_name)) AS full_name, current_grade, status
        FROM students
        WHERE UPPER(TRIM(student_id)) = %s
        LIMIT 1
        """,
        (student_id,),
    )
    row = cursor.fetchone()
    if not row:
        return None, 'No student found with that ID.'
    if isinstance(row, dict):
        st_id = (row.get('student_id') or '').strip()
        full_name = (row.get('full_name') or '').strip()
        grade = (row.get('current_grade') or '').strip()
        status = (row.get('status') or '').strip().lower()
    else:
        st_id = (row[0] or '').strip()
        full_name = (row[1] or '').strip()
        grade = (row[2] or '').strip()
        status = (row[3] or '').strip().lower()
    if status in ('expelled', 'alumni', 'transferred', 'suspended'):
        return None, f'Student {st_id} is not in session (status: {status or "unknown"}).'
    grade_trim = (grade or '').strip()
    if grade_trim != level_name and grade_trim.lower() != level_name.lower():
        return None, f'Student {st_id} is in {grade or "unknown class"}, not {level_name}.'
    already_in_subject = (
        _teacher_library_students_with_subject_book(cursor, level_id, subject_id)
        if subject_id is not None else set()
    )
    return {
        'student_id': st_id,
        'full_name': full_name,
        'current_grade': grade,
        'has_subject_book': st_id.upper() in already_in_subject,
    }, None


def _teacher_library_issue_copy_to_student(
    cursor, teacher_id, level_id, copy_code, student_id, notes='', expected_book_id=None,
    auto_register=False,
):
    """Issue one copy unit to a student. Returns (True, payload) or (False, message)."""
    ensure_library_book_student_issues_table(cursor)
    ensure_library_book_copy_units_table(cursor)
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
    except (TypeError, ValueError):
        return False, 'Invalid teacher or class.'
    if not _teacher_library_teacher_can_access_level(cursor, teacher_id, level_id):
        return False, 'You are not assigned to teach this class.'
    code = (copy_code or '').strip().upper()
    if not code:
        return False, 'Select a book reference number.'
    student, err = _teacher_library_lookup_student_for_level(cursor, student_id, level_id)
    if err:
        return False, err
    auto_registered_flag = False

    def _fetch_unit():
        cursor.execute(
            """
            SELECT id, library_book_id, academic_level_id, status
            FROM library_book_copy_units
            WHERE UPPER(TRIM(copy_code)) = %s
            LIMIT 1
            """,
            (code,),
        )
        return cursor.fetchone()

    unit = _fetch_unit()
    if not unit:
        if auto_register and expected_book_id is not None:
            ok_reg, reg = _teacher_library_auto_register_copy_unit(
                cursor, teacher_id, level_id, int(expected_book_id), code,
            )
            if not ok_reg:
                return False, reg
            if isinstance(reg, dict) and reg.get('auto_registered'):
                auto_registered_flag = True
            unit = _fetch_unit()
            if not unit:
                return False, f'Could not register reference {code}.'
        else:
            return False, (
                f'Copy reference {code} was not found in the system. '
                f'Enable auto-register when saving or ask the librarian.'
            )
    if isinstance(unit, dict):
        unit_id = int(unit.get('id') or 0)
        book_id = int(unit.get('library_book_id') or 0)
        unit_level = int(unit.get('academic_level_id') or 0)
        unit_status = (unit.get('status') or '').strip()
    else:
        unit_id = int(unit[0] or 0)
        book_id = int(unit[1] or 0)
        unit_level = int(unit[2] or 0)
        unit_status = (unit[3] or '').strip()
    if unit_level != level_id:
        return False, f'Copy {code} belongs to another class.'
    if expected_book_id is not None:
        try:
            if int(book_id) != int(expected_book_id):
                return False, f'Copy {code} belongs to another book.'
        except (TypeError, ValueError):
            return False, 'Invalid book selection.'
    if unit_status != 'in_stock':
        return False, f'Copy {code} is not available (status: {unit_status or "unknown"}).'
    if not _teacher_library_teacher_can_issue_copy(cursor, teacher_id, level_id, book_id, code):
        return False, f'Copy {code} is not in your allocated batch for this class.'
    quota = _teacher_library_teacher_book_quota(cursor, teacher_id, level_id)
    allocated = quota.get(book_id, 0)
    if allocated < 1:
        return False, 'No copies of this book were allocated to you by the library.'
    issued_map = _teacher_library_teacher_issued_counts(cursor, teacher_id, level_id)
    if issued_map.get(book_id, 0) >= allocated:
        in_stock = _teacher_library_count_teacher_batch_in_stock(
            cursor, teacher_id, level_id, book_id,
        )
        if in_stock < 1:
            return False, (
                'You have already issued all copies allocated to you for this book. '
                'Record a return if a student returned a copy before issuing again.'
            )
        return False, (
            f'You have reached your allocation limit ({allocated} copies). '
            f'{in_stock} reference(s) are still in stock — use those refs only.'
        )
    cursor.execute(
        """
        SELECT 1 FROM library_book_student_issues
        WHERE copy_unit_id = %s AND status = 'issued'
        LIMIT 1
        """,
        (unit_id,),
    )
    if cursor.fetchone():
        return False, f'Copy {code} is already issued to a student.'
    subject_id = None
    cursor.execute(
        """
        SELECT subject_id FROM library_book_teacher_distributions
        WHERE teacher_id = %s AND academic_level_id = %s AND library_book_id = %s
        LIMIT 1
        """,
        (teacher_id, level_id, book_id),
    )
    sub_row = cursor.fetchone()
    if sub_row:
        subject_id = sub_row.get('subject_id') if isinstance(sub_row, dict) else sub_row[0]
    cursor.execute(
        """
        INSERT INTO library_book_student_issues
            (copy_unit_id, copy_code, library_book_id, academic_level_id, subject_id,
             student_id, teacher_id, status, notes)
        VALUES (%s, %s, %s, %s, %s, %s, %s, 'issued', %s)
        """,
        (
            unit_id, code, book_id, level_id, subject_id,
            student['student_id'], teacher_id, (notes or '').strip()[:500] or None,
        ),
    )
    cursor.execute(
        """
        UPDATE library_book_copy_units SET status = 'issued' WHERE id = %s
        """,
        (unit_id,),
    )
    return True, {
        'copy_code': code,
        'student_id': student['student_id'],
        'student_name': student['full_name'],
        'book_id': book_id,
        'auto_registered': auto_registered_flag,
    }


def _teacher_library_return_copy(cursor, teacher_id, issue_id):
    """Return an issued copy. Returns (True, message) or (False, message)."""
    ensure_library_book_student_issues_table(cursor)
    try:
        teacher_id = int(teacher_id)
        issue_id = int(issue_id)
    except (TypeError, ValueError):
        return False, 'Invalid return request.'
    cursor.execute(
        """
        SELECT id, copy_unit_id, copy_code, teacher_id, status
        FROM library_book_student_issues
        WHERE id = %s
        LIMIT 1
        """,
        (issue_id,),
    )
    row = cursor.fetchone()
    if not row:
        return False, 'Issue record not found.'
    if isinstance(row, dict):
        if int(row.get('teacher_id') or 0) != teacher_id:
            return False, 'You can only return books you issued.'
        if (row.get('status') or '') != 'issued':
            return False, 'This book was already returned.'
        unit_id = int(row.get('copy_unit_id') or 0)
        code = (row.get('copy_code') or '').strip()
    else:
        if int(row[3] or 0) != teacher_id:
            return False, 'You can only return books you issued.'
        if (row[4] or '') != 'issued':
            return False, 'This book was already returned.'
        unit_id = int(row[1] or 0)
        code = (row[2] or '').strip()
    cursor.execute(
        """
        UPDATE library_book_student_issues
        SET status = 'returned', returned_at = NOW()
        WHERE id = %s
        """,
        (issue_id,),
    )
    cursor.execute(
        """
        UPDATE library_book_copy_units SET status = 'in_stock' WHERE id = %s
        """,
        (unit_id,),
    )
    return True, f'Copy {code} marked as returned.'


def _teacher_library_search_issued_copies(cursor, teacher_id, level_id, q, limit=25):
    """Live search copies issued by this teacher at this class."""
    ensure_library_book_student_issues_table(cursor)
    q = (q or '').strip().upper()
    if not q:
        return []
    try:
        teacher_id = int(teacher_id)
        level_id = int(level_id)
        limit = max(1, min(int(limit or 25), 50))
    except (TypeError, ValueError):
        return []
    rows = []
    try:
        cursor.execute(
            """
            SELECT
                si.id AS issue_id,
                UPPER(TRIM(si.copy_code)) AS copy_code,
                si.student_id,
                si.academic_level_id,
                si.library_book_id,
                si.issued_at,
                UPPER(TRIM(COALESCE(st.full_name, ''))) AS student_name,
                UPPER(TRIM(COALESCE(lb.book_name, ''))) AS book_name,
                UPPER(TRIM(COALESCE(al.level_name, ''))) AS level_name,
                UPPER(TRIM(COALESCE(al.level_category, ''))) AS level_category
            FROM library_book_student_issues si
            LEFT JOIN students st ON st.student_id = si.student_id
            LEFT JOIN library_books lb ON lb.id = si.library_book_id
            LEFT JOIN academic_levels al ON al.id = si.academic_level_id
            WHERE si.status = 'issued'
              AND si.teacher_id = %s
              AND si.academic_level_id = %s
              AND UPPER(TRIM(si.copy_code)) LIKE %s
            ORDER BY si.copy_code ASC, si.issued_at DESC
            LIMIT %s
            """,
            (teacher_id, level_id, q + '%', limit),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                rows.append({
                    'issue_id': int(row.get('issue_id') or 0),
                    'copy_code': (row.get('copy_code') or '').strip(),
                    'student_id': (row.get('student_id') or '').strip(),
                    'student_name': (row.get('student_name') or '').strip(),
                    'academic_level_id': int(row.get('academic_level_id') or 0),
                    'book_id': int(row.get('library_book_id') or 0),
                    'book_name': (row.get('book_name') or '').strip(),
                    'level_name': (row.get('level_name') or '').strip(),
                    'level_category': (row.get('level_category') or '').strip(),
                    'issued_at': row.get('issued_at'),
                })
            else:
                rows.append({
                    'issue_id': int(row[0] or 0),
                    'copy_code': (row[1] or '').strip(),
                    'student_id': (row[2] or '').strip(),
                    'academic_level_id': int(row[3] or 0),
                    'book_id': int(row[4] or 0),
                    'issued_at': row[5] if len(row) > 5 else None,
                    'student_name': (row[6] or '').strip() if len(row) > 6 else '',
                    'book_name': (row[7] or '').strip() if len(row) > 7 else '',
                    'level_name': (row[8] or '').strip() if len(row) > 8 else '',
                    'level_category': (row[9] or '').strip() if len(row) > 9 else '',
                })
    except Exception as e:
        print(f'_teacher_library_search_issued_copies: {e}')
    return rows


