def _student_display_initials(full_name):
    name = (full_name or '').strip()
    if not name:
        return '?'
    parts = name.split()
    if len(parts) >= 2:
        return (parts[0][0] + parts[-1][0]).upper()
    return name[:2].upper()


def _parent_in_session_student_sql(student_alias='s'):
    """SQL fragment: student considered active for parent portal lists."""
    alias = (student_alias or 's').strip() or 's'
    return (
        f"LOWER(TRIM(COALESCE({alias}.status, 'in session'))) "
        f"IN ('in session', 'active', '')"
    )


def _parent_child_linked_to_email(cursor, student_id, parent_email, user_id=None):
    """True if student_id is linked to this parent portal account."""
    sid = (student_id or '').strip()
    pem = (parent_email or '').strip()
    if not sid:
        return False
    if pem:
        try:
            cursor.execute(
                """
                SELECT 1 FROM parents
                WHERE student_id = %s AND LOWER(TRIM(email)) = LOWER(TRIM(%s))
                LIMIT 1
                """,
                (sid, pem),
            )
            if cursor.fetchone():
                return True
        except Exception:
            pass
    if user_id:
        try:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (int(user_id),),
            )
            ur = cursor.fetchone()
            usid = (ur.get('student_id') if isinstance(ur, dict) else (ur[0] if ur else '')) or ''
            if usid.strip().lower() == sid.lower():
                return True
        except Exception:
            pass
    return False


def _fetch_parent_linked_children(cursor, parent_email, user_id=None):
    """In-session children for parent dashboard switcher."""
    children = []
    pem = (parent_email or '').strip()
    status_clause = _parent_in_session_student_sql('s')
    if pem:
        try:
            cursor.execute(
                f"""
                SELECT s.student_id, s.full_name, s.current_grade, s.gender, s.status,
                       p.full_name AS parent_name, p.phone AS parent_phone
                FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE LOWER(TRIM(p.email)) = LOWER(TRIM(%s))
                  AND {status_clause}
                ORDER BY s.full_name ASC
                """,
                (pem,),
            )
            for row in cursor.fetchall() or []:
                children.append({
                    'student_id': (row.get('student_id') or '').strip(),
                    'full_name': (row.get('full_name') or '').strip(),
                    'current_grade': (row.get('current_grade') or '').strip(),
                    'gender': (row.get('gender') or '').strip(),
                    'status': (row.get('status') or '').strip(),
                    'parent_name': (row.get('parent_name') or '').strip(),
                    'parent_phone': (row.get('parent_phone') or '').strip(),
                })
        except Exception as ex:
            print(f"_fetch_parent_linked_children: {ex}")
    if not children and user_id:
        try:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (user_id,),
            )
            ur = cursor.fetchone()
            usid = (ur.get('student_id') or '').strip() if ur else ''
            if usid:
                cursor.execute(
                    f"""
                    SELECT student_id, full_name, current_grade, gender, status
                    FROM students
                    WHERE student_id = %s AND {_parent_in_session_student_sql()}
                    LIMIT 1
                    """,
                    (usid,),
                )
                sr = cursor.fetchone()
                if sr:
                    children.append({
                        'student_id': (sr.get('student_id') or '').strip(),
                        'full_name': (sr.get('full_name') or '').strip(),
                        'current_grade': (sr.get('current_grade') or '').strip(),
                        'gender': (sr.get('gender') or '').strip(),
                        'status': (sr.get('status') or '').strip(),
                        'parent_name': '',
                        'parent_phone': '',
                    })
        except Exception:
            pass
    return children


def _fetch_parent_guardian_profile(cursor, parent_email, student_id=None):
    """Parent/guardian row for profile dropdown."""
    pem = (parent_email or '').strip()
    sid = (student_id or '').strip()
    row = None
    try:
        if sid:
            cursor.execute(
                """
                SELECT full_name, email, phone, relationship, student_id
                FROM parents WHERE student_id = %s LIMIT 1
                """,
                (sid,),
            )
            row = cursor.fetchone()
        if not row and pem:
            cursor.execute(
                """
                SELECT full_name, email, phone, relationship, student_id
                FROM parents WHERE email = %s ORDER BY id ASC LIMIT 1
                """,
                (pem,),
            )
            row = cursor.fetchone()
    except Exception as ex:
        print(f"_fetch_parent_guardian_profile: {ex}")
        return None
    if not row:
        return {
            'full_name': '',
            'email': pem,
            'phone': '',
            'relationship': 'Guardian',
        }
    return {
        'full_name': (row.get('full_name') or '').strip(),
        'email': (row.get('email') or pem).strip(),
        'phone': (row.get('phone') or '').strip(),
        'relationship': (row.get('relationship') or 'Guardian').strip(),
        'student_id': (row.get('student_id') or '').strip(),
    }


def _attendance_performance_category(pct, total):
    if not total:
        return 'none'
    if pct >= 80:
        return 'excellent'
    if pct >= 60:
        return 'good'
    if pct >= 40:
        return 'fair'
    if pct > 0:
        return 'poor'
    return 'none'


def _fetch_student_term_attendance_points(cursor, student_id, term_id, *, class_mode=True):
    """Return normalized attendance points for one student/term (class days or subject sessions)."""
    from datetime import date as date_type

    sid = (student_id or '').strip()
    if not sid or not term_id:
        return []
    ensure_student_attendance_records_table(cursor)
    ensure_student_attendance_schema(cursor)
    try:
        if class_mode:
            cursor.execute(
                """
                SELECT sar.attendance_date, sar.present
                FROM student_attendance_records sar
                WHERE sar.student_id = %s AND sar.term_id = %s
                  AND COALESCE(sar.subject_id, 0) = 0
                ORDER BY sar.attendance_date ASC
                """,
                (sid, int(term_id)),
            )
        else:
            cursor.execute(
                """
                SELECT sar.attendance_date, sar.present, sar.subject_id,
                       COALESCE(s.subject_name, CONCAT('Subject #', sar.subject_id)) AS subject_name
                FROM student_attendance_records sar
                LEFT JOIN subjects s ON s.id = sar.subject_id
                WHERE sar.student_id = %s AND sar.term_id = %s
                  AND COALESCE(sar.subject_id, 0) > 0
                ORDER BY sar.attendance_date ASC, subject_name ASC
                """,
                (sid, int(term_id)),
            )
        raw_rows = cursor.fetchall() or []
    except Exception as ex:
        print(f"_fetch_student_term_attendance_points: {ex}")
        return []

    pts = []
    for r in raw_rows:
        dt = r.get('attendance_date') if isinstance(r, dict) else r[0]
        pres = r.get('present') if isinstance(r, dict) else r[1]
        d = _coerce_to_date(dt)
        if not d:
            continue
        is_present = bool(int(pres)) if pres is not None else False
        pt = {'date': d, 'present': is_present}
        if not class_mode:
            pt['subject_id'] = r.get('subject_id') if isinstance(r, dict) else (r[2] if len(r) > 2 else 0)
            pt['subject_name'] = (
                (r.get('subject_name') if isinstance(r, dict) else (r[3] if len(r) > 3 else '')) or ''
            ).strip()
        pts.append(pt)
    return pts


def _build_attendance_summary_from_points(pts):
    total = len(pts)
    present = sum(1 for p in pts if p.get('present'))
    absent = total - present
    pct = round(100.0 * present / total, 1) if total else 0.0
    return {
        'total_recorded': total,
        'present': present,
        'absent': absent,
        'pct': pct,
        'category': _attendance_performance_category(pct, total),
    }


def _build_attendance_weekly_from_points(pts):
    from collections import defaultdict

    week_acc = defaultdict(lambda: [0, 0])
    for pt in pts:
        d = pt['date']
        iso = d.isocalendar()
        key = (iso[0], iso[1])
        week_acc[key][1] += 1
        if pt.get('present'):
            week_acc[key][0] += 1
    by_week = []
    for (y, wnum) in sorted(week_acc.keys()):
        pr, tot = week_acc[(y, wnum)]
        pct_w = round(100 * pr / tot, 1) if tot else 0
        by_week.append({
            'label': f'Week {wnum}, {y}',
            'present': pr,
            'total': tot,
            'absent': tot - pr,
            'pct': pct_w,
        })
    return by_week


def _build_attendance_daily_chart_from_points(pts, *, aggregate_by_date=False):
    from collections import defaultdict

    if aggregate_by_date:
        day_acc = defaultdict(lambda: [0, 0])
        for pt in pts:
            day_acc[pt['date']][1] += 1
            if pt.get('present'):
                day_acc[pt['date']][0] += 1
        daily_points = []
        for d in sorted(day_acc.keys()):
            pr, tot = day_acc[d]
            daily_points.append({
                'date_str': d.strftime('%Y-%m-%d'),
                'label': d.strftime('%d %b'),
                'value': round(100.0 * pr / tot, 1) if tot else 0.0,
            })
        return daily_points

    daily_points = []
    for pt in pts:
        d = pt['date']
        daily_points.append({
            'date_str': d.strftime('%Y-%m-%d'),
            'label': d.strftime('%d %b'),
            'value': 100.0 if pt.get('present') else 0.0,
        })
    return daily_points


def _build_attendance_recent_from_points(pts, *, limit=45, include_subject=False):
    recent = []
    for pt in sorted(pts, key=lambda x: x['date'], reverse=True)[:limit]:
        d = pt['date']
        row = {
            'date_str': d.strftime('%Y-%m-%d'),
            'weekday': d.strftime('%a'),
            'display': d.strftime('%a, %d %b %Y'),
            'present': bool(pt.get('present')),
        }
        if include_subject:
            subj = (pt.get('subject_name') or '').strip()
            row['subject_name'] = subj
            row['display'] = d.strftime('%a, %d %b %Y') + (f' · {subj}' if subj else '')
        recent.append(row)
    return recent


def _build_subject_attendance_by_subject(pts):
    from collections import defaultdict

    acc = defaultdict(lambda: {'subject_name': '', 'present': 0, 'total': 0})
    for pt in pts:
        sid = int(pt.get('subject_id') or 0)
        if not sid:
            continue
        key = sid
        acc[key]['subject_name'] = (pt.get('subject_name') or f'Subject #{sid}').strip()
        acc[key]['total'] += 1
        if pt.get('present'):
            acc[key]['present'] += 1
    rows = []
    for sid in sorted(acc.keys(), key=lambda k: acc[k]['subject_name'].lower()):
        row = acc[sid]
        tot = row['total']
        pr = row['present']
        rows.append({
            'subject_id': sid,
            'subject_name': row['subject_name'],
            'present': pr,
            'absent': tot - pr,
            'total': tot,
            'pct': round(100.0 * pr / tot, 1) if tot else 0.0,
        })
    rows.sort(key=lambda r: (-r['pct'], r['subject_name'].lower()))
    return rows


def _build_attendance_analytics_bundle(pts, *, recent_limit=45, aggregate_daily=False, include_subject_recent=False):
    summary = _build_attendance_summary_from_points(pts)
    return {
        'summary': summary,
        'by_week': _build_attendance_weekly_from_points(pts),
        'daily_points': _build_attendance_daily_chart_from_points(
            pts, aggregate_by_date=aggregate_daily,
        ),
        'recent_days': _build_attendance_recent_from_points(
            pts, limit=recent_limit, include_subject=include_subject_recent,
        ),
    }


def _spotlight_attendance_summary_for_student(cursor, student_id, term_id=None):
    """Compact class-day attendance stats for parent/student home (current term)."""
    empty = {
        'has_data': False,
        'term_label': '',
        'total_recorded': 0,
        'present': 0,
        'absent': 0,
        'pct': 0.0,
        'category': 'none',
        'recent_weeks': [],
    }
    sid = (student_id or '').strip()
    if not sid:
        return empty
    if not term_id:
        _y, _yn, term_id, term_name = _get_current_academic_year_and_term(cursor)
    else:
        term_name = ''
        cursor.execute("SELECT term_name FROM terms WHERE id = %s LIMIT 1", (int(term_id),))
        tr = cursor.fetchone()
        if tr:
            term_name = (tr.get('term_name') if isinstance(tr, dict) else tr[0]) or ''
    if not term_id:
        return empty
    term_label = term_name or 'Current term'
    pts = _fetch_student_term_attendance_points(cursor, sid, term_id, class_mode=True)
    if not pts:
        return {**empty, 'term_label': term_label}
    bundle = _build_attendance_analytics_bundle(pts, recent_limit=6)
    summary = bundle['summary']
    recent_weeks = []
    for w in bundle['by_week'][-6:]:
        recent_weeks.append({
            'label': w['label'].replace('Week ', 'W').split(',')[0],
            'present': w['present'],
            'total': w['total'],
            'pct': w['pct'],
            'height_pct': max(8, round(w['pct'])) if w['total'] else 8,
        })
    return {
        'has_data': summary['total_recorded'] > 0,
        'term_label': term_label,
        'total_recorded': summary['total_recorded'],
        'present': summary['present'],
        'absent': summary['absent'],
        'pct': summary['pct'],
        'category': summary['category'],
        'recent_weeks': recent_weeks,
    }


