def _spotlight_subject_progress_for_student(cursor, student_id, term_id=None):
    """Per-subject class curriculum coverage for parent dashboard."""
    sid = (student_id or '').strip()
    if not sid:
        return []
    if not term_id:
        _y, _yn, term_id, _tn = _get_current_academic_year_and_term(cursor)
    cursor.execute("SELECT current_grade FROM students WHERE student_id = %s LIMIT 1", (sid,))
    rw = cursor.fetchone()
    grade = (rw.get('current_grade') or '').strip() if rw else ''
    level_id = _spotlight_academic_level_id(cursor, grade)
    if not level_id or not term_id:
        return _spotlight_subjects_for_student(cursor, sid)
    subjects = []
    try:
        cursor.execute(
            """
            SELECT s.id AS subject_id, s.subject_name, COALESCE(s.subject_code, '') AS subject_code
            FROM subject_academic_levels sal
            INNER JOIN subjects s ON s.id = sal.subject_id
            WHERE sal.academic_level_id = %s AND COALESCE(s.status, 'active') = 'active'
            ORDER BY s.subject_name
            """,
            (int(level_id),),
        )
        rows = cursor.fetchall() or []
        seen_ids = set()
        if not rows:
            try:
                cursor.execute(
                    """
                    SELECT DISTINCT s.id AS subject_id, s.subject_name, COALESCE(s.subject_code, '') AS subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE al.level_name = %s AND COALESCE(s.status, 'active') = 'active'
                    ORDER BY s.subject_name
                    """,
                    (grade,),
                )
                rows = cursor.fetchall() or []
            except Exception:
                rows = []
        if not rows:
            base = _spotlight_subjects_for_student(cursor, sid)
            for b in base:
                subjects.append({**b, 'subject_id': None, 'coverage': _subject_session_coverage_empty()})
            return subjects
        for row in rows:
            subj_id = row.get('subject_id')
            if subj_id in seen_ids:
                continue
            seen_ids.add(subj_id)
            cov = _compute_subject_session_coverage(cursor, level_id, subj_id, term_id)
            subjects.append({
                'subject_id': subj_id,
                'subject_name': (row.get('subject_name') or 'Subject').strip(),
                'subject_code': (row.get('subject_code') or '').strip(),
                'coverage': cov,
            })
    except Exception as ex:
        print(f"_spotlight_subject_progress_for_student: {ex}")
        return []
    return subjects


def _parent_class_subject_progress_bundle(cursor, student_id, term_id=None, term_name=None):
    """Structured class subject progress for parent dashboard (list + summary)."""
    sid = (student_id or '').strip()
    empty = {
        'grade': '',
        'term_label': term_name or '',
        'subject_count': 0,
        'subjects_with_data': 0,
        'avg_curriculum_pct': None,
        'total_sessions_done': 0,
        'total_sessions_planned': 0,
        'subjects': [],
    }
    if not sid:
        return empty
    if not term_id or not term_name:
        _y, _yn, term_id, term_name = _get_current_academic_year_and_term(cursor)
    cursor.execute(
        "SELECT current_grade FROM students WHERE student_id = %s LIMIT 1",
        (sid,),
    )
    rw = cursor.fetchone()
    grade = (rw.get('current_grade') or '').strip() if rw else ''
    subjects = _spotlight_subject_progress_for_student(cursor, sid, term_id)
    total_done = 0
    total_planned = 0
    curriculum_pcts = []
    with_data = 0
    for subj in subjects:
        cov = subj.get('coverage') or _subject_session_coverage_empty()
        if cov.get('has_data'):
            with_data += 1
        sd = int(cov.get('sessions_done') or 0)
        sp = int(cov.get('sessions_planned_term') or 0)
        total_done += sd
        total_planned += sp
        cp = cov.get('curriculum_pct')
        if cp is not None:
            curriculum_pcts.append(int(cp))
    avg_curriculum = (
        round(sum(curriculum_pcts) / len(curriculum_pcts))
        if curriculum_pcts else None
    )
    return {
        'grade': grade,
        'term_label': term_name or '',
        'subject_count': len(subjects),
        'subjects_with_data': with_data,
        'avg_curriculum_pct': avg_curriculum,
        'total_sessions_done': total_done,
        'total_sessions_planned': total_planned,
        'subjects': subjects,
    }


def _parent_portal_technician_preview(user_role):
    """Technician using /parent to preview a guardian view (with or without role-switch)."""
    return (user_role or '').lower().strip() == 'technician'


def _parent_dashboard_spotlight_student(
    cursor, *, is_technician, viewing_as_parent, selected_student_id, parent_email, user_id
):
    """One student row for /parent header: technician selection, else users.student_id, else first child by parent email."""
    target_sid = ''
    if is_technician:
        target_sid = (selected_student_id or '').strip()
    else:
        sel = (selected_student_id or '').strip()
        if sel and _parent_child_linked_to_email(cursor, sel, parent_email, user_id=user_id):
            target_sid = sel
        if user_id:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (user_id,),
            )
            ur = cursor.fetchone()
            if ur and (ur.get('student_id') or '').strip():
                target_sid = ur.get('student_id').strip()
        pem = (parent_email or '').strip()
        if not target_sid and pem:
            cursor.execute(
                f"""
                SELECT s.student_id FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE LOWER(TRIM(p.email)) = LOWER(TRIM(%s))
                  AND {_parent_in_session_student_sql('s')}
                ORDER BY s.full_name ASC
                LIMIT 1
                """,
                (pem,),
            )
            fr = cursor.fetchone()
            if fr and (fr.get('student_id') or '').strip():
                target_sid = fr.get('student_id').strip()
    if not target_sid:
        return None

    has_img_col = False
    has_verified_col = False
    try:
        cursor.execute("SHOW COLUMNS FROM students LIKE 'profile_image'")
        has_img_col = bool(cursor.fetchone())
        cursor.execute("SHOW COLUMNS FROM students LIKE 'parent_info_verified'")
        has_verified_col = bool(cursor.fetchone())
    except Exception:
        has_img_col = False
        has_verified_col = False

    verified_sel = ', parent_info_verified' if has_verified_col else ', 0 AS parent_info_verified'
    if has_img_col:
        cursor.execute(
            f"""
            SELECT student_id, full_name, current_grade, gender, date_of_birth, status, profile_image{verified_sel}
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (target_sid,),
        )
    else:
        cursor.execute(
            f"""
            SELECT student_id, full_name, current_grade, gender, date_of_birth, status{verified_sel}
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (target_sid,),
        )
    srow = cursor.fetchone()
    if not srow:
        return None

    dob = srow.get('date_of_birth')
    dob_str = ''
    if dob and hasattr(dob, 'strftime'):
        dob_str = dob.strftime('%d %b %Y')
    elif dob:
        dob_str = str(dob)[:10]

    prof = ''
    if has_img_col:
        prof = (srow.get('profile_image') or '').strip()

    full_name = (srow.get('full_name') or '').strip()
    return {
        'student_id': (srow.get('student_id') or '').strip(),
        'full_name': full_name,
        'current_grade': (srow.get('current_grade') or '').strip(),
        'gender': (srow.get('gender') or '').strip(),
        'status': (srow.get('status') or '').strip(),
        'date_of_birth_formatted': dob_str,
        'profile_image': prof or None,
        'initials': _student_display_initials(full_name),
        'parent_info_verified': bool(int(srow.get('parent_info_verified') or 0)),
    }


def _spotlight_academic_level_id(cursor, student_grade):
    """Resolve academic_levels.id for a grade label (tolerates level_status vs status)."""
    if not (student_grade or '').strip():
        return None
    g = student_grade.strip()
    attempts = [
        (
            """
            SELECT al.id FROM academic_levels al
            WHERE al.level_name = %s AND COALESCE(al.level_status, 'active') = 'active'
            LIMIT 1
            """,
            (g,),
        ),
        (
            """
            SELECT al.id FROM academic_levels al
            WHERE al.level_name = %s AND COALESCE(al.status, 'active') = 'active'
            LIMIT 1
            """,
            (g,),
        ),
        (
            "SELECT al.id FROM academic_levels al WHERE al.level_name = %s LIMIT 1",
            (g,),
        ),
    ]
    for sql, params in attempts:
        try:
            cursor.execute(sql, params)
            r = cursor.fetchone()
            if r and r.get('id'):
                return r.get('id')
        except Exception:
            continue
    return None


def _spotlight_fee_balance_for_student(cursor, student_id):
    """Active fee structure + payments for one student (aligned with parent_student_fees)."""
    base = {
        'has_structure': False,
        'fee_name': None,
        'total_amount': 0.0,
        'total_paid': 0.0,
        'balance': 0.0,
    }
    st = None
    try:
        cursor.execute(
            """
            SELECT current_grade, LOWER(TRIM(COALESCE(student_category, ''))) AS student_category
            FROM students WHERE student_id = %s LIMIT 1
            """,
            (student_id,),
        )
        st = cursor.fetchone()
    except Exception:
        try:
            cursor.execute(
                "SELECT current_grade FROM students WHERE student_id = %s LIMIT 1",
                (student_id,),
            )
            st = cursor.fetchone()
        except Exception:
            return base
    if not st:
        return base
    student_grade = (st.get('current_grade') or '').strip()
    student_category = (st.get('student_category') or '').strip().lower() if isinstance(st, dict) else ''
    if not student_grade:
        return base

    academic_level_id = _spotlight_academic_level_id(cursor, student_grade)
    if not academic_level_id:
        return base

    fee_structure_result = None
    try:
        if student_category == 'self sponsored':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND (fs.category = 'self sponsored' OR fs.category = 'both')
                ORDER BY
                  CASE WHEN fs.category = 'self sponsored' THEN 1 WHEN fs.category = 'both' THEN 2 ELSE 3 END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        elif student_category == 'sponsored':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND (fs.category = 'sponsored' OR fs.category = 'both')
                ORDER BY
                  CASE WHEN fs.category = 'sponsored' THEN 1 WHEN fs.category = 'both' THEN 2 ELSE 3 END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        elif student_category == 'both':
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                ORDER BY
                  CASE
                    WHEN fs.category = 'both' THEN 1
                    WHEN fs.category = 'self sponsored' THEN 2
                    WHEN fs.category = 'sponsored' THEN 3
                    ELSE 4
                  END,
                  fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
        else:
            cursor.execute(
                """
                SELECT fs.id, fs.fee_name, fs.total_amount, fs.status
                FROM fee_structures fs
                WHERE fs.academic_level_id = %s
                  AND fs.status = 'active'
                  AND fs.category = 'both'
                ORDER BY fs.created_at DESC
                LIMIT 1
                """,
                (academic_level_id,),
            )
            fee_structure_result = cursor.fetchone()
    except Exception as ex:
        print(f"_spotlight_fee_balance_for_student fee_structure: {ex}")
        return base

    if not fee_structure_result:
        return base

    total_amount = float(fee_structure_result.get('total_amount', 0) or 0)
    cursor.execute(
        """
        SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
        FROM student_payments WHERE student_id = %s
        """,
        (student_id,),
    )
    pr = cursor.fetchone()
    total_paid = float(pr.get('total_paid', 0) if pr else 0)
    balance = total_amount - total_paid
    return {
        'has_structure': True,
        'fee_name': fee_structure_result.get('fee_name') or 'Fees',
        'total_amount': total_amount,
        'total_paid': total_paid,
        'balance': balance,
    }


def _spotlight_pocket_money_for_student(cursor, student_id):
    """Pocket money balance and ledger summary for parent dashboard card."""
    base = {
        'has_account': False,
        'balance': 0.0,
        'total_topped_up': 0.0,
        'total_spent': 0.0,
        'transaction_count': 0,
    }
    sid = (student_id or '').strip()
    if not sid:
        return base
    ensure_student_pocket_money_tables(cursor)
    try:
        cursor.execute(
            """
            SELECT COALESCE(pm.balance, 0) AS balance
            FROM students s
            LEFT JOIN student_pocket_money_accounts pm ON pm.student_id = s.student_id
            WHERE LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
              AND LOWER(TRIM(COALESCE(s.status, 'in session'))) IN ('in session', 'active', '')
            LIMIT 1
            """,
            (sid,),
        )
        row = cursor.fetchone()
        if not row:
            return base
        if isinstance(row, dict):
            balance = float(row.get('balance') or 0)
        else:
            balance = float(row[0] if row else 0)
        base['has_account'] = True
        base['balance'] = balance

        cursor.execute(
            """
            SELECT
                COALESCE(SUM(CASE WHEN direction = 'credit' THEN amount ELSE 0 END), 0) AS total_topped_up,
                COALESCE(SUM(CASE WHEN direction = 'debit' THEN amount ELSE 0 END), 0) AS total_spent,
                COUNT(*) AS transaction_count
            FROM student_pocket_money_transactions
            WHERE student_id = %s
            """,
            (sid,),
        )
        agg = cursor.fetchone()
        if agg:
            if isinstance(agg, dict):
                base['total_topped_up'] = float(agg.get('total_topped_up') or 0)
                base['total_spent'] = float(agg.get('total_spent') or 0)
                base['transaction_count'] = int(agg.get('transaction_count') or 0)
            else:
                base['total_topped_up'] = float(agg[0] if len(agg) > 0 else 0)
                base['total_spent'] = float(agg[1] if len(agg) > 1 else 0)
                base['transaction_count'] = int(agg[2] if len(agg) > 2 else 0)
    except Exception as ex:
        print(f"_spotlight_pocket_money_for_student: {ex}")
    return base


def _spotlight_subjects_for_student(cursor, student_id):
    """Subjects from class assignments for the student's grade, else distinct subjects from marks."""
    out = []
    cursor.execute("SELECT current_grade FROM students WHERE student_id = %s LIMIT 1", (student_id,))
    rw = cursor.fetchone()
    grade = (rw.get('current_grade') or '').strip() if rw else ''
    if grade:
        try:
            cursor.execute("SHOW TABLES LIKE 'teacher_subject_assignments'")
            if cursor.fetchone():
                cursor.execute(
                    """
                    SELECT DISTINCT s.subject_name, COALESCE(s.subject_code, '') AS subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE al.level_name = %s
                    ORDER BY s.subject_name
                    """,
                    (grade,),
                )
                for r in cursor.fetchall() or []:
                    out.append(
                        {
                            'subject_name': (r.get('subject_name') or 'Subject').strip(),
                            'subject_code': (r.get('subject_code') or '').strip(),
                        }
                    )
        except Exception as ex:
            print(f"_spotlight_subjects_for_student tsa: {ex}")
    if not out:
        try:
            cursor.execute(
                """
                SELECT DISTINCT sub.subject_name, COALESCE(sub.subject_code, '') AS subject_code
                FROM student_marks sm
                INNER JOIN subjects sub ON sub.id = sm.subject_id
                WHERE sm.student_id = %s
                ORDER BY sub.subject_name
                """,
                (student_id,),
            )
            for r in cursor.fetchall() or []:
                out.append(
                    {
                        'subject_name': (r.get('subject_name') or 'Subject').strip(),
                        'subject_code': (r.get('subject_code') or '').strip(),
                    }
                )
        except Exception:
            pass
    return out


def _parse_dob_submitted(value):
    """Parse HTML date or common formats to a date object."""
    if not value:
        return None
    s = str(value).strip()
    for fmt in ('%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y'):
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            continue
    return None


def lookup_account_for_password_reset(email):
    """Find account by email: employees first, then users (parent/student). Returns id, email, full_name, account_type."""
    email_norm = normalize_login_email(email)
    if not email_norm:
        return None
    connection = get_db_connection()
    if not connection:
        return None
    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id, full_name, email FROM employees
                WHERE LOWER(TRIM(email)) = %s AND status IN ('pending approval', 'active')
            """, (email_norm,))
            row = cursor.fetchone()
            if row:
                return {
                    'account_type': 'employee',
                    'id': row['id'],
                    'full_name': (row.get('full_name') or '').strip(),
                    'email': (row.get('email') or email_norm).strip(),
                }
            cursor.execute("""
                SELECT id, full_name, email, role FROM users
                WHERE LOWER(TRIM(email)) = %s AND role IN ('parent', 'student')
            """, (email_norm,))
            row = cursor.fetchone()
            if row:
                role = (row.get('role') or '').strip()
                if role not in ('parent', 'student'):
                    return None
                return {
                    'account_type': role,
                    'id': row['id'],
                    'full_name': (row.get('full_name') or '').strip(),
                    'email': (row.get('email') or email_norm).strip(),
                }
            return None
    except Exception as e:
        print(f"lookup_account_for_password_reset: {e}")
        return None
    finally:
        try:
            connection.close()
        except Exception:
            pass


def _fetch_integration_email_dict():
    """SMTP settings saved under Integration Settings → Email."""
    connection = get_db_connection()
    if not connection:
        return {}
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT settings_json FROM integration_settings WHERE integration_type = %s LIMIT 1",
                ('email',),
            )
            row = cursor.fetchone()
            if not row:
                return {}
            js = row.get('settings_json') if isinstance(row, dict) else row[0]
            data = json.loads(js or '{}')
            return data if isinstance(data, dict) else {}
    except Exception as e:
        print(f"_fetch_integration_email_dict: {e}")
        return {}
    finally:
        try:
            connection.close()
        except Exception:
            pass


def apply_mail_config_from_env_and_integration():
    """
    Flask-Mail reads app.config. Merge .env with integration_settings email (SMTP),
    so password reset works when credentials are only in the dashboard.
    """
    app.config['MAIL_SERVER'] = os.environ.get('MAIL_SERVER', app.config.get('MAIL_SERVER', 'smtp.gmail.com'))
    try:
        app.config['MAIL_PORT'] = int(os.environ.get('MAIL_PORT', app.config.get('MAIL_PORT', 587)))
    except (TypeError, ValueError):
        app.config['MAIL_PORT'] = 587
    app.config['MAIL_USE_TLS'] = os.environ.get('MAIL_USE_TLS', 'True').lower() in ['true', '1', 'yes']
    app.config['MAIL_USE_SSL'] = os.environ.get('MAIL_USE_SSL', 'False').lower() in ['true', '1', 'yes']
    app.config['MAIL_USERNAME'] = os.environ.get('MAIL_USERNAME', '')
    app.config['MAIL_PASSWORD'] = os.environ.get('MAIL_PASSWORD', '')
    app.config['MAIL_DEFAULT_SENDER'] = os.environ.get(
        'MAIL_DEFAULT_SENDER', app.config.get('MAIL_DEFAULT_SENDER', 'noreply@modernschool.com')
    )

    integ = _fetch_integration_email_dict()
    smtp_user = (integ.get('smtp_username') or '').strip()
    smtp_pass = (integ.get('smtp_password') or '').strip()
    if smtp_user and smtp_pass:
        app.config['MAIL_SERVER'] = (integ.get('smtp_server') or 'smtp.gmail.com').strip() or 'smtp.gmail.com'
        try:
            app.config['MAIL_PORT'] = int(integ.get('smtp_port') or 587)
        except (TypeError, ValueError):
            app.config['MAIL_PORT'] = 587
        port = int(app.config['MAIL_PORT'])
        utls = integ.get('use_tls')
        if utls is None:
            utls = port != 465
        if isinstance(utls, bool):
            app.config['MAIL_USE_TLS'] = utls
        else:
            app.config['MAIL_USE_TLS'] = str(utls).lower() in ('true', '1', 'yes')
        app.config['MAIL_USE_SSL'] = port == 465 and not app.config['MAIL_USE_TLS']
        app.config['MAIL_USERNAME'] = smtp_user
        app.config['MAIL_PASSWORD'] = smtp_pass
        app.config['MAIL_DEFAULT_SENDER'] = (integ.get('from_email') or smtp_user).strip()
    # Flask-Mail caches configuration at init time; refresh extension state after any update.
    try:
        mail.init_app(app)
    except Exception:
        pass

    if smtp_user and smtp_pass:
        return True
    return bool((app.config.get('MAIL_USERNAME') or '').strip())


def normalize_school_domain(raw):
    """Normalize portal base URL / domain (https://host, no trailing slash or path)."""
    val = (raw or '').strip()
    if not val:
        return ''
    val = val.rstrip('/')
    if not re.match(r'^https?://', val, re.I):
        val = 'https://' + val.lstrip('/')
    try:
        from urllib.parse import urlparse
        parsed = urlparse(val)
        if not parsed.netloc:
            return ''
        scheme = (parsed.scheme or 'https').lower()
        if scheme not in ('http', 'https'):
            scheme = 'https'
        return f'{scheme}://{parsed.netloc}'
    except Exception:
        return ''


def get_public_app_base_url():
    """
    Public portal base URL for links in emails/SMS and QR codes.
    Priority: APP_DOMAIN / PORTAL_BASE_URL (.env) → school_domain (system settings) → current request host.
    """
    raw = (os.environ.get('APP_DOMAIN') or os.environ.get('PORTAL_BASE_URL') or '').strip().rstrip('/')
    if raw:
        normalized = normalize_school_domain(raw)
        if normalized:
            return normalized
    try:
        db_domain = normalize_school_domain((get_school_settings() or {}).get('school_domain') or '')
        if db_domain:
            return db_domain
    except Exception:
        pass
    if has_request_context():
        try:
            return request.url_root.rstrip('/')
        except Exception:
            pass
    return ''


def public_portal_url(endpoint, **values):
    """Absolute URL for parent/staff portal pages (honours APP_DOMAIN when set)."""
    path = url_for(endpoint, **values)
    base = get_public_app_base_url()
    if base:
        if not path.startswith('/'):
            path = '/' + path
        return base + path
    if has_request_context():
        return url_for(endpoint, _external=True, **values)
    return path


def _portal_qr_data_url(url, box_size=6, border=2):
    """PNG data URL for a scannable QR code (parent portal links on printed reports)."""
    target = (url or '').strip()
    if not target:
        return ''
    with _PORTAL_QR_CACHE_LOCK:
        cached = _PORTAL_QR_CACHE.get(target)
        if cached is not None:
            return cached
    try:
        import base64
        import io

        import qrcode

        qr = qrcode.QRCode(
            version=None,
            error_correction=qrcode.constants.ERROR_CORRECT_M,
            box_size=box_size,
            border=border,
        )
        qr.add_data(target)
        qr.make(fit=True)
        img = qr.make_image(fill_color='black', back_color='white')
        buf = io.BytesIO()
        img.save(buf, format='PNG')
        data_url = 'data:image/png;base64,' + base64.b64encode(buf.getvalue()).decode('ascii')
    except Exception as ex:
        print(f'_portal_qr_data_url: {ex}')
        data_url = ''
    with _PORTAL_QR_CACHE_LOCK:
        if len(_PORTAL_QR_CACHE) >= _PORTAL_QR_CACHE_MAX:
            # Drop an arbitrary old entry to bound memory
            try:
                _PORTAL_QR_CACHE.pop(next(iter(_PORTAL_QR_CACHE)))
            except StopIteration:
                pass
        _PORTAL_QR_CACHE[target] = data_url
    return data_url


def _parent_portal_setup_urls(student_id):
    """Login and setup-wizard URLs for a given admission ID."""
    sid = (student_id or '').strip()
    login_url = public_portal_url('login', role='parent', admission=sid)
    setup_url = public_portal_url('parent_portal_setup', admission=sid)
    portal_home = get_public_app_base_url() or login_url.rsplit('/login', 1)[0]
    return {
        'portal_home': portal_home,
        'login_url': login_url,
        'setup_url': setup_url,
    }


def _send_integration_sms(phone, message):
    """Send one SMS via Africa's Talking when Integration Settings → SMS is configured."""
    phone = (phone or '').strip()
    if not phone:
        return False, 'no phone'
    txt = (message or '').strip()[:480]
    if not txt:
        return False, 'empty message'
    integ = _load_integration_data_communication()
    flags = _communication_channel_flags(integ)
    if not flags.get('sms'):
        return False, 'SMS not configured'
    sm = integ.get('sms') or {}
    prov = (sm.get('provider') or '').lower()
    api_key = (sm.get('api_key') or '').strip()
    sender_id = (sm.get('sender_id') or '').strip() or 'INFO'
    if not ('africa' in prov or prov == 'africastalking'):
        return False, 'SMS provider not supported'
    username = (sm.get('username') or sm.get('account_username') or '').strip()
    if not username or not api_key:
        return False, "Africa's Talking username/API key missing"
    try:
        import urllib.parse
        import urllib.request

        data = urllib.parse.urlencode(
            {
                'username': username,
                'to': phone,
                'message': txt,
                'from': sender_id,
            }
        ).encode()
        req = urllib.request.Request(
            'https://api.africastalking.com/version1/messaging',
            data=data,
            headers={
                'apiKey': api_key,
                'Content-Type': 'application/x-www-form-urlencoded',
                'Accept': 'application/json',
            },
            method='POST',
        )
        with urllib.request.urlopen(req, timeout=25) as resp:
            _ = resp.read()
        return True, ''
    except Exception as ex:
        print(f"_send_integration_sms: {ex}")
        return False, str(ex)


def _send_integration_whatsapp(phone, subject, message):
    """Send one WhatsApp text via Cloud API when Integration Settings → WhatsApp is configured."""
    phone = re.sub(r'\D', '', (phone or '').strip())
    if not phone:
        return False, 'no phone'
    txt = f"*{subject}*\n{message}"[:1000] if subject else (message or '')[:1000]
    if not txt.strip():
        return False, 'empty message'
    integ = _load_integration_data_communication()
    flags = _communication_channel_flags(integ)
    if not flags.get('whatsapp'):
        return False, 'WhatsApp not configured'
    wa = integ.get('whatsapp') or {}
    token = (wa.get('api_key') or wa.get('access_token') or '').strip()
    phone_id = (wa.get('phone_number_id') or wa.get('phone_number') or '').strip()
    if not token or not phone_id or len(phone) < 7:
        return False, 'WhatsApp access token or phone number id missing'
    try:
        import urllib.request

        graph_url = f'https://graph.facebook.com/v18.0/{phone_id}/messages'
        payload = json.dumps(
            {
                'messaging_product': 'whatsapp',
                'to': phone,
                'type': 'text',
                'text': {'body': txt},
            }
        ).encode('utf-8')
        req = urllib.request.Request(
            graph_url,
            data=payload,
            headers={
                'Authorization': f'Bearer {token}',
                'Content-Type': 'application/json',
            },
            method='POST',
        )
        with urllib.request.urlopen(req, timeout=25) as resp:
            _ = resp.read()
        return True, ''
    except Exception as ex:
        print(f"_send_integration_whatsapp: {ex}")
        return False, str(ex)


