                                    if not ok:
                                        error = (
                                            'Could not send the verification email. Ask the school to check email settings, '
                                            'or try again later.'
                                        )
                                    else:
                                        connection.commit()
                                        _clear_employee_password_reset_session()
                                        session['pwd_reset_email'] = result
                                        session['pwd_reset_account_type'] = 'employee'
