@app.route('/reset-password', methods=['GET', 'POST'])
def reset_password():
    """Legacy URL — redirect to the role-specific reset page when possible."""
    account_type = (session.get('pwd_reset_account_type') or request.args.get('role') or '').strip().lower()
    routes = {
        'employee': 'employee_reset_password',
        'student': 'student_reset_password',
        'parent': 'parent_reset_password',
    }
    if account_type in routes:
        return redirect(url_for(routes[account_type]))
    flash('Start from the password reset link for your role on the sign-in page.', 'info')
    return redirect(url_for('login'))


@app.route('/logout')
def logout():
    try:
        unregister_active_employee_session()
    except Exception:
        pass
    session.clear()
    flash('You have been logged out successfully.', 'success')
    return redirect(url_for('home'))

@app.route('/dashboard/parent')
@login_required
def dashboard_parent():
    """Parent dashboard - accessible to parents and technicians"""
    user_role = session.get('role', '').lower()
    viewing_as = session.get('viewing_as_role', '')
    
    # Parents and technicians (parent portal preview with student picker)
    if user_role not in ('parent', 'technician'):
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))
    
    is_technician = _parent_portal_technician_preview(user_role)
    # Technicians on /parent always use parent UI; role-switch may also set viewing_as_role
    current_view_role = 'parent' if is_technician else user_role
    if is_technician and viewing_as != 'parent':
        session['viewing_as_role'] = 'parent'
    
    # Get parent's email from session
    parent_email = session.get('email', '')
    
    # For technicians, fetch all students for selection
    all_students = []
    selected_student_id = (request.args.get('student_id', '') or session.get('parent_view_student_id', '')).strip()
    
    if is_technician:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status,
                               p.full_name as parent_name, p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE LOWER(TRIM(COALESCE(s.status, 'in session'))) IN (
                            'in session', 'active', ''
                        )
                        ORDER BY s.full_name ASC
                    """)
                    all_students = cursor.fetchall()
            except Exception as e:
                print(f"Error fetching students for technician: {e}")
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass
        
        # If a student is selected, use that student's parent email
        if selected_student_id:
            session['parent_view_student_id'] = selected_student_id
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute("""
                            SELECT p.email
                            FROM parents p
                            WHERE p.student_id = %s
                            LIMIT 1
                        """, (selected_student_id,))
                        parent_result = cursor.fetchone()
                        if parent_result:
                            parent_email = parent_result.get('email', '') if isinstance(parent_result, dict) else parent_result[0]
                except Exception as e:
                    print(f"Error fetching parent email: {e}")
                finally:
                    if connection:
                        try:
                            connection.close()
                        except:
                            pass
    
    if selected_student_id and not is_technician:
        session['parent_view_student_id'] = selected_student_id

    # Parent home (/parent): spotlight student + analytics (fees, subjects, exams).
    spotlight_student = None
    spotlight_fee = None
    spotlight_pocket_money = None
    spotlight_subjects = []
    spotlight_subject_progress = []
    parent_class_progress = {
        'grade': '',
        'term_label': '',
        'subject_count': 0,
        'subjects_with_data': 0,
        'avg_curriculum_pct': None,
        'total_sessions_done': 0,
        'total_sessions_planned': 0,
        'subjects': [],
    }
    spotlight_attendance = None
    parent_children = []
    parent_guardian = None
    current_term_name = None
    current_term_id = None
    spotlight_conn = get_db_connection()
    if spotlight_conn:
        try:
            with spotlight_conn.cursor() as spotlight_cursor:
                if not is_technician:
                    parent_children = _fetch_parent_linked_children(
                        spotlight_cursor, parent_email, session.get('user_id')
                    )
                elif all_students:
                    for st in all_students:
                        if not st:
                            continue
                        if isinstance(st, dict):
                            parent_children.append({
                                'student_id': (st.get('student_id') or '').strip(),
                                'full_name': (st.get('full_name') or '').strip(),
                                'current_grade': (st.get('current_grade') or '').strip(),
                                'gender': '',
                                'status': (st.get('status') or 'in session').strip(),
                                'parent_name': (st.get('parent_name') or '').strip(),
                                'parent_phone': '',
                            })
                        else:
                            parent_children.append({
                                'student_id': (st[1] if len(st) > 1 else '') or '',
                                'full_name': (st[2] if len(st) > 2 else '') or '',
                                'current_grade': (st[3] if len(st) > 3 else '') or '',
                                'gender': '',
                                'status': 'in session',
                                'parent_name': '',
                                'parent_phone': '',
                            })

                _yid, _yname, current_term_id, current_term_name = _get_current_academic_year_and_term(
                    spotlight_cursor
                )

                raw = _parent_dashboard_spotlight_student(
                    spotlight_cursor,
                    is_technician=is_technician,
                    viewing_as_parent=is_technician or (viewing_as == 'parent'),
                    selected_student_id=selected_student_id,
                    parent_email=parent_email,
                    user_id=session.get('user_id'),
                )
                if raw:
                    row = dict(raw)
                    row['student_photo_url'] = None
                    if row.get('profile_image'):
                        try:
                            row['student_photo_url'] = url_for('static', filename=str(row['profile_image']))
                        except Exception:
                            row['student_photo_url'] = None
                    row.pop('profile_image', None)
                    spotlight_student = row
                    sid = spotlight_student.get('student_id')
                    parent_guardian = _fetch_parent_guardian_profile(
                        spotlight_cursor, parent_email, sid
                    )
                    if sid:
                        try:
                            spotlight_fee = _spotlight_fee_balance_for_student(spotlight_cursor, sid)
                        except Exception as fe:
                            print(f"dashboard_parent spotlight fee: {fe}")
                            spotlight_fee = {'has_structure': False}
                        try:
                            spotlight_pocket_money = _spotlight_pocket_money_for_student(
                                spotlight_cursor, sid
                            )
                        except Exception as pme:
                            print(f"dashboard_parent spotlight pocket money: {pme}")
                            spotlight_pocket_money = {'has_account': False}
                        try:
                            parent_class_progress = _parent_class_subject_progress_bundle(
                                spotlight_cursor, sid, current_term_id, current_term_name
                            )
                            spotlight_subject_progress = parent_class_progress.get('subjects') or []
                            spotlight_subjects = [
                                {
                                    'subject_name': s.get('subject_name'),
                                    'subject_code': s.get('subject_code'),
                                }
                                for s in spotlight_subject_progress
                            ]
                        except Exception as se:
                            print(f"dashboard_parent spotlight subjects: {se}")
                            spotlight_subject_progress = []
                            spotlight_subjects = []
                            parent_class_progress = {
                                'grade': (spotlight_student or {}).get('current_grade', ''),
                                'term_label': current_term_name or '',
                                'subject_count': 0,
                                'subjects_with_data': 0,
                                'avg_curriculum_pct': None,
                                'total_sessions_done': 0,
                                'total_sessions_planned': 0,
                                'subjects': [],
                            }
                        try:
                            spotlight_attendance = _spotlight_attendance_summary_for_student(
                                spotlight_cursor, sid, current_term_id
                            )
                        except Exception as ae:
                            print(f"dashboard_parent spotlight attendance: {ae}")
                            spotlight_attendance = None
        except Exception as e:
            print(f"dashboard_parent spotlight: {e}")
            spotlight_student = None
        finally:
            try:
                spotlight_conn.close()
            except Exception:
                pass

    if not parent_guardian:
        parent_guardian = {
            'full_name': session.get('full_name', 'Parent'),
            'email': parent_email,
            'phone': '',
            'relationship': 'Guardian',
        }

    library_student_id = (selected_student_id or '').strip()
    if not library_student_id and spotlight_student:
        library_student_id = (spotlight_student.get('student_id') or '').strip()
    pocket_money_student_id = library_student_id
    exam_progress_student_id = library_student_id
    class_exam_results_student_id = library_student_id

    parent_calendar_notifications = []
    parent_hub_notifications = []
    notify_sid = library_student_id or None
    if notify_sid or parent_email or session.get('user_id'):
        notif_conn = get_db_connection()
        if notif_conn:
            try:
                with notif_conn.cursor() as notif_cursor:
                    ensure_academic_calendar_activities_table(notif_cursor)
                    ensure_academic_calendar_activity_levels_table(notif_cursor)
                    notif_conn.commit()
                    parent_hub_notifications = _fetch_parent_hub_notifications(
                        notif_cursor,
                        parent_email,
                        notify_sid,
                        user_id=session.get('user_id'),
                    )
                    parent_calendar_notifications = [
                        n for n in parent_hub_notifications if n.get('type') == 'calendar'
                    ]
            except Exception as nfe:
                print(f"dashboard_parent calendar notifications: {nfe}")
            finally:
                try:
                    notif_conn.close()
                except Exception:
                    pass

    return render_template('dashboards/dashboard_parent.html',
                         is_technician=is_technician,
                         current_view_role=current_view_role,
                         all_students=all_students if is_technician else [],
                         is_technician_parent_preview=is_technician,
                         selected_student_id=selected_student_id,
                         library_student_id=library_student_id,
                         pocket_money_student_id=pocket_money_student_id,
                         exam_progress_student_id=exam_progress_student_id,
                         class_exam_results_student_id=class_exam_results_student_id,
                         class_subject_progress_student_id=library_student_id,
                         parent_children=parent_children,
                         parent_guardian=parent_guardian,
                         current_term_name=current_term_name,
                         spotlight_student=spotlight_student,
                         spotlight_fee=spotlight_fee,
                         spotlight_pocket_money=spotlight_pocket_money,
                         spotlight_subjects=spotlight_subjects,
                         spotlight_subject_progress=spotlight_subject_progress,
                         parent_class_progress=parent_class_progress,
                         spotlight_attendance=spotlight_attendance,
                         parent_calendar_notifications=parent_calendar_notifications,
                         parent_hub_notifications=parent_hub_notifications,
                         mpesa_daraja_enabled=_get_daraja_settings_from_flag(),
                         mpesa_sandbox_confirm=_mpesa_sandbox_manual_confirm_enabled())

@app.route('/dashboard/parent/student-fees')
@app.route('/parent/student-fees')
@login_required
def parent_student_fees():
    """Parent view of their children's fees — full structure, items, and payment history."""
    user_role = session.get('role', '').lower()
    viewing_as = session.get('viewing_as_role', '')
    parent_email = session.get('email', '')

    if user_role != 'parent' and not (user_role == 'technician' and viewing_as == 'parent'):
        if user_role != 'technician':
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
    
    # For technicians, fetch all students for selection
    all_students = []
    selected_student_id = request.args.get('student_id', '') or session.get('parent_view_student_id', '')
    
    if user_role == 'technician' and viewing_as == 'parent':
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status,
                               p.full_name as parent_name, p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE s.status = 'in session'
                        ORDER BY s.full_name ASC
                    """)
                    all_students = cursor.fetchall()
            except Exception as e:
                print(f"Error fetching students for technician: {e}")
            finally:
                if connection:
                    try:
                        connection.close()
                    except:
                        pass
        
        # If a student is selected, use that student's parent email
        if selected_student_id:
            session['parent_view_student_id'] = selected_student_id
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute("""
                            SELECT p.email
                            FROM parents p
                            WHERE p.student_id = %s
                            LIMIT 1
                        """, (selected_student_id,))
                        parent_result = cursor.fetchone()
                        if parent_result:
                            parent_email = parent_result.get('email', '') if isinstance(parent_result, dict) else parent_result[0]
                except Exception as e:
                    print(f"Error fetching parent email: {e}")
                finally:
                    if connection:
                        try:
                            connection.close()
                        except:
                            pass
    
    children = []
    student_ids = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                if parent_email:
                    for ch in _parent_list_linked_children(cursor, parent_email):
                        student_ids.append(ch['student_id'])
                elif user_role == 'technician' and selected_student_id:
                    student_ids.append(selected_student_id.strip())

                if selected_student_id:
                    sel = selected_student_id.strip()
                    if student_ids:
                        student_ids = [s for s in student_ids if s == sel]
                    elif user_role == 'technician':
                        student_ids = [sel]

                for sid in student_ids:
                    detail = _fetch_parent_child_fee_details(cursor, sid)
                    if detail:
                        children.append(detail)
        except Exception as e:
            print(f"parent_student_fees: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading fees information. Please try again.', 'error')
        finally:
            try:
                connection.close()
            except Exception:
                pass

    pocket_money_student_id = (selected_student_id or '').strip()
    if not pocket_money_student_id and len(children) == 1:
        pocket_money_student_id = (children[0].get('student_id') or '').strip()

    return render_template('dashboards/parent_student_fees.html',
                         children=children,
                         is_technician=user_role == 'technician',
                         current_view_role=viewing_as if user_role == 'technician' and viewing_as else user_role,
                         all_students=all_students if user_role == 'technician' and viewing_as == 'parent' else [],
                         selected_student_id=selected_student_id,
                         pocket_money_student_id=pocket_money_student_id,
                         mpesa_daraja_enabled=_get_daraja_settings_from_flag(),
                         mpesa_sandbox_confirm=_mpesa_sandbox_manual_confirm_enabled())

