def _fetch_curriculum_coordinator_dashboard_analytics(cursor):
    """School-wide snapshot for the coordinator dashboard (current term when available)."""
    out = _curriculum_coordinator_dashboard_analytics_empty()
    try:
        cursor.execute(
            """
            SELECT id, year_name
            FROM academic_years
            WHERE is_current = TRUE AND status = 'active'
            LIMIT 1
            """
        )
        year_row = cursor.fetchone()
        current_academic_year_id = None
        if year_row:
            current_academic_year_id = year_row.get('id') if isinstance(year_row, dict) else year_row[0]
            out['year_name'] = year_row.get('year_name') if isinstance(year_row, dict) else (year_row[1] if len(year_row) > 1 else None)

        current_term_id = None
        if current_academic_year_id:
            cursor.execute(
                """
                SELECT id, term_name
                FROM terms
                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                LIMIT 1
                """,
                (current_academic_year_id,),
            )
            term_row = cursor.fetchone()
            if not term_row:
                cursor.execute(
                    """
                    SELECT id, term_name FROM terms
                    WHERE status = 'active' AND academic_year_id = %s
                    ORDER BY id DESC
                    LIMIT 1
                    """,
                    (current_academic_year_id,),
                )
                term_row = cursor.fetchone()
            if term_row:
                current_term_id = term_row.get('id') if isinstance(term_row, dict) else term_row[0]
                out['term_name'] = term_row.get('term_name') if isinstance(term_row, dict) else (term_row[1] if len(term_row) > 1 else None)

        if not current_term_id:
            cursor.execute(
                """
                SELECT t.id, t.term_name, ay.year_name
                FROM terms t
                JOIN academic_years ay ON t.academic_year_id = ay.id
                WHERE t.status = 'active' AND ay.status = 'active'
                ORDER BY ay.is_current DESC, t.is_current DESC, t.id DESC
                LIMIT 1
                """
            )
            any_term = cursor.fetchone()
            if any_term:
                if isinstance(any_term, dict):
                    current_term_id = any_term.get('id')
                    out['term_name'] = out['term_name'] or any_term.get('term_name')
                    out['year_name'] = out['year_name'] or any_term.get('year_name')
                else:
                    current_term_id = any_term[0] if len(any_term) > 0 else None
                    out['term_name'] = out['term_name'] or (any_term[1] if len(any_term) > 1 else None)
                    out['year_name'] = out['year_name'] or (any_term[2] if len(any_term) > 2 else None)

        if current_term_id is not None:
            out['term_id'] = int(current_term_id)

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM academic_levels
                WHERE COALESCE(level_status, 'active') = 'active'
                """
            )
            r = cursor.fetchone()
            if r:
                out['active_levels_count'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c
                FROM subject_academic_levels sal
                INNER JOIN academic_levels al ON sal.academic_level_id = al.id
                INNER JOIN subjects s ON sal.subject_id = s.id
                WHERE COALESCE(al.level_status, 'active') = 'active'
                  AND COALESCE(s.status, 'active') = 'active'
                """
            )
            r = cursor.fetchone()
            if r:
                out['registered_subject_links'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM students
                WHERE LOWER(TRIM(COALESCE(status, ''))) IN ('in session', 'active')
                """
            )
            r = cursor.fetchone()
            if r:
                out['students_in_session'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
        except Exception:
            pass

        if current_term_id is not None:
            try:
                cursor.execute(
                    "SELECT COUNT(*) AS c FROM exams WHERE term_id = %s",
                    (current_term_id,),
                )
                r = cursor.fetchone()
                if r:
                    out['exam_rows_this_term'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
            except Exception:
                pass
            try:
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c
                    FROM student_marks sm
                    INNER JOIN exams e ON sm.exam_id = e.id
                    WHERE e.term_id = %s AND sm.marks IS NOT NULL
                    """,
                    (current_term_id,),
                )
                r = cursor.fetchone()
                if r:
                    out['marks_entries_this_term'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
            except Exception:
                pass

        try:
            cursor.execute(
                """
                SELECT al.level_name AS ln, COUNT(*) AS c
                FROM students st
                INNER JOIN academic_levels al
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al.level_name))
                WHERE LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                  AND COALESCE(al.level_status, 'active') = 'active'
                GROUP BY al.id, al.level_name
                ORDER BY al.level_name ASC
                """
            )
            for row in cursor.fetchall() or []:
                ln = row.get('ln') if isinstance(row, dict) else (row[0] if row else '')
                cv = row.get('c') if isinstance(row, dict) else (row[1] if len(row) > 1 else 0)
                if ln:
                    out['level_chart']['labels'].append(str(ln).strip()[:48])
                    out['level_chart']['counts'].append(int(cv or 0))
        except Exception:
            pass

        if not out['level_chart']['labels']:
            try:
                cursor.execute(
                    """
                    SELECT TRIM(st.current_grade) AS g, COUNT(*) AS c
                    FROM students st
                    WHERE LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                      AND TRIM(COALESCE(st.current_grade, '')) <> ''
                    GROUP BY TRIM(st.current_grade)
                    ORDER BY c DESC, g ASC
                    LIMIT 24
                    """
                )
                for row in cursor.fetchall() or []:
                    g = row.get('g') if isinstance(row, dict) else (row[0] if row else '')
                    cv = row.get('c') if isinstance(row, dict) else (row[1] if len(row) > 1 else 0)
                    if g:
                        out['level_chart']['labels'].append(str(g).strip()[:48])
                        out['level_chart']['counts'].append(int(cv or 0))
            except Exception:
                pass

        if current_term_id is not None:
            try:
                ensure_subject_exam_total_marks_column(cursor)
                cursor.execute(
                    """
                    SELECT sub.subject_name AS sn,
                           AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                               / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_m,
                           COUNT(*) AS cnt
                    FROM student_marks sm
                    INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                    INNER JOIN subjects sub ON sm.subject_id = sub.id
                    INNER JOIN students st ON st.student_id = sm.student_id
                    WHERE sm.marks IS NOT NULL
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    GROUP BY sub.id, sub.subject_name
                    ORDER BY cnt DESC, sn ASC
                    LIMIT 12
                    """,
                    (current_term_id,),
                )
                for row in cursor.fetchall() or []:
                    sn = row.get('sn') if isinstance(row, dict) else (row[0] if row else '')
                    mean_m = row.get('mean_m') if isinstance(row, dict) else (row[1] if len(row) > 1 else None)
                    if not sn:
                        continue
                    try:
                        mf = round(float(mean_m), 2) if mean_m is not None else 0.0
                    except (TypeError, ValueError):
                        mf = 0.0
                    out['subject_chart']['labels'].append(str(sn).strip()[:40])
                    out['subject_chart']['means'].append(mf)
            except Exception:
                pass

            try:
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c, COALESCE(SUM(sar.present), 0) AS pr
                    FROM student_attendance_records sar
                    INNER JOIN students st ON st.student_id = sar.student_id
                    WHERE sar.term_id = %s
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    """,
                    (int(current_term_id),),
                )
                r = cursor.fetchone()
                if r:
                    c = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
                    pr = int((r.get('pr') if isinstance(r, dict) else r[1]) or 0)
                    out['attendance_rows_this_term'] = c
                    out['attendance_present_this_term'] = pr
                    out['attendance_absent_this_term'] = max(0, c - pr)
                    out['attendance_rate_pct'] = round(100.0 * pr / c, 1) if c else 0.0
            except Exception:
                pass

            try:
                cursor.execute(
                    """
                    SELECT al.level_name AS ln, COUNT(*) AS tot, COALESCE(SUM(sar.present), 0) AS pr
                    FROM student_attendance_records sar
                    INNER JOIN academic_levels al ON sar.academic_level_id = al.id
                    INNER JOIN students st ON st.student_id = sar.student_id
                    WHERE sar.term_id = %s
                      AND LOWER(TRIM(COALESCE(st.status, ''))) IN ('in session', 'active')
                    GROUP BY al.id, al.level_name
                    ORDER BY al.level_name ASC
                    """,
                    (int(current_term_id),),
                )
                for row in cursor.fetchall() or []:
                    ln = row.get('ln') if isinstance(row, dict) else (row[0] if row else '')
                    tot = int((row.get('tot') if isinstance(row, dict) else row[1]) or 0)
                    pr = int((row.get('pr') if isinstance(row, dict) else row[2]) or 0)
                    if ln and tot > 0:
                        pct = round(100.0 * pr / tot, 1)
                        out['attendance_by_level_chart']['labels'].append(str(ln).strip()[:48])
                        out['attendance_by_level_chart']['rates'].append(pct)
            except Exception:
                pass
    except Exception as e:
        import traceback
        print(f"Error computing curriculum coordinator dashboard analytics: {e}")
        print(traceback.format_exc())
        return _curriculum_coordinator_dashboard_analytics_empty()
    return out


def ensure_student_attendance_records_table(cursor):
    """Daily student attendance (per class, term, date)."""
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS student_attendance_records (
                id INT AUTO_INCREMENT PRIMARY KEY,
                student_id VARCHAR(20) NOT NULL,
                attendance_date DATE NOT NULL,
                academic_level_id INT NOT NULL,
                term_id INT NOT NULL,
                subject_id INT NOT NULL DEFAULT 0,
                session_slot VARCHAR(20) NOT NULL DEFAULT '',
                present TINYINT(1) NOT NULL DEFAULT 1,
                recorded_by_employee_id INT NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY unique_student_date_level_term_subject_slot (
                    student_id, attendance_date, academic_level_id, term_id, subject_id, session_slot
                ),
                INDEX idx_student_date (student_id, attendance_date),
                INDEX idx_level_term_date (academic_level_id, term_id, attendance_date),
                INDEX idx_sar_term_recorded (term_id, recorded_by_employee_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        """)
    except Exception as e:
        _schema_ignore_existing(e, 'student_attendance_records table')


def _compute_teacher_dashboard_analytics(cursor, teacher_id, term_id):
    """KPIs for the teacher home dashboard for the current term (marks, attendance, exams)."""
    empty = _teacher_dashboard_analytics_empty()
    try:
        teacher_id = int(teacher_id)
        term_id = int(term_id)
    except (TypeError, ValueError):
        return empty
    if not teacher_id or not term_id:
        return empty
    out = dict(empty)
    try:
        ensure_student_attendance_records_table(cursor)
        ensure_subject_exam_total_marks_column(cursor)
        level_ids = _teacher_dashboard_collect_level_ids(cursor, teacher_id, term_id)

        if level_ids:
            ph = ','.join(['%s'] * len(level_ids))
            # Resolve cohort level: academic_level_id when set, else map current_grade -> academic_levels.
            # (Marks queries must use the same rule or subject means / ranks stay empty.)
            try:
                cursor.execute(
                    f"""
                    SELECT COUNT(DISTINCT s.student_id) AS c
                    FROM students s
                    LEFT JOIN academic_levels al_sg
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al_sg.level_name))
                    WHERE s.status = 'in session'
                      AND COALESCE(s.academic_level_id, al_sg.id) IN ({ph})
                    """,
                    level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['student_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception:
                cursor.execute(
                    f"""
                    SELECT COUNT(DISTINCT s.student_id) AS c
                    FROM students s
                    INNER JOIN academic_levels al
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE s.status = 'in session' AND al.id IN ({ph})
                    """,
                    level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['student_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

            try:
                cursor.execute(
                    f"""
                    SELECT COUNT(*) AS c FROM student_attendance_records sar
                    INNER JOIN students s ON s.student_id = sar.student_id AND s.status = 'in session'
                    LEFT JOIN academic_levels al_sg
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al_sg.level_name))
                    WHERE sar.term_id = %s AND sar.present = 1
                      AND COALESCE(s.academic_level_id, al_sg.id) IN ({ph})
                    """,
                    [term_id] + level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['attendance_present_cohort'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception:
                cursor.execute(
                    f"""
                    SELECT COUNT(*) AS c
                    FROM student_attendance_records sar
                    INNER JOIN students s
                      ON s.student_id = sar.student_id AND s.status = 'in session'
                    INNER JOIN academic_levels al
                      ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE sar.term_id = %s AND sar.present = 1 AND al.id IN ({ph})
                    """,
                    [term_id] + level_ids,
                )
                rr = cursor.fetchone()
                if rr:
                    out['attendance_present_cohort'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

        try:
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM student_attendance_records
                WHERE term_id = %s AND recorded_by_employee_id = %s
                """,
                (term_id, teacher_id),
            )
            rr = cursor.fetchone()
            if rr:
                out['attendance_entries_you_recorded'] = int(
                    (rr.get('c') if isinstance(rr, dict) else rr[0]) or 0
                )
        except Exception as att_rec_e:
            print(f"Teacher dashboard attendance_entries skipped: {att_rec_e}")

        cursor.execute(
            """
            SELECT COUNT(DISTINCT CONCAT(day_of_week,'|',time_slot,'|',academic_level_id,'|',IFNULL(subject_id,0))) AS c
            FROM timetables WHERE teacher_id = %s AND term_id = %s
            """,
            (teacher_id, term_id),
        )
        rr = cursor.fetchone()
        if rr:
            out['timetable_slot_count'] = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)

        out['distinct_class_group_count'] = _teacher_dashboard_class_group_count(
            cursor, teacher_id, term_id
        )

        lesson_stats = _teacher_dashboard_lesson_stats_term(cursor, teacher_id, term_id)
        out['lessons_attended_term'] = lesson_stats.get('lessons_attended_term', 0)
        out['lessons_allocated_term'] = lesson_stats.get('lessons_allocated_term', 0)
        out['attendance_present_cohort'] = out['lessons_attended_term']

        sup_count = 0
        try:
            cursor.execute(
                """
                SELECT COUNT(DISTINCT e.id) AS c FROM exams e
                WHERE e.term_id = %s
                  AND (e.status IS NULL OR e.status != 'cancelled')
                  AND (
                        e.supervisor_id = %s
                        OR EXISTS (
                            SELECT 1 FROM exam_supervisors es
                            WHERE es.exam_id = e.id AND es.supervisor_id = %s
                        )
                      )
                """,
                (term_id, teacher_id, teacher_id),
            )
            rr = cursor.fetchone()
            if rr:
                sup_count = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
        except Exception as sup_e:
            try:
                cursor.execute(
                    """
                    SELECT COUNT(DISTINCT e.id) AS c FROM exams e
                    WHERE e.term_id = %s
                      AND (e.status IS NULL OR e.status != 'cancelled')
                      AND e.supervisor_id = %s
                    """,
                    (term_id, teacher_id),
                )
                rr = cursor.fetchone()
                if rr:
                    sup_count = int((rr.get('c') if isinstance(rr, dict) else rr[0]) or 0)
            except Exception as sup_e2:
                print(f"Teacher dashboard exam supervisor count skipped: {sup_e} / {sup_e2}")
        out['exams_supervise_duty_count'] = sup_count

        try:
            cursor.execute(
                """
                SELECT sub.subject_name, sub.subject_code,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_marks,
                       COUNT(sm.marks) AS mark_count
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.teacher_id = %s
                 AND tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY sub.id, sub.subject_name, sub.subject_code
                ORDER BY sub.subject_name
                """,
                (term_id, teacher_id),
            )
        except Exception:
            cursor.execute(
                """
                SELECT sub.subject_name, sub.subject_code,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS mean_marks,
                       COUNT(sm.marks) AS mark_count
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.teacher_id = %s
                 AND tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY sub.id, sub.subject_name, sub.subject_code
                ORDER BY sub.subject_name
                """,
                (term_id, teacher_id),
            )
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                mean_m = r.get('mean_marks')
                cnt = r.get('mark_count')
                sn = r.get('subject_name') or ''
                sc = r.get('subject_code') or ''
            else:
                mean_m = r[2] if len(r) > 2 else None
                cnt = r[3] if len(r) > 3 else 0
                sn = r[0] if len(r) > 0 else ''
                sc = r[1] if len(r) > 1 else ''
            try:
                mean_f = round(float(mean_m), 2) if mean_m is not None else None
            except (TypeError, ValueError):
                mean_f = None
            out['subject_rows'].append({
                'subject_name': sn,
                'subject_code': sc,
                'mean_marks': mean_f,
                'mark_count': int(cnt or 0),
            })

        try:
            cursor.execute(
                """
                SELECT COALESCE(st.academic_level_id, al_st.id) AS academic_level_id, al.level_name,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m, COUNT(*) AS cnt
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN academic_levels al ON al.id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY COALESCE(st.academic_level_id, al_st.id), al.level_name
                """,
                (term_id,),
            )
        except Exception:
            cursor.execute(
                """
                SELECT al_st.id AS academic_level_id, al.level_name,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m, COUNT(*) AS cnt
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN academic_levels al ON al.id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY al_st.id, al.level_name
                """,
                (term_id,),
            )
        level_avgs = []
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                lid = r.get('academic_level_id')
                lname = r.get('level_name') or ''
                avg_m = r.get('avg_m')
                cnt = r.get('cnt')
            else:
                lid = r[0] if len(r) > 0 else None
                lname = r[1] if len(r) > 1 else ''
                avg_m = r[2] if len(r) > 2 else None
                cnt = r[3] if len(r) > 3 else 0
            try:
                avg_f = float(avg_m) if avg_m is not None else None
            except (TypeError, ValueError):
                avg_f = None
            if lid is not None and avg_f is not None:
                level_avgs.append({
                    'academic_level_id': int(lid),
                    'level_name': lname,
                    'avg_m': avg_f,
                    'cnt': int(cnt or 0),
                })

        level_avgs.sort(key=lambda x: x['avg_m'], reverse=True)
        total_levels = len(level_avgs)
        last_avg = None
        rank_i = 0
        for idx, row in enumerate(level_avgs):
            if last_avg is None or row['avg_m'] < last_avg:
                rank_i = idx + 1
            row['school_rank'] = rank_i
            last_avg = row['avg_m']

        taught_set = set(level_ids)
        for row in level_avgs:
            if row['academic_level_id'] in taught_set:
                out['class_rank_rows'].append({
                    'level_name': row['level_name'],
                    'avg_m': round(row['avg_m'], 2),
                    'mark_count': row['cnt'],
                    'school_rank': row['school_rank'],
                    'levels_compared': total_levels,
                })

        try:
            cursor.execute(
                """
                SELECT tsa.teacher_id,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                LEFT JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.subject_id = sm.subject_id
                 AND tsa.academic_level_id = COALESCE(st.academic_level_id, al_st.id)
                WHERE sm.marks IS NOT NULL
                GROUP BY tsa.teacher_id
                """,
                (term_id,),
            )
        except Exception:
            cursor.execute(
                """
                SELECT tsa.teacher_id,
                       AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                           / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS avg_m
                FROM student_marks sm
                INNER JOIN exams e ON sm.exam_id = e.id AND e.term_id = %s
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                INNER JOIN students st ON st.student_id = sm.student_id AND st.status = 'in session'
                INNER JOIN academic_levels al_st
                  ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al_st.level_name))
                INNER JOIN teacher_subject_assignments tsa
                  ON tsa.subject_id = sm.subject_id AND tsa.academic_level_id = al_st.id
                WHERE sm.marks IS NOT NULL
                GROUP BY tsa.teacher_id
                """,
                (term_id,),
            )
        teacher_avgs = []
        for r in cursor.fetchall() or []:
            tid = r.get('teacher_id') if isinstance(r, dict) else (r[0] if r else None)
            avg_m = r.get('avg_m') if isinstance(r, dict) else (r[1] if len(r) > 1 else None)
            if tid is None:
                continue
            try:
                teacher_avgs.append({'teacher_id': int(tid), 'avg_m': float(avg_m)})
            except (TypeError, ValueError):
                continue
        teacher_avgs.sort(key=lambda x: x['avg_m'], reverse=True)
        out['overall_teachers_count'] = len(teacher_avgs)
        last_t = None
        trank = 0
        for idx, row in enumerate(teacher_avgs):
            if last_t is None or row['avg_m'] < last_t:
                trank = idx + 1
            row['rank'] = trank
            last_t = row['avg_m']
        for row in teacher_avgs:
            if row['teacher_id'] == teacher_id:
                out['overall_mean'] = round(row['avg_m'], 2)
                out['overall_rank'] = row['rank']
                break
    except Exception as e:
        import traceback
        print(f"Error computing teacher dashboard analytics: {e}")
        print(traceback.format_exc())
        # Return partial metrics if some queries succeeded before the failure
        return out
    return out


@app.route('/dashboard/employee')
@login_required
def dashboard_employee():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check if user is a teacher (either actual role or viewing as teacher)
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    
    if user_role not in EMPLOYEE_SUB_ROLES:
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))
    
    # Get employee data for profile picture
    connection = get_db_connection()
    employee_data = {}
    if connection:
        try:
            with connection.cursor() as cursor:
                employee_id = session.get('employee_id') or session.get('user_id')
                cursor.execute("SELECT * FROM employees WHERE id = %s OR employee_id = %s", 
                             (employee_id, employee_id))
                employee = cursor.fetchone()
                if employee:
                    employee_data = employee
        except Exception as e:
            print(f"Error fetching employee data: {e}")
        finally:
            connection.close()
    
    # Check if user is technician (for role switching)
    is_technician = user_role == 'technician'
    current_view_role = session.get('viewing_as_role', user_role)
    current_employee_role = session.get('viewing_as_employee_role', user_role if user_role in EMPLOYEE_SUB_ROLES else 'employee')
    dashboard_content_role = normalize_employee_dashboard_content_role(
        user_role, is_technician, session.get('viewing_as_employee_role')
    )
    technician_portal_preview = _technician_portal_preview_role()
    is_technician_teacher_preview = bool(
        is_technician and technician_portal_preview in ('teacher', 'teachers')
    )
    if technician_portal_preview:
        dashboard_content_role = technician_portal_preview
