@app.route('/dashboard/employee/find-student/<student_id>', methods=['GET'])
@app.route('/dashboard/warden/find-student/<student_id>', methods=['GET'])
@login_required
def teacher_find_student_detail(student_id):
    """Student detail for find-student page; redacts sponsor/parent fields when unauthorized."""
    if not _find_student_portal_access():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500
    try:
        with connection.cursor() as cursor:
            row = _fetch_student_detail_row(cursor, student_id)
            hostel_occupation = _student_hostel_occupation_dict(cursor, student_id)
        if not row:
            return jsonify({'success': False, 'message': 'Student not found.'}), 404
        can_contact = _can_view_student_contact_details()
        payload = _student_row_to_detail_dict(row)
        payload['hostel_occupation'] = hostel_occupation
        if not can_contact:
            payload = _redact_student_contact_fields(payload)
        return jsonify({
            'success': True,
            'student': payload,
            'can_view_contact_details': can_contact,
            'contact_details_restricted': not can_contact,
        })
    except Exception as e:
        print(f"teacher_find_student_detail: {e}")
        return jsonify({'success': False, 'message': 'Error fetching student details.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/find-student/search', methods=['GET'])
@app.route('/dashboard/warden/find-student/search', methods=['GET'])
@login_required
def teacher_find_student_search():
    """Typeahead JSON for find-student page."""
    if not _find_student_portal_access():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403
    q = (request.args.get('q') or '').strip()
    if len(q) < 1:
        return jsonify({'success': True, 'students': []})
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500
    try:
        with connection.cursor() as cursor:
            students = _fetch_find_student_suggestions(cursor, q=q, limit=25)
        return jsonify({'success': True, 'students': students})
    except Exception as e:
        print(f"teacher_find_student_search: {e}")
        return jsonify({'success': False, 'message': 'Search failed'}), 500
    finally:
        connection.close()


# Teacher My Classes Route
@app.route('/dashboard/employee/my-classes')
@login_required
def teacher_my_classes():
    """Teacher's My Classes page - displays timetable with classes and lessons"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check if user is a teacher or technician
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_technician = user_role == 'technician'
    
    if not (is_teacher or is_technician):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get teacher's ID
    if is_technician:
        teacher_id = session.get('viewing_as_employee_id')
        if not teacher_id:
            return render_template('dashboards/teacher_my_classes.html',
                                 role=user_role,
                                 is_technician=True,
                                 teacher_name=None,
                                 staff_employee_number=None,
                                 portal_employee_number=None,
                                 current_term=None,
                                 current_year=None,
                                 timetable_data={},
                                 assignments=[],
                                 days_order=['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'])
    else:
        # Use user_id (database primary key) not employee_id (string like "333333")
        teacher_id = session.get('user_id')
    
    connection = get_db_connection()
    timetable_data = {}
    assignments = []
    teacher_name = None
    staff_employee_number = None
    portal_employee_number = None
    current_term = None
    current_year = None
    
    # Days of the week in order
    days_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get teacher info
                cursor.execute(f"""
                    SELECT emp.id, emp.full_name,
                           {_employee_staff_identity_sql('emp')} AS staff_employee_number,
                           emp.employee_id AS portal_employee_number
                    FROM employees emp
                    WHERE emp.id = %s
                """, (teacher_id,))
                teacher_result = cursor.fetchone()
                if teacher_result:
                    if isinstance(teacher_result, dict):
                        teacher_name = teacher_result.get('full_name', '')
                        staff_employee_number = teacher_result.get('staff_employee_number')
                        portal_employee_number = teacher_result.get('portal_employee_number')
                    else:
                        teacher_name = teacher_result[1] if len(teacher_result) > 1 else ''
                        staff_employee_number = teacher_result[2] if len(teacher_result) > 2 else None
                        portal_employee_number = teacher_result[3] if len(teacher_result) > 3 else None
                
                # Get current academic year
                cursor.execute("""
                    SELECT id, year_name, is_current
                    FROM academic_years
                    WHERE is_current = TRUE AND status = 'active'
                    LIMIT 1
                """)
                current_year_result = cursor.fetchone()
                current_academic_year_id = None
                if current_year_result:
                    current_academic_year_id = current_year_result.get('id') if isinstance(current_year_result, dict) else current_year_result[0]
                    current_year = current_year_result.get('year_name') if isinstance(current_year_result, dict) else current_year_result[1]
                
                # Get current term
                current_term_id = None
                if current_academic_year_id:
                    cursor.execute("""
                        SELECT id, term_name, is_current
                        FROM terms
                        WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                        LIMIT 1
                    """, (current_academic_year_id,))
                    current_term_result = cursor.fetchone()
                    if current_term_result:
                        current_term_id = current_term_result.get('id') if isinstance(current_term_result, dict) else current_term_result[0]
                        current_term = current_term_result.get('term_name') if isinstance(current_term_result, dict) else current_term_result[1]
                
                # Get teacher's subject assignments (academic levels and subjects)
                cursor.execute("""
                    SELECT tsa.id, tsa.academic_level_id, tsa.subject_id,
                           al.level_name, al.level_category,
                           s.subject_name, s.subject_code
                    FROM teacher_subject_assignments tsa
                    LEFT JOIN academic_levels al ON tsa.academic_level_id = al.id
                    LEFT JOIN subjects s ON tsa.subject_id = s.id
                    WHERE tsa.teacher_id = %s
                    ORDER BY al.level_name, s.subject_name
                """, (teacher_id,))
                assignments_results = cursor.fetchall()
                
                for row in assignments_results:
                    if isinstance(row, dict):
                        assignments.append({
                            'id': row.get('id'),
                            'academic_level_id': row.get('academic_level_id'),
                            'subject_id': row.get('subject_id'),
                            'level_name': row.get('level_name', ''),
                            'level_category': row.get('level_category', ''),
                            'subject_name': row.get('subject_name', ''),
                            'subject_code': row.get('subject_code', '')
                        })
                    else:
                        assignments.append({
                            'id': row[0],
                            'academic_level_id': row[1],
                            'subject_id': row[2],
                            'level_name': row[3] if len(row) > 3 else '',
                            'level_category': row[4] if len(row) > 4 else '',
                            'subject_name': row[5] if len(row) > 5 else '',
                            'subject_code': row[6] if len(row) > 6 else ''
                        })

                # Count students currently in session per academic level.
                # Students table stores grade label in current_grade, not academic_level_id.
                in_session_by_level = {}
                cursor.execute("""
                    SELECT al.id AS academic_level_id, COUNT(*) AS in_session_count
                    FROM students st
                    JOIN academic_levels al
                      ON TRIM(LOWER(st.current_grade)) = TRIM(LOWER(al.level_name))
                    WHERE st.status = 'in session'
                    GROUP BY al.id
                """)
                in_session_results = cursor.fetchall()
                for row in in_session_results:
                    if isinstance(row, dict):
                        level_id = row.get('academic_level_id')
                        in_session_count = row.get('in_session_count', 0)
                    else:
                        level_id = row[0] if len(row) > 0 else None
                        in_session_count = row[1] if len(row) > 1 else 0
                    if level_id is not None:
                        in_session_by_level[level_id] = int(in_session_count or 0)
                
                # Get timetable entries for this teacher
                if current_term_id:
                    cursor.execute("""
                        SELECT DISTINCT t.id, t.day_of_week, t.time_slot, t.academic_level_id,
                               al.level_name, al.level_category, t.subject_id,
                               s.subject_name, s.subject_code
                        FROM timetables t
                        LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                        LEFT JOIN subjects s ON t.subject_id = s.id
                        WHERE t.teacher_id = %s AND t.term_id = %s
                        ORDER BY 
                            FIELD(t.day_of_week, 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'),
                            t.time_slot
                    """, (teacher_id, current_term_id))
                    timetable_results = cursor.fetchall()

                    # Organize timetable by day and time
                    for row in timetable_results:
                        if isinstance(row, dict):
                            day = row.get('day_of_week', '')
                            time = row.get('time_slot', '')
                            level_name = row.get('level_name', '')
                            academic_level_id = row.get('academic_level_id')
                            subject_name = row.get('subject_name') or ''
                            subject_code = row.get('subject_code') or ''
                            subject_id = row.get('subject_id')
                        else:
                            day = row[1] if len(row) > 1 else ''
                            time = row[2] if len(row) > 2 else ''
                            level_name = row[4] if len(row) > 4 else ''
                            academic_level_id = row[3] if len(row) > 3 else None
                            subject_id = row[6] if len(row) > 6 else None
                            subject_name = row[7] if len(row) > 7 and row[7] else ''
                            subject_code = row[8] if len(row) > 8 and row[8] else ''
                        
                        if day and time:
                            if day not in timetable_data:
                                timetable_data[day] = {}
                            if time not in timetable_data[day]:
                                timetable_data[day][time] = []

                            # If subject isn't set on this slot, fallback to assignment for same class.
                            if not subject_name and subject_id and assignments:
                                for assignment in assignments:
                                    if assignment.get('academic_level_id') == academic_level_id and assignment.get('subject_id') == subject_id:
                                        subject_name = assignment.get('subject_name', '') or ''
                                        subject_code = assignment.get('subject_code', '') or ''
                                        break

                            timetable_data[day][time].append({
                                'level_name': level_name,
                                'subject_name': subject_name or 'No Subject Assigned',
                                'subject_code': subject_code,
                                'academic_level_id': academic_level_id,
                                'in_session_count': in_session_by_level.get(academic_level_id, 0),
                            })
                
        except Exception as e:
            print(f"Error fetching teacher classes: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading your classes. Please try again.', 'error')
        finally:
            connection.close()
    
    return render_template('dashboards/teacher_my_classes.html',
                         role=user_role,
                         is_technician=is_technician,
                         teacher_name=teacher_name,
                         staff_employee_number=staff_employee_number,
                         portal_employee_number=portal_employee_number,
                         current_term=current_term,
                         current_year=current_year,
                         timetable_data=timetable_data,
                         assignments=assignments,
                         days_order=days_order)


