def _student_fees_has_access():
    """Same gate as student_fees page."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_technician = user_role == 'technician'
    if not is_accountant and not is_principal:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    employee_id = session.get('employee_id') or session.get('user_id')
                    if employee_id:
                        cursor.execute(
                            "SELECT role FROM employees WHERE id = %s OR employee_id = %s",
                            (employee_id, employee_id),
                        )
                        result = cursor.fetchone()
                        if result:
                            db_role = result.get('role') if isinstance(result, dict) else result[0]
                            db_role = (db_role or '').lower()
                            if db_role == 'accountant':
                                is_accountant = True
                            elif db_role == 'head of institution':
                                is_principal = True
            except Exception as e:
                print(f"_student_fees_has_access role: {e}")
            finally:
                connection.close()
    has_view = check_permission_or_role('view_student_fees', ['accountant', 'head of institution'])
    has_manage = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    return is_technician or has_view or has_manage


def _student_fees_level_by_name(cursor):
    level_by_name = {}
    cursor.execute(
        """
        SELECT id, level_name, level_category
        FROM academic_levels
        WHERE level_status = 'active'
        """
    )
    for r in cursor.fetchall() or []:
        ln = r.get('level_name') if isinstance(r, dict) else r[1]
        if not ln:
            continue
        level_by_name[ln] = {
            'id': r.get('id') if isinstance(r, dict) else r[0],
            'level_name': ln,
            'level_category': (r.get('level_category') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')) or '',
        }
    return level_by_name


def _student_fees_payment_status(fee_structure, balance):
    if not fee_structure:
        return 'no_structure'
    if balance <= 0:
        return 'paid'
    deadline_str = fee_structure.get('payment_deadline')
    if deadline_str:
        try:
            deadline_date = datetime.strptime(str(deadline_str).split(' ')[0], '%Y-%m-%d').date()
            if deadline_date < datetime.now().date():
                return 'overdue'
        except Exception:
            pass
    return 'pending'


def _student_fees_row_payload(
    cursor, row, cy, ct, level_by_name,
    structure_cache=None, payments_all=None, payments_by_fs=None,
):
    """One in-session student row for the fees register (JSON-safe)."""
    if isinstance(row, dict):
        student_id = row.get('student_id')
        full_name = row.get('full_name', '')
        current_grade = row.get('current_grade', '') or ''
        student_category = row.get('student_category', '') or ''
        parent_name = row.get('parent_name')
        parent_phone = row.get('parent_phone')
    else:
        student_id = row[1] if len(row) > 1 else row[0]
        full_name = row[2] if len(row) > 2 else ''
        current_grade = (row[3] if len(row) > 3 else '') or ''
        student_category = (row[5] if len(row) > 5 else '') or ''
        parent_name = row[6] if len(row) > 6 else None
        parent_phone = row[7] if len(row) > 7 else None

    academic_level = None
    level_id = None
    if current_grade and current_grade in level_by_name:
        academic_level = dict(level_by_name[current_grade])
        level_id = academic_level.get('id')

    fee_structure = None
    if level_id:
        cache_key = (int(level_id), (student_category or '').lower().strip())
        if structure_cache is not None and cache_key in structure_cache:
            fee_structure = structure_cache[cache_key]
        else:
            fee_structure = _reports_select_fee_structure_for_student(
                cursor, level_id, student_category, cy, ct,
            )
            if structure_cache is not None:
                structure_cache[cache_key] = fee_structure

    if payments_all is not None:
        total_paid_all = float(payments_all.get(str(student_id), 0) or 0)
    else:
        cursor.execute(
            """
            SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
            FROM student_payments
            WHERE student_id = %s
            """,
            (student_id,),
        )
        all_pay = cursor.fetchone()
        total_paid_all = float(
            (all_pay.get('total_paid') if isinstance(all_pay, dict) else all_pay[0]) or 0
        ) if all_pay else 0.0

    carry_forward = 0.0
    previous_term_balance = 0.0
    total_amount_due = 0.0
    balance = 0.0

    if fee_structure:
        fs_id = fee_structure.get('id')
        paid_override = None
        if payments_by_fs is not None and fs_id is not None:
            paid_override = float(payments_by_fs.get((str(student_id), int(fs_id)), 0) or 0)
        amounts = _reports_compute_student_fee_balance(
            cursor, student_id, student_category, level_id, fee_structure,
            paid_amount_override=paid_override,
        )
        if amounts:
            total_amount_due = float(amounts.get('total_amount') or 0)
            balance = float(amounts.get('balance') or 0)
            carry_forward = float(amounts.get('carry_forward') or 0)
            previous_term_balance = float(amounts.get('previous_term_balance') or 0)

    payment_status = _student_fees_payment_status(fee_structure, balance)

    fs_out = None
    if fee_structure:
        fs_out = {
            'id': fee_structure.get('id'),
            'fee_name': fee_structure.get('fee_name', ''),
            'category': fee_structure.get('category', 'both'),
            'payment_deadline': fee_structure.get('payment_deadline'),
            'total_amount': float(fee_structure.get('total_amount') or 0),
            'status': fee_structure.get('status', 'active'),
            'finance_account_id': fee_structure.get('finance_account_id'),
            'finance_account_name': fee_structure.get('finance_account_name') or '',
            'academic_year_id': fee_structure.get('academic_year_id'),
            'academic_year_name': fee_structure.get('academic_year_name') or '',
            'term_id': fee_structure.get('term_id'),
            'term_name': fee_structure.get('term_name') or '',
        }

    return {
        'student_id': student_id,
        'full_name': full_name or '',
        'current_grade': current_grade,
        'student_category': student_category,
        'parent_name': parent_name or '',
        'parent_phone': parent_phone or '',
        'academic_level': academic_level,
        'fee_structure': fs_out,
        'payment_status': payment_status,
        'total_paid': total_paid_all,
        'carry_forward': carry_forward,
        'previous_term_balance': previous_term_balance,
        'total_amount_due': total_amount_due,
        'balance': balance,
    }


STUDENT_FEES_LIST_SORTS = {
    'name_asc': ('s.full_name', 'ASC'),
    'name_desc': ('s.full_name', 'DESC'),
    'id_asc': ('s.student_id', 'ASC'),
    'id_desc': ('s.student_id', 'DESC'),
    'grade_asc': ('s.current_grade', 'ASC'),
    'grade_desc': ('s.current_grade', 'DESC'),
}


def _fetch_student_fees_students_page(cursor, page=1, per_page=50, q='', grade='', category='', sort='name_asc'):
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    q = (q or '').strip()
    grade = (grade or '').strip()
    category = (category or '').strip().lower()
    order_col, order_dir = STUDENT_FEES_LIST_SORTS.get(sort, STUDENT_FEES_LIST_SORTS['name_asc'])

    cy, ct = _reports_current_year_term_ids(cursor)
    level_by_name = _student_fees_level_by_name(cursor)

    where = ["s.status = 'in session'"]
    params = []
    if grade:
        where.append('s.current_grade = %s')
        params.append(grade)
    if category:
        where.append('LOWER(TRIM(COALESCE(s.student_category, ""))) = %s')
        params.append(category)
    if q:
        like = '%' + q + '%'
        where.append(
            '(s.full_name LIKE %s OR s.student_id LIKE %s OR s.current_grade LIKE %s)'
        )
        params.extend([like, like, like])

    where_sql = ' WHERE ' + ' AND '.join(where)

    cursor.execute(f'SELECT COUNT(*) AS c FROM students s{where_sql}', tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)

    cursor.execute(
        f"""
        SELECT s.student_id, s.full_name, s.current_grade, s.status, s.student_category,
               p.full_name AS parent_name, p.phone AS parent_phone
        FROM students s
        LEFT JOIN parents p ON p.id = (
            SELECT p2.id FROM parents p2
            WHERE p2.student_id = s.student_id
            ORDER BY p2.id ASC LIMIT 1
        )
        {where_sql}
        ORDER BY {order_col} {order_dir}, s.student_id ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    rows = list(cursor.fetchall() or [])
    student_ids = []
    for r in rows:
        sid = r.get('student_id') if isinstance(r, dict) else (r[0] if r else None)
        if sid is not None:
            student_ids.append(str(sid))

    payments_all = {}
    payments_by_fs = {}
    if student_ids:
        placeholders = ','.join(['%s'] * len(student_ids))
        cursor.execute(
            f"""
            SELECT student_id, COALESCE(SUM(amount_paid), 0) AS total_paid
            FROM student_payments
            WHERE student_id IN ({placeholders})
            GROUP BY student_id
            """,
            tuple(student_ids),
        )
        for pay in cursor.fetchall() or []:
            if isinstance(pay, dict):
                payments_all[str(pay.get('student_id'))] = float(pay.get('total_paid') or 0)
            else:
                payments_all[str(pay[0])] = float(pay[1] or 0)
        cursor.execute(
            f"""
            SELECT student_id, fee_structure_id, COALESCE(SUM(amount_paid), 0) AS total_paid
            FROM student_payments
            WHERE student_id IN ({placeholders})
            GROUP BY student_id, fee_structure_id
            """,
            tuple(student_ids),
        )
        for pay in cursor.fetchall() or []:
            if isinstance(pay, dict):
                sid = str(pay.get('student_id'))
                fsid = pay.get('fee_structure_id')
                amt = float(pay.get('total_paid') or 0)
            else:
                sid = str(pay[0])
                fsid = pay[1]
                amt = float(pay[2] or 0)
            if fsid is None:
                continue
            try:
                payments_by_fs[(sid, int(fsid))] = amt
            except (TypeError, ValueError):
                continue

    structure_cache = {}
    students = [
        _student_fees_row_payload(
            cursor, r, cy, ct, level_by_name,
            structure_cache=structure_cache,
            payments_all=payments_all,
            payments_by_fs=payments_by_fs,
        )
        for r in rows
    ]
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return {
        'students': students,
        'page': page,
        'per_page': per_page,
        'total': total,
        'pages': pages,
    }


def _fetch_student_fees_stats(cursor):
    cursor.execute(
        """
        SELECT COUNT(*) AS total
        FROM students
        WHERE status = 'in session'
        """
    )
    row = cursor.fetchone() or {}
    total = int(row.get('total') if isinstance(row, dict) else row[0] or 0)
    return {'in_session': total}


def _format_parent_portal_date(value):
    """Short date for parent portal tables."""
    if not value:
        return None
    if hasattr(value, 'strftime'):
        return value.strftime('%d %b %Y')
    text = str(value).strip()
    return text.split(' ')[0] if text else None


def _fetch_parent_child_fee_details(cursor, student_id):
    """Full fee breakdown for one child (parent portal — read-only)."""
    sid = (student_id or '').strip()
    if not sid:
        return None
    cursor.execute(
        """
        SELECT s.id, s.student_id, s.full_name, s.current_grade, s.status, s.student_category,
               p.full_name AS parent_name, p.phone AS parent_phone
        FROM students s
        LEFT JOIN parents p ON s.student_id = p.student_id
        WHERE s.student_id = %s AND s.status = 'in session'
        LIMIT 1
        """,
        (sid,),
    )
    row = cursor.fetchone()
    if not row:
        return None

    cy, ct = _reports_current_year_term_ids(cursor)
    level_by_name = _student_fees_level_by_name(cursor)
    core = _student_fees_row_payload(cursor, row, cy, ct, level_by_name)

    fee_structure = core.get('fee_structure')
    fs_full = None
    level_id = (core.get('academic_level') or {}).get('id')
    student_category = core.get('student_category') or ''
    if level_id:
        fs_full = _reports_select_fee_structure_for_student(
            cursor, level_id, student_category, cy, ct,
        )
    if fs_full and fee_structure:
        fee_structure = {
            **fs_full,
            **fee_structure,
            'start_date': fs_full.get('start_date'),
            'end_date': fs_full.get('end_date'),
            'payment_deadline': fs_full.get('payment_deadline'),
        }
    elif fs_full:
        fee_structure = fs_full

    fee_items = []
    fs_id = (fee_structure or {}).get('id')
    if fs_id:
        cursor.execute(
            """
            SELECT item_name, item_description, amount
            FROM fee_items
            WHERE fee_structure_id = %s
            ORDER BY id ASC
            """,
            (fs_id,),
        )
        for item in cursor.fetchall() or []:
            if isinstance(item, dict):
                fee_items.append({
                    'item_name': (item.get('item_name') or '').strip(),
                    'item_description': (item.get('item_description') or '').strip(),
                    'amount': float(item.get('amount') or 0),
                })
            else:
                fee_items.append({
                    'item_name': (item[0] or '').strip() if len(item) > 0 else '',
                    'item_description': (item[1] or '').strip() if len(item) > 1 else '',
                    'amount': float(item[2] if len(item) > 2 and item[2] else 0),
                })

    ensure_fee_structures_finance_account_column(cursor)
    cursor.execute(
        """
        SELECT sp.id, sp.amount_paid, sp.payment_method, sp.reference_number,
               sp.cheque_number, sp.transaction_id, sp.payment_date, sp.notes,
               sp.created_at, fs.fee_name, fs.category AS fee_category,
               t.term_name, ay.year_name AS academic_year_name,
               e.full_name AS received_by_name
        FROM student_payments sp
        LEFT JOIN fee_structures fs ON sp.fee_structure_id = fs.id
        LEFT JOIN terms t ON fs.term_id = t.id
        LEFT JOIN academic_years ay ON fs.academic_year_id = ay.id
        LEFT JOIN employees e ON sp.received_by = e.id
        WHERE sp.student_id = %s
        ORDER BY sp.payment_date DESC, sp.created_at DESC
        """,
        (sid,),
    )
    payments = []
    for payment in cursor.fetchall() or []:
        if isinstance(payment, dict):
            payment_date = payment.get('payment_date')
            payments.append({
                'id': payment.get('id'),
                'amount_paid': float(payment.get('amount_paid') or 0),
                'payment_date': payment_date,
                'payment_date_formatted': _format_parent_portal_date(payment_date),
                'payment_method': (payment.get('payment_method') or '').strip(),
                'reference_number': (payment.get('reference_number') or '').strip(),
                'cheque_number': (payment.get('cheque_number') or '').strip(),
                'transaction_id': (payment.get('transaction_id') or '').strip(),
                'notes': (payment.get('notes') or '').strip(),
                'fee_name': (payment.get('fee_name') or '').strip(),
                'fee_category': (payment.get('fee_category') or '').strip(),
                'term_name': (payment.get('term_name') or '').strip(),
                'academic_year_name': (payment.get('academic_year_name') or '').strip(),
                'received_by_name': (payment.get('received_by_name') or '').strip(),
            })
        else:
            payment_date = payment[6] if len(payment) > 6 else None
            payments.append({
                'id': payment[0] if len(payment) > 0 else None,
                'amount_paid': float(payment[1] if len(payment) > 1 and payment[1] else 0),
                'payment_method': (payment[2] or '').strip() if len(payment) > 2 else '',
                'reference_number': (payment[3] or '').strip() if len(payment) > 3 else '',
                'cheque_number': (payment[4] or '').strip() if len(payment) > 4 else '',
                'transaction_id': (payment[5] or '').strip() if len(payment) > 5 else '',
                'payment_date': payment_date,
                'payment_date_formatted': _format_parent_portal_date(payment_date),
                'notes': (payment[7] or '').strip() if len(payment) > 7 else '',
                'fee_name': (payment[9] or '').strip() if len(payment) > 9 else '',
                'fee_category': (payment[10] or '').strip() if len(payment) > 10 else '',
                'term_name': (payment[11] or '').strip() if len(payment) > 11 else '',
                'academic_year_name': (payment[12] or '').strip() if len(payment) > 12 else '',
                'received_by_name': (payment[13] or '').strip() if len(payment) > 13 else '',
            })

    fs_display = None
    if fee_structure:
        fs_display = dict(fee_structure)
        fs_display['payment_deadline_formatted'] = _format_parent_portal_date(
            fee_structure.get('payment_deadline'),
        )
        fs_display['start_date_formatted'] = _format_parent_portal_date(
            fee_structure.get('start_date'),
        )
        fs_display['end_date_formatted'] = _format_parent_portal_date(
            fee_structure.get('end_date'),
        )
        cat = (fee_structure.get('category') or 'both').replace('_', ' ').title()
        fs_display['category_label'] = cat

    total_due = float(core.get('total_amount_due') or 0)
    balance = float(core.get('balance') or 0)
    total_paid = float(core.get('total_paid') or 0)
    payment_status = core.get('payment_status') or 'no_structure'
    if payment_status == 'paid':
        status_label = 'Fully paid'
    elif payment_status == 'overdue':
        status_label = 'Overdue'
    elif payment_status == 'pending':
        status_label = 'Payment pending'
    else:
        status_label = 'No fee structure'

    percent_paid = 0
    if total_due > 0:
        paid_on_structure = max(0.0, total_due - balance)
        percent_paid = min(100, int(round((paid_on_structure / total_due) * 100)))

    return {
        'id': core.get('student_id'),
        'student_id': core.get('student_id'),
        'full_name': core.get('full_name'),
        'current_grade': core.get('current_grade'),
        'student_category': (core.get('student_category') or '').strip(),
        'student_category_label': (core.get('student_category') or '—').replace('_', ' ').title(),
        'parent_name': core.get('parent_name') or '',
        'parent_phone': core.get('parent_phone') or '',
        'academic_level': core.get('academic_level'),
        'fee_structure': fs_display,
        'fee_items': fee_items,
        'payments': payments,
        'total_paid': total_paid,
        'total_amount_due': total_due,
        'carry_forward': float(core.get('carry_forward') or 0),
        'previous_term_balance': float(core.get('previous_term_balance') or 0),
        'balance': balance,
        'payment_status': payment_status,
        'payment_status_label': status_label,
        'percent_paid': percent_paid,
    }


def _fetch_pocket_money_summary(cursor):
    """Hero stats: in-session count, students with balance, total pocket money."""
    ensure_student_pocket_money_tables(cursor)
    cursor.execute(
        """
        SELECT COUNT(*) AS c,
               COALESCE(SUM(pm.balance), 0) AS total_balance,
               SUM(CASE WHEN COALESCE(pm.balance, 0) > 0 THEN 1 ELSE 0 END) AS with_balance
        FROM students s
        LEFT JOIN student_pocket_money_accounts pm ON pm.student_id = s.student_id
        WHERE s.status = 'in session'
        """
    )
    row = cursor.fetchone() or {}
    if isinstance(row, dict):
        student_count = int(row.get('c') or 0)
        total_bal = float(row.get('total_balance') or 0)
        with_balance = int(row.get('with_balance') or 0)
    else:
        student_count = int(row[0] if len(row) > 0 else 0)
        total_bal = float(row[1] if len(row) > 1 else 0)
        with_balance = int(row[2] if len(row) > 2 else 0)
    return {
        'student_count': student_count,
        'with_balance_count': with_balance,
        'total_balance_display': f'{total_bal:,.2f}',
    }


def _fetch_parent_student_pocket_money(cursor, student_id):
    """Read-only pocket money balance and recent transactions for parent portal."""
    ensure_student_pocket_money_tables(cursor)
    sid = (student_id or '').strip()
    if not sid:
        return {'balance': 0.0, 'balance_display': '0.00', 'transactions': []}

    cursor.execute(
        """
        SELECT COALESCE(pm.balance, 0) AS pocket_balance
        FROM students s
        LEFT JOIN student_pocket_money_accounts pm ON pm.student_id = s.student_id
        WHERE LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
          AND s.status = 'in session'
        LIMIT 1
        """,
        (sid,),
    )
    bal_row = cursor.fetchone()
    if not bal_row:
        return None
    if isinstance(bal_row, dict):
        balance = float(bal_row.get('pocket_balance') or 0)
    else:
        balance = float(bal_row[0] if bal_row else 0)

    cursor.execute(
        """
        SELECT direction, amount, balance_after, reference_code, payment_method,
               notes, recorded_by_name, created_at
        FROM student_pocket_money_transactions
        WHERE student_id = %s
        ORDER BY created_at DESC, id DESC
        LIMIT 100
        """,
        (sid,),
    )
    transactions = []
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            direction = (row.get('direction') or '').strip().lower()
            try:
                amount = float(row.get('amount') or 0)
            except (TypeError, ValueError):
                amount = 0.0
            try:
                bal_after = float(row.get('balance_after') or 0)
            except (TypeError, ValueError):
                bal_after = 0.0
            ref = (row.get('reference_code') or '').strip()
            method = (row.get('payment_method') or '').strip()
            notes = (row.get('notes') or '').strip()
            recorded_by = (row.get('recorded_by_name') or '').strip()
            created_at = row.get('created_at')
        else:
            direction = (row[0] or '').strip().lower() if len(row) > 0 else ''
            try:
                amount = float(row[1] if len(row) > 1 else 0)
            except (TypeError, ValueError):
                amount = 0.0
            try:
                bal_after = float(row[2] if len(row) > 2 else 0)
            except (TypeError, ValueError):
                bal_after = 0.0
            ref = (row[3] or '').strip() if len(row) > 3 else ''
            method = (row[4] or '').strip() if len(row) > 4 else ''
            notes = (row[5] or '').strip() if len(row) > 5 else ''
            recorded_by = (row[6] or '').strip() if len(row) > 6 else ''
            created_at = row[7] if len(row) > 7 else None
        created_display = ''
        if created_at:
            try:
                created_display = created_at.strftime('%d %b %Y, %H:%M')
            except Exception:
                created_display = str(created_at)[:16]
        transactions.append({
            'direction': direction,
            'direction_label': _pocket_money_direction_label(direction),
            'amount': amount,
            'amount_display': f'{amount:,.2f}',
            'balance_after_display': f'{bal_after:,.2f}',
            'reference_code': ref or '—',
            'payment_method': method or '—',
            'notes': notes,
            'recorded_by_name': recorded_by,
            'created_at_display': created_display or '—',
        })

    return {
        'balance': balance,
        'balance_display': f'{balance:,.2f}',
        'transactions': transactions,
    }


_pocket_money_schema_ensuring = False


def ensure_student_pocket_money_tables(cursor):
    """Per-student pocket money balance and transaction ledger."""
    global _pocket_money_schema_ensuring
    if _pocket_money_schema_ensuring:
        return
    _pocket_money_schema_ensuring = True
    try:
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS student_pocket_money_accounts (
                student_id VARCHAR(20) NOT NULL PRIMARY KEY,
                balance DECIMAL(14,2) NOT NULL DEFAULT 0,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                CONSTRAINT fk_spm_account_student
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                    ON DELETE CASCADE
            ) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS student_pocket_money_transactions (
                id INT AUTO_INCREMENT PRIMARY KEY,
                student_id VARCHAR(20) NOT NULL,
                direction ENUM('credit', 'debit') NOT NULL,
                amount DECIMAL(14,2) NOT NULL,
                balance_after DECIMAL(14,2) NOT NULL,
                reference_code VARCHAR(64) NULL,
                notes VARCHAR(500) NULL,
                recorded_by_name VARCHAR(255) NULL,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                INDEX idx_spm_tx_student (student_id),
                INDEX idx_spm_tx_created (created_at),
                CONSTRAINT fk_spm_tx_student
                    FOREIGN KEY (student_id) REFERENCES students(student_id)
                    ON DELETE CASCADE
            ) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci
        """)
        for col_sql in (
            "ADD COLUMN finance_account_id INT NULL AFTER recorded_by_name",
            "ADD COLUMN payment_method VARCHAR(50) NULL AFTER finance_account_id",
        ):
            col_name = col_sql.split('ADD COLUMN ')[1].split()[0]
            try:
                cursor.execute(
                    f"SHOW COLUMNS FROM student_pocket_money_transactions LIKE '{col_name}'"
                )
                if not cursor.fetchone():
                    cursor.execute(
                        f"ALTER TABLE student_pocket_money_transactions {col_sql}"
                    )
            except Exception as col_err:
                print(f"ensure_student_pocket_money_tables {col_name}: {col_err}")
    except Exception as e:
        print(f"ensure_student_pocket_money_tables: {e}")
    finally:
        _pocket_money_schema_ensuring = False


def _generate_pocket_money_reference(cursor, student_id):
    ensure_student_pocket_money_tables(cursor)
    cursor.execute(
        """
        SELECT reference_code FROM student_pocket_money_transactions
        WHERE reference_code LIKE 'PM-%'
        ORDER BY id DESC LIMIT 1
        """
    )
    row = cursor.fetchone()
    next_num = 1
    if row:
        code = (row.get('reference_code') if isinstance(row, dict) else row[0]) or ''
        m = re.match(r'^PM-(\d+)$', str(code).strip().upper())
        if m:
            next_num = int(m.group(1)) + 1
    return f'PM-{next_num:05d}'


def _fetch_pocket_money_students_page(cursor, page=1, per_page=50, q='', grade='', sort='name_asc'):
    """In-session students with pocket money balances."""
    ensure_student_pocket_money_tables(cursor)
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    q = (q or '').strip()
    grade = (grade or '').strip()
    if sort not in STUDENT_FEES_LIST_SORTS:
        sort = 'name_asc'
    order_col, order_dir = STUDENT_FEES_LIST_SORTS.get(sort, STUDENT_FEES_LIST_SORTS['name_asc'])

    where = ["s.status = 'in session'"]
    params = []
    if grade:
        where.append('s.current_grade = %s')
        params.append(grade)
    if q:
        like = '%' + q + '%'
        where.append(
            '(s.full_name LIKE %s OR s.student_id LIKE %s OR s.current_grade LIKE %s '
            'OR CAST(s.assessment_number AS CHAR) LIKE %s)'
        )
        params.extend([like, like, like, like])

    where_sql = ' WHERE ' + ' AND '.join(where)

    cursor.execute(
        f'SELECT COUNT(*) AS c FROM students s{where_sql}',
        tuple(params),
    )
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)

    cursor.execute(
        f"""
        SELECT s.student_id, s.full_name, s.current_grade, s.assessment_number,
               COALESCE(pm.balance, 0) AS pocket_balance
        FROM students s
        LEFT JOIN student_pocket_money_accounts pm ON pm.student_id = s.student_id
        {where_sql}
        ORDER BY {order_col} {order_dir}, s.student_id ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    students = []
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            sid = (row.get('student_id') or '').strip()
            full_name = (row.get('full_name') or '').strip()
            grade = (row.get('current_grade') or '').strip()
            assessment = (row.get('assessment_number') or '').strip()
            try:
                bal = float(row.get('pocket_balance') or 0)
            except (TypeError, ValueError):
                bal = 0.0
        else:
            sid = (row[0] or '').strip()
            full_name = (row[1] or '').strip()
            grade = (row[2] or '').strip() if len(row) > 2 else ''
            assessment = (row[3] or '').strip() if len(row) > 3 else ''
            try:
                bal = float(row[4] if len(row) > 4 else 0)
            except (TypeError, ValueError):
                bal = 0.0
        students.append({
            'student_id': sid,
            'admission_number': sid,
            'full_name': full_name,
            'current_grade': grade,
            'assessment_number': assessment or '',
            'pocket_balance': bal,
            'pocket_balance_display': f'{bal:,.2f}',
        })

    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    total_balance = sum(float(s.get('pocket_balance') or 0) for s in students)
    return {
        'students': students,
        'page': page,
        'per_page': per_page,
        'total': total,
        'pages': pages,
        'page_balance_total': total_balance,
        'page_balance_total_display': f'{total_balance:,.2f}',
    }


def _top_up_student_pocket_money(
    cursor, student_id, amount, finance_account_id, payment_method,
    reference_code, notes=None, recorded_by_name=None,
):
    """Credit a student's pocket money and post to a Pocket money finance account."""
    from decimal import Decimal, InvalidOperation

    sid = (student_id or '').strip()
    if not sid:
        return False, None, 'Select a student.'
    try:
        amt = Decimal(str(amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, None, 'Enter a valid amount greater than zero.'
    if amt <= 0:
        return False, None, 'Enter a valid amount greater than zero.'

    payment_method = _normalize_supplier_payment_method(payment_method)
    if not payment_method:
        return False, None, 'Select a top-up mode (Cash, Cheque, or Mobile Money).'

    ref = (reference_code or '').strip()
    if not ref:
        return False, None, 'Enter the payment reference number.'
    if len(ref) > 255:
        ref = ref[:255]

    ok_fy, fy_err = _assert_financial_year_writable(cursor)
    if not ok_fy:
        return False, None, fy_err

    ensure_student_pocket_money_tables(cursor)
    ensure_finance_accounts_table(cursor)
    ensure_finance_account_transactions_table(cursor)

    ok_acct, acct, acct_err = _validate_pocket_money_finance_account(
        cursor, finance_account_id, payment_method,
    )
    if not ok_acct:
        return False, None, acct_err or 'Invalid pocket money account.'

    cursor.execute(
        "SELECT student_id FROM students WHERE student_id = %s AND status = 'in session' LIMIT 1",
        (sid,),
    )
    if not cursor.fetchone():
        return False, None, 'Student not found or not in session.'

    cursor.execute(
        """
        INSERT INTO student_pocket_money_accounts (student_id, balance)
        VALUES (%s, 0)
        ON DUPLICATE KEY UPDATE student_id = student_id
        """,
        (sid,),
    )
    cursor.execute(
        """
        UPDATE student_pocket_money_accounts
        SET balance = COALESCE(balance, 0) + %s
        WHERE student_id = %s
        """,
        (amt, sid),
    )
    if cursor.rowcount < 1:
        return False, None, 'Could not update pocket money balance.'

    cursor.execute(
        "SELECT COALESCE(balance, 0) FROM student_pocket_money_accounts WHERE student_id = %s",
        (sid,),
    )
    bal_row = cursor.fetchone()
    if isinstance(bal_row, dict):
        balance_after = float(next(iter(bal_row.values()), 0) or 0)
    else:
        balance_after = float(bal_row[0] if bal_row else 0)

    note_text = (notes or '').strip()
    if len(note_text) > 500:
        note_text = note_text[:500]

    cursor.execute(
        """
        INSERT INTO student_pocket_money_transactions
            (student_id, direction, amount, balance_after, reference_code, notes,
             recorded_by_name, finance_account_id, payment_method)
        VALUES (%s, 'credit', %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            sid, amt, balance_after, ref, note_text or None,
            (recorded_by_name or '').strip() or None,
            int(finance_account_id), payment_method,
        ),
    )
    txn_id = cursor.lastrowid

    ok_credit, credit_err = _credit_finance_account(
        cursor, finance_account_id, amt,
        payment_method=payment_method,
        reference_code=ref,
        description=f'Pocket money top-up — {sid}',
        related_type='student_pocket_money',
        related_id=txn_id,
        recorded_by_name=recorded_by_name,
    )
    if not ok_credit:
        return False, None, credit_err or 'Could not update finance account balance.'

    fa_bal = _fetch_finance_account_ledger_balance(cursor, finance_account_id)

    return True, {
        'student_id': sid,
        'reference_code': ref,
        'amount': float(amt),
        'amount_display': f'{float(amt):,.2f}',
        'balance_after': balance_after,
        'balance_after_display': f'{balance_after:,.2f}',
        'finance_account_id': int(finance_account_id),
        'finance_account_name': acct.get('account_name') if acct else '',
        'finance_account_balance': fa_bal,
        'finance_account_balance_display': f'{fa_bal:,.2f}',
        'payment_method': payment_method,
    }, None


def _pocket_money_direction_label(direction):
    d = (direction or '').strip().lower()
    if d == 'credit':
        return 'Top-up'
    if d == 'debit':
        return 'Withdrawal'
    return (direction or '—').strip().title() or '—'


def _format_pocket_money_transaction_row(row):
    """Normalize a student_pocket_money_transactions row for API/templates."""
    if isinstance(row, dict):
        direction = (row.get('direction') or '').strip().lower()
        try:
            amount = float(row.get('amount') or 0)
        except (TypeError, ValueError):
            amount = 0.0
        try:
            bal_after = float(row.get('balance_after') or 0)
        except (TypeError, ValueError):
            bal_after = 0.0
        ref = (row.get('reference_code') or '').strip()
        method = (row.get('payment_method') or '').strip()
        notes = (row.get('notes') or '').strip()
        recorded_by = (row.get('recorded_by_name') or '').strip()
        created_at = row.get('created_at')
        finance_account_name = (row.get('finance_account_name') or '').strip()
        txn_id = row.get('id')
    else:
        direction = (row[0] or '').strip().lower() if len(row) > 0 else ''
        try:
            amount = float(row[1] if len(row) > 1 else 0)
        except (TypeError, ValueError):
            amount = 0.0
        try:
            bal_after = float(row[2] if len(row) > 2 else 0)
        except (TypeError, ValueError):
            bal_after = 0.0
        ref = (row[3] or '').strip() if len(row) > 3 else ''
        method = (row[4] or '').strip() if len(row) > 4 else ''
        notes = (row[5] or '').strip() if len(row) > 5 else ''
        recorded_by = (row[6] or '').strip() if len(row) > 6 else ''
        created_at = row[7] if len(row) > 7 else None
        finance_account_name = (row[8] or '').strip() if len(row) > 8 else ''
        txn_id = row[9] if len(row) > 9 else None
    created_display = ''
    if created_at:
        try:
            created_display = created_at.strftime('%d %b %Y, %H:%M')
        except Exception:
            created_display = str(created_at)[:16]
    return {
        'id': txn_id,
        'direction': direction,
        'direction_label': _pocket_money_direction_label(direction),
        'amount': amount,
        'amount_display': f'{amount:,.2f}',
        'balance_after': bal_after,
        'balance_after_display': f'{bal_after:,.2f}',
        'reference_code': ref or '—',
        'payment_method': method or '—',
        'notes': notes,
        'recorded_by_name': recorded_by or '—',
        'finance_account_name': finance_account_name or '—',
        'created_at_display': created_display or '—',
    }


def _fetch_student_pocket_money_audit(cursor, student_id, limit=200):
    """Pocket money balance and full audit trail for accountant view."""
    ensure_student_pocket_money_tables(cursor)
    sid = (student_id or '').strip()
    if not sid:
        return None, 'Student is required.'

    cursor.execute(
        """
        SELECT s.student_id, s.full_name, s.current_grade,
               COALESCE(pm.balance, 0) AS pocket_balance
        FROM students s
        LEFT JOIN student_pocket_money_accounts pm ON pm.student_id = s.student_id
        WHERE LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
          AND s.status = 'in session'
        LIMIT 1
        """,
        (sid,),
    )
    st_row = cursor.fetchone()
    if not st_row:
        return None, 'Student not found or not in session.'
    if isinstance(st_row, dict):
        full_name = (st_row.get('full_name') or '').strip()
        grade = (st_row.get('current_grade') or '').strip()
        balance = float(st_row.get('pocket_balance') or 0)
        admission = (st_row.get('student_id') or '').strip()
    else:
        admission = (st_row[0] or '').strip()
        full_name = (st_row[1] or '').strip()
        grade = (st_row[2] or '').strip() if len(st_row) > 2 else ''
        balance = float(st_row[3] if len(st_row) > 3 else 0)

    cursor.execute(
        f"""
        SELECT t.id, t.direction, t.amount, t.balance_after, t.reference_code,
               t.payment_method, t.notes, t.recorded_by_name, t.created_at,
               fa.account_name AS finance_account_name
        FROM student_pocket_money_transactions t
        LEFT JOIN finance_accounts fa ON fa.id = t.finance_account_id
        WHERE t.student_id = %s
        ORDER BY t.created_at DESC, t.id DESC
        LIMIT {int(max(1, min(limit, 500)))}
        """,
        (sid,),
    )
    transactions = [
        _format_pocket_money_transaction_row(row)
        for row in (cursor.fetchall() or [])
    ]
    return {
        'student_id': admission,
        'admission_number': admission,
        'full_name': full_name,
        'current_grade': grade,
        'balance': balance,
        'balance_display': f'{balance:,.2f}',
        'transactions': transactions,
    }, None


def _debit_pocket_money_finance_account(
    cursor, finance_account_id, amount, payment_method, reference_code,
    description, related_type=None, related_id=None, recorded_by_name=None,
    activity_date=None,
):
    """Debit a pocket money finance ledger when paying out to a student."""
    from decimal import Decimal, InvalidOperation

    ok_fy, fy_err = _assert_financial_year_writable(cursor, activity_date)
    if not ok_fy:
        return False, fy_err
    try:
        amt = Decimal(str(amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid payment amount.'
    if amt <= 0:
        return False, 'Enter a valid amount greater than zero.'

    ok, acct, err = _validate_pocket_money_finance_account(
        cursor, finance_account_id, payment_method,
    )
    if not ok:
        return False, err

    fid = int(finance_account_id)
    ensure_finance_account_transactions_table(cursor)
    if related_type and related_id is not None:
        if _finance_ledger_exists(
            cursor, related_type, related_id, 'debit', finance_account_id=fid,
        ):
            return True, acct.get('account_name') if acct else ''

    cursor.execute(
        """
        SELECT COALESCE(current_balance, 0) AS current_balance
        FROM finance_accounts WHERE id = %s LIMIT 1
        """,
        (fid,),
    )
    bal_row = cursor.fetchone()
    if isinstance(bal_row, dict):
        available = Decimal(str(bal_row.get('current_balance') or 0)).quantize(Decimal('0.01'))
    else:
        available = Decimal(str(bal_row[0] if bal_row else 0)).quantize(Decimal('0.01'))
    acct_name = (acct.get('account_name') if acct else '') or 'Account'
    if available < amt:
        return False, _insufficient_funds_message(acct_name, available)

    cursor.execute(
        """
        UPDATE finance_accounts
        SET current_balance = COALESCE(current_balance, 0) - %s
        WHERE id = %s
          AND COALESCE(current_balance, 0) >= %s
        """,
        (amt, fid, amt),
    )
    if cursor.rowcount != 1:
        return False, _insufficient_funds_message(acct_name, available)

    cursor.execute(
        "SELECT COALESCE(current_balance, 0) FROM finance_accounts WHERE id = %s",
        (fid,),
    )
    after_row = cursor.fetchone()
    if isinstance(after_row, dict):
        balance_after = float(next(iter(after_row.values()), 0) or 0)
    else:
        balance_after = float(after_row[0] if after_row else 0)

    cursor.execute(
        """
        INSERT INTO finance_account_transactions
            (finance_account_id, direction, amount, payment_method, reference_code,
             description, related_type, related_id, balance_after, recorded_by_name)
        VALUES (%s, 'debit', %s, %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            fid, amt, payment_method,
            (reference_code or '').strip() or None,
            (description or '').strip() or None,
            related_type, related_id, balance_after,
            (recorded_by_name or '').strip() or None,
        ),
    )
    return True, acct_name


def _withdraw_student_pocket_money(
    cursor, student_id, amount, finance_account_id, payment_method,
    reference_code, notes=None, recorded_by_name=None,
):
    """Debit a student's pocket money and pay out from the pocket money finance account."""
    from decimal import Decimal, InvalidOperation

    sid = (student_id or '').strip()
    if not sid:
        return False, None, 'Select a student.'
    try:
        amt = Decimal(str(amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, None, 'Enter a valid amount greater than zero.'
    if amt <= 0:
        return False, None, 'Enter a valid amount greater than zero.'

    payment_method = _normalize_supplier_payment_method(payment_method)
    if not payment_method:
        return False, None, 'Select a withdrawal mode (Cash, Cheque, or Mobile Money).'

    ref = (reference_code or '').strip()
    if not ref:
        return False, None, 'Enter the payment reference number.'
    if len(ref) > 255:
        ref = ref[:255]

    ok_fy, fy_err = _assert_financial_year_writable(cursor)
    if not ok_fy:
        return False, None, fy_err

    ensure_student_pocket_money_tables(cursor)
    ensure_finance_accounts_table(cursor)
    ensure_finance_account_transactions_table(cursor)

    ok_acct, acct, acct_err = _validate_pocket_money_finance_account(
        cursor, finance_account_id, payment_method,
    )
    if not ok_acct:
        return False, None, acct_err or 'Invalid pocket money account.'

    cursor.execute(
        "SELECT student_id FROM students WHERE student_id = %s AND status = 'in session' LIMIT 1",
        (sid,),
    )
    if not cursor.fetchone():
        return False, None, 'Student not found or not in session.'

    cursor.execute(
        """
        INSERT INTO student_pocket_money_accounts (student_id, balance)
        VALUES (%s, 0)
        ON DUPLICATE KEY UPDATE student_id = student_id
        """,
        (sid,),
    )
    cursor.execute(
        """
        SELECT COALESCE(balance, 0) FROM student_pocket_money_accounts
        WHERE student_id = %s LIMIT 1
        """,
        (sid,),
    )
    bal_row = cursor.fetchone()
    if isinstance(bal_row, dict):
        current_bal = Decimal(str(next(iter(bal_row.values()), 0) or 0)).quantize(Decimal('0.01'))
    else:
        current_bal = Decimal(str(bal_row[0] if bal_row else 0)).quantize(Decimal('0.01'))
    if current_bal < amt:
        return False, None, (
            f'Insufficient pocket money balance. Available: KES {float(current_bal):,.2f}.'
        )

    cursor.execute(
        """
        UPDATE student_pocket_money_accounts
        SET balance = COALESCE(balance, 0) - %s
        WHERE student_id = %s
          AND COALESCE(balance, 0) >= %s
        """,
        (amt, sid, amt),
    )
    if cursor.rowcount < 1:
        return False, None, 'Could not update pocket money balance.'

    cursor.execute(
        "SELECT COALESCE(balance, 0) FROM student_pocket_money_accounts WHERE student_id = %s",
        (sid,),
    )
    bal_row = cursor.fetchone()
    if isinstance(bal_row, dict):
        balance_after = float(next(iter(bal_row.values()), 0) or 0)
    else:
        balance_after = float(bal_row[0] if bal_row else 0)

    note_text = (notes or '').strip()
    if len(note_text) > 500:
        note_text = note_text[:500]

    cursor.execute(
        """
        INSERT INTO student_pocket_money_transactions
            (student_id, direction, amount, balance_after, reference_code, notes,
             recorded_by_name, finance_account_id, payment_method)
        VALUES (%s, 'debit', %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            sid, amt, balance_after, ref, note_text or None,
            (recorded_by_name or '').strip() or None,
            int(finance_account_id), payment_method,
        ),
    )
    txn_id = cursor.lastrowid

    ok_debit, debit_err = _debit_pocket_money_finance_account(
        cursor, finance_account_id, amt,
        payment_method=payment_method,
        reference_code=ref,
        description=f'Pocket money withdrawal — {sid}',
        related_type='student_pocket_money',
        related_id=txn_id,
        recorded_by_name=recorded_by_name,
    )
    if not ok_debit:
        return False, None, debit_err or 'Could not update finance account balance.'

    fa_bal = _fetch_finance_account_ledger_balance(cursor, finance_account_id)

    return True, {
        'student_id': sid,
        'reference_code': ref,
        'amount': float(amt),
        'amount_display': f'{float(amt):,.2f}',
        'balance_after': balance_after,
        'balance_after_display': f'{balance_after:,.2f}',
        'finance_account_id': int(finance_account_id),
        'finance_account_name': acct.get('account_name') if acct else '',
        'finance_account_balance': fa_bal,
        'finance_account_balance_display': f'{fa_bal:,.2f}',
        'payment_method': payment_method,
    }, None


# Student Fees Route
@app.route('/dashboard/employee/student-fees')
@login_required
def student_fees():
    """Student Fees management page for accountants"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    print(f"DEBUG Student Fees Route:")
    print(f"  - user_role from session: {user_role}")
    print(f"  - viewing_as_role: {viewing_as_role}")
    print(f"  - employee_id: {session.get('employee_id')}")
    print(f"  - user_id: {session.get('user_id')}")
    
    # Check if user is accountant or viewing as accountant (for role switching)
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    
    # Check if user is principal or viewing as principal
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    # Also allow technicians (they can switch to accountant role)
    is_technician = user_role == 'technician'
    
    # If not accountant or principal, check actual role from database
    if not is_accountant and not is_principal:
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    employee_id = session.get('employee_id') or session.get('user_id')
                    if employee_id:
                        cursor.execute("SELECT role FROM employees WHERE id = %s OR employee_id = %s", 
                                     (employee_id, employee_id))
                        result = cursor.fetchone()
                        if result:
                            db_role = result.get('role') if isinstance(result, dict) else result[0]
                            db_role = db_role.lower() if db_role else ''
                            print(f"  - db_role: {db_role}")
                            if db_role == 'accountant':
                                is_accountant = True
                            elif db_role == 'head of institution':
                                is_principal = True
            except Exception as e:
                print(f"Error fetching employee role: {e}")
            finally:
                connection.close()
    
    # Check permission-based access
    employee_id = session.get('employee_id') or session.get('user_id')
    has_view_fees_permission = check_permission_or_role('view_student_fees', ['accountant', 'head of institution'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    
    # Check specific permissions for accountant features
    can_view_students = check_permission_or_role('view_students', ['accountant', 'head of institution', 'deputy head of institution'])
    can_view_fee_structure_details = check_permission_or_role('view_fee_structure_details', ['accountant', 'head of institution'])
    can_record_payments = check_permission_or_role('process_payments', ['accountant', 'head of institution'])
    can_add_fee_structure = check_permission_or_role('add_fee_structure', ['accountant', 'head of institution'])
    can_edit_fee_structure = check_permission_or_role('edit_fee_structure', ['accountant', 'head of institution'])
    can_delete_fee_structure = check_permission_or_role('delete_fee_structure', ['accountant', 'head of institution'])
    
    if not _student_fees_has_access():
        flash('You do not have permission to access this page. Only accountants, principals, or users with fee viewing permissions can access Student Fees.', 'error')
        return redirect(employee_dashboard_path())

    # Student register loads via /student-fees/students (paginated API)
    connection = get_db_connection()
    students = []
    academic_levels = []
    levels_by_category = []
    level_combinations_display = []
    member_level_ids = set()
    academic_years = []
    terms = []
    fee_structure_batches = []
    current_academic_year_id = None
    current_academic_year_name = ''
    current_term_id = None
    current_term_name = ''
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get current academic year
                cursor.execute("""
                    SELECT id, year_name, is_current
                    FROM academic_years
                    WHERE is_current = TRUE AND status = 'active'
                    LIMIT 1
                """)
                current_year_result = cursor.fetchone()
                if current_year_result:
                    current_academic_year_id = current_year_result.get('id') if isinstance(current_year_result, dict) else current_year_result[0]
                    current_academic_year_name = (
                        current_year_result.get('year_name', '') if isinstance(current_year_result, dict)
                        else (current_year_result[1] if len(current_year_result) > 1 else '')
                    )
                
                # Get current term for the current academic year
                if current_academic_year_id:
                    cursor.execute("""
                        SELECT id, term_name, is_current
                        FROM terms
                        WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                        LIMIT 1
                    """, (current_academic_year_id,))
                    current_term_result = cursor.fetchone()
                    if current_term_result:
                        current_term_id = current_term_result.get('id') if isinstance(current_term_result, dict) else current_term_result[0]
                        current_term_name = (
                            current_term_result.get('term_name', '') if isinstance(current_term_result, dict)
                            else (current_term_result[1] if len(current_term_result) > 1 else '')
                        )
                
                # Fetch active academic levels — fee structure counts scoped to current year/term
                if current_academic_year_id and current_term_id:
                    cursor.execute("""
                        SELECT al.id, al.level_category, al.level_name, al.level_description,
                               COUNT(DISTINCT fs.id) as fee_structure_count
                        FROM academic_levels al
                        LEFT JOIN fee_structures fs ON al.id = fs.academic_level_id
                            AND fs.status = 'active'
                            AND fs.academic_year_id = %s
                            AND fs.term_id = %s
                        WHERE al.level_status = 'active'
                        GROUP BY al.id, al.level_category, al.level_name, al.level_description
                        ORDER BY al.level_name ASC
                    """, (current_academic_year_id, current_term_id))
                else:
                    cursor.execute("""
                        SELECT al.id, al.level_category, al.level_name, al.level_description,
                               COUNT(DISTINCT fs.id) as fee_structure_count
                        FROM academic_levels al
                        LEFT JOIN fee_structures fs ON al.id = fs.academic_level_id
                            AND fs.status = 'active'
                        WHERE al.level_status = 'active'
                        GROUP BY al.id, al.level_category, al.level_name, al.level_description
                        ORDER BY al.level_name ASC
                    """)
                academic_levels_results = cursor.fetchall()
                
                if academic_levels_results:
                    for row in academic_levels_results:
                        fee_structure_count = row.get('fee_structure_count', 0) if isinstance(row, dict) else row[4]
                        fee_structure_count = int(fee_structure_count) if fee_structure_count else 0
                        academic_levels.append({
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                            'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2],
                            'level_description': row.get('level_description', '') if isinstance(row, dict) else row[3],
                            'has_fee_structure': fee_structure_count > 0,
                            'fee_structure_count': fee_structure_count
                        })

                levels_by_category, level_combinations_display, member_level_ids = (
                    build_academic_levels_picker_grouping(academic_levels, cursor)
                )
                
                # Fetch ALL active academic years (ONLY filter by status='active', ignore is_current)
                cursor.execute("""
                    SELECT id, year_name, start_date, end_date, status, is_current, is_locked
                    FROM academic_years
                    WHERE status = 'active'
                    ORDER BY start_date DESC
                """)
                academic_years_results = cursor.fetchall()
                print(f"DEBUG: Found {len(academic_years_results) if academic_years_results else 0} active academic years")
                if academic_years_results:
                    for year in academic_years_results:
                        year_dict = {
                            'id': year.get('id') if isinstance(year, dict) else year[0],
                            'year_name': year.get('year_name', '') if isinstance(year, dict) else year[1],
                            'start_date': year.get('start_date') if isinstance(year, dict) else year[2],
                            'end_date': year.get('end_date') if isinstance(year, dict) else year[3],
                            'status': year.get('status', '') if isinstance(year, dict) else year[4],
                            'is_current': year.get('is_current', False) if isinstance(year, dict) else year[5],
                            'is_locked': year.get('is_locked', False) if isinstance(year, dict) else (year[6] if len(year) > 6 else False)
                        }
                        academic_years.append(year_dict)
                        print(f"DEBUG: Added academic year: {year_dict['year_name']} (ID: {year_dict['id']}, Status: {year_dict['status']})")
                
                # Fetch ALL active terms that are not locked
                cursor.execute("""
                    SELECT t.id, t.term_name, t.academic_year_id, t.start_date, t.end_date, t.status, t.is_current, t.is_locked,
                           ay.year_name as academic_year_name
                    FROM terms t
                    LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                    WHERE t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                    ORDER BY t.academic_year_id DESC, t.start_date ASC
                """)
                terms_results = cursor.fetchall()
                print(f"DEBUG: Found {len(terms_results) if terms_results else 0} active terms")
                if terms_results:
                    for term in terms_results:
                        term_dict = {
                            'id': term.get('id') if isinstance(term, dict) else term[0],
                            'term_name': term.get('term_name', '') if isinstance(term, dict) else term[1],
                            'academic_year_id': term.get('academic_year_id') if isinstance(term, dict) else term[2],
                            'start_date': term.get('start_date') if isinstance(term, dict) else term[3],
                            'end_date': term.get('end_date') if isinstance(term, dict) else term[4],
                            'status': term.get('status', '') if isinstance(term, dict) else term[5],
                            'is_current': term.get('is_current', False) if isinstance(term, dict) else term[6],
                            'is_locked': term.get('is_locked', False) if isinstance(term, dict) else term[7],
                            'academic_year_name': term.get('academic_year_name', '') if isinstance(term, dict) else term[8]
                        }
                        terms.append(term_dict)
                        print(f"DEBUG: Added term: {term_dict['term_name']} (ID: {term_dict['id']}, Year ID: {term_dict['academic_year_id']}, Status: {term_dict['status']})")

                fee_structure_batches = _fetch_fee_structure_batches_for_display(
                    cursor, current_academic_year_id, current_term_id,
                )
        except Exception as e:
            print(f"Error fetching data: {e}")
            import traceback
            traceback.print_exc()
        finally:
            connection.close()
    
    from datetime import datetime
    today = datetime.now().strftime('%Y-%m-%d')
    
    # Get current employee info for payment recording
    current_employee = None
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                employee_id = session.get('employee_id') or session.get('user_id')
                if employee_id:
                    cursor.execute("""
                        SELECT id, employee_id, full_name, role
                        FROM employees
                        WHERE id = %s OR employee_id = %s
                        LIMIT 1
                    """, (employee_id, employee_id))
                    emp_result = cursor.fetchone()
                    if emp_result:
                        current_employee = {
                            'id': emp_result.get('id'),
                            'employee_id': emp_result.get('employee_id'),
                            'full_name': emp_result.get('full_name'),
                            'role': emp_result.get('role')
                        }
        except Exception as e:
            print(f"Error fetching employee info: {e}")
        finally:
            connection.close()
    
    # Check additional permissions
    can_generate_invoices = check_permission_or_role('generate_invoices', ['accountant', 'head of institution'])
    
    return render_template('dashboards/student_fees.html', 
                         students=students, 
                         academic_levels=academic_levels,
                         levels_by_category=levels_by_category,
                         level_combinations_display=level_combinations_display,
                         member_level_ids=sorted(member_level_ids),
                         academic_years=academic_years,
                         terms=terms,
                         today=today,
                         current_employee=current_employee,
                         current_academic_year_name=current_academic_year_name,
                         current_term_name=current_term_name,
                         fee_structure_batches=fee_structure_batches,
                         can_view_students=can_view_students,
                         can_view_fee_structure_details=can_view_fee_structure_details,
                         can_record_payments=can_record_payments,
                         can_add_fee_structure=can_add_fee_structure,
                         can_edit_fee_structure=can_edit_fee_structure,
                         can_delete_fee_structure=can_delete_fee_structure,
                         can_generate_invoices=can_generate_invoices,
                         mpesa_daraja_enabled=_get_daraja_settings_from_flag(),
                         mpesa_sandbox_confirm=_mpesa_sandbox_manual_confirm_enabled())


