@app.route('/dashboard/employee/student-fees/fee-items', methods=['GET'])
@login_required
def get_fee_items():
    """Get all existing fee items from the database"""
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'items': []}), 200
    
    try:
        with connection.cursor() as cursor:
            # Get distinct fee items from all fee structures
            ensure_fee_items_vote_code_column(cursor)
            cursor.execute("""
                SELECT DISTINCT 
                    item_name,
                    vote_code,
                    item_description, 
                    amount
                FROM fee_items
                ORDER BY item_name ASC, amount DESC
            """)
            items_results = cursor.fetchall()
            
            items = []
            if items_results:
                for item in items_results:
                    if isinstance(item, dict):
                        item_dict = {
                            'item_name': item.get('item_name', ''),
                            'vote_code': item.get('vote_code', '') or '',
                            'item_description': item.get('item_description', ''),
                            'amount': float(item.get('amount', 0)),
                        }
                    else:
                        item_dict = {
                            'item_name': item[0] if len(item) > 0 else '',
                            'vote_code': item[1] if len(item) > 1 else '',
                            'item_description': item[2] if len(item) > 2 else '',
                            'amount': float(item[3] if len(item) > 3 else 0),
                        }
                    items.append(item_dict)
            
            return jsonify({'success': True, 'items': items}), 200
    except Exception as e:
        print(f"Error fetching fee items: {e}")
        return jsonify({'success': False, 'items': []}), 200
    finally:
        connection.close()


