@app.route('/dashboard/employee/student-fees/check-fee-structure', methods=['GET'])
@login_required
def check_fee_structure():
    """Check if a fee structure exists for the given academic year, term, academic level, and category combination"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission to view fee structure details
    is_technician = user_role == 'technician'
    has_view_fee_structure_details = check_permission_or_role('view_fee_structure_details', ['accountant', 'head of institution'])
    has_view_fees = check_permission_or_role('view_fees', ['accountant', 'head of institution'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_view_fee_structure_details or has_view_fees):
        return jsonify({'success': False, 'message': 'You do not have permission to view fee structure details. Please contact your administrator.'}), 403
    
    academic_year_id = request.args.get('academic_year_id')
    term_id = request.args.get('term_id')
    academic_level_id = request.args.get('academic_level_id')
    category = request.args.get('category', '').strip().lower()
    
    if not academic_year_id or not term_id or not academic_level_id or not category:
        return jsonify({'exists': False}), 200
    
    # Validate category
    if category not in ['self sponsored', 'sponsored', 'both']:
        return jsonify({'exists': False}), 200
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'exists': False}), 200
    
    try:
        with connection.cursor() as cursor:
            # Check for category conflicts:
            # 1. If checking "both", check if "self sponsored" or "sponsored" exists
            # 2. If checking "self sponsored" or "sponsored", check if "both" exists
            # 3. Check if exact same category already exists
            
            conflict_exists = False
            conflict_message = ''
            existing_name = ''
            
            if category == 'both':
                # Check if "self sponsored" or "sponsored" exists
                cursor.execute("""
                    SELECT id, fee_name, category
                    FROM fee_structures 
                    WHERE academic_year_id = %s
                    AND term_id = %s
                    AND academic_level_id = %s 
                    AND category IN ('self sponsored', 'sponsored')
                    AND status = 'active'
                """, (academic_year_id, term_id, academic_level_id))
                
                existing_individual = cursor.fetchone()
                if existing_individual:
                    conflict_exists = True
                    existing_name = existing_individual.get('fee_name') if isinstance(existing_individual, dict) else existing_individual[1]
                    existing_category = existing_individual.get('category') if isinstance(existing_individual, dict) else existing_individual[2]
                    conflict_message = f'Cannot use "Both" category because a fee structure exists for "{existing_category.title()}" category. The "Both" category covers both self-sponsored and sponsored students, so it cannot coexist with individual category fee structures.'
            else:
                # Check if "both" exists
                cursor.execute("""
                    SELECT id, fee_name
                    FROM fee_structures 
                    WHERE academic_year_id = %s
                    AND term_id = %s
                    AND academic_level_id = %s 
                    AND category = 'both'
                    AND status = 'active'
                """, (academic_year_id, term_id, academic_level_id))
                
                existing_both = cursor.fetchone()
                if existing_both:
                    conflict_exists = True
                    existing_name = existing_both.get('fee_name') if isinstance(existing_both, dict) else existing_both[1]
                    conflict_message = f'Cannot use "{category.title()}" category because a fee structure exists for "Both" category. The "Both" category covers both self-sponsored and sponsored students, so individual category fee structures cannot be created when "Both" exists.'
            
            # Check if exact same category already exists
            if not conflict_exists:
                cursor.execute("""
                    SELECT id, fee_name
                    FROM fee_structures 
                    WHERE academic_year_id = %s
                    AND term_id = %s
                    AND academic_level_id = %s 
                    AND category = %s
                    AND status = 'active'
                """, (academic_year_id, term_id, academic_level_id, category))
                
                existing_structure = cursor.fetchone()
                if existing_structure:
                    conflict_exists = True
                    existing_name = existing_structure.get('fee_name') if isinstance(existing_structure, dict) else existing_structure[1]
                    conflict_message = f'A fee structure already exists for this Category ({category}), Academic Level, Term, and Academic Year combination.'
            
            if conflict_exists:
                return jsonify({
                    'exists': True,
                    'fee_name': existing_name,
                    'conflict_message': conflict_message
                }), 200
            else:
                return jsonify({'exists': False}), 200
    except Exception as e:
        print(f"Error checking fee structure: {e}")
        return jsonify({'exists': False}), 200
    finally:
        connection.close()

@app.route('/dashboard/employee/student-fees/check-fee-structures-for-term', methods=['GET'])
@login_required
def check_fee_structures_for_term():
    """Academic level IDs that already have a conflicting fee structure for year/term/category."""
    academic_year_id = request.args.get('academic_year_id')
    term_id = request.args.get('term_id')
    category = request.args.get('category', '').strip().lower()
    exclude_raw = request.args.get('exclude_structure_ids', '').strip()
    exclude_ids = []
    for part in exclude_raw.split(','):
        part = part.strip()
        if part.isdigit():
            exclude_ids.append(int(part))

    if not academic_year_id or not term_id or not category:
        return jsonify({'academic_levels_with_structure': [], 'conflicts_by_level': {}}), 200

    if category not in ['self sponsored', 'sponsored', 'both']:
        return jsonify({'academic_levels_with_structure': [], 'conflicts_by_level': {}}), 200

    connection = get_db_connection()
    if not connection:
        return jsonify({'academic_levels_with_structure': [], 'conflicts_by_level': {}}), 200

    try:
        with connection.cursor() as cursor:
            ex_clause = ''
            ex_params = ()
            if exclude_ids:
                placeholders = ','.join(['%s'] * len(exclude_ids))
                ex_clause = f' AND id NOT IN ({placeholders})'
                ex_params = tuple(exclude_ids)

            conflict_level_ids = set()
            conflicts_by_level = {}

            def _add_rows(rows):
                for row in rows or []:
                    if isinstance(row, dict):
                        lid = row.get('academic_level_id')
                        fname = row.get('fee_name', '')
                        cat = row.get('category', '')
                    else:
                        lid = row[0]
                        fname = row[1] if len(row) > 1 else ''
                        cat = row[2] if len(row) > 2 else ''
                    if lid is None:
                        continue
                    lid = int(lid)
                    conflict_level_ids.add(lid)
                    key = str(lid)
                    if key not in conflicts_by_level:
                        conflicts_by_level[key] = {
                            'fee_name': fname or '',
                            'category': cat or '',
                        }

            cursor.execute(
                f"""
                SELECT academic_level_id, fee_name, category
                FROM fee_structures
                WHERE academic_year_id = %s AND term_id = %s AND category = %s
                  AND status = 'active' {ex_clause}
                """,
                (academic_year_id, term_id, category) + ex_params,
            )
            _add_rows(cursor.fetchall())

            if category == 'both':
                cursor.execute(
                    f"""
                    SELECT academic_level_id, fee_name, category
                    FROM fee_structures
                    WHERE academic_year_id = %s AND term_id = %s
                      AND category IN ('self sponsored', 'sponsored')
                      AND status = 'active' {ex_clause}
                    """,
                    (academic_year_id, term_id) + ex_params,
                )
                _add_rows(cursor.fetchall())
            elif category in ('self sponsored', 'sponsored'):
                cursor.execute(
                    f"""
                    SELECT academic_level_id, fee_name, category
                    FROM fee_structures
                    WHERE academic_year_id = %s AND term_id = %s
                      AND category = 'both' AND status = 'active' {ex_clause}
                    """,
                    (academic_year_id, term_id) + ex_params,
                )
                _add_rows(cursor.fetchall())

            return jsonify({
                'academic_levels_with_structure': sorted(conflict_level_ids),
                'conflicts_by_level': conflicts_by_level,
            }), 200
    except Exception as e:
        print(f"Error checking fee structures for term: {e}")
        return jsonify({'academic_levels_with_structure': []}), 200
    finally:
        connection.close()


