@app.route('/dashboard/employee/student-fees/create-fee-structure', methods=['POST'])
@login_required
def create_fee_structure():
    """Create a new fee structure"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is accountant or viewing as accountant
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access - specific permission for adding fee structures
    has_add_fee_structure_permission = check_permission_or_role('add_fee_structure', ['accountant', 'head of institution'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_add_fee_structure_permission or has_manage_fees_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to add fee structures. Please contact your administrator.'}), 403
    
    try:
        data = request.get_json()
        
        # Validate required fields
        raw_level_ids = data.get('academic_level_ids')
        academic_level_id = data.get('academic_level_id')
        academic_year_id = data.get('academic_year_id')
        term_id = data.get('term_id')
        fee_name = data.get('fee_name', '').strip().upper()
        fee_items = data.get('fee_items', [])

        if isinstance(raw_level_ids, list) and raw_level_ids:
            academic_level_ids = []
            for value in raw_level_ids:
                try:
                    academic_level_ids.append(int(value))
                except (TypeError, ValueError):
                    continue
            academic_level_ids = sorted(list(set(academic_level_ids)))
        elif academic_level_id:
            try:
                academic_level_ids = [int(academic_level_id)]
            except (TypeError, ValueError):
                academic_level_ids = []
        else:
            academic_level_ids = []

        finance_account_id_raw = data.get('finance_account_id')
        try:
            finance_account_id = int(finance_account_id_raw)
        except (TypeError, ValueError):
            finance_account_id = None

        if not academic_level_ids or not academic_year_id or not term_id or not fee_name:
            return jsonify({'success': False, 'message': 'All required fields must be filled'}), 400

        if not finance_account_id:
            return jsonify({
                'success': False,
                'message': 'Please select the finance account fees will be paid into.',
            }), 400
        
        if not fee_items or len(fee_items) == 0:
            return jsonify({'success': False, 'message': 'At least one vote is required'}), 400
        
        # Calculate total amount
        total_amount = sum(float(item.get('amount', 0)) for item in fee_items)
        
        # Get employee ID for created_by
        employee_id = session.get('employee_id') or session.get('user_id')
        
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed'}), 500
        
        try:
            with connection.cursor() as cursor:
                ensure_fee_structures_finance_account_column(cursor)
                ensure_fee_items_vote_code_column(cursor)
                ensure_student_fee_votes_vote_code_column(cursor)

                ok_levels, levels_msg = _finance_account_accepts_levels(
                    cursor, finance_account_id, academic_level_ids
                )
                if not ok_levels:
                    return jsonify({'success': False, 'message': levels_msg}), 400

                cursor.execute(
                    """
                    SELECT account_status FROM finance_accounts WHERE id = %s LIMIT 1
                    """,
                    (finance_account_id,),
                )
                fa_row = cursor.fetchone()
                if not fa_row:
                    return jsonify({'success': False, 'message': 'Finance account not found'}), 400
                fa_status = (
                    (fa_row.get('account_status') if isinstance(fa_row, dict) else fa_row[0])
                    or 'active'
                ).strip().lower()
                if fa_status != 'active':
                    return jsonify({
                        'success': False,
                        'message': 'Selected finance account is not active.',
                    }), 400

                # Get term details to extract dates
                cursor.execute("""
                    SELECT start_date, end_date
                    FROM terms
                    WHERE id = %s AND status = 'active'
                """, (term_id,))
                term_result = cursor.fetchone()
                
                if not term_result:
                    return jsonify({'success': False, 'message': 'Selected term not found or not active'}), 400
                
                term_start_date = term_result.get('start_date') if isinstance(term_result, dict) else term_result[0]
                term_end_date = term_result.get('end_date') if isinstance(term_result, dict) else term_result[1]
                
                # Use term end_date as payment deadline
                payment_deadline = term_end_date
                
                # Get category from request data (must be provided)
                category = data.get('category', '').strip().lower()
                if category not in ['self sponsored', 'sponsored', 'both']:
                    return jsonify({
                        'success': False, 
                        'message': 'Invalid category. Please select a valid category (Self Sponsored, Sponsored, or Both).'
                    }), 400
                
                created_structure_ids = []
                total_items_inserted = 0

                for academic_level_id in academic_level_ids:
                    if category == 'both':
                        cursor.execute("""
                            SELECT id, fee_name, category
                            FROM fee_structures 
                            WHERE academic_year_id = %s
                            AND term_id = %s
                            AND academic_level_id = %s 
                            AND category IN ('self sponsored', 'sponsored')
                            AND status = 'active'
                        """, (academic_year_id, term_id, academic_level_id))
                        existing_individual = cursor.fetchone()
                        if existing_individual:
                            existing_name = existing_individual.get('fee_name') if isinstance(existing_individual, dict) else existing_individual[1]
                            existing_category = existing_individual.get('category') if isinstance(existing_individual, dict) else existing_individual[2]
                            connection.rollback()
                            return jsonify({
                                'success': False,
                                'message': f'Cannot create "Both" for level {academic_level_id}. Existing "{existing_category}" structure: {existing_name}.'
                            }), 400
                    else:
                        cursor.execute("""
                            SELECT id, fee_name
                            FROM fee_structures 
                            WHERE academic_year_id = %s
                            AND term_id = %s
                            AND academic_level_id = %s 
                            AND category = 'both'
                            AND status = 'active'
                        """, (academic_year_id, term_id, academic_level_id))
                        existing_both = cursor.fetchone()
                        if existing_both:
                            existing_name = existing_both.get('fee_name') if isinstance(existing_both, dict) else existing_both[1]
                            connection.rollback()
                            return jsonify({
                                'success': False,
                                'message': f'Cannot create "{category}" for level {academic_level_id}. Existing "Both" structure: {existing_name}.'
                            }), 400

                    cursor.execute("""
                        SELECT id, fee_name
                        FROM fee_structures 
                        WHERE academic_year_id = %s
                        AND term_id = %s
                        AND academic_level_id = %s 
                        AND category = %s
                        AND status = 'active'
                    """, (academic_year_id, term_id, academic_level_id, category))
                    existing_structure = cursor.fetchone()
                    if existing_structure:
                        existing_name = existing_structure.get('fee_name') if isinstance(existing_structure, dict) else existing_structure[1]
                        connection.rollback()
                        return jsonify({
                            'success': False,
                            'message': f'Fee structure already exists for level {academic_level_id} ({category}): {existing_name}.'
                        }), 400

                    cursor.execute("""
                        INSERT INTO fee_structures 
                        (academic_level_id, finance_account_id, academic_year_id, term_id, fee_name, category, start_date, end_date, payment_deadline, total_amount, created_by)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                    """, (academic_level_id, finance_account_id, academic_year_id, term_id, fee_name, category, term_start_date, term_end_date, payment_deadline, total_amount, employee_id))
                    fee_structure_id = cursor.lastrowid
                    created_structure_ids.append(fee_structure_id)

                    ensure_fee_items_vote_code_column(cursor)
                    items_inserted = 0
                    for index, item in enumerate(fee_items):
                        item_name = item.get('item_name', '').strip().upper()
                        vote_code = item.get('vote_code', '').strip().upper()
                        item_description = item.get('item_description', '').strip().upper()
                        amount = float(item.get('amount', 0))
                        if not item_name or not vote_code or not item_description or amount <= 0:
                            continue
                        cursor.execute("""
                            INSERT INTO fee_items 
                            (fee_structure_id, item_name, vote_code, item_description, amount, item_order)
                            VALUES (%s, %s, %s, %s, %s, %s)
                        """, (fee_structure_id, item_name, vote_code, item_description, amount, index))
                        items_inserted += 1
                    total_items_inserted += items_inserted
                    _sync_student_fee_votes_for_structure(cursor, fee_structure_id)
                
                # Verify items were inserted
                if total_items_inserted == 0:
                    connection.rollback()
                    return jsonify({
                        'success': False, 
                        'message': 'No valid votes were provided. Please ensure all votes have a name, code, description, and amount greater than 0.'
                    }), 400
                
                connection.commit()
                
                # Verify items were saved
                return jsonify({
                    'success': True, 
                    'message': f'Created {len(created_structure_ids)} fee structure(s) with {total_items_inserted} item row(s).',
                    'fee_structure_ids': created_structure_ids,
                    'items_count': total_items_inserted
                }), 200
                
        except Exception as e:
            connection.rollback()
            print(f"Error creating fee structure: {e}")
            return jsonify({'success': False, 'message': f'Error creating fee structure: {str(e)}'}), 500
        finally:
            connection.close()
            
    except Exception as e:
        print(f"Error in create_fee_structure: {e}")
        return jsonify({'success': False, 'message': 'An error occurred'}), 500

@app.route('/dashboard/employee/student-fees/fee-structures')
@login_required
def fee_structures():
    """Display all fee structures"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is accountant or viewing as accountant
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access
    has_view_fees_permission = check_permission_or_role('view_fees', ['accountant'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_view_fees_permission or has_manage_fees_permission):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    can_add_fee_structure = check_permission_or_role('add_fee_structure', ['accountant', 'head of institution'])
    
    connection = get_db_connection()
    fee_structures_list = []
    academic_levels = []
    academic_years = []
    levels_by_category = []
    level_combinations_display = []
    member_level_ids = []
    terms = []
    finance_accounts_picker = []
    
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_fee_structures_finance_account_column(cursor)
                ensure_student_fee_votes_table(cursor)
                ensure_fee_items_vote_code_column(cursor)
                ensure_student_fee_votes_vote_code_column(cursor)
                finance_accounts_picker = _fetch_finance_accounts_for_fee_structure_picker(cursor)

                # Fetch all fee structures with academic level and academic year info
                cursor.execute("""
                    SELECT fs.id, fs.academic_level_id, fs.finance_account_id, fs.academic_year_id,
                           fs.term_id, fs.fee_name, fs.category, fs.start_date, fs.end_date,
                           fs.payment_deadline, fs.total_amount, fs.status,
                           fs.created_at, fs.updated_at,
                           al.level_name, al.level_category,
                           ay.year_name as academic_year_name, ay.is_current as year_is_current,
                           t.term_name as term_name,
                           fa.account_name as finance_account_name,
                           fa.account_category as finance_account_category
                    FROM fee_structures fs
                    LEFT JOIN academic_levels al ON fs.academic_level_id = al.id
                    LEFT JOIN academic_years ay ON fs.academic_year_id = ay.id
                    LEFT JOIN terms t ON fs.term_id = t.id
                    LEFT JOIN finance_accounts fa ON fa.id = fs.finance_account_id
                    ORDER BY fs.created_at DESC, fs.updated_at DESC, fs.id DESC
                """)
                structures = cursor.fetchall()
                
                for row in structures:
                    # Fetch fee items for this structure
                    cursor.execute("""
                        SELECT id, item_name, vote_code, item_description, amount, item_order
                        FROM fee_items
                        WHERE fee_structure_id = %s
                        ORDER BY item_order ASC
                    """, (row.get('id'),))
                    items = cursor.fetchall()
                    
                    # Format dates
                    start_date = row.get('start_date')
                    end_date = row.get('end_date')
                    payment_deadline = row.get('payment_deadline')
                    
                    if start_date and hasattr(start_date, 'strftime'):
                        start_date = start_date.strftime('%Y-%m-%d')
                    elif start_date:
                        start_date = str(start_date).split(' ')[0]
                    
                    if end_date and hasattr(end_date, 'strftime'):
                        end_date = end_date.strftime('%Y-%m-%d')
                    elif end_date:
                        end_date = str(end_date).split(' ')[0]
                    
                    if payment_deadline and hasattr(payment_deadline, 'strftime'):
                        payment_deadline = payment_deadline.strftime('%Y-%m-%d')
                    elif payment_deadline:
                        payment_deadline = str(payment_deadline).split(' ')[0]

                    created_at = row.get('created_at')
                    updated_at = row.get('updated_at')
                    if created_at and hasattr(created_at, 'isoformat'):
                        created_at = created_at.isoformat(sep=' ', timespec='seconds')
                    elif created_at:
                        created_at = str(created_at).split('.')[0]
                    if updated_at and hasattr(updated_at, 'isoformat'):
                        updated_at = updated_at.isoformat(sep=' ', timespec='seconds')
                    elif updated_at:
                        updated_at = str(updated_at).split('.')[0]
                    
                    fee_structures_list.append({
                        'id': row.get('id'),
                        'academic_level_id': row.get('academic_level_id'),
                        'finance_account_id': row.get('finance_account_id'),
                        'finance_account_name': row.get('finance_account_name') or '',
                        'finance_account_category': row.get('finance_account_category') or '',
                        'academic_year_id': row.get('academic_year_id'),
                        'term_id': row.get('term_id'),
                        'fee_name': row.get('fee_name', ''),
                        'category': row.get('category', 'both'),
                        'start_date': start_date,
                        'end_date': end_date,
                        'payment_deadline': payment_deadline,
                        'total_amount': float(row.get('total_amount', 0)),
                        'status': row.get('status', 'active'),
                        'created_at': created_at,
                        'updated_at': updated_at,
                        'level_name': row.get('level_name', ''),
                        'level_category': row.get('level_category', ''),
                        'academic_year_name': row.get('academic_year_name', ''),
                        'term_name': row.get('term_name', ''),
                        'year_is_current': row.get('year_is_current', False),
                        'enrolled_student_count': len(
                            _students_for_fee_structure_level(
                                cursor,
                                row.get('academic_level_id'),
                                row.get('category', 'both'),
                            )
                        ),
                        'items': [{
                            'id': item.get('id'),
                            'item_name': item.get('item_name', ''),
                            'vote_code': item.get('vote_code', '') or '',
                            'item_description': item.get('item_description', ''),
                            'amount': float(item.get('amount', 0))
                        } for item in items]
                    })
                
                # Fetch active academic levels for edit modal
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                
                for row in academic_levels_results:
                    academic_levels.append({
                        'id': row.get('id'),
                        'level_category': row.get('level_category', ''),
                        'level_name': row.get('level_name', ''),
                        'level_description': row.get('level_description', '')
                    })

                levels_by_category, level_combinations_display, member_level_ids = (
                    build_academic_levels_picker_grouping(academic_levels, cursor)
                )
                
                # Fetch all academic years for filtering
                cursor.execute("""
                    SELECT id, year_name, start_date, end_date, status, is_current
                    FROM academic_years
                    ORDER BY start_date DESC
                """)
                academic_years_results = cursor.fetchall()
                
                for row in academic_years_results:
                    academic_years.append({
                        'id': row.get('id'),
                        'year_name': row.get('year_name', ''),
                        'start_date': row.get('start_date'),
                        'end_date': row.get('end_date'),
                        'status': row.get('status', 'active'),
                        'is_current': row.get('is_current', False)
                    })

                cursor.execute("""
                    SELECT t.id, t.term_name, t.academic_year_id, t.start_date, t.end_date, t.status, t.is_current, t.is_locked,
                           ay.year_name as academic_year_name
                    FROM terms t
                    LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                    WHERE t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                    ORDER BY t.academic_year_id DESC, t.start_date ASC
                """)
                for term in cursor.fetchall() or []:
                    terms.append({
                        'id': term.get('id') if isinstance(term, dict) else term[0],
                        'term_name': term.get('term_name', '') if isinstance(term, dict) else term[1],
                        'academic_year_id': term.get('academic_year_id') if isinstance(term, dict) else term[2],
                        'start_date': term.get('start_date') if isinstance(term, dict) else term[3],
                        'end_date': term.get('end_date') if isinstance(term, dict) else term[4],
                        'status': term.get('status', '') if isinstance(term, dict) else term[5],
                        'is_current': term.get('is_current', False) if isinstance(term, dict) else term[6],
                        'is_locked': term.get('is_locked', False) if isinstance(term, dict) else term[7],
                        'academic_year_name': term.get('academic_year_name', '') if isinstance(term, dict) else term[8],
                    })
        except Exception as e:
            print(f"Error fetching fee structures: {e}")
        finally:
            connection.close()

    fee_structures_list.sort(
        key=lambda s: (
            s.get('created_at') or '',
            s.get('updated_at') or '',
            int(s.get('id') or 0),
        ),
        reverse=True,
    )
    
    return render_template('dashboards/fee_structures.html', 
                         fee_structures=fee_structures_list, 
                         academic_levels=academic_levels,
                         academic_years=academic_years,
                         levels_by_category=levels_by_category,
                         level_combinations_display=level_combinations_display,
                         member_level_ids=sorted(member_level_ids),
                         terms=terms,
                         finance_accounts_picker=finance_accounts_picker,
                         can_add_fee_structure=can_add_fee_structure)

@app.route('/dashboard/employee/student-fees/payments-audit')
@login_required
def payments_audit():
    """Display payments audit log showing all changes to student fees"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check if user is accountant or viewing as accountant
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access
    has_view_fees_permission = check_permission_or_role('view_student_fees', ['accountant', 'head of institution'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_view_fees_permission or has_manage_fees_permission):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    connection = get_db_connection()
    audit_logs = []
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Check if audit table exists, if not create it
                try:
                    cursor.execute("SHOW TABLES LIKE 'student_payment_audit'")
                    table_exists = cursor.fetchone()
                    
                    if not table_exists:
                        # Create the audit table if it doesn't exist
                        cursor.execute("""
                            CREATE TABLE IF NOT EXISTS student_payment_audit (
                                id INT AUTO_INCREMENT PRIMARY KEY,
                                payment_id INT,
                                student_id VARCHAR(20) NOT NULL,
                                action_type ENUM('INSERT', 'UPDATE', 'DELETE') NOT NULL,
                                field_name VARCHAR(100),
                                old_value TEXT,
                                new_value TEXT,
                                changed_by INT,
                                changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                FOREIGN KEY (payment_id) REFERENCES student_payments(id) ON DELETE SET NULL,
                                FOREIGN KEY (student_id) REFERENCES students(student_id) ON DELETE CASCADE,
                                FOREIGN KEY (changed_by) REFERENCES employees(id) ON DELETE SET NULL,
                                INDEX idx_payment_id (payment_id),
                                INDEX idx_student_id (student_id),
                                INDEX idx_changed_at (changed_at),
                                INDEX idx_action_type (action_type)
                            )
                        """)
                        connection.commit()
                except Exception as e:
                    print(f"Error checking/creating audit table: {e}")
                
                # Fetch all audit logs with student and employee information
                cursor.execute("""
                    SELECT 
                        spa.id,
                        spa.payment_id,
                        spa.student_id,
                        spa.action_type,
                        spa.field_name,
                        spa.old_value,
                        spa.new_value,
                        spa.changed_at,
                        s.full_name as student_name,
                        e.full_name as employee_name,
                        e.employee_id as employee_code,
                        sp.amount_paid,
                        sp.payment_method,
                        sp.payment_date,
                        fs.fee_name
                    FROM student_payment_audit spa
                    LEFT JOIN students s ON spa.student_id = s.student_id
                    LEFT JOIN employees e ON spa.changed_by = e.id
                    LEFT JOIN student_payments sp ON spa.payment_id = sp.id
                    LEFT JOIN fee_structures fs ON sp.fee_structure_id = fs.id
                    ORDER BY spa.changed_at DESC
                    LIMIT 1000
                """)
                
                results = cursor.fetchall()
                
                for row in results:
                    changed_at = row.get('changed_at')
                    if changed_at and hasattr(changed_at, 'strftime'):
                        changed_at_str = changed_at.strftime('%Y-%m-%d %H:%M:%S')
                    else:
                        changed_at_str = str(changed_at) if changed_at else ''
                    
                    payment_date = row.get('payment_date')
                    if payment_date and hasattr(payment_date, 'strftime'):
                        payment_date_str = payment_date.strftime('%Y-%m-%d')
                    else:
                        payment_date_str = str(payment_date).split(' ')[0] if payment_date else ''
                    
                    audit_logs.append({
                        'id': row.get('id'),
                        'payment_id': row.get('payment_id'),
                        'student_id': row.get('student_id'),
                        'student_name': row.get('student_name', 'Unknown'),
                        'action_type': row.get('action_type', ''),
                        'field_name': row.get('field_name', ''),
                        'old_value': row.get('old_value', ''),
                        'new_value': row.get('new_value', ''),
                        'changed_at': changed_at_str,
                        'employee_name': row.get('employee_name', 'Unknown'),
                        'employee_code': row.get('employee_code', ''),
                        'amount_paid': float(row.get('amount_paid', 0)) if row.get('amount_paid') else 0,
                        'payment_method': row.get('payment_method', ''),
                        'payment_date': payment_date_str,
                        'fee_name': row.get('fee_name', '')
                    })
        except Exception as e:
            print(f"Error fetching audit logs: {e}")
            import traceback
            traceback.print_exc()
        finally:
            connection.close()
    
    return render_template('dashboards/payments_audit.html',
                         audit_logs=audit_logs,
                         role=user_role)


