@app.route('/dashboard/employee/student-fees/pocket-money/mpesa/stk-push', methods=['POST'])
@login_required
def accountant_pocket_money_mpesa_stk_push():
    """Accountant: Daraja STK push for student pocket money top-up."""
    import daraja_mpesa as daraja

    if not _employee_can_process_payments():
        return jsonify({'success': False, 'message': 'You do not have permission to record payments.'}), 403

    data = request.get_json(silent=True) or request.form
    student_id = (data.get('student_id') or '').strip()
    phone = (data.get('phone') or '').strip()
    raw_amount = data.get('amount')
    notes = (data.get('notes') or '').strip()
    finance_account_id = data.get('finance_account_id')

    if not student_id or not phone or not finance_account_id:
        return jsonify({
            'success': False,
            'message': 'Student, pocket money account, and M-Pesa phone are required.',
        }), 400

    try:
        finance_account_id = int(finance_account_id)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Invalid pocket money account.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable.'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT student_id FROM students
                WHERE student_id = %s AND status = 'in session' LIMIT 1
                """,
                (student_id,),
            )
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Student not found or not in session.'}), 404

            ok_acct, _acct, acct_err = _validate_pocket_money_finance_account(
                cursor, finance_account_id, 'Mobile Money',
            )
            if not ok_acct:
                return jsonify({'success': False, 'message': acct_err or 'Invalid pocket money account.'}), 400

            daraja_settings = _get_daraja_settings(cursor)
            if not daraja_settings.get('enabled'):
                return jsonify({
                    'success': False,
                    'message': 'M-Pesa online payments are disabled. Enable under Integration → Finance.',
                }), 400
            if not daraja.credentials_configured(daraja_settings):
                return jsonify({
                    'success': False,
                    'message': 'M-Pesa Daraja credentials are not configured on the server.',
                }), 503

            mpesa_cfg, cfg_err = _finance_account_mpesa_stk_config(
                cursor, finance_account_id, student_id, daraja_settings,
            )
            if cfg_err:
                return jsonify({'success': False, 'message': cfg_err}), 400

            callback_url, cb_err = daraja.resolve_stk_callback_url(
                daraja_settings,
                fallback_url=url_for('mpesa_stk_callback', _external=True),
            )
            if cb_err:
                return jsonify({'success': False, 'message': cb_err}), 400

            stk = daraja.stk_push(
                daraja_settings,
                phone=phone,
                amount=raw_amount,
                account_reference=mpesa_cfg['account_reference'],
                transaction_desc='Pocket money',
                callback_url=callback_url,
                business_shortcode=mpesa_cfg['business_shortcode'],
                transaction_type=mpesa_cfg['transaction_type'],
                party_b_shortcode=mpesa_cfg.get('party_b_shortcode'),
            )
            if not stk.get('ok'):
                return jsonify({'success': False, 'message': stk.get('error') or 'STK push failed.'}), 400

            emp_db_id, emp_name = _mpesa_stk_employee_context(cursor)
            pocket_money_reference = _generate_pocket_money_reference(cursor, student_id)
            stk_meta = {
                'initiated_by': 'accountant',
                'employee_db_id': emp_db_id,
                'employee_name': emp_name,
                'notes': notes[:500] if notes else None,
                'pocket_money_reference': pocket_money_reference,
                'stk': stk.get('raw') or {},
            }

            ensure_mpesa_stk_transactions_table(cursor)
            cursor.execute(
                """
                INSERT INTO mpesa_stk_transactions
                    (checkout_request_id, merchant_request_id, student_id, parent_email,
                     purpose, amount, phone, finance_account_id, fee_structure_id,
                     account_reference, business_shortcode, mpesa_type, status, raw_request_json)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    stk.get('checkout_request_id'),
                    stk.get('merchant_request_id'),
                    student_id,
                    None,
                    'accountant_pocket_money',
                    raw_amount,
                    phone,
                    finance_account_id,
                    None,
                    mpesa_cfg['account_reference'],
                    mpesa_cfg['business_shortcode'],
                    mpesa_cfg['mpesa_type'],
                    'pending',
                    json.dumps(stk_meta),
                ),
            )
            connection.commit()

            sync_warning = None
            if _mpesa_should_sync_stk_to_remote():
                sync_ok, _code, sync_detail = _mpesa_stk_sync_pending_to_remote({
                    'checkout_request_id': stk.get('checkout_request_id'),
                    'merchant_request_id': stk.get('merchant_request_id'),
                    'student_id': student_id,
                    'parent_email': None,
                    'purpose': 'accountant_pocket_money',
                    'amount': raw_amount,
                    'phone': phone,
                    'finance_account_id': finance_account_id,
                    'fee_structure_id': None,
                    'account_reference': mpesa_cfg['account_reference'],
                    'business_shortcode': mpesa_cfg['business_shortcode'],
                    'mpesa_type': mpesa_cfg['mpesa_type'],
                    'raw_request_json': json.dumps({'sync_origin': 'local', **stk_meta}),
                })
                _mpesa_stk_record_sync_meta(cursor, stk.get('checkout_request_id'), sync_ok, sync_detail)
                connection.commit()
                if not sync_ok:
                    sync_warning = sync_detail

            payload = {
                'success': True,
                'message': stk.get('customer_message') or 'Check the phone for the M-Pesa prompt.',
                'checkout_request_id': stk.get('checkout_request_id'),
                'account_reference': mpesa_cfg['account_reference'],
                'pocket_money_reference': pocket_money_reference,
                'business_name': mpesa_cfg.get('business_name'),
                'mpesa_type': mpesa_cfg.get('mpesa_type'),
            }
            if sync_warning:
                payload['sync_warning'] = sync_warning
            if _mpesa_sandbox_manual_confirm_enabled():
                payload['confirm_available'] = True
            return jsonify(payload)
    except Exception as e:
        print(f"accountant_pocket_money_mpesa_stk_push: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Could not start M-Pesa payment.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/record-payment', methods=['POST'])
@login_required
def record_payment():
    """Record a payment for a student"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    is_technician = user_role == 'technician'
    
    # Check permission-based access
    has_process_payments_permission = check_permission_or_role('process_payments', ['accountant'])
    
    # Debug logging
    print(f"DEBUG record_payment:")
    print(f"  - user_role: {user_role}")
    print(f"  - employee_id: {employee_id}")
    print(f"  - is_technician: {is_technician}")
    print(f"  - has_process_payments_permission: {has_process_payments_permission}")
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_process_payments_permission):
        print(f"  - ACCESS DENIED: No permission to record payments")
        return jsonify({'success': False, 'message': 'You do not have permission to record payments.'}), 403
    
    print(f"  - ACCESS GRANTED: Allowing payment recording")
    
    try:
        # Get form data
        student_id = request.form.get('student_id')
        fee_structure_id = request.form.get('fee_structure_id')
        amount_paid = float(request.form.get('amount_paid', 0))
        payment_method = request.form.get('payment_method')
        reference_number = request.form.get('reference_number', '').strip()
        cheque_number = request.form.get('cheque_number', '').strip()
        transaction_id = request.form.get('transaction_id', '').strip()
        payment_date = request.form.get('payment_date')
        notes = request.form.get('notes', '').strip()
        supplier_phone_raw = request.form.get('supplier_phone', '').strip()
        
        is_supplier_offset = payment_method == 'Supplier Offset'
        if is_supplier_offset:
            payment_date = payment_date or datetime.now().strftime('%Y-%m-%d')

        # Validate required fields
        if not student_id or not fee_structure_id or not amount_paid or not payment_method:
            return jsonify({'success': False, 'message': 'Please fill in all required fields.'}), 400
        if not payment_date and not is_supplier_offset:
            return jsonify({'success': False, 'message': 'Please fill in all required fields.'}), 400
        
        if amount_paid <= 0:
            return jsonify({'success': False, 'message': 'Amount paid must be greater than zero.'}), 400
        
        # Handle file upload
        proof_of_payment = None
        if 'proof_of_payment' in request.files:
            file = request.files['proof_of_payment']
            if file and file.filename != '' and allowed_payment_file(file.filename):
                timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
                if is_image_filename(file.filename):
                    proof_of_payment = _save_optimized_image(
                        file,
                        PAYMENT_PROOF_FOLDER,
                        f'payment_{student_id}_{timestamp}',
                        preset='payment_proof',
                    )
                else:
                    filename = secure_filename(f"payment_{student_id}_{timestamp}_{file.filename}")
                    filepath = os.path.join(app.config['PAYMENT_PROOF_FOLDER'], filename)
                    file.save(filepath)
                    proof_of_payment = f"uploads/payment_proofs/{filename}"
        
        # Validate payment method specific fields
        if payment_method == 'Bank Transfer' and not reference_number:
            return jsonify({'success': False, 'message': 'Reference number is required for bank transfer.'}), 400
        if payment_method == 'Cheque' and not cheque_number:
            return jsonify({'success': False, 'message': 'Cheque number is required for cheque payment.'}), 400
        if payment_method == 'Mobile Money' and not transaction_id:
            return jsonify({'success': False, 'message': 'Transaction ID is required for mobile money payment.'}), 400
        
        # Save to database
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection error.'}), 500
        
        try:
            with connection.cursor() as cursor:
                if is_supplier_offset:
                    if not supplier_phone_raw:
                        return jsonify({
                            'success': False,
                            'message': 'Enter the supplier phone number to trade from their account.',
                        }), 400
                    supplier_info = _fetch_supplier_payable_by_phone(cursor, supplier_phone_raw)
                    if not supplier_info.get('is_supplier'):
                        return jsonify({
                            'success': False,
                            'message': supplier_info.get('message')
                            or 'This phone number is not registered as a supplier.',
                        }), 400
                    supplier_credit = float(supplier_info.get('balance_due') or 0)
                    if supplier_credit <= 0:
                        return jsonify({
                            'success': False,
                            'message': 'This supplier has no outstanding balance to trade against.',
                        }), 400
                    if amount_paid > supplier_credit + 0.005:
                        return jsonify({
                            'success': False,
                            'message': (
                                f'Trade amount cannot exceed supplier credit of KES {supplier_credit:,.2f}.'
                            ),
                        }), 400

                # Get employee database ID (not employee_id code)
                received_by_id = None
                employee_identifier = session.get('employee_id') or session.get('user_id')
                if employee_identifier:
                    cursor.execute("""
                        SELECT id FROM employees 
                        WHERE id = %s OR employee_id = %s
                        LIMIT 1
                    """, (employee_identifier, employee_identifier))
                    emp_result = cursor.fetchone()
                    if emp_result:
                        received_by_id = emp_result.get('id') if isinstance(emp_result, dict) else emp_result[0]
                
                cursor.execute("""
                    INSERT INTO student_payments 
                    (student_id, fee_structure_id, amount_paid, payment_method, reference_number, 
                     cheque_number, transaction_id, proof_of_payment, received_by, payment_date, notes)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (student_id, fee_structure_id, amount_paid, payment_method, reference_number,
                      cheque_number, transaction_id, proof_of_payment, received_by_id, payment_date, notes))
                
                payment_id = cursor.lastrowid

                ok_credit, credit_err = _credit_student_fee_payment_accounts(
                    cursor, payment_id, fee_structure_id, amount_paid,
                    payment_method=payment_method,
                    reference_code=(
                        reference_number or transaction_id or cheque_number or f'FEE-{payment_id}'
                    ),
                    student_id=student_id,
                    recorded_by_name=(
                        session.get('full_name') or session.get('username') or ''
                    ).strip() or None,
                )
                if not ok_credit:
                    connection.rollback()
                    return jsonify({
                        'success': False,
                        'message': credit_err or 'Could not update finance account balance.',
                    }), 400

                if is_supplier_offset:
                    paid_by_name = (
                        session.get('full_name') or session.get('username') or ''
                    ).strip()
                    ok_offset, offset_err = _apply_supplier_offset_for_fee_payment(
                        cursor,
                        supplier_phone_raw,
                        amount_paid,
                        paid_by_name,
                        payment_id,
                        student_id=student_id,
                    )
                    if not ok_offset:
                        connection.rollback()
                        return jsonify({
                            'success': False,
                            'message': offset_err or 'Could not apply supplier offset.',
                        }), 400
                
                # Log audit entry for payment creation
                payment_details = f"Amount: KES {amount_paid:,.2f}, Method: {payment_method}, Date: {payment_date}"
                if reference_number:
                    payment_details += f", Ref: {reference_number}"
                if cheque_number:
                    payment_details += f", Cheque: {cheque_number}"
                if transaction_id:
                    payment_details += f", Transaction: {transaction_id}"
                if notes:
                    payment_details += f", Notes: {notes[:100]}"
                
                cursor.execute("""
                    INSERT INTO student_payment_audit 
                    (payment_id, student_id, action_type, field_name, old_value, new_value, changed_by)
                    VALUES (%s, %s, 'INSERT', 'Payment Created', NULL, %s, %s)
                """, (payment_id, student_id, payment_details, received_by_id))
                
                connection.commit()
                
                success_message = (
                    'Payment recorded via supplier trade.'
                    if is_supplier_offset
                    else 'Payment recorded successfully.'
                )
                return jsonify({
                    'success': True,
                    'message': success_message,
                })
        except Exception as e:
            connection.rollback()
            print(f"Error recording payment: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'message': f'Error recording payment: {str(e)}'}), 500
        finally:
            connection.close()
            
    except Exception as e:
        print(f"Error in record_payment: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'An error occurred while recording payment.'}), 500


def _employee_can_process_payments():
    user_role = session.get('role', '').lower()
    if user_role == 'technician':
        return True
    return bool(check_permission_or_role('process_payments', ['accountant']))


def _mpesa_stk_employee_context(cursor):
    """Employee DB id + display name for accountant-initiated STK."""
    employee_identifier = session.get('employee_id') or session.get('user_id')
    fallback = (session.get('full_name') or session.get('username') or 'Staff').strip()
    if not employee_identifier:
        return None, fallback
    cursor.execute(
        """
        SELECT id, full_name FROM employees
        WHERE id = %s OR employee_id = %s LIMIT 1
        """,
        (employee_identifier, employee_identifier),
    )
    row = cursor.fetchone()
    if not row:
        return None, fallback
    if isinstance(row, dict):
        return row.get('id'), (row.get('full_name') or fallback).strip()
    return row[0], (row[1] or fallback).strip()


def _mpesa_stk_employee_can_view_txn(txn_row):
    if not _employee_can_process_payments():
        return False
    return (txn_row.get('purpose') or '').lower() in (
        'accountant_school_fee', 'accountant_pocket_money',
    )


def _resolve_student_fee_mpesa_account(cursor, student_id, fee_structure_id):
    """Finance account from fee structure for accountant STK."""
    cursor.execute(
        "SELECT finance_account_id FROM fee_structures WHERE id = %s LIMIT 1",
        (fee_structure_id,),
    )
    fs = cursor.fetchone()
    if not fs:
        return None, None, 'Fee structure not found.'
    finance_account_id = fs.get('finance_account_id') if isinstance(fs, dict) else fs[0]
    if not finance_account_id:
        return None, None, 'This fee structure has no linked finance account.'
    return int(finance_account_id), int(fee_structure_id), None


@app.route('/dashboard/employee/student-fees/mpesa/stk-push', methods=['POST'])
@login_required
def accountant_mpesa_stk_push():
    """Accountant: Daraja STK push for student fee payment to linked finance account."""
    import daraja_mpesa as daraja

    if not _employee_can_process_payments():
        return jsonify({'success': False, 'message': 'You do not have permission to record payments.'}), 403

    data = request.get_json(silent=True) or request.form
    student_id = (data.get('student_id') or '').strip()
    fee_structure_id = data.get('fee_structure_id')
    phone = (data.get('phone') or '').strip()
    raw_amount = data.get('amount')

    if not student_id or not fee_structure_id or not phone:
        return jsonify({'success': False, 'message': 'Student, fee structure, and phone are required.'}), 400

    try:
        fee_structure_id = int(fee_structure_id)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'message': 'Invalid fee structure.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable.'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT student_id FROM students WHERE student_id = %s LIMIT 1",
                (student_id,),
            )
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Student not found.'}), 404

            daraja_settings = _get_daraja_settings(cursor)
            if not daraja_settings.get('enabled'):
                return jsonify({
                    'success': False,
                    'message': 'M-Pesa online payments are disabled. Enable under Integration → Finance.',
                }), 400
            if not daraja.credentials_configured(daraja_settings):
                return jsonify({
                    'success': False,
                    'message': 'M-Pesa Daraja credentials are not configured on the server.',
                }), 503

            finance_account_id, fee_structure_id, err = _resolve_student_fee_mpesa_account(
                cursor, student_id, fee_structure_id,
            )
            if err:
                return jsonify({'success': False, 'message': err}), 400

            mpesa_cfg, cfg_err = _finance_account_mpesa_stk_config(
                cursor, finance_account_id, student_id, daraja_settings,
            )
            if cfg_err:
                return jsonify({'success': False, 'message': cfg_err}), 400

            callback_url, cb_err = daraja.resolve_stk_callback_url(
                daraja_settings,
                fallback_url=url_for('mpesa_stk_callback', _external=True),
            )
            if cb_err:
                return jsonify({'success': False, 'message': cb_err}), 400

            stk = daraja.stk_push(
                daraja_settings,
                phone=phone,
                amount=raw_amount,
                account_reference=mpesa_cfg['account_reference'],
                transaction_desc='School fees',
                callback_url=callback_url,
                business_shortcode=mpesa_cfg['business_shortcode'],
                transaction_type=mpesa_cfg['transaction_type'],
                party_b_shortcode=mpesa_cfg.get('party_b_shortcode'),
            )
            if not stk.get('ok'):
                return jsonify({'success': False, 'message': stk.get('error') or 'STK push failed.'}), 400

            emp_db_id, emp_name = _mpesa_stk_employee_context(cursor)
            stk_meta = {
                'initiated_by': 'accountant',
                'employee_db_id': emp_db_id,
                'employee_name': emp_name,
                'stk': stk.get('raw') or {},
            }

            ensure_mpesa_stk_transactions_table(cursor)
            cursor.execute(
                """
                INSERT INTO mpesa_stk_transactions
                    (checkout_request_id, merchant_request_id, student_id, parent_email,
                     purpose, amount, phone, finance_account_id, fee_structure_id,
                     account_reference, business_shortcode, mpesa_type, status, raw_request_json)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    stk.get('checkout_request_id'),
                    stk.get('merchant_request_id'),
                    student_id,
                    None,
                    'accountant_school_fee',
                    raw_amount,
                    phone,
                    finance_account_id,
                    fee_structure_id,
                    mpesa_cfg['account_reference'],
                    mpesa_cfg['business_shortcode'],
                    mpesa_cfg['mpesa_type'],
                    'pending',
                    json.dumps(stk_meta),
                ),
            )
            connection.commit()

            sync_warning = None
            if _mpesa_should_sync_stk_to_remote():
                sync_ok, _code, sync_detail = _mpesa_stk_sync_pending_to_remote({
                    'checkout_request_id': stk.get('checkout_request_id'),
                    'merchant_request_id': stk.get('merchant_request_id'),
                    'student_id': student_id,
                    'parent_email': None,
                    'purpose': 'accountant_school_fee',
                    'amount': raw_amount,
                    'phone': phone,
                    'finance_account_id': finance_account_id,
                    'fee_structure_id': fee_structure_id,
                    'account_reference': mpesa_cfg['account_reference'],
                    'business_shortcode': mpesa_cfg['business_shortcode'],
                    'mpesa_type': mpesa_cfg['mpesa_type'],
                    'raw_request_json': json.dumps({'sync_origin': 'local', **stk_meta}),
                })
                _mpesa_stk_record_sync_meta(cursor, stk.get('checkout_request_id'), sync_ok, sync_detail)
                connection.commit()
                if not sync_ok:
                    sync_warning = sync_detail

            payload = {
                'success': True,
                'message': stk.get('customer_message') or 'Check the phone for the M-Pesa prompt.',
                'checkout_request_id': stk.get('checkout_request_id'),
                'account_reference': mpesa_cfg['account_reference'],
                'business_name': mpesa_cfg.get('business_name'),
                'mpesa_type': mpesa_cfg.get('mpesa_type'),
            }
            if sync_warning:
                payload['sync_warning'] = sync_warning
            if _mpesa_sandbox_manual_confirm_enabled():
                payload['confirm_available'] = True
            return jsonify(payload)
    except Exception as e:
        print(f"accountant_mpesa_stk_push: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Could not start M-Pesa payment.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/mpesa/status/<checkout_request_id>', methods=['GET'])
@login_required
def accountant_mpesa_stk_status(checkout_request_id):
    """Accountant: poll STK fee payment status."""
    if not _employee_can_process_payments():
        return jsonify({'success': False, 'message': 'Permission denied.'}), 403

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable.'}), 500
    try:
        with connection.cursor() as cursor:
            ensure_mpesa_stk_transactions_table(cursor)
            cursor.execute(
                "SELECT * FROM mpesa_stk_transactions WHERE checkout_request_id = %s LIMIT 1",
                (checkout_request_id,),
            )
            txn = cursor.fetchone()
            if not txn:
                return jsonify({'success': False, 'message': 'Transaction not found.'}), 404
            txn_row = txn if isinstance(txn, dict) else dict(zip([d[0] for d in cursor.description], txn))

            if not _mpesa_stk_employee_can_view_txn(txn_row):
                return jsonify({'success': False, 'message': 'Permission denied.'}), 403

            status = (txn_row.get('status') or 'pending').lower()
            if status == 'completed':
                connection.commit()
                return jsonify({
                    'success': True,
                    'status': 'completed',
                    'message': txn_row.get('result_desc') or _mpesa_parent_success_message(txn_row),
                    **_mpesa_stk_status_fields(txn_row),
                })
            if status in ('failed', 'cancelled'):
                connection.commit()
                return jsonify({
                    'success': True,
                    'status': status,
                    'message': txn_row.get('result_desc') or 'Payment was not completed.',
                    **_mpesa_stk_status_fields(txn_row),
                })

            daraja_settings = _get_daraja_settings(cursor)
            _mpesa_stk_ensure_remote_registered(cursor, txn_row)
            connection.commit()
            polled = _mpesa_stk_try_complete_from_query(cursor, txn_row, daraja_settings)
            if polled:
                connection.commit()
                return jsonify(polled)
            remote = _mpesa_stk_try_complete_from_remote_sync(cursor, txn_row)
            if remote:
                connection.commit()
                return jsonify(remote)
            connection.commit()
            pending_payload = {
                'success': True,
                'status': 'pending',
                'message': 'Waiting for M-Pesa PIN on the phone…',
                **_mpesa_stk_status_fields(txn_row),
            }
            sync_warning = _mpesa_stk_sync_warning_from_row(txn_row)
            if sync_warning:
                pending_payload['sync_warning'] = sync_warning
            if _mpesa_sandbox_manual_confirm_enabled():
                pending_payload['confirm_available'] = True
            return jsonify(pending_payload)
    except Exception as e:
        print(f"accountant_mpesa_stk_status: {e}")
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': 'Could not check status.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/mpesa/confirm-payment', methods=['POST'])
@login_required
def accountant_mpesa_confirm_payment():
    """Sandbox local dev: accountant confirms STK payment after PIN entered."""
    if not _mpesa_sandbox_manual_confirm_enabled():
        return jsonify({'success': False, 'message': 'Manual confirm is only available in sandbox local dev.'}), 403
    if not _employee_can_process_payments():
        return jsonify({'success': False, 'message': 'Permission denied.'}), 403

    data = request.get_json(silent=True) or request.form
    checkout_id = (data.get('checkout_request_id') or '').strip()
    mpesa_receipt = (data.get('mpesa_code_reference') or data.get('mpesa_receipt') or '').strip()
    if not checkout_id:
        return jsonify({'success': False, 'message': 'Missing payment session.'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable.'}), 500
    try:
        with connection.cursor() as cursor:
            ensure_mpesa_stk_transactions_table(cursor)
            cursor.execute(
                "SELECT * FROM mpesa_stk_transactions WHERE checkout_request_id = %s LIMIT 1",
                (checkout_id,),
            )
            txn = cursor.fetchone()
            if not txn:
                return jsonify({'success': False, 'message': 'Payment session not found.'}), 404
            txn_row = txn if isinstance(txn, dict) else dict(zip([d[0] for d in cursor.description], txn))
            if not _mpesa_stk_employee_can_view_txn(txn_row):
                return jsonify({'success': False, 'message': 'Permission denied.'}), 403

            status = (txn_row.get('status') or 'pending').lower()
            if status == 'completed':
                return jsonify({
                    'success': True,
                    'status': 'completed',
                    'message': txn_row.get('result_desc') or _mpesa_parent_success_message(txn_row),
                    **_mpesa_stk_status_fields(txn_row),
                })

            receipt = mpesa_receipt or checkout_id
            callback_data = {
                'result_code': 0,
                'result_desc': 'Sandbox payment confirmed by accountant.',
                'mpesa_receipt': receipt,
                'mpesa_code_reference': receipt,
            }
            ok, msg, recorded_receipt = _mpesa_stk_finalize_success(
                cursor, txn_row, callback_data,
                raw_json=json.dumps({'sandbox_manual_confirm': True, 'initiated_by': 'accountant'}),
            )
            if not ok:
                connection.commit()
                return jsonify({'success': False, 'message': msg or 'Could not record payment.'}), 400
            connection.commit()
            return jsonify({
                'success': True,
                'status': 'completed',
                'message': msg,
                'mpesa_receipt': recorded_receipt,
                'mpesa_code_reference': recorded_receipt,
            })
    except Exception as e:
        print(f"accountant_mpesa_confirm_payment: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Could not confirm payment.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/transactions/<student_id>', methods=['GET'])
@login_required
def get_student_transactions(student_id):
    """Get all transactions for a student"""
    if not _student_fees_has_access():
        return jsonify({'success': False, 'message': 'You do not have permission to view transactions.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            ensure_fee_structures_finance_account_column(cursor)
            cursor.execute("""
                SELECT sp.id, sp.amount_paid, sp.payment_method, sp.reference_number,
                       sp.cheque_number, sp.transaction_id, sp.proof_of_payment,
                       sp.payment_date, sp.notes, sp.created_at,
                       fs.fee_name, fs.total_amount,
                       fa.account_name AS finance_account_name,
                       t.term_name, ay.year_name,
                       e.full_name AS received_by_name, e.employee_id AS received_by_id
                FROM student_payments sp
                LEFT JOIN fee_structures fs ON sp.fee_structure_id = fs.id
                LEFT JOIN finance_accounts fa ON fa.id = fs.finance_account_id
                LEFT JOIN terms t ON fs.term_id = t.id
                LEFT JOIN academic_years ay ON fs.academic_year_id = ay.id
                LEFT JOIN employees e ON sp.received_by = e.id
                WHERE sp.student_id = %s
                ORDER BY sp.payment_date DESC, sp.created_at DESC
            """, (student_id,))
            transactions = cursor.fetchall()
            
            transactions_list = []
            for row in transactions:
                payment_date = row.get('payment_date')
                if payment_date and hasattr(payment_date, 'strftime'):
                    payment_date = payment_date.strftime('%Y-%m-%d')
                elif payment_date:
                    payment_date = str(payment_date).split(' ')[0]
                
                created_at = row.get('created_at')
                if created_at and hasattr(created_at, 'strftime'):
                    created_at = created_at.strftime('%Y-%m-%d %H:%M:%S')
                elif created_at:
                    created_at = str(created_at)
                
                # Safely convert amounts to float, handling None values
                amount_paid = row.get('amount_paid')
                if amount_paid is None:
                    amount_paid = 0.0
                else:
                    try:
                        amount_paid = float(amount_paid)
                    except (TypeError, ValueError):
                        amount_paid = 0.0
                
                total_amount = row.get('total_amount')
                if total_amount is None:
                    total_amount = 0.0
                else:
                    try:
                        total_amount = float(total_amount)
                    except (TypeError, ValueError):
                        total_amount = 0.0
                
                term_name = row.get('term_name') or ''
                year_name = row.get('year_name') or ''
                billing_period = f'{term_name} · {year_name}' if term_name and year_name else (term_name or year_name or '')
                transactions_list.append({
                    'id': row.get('id'),
                    'amount_paid': amount_paid,
                    'payment_method': row.get('payment_method', ''),
                    'reference_number': row.get('reference_number', ''),
                    'cheque_number': row.get('cheque_number', ''),
                    'transaction_id': row.get('transaction_id', ''),
                    'proof_of_payment': row.get('proof_of_payment', ''),
                    'payment_date': payment_date,
                    'notes': row.get('notes', ''),
                    'created_at': created_at,
                    'fee_name': row.get('fee_name', ''),
                    'finance_account_name': row.get('finance_account_name') or '',
                    'billing_period': billing_period,
                    'fee_total': total_amount,
                    'received_by_name': row.get('received_by_name', ''),
                    'received_by_id': row.get('received_by_id', '')
                })
            
            return jsonify({
                'success': True,
                'transactions': transactions_list
            })
    except Exception as e:
        print(f"Error fetching transactions: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'Error fetching transactions.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/update-payment', methods=['POST'])
@login_required
def update_payment_amount():
    """Update the amount_paid for an existing student payment (with audit log)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')

    is_technician = user_role == 'technician'
    has_process_payments_permission = check_permission_or_role('process_payments', ['accountant'])

    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_process_payments_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to update payments.'}), 403

    try:
        if request.is_json:
            data = request.get_json()
            payment_id = data.get('payment_id')
            student_id = data.get('student_id')
            amount_paid = float(data.get('amount_paid', 0))
        else:
            payment_id = request.form.get('payment_id')
            student_id = request.form.get('student_id')
            amount_paid = float(request.form.get('amount_paid', 0))

        if not payment_id or not student_id:
            return jsonify({'success': False, 'message': 'Missing payment_id or student_id.'}), 400
        if amount_paid < 0:
            return jsonify({'success': False, 'message': 'Amount paid cannot be negative.'}), 400

        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection error.'}), 500

        try:
            with connection.cursor() as cursor:
                cursor.execute(
                    "SELECT amount_paid FROM student_payments WHERE id = %s AND student_id = %s",
                    (payment_id, student_id)
                )
                row = cursor.fetchone()
                if not row:
                    return jsonify({'success': False, 'message': 'Payment not found.'}), 404

                old_value = row.get('amount_paid') if isinstance(row, dict) else row[0]
                try:
                    old_value = float(old_value) if old_value is not None else 0.0
                except (TypeError, ValueError):
                    old_value = 0.0

                cursor.execute(
                    "UPDATE student_payments SET amount_paid = %s WHERE id = %s AND student_id = %s",
                    (amount_paid, payment_id, student_id)
                )
                if cursor.rowcount == 0:
                    return jsonify({'success': False, 'message': 'Payment not updated.'}), 400

                received_by_id = None
                if employee_id:
                    cursor.execute(
                        "SELECT id FROM employees WHERE id = %s OR employee_id = %s LIMIT 1",
                        (employee_id, employee_id)
                    )
                    emp = cursor.fetchone()
                    if emp:
                        received_by_id = emp.get('id') if isinstance(emp, dict) else emp[0]

                cursor.execute("""
                    INSERT INTO student_payment_audit
                    (payment_id, student_id, action_type, field_name, old_value, new_value, changed_by)
                    VALUES (%s, %s, 'UPDATE', 'amount_paid', %s, %s, %s)
                """, (payment_id, student_id, str(old_value), str(amount_paid), received_by_id))

                connection.commit()
                return jsonify({'success': True, 'amount_paid': amount_paid})
        except Exception as e:
            connection.rollback()
            print(f"Error updating payment: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'message': str(e)}), 500
        finally:
            connection.close()
    except ValueError as e:
        return jsonify({'success': False, 'message': 'Invalid amount.'}), 400
    except Exception as e:
        print(f"Error in update_payment_amount: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'An error occurred while updating payment.'}), 500

@app.route('/dashboard/employee/student-fees/delete-payment', methods=['POST'])
@login_required
def delete_payment():
    """Delete a student payment (with audit log)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')

    is_technician = user_role == 'technician'
    has_process_payments_permission = check_permission_or_role('process_payments', ['accountant'])

    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_process_payments_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to delete payments.'}), 403

    try:
        if request.is_json:
            data = request.get_json()
            payment_id = data.get('payment_id')
            student_id = data.get('student_id')
        else:
            payment_id = request.form.get('payment_id')
            student_id = request.form.get('student_id')

        if not payment_id or not student_id:
            return jsonify({'success': False, 'message': 'Missing payment_id or student_id.'}), 400

        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection error.'}), 500

        try:
            with connection.cursor() as cursor:
                # Get employee database ID (not employee_id code)
                received_by_id = None
                employee_identifier = session.get('employee_id') or session.get('user_id')
                if employee_identifier:
                    cursor.execute("""
                        SELECT id FROM employees 
                        WHERE id = %s OR employee_id = %s
                        LIMIT 1
                    """, (employee_identifier, employee_identifier))
                    emp_result = cursor.fetchone()
                    if emp_result:
                        received_by_id = emp_result.get('id') if isinstance(emp_result, dict) else emp_result[0]

                # Get payment details before deletion for audit log
                cursor.execute("""
                    SELECT id, student_id, fee_structure_id, amount_paid, payment_method, 
                           reference_number, cheque_number, transaction_id, payment_date, notes
                    FROM student_payments
                    WHERE id = %s AND student_id = %s
                    LIMIT 1
                """, (payment_id, student_id))
                payment_result = cursor.fetchone()

                if not payment_result:
                    return jsonify({'success': False, 'message': 'Payment not found.'}), 404

                payment_date = (
                    payment_result.get('payment_date')
                    if isinstance(payment_result, dict)
                    else (payment_result[8] if len(payment_result) > 8 else None)
                )
                ok_fy, fy_err = _assert_financial_year_writable(cursor, payment_date)
                if not ok_fy:
                    return jsonify({'success': False, 'message': fy_err}), 403

                # Create audit log entry before deletion
                payment_details = f"Amount: KES {payment_result.get('amount_paid', 0) if isinstance(payment_result, dict) else payment_result[3] or 0}, Method: {payment_result.get('payment_method', '') if isinstance(payment_result, dict) else payment_result[4] or ''}, Date: {payment_result.get('payment_date', '') if isinstance(payment_result, dict) else payment_result[8] or ''}"
                
                # Log audit entry for payment deletion BEFORE deleting the payment
                # This ensures the foreign key constraint is satisfied
                cursor.execute("""
                    INSERT INTO student_payment_audit 
                    (payment_id, student_id, action_type, field_name, old_value, new_value, changed_by)
                    VALUES (%s, %s, 'DELETE', 'Payment Deleted', %s, NULL, %s)
                """, (payment_id, student_id, payment_details, received_by_id))
                
                # Delete the payment after audit log is created
                cursor.execute("""
                    DELETE FROM student_payments
                    WHERE id = %s AND student_id = %s
                """, (payment_id, student_id))

                connection.commit()
                return jsonify({
                    'success': True,
                    'message': 'Payment deleted successfully.'
                })
        except Exception as e:
            connection.rollback()
            print(f"Error deleting payment: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'message': f'Error deleting payment: {str(e)}'}), 500
        finally:
            connection.close()
    except Exception as e:
        print(f"Error in delete_payment: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'An error occurred while deleting payment.'}), 500

@app.route('/dashboard/employee/student-fees/fee-structure/<int:structure_id>/update', methods=['POST'])
@login_required
def update_fee_structure(structure_id):
    """Update a fee structure"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access - specific permission for editing fee structures
    has_edit_fee_structure_permission = check_permission_or_role('edit_fee_structure', ['accountant', 'head of institution'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_edit_fee_structure_permission or has_manage_fees_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to edit fee structures. Please contact your administrator.'}), 403
    
    try:
        data = request.get_json()
        
        if not data:
            return jsonify({'success': False, 'message': 'No data provided in request'}), 400
        
        raw_level_ids = data.get('academic_level_ids')
        academic_level_id = data.get('academic_level_id')
        if isinstance(raw_level_ids, list) and raw_level_ids:
            academic_level_ids = []
            for value in raw_level_ids:
                try:
                    academic_level_ids.append(int(value))
                except (TypeError, ValueError):
                    continue
            academic_level_ids = sorted(set(academic_level_ids))
        elif academic_level_id:
            try:
                academic_level_ids = [int(academic_level_id)]
            except (TypeError, ValueError):
                academic_level_ids = []
        else:
            academic_level_ids = []

        finance_account_id_raw = data.get('finance_account_id')
        try:
            finance_account_id = int(finance_account_id_raw)
        except (TypeError, ValueError):
            finance_account_id = None
        academic_year_id = data.get('academic_year_id')
        term_id = data.get('term_id')
        fee_name = data.get('fee_name', '').strip().upper()
        category = data.get('category', 'both').strip().lower()
        if category not in ['self sponsored', 'sponsored', 'both']:
            category = 'both'  # Default to 'both' if invalid
        start_date = data.get('start_date')
        end_date = data.get('end_date')
        payment_deadline = data.get('payment_deadline')
        fee_items = data.get('fee_items', [])
        
        # Validate required fields
        missing_fields = []
        if not finance_account_id:
            missing_fields.append('finance_account_id')
        if not academic_level_ids:
            missing_fields.append('academic_level_ids')
        if not fee_name:
            missing_fields.append('fee_name')
        if not start_date:
            missing_fields.append('start_date')
        if not end_date:
            missing_fields.append('end_date')
        if not payment_deadline:
            missing_fields.append('payment_deadline')
        
        if missing_fields:
            return jsonify({
                'success': False, 
                'message': f'Missing required fields: {", ".join(missing_fields)}'
            }), 400
        
        if not fee_items or len(fee_items) == 0:
            return jsonify({'success': False, 'message': 'At least one vote is required'}), 400
        
        total_amount = sum(float(item.get('amount', 0)) for item in fee_items)
        
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed'}), 500
        
        try:
            with connection.cursor() as cursor:
                ensure_fee_structures_finance_account_column(cursor)
                ensure_fee_items_vote_code_column(cursor)
                ensure_student_fee_votes_vote_code_column(cursor)

                ok_levels, levels_msg = _finance_account_accepts_levels(
                    cursor, finance_account_id, academic_level_ids
                )
                if not ok_levels:
                    return jsonify({'success': False, 'message': levels_msg}), 400

                cursor.execute(
                    """
                    SELECT account_status FROM finance_accounts WHERE id = %s LIMIT 1
                    """,
                    (finance_account_id,),
                )
                fa_row = cursor.fetchone()
                if not fa_row:
                    return jsonify({'success': False, 'message': 'Finance account not found'}), 400
                fa_status = (
                    (fa_row.get('account_status') if isinstance(fa_row, dict) else fa_row[0])
                    or 'active'
                ).strip().lower()
                if fa_status != 'active':
                    return jsonify({
                        'success': False,
                        'message': 'Selected finance account is not active.',
                    }), 400

                cursor.execute(
                    """
                    SELECT id, category, academic_year_id, term_id, created_by
                    FROM fee_structures
                    WHERE id = %s AND status = 'active'
                    """,
                    (structure_id,),
                )
                anchor_row = cursor.fetchone()
                if not anchor_row:
                    return jsonify({'success': False, 'message': 'Fee structure not found'}), 404

                if isinstance(anchor_row, dict):
                    if not academic_year_id:
                        academic_year_id = anchor_row.get('academic_year_id')
                    if not term_id:
                        term_id = anchor_row.get('term_id')
                    created_by = anchor_row.get('created_by') or employee_id
                else:
                    if not academic_year_id:
                        academic_year_id = anchor_row[2]
                    if not term_id:
                        term_id = anchor_row[3]
                    created_by = anchor_row[4] if len(anchor_row) > 4 else employee_id

                if not academic_year_id or not term_id:
                    return jsonify({
                        'success': False,
                        'message': 'Academic year and term are required.',
                    }), 400

                siblings = _fetch_fee_structure_batch_siblings(cursor, structure_id)
                sibling_by_level = {
                    int(s['academic_level_id']): int(s['id'])
                    for s in siblings
                    if s.get('academic_level_id') is not None
                }
                batch_ids = list(sibling_by_level.values())
                selected_set = set(academic_level_ids)

                for level_id, sid in sibling_by_level.items():
                    if level_id not in selected_set:
                        if _fee_structure_has_payments(cursor, sid):
                            connection.rollback()
                            return jsonify({
                                'success': False,
                                'message': (
                                    'Cannot remove a level that already has student payments. '
                                    'Deselect other levels or delete payments first.'
                                ),
                            }), 400
                        cursor.execute(
                            "DELETE FROM fee_structures WHERE id = %s",
                            (sid,),
                        )

                update_fields = [
                    "finance_account_id = %s",
                    "fee_name = %s",
                    "category = %s",
                    "start_date = %s",
                    "end_date = %s",
                    "payment_deadline = %s",
                    "total_amount = %s",
                    "academic_year_id = %s",
                    "term_id = %s",
                ]
                updated_ids = []
                total_items_inserted = 0

                for level_id in academic_level_ids:
                    conflict_msg = _fee_structure_category_conflict(
                        cursor,
                        academic_year_id,
                        term_id,
                        level_id,
                        category,
                        exclude_ids=batch_ids,
                    )
                    if conflict_msg:
                        connection.rollback()
                        return jsonify({'success': False, 'message': conflict_msg}), 400

                    if level_id in sibling_by_level:
                        sid = sibling_by_level[level_id]
                        cursor.execute(
                            f"""
                            UPDATE fee_structures
                            SET academic_level_id = %s, {', '.join(update_fields)}
                            WHERE id = %s
                            """,
                            (
                                level_id,
                                finance_account_id,
                                fee_name,
                                category,
                                start_date,
                                end_date,
                                payment_deadline,
                                total_amount,
                                academic_year_id,
                                term_id,
                                sid,
                            ),
                        )
                    else:
                        cursor.execute(
                            """
                            INSERT INTO fee_structures
                            (academic_level_id, finance_account_id, academic_year_id, term_id,
                             fee_name, category, start_date, end_date, payment_deadline,
                             total_amount, created_by)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                            """,
                            (
                                level_id,
                                finance_account_id,
                                academic_year_id,
                                term_id,
                                fee_name,
                                category,
                                start_date,
                                end_date,
                                payment_deadline,
                                total_amount,
                                created_by,
                            ),
                        )
                        sid = cursor.lastrowid

                    items_inserted = _replace_fee_structure_items(cursor, sid, fee_items)
                    if items_inserted == 0:
                        connection.rollback()
                        return jsonify({
                            'success': False,
                            'message': (
                                'No valid votes were provided. Each vote needs a name, '
                                'description, and amount greater than 0.'
                            ),
                        }), 400
                    updated_ids.append(sid)
                    total_items_inserted += items_inserted
                    _sync_student_fee_votes_for_structure(cursor, sid)

                connection.commit()

                return jsonify({
                    'success': True,
                    'message': (
                        f'Updated {len(updated_ids)} fee structure(s) with '
                        f'{total_items_inserted} vote row(s).'
                    ),
                    'fee_structure_ids': updated_ids,
                    'items_count': total_items_inserted,
                }), 200
                
        except Exception as e:
            connection.rollback()
            print(f"Error updating fee structure: {e}")
            return jsonify({'success': False, 'message': f'Error updating fee structure: {str(e)}'}), 500
        finally:
            connection.close()
            
    except Exception as e:
        print(f"Error in update_fee_structure: {e}")
        return jsonify({'success': False, 'message': 'An error occurred'}), 500


def _finance_delete_verification_target_key(action, target_parts):
    """Stable session key tying a verification code to one delete target."""
    if action == 'finance_account':
        return f'account:{int(target_parts[0])}'
    if action == 'fee_structure':
        ids = sorted({int(x) for x in target_parts if int(x) > 0})
        return 'fee_structure:' + ','.join(str(i) for i in ids)
    return ''


def _resolve_session_verification_email(cursor):
    """Email and display name for the logged-in user."""
    email = normalize_login_email(session.get('email') or '')
    name = (session.get('full_name') or '').strip() or 'User'
    if email:
        return email, name

    employee_id = session.get('employee_id') or session.get('user_id')
    if employee_id:
        cursor.execute(
            """
            SELECT full_name, email
            FROM employees
            WHERE id = %s OR employee_id = %s
            LIMIT 1
            """,
            (employee_id, employee_id),
        )
        row = cursor.fetchone()
        if row:
            if isinstance(row, dict):
                name = (row.get('full_name') or '').strip() or name
                email = normalize_login_email(row.get('email') or '')
            else:
                name = (row[0] or '').strip() if len(row) > 0 else name
                email = normalize_login_email(row[1] or '') if len(row) > 1 else ''
    return email, name


def send_finance_delete_verification_email(to_email, recipient_name, verification_code, action_label):
    """Send 6-digit confirmation code before deleting finance data."""
    try:
        if not apply_mail_config_from_env_and_integration():
            print("Finance delete code: SMTP not configured.")
            return False
        settings = get_school_settings()
        school_name = (settings.get('school_name') or os.environ.get('SCHOOL_NAME') or 'School').strip() or 'School'
        safe_name = (recipient_name or 'there').strip() or 'there'
        label = (action_label or 'this record').strip() or 'this record'
        subject = f"{school_name} — Delete confirmation code"
        html_body = f"""
        <!DOCTYPE html>
        <html><head><meta charset="UTF-8"></head>
        <body style="font-family:system-ui,sans-serif;line-height:1.6;color:#333;max-width:560px;margin:0 auto;padding:24px;">
            <p>Hello {safe_name},</p>
            <p>You requested to permanently delete {label}.</p>
            <p>Use this 6-digit code to confirm:</p>
            <p style="font-size:28px;font-weight:700;letter-spacing:0.2em;color:#1e293b;">{verification_code}</p>
            <p style="color:#64748b;font-size:14px;">This code expires in 10 minutes. If this wasn't you, ignore this email.</p>
            <p style="margin-top:24px;font-size:13px;color:#94a3b8;">{school_name}</p>
        </body></html>
        """
        text_body = (
            f"Hello {safe_name},\n\n"
            f"You requested to permanently delete {label}.\n\n"
            f"Confirmation code: {verification_code}\n\n"
            f"This code expires in 10 minutes. If you didn't request this, ignore it.\n\n{school_name}\n"
        )
        msg = Message(subject=subject, recipients=[to_email], html=html_body, body=text_body)
        mail.send(msg)
        return True
    except Exception as e:
        print(f"Error sending finance delete verification email: {e}")
        return False


def _issue_finance_delete_verification_code(cursor, action, target_key, action_label):
    """Create session-bound delete code and email it to the logged-in user."""
    recipient_email, recipient_name = _resolve_session_verification_email(cursor)
    if not recipient_email:
        return False, 'Your account has no email configured to receive the confirmation code.', None

    code = ''.join(secrets.choice('0123456789') for _ in range(6))
    session['finance_delete_verification'] = {
        'action': action,
        'target_key': target_key,
        'code_hash': generate_password_hash(code),
        'requested_by': session.get('employee_id') or session.get('user_id'),
        'expires_at': (datetime.utcnow() + timedelta(minutes=10)).isoformat(),
    }
    session.modified = True

    sent = send_finance_delete_verification_email(
        recipient_email, recipient_name, code, action_label,
    )
    if not sent:
        return True, (
            'Email delivery is currently unavailable. Use the code shown on screen to continue.'
        ), code
    return True, f'Confirmation code sent to {recipient_email}.', None


def _validate_finance_delete_verification_code(action, target_key, confirmation_code):
    """Validate emailed delete confirmation code for the current session."""
    code = str(confirmation_code or '').strip().replace(' ', '')
    if not code:
        return False, 'Enter the 6-digit confirmation code sent to your email.'
    if (not code.isdigit()) or len(code) != 6:
        return False, 'Enter a valid 6-digit confirmation code.'

    pending = session.get('finance_delete_verification') or {}
    expires_at_str = str(pending.get('expires_at') or '').strip()
    try:
        expires_at = datetime.fromisoformat(expires_at_str) if expires_at_str else None
    except Exception:
        expires_at = None
    is_expired = (expires_at is None) or (datetime.utcnow() > expires_at)
    pending_matches = (
        pending.get('action') == action and
        pending.get('target_key') == target_key
    )
    if not pending_matches or is_expired:
        return False, 'Your confirmation session is missing or expired. Request a new 6-digit code.'

    pending_code_hash = str(pending.get('code_hash') or '')
    code_ok = False
    try:
        code_ok = bool(pending_code_hash) and check_password_hash(pending_code_hash, code)
    except Exception:
        code_ok = False
    if not code_ok:
        return False, 'Invalid confirmation code.'

    requested_by = pending.get('requested_by')
    current_user = session.get('employee_id') or session.get('user_id')
    if requested_by and current_user and str(requested_by) != str(current_user):
        return False, 'Confirmation code was issued to another user session.'

    session.pop('finance_delete_verification', None)
    session.modified = True
    return True, ''


@app.route('/dashboard/employee/student-fees/fee-structure/<int:structure_id>/delete/request-code', methods=['POST'])
@login_required
def request_fee_structure_delete_code(structure_id):
    """Email a 6-digit code before deleting a fee structure."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_technician = user_role == 'technician'
    has_delete_fee_structure_permission = check_permission_or_role(
        'delete_fee_structure', ['accountant', 'head of institution'],
    )
    has_manage_fees_permission = check_permission_or_role(
        'manage_fees', ['accountant', 'head of institution'],
    )
    if not (is_technician or has_delete_fee_structure_permission or has_manage_fees_permission):
        return jsonify({'success': False, 'message': 'Permission denied.'}), 403

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            data = request.get_json(silent=True) or {}
            requested_ids = data.get('structure_ids')
            batch_ids = []
            if isinstance(requested_ids, (list, tuple)) and requested_ids:
                try:
                    batch_ids = sorted({int(x) for x in requested_ids if int(x) > 0})
                except (TypeError, ValueError):
                    batch_ids = []
            if not batch_ids:
                batch_ids = _fetch_fee_structure_batch_ids_for_delete(cursor, structure_id)
            if not batch_ids:
                return jsonify({'success': False, 'message': 'Fee structure not found.'}), 404

            cursor.execute(
                "SELECT fee_name FROM fee_structures WHERE id = %s LIMIT 1",
                (structure_id,),
            )
            row = cursor.fetchone()
            fee_name = (
                (row.get('fee_name') or '').strip()
                if isinstance(row, dict) else (row[0] or '').strip()
            ) if row else 'Fee structure'
            if not fee_name:
                fee_name = 'Fee structure'

            target_key = _finance_delete_verification_target_key('fee_structure', batch_ids)
            ok, message, dev_code = _issue_finance_delete_verification_code(
                cursor,
                'fee_structure',
                target_key,
                f'fee structure "{fee_name}"',
            )
            if not ok:
                return jsonify({'success': False, 'message': message}), 400
            payload = {'success': True, 'message': message}
            if dev_code:
                payload['delivery'] = 'onscreen'
                payload['dev_code'] = dev_code
            return jsonify(payload), 200
    except Exception as e:
        print(f"request_fee_structure_delete_code: {e}")
        return jsonify({'success': False, 'message': 'Could not send confirmation code.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/student-fees/fee-structure/<int:structure_id>/delete', methods=['POST'])
@login_required
def delete_fee_structure(structure_id):
    """Delete a fee structure"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    # Check permission-based access - specific permission for deleting fee structures
    has_delete_fee_structure_permission = check_permission_or_role('delete_fee_structure', ['accountant', 'head of institution'])
    has_manage_fees_permission = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_delete_fee_structure_permission or has_manage_fees_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to delete fee structures. Please contact your administrator.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            data = request.get_json(silent=True) or {}
            requested_ids = data.get('structure_ids')
            batch_ids = []
            if isinstance(requested_ids, (list, tuple)) and requested_ids:
                try:
                    batch_ids = sorted({
                        int(x) for x in requested_ids if int(x) > 0
                    })
                except (TypeError, ValueError):
                    batch_ids = []
            if not batch_ids:
                batch_ids = _fetch_fee_structure_batch_ids_for_delete(cursor, structure_id)
            if batch_ids:
                placeholders = ','.join(['%s'] * len(batch_ids))
                cursor.execute(
                    f"SELECT id FROM fee_structures WHERE id IN ({placeholders})",
                    tuple(batch_ids),
                )
                batch_ids = []
                for row in cursor.fetchall() or []:
                    rid = row.get('id') if isinstance(row, dict) else row[0]
                    if rid is not None:
                        batch_ids.append(int(rid))
            if not batch_ids:
                return jsonify({'success': False, 'message': 'Fee structure not found.'}), 404

            cursor.execute(
                "SELECT fee_name FROM fee_structures WHERE id = %s LIMIT 1",
                (structure_id,),
            )
            row = cursor.fetchone()
            fee_name = (
                (row.get('fee_name') or '').strip()
                if isinstance(row, dict) else (row[0] or '').strip()
            ) if row else 'Fee structure'
            if not fee_name:
                fee_name = 'Fee structure'

            target_key = _finance_delete_verification_target_key('fee_structure', batch_ids)
            confirmation_code = data.get('confirmation_code')
            code_ok, code_message = _validate_finance_delete_verification_code(
                'fee_structure', target_key, confirmation_code,
            )
            if not code_ok:
                return jsonify({'success': False, 'message': code_message}), 401

            total_payments = 0
            for sid in batch_ids:
                purged = _purge_fee_structure_fee_transactions(cursor, sid)
                total_payments += int(purged.get('payments') or 0)
                cursor.execute("DELETE FROM fee_structures WHERE id = %s", (sid,))

            connection.commit()

            level_note = ''
            if len(batch_ids) > 1:
                level_note = f' ({len(batch_ids)} class levels)'

            if total_payments:
                message = (
                    f'Fee structure "{fee_name}"{level_note} deleted with '
                    f'{total_payments} student payment(s) and related ledger entries.'
                )
            else:
                message = f'Fee structure "{fee_name}"{level_note} deleted successfully.'
            return jsonify({'success': True, 'message': message}), 200
    except Exception as e:
        connection.rollback()
        print(f"Error deleting fee structure: {e}")
        return jsonify({'success': False, 'message': f'Error deleting fee structure: {str(e)}'}), 500
    finally:
        connection.close()

@app.route('/dashboard/employee/staff-and-salaries')
@login_required
def staff_and_salaries():
    """Staff and Salaries page for employees - unified with tabs"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permissions - accountant, principal, super admin, technician can access
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    # Check permission-based access
    is_technician = user_role == 'technician'
    has_salary_permission = check_permission_or_role('manage_salaries', 
                                                     ['accountant', 'head of institution', 'super admin'])
    
    # Permission check handles role fallback if no permissions are assigned
    if not (is_technician or has_salary_permission):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get filter parameters for salary records
    filter_type = request.args.get('filter', 'all')
    filter_month = request.args.get('month', '')
    filter_year = request.args.get('year', '')
    
    # Fetch all data types
    connection = get_db_connection()
    employees = []
    active_employees_for_register = []
    salary_records_list = []
    audits = []
    payment_analytics = _fetch_payroll_payment_analytics([])
    roles_set = set()
    filter_info = {'type': filter_type, 'month': filter_month, 'year': filter_year}
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # 1. Fetch employees with their salary information
                cursor.execute("""
                    SELECT e.id, e.employee_id, e.full_name, e.email, e.phone, e.id_number, e.role, e.status, 
                           e.profile_picture, e.created_at,
                           es.id as salary_id, es.effective_date, es.basic_salary, es.house_allowance,
                           es.transport_allowance, es.medical_allowance, es.overtime, es.bonus,
                           es.paye, es.nssf, es.nhif, es.sacco, es.staff_loans, es.absenteeism,
                           es.total_earnings, es.total_deductions, es.net_salary, es.is_active as salary_is_active,
                           es.updated_at as salary_updated_at, es.payment_period
                    FROM employees e
                    LEFT JOIN employee_salaries es ON e.id = es.employee_id AND es.is_active = TRUE
                    WHERE e.status = 'active'
                    ORDER BY e.full_name ASC
                """)
                employees_raw = cursor.fetchall()
                
                # Process employees and calculate stats
                for emp in employees_raw:
                    # Check if salary was edited (check if there's an audit record)
                    salary_edited = False
                    if emp.get('salary_id'):
                        try:
                            cursor.execute("""
                                SELECT COUNT(*) as audit_count 
                                FROM employee_salary_audits 
                                WHERE salary_id = %s
                            """, (emp.get('salary_id'),))
                            audit_result = cursor.fetchone()
                            salary_edited = audit_result.get('audit_count', 0) > 0 if audit_result else False
                        except:
                            # Table might not exist yet, that's okay
                            salary_edited = False
                    
                    emp_dict = dict(emp)
                    emp_dict['salary_edited'] = salary_edited
                    employees.append(emp_dict)
                    roles_set.add(emp.get('role', ''))

                # Active employees eligible for new salary registration (no active salary yet)
                cursor.execute("""
                    SELECT e.id, e.employee_id, e.full_name, e.role
                    FROM employees e
                    WHERE e.status = 'active'
                    AND NOT EXISTS (
                        SELECT 1 FROM employee_salaries es
                        WHERE es.employee_id = e.id AND es.is_active = TRUE
                    )
                    ORDER BY e.full_name ASC
                """)
                active_employees_for_register = cursor.fetchall() or []
                
                # 2. Fetch salary records with payment information
                from datetime import datetime, timedelta
                from dateutil.relativedelta import relativedelta
                
                base_query = """
                    SELECT 
                        es.id as salary_id,
                        es.employee_id,
                        es.net_salary,
                        es.effective_date,
                        es.payment_period,
                        e.full_name,
                        e.phone,
                        e.employee_id as emp_code
                    FROM employee_salaries es
                    INNER JOIN employees e ON es.employee_id = e.id
                    WHERE 1=1
                """
                
                query_params = []
                
                # Add period filter
                if filter_type == 'month' and filter_month:
                    base_query += " AND es.is_active = TRUE AND DATE_FORMAT(es.effective_date, '%%Y-%%m') = %s"
                    query_params.append(filter_month)
                elif filter_type == 'year' and filter_year:
                    base_query += " AND YEAR(es.effective_date) = %s"
                    query_params.append(int(filter_year))
                else:
                    base_query += " AND es.is_active = TRUE"
                
                base_query += " ORDER BY e.full_name ASC"
                
                cursor.execute(base_query, tuple(query_params) if query_params else None)
                records = cursor.fetchall()
                
                for record in records:
                    salary_id = record.get('salary_id')
                    employee_id = record.get('employee_id')
                    net_salary = float(record.get('net_salary', 0))
                    effective_date = record.get('effective_date')
                    payment_period = record.get('payment_period', 'Monthly')
                    
                    # Calculate current period based on effective_date and payment_period
                    current_date = datetime.now().date()
                    if isinstance(effective_date, str):
                        effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
                    elif hasattr(effective_date, 'date'):
                        effective_date = effective_date.date()
                    
                    # Calculate period start and end dates
                    period_start, period_end, current_period_num = calculate_period_dates(
                        effective_date, payment_period, current_date
                    )
                    
                    # Get payments for current period
                    cursor.execute("""
                        SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                        FROM employee_salary_payments
                        WHERE salary_id = %s 
                        AND payment_date >= %s 
                        AND payment_date <= %s
                    """, (salary_id, period_start, period_end))
                    current_period_paid = cursor.fetchone()
                    total_paid_current = float(current_period_paid.get('total_paid', 0) if current_period_paid else 0)
                    
                    # Calculate carry-forward balance from previous period
                    carry_forward = 0.0
                    if current_period_num > 1:
                        # Get previous period dates
                        prev_period_start, prev_period_end, _ = calculate_period_dates(
                            effective_date, payment_period, period_start - timedelta(days=1)
                        )
                        
                        # Get payments for previous period
                        cursor.execute("""
                            SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                            FROM employee_salary_payments
                            WHERE salary_id = %s 
                            AND payment_date >= %s 
                            AND payment_date <= %s
                        """, (salary_id, prev_period_start, prev_period_end))
                        prev_period_paid = cursor.fetchone()
                        total_paid_prev = float(prev_period_paid.get('total_paid', 0) if prev_period_paid else 0)
                        
                        # Calculate previous period balance (net_salary - total_paid)
                        carry_forward = max(0, net_salary - total_paid_prev)
                    
                    # Amount to be paid = net_salary + carry_forward
                    amount_to_be_paid = net_salary + carry_forward
                    balance = amount_to_be_paid - total_paid_current
                    
                    salary_records_list.append({
                        'salary_id': salary_id,
                        'employee_id': employee_id,
                        'employee_code': record.get('emp_code'),
                        'employee_name': record.get('full_name'),
                        'phone': record.get('phone'),
                        'amount_to_be_paid': amount_to_be_paid,
                        'total_paid': total_paid_current,
                        'balance': balance,
                        'effective_date': effective_date,
                        'payment_period': payment_period,
                        'carry_forward': carry_forward,
                        'current_period_start': period_start,
                        'current_period_end': period_end
                    })
                
                # 3. Fetch salary audits
                try:
                    cursor.execute("""
                        SELECT 
                            esa.id,
                            esa.salary_id,
                            esa.employee_id,
                            esa.field_name,
                            esa.old_value,
                            esa.new_value,
                            esa.edited_by,
                            esa.edited_by_name,
                            esa.edited_at,
                            e.full_name as employee_name,
                            e.employee_id as employee_code
                        FROM employee_salary_audits esa
                        INNER JOIN employees e ON esa.employee_id = e.id
                        ORDER BY esa.edited_at DESC
                    """)
                    audits = cursor.fetchall()
                except Exception as e:
                    # Table might not exist yet
                    audits = []
                    print(f"Salary audits table might not exist: {e}")

                payment_analytics = _fetch_payroll_payment_analytics(salary_records_list, cursor)
                    
        except Exception as e:
            print(f"Error fetching data: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading data. Please try again.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass  # Connection might already be closed
    
    return render_template('dashboards/staff_and_salaries.html', 
                         employees=employees,
                         active_employees_for_register=active_employees_for_register,
                         salary_records=salary_records_list,
                         audits=audits,
                         payment_analytics=payment_analytics,
                         filter_info=filter_info)

def calculate_period_dates(effective_date, payment_period, reference_date):
    """
    Calculate period start and end dates based on payment_period and effective_date.
    Returns: (period_start, period_end, period_number)
    """
    if isinstance(effective_date, str):
        effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
    elif hasattr(effective_date, 'date'):
        effective_date = effective_date.date()
    
    if isinstance(reference_date, str):
        reference_date = datetime.strptime(reference_date, '%Y-%m-%d').date()
    elif hasattr(reference_date, 'date'):
        reference_date = reference_date.date()
    
    # Calculate how many periods have passed since effective_date
    if payment_period == 'Daily':
        days_diff = (reference_date - effective_date).days
        period_num = days_diff + 1
        period_start = effective_date + timedelta(days=days_diff)
        period_end = period_start
    elif payment_period == 'Weekly':
        weeks_diff = (reference_date - effective_date).days // 7
        period_num = weeks_diff + 1
        period_start = effective_date + timedelta(weeks=weeks_diff)
        period_end = period_start + timedelta(days=6)
    elif payment_period == 'Monthly':
        months_diff = (reference_date.year - effective_date.year) * 12 + (reference_date.month - effective_date.month)
        period_num = months_diff + 1
        period_start = effective_date + relativedelta(months=months_diff)
        # Set to first day of the month
        period_start = period_start.replace(day=1)
        # Last day of the month
        if period_start.month == 12:
            period_end = period_start.replace(day=31)
        else:
            period_end = (period_start + relativedelta(months=1) - timedelta(days=1))
    elif payment_period == 'Quarterly':
        months_diff = (reference_date.year - effective_date.year) * 12 + (reference_date.month - effective_date.month)
        quarters_diff = months_diff // 3
        period_num = quarters_diff + 1
        quarter_start_month = ((effective_date.month - 1) // 3) * 3 + 1
        period_start = effective_date.replace(month=quarter_start_month, day=1) + relativedelta(months=quarters_diff * 3)
        period_end = period_start + relativedelta(months=3) - timedelta(days=1)
    elif payment_period == 'Semi-Annual':
        months_diff = (reference_date.year - effective_date.year) * 12 + (reference_date.month - effective_date.month)
        semis_diff = months_diff // 6
        period_num = semis_diff + 1
        semi_start_month = ((effective_date.month - 1) // 6) * 6 + 1
        period_start = effective_date.replace(month=semi_start_month, day=1) + relativedelta(months=semis_diff * 6)
        period_end = period_start + relativedelta(months=6) - timedelta(days=1)
    elif payment_period == '3/4 Annual':
        months_diff = (reference_date.year - effective_date.year) * 12 + (reference_date.month - effective_date.month)
        periods_diff = months_diff // 9
        period_num = periods_diff + 1
        period_start_month = ((effective_date.month - 1) // 9) * 9 + 1
        period_start = effective_date.replace(month=period_start_month, day=1) + relativedelta(months=periods_diff * 9)
        period_end = period_start + relativedelta(months=9) - timedelta(days=1)
    elif payment_period == 'Annually':
        years_diff = reference_date.year - effective_date.year
        period_num = years_diff + 1
        period_start = effective_date.replace(year=effective_date.year + years_diff, month=1, day=1)
        period_end = period_start.replace(month=12, day=31)
    else:
        # Default to monthly
        months_diff = (reference_date.year - effective_date.year) * 12 + (reference_date.month - effective_date.month)
        period_num = months_diff + 1
        period_start = effective_date + relativedelta(months=months_diff)
        period_start = period_start.replace(day=1)
        if period_start.month == 12:
            period_end = period_start.replace(day=31)
        else:
            period_end = (period_start + relativedelta(months=1) - timedelta(days=1))
    
    return period_start, period_end, period_num


def _fetch_accountant_fee_overview_snapshot(cursor):
    """In-session student fee totals for accountant home (same rules as finance overview)."""
    bundle = _finance_overview_student_fee_bundle(cursor)
    rows = bundle.get('student_rows') or []
    students_with_balance = sum(
        1 for r in rows if (r.get('balance') is not None and float(r.get('balance') or 0) > 0)
    )
    total_outstanding = float(bundle.get('total_outstanding') or 0)
    sum_total = float(bundle.get('sum_total_amount') or 0)
    sum_paid = float(bundle.get('sum_paid_amount') or 0)
    collection_pct = round((sum_paid / sum_total) * 100, 1) if sum_total > 0 else 0.0
    return {
        'student_count': len(rows),
        'students_with_balance': students_with_balance,
        'total_outstanding': total_outstanding,
        'total_outstanding_display': _format_kes_amount(total_outstanding),
        'sum_total_amount': sum_total,
        'sum_total_display': _format_kes_amount(sum_total),
        'sum_paid_amount': sum_paid,
        'sum_paid_display': _format_kes_amount(sum_paid),
        'collection_pct': collection_pct,
    }


