@app.route('/dashboard/employee/staff-and-salaries/get-employee-salary/<int:employee_id>')
@login_required
def get_employee_salary(employee_id):
    """Get active salary information for an employee including total paid"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    if not (is_accountant or is_principal or is_super_admin or is_technician):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Ensure payment_period column exists
            try:
                cursor.execute("ALTER TABLE employee_salaries ADD COLUMN payment_period ENUM('Daily', 'Weekly', 'Monthly', 'Quarterly', 'Semi-Annual', '3/4 Annual', 'Annually') DEFAULT 'Monthly' AFTER effective_date")
            except Exception as e:
                # Column might already exist, ignore the error
                pass
            
            # Get active salary
            cursor.execute("""
                SELECT es.*
                FROM employee_salaries es
                WHERE es.employee_id = %s AND es.is_active = TRUE
                ORDER BY es.effective_date DESC
                LIMIT 1
            """, (employee_id,))
            salary = cursor.fetchone()
            
            if not salary:
                return jsonify({'success': False, 'message': 'No active salary found for this employee'}), 404
            
            # Calculate current period and payments with carry-forward
            effective_date = salary.get('effective_date')
            payment_period = salary.get('payment_period', 'Monthly')
            net_salary = float(salary.get('net_salary', 0))
            
            if isinstance(effective_date, str):
                effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
            elif hasattr(effective_date, 'date'):
                effective_date = effective_date.date()
            
            current_date = datetime.now().date()
            period_start, period_end, current_period_num = calculate_period_dates(
                effective_date, payment_period, current_date
            )
            
            # Get payments for current period
            cursor.execute("""
                SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                FROM employee_salary_payments
                WHERE salary_id = %s 
                AND payment_date >= %s 
                AND payment_date <= %s
            """, (salary.get('id'), period_start, period_end))
            current_period_paid = cursor.fetchone()
            total_paid_current = float(current_period_paid.get('total_paid', 0) if current_period_paid else 0)
            
            # Calculate carry-forward balance from previous period
            carry_forward = 0.0
            if current_period_num > 1:
                # Get previous period dates
                prev_period_start, prev_period_end, _ = calculate_period_dates(
                    effective_date, payment_period, period_start - timedelta(days=1)
                )
                
                # Get payments for previous period
                cursor.execute("""
                    SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                    FROM employee_salary_payments
                    WHERE salary_id = %s 
                    AND payment_date >= %s 
                    AND payment_date <= %s
                """, (salary.get('id'), prev_period_start, prev_period_end))
                prev_period_paid = cursor.fetchone()
                total_paid_prev = float(prev_period_paid.get('total_paid', 0) if prev_period_paid else 0)
                
                # Calculate previous period balance (net_salary - total_paid)
                carry_forward = max(0, net_salary - total_paid_prev)
            
            # Amount to be paid = net_salary + carry_forward
            amount_to_be_paid = net_salary + carry_forward
            balance = amount_to_be_paid - total_paid_current
            
            return jsonify({
                'success': True,
                'salary': {
                    'id': salary.get('id'),
                    'employee_id': salary.get('employee_id'),
                    'effective_date': salary.get('effective_date').strftime('%Y-%m-%d') if salary.get('effective_date') else '',
                    'net_salary': net_salary,
                    'total_paid': total_paid_current,
                    'amount_to_be_paid': amount_to_be_paid,
                    'carry_forward': carry_forward,
                    'balance': balance
                }
            })
    except Exception as e:
        print(f"Error fetching employee salary: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'Error fetching salary information'}), 500
    finally:
        connection.close()

@app.route('/dashboard/employee/staff-and-salaries/record-salary-payment', methods=['POST'])
@login_required
def record_salary_payment():
    """Record a salary payment for an employee"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    if not (is_accountant or is_principal or is_super_admin or is_technician):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    try:
        data = request.get_json()
        employee_id = data.get('employee_id')
        salary_id = data.get('salary_id')
        amount_paid = data.get('amount_paid')
        payment_date = data.get('payment_date')
        payment_method = data.get('payment_method')
        reference_number = data.get('reference_number')
        notes = data.get('notes')
        
        if not all([employee_id, salary_id, amount_paid, payment_date, payment_method]):
            return jsonify({'success': False, 'message': 'Missing required fields'}), 400
        
        try:
            amount_paid = float(amount_paid)
            if amount_paid <= 0:
                return jsonify({'success': False, 'message': 'Payment amount must be greater than 0'}), 400
        except (ValueError, TypeError):
            return jsonify({'success': False, 'message': 'Invalid payment amount'}), 400
        
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed'}), 500
        
        try:
            with connection.cursor() as cursor:
                # Ensure payment_period column exists
                try:
                    cursor.execute("ALTER TABLE employee_salaries ADD COLUMN payment_period ENUM('Daily', 'Weekly', 'Monthly', 'Quarterly', 'Semi-Annual', '3/4 Annual', 'Annually') DEFAULT 'Monthly' AFTER effective_date")
                except Exception as e:
                    # Column might already exist, ignore the error
                    pass
                
                # Verify salary exists and is active
                cursor.execute("""
                    SELECT net_salary, effective_date, payment_period FROM employee_salaries
                    WHERE id = %s AND employee_id = %s AND is_active = TRUE
                """, (salary_id, employee_id))
                salary = cursor.fetchone()
                
                if not salary:
                    return jsonify({'success': False, 'message': 'Salary not found or inactive'}), 404
                
                # Calculate current period and balance with carry-forward
                effective_date = salary.get('effective_date')
                payment_period = salary.get('payment_period', 'Monthly')
                net_salary = float(salary.get('net_salary', 0))
                
                if isinstance(effective_date, str):
                    effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
                elif hasattr(effective_date, 'date'):
                    effective_date = effective_date.date()
                
                # Use payment_date to determine which period this payment belongs to
                if isinstance(payment_date, str):
                    payment_date_obj = datetime.strptime(payment_date, '%Y-%m-%d').date()
                else:
                    payment_date_obj = payment_date
                
                period_start, period_end, current_period_num = calculate_period_dates(
                    effective_date, payment_period, payment_date_obj
                )
                
                # Get payments for current period
                cursor.execute("""
                    SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                    FROM employee_salary_payments
                    WHERE salary_id = %s 
                    AND payment_date >= %s 
                    AND payment_date <= %s
                """, (salary_id, period_start, period_end))
                current_period_paid = cursor.fetchone()
                total_paid_current = float(current_period_paid.get('total_paid', 0) if current_period_paid else 0)
                
                # Calculate carry-forward balance from previous period
                carry_forward = 0.0
                if current_period_num > 1:
                    # Get previous period dates
                    prev_period_start, prev_period_end, _ = calculate_period_dates(
                        effective_date, payment_period, period_start - timedelta(days=1)
                    )
                    
                    # Get payments for previous period
                    cursor.execute("""
                        SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                        FROM employee_salary_payments
                        WHERE salary_id = %s 
                        AND payment_date >= %s 
                        AND payment_date <= %s
                    """, (salary_id, prev_period_start, prev_period_end))
                    prev_period_paid = cursor.fetchone()
                    total_paid_prev = float(prev_period_paid.get('total_paid', 0) if prev_period_paid else 0)
                    
                    # Calculate previous period balance (net_salary - total_paid)
                    carry_forward = max(0, net_salary - total_paid_prev)
                
                # Amount to be paid = net_salary + carry_forward
                amount_to_be_paid = net_salary + carry_forward
                balance = amount_to_be_paid - total_paid_current
                
                # Check if payment exceeds balance
                if amount_paid > balance:
                    return jsonify({'success': False, 'message': 'Payment amount exceeds the remaining balance'}), 400
                
                # Ensure payments table exists
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS employee_salary_payments (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        employee_id INT NOT NULL,
                        salary_id INT NOT NULL,
                        amount_paid DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        payment_date DATE NOT NULL,
                        payment_method ENUM('Cash', 'Bank Transfer', 'Cheque', 'Mobile Money', 'Credit/Debit Card') DEFAULT 'Bank Transfer',
                        reference_number VARCHAR(255),
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                        FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
                        FOREIGN KEY (salary_id) REFERENCES employee_salaries(id) ON DELETE CASCADE,
                        INDEX idx_employee_id (employee_id),
                        INDEX idx_salary_id (salary_id),
                        INDEX idx_payment_date (payment_date)
                    )
                """)
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS employee_salary_audits (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        salary_id INT NOT NULL,
                        employee_id INT NOT NULL,
                        field_name VARCHAR(100) NOT NULL,
                        old_value TEXT,
                        new_value TEXT,
                        edited_by INT NOT NULL,
                        edited_by_name VARCHAR(255),
                        edited_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        FOREIGN KEY (salary_id) REFERENCES employee_salaries(id) ON DELETE CASCADE,
                        FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
                        FOREIGN KEY (edited_by) REFERENCES employees(id) ON DELETE CASCADE,
                        INDEX idx_salary_id (salary_id),
                        INDEX idx_employee_id (employee_id),
                        INDEX idx_edited_at (edited_at)
                    )
                """)
                _ensure_salary_audit_payment_column(cursor)

                # Record payment
                cursor.execute("""
                    INSERT INTO employee_salary_payments
                    (employee_id, salary_id, amount_paid, payment_date, payment_method, reference_number, notes)
                    VALUES (%s, %s, %s, %s, %s, %s, %s)
                """, (employee_id, salary_id, amount_paid, payment_date, payment_method, reference_number, notes))
                payment_id = cursor.lastrowid

                editor_id, editor_name = _resolve_payroll_editor(cursor, session)
                _log_salary_payment_audit(
                    cursor,
                    payment_id,
                    salary_id,
                    employee_id,
                    amount_paid,
                    payment_date,
                    payment_method,
                    reference_number,
                    notes,
                    balance,
                    editor_id,
                    editor_name,
                )

                connection.commit()

                return jsonify({
                    'success': True,
                    'message': 'Payment recorded successfully',
                    'payment_id': payment_id,
                })
        except Exception as e:
            connection.rollback()
            print(f"Error recording salary payment: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'message': f'Error recording payment: {str(e)}'}), 500
        finally:
            connection.close()
    except Exception as e:
        print(f"Error in record_salary_payment: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'An error occurred'}), 500

@app.route('/dashboard/employee/staff-and-salaries/get-payment-history/<int:employee_id>/<int:salary_id>')
@login_required
def get_payment_history(employee_id, salary_id):
    """Get payment history for an employee's salary"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    if not (is_accountant or is_principal or is_super_admin or is_technician):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Get employee and salary information
            cursor.execute("""
                SELECT e.full_name, e.employee_id as employee_code, es.net_salary
                FROM employees e
                INNER JOIN employee_salaries es ON e.id = es.employee_id
                WHERE e.id = %s AND es.id = %s
            """, (employee_id, salary_id))
            employee_salary = cursor.fetchone()
            
            if not employee_salary:
                return jsonify({'success': False, 'message': 'Employee or salary not found'}), 404
            
            # Get all payment history for this salary
            cursor.execute("""
                SELECT 
                    id,
                    amount_paid,
                    payment_date,
                    payment_method,
                    reference_number,
                    notes,
                    created_at
                FROM employee_salary_payments
                WHERE employee_id = %s AND salary_id = %s
                ORDER BY payment_date DESC, created_at DESC
            """, (employee_id, salary_id))
            payments = cursor.fetchall()
            
            # Calculate total paid
            total_paid = sum(float(p.get('amount_paid', 0)) for p in payments)
            net_salary = float(employee_salary.get('net_salary', 0))
            
            return jsonify({
                'success': True,
                'employee_name': employee_salary.get('full_name'),
                'employee_code': employee_salary.get('employee_code'),
                'net_salary': net_salary,
                'total_paid': total_paid,
                'payments': [{
                    'id': p.get('id'),
                    'amount_paid': float(p.get('amount_paid', 0)),
                    'payment_date': p.get('payment_date').strftime('%Y-%m-%d') if p.get('payment_date') else '',
                    'payment_method': p.get('payment_method', ''),
                    'reference_number': p.get('reference_number', ''),
                    'notes': p.get('notes', ''),
                    'created_at': p.get('created_at').strftime('%Y-%m-%d %H:%M:%S') if p.get('created_at') else ''
                } for p in payments]
            })
    except Exception as e:
        print(f"Error fetching payment history: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'Error fetching payment history'}), 500
    finally:
        connection.close()

@app.route('/dashboard/employee/staff-and-salaries/salary-audits')
@login_required
def salary_audits():
    """Display salary audit trail"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    if not (is_accountant or is_principal or is_super_admin or is_technician):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    connection = get_db_connection()
    audits = []
    payment_analytics = _fetch_payroll_payment_analytics([])
    audit_summary = _fetch_salary_audit_summary([])
    
    if connection:
        try:
            with connection.cursor() as cursor:
                _backfill_salary_payment_audits(cursor, session)
                connection.commit()
                audits = _fetch_salary_audit_trail(cursor)
                audit_summary = _fetch_salary_audit_summary(audits)

                # Payment analytics (active payroll totals)
                salary_records_list = []
                from datetime import datetime, timedelta
                cursor.execute("""
                    SELECT es.id AS salary_id, es.employee_id, es.net_salary, es.effective_date,
                           es.payment_period, e.full_name, e.phone, e.employee_id AS emp_code
                    FROM employee_salaries es
                    INNER JOIN employees e ON es.employee_id = e.id
                    WHERE es.is_active = TRUE
                    ORDER BY e.full_name ASC
                """)
                records = cursor.fetchall() or []
                current_date = datetime.now().date()
                for record in records:
                    salary_id = record.get('salary_id')
                    net_salary = float(record.get('net_salary', 0))
                    effective_date = record.get('effective_date')
                    payment_period = record.get('payment_period', 'Monthly')
                    if isinstance(effective_date, str):
                        effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
                    elif hasattr(effective_date, 'date'):
                        effective_date = effective_date.date()
                    period_start, period_end, current_period_num = calculate_period_dates(
                        effective_date, payment_period, current_date
                    )
                    cursor.execute("""
                        SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
                        FROM employee_salary_payments
                        WHERE salary_id = %s AND payment_date >= %s AND payment_date <= %s
                    """, (salary_id, period_start, period_end))
                    current_period_paid = cursor.fetchone()
                    total_paid_current = float(
                        current_period_paid.get('total_paid', 0) if current_period_paid else 0
                    )
                    carry_forward = 0.0
                    if current_period_num > 1:
                        prev_period_start, prev_period_end, _ = calculate_period_dates(
                            effective_date, payment_period, period_start - timedelta(days=1)
                        )
                        cursor.execute("""
                            SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
                            FROM employee_salary_payments
                            WHERE salary_id = %s AND payment_date >= %s AND payment_date <= %s
                        """, (salary_id, prev_period_start, prev_period_end))
                        prev_period_paid = cursor.fetchone()
                        total_paid_prev = float(
                            prev_period_paid.get('total_paid', 0) if prev_period_paid else 0
                        )
                        carry_forward = max(0, net_salary - total_paid_prev)
                    amount_to_be_paid = net_salary + carry_forward
                    salary_records_list.append({
                        'amount_to_be_paid': amount_to_be_paid,
                        'total_paid': total_paid_current,
                        'balance': amount_to_be_paid - total_paid_current,
                    })
                payment_analytics = _fetch_payroll_payment_analytics(salary_records_list, cursor)
        except Exception as e:
            print(f"Error fetching salary audits: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading salary audits. Please try again.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass
    
    return render_template('dashboards/salary_audits.html',
                         audits=audits,
                         payment_analytics=payment_analytics,
                         audit_summary=audit_summary)


STAFF_MANAGEMENT_VIEW_ROLES = [
    'employee', 'super admin', 'head of institution', 'deputy head of institution',
    'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian',
    'warden', 'transport manager', 'store manager', 'technician', 'cateress',
]

STAFF_MANAGEMENT_LIST_SORTS = {
    'created_desc': ('e.created_at', 'DESC'),
    'created_asc': ('e.created_at', 'ASC'),
    'name_asc': ('e.full_name', 'ASC'),
    'name_desc': ('e.full_name', 'DESC'),
    'id_asc': ('e.employee_id', 'ASC'),
    'id_desc': ('e.employee_id', 'DESC'),
}


def _staff_management_has_access():
    return check_permission_or_role('view_staff', allowed_roles=STAFF_MANAGEMENT_VIEW_ROLES)


def _staff_management_teachers_sql_clause():
    """Match employees.role or employee_roles (teacher / teachers, normalized)."""
    return _sql_employee_is_teacher('e')


def _staff_management_status_where(status):
    status = (status or 'all').strip().lower()
    if status == 'active':
        return "e.status = 'active'", []
    if status == 'pending':
        return "e.status IN ('pending', 'pending approval')", []
    if status == 'suspended':
        return "e.status = 'suspended'", []
    if status == 'other':
        return (
            "e.status NOT IN ('active', 'pending', 'pending approval', 'suspended') "
            "AND COALESCE(e.status, '') != ''",
            [],
        )
    return '', []


def _staff_management_row_dict(row):
    if isinstance(row, dict):
        d = dict(row)
    else:
        d = {
            'id': row[0],
            'employee_id': row[1],
            'full_name': row[2],
            'email': row[3],
            'phone': row[4],
            'id_number': row[5],
            'role': row[6],
            'status': row[7],
            'profile_picture': row[8] if len(row) > 8 else None,
            'created_at': row[9] if len(row) > 9 else None,
            'staff_employee_number': row[10] if len(row) > 10 else None,
        }
    for k, val in list(d.items()):
        if isinstance(val, (datetime, date_cls)):
            d[k] = val.isoformat() if val else None
        elif val is not None and not isinstance(val, (bool, int, float, str, list)):
            d[k] = str(val)
    sn = d.get('staff_employee_number')
    if sn is None or sn == '':
        d['staff_employee_number'] = str(d.get('id') or '')
    else:
        d['staff_employee_number'] = str(sn)
    d['allocated_roles'] = d.get('allocated_roles') or []
    return d


def _fetch_staff_management_stats(cursor, teachers_only=False):
    extra = f" AND {_staff_management_teachers_sql_clause()}" if teachers_only else ''
    cursor.execute(f"""
        SELECT
            COUNT(*) AS total,
            SUM(CASE WHEN e.status = 'active' THEN 1 ELSE 0 END) AS active,
            SUM(CASE WHEN e.status IN ('pending', 'pending approval') THEN 1 ELSE 0 END) AS pending,
            SUM(CASE WHEN e.status = 'suspended' THEN 1 ELSE 0 END) AS suspended,
            SUM(CASE WHEN e.status NOT IN ('active', 'pending', 'pending approval', 'suspended')
                      AND COALESCE(e.status, '') != '' THEN 1 ELSE 0 END) AS other
        FROM employees e
        WHERE 1=1{extra}
    """)
    row = cursor.fetchone() or {}
    if isinstance(row, dict):
        return {
            'total': int(row.get('total') or 0),
            'active': int(row.get('active') or 0),
            'pending': int(row.get('pending') or 0),
            'suspended': int(row.get('suspended') or 0),
            'other': int(row.get('other') or 0),
        }
    return {
        'total': int(row[0] or 0),
        'active': int(row[1] or 0),
        'pending': int(row[2] or 0),
        'suspended': int(row[3] or 0) if len(row) > 3 else 0,
        'other': int(row[4] or 0) if len(row) > 4 else 0,
    }


def _fetch_staff_management_page(cursor, page=1, per_page=50, q='', status='all', sort='created_desc', teachers_only=False):
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    q = (q or '').strip()
    order_col, order_dir = STAFF_MANAGEMENT_LIST_SORTS.get(
        sort, STAFF_MANAGEMENT_LIST_SORTS['created_desc']
    )
    where = []
    params = []
    if teachers_only:
        where.append(_staff_management_teachers_sql_clause())
    status_sql, status_params = _staff_management_status_where(status)
    if status_sql:
        where.append(status_sql)
        params.extend(status_params)
    if q:
        like = '%' + q + '%'
        where.append(
            "(e.full_name LIKE %s OR e.email LIKE %s OR e.employee_id LIKE %s "
            f"OR CAST({_employee_staff_identity_sql('e')}) LIKE %s OR e.phone LIKE %s)"
        )
        params.extend([like, like, like, like, like])
    where_sql = (' WHERE ' + ' AND '.join(where)) if where else ''
    cursor.execute(f"SELECT COUNT(*) AS c FROM employees e{where_sql}", tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
    cursor.execute(
        f"""
        SELECT e.id, e.employee_id, e.full_name, e.email, e.phone, e.id_number, e.role, e.status,
               e.profile_picture, e.created_at,
               {_employee_staff_identity_sql('e')} AS staff_employee_number
        FROM employees e
        {where_sql}
        ORDER BY {order_col} {order_dir}, e.id ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    raw = cursor.fetchall() or []
    employees = [_staff_management_row_dict(r) for r in raw]
    attach_allocated_roles_to_employees(cursor, employees)
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return {'employees': employees, 'page': page, 'per_page': per_page, 'total': total, 'pages': pages}


