@app.route('/approve-employee/<int:employee_id>', methods=['POST'])
@login_required
def approve_employee(employee_id):
    """Approve employee, assign role(s), and send email"""
    user_role = session.get('role', '').lower()
    
    if user_role not in EMPLOYEE_SUB_ROLES:
        return jsonify({'success': False, 'message': 'You do not have permission to approve employees.'}), 403
    
    data = request.get_json(silent=True) or {}
    roles = parse_allocated_roles_payload(data)
    
    if not roles:
        return jsonify({'success': False, 'message': 'Please select at least one role for the employee.'}), 400
    primary_role = roles[0]
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if employee exists
            cursor.execute("""
                SELECT id, employee_id, full_name, email, status
                FROM employees 
                WHERE id = %s
            """, (employee_id,))
            employee = cursor.fetchone()
            
            if not employee:
                return jsonify({'success': False, 'message': 'Employee not found.'}), 404
            
            # Check if employee is already approved
            if employee.get('status') == 'active':
                return jsonify({'success': False, 'message': f'Employee {employee.get("full_name")} is already active.'}), 400
            
            # Update employee status to active and sync allocated roles
            cursor.execute("""
                UPDATE employees 
                SET status = 'active', updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (employee_id,))
            sync_employee_allocated_roles(cursor, employee_id, roles, primary_role=primary_role)

            if 'teachers' in roles:
                raw_staff = data.get('staff_employee_number')
                staff_num = str(raw_staff).strip() if raw_staff is not None else ''
                if not staff_num:
                    staff_num = str(employee_id)
                elif len(staff_num) > 50:
                    connection.rollback()
                    return jsonify({'success': False, 'message': 'Staff number is too long (max 50 characters).'}), 400
                if _staff_number_is_taken(cursor, staff_num, employee_id):
                    connection.rollback()
                    return jsonify({
                        'success': False,
                        'message': 'This staff number is already assigned to another employee. Choose a different staff number.',
                    }), 400
                try:
                    cursor.execute(
                        """
                        INSERT INTO employee_number (employee_id, staff_number)
                        VALUES (%s, %s)
                        """,
                        (employee_id, staff_num),
                    )
                except IntegrityError:
                    connection.rollback()
                    return jsonify({'success': False, 'message': 'This staff number is already in use.'}), 400
            
            connection.commit()
            
            # Send approval email with role information
            roles_label = ', '.join(r.title() for r in roles)
            email_sent = send_employee_approval_email(
                employee.get('email'),
                employee.get('full_name'),
                employee.get('employee_id'),
                roles_label,
            )
            
            if not email_sent:
                print(f"Warning: Failed to send approval email to {employee.get('email')}")
            
            return jsonify({
                'success': True, 
                'message': (
                    f'Employee {employee.get("full_name")} has been approved with role(s): {roles_label}. '
                    'Email notification sent.'
                ),
            })
            
    except Exception as e:
        print(f"Error approving employee: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'An error occurred while approving the employee.'}), 500
    finally:
        connection.close()

@app.route('/update-employee/<int:employee_id>', methods=['POST'])
@login_required
def update_employee(employee_id):
    """Update employee details"""
    user_role = session.get('role', '').lower()
    current_employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access
    has_access = check_permission_or_role('edit_staff', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician', 'cateress'])
    
    if not has_access:
        return jsonify({'success': False, 'message': 'You do not have permission to update employees.'}), 403
    
    data = request.get_json(silent=True) or {}
    full_name = str(data.get('full_name', '')).strip().upper()
    email = str(data.get('email', '')).strip().lower()
    phone = str(data.get('phone', '')).strip()
    id_number = str(data.get('id_number', '')).strip().upper()
    roles = parse_allocated_roles_payload(data)
    new_password = str(data.get('new_password', ''))
    staff_employee_number_raw = data.get('staff_employee_number')
    staff_num = None
    if staff_employee_number_raw is not None:
        staff_num = str(staff_employee_number_raw).strip()
        if not staff_num:
            return jsonify({'success': False, 'message': 'Staff number cannot be empty.'}), 400
    
    if not all([full_name, email, phone]) or not roles:
        return jsonify({'success': False, 'message': 'Please fill in all required fields and assign at least one role.'}), 400
    if new_password and len(new_password.strip()) < 6:
        return jsonify({'success': False, 'message': 'New password must be at least 6 characters long.'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if employee exists
            cursor.execute("SELECT id FROM employees WHERE id = %s", (employee_id,))
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Employee not found.'}), 404
            
            # Check if email is already taken by another employee
            cursor.execute("SELECT id FROM employees WHERE email = %s AND id != %s", (email, employee_id))
            if cursor.fetchone():
                return jsonify({'success': False, 'message': 'Email is already in use by another employee.'}), 400

            primary_role = roles[0]
            
            if new_password.strip():
                password_hash = generate_password_hash(new_password.strip())
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, id_number = %s, password_hash = %s, updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                """, (full_name, email, phone, id_number, password_hash, employee_id))

                # Verify hash is stored and can be used for login before commit.
                cursor.execute("SELECT password_hash FROM employees WHERE id = %s", (employee_id,))
                row = cursor.fetchone()
                stored_hash = row.get('password_hash') if isinstance(row, dict) else (row[0] if row else None)
                try:
                    if not stored_hash or not check_password_hash(stored_hash, new_password.strip()):
                        connection.rollback()
                        return jsonify({'success': False, 'message': 'Password update verification failed. Please try again.'}), 500
                except Exception:
                    connection.rollback()
                    return jsonify({'success': False, 'message': 'Password format error. Please set the password again.'}), 500
            else:
                cursor.execute("""
                    UPDATE employees 
                    SET full_name = %s, email = %s, phone = %s, id_number = %s, updated_at = CURRENT_TIMESTAMP
                    WHERE id = %s
                """, (full_name, email, phone, id_number, employee_id))

            sync_employee_allocated_roles(cursor, employee_id, roles, primary_role=primary_role)

            if staff_num is not None:
                cursor.execute(
                    """
                    INSERT INTO employee_number (employee_id, staff_number)
                    VALUES (%s, %s)
                    ON DUPLICATE KEY UPDATE staff_number = VALUES(staff_number), updated_at = CURRENT_TIMESTAMP
                    """,
                    (employee_id, staff_num),
                )
            
            connection.commit()
            if new_password.strip():
                return jsonify({'success': True, 'message': 'Employee updated successfully. Password changed.'})
            return jsonify({'success': True, 'message': 'Employee updated successfully.'})
            
    except IntegrityError as ie:
        print(f"Error updating employee (integrity): {ie}")
        connection.rollback()
        err_msg = str(ie).lower()
        if 'staff_number' in err_msg or 'duplicate' in err_msg:
            return jsonify({'success': False, 'message': 'This staff number is already assigned to another employee.'}), 400
        return jsonify({'success': False, 'message': 'Could not save staff number. Please try a different value.'}), 400
    except Exception as e:
        print(f"Error updating employee: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'An error occurred while updating the employee.'}), 500
    finally:
        connection.close()

@app.route('/delete-employee/<int:employee_id>', methods=['POST'])
@login_required
def delete_employee(employee_id):
    """Permanently remove an employee and related portal access from the system."""
    actor_pk = resolve_session_employee_pk()

    if actor_pk is not None and employee_id == actor_pk:
        return jsonify({'success': False, 'message': 'You cannot delete your own account.'}), 400

    if not may_delete_staff_members():
        return jsonify({'success': False, 'message': 'You do not have permission to delete employees.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT id, full_name, profile_picture, role FROM employees WHERE id = %s",
                (employee_id,),
            )
            employee = cursor.fetchone()
            
            if not employee:
                return jsonify({'success': False, 'message': 'Employee not found.'}), 404

            emp_name = employee.get('full_name') if isinstance(employee, dict) else employee[1]
            emp_role = (employee.get('role') if isinstance(employee, dict) else employee[3] or '').strip().lower()
            profile_path = employee.get('profile_picture') if isinstance(employee, dict) else employee[2]

            if emp_role in ('head of institution', 'super admin'):
                ensure_employee_roles_schema(cursor)
                cursor.execute(
                    """
                    SELECT COUNT(*) AS cnt FROM employees e
                    WHERE e.id != %s AND e.status = 'active'
                      AND (
                        e.role = %s
                        OR EXISTS (
                            SELECT 1 FROM employee_roles er
                            WHERE er.employee_id = e.id AND er.role = %s
                        )
                      )
                    """,
                    (employee_id, emp_role, emp_role),
                )
                cnt_row = cursor.fetchone()
                remaining = (
                    cnt_row.get('cnt', 0) if isinstance(cnt_row, dict) else (cnt_row[0] if cnt_row else 0)
                )
                if int(remaining or 0) < 1:
                    return jsonify({
                        'success': False,
                        'message': (
                            f'Cannot delete the only active {emp_role}. '
                            'Assign the role to another staff member first.'
                        ),
                    }), 400

            _purge_employee_dependencies(cursor, employee_id)
            cursor.execute("DELETE FROM employees WHERE id = %s", (employee_id,))
            
            connection.commit()

            if profile_path:
                try:
                    rel = str(profile_path).replace('\\', '/').lstrip('/')
                    if rel.startswith('static/'):
                        rel = rel[7:]
                    full_path = os.path.join(app.root_path, 'static', rel)
                    if os.path.isfile(full_path):
                        os.remove(full_path)
                except OSError as file_err:
                    print(f"Note: could not remove profile file for employee {employee_id}: {file_err}")

            return jsonify({
                'success': True,
                'message': f'{emp_name} has been removed from the system.',
            })
            
    except IntegrityError as ie:
        print(f"Error deleting employee (integrity): {ie}")
        connection.rollback()
        return jsonify({
            'success': False,
            'message': 'Cannot delete this staff member because they are still linked to other school records. Remove or reassign those links first.',
        }), 400
    except Exception as e:
        print(f"Error deleting employee: {e}")
        connection.rollback()
        err = str(e).lower()
        if 'foreign key' in err or '1451' in err:
            return jsonify({
                'success': False,
                'message': 'Cannot delete this staff member because they are still linked to other school records.',
            }), 400
        return jsonify({'success': False, 'message': 'An error occurred while deleting the employee.'}), 500
    finally:
        connection.close()

@app.route('/toggle-suspend-employee/<int:employee_id>', methods=['POST'])
@login_required
def toggle_suspend_employee(employee_id):
    """Toggle suspend/unsuspend employee"""
    user_role = session.get('role', '').lower()
    
    if user_role not in EMPLOYEE_SUB_ROLES:
        return jsonify({'success': False, 'message': 'You do not have permission to suspend/unsuspend employees.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if employee exists and get current status
            cursor.execute("SELECT id, full_name, status FROM employees WHERE id = %s", (employee_id,))
            employee = cursor.fetchone()
            
            if not employee:
                return jsonify({'success': False, 'message': 'Employee not found.'}), 404
            
            current_status = employee.get('status')
            new_status = 'suspended' if current_status != 'suspended' else 'active'
            
            # Update employee status
            cursor.execute("""
                UPDATE employees 
                SET status = %s, updated_at = CURRENT_TIMESTAMP
                WHERE id = %s
            """, (new_status, employee_id))
            
            connection.commit()
            action = 'suspended' if new_status == 'suspended' else 'unsuspended'
            return jsonify({
                'success': True, 
                'message': f'Employee {employee.get("full_name")} has been {action} successfully.',
                'new_status': new_status
            })
            
    except Exception as e:
        print(f"Error toggling suspend employee: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'An error occurred while updating the employee status.'}), 500
    finally:
        connection.close()

