@app.route('/delete-student/<student_id>', methods=['POST'])
@login_required
def delete_student(student_id):
    """Delete a student"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access
    has_access = check_permission_or_role('delete_students', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician', 'cateress'])
    
    if not has_access:
        return jsonify({'success': False, 'message': 'You do not have permission to delete students.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if student exists
            cursor.execute("SELECT id FROM students WHERE student_id = %s", (student_id,))
            student = cursor.fetchone()
            
            if not student:
                return jsonify({'success': False, 'message': 'Student not found.'}), 404
            
            # Delete student (cascade will delete parent records)
            cursor.execute("DELETE FROM students WHERE student_id = %s", (student_id,))
            connection.commit()
            
            return jsonify({'success': True, 'message': 'Student deleted successfully.'})
    except Exception as e:
        print(f"Error deleting student: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Error deleting student.'}), 500
    finally:
        connection.close()

@app.route('/approve-student/<student_id>', methods=['POST'])
@login_required
def approve_student(student_id):
    """Approve student admission and send congratulations email to parent"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access (approve requires edit permission)
    has_access = check_permission_or_role('edit_students', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician', 'cateress'])
    
    if not has_access:
        flash('You do not have permission to approve students.', 'error')
        return redirect(url_for('student_management'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error. Please try again later.', 'error')
        return redirect(url_for('student_management'))
    
    try:
        with connection.cursor() as cursor:
            # Check if student exists and get student details
            cursor.execute("""
                SELECT s.id, s.student_id, s.full_name, s.status,
                       p.full_name as parent_name, p.email as parent_email, p.phone as parent_phone
                FROM students s
                LEFT JOIN parents p ON s.student_id = p.student_id
                WHERE s.student_id = %s
            """, (student_id,))
            student = cursor.fetchone()
            
            if not student:
                flash('Student not found.', 'error')
                return redirect(url_for('student_management'))
            
            # Check if student is already approved
            if student.get('status') != 'pending approval':
                flash(f'Student {student.get("full_name")} is already {student.get("status")}.', 'info')
                return redirect(url_for('student_management'))
            
            # Update student status to 'in session'
            cursor.execute("""
                UPDATE students 
                SET status = 'in session', updated_at = CURRENT_TIMESTAMP
                WHERE student_id = %s
            """, (student_id,))
            
            connection.commit()
            
            student_name = student.get('full_name') or student_id
            notify = notify_parent_student_approved(
                student.get('parent_email'),
                student.get('parent_phone'),
                student.get('parent_name'),
                student_name,
                student_id,
            )
            parts = [f'{student_name} approved.']
            if notify.get('email_sent'):
                parts.append('Parent notified by email with portal setup instructions and login link.')
            elif not (student.get('parent_email') or '').strip():
                parts.append('No parent email on file — add one in student details to send portal instructions.')
            if notify.get('sms_sent'):
                parts.append('SMS sent to parent phone.')
            err_bits = [e for e in (notify.get('errors') or []) if e]
            if err_bits and not notify.get('email_sent'):
                flash(' '.join(parts) + ' ' + ' '.join(err_bits), 'warning')
            elif err_bits:
                flash(' '.join(parts) + ' Note: ' + ' '.join(err_bits), 'warning' if not notify.get('email_sent') else 'success')
            else:
                flash(' '.join(parts), 'success')
            
    except Exception as e:
        print(f"Error approving student: {e}")
        connection.rollback()
        flash('An error occurred while approving the student. Please try again.', 'error')
    finally:
        if connection:
            try:
                connection.close()
            except:
                pass  # Connection might already be closed
    
    return redirect(url_for('student_management'))


def _get_students_by_level():
    """Helper: fetch students grouped by academic level. Returns list of {level_name, level_category, students}."""
    students_by_level = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_name, level_category FROM academic_levels
                    WHERE level_status = 'active' ORDER BY level_name ASC
                """)
                levels = [{'level_name': r.get('level_name') if isinstance(r, dict) else r[1],
                          'level_category': r.get('level_category') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')}
                         for r in (cursor.fetchall() or [])]
                cursor.execute("""
                    SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender, p.full_name as parent_name
                    FROM students s LEFT JOIN parents p ON s.student_id = p.student_id
                    ORDER BY s.full_name ASC
                """)
                level_to_students = {}
                for row in cursor.fetchall() or []:
                    st = {'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                          'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                          'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                          'status': row.get('status') if isinstance(row, dict) else row[3],
                          'gender': row.get('gender') if isinstance(row, dict) else (row[4] if len(row) > 4 else ''),
                          'parent_name': row.get('parent_name') if isinstance(row, dict) else (row[5] if len(row) > 5 else '')}
                    grade = st['current_grade'] or 'Ungraded'
                    level_to_students.setdefault(grade, []).append(st)
                seen = set()
                for lv in levels:
                    ln = lv['level_name']
                    if ln in level_to_students:
                        students_by_level.append({'level_name': ln, 'level_category': lv.get('level_category', ''), 'students': level_to_students[ln]})
                        seen.add(ln)
                for grade, sts in sorted(level_to_students.items()):
                    if grade not in seen:
                        students_by_level.append({'level_name': grade, 'level_category': '', 'students': sts})
        except Exception as e:
            print(f"Error in _get_students_by_level: {e}")
        finally:
            if connection:
                try: connection.close()
                except: pass
    return students_by_level


def _students_progress_level_summaries(cursor):
    """Class names with student counts (no full student list)."""
    level_meta = {}
    try:
        cursor.execute(
            """
            SELECT id, level_name, level_category
            FROM academic_levels
            WHERE level_status = 'active'
            ORDER BY level_name ASC
            """
        )
        for row in cursor.fetchall() or []:
            ln = (row.get('level_name') if isinstance(row, dict) else row[1]) or ''
            ln = str(ln).strip()
            if not ln:
                continue
            level_meta[ln] = {
                'level_name': ln,
                'level_category': (row.get('level_category') if isinstance(row, dict) else row[2]) or '',
                'total': 0,
            }
        cursor.execute(
            """
            SELECT TRIM(COALESCE(s.current_grade, '')) AS level_name, COUNT(*) AS c
            FROM students s
            GROUP BY TRIM(COALESCE(s.current_grade, ''))
            """
        )
        out = []
        seen = set()
        for row in cursor.fetchall() or []:
            ln = (row.get('level_name') if isinstance(row, dict) else row[0]) or ''
            ln = str(ln).strip() or 'Ungraded'
            cnt = int((row.get('c') if isinstance(row, dict) else row[1]) or 0)
            cat = (level_meta.get(ln) or {}).get('level_category', '')
            out.append({'level_name': ln, 'level_category': cat, 'total': cnt})
            seen.add(ln)
        for ln, meta in sorted(level_meta.items(), key=lambda x: x[0]):
            if ln not in seen:
                out.append({'level_name': ln, 'level_category': meta['level_category'], 'total': 0})
        out.sort(key=lambda x: (x.get('level_category') or '', x.get('level_name') or ''))
        return out
    except Exception as e:
        print(f'_students_progress_level_summaries: {e}')
        return []


def _fetch_students_progress_page(cursor, level_name, page=1, per_page=50, q=''):
    """Paginated students for one class/grade on Students Progress."""
    rows = []
    total = 0
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    pages = 1
    level_key = (level_name or '').strip()
    if level_key == 'Ungraded':
        grade_clause = "(TRIM(COALESCE(s.current_grade, '')) = '' OR s.current_grade IS NULL)"
        params_base = []
    else:
        grade_clause = "TRIM(COALESCE(s.current_grade, '')) = %s"
        params_base = [level_key]
    search_sql = ''
    search_params = []
    q = (q or '').strip()
    if q:
        like = f'%{q}%'
        search_sql = (
            ' AND (s.full_name LIKE %s OR s.student_id LIKE %s OR COALESCE(p.full_name, "") LIKE %s) '
        )
        search_params = [like, like, like]
    try:
        count_sql = f"""
            SELECT COUNT(*) AS c
            FROM students s
            LEFT JOIN parents p ON s.student_id = p.student_id
            WHERE {grade_clause}
            {search_sql}
        """
        cursor.execute(count_sql, tuple(params_base) + tuple(search_params))
        count_row = cursor.fetchone()
        total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
        pages = max(1, (total + per_page - 1) // per_page) if total else 1
        if page > pages:
            page = pages
        offset = (page - 1) * per_page
        list_sql = f"""
            SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender,
                   p.full_name AS parent_name
            FROM students s
            LEFT JOIN parents p ON s.student_id = p.student_id
            WHERE {grade_clause}
            {search_sql}
            ORDER BY s.full_name ASC
            LIMIT %s OFFSET %s
        """
        cursor.execute(list_sql, tuple(params_base) + tuple(search_params) + (per_page, offset))
        for row in cursor.fetchall() or []:
            rows.append({
                'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                'status': row.get('status') if isinstance(row, dict) else row[3],
                'gender': row.get('gender') if isinstance(row, dict) else row[4],
                'parent_name': row.get('parent_name') if isinstance(row, dict) else row[5],
            })
    except Exception as e:
        print(f'_fetch_students_progress_page: {e}')
        rows = []
        total = 0
        pages = 1
    return {
        'students': rows,
        'page': page,
        'per_page': per_page,
        'total': total,
        'pages': pages,
        'level_name': level_key or 'Ungraded',
    }


def _attendance_register_teacher_scope():
    """Whether attendance register should be scoped to one teacher's allocated classes."""
    user_role = (session.get('role') or '').lower().strip()
    viewing_as = (session.get('viewing_as_employee_role') or '').lower().strip()
    is_teacher_role = user_role in ('teachers', 'teacher') or viewing_as in ('teachers', 'teacher')
    if not is_teacher_role:
        return False, None
    teacher_id = _subject_progress_teacher_id() or _teacher_portal_employee_pk()
    if not teacher_id:
        return True, None
    return True, teacher_id


def _get_attendance_class_level_options(is_teacher, teacher_id=None):
    """Class names for attendance filter without loading every student."""
    options = []
    connection = get_db_connection()
    if not connection:
        return options
    try:
        with connection.cursor() as cursor:
            if is_teacher and teacher_id:
                for level in _fetch_teacher_subject_progress_levels(cursor, teacher_id):
                    ln = str((level or {}).get('level_name') or '').strip()
                    if ln and ln not in options:
                        options.append(ln)
                options.sort()
            else:
                cursor.execute("""
                    SELECT DISTINCT s.current_grade
                    FROM students s
                    WHERE s.status = 'in session' AND COALESCE(s.current_grade, '') != ''
                    ORDER BY s.current_grade ASC
                """)
                for r in cursor.fetchall() or []:
                    g = r.get('current_grade') if isinstance(r, dict) else r[0]
                    if g and str(g).strip():
                        options.append(str(g).strip())
    except Exception as e:
        print(f"_get_attendance_class_level_options: {e}")
    finally:
        try:
            connection.close()
        except Exception:
            pass
    return options


def _fetch_attendance_students_page(cursor, grade, page=1, per_page=50, q=''):
    """Paginated in-session students for one class (attendance register)."""
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    grade = (grade or '').strip()
    q = (q or '').strip()
    if not grade:
        return [], {'page': 1, 'per_page': per_page, 'total': 0, 'pages': 1}
    where = ["s.status = 'in session'", 's.current_grade = %s']
    params = [grade]
    if q:
        like = '%' + q + '%'
        where.append('(s.full_name LIKE %s OR s.student_id LIKE %s)')
        params.extend([like, like])
    where_sql = ' WHERE ' + ' AND '.join(where)
    cursor.execute(f'SELECT COUNT(*) AS c FROM students s{where_sql}', tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
    cursor.execute(
        f"""
        SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender, p.full_name AS parent_name
        FROM students s
        LEFT JOIN parents p ON s.student_id = p.student_id
        {where_sql}
        ORDER BY s.full_name ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    students = []
    for row in cursor.fetchall() or []:
        students.append({
            'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
            'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
            'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
            'status': row.get('status') if isinstance(row, dict) else row[3],
            'gender': row.get('gender') if isinstance(row, dict) else (row[4] if len(row) > 4 else ''),
            'parent_name': row.get('parent_name') if isinstance(row, dict) else (row[5] if len(row) > 5 else ''),
        })
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return students, {'page': page, 'per_page': per_page, 'total': total, 'pages': pages}


def _students_by_level_for_attendance(cursor, class_level, page=1, per_page=50, q='', level_id_by_name=None):
    """Single level group with paginated students for the register."""
    class_level = (class_level or '').strip()
    if not class_level:
        return []
    students, _meta = _fetch_attendance_students_page(cursor, class_level, page, per_page, q)
    lid = (level_id_by_name or {}).get(class_level)
    return [{
        'level_name': class_level,
        'level_category': '',
        'students': students,
        'id': int(lid) if lid is not None else None,
    }]


def _attendance_visible_student_ids(students_by_level):
    ids = []
    for lg in students_by_level or []:
        for st in (lg.get('students') or []):
            sid = st.get('student_id')
            if sid is not None and str(sid).strip():
                ids.append(str(sid).strip())
    return list(dict.fromkeys(ids))


def _build_weeks_and_days(term_start, term_end, selected_week_index=1):
    """Build list of weeks, each with its days (based on term dates). Returns (weeks_list, selected_week_days)."""
    from datetime import timedelta
    weeks_options = []  # [{week_num, label, start, end, days: [{date, day_name, label}]}]
    if not term_start or not term_end:
        return weeks_options, []
    try:
        current = term_start
        week_num = 1
        selected_week_days = []
        while current <= term_end:
            week_start = current
            week_end = min(current + timedelta(days=6), term_end)
            days_in_week = []
            d = week_start
            while d <= week_end:
                day_name = d.strftime('%a')  # Mon, Tue, etc.
                day_label = f"{day_name} {d.day}"
                days_in_week.append({'date': d, 'day_name': day_name, 'label': day_label, 'date_str': d.strftime('%Y-%m-%d')})
                d += timedelta(days=1)
            weeks_options.append({
                'week_num': week_num,
                'label': f"Week {week_num} ({week_start.strftime('%d %b')} - {week_end.strftime('%d %b %Y')})",
                'start': week_start,
                'end': week_end,
                'days': days_in_week,
            })
            if week_num == selected_week_index:
                selected_week_days = days_in_week
            week_num += 1
            current = week_end + timedelta(days=1)
        if not selected_week_days and weeks_options:
            selected_week_days = weeks_options[0]['days']
        return weeks_options, selected_week_days
    except (TypeError, AttributeError, ValueError):
        return [], []


def _get_teacher_level_ids(teacher_user_id):
    """Distinct academic level names this teacher teaches (subject allocations + timetable)."""
    level_names = set()
    if not teacher_user_id:
        return level_names
    conn = get_db_connection()
    if conn:
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    SELECT DISTINCT al.level_name
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON tsa.academic_level_id = al.id
                    WHERE tsa.teacher_id = %s
                    UNION
                    SELECT DISTINCT al.level_name
                    FROM timetables tt
                    INNER JOIN academic_levels al ON tt.academic_level_id = al.id
                    WHERE tt.teacher_id = %s
                """, (teacher_user_id, teacher_user_id))
                for r in cur.fetchall() or []:
                    ln = r.get('level_name') if isinstance(r, dict) else r[0]
                    if ln:
                        level_names.add(str(ln).strip())
        except Exception as e:
            _schema_ignore_existing(e, '_get_teacher_level_ids union query')
            try:
                with conn.cursor() as cur:
                    cur.execute("""
                        SELECT DISTINCT al.level_name FROM teacher_subject_assignments tsa
                        INNER JOIN academic_levels al ON tsa.academic_level_id = al.id
                        WHERE tsa.teacher_id = %s
                    """, (teacher_user_id,))
                    for r in cur.fetchall() or []:
                        ln = r.get('level_name') if isinstance(r, dict) else r[0]
                        if ln:
                            level_names.add(str(ln).strip())
            except Exception as e2:
                print(f"Error in _get_teacher_level_ids fallback: {e2}")
        finally:
            try:
                conn.close()
            except Exception:
                pass
    return level_names


def _filter_students_by_level_for_ids(students_by_level_all, allowed_ids):
    """Restrict grouped students to those whose student_id is in allowed_ids."""
    allowed = {str(x).strip() for x in allowed_ids if x is not None and str(x).strip()}
    out = []
    for lg in students_by_level_all:
        sts = [s for s in (lg.get('students') or []) if str(s.get('student_id', '')).strip() in allowed]
        if sts:
            out.append({**lg, 'students': sts})
    return out


def _coerce_date_only(val):
    """Normalize DB/date-like values to a Python date."""
    if val is None:
        return None
    if isinstance(val, datetime):
        return val.date()
    if isinstance(val, date_cls):
        return val
    du = getattr(val, 'date', None)
    if callable(du):
        try:
            out = du()
            if isinstance(out, date_cls):
                return out
        except Exception:
            pass
    try:
        return datetime.strptime(str(val)[:10], '%Y-%m-%d').date()
    except Exception:
        return None


def _register_aggregate_analytics_empty():
    """Default shape for staff attendance register aggregate analytics (filtered grid)."""
    return {
        'has_data': False,
        'total_records': 0,
        'present_count': 0,
        'absent_count': 0,
        'overall_pct': 0.0,
        'by_level': [],
        'by_day': [],
    }


def _attendance_register_row_present(val):
    if val is None:
        return False
    if isinstance(val, bool):
        return val
    try:
        return int(val) != 0
    except (TypeError, ValueError):
        return str(val).lower() in ('true', '1', 'yes', 't')


def _compute_register_aggregate_analytics(cursor, term_id, selected_week_days, students_by_level):
    """Sum saved attendance rows for visible students and dates in the current register view."""
    out = _register_aggregate_analytics_empty()
    if not term_id or not selected_week_days:
        return out
    date_list = []
    date_label = {}
    for d in selected_week_days:
        ds = d.get('date_str')
        if not ds:
            continue
        date_list.append(ds)
        date_label[ds] = d.get('label') or ds
    if not date_list:
        return out
    visible = []
    sid_to_level = {}
    for lg in students_by_level or []:
        lname = str(lg.get('level_name') or '').strip() or 'Class'
        for st in (lg.get('students') or []):
            sid = st.get('student_id')
            if sid is None:
                continue
            s = str(sid).strip()
            if not s:
                continue
            visible.append(s)
            sid_to_level[s] = lname
    vis_unique = list(dict.fromkeys(visible))
    if not vis_unique:
        return out
    ph_d = ','.join(['%s'] * len(date_list))
    ph_s = ','.join(['%s'] * len(vis_unique))
    cursor.execute(
        f"""
        SELECT sar.student_id, sar.attendance_date, sar.present
        FROM student_attendance_records sar
        WHERE sar.term_id = %s
          AND sar.attendance_date IN ({ph_d})
          AND sar.student_id IN ({ph_s})
          AND {_attendance_class_day_sql('sar')}
        """,
        tuple([term_id] + date_list + vis_unique),
    )
    rows = cursor.fetchall() or []
    if not rows:
        return out
    by_level = defaultdict(lambda: {'present': 0, 'total': 0})
    by_day = defaultdict(lambda: {'present': 0, 'total': 0})
    present_total = 0
    for r in rows:
        sid = str((r.get('student_id') if isinstance(r, dict) else r[0]) or '').strip()
        dt = r.get('attendance_date') if isinstance(r, dict) else r[1]
        pr = r.get('present') if isinstance(r, dict) else r[2]
        ds = dt.strftime('%Y-%m-%d') if hasattr(dt, 'strftime') else str(dt)[:10]
        is_pr = _attendance_register_row_present(pr)
        lvl = sid_to_level.get(sid, 'Unknown')
        by_level[lvl]['total'] += 1
        if is_pr:
            by_level[lvl]['present'] += 1
            present_total += 1
        by_day[ds]['total'] += 1
        if is_pr:
            by_day[ds]['present'] += 1
    n = len(rows)
    out['has_data'] = True
    out['total_records'] = n
    out['present_count'] = present_total
    out['absent_count'] = n - present_total
    out['overall_pct'] = round(100.0 * present_total / n, 1) if n else 0.0
    level_rows = []
    for ln, agg in sorted(by_level.items(), key=lambda x: (x[0] or '').lower()):
        t = agg['total']
        p = agg['present']
        level_rows.append({
            'level_name': ln,
            'present': p,
            'absent': t - p,
            'total': t,
            'pct': round(100.0 * p / t, 1) if t else 0.0,
        })
    out['by_level'] = level_rows
    day_rows = []
    for ds in date_list:
        agg = by_day.get(ds, {'present': 0, 'total': 0})
        t = agg['total']
        p = agg['present']
        day_rows.append({
            'date_str': ds,
            'label': date_label.get(ds, ds),
            'present': p,
            'absent': t - p,
            'total': t,
            'pct': round(100.0 * p / t, 1) if t else None,
        })
    out['by_day'] = day_rows
    return out


_ATTENDANCE_FIELD_KEY_RE = re.compile(
    r'^(.+)_(\d{4}-\d{2}-\d{2})(?:_(\d+))?(?:_(morning|afternoon|evening))?$'
)


def _attendance_filter_args_from_form(form):
    """Build query-style args from attendance POST hidden fields for register refresh."""
    from werkzeug.datastructures import ImmutableMultiDict
    pairs = []
    for k in (
        'term_id', 'academic_year_id', 'filter_type', 'month', 'day',
        'period_start', 'period_end', 'class_level', 'page', 'per_page', 'q',
    ):
        v = form.get(k)
        if v is not None and str(v).strip() != '':
            pairs.append((k, str(v).strip()))
    return ImmutableMultiDict(pairs)


def _attendance_register_refresh_html(students_by_level, is_teacher, teacher_id, attendance_mode='admin'):
    """Render summary + register analytics fragments after a successful save."""
    ctx = _attendance_register_get_context(
        students_by_level, is_teacher, _attendance_filter_args_from_form(request.form),
        teacher_id=teacher_id, attendance_mode=attendance_mode,
    )
    tpl_ctx = {
        **ctx,
        'is_teacher_view': is_teacher and attendance_mode in ('subject', 'class'),
        'is_class_teacher_view': attendance_mode == 'class',
        'use_class_session_slots': attendance_mode == 'class',
        'is_parent_view': False,
    }
    return {
        'register_analytics_html': render_template(
            'dashboards/_attendance_register_analytics_partial.html', **tpl_ctx
        ),
    }


def _snap_date_to_study_day(d, allowed_weekdays, lo=None, hi=None):
    """Move a calendar date onto the nearest configured study day within term bounds."""
    if not d:
        return d
    weekdays = set(allowed_weekdays or [])
    if not weekdays:
        weekdays = {'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'}
    if d.strftime('%A') in weekdays:
        return d
    for delta in range(1, 8):
        candidate = d - timedelta(days=delta)
        if lo and candidate < lo:
            break
        if candidate.strftime('%A') in weekdays:
            return candidate
    for delta in range(1, 8):
        candidate = d + timedelta(days=delta)
        if hi and candidate > hi:
            break
        if candidate.strftime('%A') in weekdays:
            return candidate
    return d


def _parse_attendance_checkbox_key(key):
    """Parse att_{student_id}_{date}[_subject_id][_{morning|afternoon|evening}]."""
    if not key or not key.startswith('att_'):
        return None
    m = _ATTENDANCE_FIELD_KEY_RE.match(key[4:])
    if not m:
        return None
    sid = m.group(1)
    date_str = m.group(2)
    subj_raw = m.group(3)
    session_slot = (m.group(4) or '').strip().lower()
    try:
        subject_id = int(subj_raw) if subj_raw is not None else 0
    except (TypeError, ValueError):
        subject_id = 0
    return sid, date_str, subject_id, session_slot


def _build_teacher_level_attendance_columns(cursor, teacher_id, term_id, level_id, selected_week_days):
    """One column per subject scheduled on each visible day (teacher timetable)."""
    columns = []
    if not teacher_id or not term_id or not level_id or not selected_week_days:
        return columns
    try:
        for day in selected_week_days:
            dt = day.get('date')
            if not dt:
                try:
                    dt = datetime.strptime(day.get('date_str', ''), '%Y-%m-%d').date()
                except Exception:
                    continue
            weekday = dt.strftime('%A')
            time_by_subject = _fetch_timetable_session_times(
                cursor, teacher_id, term_id, int(level_id), weekday,
            )
            cursor.execute("""
                SELECT DISTINCT t.subject_id, s.subject_name, s.subject_code
                FROM timetables t
                INNER JOIN subjects s ON s.id = t.subject_id
                WHERE t.term_id = %s AND t.academic_level_id = %s AND t.teacher_id = %s
                  AND t.day_of_week = %s
                ORDER BY s.subject_name ASC
            """, (int(term_id), int(level_id), int(teacher_id), weekday))
            for row in cursor.fetchall() or []:
                sid = row.get('subject_id') if isinstance(row, dict) else row[0]
                if sid is None:
                    continue
                sname = (row.get('subject_name', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')) or ''
                scode = (row.get('subject_code', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else '')) or ''
                short = scode or sname
                sid_int = int(sid)
                session_time = time_by_subject.get(sid_int, '')
                columns.append({
                    'date_str': day.get('date_str', ''),
                    'label': day.get('label', ''),
                    'session_date_display': _attendance_session_date_display(dt),
                    'subject_id': sid_int,
                    'subject_name': sname,
                    'subject_code': scode,
                    'learning_area': _attendance_learning_area_label(sname, scode),
                    'session_time': session_time,
                    'header_label': f"{day.get('label', '')} · {short}",
                })
    except Exception as e:
        print(f"_build_teacher_level_attendance_columns: {e}")
    return columns


def _fetch_level_timetable_session_times(cursor, term_id, level_id, weekday_name):
    """Map subject_id -> comma-separated time_slot for one class level/day."""
    out = {}
    if not term_id or not level_id or not weekday_name:
        return out
    try:
        cursor.execute(
            """
            SELECT t.subject_id,
                   GROUP_CONCAT(DISTINCT t.time_slot ORDER BY t.time_slot SEPARATOR ', ') AS session_times
            FROM timetables t
            WHERE t.term_id = %s AND t.academic_level_id = %s
              AND t.day_of_week = %s AND t.subject_id IS NOT NULL
            GROUP BY t.subject_id
            """,
            (int(term_id), int(level_id), str(weekday_name)),
        )
        for row in cursor.fetchall() or []:
            sid = row.get('subject_id') if isinstance(row, dict) else row[0]
            times = row.get('session_times') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
            if sid:
                out[int(sid)] = (times or '').strip()
    except Exception as ex:
        print(f"_fetch_level_timetable_session_times: {ex}")
    return out


