@login_required
def parent_exam_progress():
    """List linked children; single child redirects to their exam progress detail."""
    ctx = _parent_dashboard_auth()
    if ctx is None:
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))

    parent_email = ctx['parent_email']
    user_id = session.get('user_id')
    children = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                for ch in _fetch_parent_linked_children(cursor, parent_email, user_id=user_id):
                    children.append({
                        'student_id': ch.get('student_id'),
                        'full_name': ch.get('full_name'),
                        'current_grade': ch.get('current_grade'),
                    })
                summaries = _parent_children_exam_summaries([c['student_id'] for c in children])
                for c in children:
                    sm = summaries.get(str(c['student_id']).strip(), {})
                    c['exam_count'] = sm.get('exam_count', 0)
                    c['overall_mean'] = sm.get('overall_mean')
        except Exception as e:
            print(f"Error listing parent exam progress children: {e}")
            flash('Error loading children.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    if len(children) == 1:
        return redirect(parent_dashboard_path(f"exam-progress/{children[0]['student_id']}"))

    return render_template(
        'dashboards/parent_exam_progress_list.html',
        children=children,
        is_technician=ctx['is_technician'],
        current_view_role=ctx['current_view_role'],
        all_students=ctx['all_students'],
        selected_student_id=ctx['selected_student_id'],
    )


