@app.route('/dashboard/employee/subject-class-allocation/update', methods=['POST'])
@login_required
def update_teacher_subject_allocation():
    """Update teacher for an existing teacher-subject allocation row."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        assignment_id = int(data.get('assignment_id', 0))
        teacher_id = int(data.get('teacher_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid allocation or teacher ID'}), 400

    if assignment_id <= 0 or teacher_id <= 0:
        return jsonify({'success': False, 'message': 'Invalid allocation or teacher ID'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id, academic_level_id, subject_id
                FROM teacher_subject_assignments
                WHERE id = %s
            """, (assignment_id,))
            existing = cursor.fetchone()
            if not existing:
                return jsonify({'success': False, 'message': 'Allocation not found'}), 404

            academic_level_id = existing.get('academic_level_id') if isinstance(existing, dict) else (existing[1] if len(existing) > 1 else None)
            subject_id = existing.get('subject_id') if isinstance(existing, dict) else (existing[2] if len(existing) > 2 else None)
            if academic_level_id is None or subject_id is None:
                return jsonify({'success': False, 'message': 'Invalid allocation record'}), 400

            cursor.execute("""
                SELECT id FROM employees
                WHERE id = %s AND status = 'active' AND role = 'teachers'
            """, (teacher_id,))
            if not cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'Only active employees with role teachers can be assigned.'
                }), 400

            cursor.execute("""
                SELECT id FROM teacher_subject_assignments
                WHERE academic_level_id = %s AND subject_id = %s AND teacher_id = %s AND id != %s
                LIMIT 1
            """, (academic_level_id, subject_id, teacher_id, assignment_id))
            if cursor.fetchone():
                return jsonify({'success': False, 'message': 'This teacher is already allocated to this subject in this level.'}), 400

            cursor.execute("""
                UPDATE teacher_subject_assignments
                SET teacher_id = %s
                WHERE id = %s
            """, (teacher_id, assignment_id))
            connection.commit()
            return jsonify({'success': True, 'message': 'Allocation updated successfully'})
    except Exception as e:
        print(f"Error updating allocation: {e}")
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error updating allocation: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Create Subject Route
@app.route('/dashboard/employee/subject-class-allocation/create-subject', methods=['POST'])
@login_required
def create_subject():
    """Create a new subject"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data, is_multipart = _subject_registration_payload()
    subject_name = data.get('subject_name', '').strip().upper()
    subject_code = data.get('subject_code', '').strip().upper() if data.get('subject_code') else ''
    description = data.get('description', '').strip().upper() if data.get('description') else ''
    academic_level_ids = data.get('academic_level_ids') or []
    
    if not subject_name:
        return jsonify({'success': False, 'message': 'Subject name is required'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            ensure_subject_main_photo_column(cursor)
            ensure_subject_scheme_tables(cursor)
            # Check if subject code already exists (if provided)
            if subject_code:
                cursor.execute("SELECT id FROM subjects WHERE subject_code = %s", (subject_code,))
                if cursor.fetchone():
                    return jsonify({'success': False, 'message': 'Subject code already exists'}), 400
            
            # Insert new subject
            cursor.execute("""
                INSERT INTO subjects (subject_name, subject_code, description, status)
                VALUES (%s, %s, %s, 'active')
            """, (subject_name, subject_code if subject_code else None, description if description else None))
            
            connection.commit()
            subject_id = cursor.lastrowid

            main_photo_path = None
            if is_multipart:
                main_photo_path, photo_err = _resolve_subject_main_photo_path(
                    request, None, subject_id,
                )
                if photo_err:
                    return jsonify({'success': False, 'message': photo_err}), 400
                if main_photo_path:
                    cursor.execute(
                        "UPDATE subjects SET main_photo = %s WHERE id = %s",
                        (main_photo_path, subject_id),
                    )
                    connection.commit()

            # Save selected teaching levels for the subject
            cleaned_level_ids = []
            for lid in academic_level_ids:
                try:
                    lid_int = int(lid)
                    if lid_int > 0:
                        cleaned_level_ids.append(lid_int)
                except (ValueError, TypeError):
                    continue
            if cleaned_level_ids:
                for lid in sorted(set(cleaned_level_ids)):
                    cursor.execute("""
                        INSERT IGNORE INTO subject_academic_levels (subject_id, academic_level_id)
                        VALUES (%s, %s)
                    """, (subject_id, lid))
                connection.commit()
            
            scheme_data = []
            if _scheme_of_work_provided():
                scheme_data = _parse_scheme_of_work_payload()
                _save_subject_scheme_of_work(cursor, subject_id, scheme_data)
                connection.commit()
            
            return jsonify({
                'success': True, 
                'message': 'Subject created successfully',
                'subject': {
                    'id': subject_id,
                    'subject_name': subject_name,
                    'subject_code': subject_code,
                    'description': description,
                    'main_photo': main_photo_path,
                    'main_photo_url': _subject_course_image_public_url(main_photo_path),
                    'scheme_of_work': scheme_data,
                    'academic_level_ids': sorted(set(cleaned_level_ids)) if academic_level_ids else []
                }
            })
            
    except Exception as e:
        print(f"Error creating subject: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Error creating subject: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

@app.route('/dashboard/employee/academic-subject-registration')
@login_required
def academic_subject_registration():
    """Academic Subject Registration page - allows users to register, edit, and delete subjects"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Fetch all subjects
    connection = get_db_connection()
    subjects = []
    active_academic_levels = []
    
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_subject_main_photo_column(cursor)
                ensure_subject_scheme_tables(cursor)
                cursor.execute("""
                    SELECT id, subject_name, subject_code, description, main_photo, status, created_at, updated_at
                    FROM subjects
                    ORDER BY subject_name ASC
                """)
                subjects_results = cursor.fetchall()
                
                for row in subjects_results:
                    main_photo = row.get('main_photo') if isinstance(row, dict) else (row[4] if len(row) > 4 else None)
                    subjects.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'subject_name': row.get('subject_name', '') if isinstance(row, dict) else row[1],
                        'subject_code': row.get('subject_code', '') if isinstance(row, dict) else row[2],
                        'description': row.get('description', '') if isinstance(row, dict) else row[3],
                        'main_photo': main_photo,
                        'main_photo_url': _subject_course_image_public_url(main_photo),
                        'status': row.get('status', 'active') if isinstance(row, dict) else (row[5] if len(row) > 5 else 'active'),
                        'created_at': row.get('created_at') if isinstance(row, dict) else (row[6] if len(row) > 6 else None),
                        'updated_at': row.get('updated_at') if isinstance(row, dict) else (row[7] if len(row) > 7 else None)
                    })

                # Active academic levels for registration form
                cursor.execute("""
                    SELECT id, level_name, level_category
                    FROM academic_levels
                    WHERE COALESCE(level_status, 'active') = 'active'
                    ORDER BY level_category ASC, level_name ASC
                """)
                for lvl in cursor.fetchall() or []:
                    active_academic_levels.append({
                        'id': lvl.get('id') if isinstance(lvl, dict) else lvl[0],
                        'level_name': lvl.get('level_name', '') if isinstance(lvl, dict) else lvl[1],
                        'level_category': lvl.get('level_category', '') if isinstance(lvl, dict) else (lvl[2] if len(lvl) > 2 else '')
                    })

                # Map each subject to registered academic levels
                cursor.execute("""
                    SELECT sal.subject_id, al.id AS level_id, al.level_name, al.level_category
                    FROM subject_academic_levels sal
                    INNER JOIN academic_levels al ON sal.academic_level_id = al.id
                    ORDER BY sal.subject_id, al.level_category, al.level_name
                """)
                subject_levels_map = {}
                for m in cursor.fetchall() or []:
                    sid = m.get('subject_id') if isinstance(m, dict) else m[0]
                    if sid not in subject_levels_map:
                        subject_levels_map[sid] = []
                    subject_levels_map[sid].append({
                        'id': m.get('level_id') if isinstance(m, dict) else m[1],
                        'level_name': m.get('level_name', '') if isinstance(m, dict) else m[2],
                        'level_category': m.get('level_category', '') if isinstance(m, dict) else (m[3] if len(m) > 3 else '')
                    })

                for s in subjects:
                    s['academic_levels'] = subject_levels_map.get(s['id'], [])
                    s['academic_level_ids'] = [x['id'] for x in s['academic_levels']]

                scheme_map = _fetch_scheme_of_work_for_subjects(cursor, [s['id'] for s in subjects])
                for s in subjects:
                    s['scheme_of_work'] = scheme_map.get(s['id'], [])
                    s['scheme_topic_count'] = len(s['scheme_of_work'])
                    s['scheme_subtopic_count'] = sum(len(t.get('subtopics') or []) for t in s['scheme_of_work'])
        except Exception as e:
            print(f"Error fetching subjects: {e}")
        finally:
            connection.close()
    
    return render_template('dashboards/academic_subject_registration.html', 
                         role=user_role,
                         subjects=subjects,
                         active_academic_levels=active_academic_levels)

