@app.route('/dashboard/employee/classes-subjects/level/<int:level_id>')
@login_required
def classes_subjects_level_detail(level_id):
    """Academic level detail: all subjects allocated to the class."""
    if not _academic_classes_portal_allowed():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    user_role = session.get('role', '').lower()
    connection = get_db_connection()
    level = None
    level_subjects = []
    total_allocated_teachers = 0
    class_teacher = None
    current_term_name = None
    enrolled_count = 0

    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description
                    FROM academic_levels
                    WHERE id = %s AND COALESCE(level_status, 'active') = 'active'
                    LIMIT 1
                """, (level_id,))
                row = cursor.fetchone()
                if not row:
                    flash('Academic level not found or inactive.', 'error')
                    return redirect(employee_dash_url('classes-subjects'))

                level = {
                    'id': row.get('id') if isinstance(row, dict) else row[0],
                    'level_category': row.get('level_category', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else ''),
                    'level_name': row.get('level_name', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else ''),
                    'level_description': row.get('level_description', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                }

                level_subjects, total_allocated_teachers = _fetch_level_subject_allocations_with_teachers(
                    cursor, level_id,
                )

                _current_year_id, _yn, current_term_id, current_term_name = _get_current_academic_year_and_term(cursor)
                class_teacher = _fetch_class_teacher_for_level(cursor, level_id)
                cursor.execute(
                    """
                    SELECT COUNT(*) AS c FROM students
                    WHERE TRIM(COALESCE(current_grade, '')) = %s
                      AND LOWER(TRIM(COALESCE(status, ''))) = 'in session'
                    """,
                    (level['level_name'],),
                )
                er = cursor.fetchone()
                enrolled_count = int((er.get('c') if isinstance(er, dict) else er[0]) or 0) if er else 0
                for item in level_subjects:
                    sid = item.get('subject_id')
                    if sid and current_term_id:
                        item['coverage'] = _compute_subject_session_coverage(
                            cursor, level_id, sid, current_term_id,
                        )
                    else:
                        item['coverage'] = _subject_session_coverage_empty()
        except Exception as e:
            print(f"Error loading classes-subjects level detail: {e}")
            import traceback
            traceback.print_exc()
            flash('Could not load level allocations right now.', 'error')
            return redirect(employee_dash_url('classes-subjects'))
        finally:
            connection.close()

    return render_template(
        'dashboards/classes_subjects_level_detail.html',
        role=user_role,
        level=level,
        level_subjects=level_subjects,
        total_allocated_teachers=total_allocated_teachers,
        class_teacher=class_teacher,
        current_term_name=current_term_name,
        enrolled_count=enrolled_count,
    )


