def _stock_in_row_to_dict(row):
    """Map stock-in movement JOIN row to a UI dict."""
    if isinstance(row, dict):
        data = {
            'id': int(row.get('id') or 0),
            'reference_number': (row.get('reference_number') or '').strip(),
            'quantity': int(row.get('quantity') or 0),
            'buying_price': row.get('buying_price'),
            'total_amount': row.get('total_amount'),
            'payment_status': (row.get('payment_status') or '').strip(),
            'amount_paid': row.get('amount_paid'),
            'paid_to_company_name': (row.get('paid_to_company_name') or '').strip() or None,
            'paid_to_company_phone': (row.get('paid_to_company_phone') or '').strip() or None,
            'notes': (row.get('notes') or '').strip() or None,
            'delivery_note': (row.get('delivery_note') or '').strip() or None,
            'created_at': row.get('created_at'),
            'performed_by_name': (row.get('performed_by_name') or '').strip() or None,
            'item_ref': (row.get('item_ref') or '').strip(),
            'item_name': (row.get('item_name') or '').strip(),
            'item_category': (row.get('item_category') or '').strip(),
            'measure': (row.get('measure') or '').strip(),
            'supplier_name': (row.get('supplier_name') or '').strip() or None,
            'supplier_phone': (row.get('supplier_phone') or '').strip() or None,
        }
    else:
        data = {
            'id': int(row[0] or 0),
            'reference_number': (row[1] or '').strip(),
            'quantity': int(row[2] or 0),
            'buying_price': row[3] if len(row) > 3 else None,
            'total_amount': row[4] if len(row) > 4 else None,
            'payment_status': (row[5] or '').strip() if len(row) > 5 else '',
            'amount_paid': row[6] if len(row) > 6 else 0,
            'paid_to_company_name': (row[7] or '').strip() or None if len(row) > 7 else None,
            'paid_to_company_phone': (row[8] or '').strip() or None if len(row) > 8 else None,
            'notes': (row[9] or '').strip() or None if len(row) > 9 else None,
            'delivery_note': (row[10] or '').strip() or None if len(row) > 10 else None,
            'created_at': row[11] if len(row) > 11 else None,
            'performed_by_name': (row[12] or '').strip() or None if len(row) > 12 else None,
            'item_ref': (row[13] or '').strip() if len(row) > 13 else '',
            'item_name': (row[14] or '').strip() if len(row) > 14 else '',
            'item_category': (row[15] or '').strip() if len(row) > 15 else '',
            'measure': (row[16] or '').strip() if len(row) > 16 else '',
            'supplier_name': (row[17] or '').strip() or None if len(row) > 17 else None,
            'supplier_phone': (row[18] or '').strip() or None if len(row) > 18 else None,
        }
    ca = data.get('created_at')
    if ca and hasattr(ca, 'strftime'):
        data['created_at_display'] = ca.strftime('%d %b %Y, %H:%M')
    elif ca:
        data['created_at_display'] = str(ca)
    else:
        data['created_at_display'] = '—'
    try:
        bp = float(data['buying_price']) if data.get('buying_price') is not None else None
        data['buying_price_display'] = f'{bp:.2f}' if bp is not None else '—'
    except (TypeError, ValueError):
        data['buying_price_display'] = '—'
    try:
        ta = float(data['total_amount']) if data.get('total_amount') is not None else None
        data['total_amount_display'] = f'{ta:.2f}' if ta is not None else '—'
    except (TypeError, ValueError):
        data['total_amount_display'] = '—'
        ta = None
    try:
        ap = float(data.get('amount_paid') or 0)
        data['amount_paid_display'] = f'{ap:.2f}'
    except (TypeError, ValueError):
        ap = 0.0
        data['amount_paid_display'] = '0.00'
    if ta is not None:
        balance = max(0.0, ta - ap)
        data['balance_due'] = balance
        data['balance_due_display'] = f'{balance:.2f}'
    else:
        data['balance_due'] = 0.0
        data['balance_due_display'] = '—'
    status = _store_stock_payment_status(ap, ta)
    data['payment_status'] = status
    if status == 'partial':
        data['payment_status_label'] = 'Partial payment'
    elif status == 'paid':
        data['payment_status_label'] = 'Paid'
    else:
        data['payment_status_label'] = 'Pending'
    data['can_pay'] = status in ('pending', 'partial')
    return data


def _fetch_store_stock_in_list(cursor, payment_filter='all', limit=500):
    """All stock-in movements for accountant payments view."""
    ensure_store_stock_movements_table(cursor)
    payment_filter = (payment_filter or 'all').strip().lower()
    if payment_filter == 'pending':
        where_extra = "AND m.payment_status = 'pending'"
    elif payment_filter == 'partial':
        where_extra = "AND m.payment_status = 'partial'"
    elif payment_filter == 'paid':
        where_extra = "AND m.payment_status = 'paid'"
    elif payment_filter == 'outstanding':
        where_extra = "AND m.payment_status IN ('pending', 'partial')"
    else:
        where_extra = ''
    rows = []
    try:
        cursor.execute(
            f"""
            SELECT m.id, m.reference_number, m.quantity,
                   m.buying_price, m.total_amount, m.payment_status,
                   m.amount_paid, m.paid_to_company_name, m.paid_to_company_phone,
                   m.notes, m.delivery_note, m.created_at, m.performed_by_name,
                   si.reference_code AS item_ref, si.item_name, si.item_category, si.measure,
                   sup.company_name AS supplier_name, sup.phone AS supplier_phone
            FROM store_stock_movements m
            INNER JOIN store_inventory_items si ON si.id = m.store_item_id
            LEFT JOIN store_suppliers sup ON sup.id = m.supplier_id
            WHERE m.movement_type = 'in'
            {where_extra}
            ORDER BY m.created_at DESC, m.id DESC
            LIMIT %s
            """,
            (int(limit),),
        )
        for row in cursor.fetchall() or []:
            rows.append(_stock_in_row_to_dict(row))
    except Exception as e:
        print(f"_fetch_store_stock_in_list: {e}")
    return rows


def _supplier_payable_phone_key(row):
    """Normalized phone used to group supplier payables."""
    phone = _normalize_store_supplier_phone(
        (row.get('paid_to_company_phone') or row.get('supplier_phone') or '')
    )
    if phone:
        return phone
    return f"__no_phone_{row.get('id')}"


def _stock_in_invoice_dropdown_label(row):
    """Display label for invoice picker: delivery note — reference."""
    ref = (row.get('reference_number') or '').strip() or '—'
    dn = (row.get('delivery_note') or '').strip()
    if dn:
        return f'{dn} — {ref}'
    return ref


def _slim_payable_movement(row):
    """Movement fields needed by the pay modal (JSON-safe)."""
    if not row:
        return None
    return {
        'id': row.get('id'),
        'reference_number': row.get('reference_number'),
        'delivery_note': row.get('delivery_note'),
        'invoice_label': _stock_in_invoice_dropdown_label(row),
        'item_name': row.get('item_name'),
        'balance_due': row.get('balance_due'),
        'balance_due_display': row.get('balance_due_display'),
        'total_amount_display': row.get('total_amount_display'),
        'amount_paid_display': row.get('amount_paid_display'),
        'paid_to_company_name': row.get('paid_to_company_name'),
        'supplier_name': row.get('supplier_name'),
        'paid_to_company_phone': row.get('paid_to_company_phone'),
        'supplier_phone': row.get('supplier_phone'),
    }


def _aggregate_supplier_payables_by_phone(records, status_filter='all'):
    """Cumulative balance and status per supplier, grouped by phone number."""
    status_filter = (status_filter or 'all').strip().lower()
    if status_filter not in ('all', 'pending', 'partial', 'paid', 'outstanding'):
        status_filter = 'all'

    buckets = {}
    for row in records:
        key = _supplier_payable_phone_key(row)
        if key not in buckets:
            display_phone = (
                row.get('paid_to_company_phone') or row.get('supplier_phone') or ''
            ).strip()
            if not display_phone and not key.startswith('__no_phone_'):
                display_phone = key
            buckets[key] = {
                'phone_key': key,
                'supplier_phone': display_phone or '—',
                'supplier_name': '—',
                'movements': [],
                'total_invoiced': 0.0,
                'total_paid': 0.0,
                'balance_due': 0.0,
                'invoice_count': 0,
            }
        bucket = buckets[key]
        bucket['movements'].append(row)
        bucket['invoice_count'] += 1
        try:
            invoiced = float(row.get('total_amount') or 0)
        except (TypeError, ValueError):
            invoiced = 0.0
        try:
            paid = float(row.get('amount_paid') or 0)
        except (TypeError, ValueError):
            paid = 0.0
        try:
            balance = float(row.get('balance_due') if row.get('balance_due') is not None else max(0.0, invoiced - paid))
        except (TypeError, ValueError):
            balance = max(0.0, invoiced - paid)
        bucket['total_invoiced'] += invoiced
        bucket['total_paid'] += paid
        bucket['balance_due'] += balance
        reg_name = (row.get('supplier_name') or '').strip()
        paid_name = (row.get('paid_to_company_name') or '').strip()
        if reg_name:
            bucket['supplier_name'] = reg_name.upper()
        elif paid_name and bucket['supplier_name'] == '—':
            bucket['supplier_name'] = paid_name.upper()
        if not bucket['supplier_phone'] or bucket['supplier_phone'] == '—':
            phone_display = (row.get('supplier_phone') or row.get('paid_to_company_phone') or '').strip()
            if phone_display:
                bucket['supplier_phone'] = phone_display

    aggregated = []
    for bucket in buckets.values():
        balance = bucket['balance_due']
        paid_total = bucket['total_paid']
        if balance <= 0.005:
            payment_status = 'paid'
            payment_status_label = 'Paid'
        elif paid_total <= 0.005:
            payment_status = 'pending'
            payment_status_label = 'Pending'
        else:
            payment_status = 'partial'
            payment_status_label = 'Partial payment'

        payable_movements = [m for m in bucket['movements'] if m.get('can_pay')]
        payable_movements.sort(
            key=lambda m: (
                m.get('created_at').timestamp()
                if m.get('created_at') and hasattr(m.get('created_at'), 'timestamp')
                else 0
            ),
        )
        pay_record = payable_movements[0] if payable_movements else None
        print_record = bucket['movements'][0] if bucket['invoice_count'] == 1 else None

        aggregated.append({
            'phone_key': bucket['phone_key'],
            'supplier_name': bucket['supplier_name'],
            'supplier_phone': bucket['supplier_phone'],
            'payment_status': payment_status,
            'payment_status_label': payment_status_label,
            'balance_due': balance,
            'balance_due_display': f'{balance:.2f}',
            'total_invoiced': bucket['total_invoiced'],
            'total_paid': bucket['total_paid'],
            'invoice_count': bucket['invoice_count'],
            'payable_invoice_count': len(payable_movements),
            'payable_invoices': [
                _slim_payable_movement(m) for m in payable_movements if _slim_payable_movement(m)
            ],
            'can_pay': (
                pay_record is not None
                and balance > 0.005
                and (
                    not str(bucket['phone_key']).startswith('__no_phone_')
                    or bucket['invoice_count'] == 1
                )
            ),
            'print_record': _slim_payable_movement(print_record),
        })

    if status_filter == 'outstanding':
        aggregated = [
            r for r in aggregated if r['payment_status'] in ('pending', 'partial')
        ]
    elif status_filter != 'all':
        aggregated = [r for r in aggregated if r['payment_status'] == status_filter]

    aggregated.sort(key=lambda r: (r['supplier_name'], r['supplier_phone']))
    return aggregated


def _fetch_store_suppliers_overview(cursor, status_filter='all'):
    """Registered suppliers plus stock-in payables, with balances and payment status."""
    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    status_filter = (status_filter or 'all').strip().lower()
    if status_filter not in ('all', 'pending', 'partial', 'paid', 'outstanding', 'clear'):
        status_filter = 'all'

    registered = _fetch_store_suppliers_list(cursor, limit=5000)
    movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    payables = _aggregate_supplier_payables_by_phone(movements, status_filter='all')
    payables_by_phone = {}
    payables_by_key = {}
    for payable in payables:
        phone_norm = _normalize_store_supplier_phone(payable.get('supplier_phone') or '')
        if phone_norm:
            payables_by_phone[phone_norm] = payable
        key = (payable.get('phone_key') or '').strip()
        if key:
            payables_by_key[key] = payable

    seen_keys = set()
    results = []

    def _append_supplier_row(sup_id, phone, company_name, is_registered, payable):
        balance = float(payable.get('balance_due') or 0) if payable else 0.0
        if payable:
            payment_status = payable.get('payment_status') or 'paid'
            payment_status_label = payable.get('payment_status_label') or 'Paid'
            invoice_count = int(payable.get('invoice_count') or 0)
            total_invoiced = float(payable.get('total_invoiced') or 0)
            total_paid = float(payable.get('total_paid') or 0)
        else:
            payment_status = 'paid'
            payment_status_label = 'Clear'
            invoice_count = 0
            total_invoiced = 0.0
            total_paid = 0.0
        results.append({
            'id': sup_id,
            'phone': phone or '—',
            'phone_key': (
                (payable.get('phone_key') if payable else None)
                or _normalize_store_supplier_phone(phone or '')
                or (f"__reg_{sup_id}" if sup_id else '')
            ),
            'company_name': (company_name or '—').strip().upper() or '—',
            'is_registered': bool(is_registered),
            'payment_status': payment_status,
            'payment_status_label': payment_status_label,
            'balance_due': balance,
            'balance_due_display': f'{balance:,.2f}',
            'total_invoiced': total_invoiced,
            'total_invoiced_display': f'{total_invoiced:,.2f}',
            'total_paid': total_paid,
            'total_paid_display': f'{total_paid:,.2f}',
            'invoice_count': invoice_count,
        })

    for sup in registered:
        phone_norm = _normalize_store_supplier_phone(sup.get('phone') or '')
        payable = payables_by_phone.get(phone_norm)
        seen_keys.add(phone_norm or f"__reg_{sup.get('id')}")
        _append_supplier_row(
            sup.get('id'),
            sup.get('phone'),
            sup.get('company_name'),
            True,
            payable,
        )

    for payable in payables:
        phone_norm = _normalize_store_supplier_phone(payable.get('supplier_phone') or '')
        phone_key = (payable.get('phone_key') or '').strip()
        dedupe_key = phone_norm or phone_key
        if not dedupe_key or dedupe_key in seen_keys:
            continue
        seen_keys.add(dedupe_key)
        _append_supplier_row(
            None,
            payable.get('supplier_phone'),
            payable.get('supplier_name'),
            False,
            payable,
        )

    if status_filter == 'outstanding':
        results = [r for r in results if r['payment_status'] in ('pending', 'partial')]
    elif status_filter == 'clear':
        results = [r for r in results if r['payment_status'] == 'paid' and r['balance_due'] <= 0.005]
    elif status_filter != 'all':
        results = [r for r in results if r['payment_status'] == status_filter]

    results.sort(key=lambda r: (r['company_name'], r['phone']))
    return results


def _fetch_store_supplier_detail_for_page(cursor, supplier_id=None, phone_key=None):
    """Supplier profile with all stock-in supplies and payment status."""
    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)

    supplier_row = None
    resolved_key = (phone_key or '').strip()

    if supplier_id:
        supplier_row = _store_lookup_supplier_by_id(cursor, supplier_id)
        if not supplier_row:
            return None
        resolved_key = _normalize_store_supplier_phone(supplier_row.get('phone') or '') or resolved_key
    elif resolved_key and not str(resolved_key).startswith('__no_phone_'):
        phone_norm = _normalize_store_supplier_phone(resolved_key)
        if phone_norm:
            resolved_key = phone_norm
            supplier_row = _store_lookup_supplier_by_phone(cursor, phone_norm)

    if not resolved_key and not supplier_row:
        return None
    if not resolved_key and supplier_row:
        resolved_key = _normalize_store_supplier_phone(supplier_row.get('phone') or '')

    pack = _fetch_supplier_payment_statement_pack(cursor, resolved_key) if resolved_key else None
    invoices = (pack or {}).get('invoices') or []
    supplies = []
    for inv in invoices:
        supplies.append({
            'id': inv.get('id'),
            'reference_number': inv.get('reference_number'),
            'delivery_note': inv.get('delivery_note'),
            'invoice_label': _stock_in_invoice_dropdown_label(inv),
            'item_ref': inv.get('item_ref'),
            'item_name': inv.get('item_name'),
            'item_category': inv.get('item_category'),
            'measure': inv.get('measure'),
            'quantity': inv.get('quantity'),
            'buying_price_display': inv.get('buying_price_display'),
            'total_amount_display': inv.get('total_amount_display'),
            'amount_paid_display': inv.get('amount_paid_display'),
            'balance_due_display': inv.get('balance_due_display'),
            'payment_status': inv.get('payment_status'),
            'payment_status_label': inv.get('payment_status_label'),
            'created_at_display': inv.get('created_at_display'),
            'performed_by_name': inv.get('performed_by_name'),
        })

    movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    aggregated = _aggregate_supplier_payables_by_phone(movements, status_filter='all')
    payable = next((row for row in aggregated if row.get('phone_key') == resolved_key), None)

    company_name = (
        (supplier_row.get('company_name') if supplier_row else None)
        or (pack.get('supplier_name') if pack else None)
        or '—'
    )
    phone = (
        (supplier_row.get('phone') if supplier_row else None)
        or (pack.get('supplier_phone') if pack else None)
        or '—'
    )
    balance_due = float(payable.get('balance_due') or 0) if payable else sum(
        float(inv.get('balance_due') or 0) for inv in invoices
    )
    total_invoiced = float(payable.get('total_invoiced') or 0) if payable else sum(
        float(inv.get('total_amount') or 0) for inv in invoices
    )
    total_paid = float(payable.get('total_paid') or 0) if payable else sum(
        float(inv.get('amount_paid') or 0) for inv in invoices
    )

    if payable:
        payment_status = payable.get('payment_status') or 'paid'
        payment_status_label = payable.get('payment_status_label') or 'Paid'
    elif balance_due <= 0.005:
        payment_status = 'paid'
        payment_status_label = 'Clear'
    elif total_paid <= 0.005:
        payment_status = 'pending'
        payment_status_label = 'Pending'
    else:
        payment_status = 'partial'
        payment_status_label = 'Partial payment'

    return {
        'id': int(supplier_row['id']) if supplier_row and supplier_row.get('id') else None,
        'company_name': str(company_name).strip().upper() or '—',
        'phone': phone or '—',
        'phone_key': resolved_key,
        'is_registered': bool(supplier_row),
        'invoice_count': len(supplies),
        'payment_status': payment_status,
        'payment_status_label': payment_status_label,
        'balance_due': balance_due,
        'balance_due_display': f'{balance_due:,.2f}',
        'total_invoiced': total_invoiced,
        'total_invoiced_display': f'{total_invoiced:,.2f}',
        'total_paid': total_paid,
        'total_paid_display': f'{total_paid:,.2f}',
        'supplies': supplies,
        'payment_lines': (pack or {}).get('payment_lines') or [],
    }


def _stock_in_payment_line_row_to_dict(row):
    """JSON/print-safe payment line with invoice context."""
    if isinstance(row, dict):
        data = {
            'id': row.get('id'),
            'movement_id': row.get('movement_id'),
            'amount_paid': row.get('amount_paid'),
            'paid_to_company_name': row.get('paid_to_company_name'),
            'paid_to_company_phone': row.get('paid_to_company_phone'),
            'paid_by_name': row.get('paid_by_name'),
            'payment_method': row.get('payment_method'),
            'payment_reference': row.get('payment_reference'),
            'created_at': row.get('created_at'),
            'reference_number': row.get('reference_number'),
            'movement_total': row.get('movement_total'),
            'movement_status': row.get('movement_status'),
            'item_name': row.get('item_name'),
            'item_category': row.get('item_category'),
            'finance_account_name': row.get('finance_account_name'),
        }
    else:
        data = {
            'id': row[0] if len(row) > 0 else None,
            'movement_id': row[1] if len(row) > 1 else None,
            'amount_paid': row[2] if len(row) > 2 else 0,
            'paid_to_company_name': row[3] if len(row) > 3 else '',
            'paid_to_company_phone': row[4] if len(row) > 4 else '',
            'paid_by_name': row[5] if len(row) > 5 else '',
            'payment_method': row[6] if len(row) > 6 else '',
            'payment_reference': row[7] if len(row) > 7 else '',
            'created_at': row[8] if len(row) > 8 else None,
            'reference_number': row[9] if len(row) > 9 else '',
            'movement_total': row[10] if len(row) > 10 else None,
            'movement_status': row[11] if len(row) > 11 else '',
            'item_name': row[12] if len(row) > 12 else '',
            'item_category': row[13] if len(row) > 13 else '',
            'finance_account_name': row[14] if len(row) > 14 else '',
        }
    try:
        amt = float(data.get('amount_paid') or 0)
    except (TypeError, ValueError):
        amt = 0.0
    data['amount_display'] = f'{amt:,.2f}'
    ca = data.get('created_at')
    if ca and hasattr(ca, 'strftime'):
        data['created_at_display'] = ca.strftime('%d %b %Y, %H:%M')
    elif ca:
        data['created_at_display'] = str(ca)
    else:
        data['created_at_display'] = '—'
    data['reference_number'] = (data.get('reference_number') or '').strip()
    data['payment_reference'] = (data.get('payment_reference') or '').strip() or '—'
    data['payment_method'] = (data.get('payment_method') or '').strip() or '—'
    data['paid_by_name'] = (data.get('paid_by_name') or '').strip() or '—'
    data['finance_account_name'] = (data.get('finance_account_name') or '').strip() or '—'
    data['item_name'] = (data.get('item_name') or '').strip()
    data['item_category'] = (data.get('item_category') or '').strip()
    return data


def _fetch_stock_in_payment_lines_for_movements(cursor, movement_ids):
    """Payment lines for stock-in movements (oldest first)."""
    ids = [int(i) for i in (movement_ids or []) if i]
    if not ids:
        return []
    ensure_store_stock_in_payment_lines_table(cursor)
    ensure_store_stock_movements_table(cursor)
    placeholders = ','.join(['%s'] * len(ids))
    rows = []
    try:
        cursor.execute(
            f"""
            SELECT pl.id, pl.movement_id, pl.amount_paid, pl.paid_to_company_name,
                   pl.paid_to_company_phone, pl.paid_by_name, pl.payment_method,
                   pl.payment_reference, pl.created_at,
                   m.reference_number, m.total_amount, m.payment_status,
                   si.item_name, si.item_category,
                   fa.account_name AS finance_account_name
            FROM store_stock_in_payment_lines pl
            INNER JOIN store_stock_movements m ON m.id = pl.movement_id
            INNER JOIN store_inventory_items si ON si.id = m.store_item_id
            LEFT JOIN finance_accounts fa ON fa.id = pl.finance_account_id
            WHERE pl.movement_id IN ({placeholders})
            ORDER BY pl.created_at ASC, pl.id ASC
            """,
            tuple(ids),
        )
        for row in cursor.fetchall() or []:
            rows.append(_stock_in_payment_line_row_to_dict(row))
    except Exception as e:
        print(f"_fetch_stock_in_payment_lines_for_movements: {e}")
    return rows


def _fetch_supplier_payment_statement_pack(cursor, phone_key):
    """Invoices, payment lines, and misc rows for one supplier grouping key."""
    phone_key = (phone_key or '').strip()
    if not phone_key:
        return None

    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)
    ensure_accountant_misc_payments_table(cursor)

    all_movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    invoices = [
        m for m in all_movements
        if _supplier_payable_phone_key(m) == phone_key
    ]
    invoices.sort(
        key=lambda m: (
            m.get('created_at').timestamp()
            if m.get('created_at') and hasattr(m.get('created_at'), 'timestamp')
            else 0
        ),
    )

    movement_ids = [int(m.get('id') or 0) for m in invoices if m.get('id')]
    payment_lines = _fetch_stock_in_payment_lines_for_movements(cursor, movement_ids)

    phone_norm = ''
    if not phone_key.startswith('__no_phone_'):
        phone_norm = _normalize_store_supplier_phone(phone_key)

    misc_payments = []
    for misc_row in _fetch_accountant_misc_payments(cursor, limit=2000):
        misc_phone = _normalize_store_supplier_phone(
            misc_row.get('paid_to_company_phone') or '',
        )
        if phone_norm and misc_phone == phone_norm:
            misc_payments.append(misc_row)

    supplier_name = '—'
    supplier_phone = '—'
    for inv in invoices:
        reg = (inv.get('supplier_name') or '').strip()
        paid_name = (inv.get('paid_to_company_name') or '').strip()
        if reg:
            supplier_name = reg.upper()
        elif paid_name and supplier_name == '—':
            supplier_name = paid_name.upper()
        ph = (inv.get('supplier_phone') or inv.get('paid_to_company_phone') or '').strip()
        if ph:
            supplier_phone = ph
    if misc_payments and supplier_name == '—':
        supplier_name = (misc_payments[0].get('paid_to_company_name') or '—').upper()
    if misc_payments and (supplier_phone == '—' or not supplier_phone):
        supplier_phone = misc_payments[0].get('paid_to_company_phone') or '—'

    total_invoiced = sum(float(m.get('total_amount') or 0) for m in invoices)
    total_paid_on_invoices = sum(float(m.get('amount_paid') or 0) for m in invoices)
    balance_due = sum(
        float(m.get('balance_due') if m.get('balance_due') is not None else 0)
        for m in invoices
    )
    payments_total = sum(float(p.get('amount_paid') or 0) for p in payment_lines)
    misc_total = sum(float(m.get('amount') or 0) for m in misc_payments)

    return {
        'phone_key': phone_key,
        'supplier_name': supplier_name,
        'supplier_phone': supplier_phone,
        'invoices': invoices,
        'payment_lines': payment_lines,
        'misc_payments': misc_payments,
        'invoice_count': len(invoices),
        'payment_line_count': len(payment_lines),
        'misc_count': len(misc_payments),
        'total_invoiced': total_invoiced,
        'total_invoiced_display': _format_kes_amount(total_invoiced),
        'total_paid_display': _format_kes_amount(total_paid_on_invoices),
        'payments_total_display': _format_kes_amount(payments_total),
        'balance_due_display': _format_kes_amount(balance_due),
        'misc_total_display': _format_kes_amount(misc_total),
    }


def _fetch_payments_invoices_statement_packs(cursor, payment_filter='outstanding'):
    """Statement packs for each supplier row on the payments / invoices page."""
    payment_filter = (payment_filter or 'outstanding').strip().lower()
    movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    suppliers = _aggregate_supplier_payables_by_phone(
        movements, status_filter=payment_filter,
    )
    packs = []
    for sup in suppliers:
        pack = _fetch_supplier_payment_statement_pack(cursor, sup.get('phone_key'))
        if pack:
            packs.append(pack)
    return packs, payment_filter


def _fetch_outstanding_stock_in_for_phone(cursor, phone_norm):
    """Outstanding stock-in movements for a supplier phone (oldest first)."""
    if not phone_norm or str(phone_norm).startswith('__no_phone_'):
        return []
    records = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=2000)
    out = [
        row for row in records
        if _supplier_payable_phone_key(row) == phone_norm and row.get('can_pay')
    ]
    out.sort(
        key=lambda m: (
            m.get('created_at').timestamp()
            if m.get('created_at') and hasattr(m.get('created_at'), 'timestamp')
            else 0
        ),
    )
    return out


def _fetch_supplier_payable_by_phone(cursor, phone_raw):
    """Look up a registered store supplier by phone and return school payables (JSON-safe)."""
    phone_norm = _normalize_store_supplier_phone(phone_raw)
    if not phone_norm:
        return {
            'is_supplier': False,
            'ready': False,
            'message': 'Enter a valid phone number (at least 9 digits).',
        }

    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)

    supplier = _store_lookup_supplier_by_phone(cursor, phone_norm)
    if not supplier:
        return {
            'is_supplier': False,
            'ready': True,
            'supplier_phone': phone_norm,
            'message': 'This phone number is not registered as a supplier.',
        }

    stock_records = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=2000)
    aggregated = _aggregate_supplier_payables_by_phone(stock_records, status_filter='all')
    payable = next((row for row in aggregated if row.get('phone_key') == phone_norm), None) or {}
    balance_due = float(payable.get('balance_due') or 0)

    return {
        'is_supplier': True,
        'ready': True,
        'supplier_id': supplier.get('id'),
        'supplier_name': supplier.get('company_name') or '',
        'supplier_phone': supplier.get('phone') or phone_norm,
        'balance_due': balance_due,
        'balance_due_display': f'{balance_due:,.2f}',
        'invoice_count': int(payable.get('invoice_count') or 0),
        'payment_status': payable.get('payment_status') or 'paid',
        'payment_status_label': payable.get('payment_status_label') or 'Paid',
        'total_invoiced': float(payable.get('total_invoiced') or 0),
        'total_paid': float(payable.get('total_paid') or 0),
        'message': 'Registered supplier — school payable balance loaded.',
    }


def _fetch_parent_supplier_info_for_student(cursor, student_id):
    """
    If a student's parent/guardian phone matches a registered store supplier,
    return supplier payables owed by the school (JSON-safe dict).
    """
    sid = (student_id or '').strip()
    if not sid:
        return {'is_supplier': False}

    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)

    cursor.execute(
        """
        SELECT full_name, phone FROM parents
        WHERE student_id = %s
        ORDER BY id ASC
        """,
        (sid,),
    )
    parents = cursor.fetchall() or []
    if not parents:
        return {'is_supplier': False}

    for parent_row in parents:
        if isinstance(parent_row, dict):
            parent_name = (parent_row.get('full_name') or '').strip()
            parent_phone = (parent_row.get('phone') or '').strip()
        else:
            parent_name = (parent_row[0] or '').strip() if len(parent_row) > 0 else ''
            parent_phone = (parent_row[1] or '').strip() if len(parent_row) > 1 else ''

        info = _fetch_supplier_payable_by_phone(cursor, parent_phone)
        if info.get('is_supplier'):
            info['parent_name'] = parent_name
            info['parent_phone'] = parent_phone
            return info

    return {'is_supplier': False}


def _apply_supplier_offset_for_fee_payment(
    cursor, supplier_phone, offset_amount, paid_by_name, student_payment_id, student_id=None,
):
    """Apply fee payment against outstanding supplier stock-in payables (no cash out)."""
    from decimal import Decimal, InvalidOperation

    try:
        offset_dec = Decimal(str(offset_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid supplier offset amount.'

    if offset_dec <= 0:
        return False, 'Supplier offset amount must be greater than zero.'

    info = _fetch_supplier_payable_by_phone(cursor, supplier_phone)
    if not info.get('is_supplier'):
        return False, 'Enter a registered supplier phone number to trade from their account.'

    available = Decimal(str(info.get('balance_due') or 0)).quantize(Decimal('0.01'))
    if available <= 0:
        return False, 'This supplier has no outstanding balance for the school to trade against.'
    if offset_dec > available:
        return False, (
            f'Supplier credit available is only KES {float(available):,.2f}.'
        )

    phone_norm = info.get('supplier_phone') or ''
    company_name = (info.get('supplier_name') or 'SUPPLIER').strip().upper()
    if not phone_norm:
        return False, 'Supplier phone could not be resolved for offset.'

    movements = _fetch_outstanding_stock_in_for_phone(cursor, phone_norm)
    if not movements:
        return False, 'No outstanding supplier invoices to offset against.'

    remaining = offset_dec
    student_ref = (student_id or '').strip()
    ref = f'Fee offset #{student_payment_id}'
    if student_ref:
        ref = f'Fee offset {student_ref} #{student_payment_id}'
    for mov in movements:
        if remaining <= Decimal('0'):
            break
        try:
            mov_balance = Decimal(str(mov.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            mov_balance = Decimal('0')
        if mov_balance <= 0:
            continue
        apply_amt = min(remaining, mov_balance)
        ok, msg = _apply_stock_in_payment(
            cursor,
            mov['id'],
            apply_amt,
            company_name,
            phone_norm,
            paid_by_name,
            payment_method='Supplier Offset (School fees)',
            finance_account_id=None,
            payment_reference=ref,
            skip_account_debit=True,
        )
        if not ok:
            return False, msg or 'Could not apply supplier offset.'
        remaining = (remaining - apply_amt).quantize(Decimal('0.01'))

    if remaining > Decimal('0.01'):
        return False, 'Could not apply the full supplier offset amount.'
    return True, None


def _apply_stock_in_payment(
    cursor, movement_id, pay_amount, company_name, company_phone, paid_by_name,
    payment_method=None, finance_account_id=None, payment_reference=None,
    skip_account_debit=False, vote_name=None,
):
    """Apply one payment line to a stock-in movement. Returns (ok, message)."""
    from decimal import Decimal, InvalidOperation

    try:
        pay_dec = Decimal(str(pay_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid payment amount.'
    if pay_dec <= 0:
        return False, 'Enter a valid payment amount greater than zero.'

    cursor.execute(
        """
        SELECT id, reference_number, movement_type, total_amount, amount_paid
        FROM store_stock_movements WHERE id = %s
        """,
        (movement_id,),
    )
    row = cursor.fetchone()
    if not row:
        return False, 'Stock in record not found.'
    if isinstance(row, dict):
        movement_type = (row.get('movement_type') or '').strip()
        ref_no = (row.get('reference_number') or '').strip()
        total_amount = row.get('total_amount')
        current_paid = row.get('amount_paid') or 0
    else:
        movement_type = (row[2] or '').strip() if len(row) > 2 else ''
        ref_no = (row[1] or '').strip() if len(row) > 1 else ''
        total_amount = row[3] if len(row) > 3 else None
        current_paid = row[4] if len(row) > 4 else 0
    if movement_type != 'in':
        return False, 'Only stock in records can be paid from this page.'
    try:
        total_dec = Decimal(str(total_amount or 0)).quantize(Decimal('0.01'))
        paid_dec = Decimal(str(current_paid or 0)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        total_dec = Decimal('0')
        paid_dec = Decimal('0')
    balance = (total_dec - paid_dec).quantize(Decimal('0.01'))
    if balance <= 0:
        return False, f'{ref_no} is already fully paid.'
    if pay_dec > balance:
        return False, (
            f'Payment for {ref_no} cannot exceed the balance due ({balance}).'
        )
    new_paid = (paid_dec + pay_dec).quantize(Decimal('0.01'))
    new_status = _store_stock_payment_status(new_paid, total_dec)
    ensure_store_stock_in_payment_lines_table(cursor)
    vote_label = (vote_name or '').strip().upper() or None
    cursor.execute(
        """
        INSERT INTO store_stock_in_payment_lines
            (movement_id, amount_paid, paid_to_company_name,
             paid_to_company_phone, paid_by_name, payment_method,
             finance_account_id, payment_reference, vote_name)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            movement_id, pay_dec, company_name, company_phone, paid_by_name or None,
            payment_method, finance_account_id, payment_reference, vote_label,
        ),
    )
    line_id = cursor.lastrowid
    if not skip_account_debit and finance_account_id and payment_method and line_id:
        debit_desc = f'Stock-in payment {ref_no}'
        if vote_label:
            debit_desc = f'{vote_label} — {debit_desc}'
        ok, err = _debit_finance_account(
            cursor,
            finance_account_id,
            pay_dec,
            payment_method,
            payment_reference,
            debit_desc,
            related_type='stock_in_payment_line',
            related_id=int(line_id),
            recorded_by_name=paid_by_name,
        )
        if not ok:
            return False, err
    cursor.execute(
        """
        UPDATE store_stock_movements
        SET amount_paid = %s, payment_status = %s,
            paid_to_company_name = %s, paid_to_company_phone = %s
        WHERE id = %s AND movement_type = 'in'
        """,
        (new_paid, new_status, company_name, company_phone, movement_id),
    )
    if new_status == 'paid':
        return True, f'{ref_no} fully paid ({pay_dec}).'
    remaining = (total_dec - new_paid).quantize(Decimal('0.01'))
    return True, f'{ref_no} partial ({pay_dec}); balance {remaining}.'


def _record_supplier_pay_all(
    cursor, phone_norm, pay_amount, company_name, company_phone, paid_by_name,
    payment_method=None, finance_account_id=None, payment_reference=None,
    vote_name=None,
):
    """Apply payment across all outstanding invoices for a supplier phone."""
    from decimal import Decimal, InvalidOperation

    try:
        pay_total = Decimal(str(pay_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid payment amount.'
    if pay_total <= 0:
        return False, 'Enter a valid payment amount greater than zero.'

    movements = _fetch_outstanding_stock_in_for_phone(cursor, phone_norm)
    if not movements:
        return False, 'No outstanding invoices for this supplier.'

    total_balance = Decimal('0')
    for m in movements:
        try:
            total_balance += Decimal(str(m.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            pass
    if pay_total > total_balance + Decimal('0.01'):
        return False, (
            f'Payment cannot exceed total balance due ({total_balance.quantize(Decimal("0.01"))}).'
        )

    if finance_account_id and payment_method:
        ok_funds, _, fund_err = _validate_disbursement_finance_account(
            cursor, finance_account_id, payment_method, pay_total,
        )
        if not ok_funds:
            return False, fund_err or 'Insufficient funds in the selected account.'

    remaining = pay_total
    applied = 0
    notes = []
    for m in movements:
        if remaining <= Decimal('0'):
            break
        try:
            bal = Decimal(str(m.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            continue
        if bal <= 0:
            continue
        chunk = min(remaining, bal)
        ok, msg = _apply_stock_in_payment(
            cursor, m['id'], chunk, company_name, company_phone, paid_by_name,
            payment_method=payment_method,
            finance_account_id=finance_account_id,
            payment_reference=payment_reference,
            skip_account_debit=False,
            vote_name=vote_name,
        )
        if not ok:
            return False, msg
        applied += 1
        notes.append(msg)
        remaining -= chunk

    if applied == 0:
        return False, 'No payment was applied.'
    summary = (
        f'Payment of KES {pay_total:,.2f} recorded across {applied} invoice(s) '
        f'for {company_name}.'
    )
    if remaining > Decimal('0.005'):
        summary += f' Unallocated: KES {remaining.quantize(Decimal("0.01")):,.2f}.'
    return True, summary


def _record_supplier_pay_selected_invoices(
    cursor, movement_ids, company_name, company_phone, paid_by_name,
    payment_method=None, finance_account_id=None, payment_reference=None,
    expected_amount=None, vote_name=None,
):
    """Pay selected outstanding stock-in invoices — full or partial (FIFO across selection)."""
    from decimal import Decimal, InvalidOperation

    ids = []
    for raw in movement_ids or []:
        try:
            mid = int(raw)
        except (TypeError, ValueError):
            continue
        if mid > 0 and mid not in ids:
            ids.append(mid)
    if not ids:
        return False, 'Select at least one invoice to pay.'

    movements = []
    total_balance = Decimal('0')
    for mid in ids:
        cursor.execute(
            """
            SELECT id, reference_number, movement_type, total_amount, amount_paid,
                   payment_status
            FROM store_stock_movements WHERE id = %s
            """,
            (mid,),
        )
        row = cursor.fetchone()
        if not row:
            return False, f'Invoice #{mid} not found.'
        if isinstance(row, dict):
            movement_type = (row.get('movement_type') or '').strip()
            ref_no = (row.get('reference_number') or '').strip()
            total_amount = row.get('total_amount')
            current_paid = row.get('amount_paid') or 0
            payment_status = (row.get('payment_status') or '').strip()
        else:
            movement_type = (row[2] or '').strip() if len(row) > 2 else ''
            ref_no = (row[1] or '').strip() if len(row) > 1 else ''
            total_amount = row[3] if len(row) > 3 else None
            current_paid = row[4] if len(row) > 4 else 0
            payment_status = (row[5] or '').strip() if len(row) > 5 else ''
        if movement_type != 'in':
            return False, f'{ref_no or mid} is not a stock-in invoice.'
        if payment_status not in ('pending', 'partial'):
            return False, f'{ref_no or mid} is already fully paid.'
        try:
            total_dec = Decimal(str(total_amount or 0)).quantize(Decimal('0.01'))
            paid_dec = Decimal(str(current_paid or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            total_dec = Decimal('0')
            paid_dec = Decimal('0')
        balance = (total_dec - paid_dec).quantize(Decimal('0.01'))
        if balance <= 0:
            return False, f'{ref_no or mid} has no balance due.'
        movements.append({'id': mid, 'ref_no': ref_no, 'balance': balance})
        total_balance += balance

    if expected_amount is not None:
        try:
            pay_total = Decimal(str(expected_amount)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            return False, 'Invalid payment amount.'
        if pay_total <= 0:
            return False, 'Enter a valid payment amount greater than zero.'
        if pay_total > total_balance + Decimal('0.01'):
            return False, (
                f'Payment cannot exceed selected invoice total '
                f'(KES {total_balance.quantize(Decimal("0.01")):,.2f}).'
            )
    else:
        pay_total = total_balance

    if finance_account_id and payment_method:
        ok_funds, _, fund_err = _validate_disbursement_finance_account(
            cursor, finance_account_id, payment_method, pay_total,
        )
        if not ok_funds:
            return False, fund_err or 'Insufficient funds in the selected account.'

    remaining = pay_total
    applied = 0
    for m in movements:
        if remaining <= Decimal('0'):
            break
        chunk = min(remaining, m['balance'])
        ok, msg = _apply_stock_in_payment(
            cursor, m['id'], chunk, company_name, company_phone, paid_by_name,
            payment_method=payment_method,
            finance_account_id=finance_account_id,
            payment_reference=payment_reference,
            skip_account_debit=False,
            vote_name=vote_name,
        )
        if not ok:
            return False, msg
        applied += 1
        remaining -= chunk

    if applied == 0:
        return False, 'No payment was applied.'
    summary = (
        f'Payment of KES {pay_total:,.2f} recorded for {applied} selected invoice(s) '
        f'for {company_name}.'
    )
    if remaining > Decimal('0.005'):
        summary += f' Unallocated: KES {remaining.quantize(Decimal("0.01")):,.2f}.'
    return True, summary


def _fetch_store_stock_movement_detail(cursor, movement_id):
    ensure_store_stock_movements_table(cursor)
    try:
        cursor.execute(
            """
            SELECT m.id, m.reference_number, m.movement_type, m.quantity,
                   m.buying_price, m.total_amount, m.payment_status, m.amount_paid,
                   m.notes, m.delivery_note, m.stock_out_purpose,
                   m.stock_out_date, m.stock_out_department, m.stock_out_receiver_name,
                   m.quantity_before, m.quantity_after, m.created_at,
                   m.performed_by_name,
                   si.reference_code AS item_ref, si.item_name, si.item_category, si.measure,
                   sup.company_name AS supplier_name, sup.phone AS supplier_phone
            FROM store_stock_movements m
            INNER JOIN store_inventory_items si ON si.id = m.store_item_id
            LEFT JOIN store_suppliers sup ON sup.id = m.supplier_id
            WHERE m.id = %s
            """,
            (movement_id,),
        )
        row = cursor.fetchone()
        if not row:
            return None
        if isinstance(row, dict):
            data = {
                'id': int(row.get('id') or 0),
                'reference_number': (row.get('reference_number') or '').strip(),
                'movement_type': (row.get('movement_type') or '').strip(),
                'quantity': int(row.get('quantity') or 0),
                'buying_price': row.get('buying_price'),
                'total_amount': row.get('total_amount'),
                'payment_status': (row.get('payment_status') or '').strip(),
                'amount_paid': row.get('amount_paid'),
                'notes': (row.get('notes') or '').strip() or None,
                'delivery_note': (row.get('delivery_note') or '').strip() or None,
                'stock_out_purpose': (row.get('stock_out_purpose') or '').strip() or None,
                'stock_out_date': row.get('stock_out_date'),
                'stock_out_department': (row.get('stock_out_department') or '').strip() or None,
                'stock_out_receiver_name': (row.get('stock_out_receiver_name') or '').strip() or None,
                'quantity_before': int(row.get('quantity_before') or 0),
                'quantity_after': int(row.get('quantity_after') or 0),
                'created_at': row.get('created_at'),
                'performed_by_name': (row.get('performed_by_name') or '').strip() or None,
                'item_ref': (row.get('item_ref') or '').strip(),
                'item_name': (row.get('item_name') or '').strip(),
                'item_category': (row.get('item_category') or '').strip(),
                'measure': (row.get('measure') or '').strip(),
                'supplier_name': (row.get('supplier_name') or '').strip() or None,
                'supplier_phone': (row.get('supplier_phone') or '').strip() or None,
            }
        else:
            data = {
                'id': int(row[0] or 0),
                'reference_number': (row[1] or '').strip(),
                'movement_type': (row[2] or '').strip(),
                'quantity': int(row[3] or 0),
                'buying_price': row[4] if len(row) > 4 else None,
                'total_amount': row[5] if len(row) > 5 else None,
                'payment_status': (row[6] or '').strip() if len(row) > 6 else '',
                'amount_paid': row[7] if len(row) > 7 else 0,
                'notes': (row[8] or '').strip() or None if len(row) > 8 else None,
                'delivery_note': (row[9] or '').strip() or None if len(row) > 9 else None,
                'stock_out_purpose': (row[10] or '').strip() or None if len(row) > 10 else None,
                'stock_out_date': row[11] if len(row) > 11 else None,
                'stock_out_department': (row[12] or '').strip() or None if len(row) > 12 else None,
                'stock_out_receiver_name': (row[13] or '').strip() or None if len(row) > 13 else None,
                'quantity_before': int(row[14] or 0) if len(row) > 14 else 0,
                'quantity_after': int(row[15] or 0) if len(row) > 15 else 0,
                'created_at': row[16] if len(row) > 16 else None,
                'performed_by_name': (row[17] or '').strip() or None if len(row) > 17 else None,
                'item_ref': (row[18] or '').strip() if len(row) > 18 else '',
                'item_name': (row[19] or '').strip() if len(row) > 19 else '',
                'item_category': (row[20] or '').strip() if len(row) > 20 else '',
                'measure': (row[21] or '').strip() if len(row) > 21 else '',
                'supplier_name': (row[22] or '').strip() or None if len(row) > 22 else None,
                'supplier_phone': (row[23] or '').strip() or None if len(row) > 23 else None,
            }
        sod = data.get('stock_out_date')
        if sod and hasattr(sod, 'strftime'):
            data['stock_out_date_display'] = sod.strftime('%d %b %Y')
        elif sod:
            data['stock_out_date_display'] = str(sod)
        else:
            data['stock_out_date_display'] = None
        return data
    except Exception as e:
        print(f"_fetch_store_stock_movement_detail: {e}")
        return None


def _grn_document_fields_from_movement(movement):
    """Split invoice, delivery note ref, and free notes for GRN print."""
    movement = movement or {}
    notes = (movement.get('notes') or '').strip()
    delivery_note = (movement.get('delivery_note') or '').strip()
    grn_delivery = ''
    grn_notes = notes
    if notes.upper().startswith('DN: '):
        parts = notes.split('. ', 1)
        grn_delivery = parts[0][4:].strip()
        grn_notes = parts[1].strip() if len(parts) > 1 else ''
    return delivery_note or None, grn_delivery or None, grn_notes or None


def _store_print_date_display(val):
    if val and hasattr(val, 'strftime'):
        return val.strftime('%d %b %Y')
    text = str(val or '').strip()
    return text or '—'


def _store_print_kes_display(val):
    if val is None or val == '':
        return '—'
    try:
        return f'KES {float(val):.2f}'
    except (TypeError, ValueError):
        return '—'


def _store_receive_cert_scope_label(print_scope):
    scope = (print_scope or '').strip().lower()
    if scope == 'pending':
        return 'Items pending receipt'
    if scope == 'line':
        return 'Single line item'
    if scope == 'lines':
        return 'Multiple line items'
    if scope == 'received':
        return 'Goods already received'
    return 'All line items'


def _store_receive_cert_line(line_no, item_name, item_ref='', measure='', quantity='', buying_price=None):
    return {
        'line_no': line_no,
        'item_name': (item_name or '').strip() or '—',
        'item_ref': (item_ref or '').strip(),
        'measure': (measure or '').strip() or '—',
        'quantity': quantity,
        'unit_price_display': _store_print_kes_display(buying_price),
    }


def _store_receive_cert_context_from_movement(
    movement,
    *,
    just_received=False,
    back_url,
    back_label,
    store_manager_name,
    printed_at,
    delivery_to='School store',
):
    invoice, delivery_note, notes = _grn_document_fields_from_movement(movement)
    return {
        'cert_source': 'stock',
        'cert_doc_ref_label': 'Store receipt',
        'cert_doc_ref': (movement.get('reference_number') or '').strip() or '—',
        'cert_order_date_display': _store_print_date_display(movement.get('created_at')),
        'cert_print_scope': 'received',
        'cert_scope_label': _store_receive_cert_scope_label('received'),
        'cert_supplier_name': (movement.get('supplier_name') or '').strip() or '—',
        'cert_supplier_phone': (movement.get('supplier_phone') or '').strip(),
        'cert_delivery_to': (delivery_to or '').strip() or 'School store',
        'cert_invoice_tax_no': (invoice or '').strip(),
        'cert_delivery_note_ref': (delivery_note or '').strip(),
        'cert_notes': (notes or '').strip(),
        'cert_recorded_by': (movement.get('performed_by_name') or '').strip(),
        'cert_lines': [
            _store_receive_cert_line(
                1,
                movement.get('item_name'),
                movement.get('item_ref'),
                movement.get('measure'),
                movement.get('quantity'),
                movement.get('buying_price'),
            )
        ],
        'just_received': just_received,
        'back_url': back_url,
        'back_label': back_label,
        'store_manager_name': store_manager_name,
        'printed_at': printed_at,
    }


def _store_receive_cert_context_from_lpo(
    lpo,
    receive_lines,
    print_scope,
    *,
    just_received=False,
    back_url,
    back_label,
    store_manager_name,
    printed_at,
):
    cert_lines = []
    for ln in receive_lines or []:
        cert_lines.append(_store_receive_cert_line(
            ln.get('line_no') or len(cert_lines) + 1,
            ln.get('item_name'),
            ln.get('item_ref'),
            ln.get('measure'),
            ln.get('quantity'),
            ln.get('buying_price'),
        ))
    return {
        'cert_source': 'lpo',
        'cert_doc_ref_label': 'LPO No.',
        'cert_doc_ref': (lpo.get('serial_number') or '').strip() or '—',
        'cert_order_date_display': _store_print_date_display(lpo.get('lpo_date')),
        'cert_print_scope': (print_scope or 'all').strip().lower(),
        'cert_scope_label': _store_receive_cert_scope_label(print_scope),
        'cert_supplier_name': (lpo.get('supplier_name') or '').strip() or '—',
        'cert_supplier_phone': (lpo.get('supplier_phone') or '').strip(),
        'cert_delivery_to': (lpo.get('delivery_to') or '').strip() or '—',
        'cert_invoice_tax_no': '',
        'cert_delivery_note_ref': '',
        'cert_notes': '',
        'cert_recorded_by': '',
        'cert_lines': cert_lines,
        'just_received': just_received,
        'back_url': back_url,
        'back_label': back_label,
        'store_manager_name': store_manager_name,
        'printed_at': printed_at,
    }


def _resolve_lpo_receive_print_lines(lpo, scope='pending', line_id=None, line_ids=None):
    """Choose LPO lines included on a goods received certificate."""
    scope = (scope or 'pending').strip().lower()
    all_lines = (lpo or {}).get('lines') or []
    receive_lines = []
    print_scope = scope

    if line_ids:
        line_id_set = set(line_ids)
        receive_lines = [
            ln for ln in all_lines if int(ln.get('id') or 0) in line_id_set
        ]
        receive_lines.sort(key=lambda ln: int(ln.get('line_no') or 0))
        print_scope = 'lines' if len(receive_lines) > 1 else 'line'
    elif line_id:
        receive_lines = [ln for ln in all_lines if int(ln.get('id') or 0) == int(line_id)]
        print_scope = 'line'
    elif scope == 'all':
        receive_lines = list(all_lines)
        print_scope = 'all'
    elif scope == 'received':
        receive_lines = [ln for ln in all_lines if _store_lpo_line_received(ln)]
        receive_lines.sort(key=lambda ln: int(ln.get('line_no') or 0))
        print_scope = 'received'
    else:
        receive_lines = [ln for ln in all_lines if not _store_lpo_line_received(ln)]
        print_scope = 'pending'

    if not receive_lines and all_lines:
        status, _, _ = _store_lpo_receipt_status(all_lines)
        if scope == 'received' or status == 'received':
            receive_lines = list(all_lines)
            print_scope = 'received'
        elif scope == 'pending' and status == 'partial':
            receive_lines = [ln for ln in all_lines if not _store_lpo_line_received(ln)]
            if not receive_lines:
                receive_lines = list(all_lines)
                print_scope = 'all'
        elif scope in ('pending', 'all') and status == 'received':
            receive_lines = list(all_lines)
            print_scope = 'received'

    return receive_lines, print_scope


def _render_store_goods_received_certificate(**context):
    return render_template('dashboards/store_goods_received_certificate_print.html', **context)


@app.route('/dashboard/employee/store-stock/grn-print/<int:movement_id>')
@login_required
def store_stock_grn_print(movement_id):
    """Printable goods received note for a stock-in movement (physical sign-off)."""
    from datetime import datetime

    can_print = (
        _can_access_store_manager_portal()
        or _accountant_effective_role() == 'accountant'
    )
    if not can_print:
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    movement = None
    if connection:
        try:
            with connection.cursor() as cursor:
                movement = _fetch_store_stock_movement_detail(cursor, movement_id)
        finally:
            connection.close()

    if not movement:
        flash('Stock record not found.', 'error')
        return redirect(employee_dash_url('store-stock/audits'))
    if (movement.get('movement_type') or '').strip().lower() != 'in':
        flash('Goods received notes are only available for stock-in movements.', 'error')
        return redirect(employee_dash_url('store-stock/audits'))

    store_manager_name = (
        session.get('full_name') or session.get('username') or ''
    ).strip()
    just_received = (request.args.get('received') or '').strip() in ('1', 'true', 'yes')
    school_settings = get_school_settings()
    delivery_to = (
        (school_settings.get('school_name') or '').strip() + ' store'
        if school_settings.get('school_name')
        else 'School store'
    )

    cert_ctx = _store_receive_cert_context_from_movement(
        movement,
        just_received=just_received,
        back_url=employee_dash_url('store-stock') if just_received else employee_dash_url('store-stock/audits'),
        back_label='Back to stock in & out' if just_received else 'Back to audits',
        store_manager_name=store_manager_name,
        printed_at=datetime.now(),
        delivery_to=delivery_to,
    )
    return _render_store_goods_received_certificate(
        school_settings=school_settings,
        **cert_ctx,
    )


