@app.route('/dashboard/employee/books-inventory/class-student-books/<int:level_id>', methods=['GET'])
@app.route('/librarian/books-inventory/class-student-books/<int:level_id>', methods=['GET'])
@login_required
def books_inventory_class_student_books(level_id):
    """Students in a class and the library books currently issued to each."""
    redir = _books_inventory_librarian_guard()
    if redir:
        return jsonify({'ok': False, 'message': 'Permission denied.'}), 403
    connection = get_db_connection()
    if not connection:
        return jsonify({'ok': False, 'message': 'Database connection error.'}), 500
    try:
        with connection.cursor() as cursor:
            ensure_library_books_table(cursor)
            cursor.execute(
                """
                SELECT id AS level_id, UPPER(TRIM(level_category)) AS level_category,
                       UPPER(TRIM(level_name)) AS level_name,
                       UPPER(TRIM(COALESCE(level_code, ''))) AS level_code
                FROM academic_levels
                WHERE id = %s
                  AND COALESCE(level_status, 'active') = 'active'
                """,
                (level_id,),
            )
            row = cursor.fetchone()
            if not row:
                return jsonify({'ok': False, 'message': 'Class not found.'}), 404
            if isinstance(row, dict):
                level = {
                    'level_id': int(row.get('level_id') or row.get('id') or 0),
                    'level_category': (row.get('level_category') or '').strip(),
                    'level_name': (row.get('level_name') or '').strip(),
                    'level_code': (row.get('level_code') or '').strip(),
                }
            else:
                level = {
                    'level_id': int(row[0] or 0),
                    'level_category': (row[1] or '').strip(),
                    'level_name': (row[2] or '').strip(),
                    'level_code': (row[3] or '').strip(),
                }
            rows = _librarian_class_students_with_books(cursor, level_id)
            student_ids = {r.get('student_id') for r in rows if r.get('student_id')}
            books_issued_count = sum(
                1 for r in rows if (r.get('copy_code') or '').strip()
            )
            return jsonify({
                'ok': True,
                'level': level,
                'rows': rows,
                'student_count': len(student_ids),
                'books_issued_count': books_issued_count,
            })
    except Exception as e:
        print(f"books_inventory_class_student_books: {e}")
        return jsonify({'ok': False, 'message': 'Could not load students for this class.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/books-inventory/stock-in', methods=['GET', 'POST'])
@login_required
def books_inventory_stock_in():
    redir = _books_inventory_librarian_guard()
    if redir:
        return redir
    if request.method == 'GET':
        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
    book_id = request.form.get('book_id', type=int)
    level_id = request.form.get('academic_level_id', type=int)
    stock_subject_id = request.form.get('stock_subject_id', type=int)
    quantity = request.form.get('quantity', type=int)
    notes = (request.form.get('notes') or '').strip()
    supplier_phone = (request.form.get('supplier_phone') or '').strip()
    supplier_company = (request.form.get('supplier_company_name') or '').strip()
    buying_price_raw = (request.form.get('buying_price') or '').strip()
    teacher_allocations_raw = request.form.get('teacher_allocations') or ''
    teacher_allocations = _library_parse_teacher_distribution_payload(teacher_allocations_raw)
    if not book_id or not level_id:
        flash('Please select a book and academic level.', 'error')
        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_library_books_table(cursor)
                cursor.execute(
                    """
                    SELECT UPPER(TRIM(academic_category)) AS ac, subject_id
                    FROM library_books WHERE id = %s
                    """,
                    (book_id,),
                )
                br = cursor.fetchone()
                if br:
                    if isinstance(br, dict):
                        ac = br.get('ac')
                        sid = br.get('subject_id')
                    else:
                        ac = br[0] if len(br) > 0 else None
                        sid = br[1] if len(br) > 1 else None
                    if _library_book_needs_librarian_setup(ac, sid):
                        flash(
                            'Complete academic category and subject in the book catalog '
                            '(catalog setup) before allocating to a class.',
                            'error',
                        )
                        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
        except Exception as e:
            print(f"books_inventory_stock_in setup check: {e}")
        finally:
            connection.close()
    if not stock_subject_id:
        flash('Please select the subject this stock-in is linked to.', 'error')
        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
    if not supplier_phone:
        flash('Supplier phone number is required when allocating to a class.', 'error')
        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
    performed_by = session.get('employee_id') or session.get('user_id')
    performed_by_name = session.get('full_name') or session.get('employee_name') or ''
    try:
        with connection.cursor() as cursor:
            supplier_id, supplier_err = _library_upsert_supplier_for_stock_in(
                cursor, supplier_phone, supplier_company,
            )
            if supplier_err:
                connection.rollback()
                flash(supplier_err, 'error')
                return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
            ok, msg, extras = _library_apply_stock_movement(
                cursor, book_id, level_id, 'in', quantity, notes,
                performed_by=performed_by, performed_by_name=performed_by_name,
                supplier_id=supplier_id,
                stock_subject_id=stock_subject_id,
                buying_price=buying_price_raw,
            )
            if ok:
                movement_id = extras.get('movement_id')
                if movement_id and teacher_allocations:
                    dist_ok, dist_err = _library_save_teacher_distributions(
                        cursor,
                        movement_id,
                        book_id,
                        level_id,
                        teacher_allocations,
                        performed_by=performed_by,
                        stock_quantity=quantity,
                    )
                    if not dist_ok:
                        connection.rollback()
                        flash(dist_err or 'Could not save teacher allocations.', 'error')
                        return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')
                connection.commit()
                codes = extras.get('copy_codes') or []
                if codes:
                    session['last_stock_in_labels'] = {
                        'book_id': book_id,
                        'level_id': level_id,
                        'quantity': quantity,
                        'copy_codes': codes,
                    }
                if teacher_allocations:
                    total_dist = sum(a['quantity'] for a in teacher_allocations)
                    msg += f' {total_dist} cop{"ies" if total_dist != 1 else "y"} allocated to teacher(s) for distribution.'
                flash(msg, 'success')
            else:
                connection.rollback()
                flash(msg, 'error')
    except Exception as e:
        connection.rollback()
        print(f"books_inventory_stock_in: {e}")
        flash('Could not allocate copies to class.', 'error')
    finally:
        connection.close()
    return redirect(employee_dash_url('books-inventory/stock') + '?allocate=class')


