@app.route('/dashboard/employee/books-inventory', methods=['GET', 'POST'])
@login_required
def books_inventory():
    """Register and list library books (librarian)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_technician = user_role == 'technician'
    effective = viewing_as_role if is_technician and viewing_as_role else user_role
    if not _can_access_librarian_portal(effective):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    from flask import g
    inventory_view = getattr(g, 'books_inventory_view', 'catalog')
    if request.endpoint == 'books_inventory_stock':
        inventory_view = 'stock'

    academic_categories = []
    subjects_by_category = {}
    books = []
    books_stock = []
    stock_page_meta = {'page': 1, 'pages': 1, 'total': 0, 'per_page': 50}
    inventory_academic_levels = []
    library_levels_by_category = []
    library_level_combinations = []
    library_level_allocation_summary = []
    library_stock_lines = []
    library_stock_movements_recent = []
    library_stock_in_records = []
    library_level_subjects = {}
    library_stock_classes_summary = []
    open_stock_panel = None
    last_stock_in_labels = None
    last_stock_out_labels = None
    books_all = []
    catalog_filter = 'all'
    catalog_counts = {'all': 0, 'setup': 0}
    open_allocate_book_id = None
    allocate_book = None

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return render_template(
            'dashboards/books_inventory.html',
            role=user_role,
            is_technician=is_technician,
            academic_categories=academic_categories,
            subjects_by_category=subjects_by_category,
            books=books,
            books_stock=books_stock,
            stock_page_meta=stock_page_meta,
            library_books_client=[],
            open_edit_book_id=None,
            open_setup_book_id=None,
            inventory_form_open_default=False,
            inventory_academic_levels=[],
            library_levels_by_category=[],
            library_level_combinations=[],
            library_level_allocation_summary=[],
            library_stock_lines=[],
            library_stock_movements_recent=[],
            library_stock_in_records=[],
            library_level_subjects={},
            open_stock_panel=None,
            inventory_view='catalog',
            open_allocate_book_id=None,
            allocate_book=None,
            books_all=books_all,
            catalog_filter=catalog_filter,
            catalog_counts=catalog_counts,
        )

    try:
        with connection.cursor() as cursor:
            ensure_library_books_table(cursor)
            _library_sync_store_department_catalog(cursor)
            connection.commit()

            subjects_by_category = _library_subjects_by_academic_category(cursor)
            academic_categories = sorted(subjects_by_category.keys(), key=lambda x: (x or '').lower())

            if request.method == 'POST':
                book_id_update = request.form.get('book_id', type=int)
                if not book_id_update:
                    flash(
                        'Librarians cannot register new books from this page. '
                        'Ask administration to add titles to the catalog.',
                        'error',
                    )
                    return redirect(employee_dash_url('books-inventory'))
                parsed = _library_validate_librarian_book_update_form(
                    cursor, book_id_update, subjects_by_category,
                )
                if not parsed.get('ok'):
                    flash(parsed.get('message', 'Could not update the book.'), 'error')
                    return redirect(employee_dash_url('books-inventory') + '?edit=%s' % book_id_update)
                try:
                    needs_setup_edit = _library_book_needs_setup_by_id(cursor, book_id_update)
                    if needs_setup_edit is None:
                        flash('Book not found.', 'error')
                        return redirect(employee_dash_url('books-inventory'))
                    if needs_setup_edit:
                        flash(
                            'This title still needs inventory setup. Use Set up to assign category, subject, and levels.',
                            'error',
                        )
                        return redirect(employee_dash_url('books-inventory') + '?setup=%s' % book_id_update)
                    cursor.execute(
                        """
                        UPDATE library_books
                        SET book_category = %s, book_name = %s, description = %s, buying_price = %s,
                            academic_category = %s, subject_id = %s, copies_total = %s
                        WHERE id = %s
                        """,
                        (
                            parsed['book_category'],
                            parsed['book_name'],
                            parsed['description'],
                            parsed['buying_price'],
                            parsed['academic_category'],
                            parsed['subject_id'],
                            parsed['copies_total'],
                            book_id_update,
                        ),
                    )
                    connection.commit()
                    flash('Book updated successfully.', 'success')
                    return redirect(employee_dash_url('books-inventory'))
                except IntegrityError:
                    connection.rollback()
                    flash('Could not save the book (invalid category or subject).', 'error')
                    return redirect(employee_dash_url('books-inventory') + '?edit=%s' % book_id_update)
                except Exception as e:
                    connection.rollback()
                    print(f"books_inventory update: {e}")
                    flash('An error occurred while updating the book.', 'error')
                    return redirect(employee_dash_url('books-inventory') + '?edit=%s' % book_id_update)

            inventory_academic_levels = _library_inventory_academic_levels(cursor)
            library_levels_by_category, library_level_combinations, _lib_combo_member_ids = (
                build_academic_levels_picker_grouping(inventory_academic_levels, cursor)
            )
            library_level_allocation_summary = _library_allocation_stock_by_level(cursor)
            if inventory_view != 'stock':
                library_stock_lines = _library_stock_allocation_lines(cursor, limit=200)
                library_stock_in_records = _library_stock_in_records(cursor, limit=100)
            else:
                library_stock_in_records = _library_stock_in_records(cursor, limit=40)
            library_stock_movements_recent = _library_recent_stock_movements(cursor, limit=20)
            library_level_subjects = _library_subjects_by_level_map(cursor)
            if inventory_view == 'stock':
                library_stock_classes_summary = _librarian_books_stock_classes_summary(cursor)
            catalog_filter = (request.args.get('filter') or 'all').strip().lower()
            if catalog_filter not in ('all', 'setup'):
                catalog_filter = 'all'
            catalog_counts = _fetch_library_catalog_counts(cursor)
            catalog_page_meta = {'page': 1, 'pages': 1, 'total': 0, 'per_page': 50}

            def _library_apply_alloc_qty(book_list):
                for b in book_list:
                    b['allocation_status'] = 'allocated' if b.get('allocated_level_ids') else 'unallocated'
                    qty_by_level = {}
                    for ad in b.get('allocations_detail') or []:
                        try:
                            qty_by_level[int(ad.get('id'))] = max(1, int(ad.get('quantity') or 1))
                        except (TypeError, ValueError):
                            pass
                    b['alloc_qty_by_level'] = qty_by_level

            if inventory_view == 'catalog':
                cat_payload = _fetch_library_books_page(
                    cursor,
                    page=request.args.get('page', 1, type=int),
                    per_page=50,
                    catalog_filter=catalog_filter,
                    q=(request.args.get('q') or '').strip(),
                )
                books = cat_payload['books']
                _library_apply_alloc_qty(books)
                books_all = []
                catalog_page_meta = {
                    'page': cat_payload['page'],
                    'pages': cat_payload['pages'],
                    'total': cat_payload['total'],
                    'per_page': cat_payload['per_page'],
                }
            else:
                stock_payload = _fetch_library_books_page(
                    cursor,
                    page=request.args.get('page', 1, type=int),
                    per_page=50,
                    catalog_filter='all',
                    q=(request.args.get('q') or '').strip(),
                    ready_only=True,
                )
                books_stock = stock_payload['books']
                for b in books_stock:
                    b['available_to_allocate'] = _library_book_available_to_allocate(b)
                stock_page_meta = {
                    'page': stock_payload['page'],
                    'pages': stock_payload['pages'],
                    'total': stock_payload['total'],
                    'per_page': stock_payload['per_page'],
                }
                books = []
                books_all = []
                library_stock_lines = []
    except Exception as e:
        print(f"books_inventory: {e}")
        flash('Could not load the book inventory.', 'error')
        books = []
        books_stock = []
        stock_page_meta = {'page': 1, 'pages': 1, 'total': 0, 'per_page': 50}
        catalog_filter = 'all'
        catalog_counts = {'all': 0, 'setup': 0}
        catalog_page_meta = {'page': 1, 'pages': 1, 'total': 0, 'per_page': 50}
    finally:
        connection.close()

    open_edit_book_id = request.args.get('edit', type=int) if request.method == 'GET' else None
    if open_edit_book_id is not None and request.method == 'GET':
        conn_bk = get_db_connection()
        bk_found = False
        if conn_bk:
            try:
                with conn_bk.cursor() as cb:
                    ensure_library_books_table(cb)
                    cb.execute('SELECT id FROM library_books WHERE id = %s', (open_edit_book_id,))
                    bk_found = bool(cb.fetchone())
            finally:
                conn_bk.close()
        if not bk_found:
            flash('Book not found.', 'error')
            open_edit_book_id = None
    open_setup_book_id = request.args.get('setup', type=int) if request.method == 'GET' else None
    if open_setup_book_id is not None and request.method == 'GET':
        conn_bk2 = get_db_connection()
        bk2_found = False
        if conn_bk2:
            try:
                with conn_bk2.cursor() as cb2:
                    ensure_library_books_table(cb2)
                    cb2.execute('SELECT id FROM library_books WHERE id = %s', (open_setup_book_id,))
                    bk2_found = bool(cb2.fetchone())
            finally:
                conn_bk2.close()
        if not bk2_found:
            flash('Book not found.', 'error')
            open_setup_book_id = None

    open_allocate_book_id = request.args.get('book', type=int) if request.method == 'GET' and inventory_view == 'stock' else None
    if open_allocate_book_id is not None and request.method == 'GET' and inventory_view == 'stock':
        conn_bk3 = get_db_connection()
        alloc_bk_found = False
        if conn_bk3:
            try:
                with conn_bk3.cursor() as cb3:
                    ensure_library_books_table(cb3)
                    cb3.execute('SELECT id FROM library_books WHERE id = %s', (open_allocate_book_id,))
                    alloc_bk_found = bool(cb3.fetchone())
            finally:
                conn_bk3.close()
        if not alloc_bk_found:
            flash('Book not found.', 'error')
            open_allocate_book_id = None

    allocate_book = None
    if open_allocate_book_id and books_stock:
        for _ab in books_stock:
            if _ab.get('id') == open_allocate_book_id:
                allocate_book = _ab
                break
    if open_allocate_book_id and not allocate_book:
        conn_ab = get_db_connection()
        if conn_ab:
            try:
                with conn_ab.cursor() as cab:
                    cab.execute(
                        """
                        SELECT lb.id, lb.book_category, lb.book_name, lb.description, lb.buying_price,
                               lb.library_status, lb.allocation_status, lb.copies_total, lb.created_at,
                               lb.academic_category, lb.subject_id, lb.store_item_id,
                               s.subject_name, s.subject_code
                        FROM library_books lb
                        LEFT JOIN subjects s ON s.id = lb.subject_id
                        WHERE lb.id = %s
                        """,
                        (open_allocate_book_id,),
                    )
                    row = cab.fetchone()
                    if row:
                        allocate_book = _library_book_dict_from_row(row)
                        _library_enrich_books_with_allocations(cab, [allocate_book])
                        _library_enrich_books_store_quantity(cab, [allocate_book])
                        allocate_book['available_to_allocate'] = _library_book_available_to_allocate(allocate_book)
            finally:
                conn_ab.close()

    library_books_client = (
        [_library_book_client_dict(b) for b in books_all] if books_all else []
    )
    if request.method == 'GET' and inventory_view == 'stock':
        stock_q = (request.args.get('allocate') or request.args.get('stock') or '').strip().lower()
        if stock_q in ('class', 'in'):
            open_stock_panel = 'in'
        elif stock_q in ('teacher', 'out'):
            open_stock_panel = 'out'
        if open_allocate_book_id:
            open_stock_panel = None

    def _enrich_last_stock_labels(payload):
        if not payload:
            return payload
        bid = payload.get('book_id')
        lid = payload.get('level_id')
        payload = dict(payload)
        for b in books_stock or []:
            if b.get('id') == bid:
                payload['book_name'] = b.get('book_name') or ''
                break
        for lvl in inventory_academic_levels or []:
            if lvl.get('id') == lid:
                payload['level_name'] = lvl.get('level_name') or ''
                payload['level_category'] = lvl.get('level_category') or ''
                break
        if not payload.get('book_name') or not payload.get('level_name'):
            for ln in library_stock_lines or []:
                if ln.get('book_id') == bid and ln.get('level_id') == lid:
                    payload['book_name'] = payload.get('book_name') or ln.get('book_name') or ''
                    payload['level_name'] = payload.get('level_name') or ln.get('level_name') or ''
                    payload['level_category'] = payload.get('level_category') or ln.get('level_category') or ''
                    break
        return payload

    last_stock_in_labels = _enrich_last_stock_labels(session.pop('last_stock_in_labels', None))
    last_stock_out_labels = _enrich_last_stock_labels(session.pop('last_stock_out_labels', None))
    inventory_form_open_default = False

    return render_template(
        'dashboards/books_inventory.html',
        role=user_role,
        is_technician=is_technician,
        academic_categories=academic_categories,
        subjects_by_category=subjects_by_category,
        books=books,
        books_stock=books_stock,
        stock_page_meta=stock_page_meta,
        books_all=books_all,
        catalog_filter=catalog_filter,
        catalog_counts=catalog_counts,
        catalog_page_meta=catalog_page_meta,
        library_books_client=library_books_client,
        open_edit_book_id=open_edit_book_id,
        open_setup_book_id=open_setup_book_id,
        open_allocate_book_id=open_allocate_book_id,
        allocate_book=allocate_book,
        inventory_form_open_default=False,
        inventory_academic_levels=inventory_academic_levels,
        library_levels_by_category=library_levels_by_category,
        library_level_combinations=library_level_combinations,
        library_level_allocation_summary=library_level_allocation_summary,
        library_stock_lines=library_stock_lines,
        library_stock_movements_recent=library_stock_movements_recent,
        library_stock_in_records=library_stock_in_records,
        library_level_subjects=library_level_subjects,
        library_stock_classes_summary=library_stock_classes_summary,
        open_stock_panel=open_stock_panel,
        inventory_view=inventory_view,
        last_stock_in_labels=last_stock_in_labels,
        last_stock_out_labels=last_stock_out_labels,
    )


@app.route('/dashboard/employee/store-inventory/items', methods=['GET'])
@login_required
def store_inventory_items_api():
    if not _can_access_store_manager_portal():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 50, type=int)
    q = (request.args.get('q') or '').strip()
    department_station = ''
    dept_id = request.args.get('department', type=int)
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500
    try:
        with connection.cursor() as cursor:
            if dept_id:
                dept_row = _fetch_store_department_by_id(cursor, dept_id)
                if dept_row:
                    department_station = dept_row.get('department_name') or ''
            payload = _fetch_store_inventory_page(
                cursor, page=page, per_page=per_page, q=q, department_station=department_station
            )
        client_items = [_store_inventory_client_item(it) for it in payload['items']]
        return jsonify({
            'success': True,
            'items': client_items,
            'meta': {
                'page': payload['page'],
                'per_page': payload['per_page'],
                'total': payload['total'],
                'pages': payload['pages'],
            },
        })
    except Exception as e:
        print(f"store_inventory_items_api: {e}")
        return jsonify({'success': False, 'message': 'Could not load items'}), 500
    finally:
        connection.close()


