@app.route('/dashboard/employee/store-inventory/<int:item_id>/delete', methods=['POST'])
@login_required
def store_inventory_delete(item_id):
    redir = _store_inventory_guard()
    if redir:
        return redir
    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(employee_dash_url('store-inventory'))
    try:
        with connection.cursor() as cursor:
            ensure_store_inventory_items_table(cursor)
            ensure_library_books_table(cursor)
            cursor.execute(
                """
                SELECT image_path, library_book_id
                FROM store_inventory_items WHERE id = %s
                """,
                (item_id,),
            )
            row = cursor.fetchone()
            image_path = None
            library_book_id = None
            if row:
                if isinstance(row, dict):
                    image_path = row.get('image_path')
                    library_book_id = int(row.get('library_book_id') or 0) or None
                else:
                    image_path = row[0] if len(row) > 0 else None
                    library_book_id = int(row[1] or 0) or None if len(row) > 1 else None
            if library_book_id:
                cursor.execute("DELETE FROM library_books WHERE id = %s", (library_book_id,))
            cursor.execute("DELETE FROM store_inventory_items WHERE id = %s", (item_id,))
            connection.commit()
            if image_path:
                _delete_store_item_image_file(image_path)
            flash('Store item removed from inventory.', 'success')
    except Exception as e:
        print(f"store_inventory_delete: {e}")
        connection.rollback()
        flash('Could not delete the store item.', 'error')
    finally:
        connection.close()
    return redirect(employee_dash_url('store-inventory'))


