@app.route('/dashboard/employee/store-inventory', methods=['GET', 'POST'])
@login_required
def store_inventory():
    """Register and manage school store inventory items (store manager)."""
    if not _can_access_store_manager_portal():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    user_role = session.get('role', '').lower()
    is_technician = user_role == 'technician'
    items = []
    category_suggestions = []
    fee_structure_votes = []
    items_q = (request.args.get('q') or '').strip() if request.method == 'GET' else ''
    items_department_id = request.args.get('department', type=int) if request.method == 'GET' else None
    items_department = None
    items_total = 0
    items_page = 1
    items_pages = 1
    inventory_summary = {
        'total_items': 0,
        'units_on_hand': 0,
        'suspended_count': 0,
        'low_stock_count': 0,
    }
    department_stations = []

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        dept_conn = get_db_connection()
        if dept_conn:
            try:
                with dept_conn.cursor() as dept_cursor:
                    department_stations = _load_store_department_station_options(dept_cursor, dept_conn)
            except Exception as dept_err:
                print(f"store_inventory departments fallback: {dept_err}")
            finally:
                dept_conn.close()
        return render_template(
            'dashboards/store_inventory.html',
            role=user_role,
            is_technician=is_technician,
            items=items,
            store_items_client=[],
            category_suggestions=category_suggestions,
            fee_structure_votes=fee_structure_votes,
            measures=list(STORE_ITEM_MEASURES),
            department_stations=department_stations,
            open_edit_item_id=None,
            inventory_form_open_default=False,
            items_q=items_q,
            items_department_id=items_department_id,
            items_department=items_department,
            items_total=items_total,
            items_page=items_page,
            items_pages=items_pages,
            inventory_summary=inventory_summary,
        )

    try:
        with connection.cursor() as cursor:
            ensure_store_inventory_items_table(cursor)
            connection.commit()
            department_stations = _load_store_department_station_options(cursor, connection)

            if request.method == 'POST':
                item_id_update = request.form.get('item_id', type=int)
                item_category = (request.form.get('item_category') or '').strip()[:120].upper()
                item_name = (request.form.get('item_name') or '').strip()[:255].upper()
                desc_raw = (request.form.get('description') or '').strip()
                description = desc_raw.upper() if desc_raw else None
                measure = (request.form.get('measure') or '').strip().upper()
                if measure not in STORE_ITEM_MEASURES:
                    measure = ''
                department_station = _normalize_store_department_station(
                    request.form.get('department_station'),
                    cursor=cursor,
                )

                if not item_category or not item_name:
                    flash('Expense category and item name are required.', 'error')
                    if item_id_update:
                        return redirect(employee_dash_url('store-inventory') + '?edit=%s' % item_id_update)
                elif not item_id_update and not _is_valid_store_expense_category(cursor, item_category):
                    flash(
                        'Please select a valid expense category registered '
                        'in Student fees → Fee structures.',
                        'error',
                    )
                elif not department_station:
                    flash('Please select a department station for this item.', 'error')
                    if item_id_update:
                        return redirect(employee_dash_url('store-inventory') + '?edit=%s' % item_id_update)
                elif not measure:
                    flash('Please select a valid measure.', 'error')
                    if item_id_update:
                        return redirect(employee_dash_url('store-inventory') + '?edit=%s' % item_id_update)
                elif item_id_update:
                    try:
                        ensure_library_books_table(cursor)
                        cursor.execute(
                            """
                            SELECT id, image_path, department_station, library_book_id, item_category
                            FROM store_inventory_items WHERE id = %s
                            """,
                            (item_id_update,),
                        )
                        existing = cursor.fetchone()
                        if not existing:
                            flash('Store item not found.', 'error')
                            return redirect(employee_dash_url('store-inventory'))
                        if isinstance(existing, dict):
                            old_image = existing.get('image_path')
                            old_station = (existing.get('department_station') or '').strip().upper()
                            library_book_id = int(existing.get('library_book_id') or 0) or None
                            existing_category = (existing.get('item_category') or '').strip().upper()
                        else:
                            old_image = existing[1] if len(existing) > 1 else None
                            old_station = ((existing[2] or '') if len(existing) > 2 else '').strip().upper()
                            library_book_id = int(existing[3] or 0) or None if len(existing) > 3 else None
                            existing_category = ((existing[4] or '') if len(existing) > 4 else '').strip().upper()
                        if not _is_valid_store_expense_category(
                            cursor,
                            item_category,
                            extra_allowed=[existing_category],
                        ):
                            flash(
                                'Please select a valid expense category registered '
                                'in Student fees → Fee structures.',
                                'error',
                            )
                            return redirect(employee_dash_url('store-inventory') + '?edit=%s' % item_id_update)
                        new_image = _save_store_item_image(request.files.get('image'))
                        image_path = new_image if new_image else old_image
                        cursor.execute(
                            """
                            UPDATE store_inventory_items
                            SET item_category = %s, item_name = %s, description = %s,
                                measure = %s, image_path = %s, department_station = %s
                            WHERE id = %s
                            """,
                            (
                                item_category,
                                item_name,
                                description,
                                measure,
                                image_path,
                                department_station,
                                item_id_update,
                            ),
                        )
                        if _store_station_is_library(department_station):
                            if not library_book_id:
                                library_book_id = _create_library_book_for_store_item(
                                    cursor,
                                    item_id_update,
                                    item_category,
                                    item_name,
                                    description,
                                )
                            else:
                                _sync_linked_library_book_from_store_item(
                                    cursor,
                                    library_book_id,
                                    item_category,
                                    item_name,
                                    description,
                                )
                        elif library_book_id:
                            _sync_linked_library_book_from_store_item(
                                cursor,
                                library_book_id,
                                item_category,
                                item_name,
                                description,
                            )
                        connection.commit()
                        if new_image and old_image and old_image != new_image:
                            _delete_store_item_image_file(old_image)
                        flash('Store item updated successfully.', 'success')
                        return redirect(employee_dash_url('store-inventory'))
                    except Exception as e:
                        connection.rollback()
                        print(f"store_inventory update: {e}")
                        flash('An error occurred while updating the store item.', 'error')
                        return redirect(employee_dash_url('store-inventory') + '?edit=%s' % item_id_update)
                else:
                    result = _register_store_inventory_item_from_request(cursor, request)
                    if result.get('ok'):
                        connection.commit()
                        flash(result['message'], 'success')
                        return redirect(employee_dash_url('store-inventory'))
                    flash(result.get('message', 'Could not register the store item.'), 'error')

            items_q = (request.args.get('q') or '').strip() if request.method == 'GET' else ''
            items_department_id = request.args.get('department', type=int) if request.method == 'GET' else None
            items_department = None
            if items_department_id:
                items_department = _fetch_store_department_by_id(cursor, items_department_id)
                if not items_department:
                    items_department_id = None
            items_page_num = max(1, request.args.get('page', 1, type=int) or 1) if request.method == 'GET' else 1
            page_payload = _fetch_store_inventory_page(
                cursor,
                page=items_page_num,
                per_page=50,
                q=items_q,
                department_station=(items_department or {}).get('department_name') or '',
            )
            items = page_payload.get('items') or []
            category_suggestions = _fetch_store_expense_categories(cursor)
            fee_structure_votes = _fetch_store_expense_category_picker_votes(cursor)
            seen_cats = set(category_suggestions)
            cursor.execute("""
                SELECT DISTINCT TRIM(item_category) AS item_category
                FROM store_inventory_items
                WHERE COALESCE(TRIM(item_category), '') != ''
                ORDER BY item_category ASC
            """)
            for r in cursor.fetchall() or []:
                legacy_cat = (r.get('item_category') if isinstance(r, dict) else r[0]) or ''
                legacy_cat = str(legacy_cat).strip().upper()
                if legacy_cat and legacy_cat not in seen_cats:
                    seen_cats.add(legacy_cat)
                    category_suggestions.append(legacy_cat)
            category_suggestions.sort(key=lambda x: x.lower())
            items_total = int(page_payload.get('total') or 0)
            items_page = int(page_payload.get('page') or 1)
            items_pages = int(page_payload.get('pages') or 1)
            inventory_summary = _fetch_store_inventory_summary(cursor)
    except Exception as e:
        print(f"store_inventory: {e}")
        flash('An error occurred loading store inventory.', 'error')
        if not department_stations and connection:
            try:
                with connection.cursor() as dept_cursor:
                    department_stations = _load_store_department_station_options(dept_cursor, connection)
            except Exception as dept_err:
                print(f"store_inventory departments recovery: {dept_err}")
    finally:
        connection.close()

    open_edit_item_id = request.args.get('edit', type=int) if request.method == 'GET' else None
    if open_edit_item_id is not None and request.method == 'GET':
        conn_chk = get_db_connection()
        found = False
        if conn_chk:
            try:
                with conn_chk.cursor() as cchk:
                    ensure_store_inventory_items_table(cchk)
                    cchk.execute('SELECT id FROM store_inventory_items WHERE id = %s', (open_edit_item_id,))
                    found = bool(cchk.fetchone())
            finally:
                conn_chk.close()
        if not found:
            flash('Store item not found.', 'error')
            open_edit_item_id = None

    store_items_client = [_store_inventory_client_item(it) for it in items]
    inventory_form_open_default = bool(
        request.method == 'POST' and not request.form.get('item_id', type=int)
    )

    return render_template(
        'dashboards/store_inventory.html',
        role=user_role,
        is_technician=is_technician,
        items=items,
        store_items_client=store_items_client,
        category_suggestions=category_suggestions,
        fee_structure_votes=fee_structure_votes,
        measures=list(STORE_ITEM_MEASURES),
        department_stations=department_stations,
        open_edit_item_id=open_edit_item_id,
        inventory_form_open_default=inventory_form_open_default,
        items_q=items_q,
        items_department_id=items_department_id,
        items_department=items_department,
        items_total=items_total,
        items_page=items_page,
        items_pages=items_pages,
        inventory_summary=inventory_summary,
    )


@app.route('/dashboard/employee/store-stock/supplier-lookup', methods=['GET'])
@login_required
def store_stock_supplier_lookup():
    """Live lookup of store supplier by phone (stock in)."""
    redir = _store_inventory_guard()
    if redir:
        return jsonify({'ok': False, 'found': False, 'message': 'Permission denied.'}), 403
    phone_raw = (request.args.get('phone') or '').strip()
    norm = _normalize_store_supplier_phone(phone_raw)
    if not norm:
        return jsonify({
            'ok': True,
            'found': False,
            'ready': False,
            'message': 'Enter a valid phone number (at least 9 digits).',
        })
    connection = get_db_connection()
    if not connection:
        return jsonify({'ok': False, 'found': False, 'message': 'Database connection error.'}), 500
    try:
        with connection.cursor() as cursor:
            supplier = _store_lookup_supplier_by_phone(cursor, norm)
            if supplier:
                return jsonify({
                    'ok': True,
                    'found': True,
                    'ready': True,
                    'supplier_id': supplier['id'],
                    'phone': supplier['phone'],
                    'company_name': supplier['company_name'],
                    'message': 'Supplier found — name filled in.',
                })
            return jsonify({
                'ok': True,
                'found': False,
                'ready': True,
                'phone': norm,
                'message': 'New supplier — enter the supplier name.',
            })
    except Exception as e:
        print(f"store_stock_supplier_lookup: {e}")
        return jsonify({'ok': False, 'found': False, 'message': 'Could not look up supplier.'}), 500
    finally:
        connection.close()


