@app.route('/dashboard/employee/exams-assessments')
@login_required
def exams_assessments():
    """Exams & Assessments page.

    - Coordinators/principals/secretary: see all academic levels.
    - Teachers: see only allocated classes (and their subjects).
    """
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    if not (is_teacher or is_academic_coordinator or is_technician or is_principal or is_secretary):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    # Teacher view: reuse the same allocated-only dataset as `/teachers/exams-assessments`.
    # This keeps existing sidebar links (`employee_dash_url('exams-assessments')`) working for teachers.
    if is_teacher:
        return teacher_exams_assessments()
    
    # Fetch all registered academic levels
    academic_levels = []
    connection = get_db_connection()
    
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description, level_status
                    FROM academic_levels
                    ORDER BY level_category, level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                
                for row in academic_levels_results:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2],
                        'level_description': row.get('level_description', '') if isinstance(row, dict) else row[3],
                        'level_status': row.get('level_status', 'active') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'active')
                    })
        except Exception as e:
            print(f"Error fetching academic levels: {e}")
        finally:
            connection.close()
    
    return render_template('dashboards/exams_assessments.html', role=user_role, academic_levels=academic_levels)


@app.route('/teachers/exam-analytics')
@login_required
def teacher_exam_analytics():
    """Teacher URL alias for exam analytics (same view as coordinators)."""
    return exam_analytics()


@app.route('/teachers/exams-assessments')
@login_required
def teacher_exams_assessments():
    """Teacher view of Exams & Assessments: show only allocated classes/subjects with students in session."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    is_technician = user_role == 'technician'
    if not (is_teacher or is_technician):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    # Resolve teacher employee PK (employees.id)
    teacher_id = None
    if user_role in ('teachers', 'teacher'):
        teacher_id = session.get('user_id')
    elif is_technician and viewing_as_role in ('teachers', 'teacher'):
        teacher_id = session.get('viewing_as_employee_id')

    if not teacher_id:
        flash('Teacher profile not selected.', 'error')
        return redirect(employee_dashboard_path())

    # Build the same `academic_levels` structure the template expects, but scoped to this teacher.
    # Each level additionally includes `subjects`: [{id, subject_name, subject_code}, ...]
    academic_levels = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                # Only levels allocated to this teacher, and only those with at least one student "in session"
                # (students.current_grade matches academic_levels.level_name).
                #
                # Also include allocated subjects per level so the page can show "classes and subjects".
                cursor.execute("""
                    SELECT
                        al.id AS level_id,
                        al.level_category,
                        al.level_name,
                        al.level_description,
                        al.level_status,
                        s.id AS subject_id,
                        s.subject_name,
                        s.subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE tsa.teacher_id = %s
                      AND COALESCE(al.level_status, 'active') = 'active'
                      AND COALESCE(s.status, 'active') = 'active'
                    ORDER BY al.level_category, al.level_name, s.subject_name
                """, (int(teacher_id),))

                rows = cursor.fetchall() or []
                levels_by_id = {}
                for r in rows:
                    if isinstance(r, dict):
                        level_id = r.get('level_id')
                        subject_id = r.get('subject_id')
                        subject_name = r.get('subject_name')
                        subject_code = r.get('subject_code')
                        if level_id not in levels_by_id:
                            levels_by_id[level_id] = {
                                'id': level_id,
                                'level_category': r.get('level_category', ''),
                                'level_name': r.get('level_name', ''),
                                'level_description': r.get('level_description', ''),
                                'level_status': r.get('level_status', 'active'),
                                'subjects': [],
                            }
                        if subject_id is not None:
                            levels_by_id[level_id]['subjects'].append({
                                'id': subject_id,
                                'subject_name': subject_name or '',
                                'subject_code': subject_code or '',
                            })
                    else:
                        # (level_id, level_category, level_name, level_description, level_status, subject_id, subject_name, subject_code)
                        level_id = r[0] if len(r) > 0 else None
                        if level_id is None:
                            continue
                        if level_id not in levels_by_id:
                            levels_by_id[level_id] = {
                                'id': level_id,
                                'level_category': r[1] if len(r) > 1 else '',
                                'level_name': r[2] if len(r) > 2 else '',
                                'level_description': r[3] if len(r) > 3 else '',
                                'level_status': r[4] if len(r) > 4 else 'active',
                                'subjects': [],
                            }
                        subject_id = r[5] if len(r) > 5 else None
                        if subject_id is not None:
                            levels_by_id[level_id]['subjects'].append({
                                'id': subject_id,
                                'subject_name': r[6] if len(r) > 6 and r[6] else '',
                                'subject_code': r[7] if len(r) > 7 and r[7] else '',
                            })

                for lev in levels_by_id.values():
                    seen_sid = set()
                    uniq = []
                    for s in lev.get('subjects') or []:
                        sid = s.get('id')
                        if sid is None or sid in seen_sid:
                            continue
                        seen_sid.add(sid)
                        uniq.append(s)
                    lev['subjects'] = uniq

                # Preserve ordering from SQL by iterating rows and building list once per new level.
                seen = set()
                for r in rows:
                    lid = r.get('level_id') if isinstance(r, dict) else (r[0] if len(r) > 0 else None)
                    if lid is None or lid in seen:
                        continue
                    seen.add(lid)
                    academic_levels.append(levels_by_id[lid])
        except Exception as e:
            print(f"Error fetching teacher allocated academic levels: {e}")
        finally:
            connection.close()

    # Render the same UI, but scoped to teacher allocations.
    return render_template('dashboards/exams_assessments.html', role=user_role, academic_levels=academic_levels)


def _enrich_timetable_days_exam_groups(timetable_by_date):
    """Add ``day_period`` on each slot and ``exam_groups``: slots with the same ``exam_name`` grouped per day."""
    from collections import OrderedDict

    if not timetable_by_date:
        return timetable_by_date
    enriched = []
    for day in timetable_by_date:
        raw_slots = list(day.get('slots') or [])
        slots_sorted = sorted(
            raw_slots,
            key=lambda s: (
                s.get('start_time') or '99:99',
                s.get('session_type') or '',
                s.get('level_name') or '',
                s.get('id') or 0,
            ),
        )
        slots_with_period = []
        for i, s in enumerate(slots_sorted, start=1):
            sc = dict(s) if isinstance(s, dict) else s
            if isinstance(sc, dict):
                sc['day_period'] = i
            slots_with_period.append(sc)
        od = OrderedDict()
        for s in slots_with_period:
            key = (s.get('exam_name') or '').strip() or '—'
            if key not in od:
                od[key] = {
                    'exam_name': s.get('exam_name') or '—',
                    'exam_is_locked': bool(s.get('exam_is_locked')),
                    'slots': [],
                }
            if s.get('exam_is_locked'):
                od[key]['exam_is_locked'] = True
            od[key]['slots'].append(s)
        enriched.append({
            **day,
            'slots': slots_with_period,
            'exam_groups': list(od.values()),
        })
    return enriched


def _session_exam_timetable_supervisor_scope():
    """If True, timetable rows are limited to exams the signed-in teacher supervises.

    Uses ``exams.supervisor_id`` or ``exam_supervisors`` (see timetable bundle). Returns
    ``(restrict_to_supervisor: bool, supervisor_employees_id: int|None)``.
    ``supervisor_employees_id`` is ``employees.id`` (same as ``session['user_id']`` for teachers).
    """
    ur = (session.get('role') or '').lower()
    var = (session.get('viewing_as_employee_role') or '').lower()
    if ur in ('teachers', 'teacher'):
        uid = session.get('user_id')
        try:
            return True, int(uid) if uid is not None else None
        except (TypeError, ValueError):
            return True, None
    if ur == 'technician' and var in ('teachers', 'teacher'):
        vid = session.get('viewing_as_employee_id')
        try:
            return True, int(vid) if vid is not None else None
        except (TypeError, ValueError):
            return True, None
    return False, None


_EXAM_EG_MATRIX_SESSION_ORDER = ('MORNING', 'MIDDAY', 'AFTERNOON', 'EVENING', 'CUSTOM', '__OTHER__')


def _exam_eg_summary_matrix(summary_rows):
    """Build ``{cols, days}`` for date × session timetables on Exams & Grades.

    Each row needs ``exam_date`` (YYYY-MM-DD or empty), ``session_key`` (e.g. MORNING), plus labels for rendering.
    """
    if not summary_rows:
        return {'cols': [], 'days': []}
    rows = list(summary_rows)
    keys_seen = set()
    for r in rows:
        sk = r.get('session_key') or '__OTHER__'
        sk = sk.strip().upper() if isinstance(sk, str) else '__OTHER__'
        keys_seen.add(sk or '__OTHER__')

    cols = [k for k in _EXAM_EG_MATRIX_SESSION_ORDER if k in keys_seen]
    for k in sorted(keys_seen):
        if k not in cols:
            cols.append(k)

    date_set = {(r.get('exam_date') or '') for r in rows}
    dated = sorted([d for d in date_set if d])
    if '' in date_set:
        dated.append('')

    days_out = []
    for dk in dated:
        dr = [r for r in rows if (r.get('exam_date') or '') == dk]
        if not dr:
            continue
        weekday = dr[0].get('weekday') or ''
        date_heading = dr[0].get('date_heading') or '—'
        cells = {c: [] for c in cols}
        for r in dr:
            sk = r.get('session_key') or '__OTHER__'
            sk = sk.strip().upper() if isinstance(sk, str) else '__OTHER__'
            sk = sk or '__OTHER__'
            if sk not in cells:
                cells[sk] = []
            cells[sk].append(r)
        days_out.append({
            'exam_date': dk,
            'weekday': weekday,
            'date_heading': date_heading,
            'cells': cells,
        })

    return {'cols': cols, 'days': days_out}


def _compute_exams_assessments_timetable_bundle(
    supervisor_employee_id=None,
    restrict_to_supervisor=False,
    teacher_assignments_employee_id=None,
):
    """Build exams timetable data from ``request.args`` (full page or ``live=1`` AJAX).

    When ``restrict_to_supervisor`` is True, only exams supervised by ``supervisor_employee_id`` are included:
    ``exams.supervisor_id`` **or** a matching row in ``exam_supervisors`` (same logic as the teacher dashboard
    supervision counts). Used for exams-and-grades and timetable API calls when scoped as teacher.

    When ``teacher_assignments_employee_id`` is set (same employee as the teacher in session), also returns
    ``teacher_assignment_exam_rows``: exams for subject/class combinations from ``teacher_subject_assignments``,
    with allocated supervisors listed — for the “my subjects & who supervises” panel on Exams & Grades.
    """
    def _coerce_str(v):
        if v is None:
            return ''
        if isinstance(v, (bytes, bytearray)):
            return v.decode('utf-8', errors='replace').strip()
        if isinstance(v, (int, float)) and not isinstance(v, bool):
            return str(v)
        return (str(v) or '').strip()

    def _format_time_value(raw_value):
        if raw_value is None:
            return ''
        if isinstance(raw_value, (bytes, bytearray)):
            raw_value = raw_value.decode('utf-8', errors='replace').strip()
            if not raw_value:
                return ''
        if not raw_value:
            return ''
        if isinstance(raw_value, timedelta):
            seconds = int(raw_value.total_seconds())
            return f"{seconds // 3600:02d}:{(seconds % 3600) // 60:02d}"
        if hasattr(raw_value, 'strftime'):
            return raw_value.strftime('%H:%M')
        s = str(raw_value).strip()
        return s[:5] if len(s) >= 5 else s

    def _format_date_value(raw_value):
        if raw_value is None:
            return ''
        if isinstance(raw_value, (bytes, bytearray)):
            raw_value = raw_value.decode('utf-8', errors='replace').strip()
            if not raw_value:
                return ''
        if not raw_value:
            return ''
        if hasattr(raw_value, 'strftime'):
            return raw_value.strftime('%Y-%m-%d')
        s = str(raw_value).strip()
        return s[:10] if len(s) >= 10 else s

    selected_exam_name = (request.args.get('exam_name') or '').strip()
    explicit_live = str(request.args.get('live', '')).lower() in ('1', 'true', 'yes')
    raw_class_id = request.args.get('class_id', '')
    try:
        selected_class_id = int(str(raw_class_id).strip()) if str(raw_class_id).strip() != '' else 0
    except (ValueError, TypeError):
        selected_class_id = 0

    show_all_flag = str(request.args.get('show_all', '')).lower() in ('1', 'true', 'yes')

    def _int_form_arg(param_name):
        if param_name not in request.args:
            return None
        raw = request.args.get(param_name, '')
        if raw is None or str(raw).strip() == '':
            return 0
        try:
            return int(raw)
        except (TypeError, ValueError):
            return 0

    if explicit_live:
        # AJAX: explicit year/term (0 = no filter); never auto-pick current year unless client sends defaults.
        show_all = show_all_flag
        if show_all:
            selected_year_id = 0
            selected_term_id = 0
            default_year_term_from_cursor = False
            infer_term_for_year = False
            infer_year_for_term = False
        else:

            def _int_live(qname):
                if qname not in request.args:
                    return 0
                raw = request.args.get(qname, '')
                if raw is None or str(raw).strip() == '':
                    return 0
                try:
                    return int(raw)
                except (ValueError, TypeError):
                    return 0

            selected_year_id = _int_live('academic_year_id')
            selected_term_id = _int_live('term_id')
            yr_missing = (
                'academic_year_id' not in request.args
                or str(request.args.get('academic_year_id', '')).strip() == ''
            )
            tm_missing = (
                'term_id' not in request.args or str(request.args.get('term_id', '')).strip() == ''
            )
            default_year_term_from_cursor = False
            infer_term_for_year = bool(selected_year_id > 0 and tm_missing)
            infer_year_for_term = bool(selected_term_id > 0 and yr_missing)
    else:
        show_all = show_all_flag
        # Bare visit → current unlocked academic year & term ("is_current"). Explicit ?show_all=1 → no year/term filter.
        # Submitted filters always send both query keys so we distinguish first load from "All years/terms" clears.
        if show_all:
            selected_year_id = 0
            selected_term_id = 0
            default_year_term_from_cursor = False
            infer_term_for_year = False
            infer_year_for_term = False
        elif 'academic_year_id' not in request.args and 'term_id' not in request.args:
            selected_year_id = None
            selected_term_id = None
            default_year_term_from_cursor = True
            infer_term_for_year = False
            infer_year_for_term = False
        elif 'academic_year_id' in request.args and 'term_id' not in request.args:
            selected_year_id = _int_form_arg('academic_year_id')
            selected_term_id = None
            default_year_term_from_cursor = False
            infer_term_for_year = bool(selected_year_id and selected_year_id > 0)
            infer_year_for_term = False
        elif 'term_id' in request.args and 'academic_year_id' not in request.args:
            selected_year_id = None
            selected_term_id = _int_form_arg('term_id')
            default_year_term_from_cursor = False
            infer_term_for_year = False
            infer_year_for_term = bool(selected_term_id and selected_term_id > 0)
        else:
            selected_year_id = _int_form_arg('academic_year_id')
            selected_term_id = _int_form_arg('term_id')
            default_year_term_from_cursor = False
            infer_term_for_year = False
            infer_year_for_term = False

    timetable_rows = []
    teacher_assignment_exam_rows = []
    academic_years = []
    terms = []
    exams_for_filter = []
    classes_for_filter = []
    sup_filter_id = None
    if restrict_to_supervisor:
        try:
            sup_filter_id = int(supervisor_employee_id) if supervisor_employee_id is not None else None
        except (TypeError, ValueError):
            sup_filter_id = None
    ta_filter_id = None
    if teacher_assignments_employee_id is not None:
        try:
            ta_filter_id = int(teacher_assignments_employee_id)
        except (TypeError, ValueError):
            ta_filter_id = None
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:

                ACTIVE_UNLOCKED_YEAR = "status = 'active' AND (is_locked = FALSE OR is_locked IS NULL)"

                def _fetch_one_int(query, params=None):
                    cursor.execute(query, params or ())
                    r = cursor.fetchone()
                    if not r:
                        return None
                    return r.get('id') if isinstance(r, dict) else r[0]

                # Resolve defaults (current unlocked year + current term within that year) or partial-query inference.
                if default_year_term_from_cursor:
                    yid = _fetch_one_int(f"""
                        SELECT id FROM academic_years
                        WHERE {ACTIVE_UNLOCKED_YEAR} AND COALESCE(is_current, FALSE) = TRUE
                        ORDER BY start_date DESC
                        LIMIT 1
                    """)
                    if yid is None:
                        yid = _fetch_one_int(f"""
                            SELECT id FROM academic_years
                            WHERE {ACTIVE_UNLOCKED_YEAR}
                            ORDER BY start_date DESC
                            LIMIT 1
                        """)
                    selected_year_id = yid or 0
                    selected_term_id = 0
                    if selected_year_id:
                        tid = _fetch_one_int("""
                            SELECT t.id FROM terms t
                            INNER JOIN academic_years ay ON t.academic_year_id = ay.id
                            WHERE t.academic_year_id = %s
                              AND ay.status = 'active' AND (ay.is_locked = FALSE OR ay.is_locked IS NULL)
                              AND t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                              AND COALESCE(t.is_current, FALSE) = TRUE
                            LIMIT 1
                        """, (selected_year_id,))
                        if tid is None:
                            tid = _fetch_one_int("""
                                SELECT t.id FROM terms t
                                INNER JOIN academic_years ay ON t.academic_year_id = ay.id
                                WHERE t.academic_year_id = %s
                                  AND ay.status = 'active' AND (ay.is_locked = FALSE OR ay.is_locked IS NULL)
                                  AND t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                                ORDER BY t.start_date ASC, t.id ASC
                                LIMIT 1
                            """, (selected_year_id,))
                        selected_term_id = tid or 0

                elif infer_year_for_term and selected_term_id:
                    ay_id = _fetch_one_int(
                        """
                        SELECT t.academic_year_id AS id FROM terms t
                        WHERE t.id = %s
                        LIMIT 1
                        """,
                        (selected_term_id,),
                    )
                    if ay_id is not None:
                        selected_year_id = ay_id

                elif infer_term_for_year and selected_year_id:
                    tid = _fetch_one_int("""
                        SELECT t.id FROM terms t
                        INNER JOIN academic_years ay ON t.academic_year_id = ay.id
                        WHERE t.academic_year_id = %s
                          AND ay.status = 'active' AND (ay.is_locked = FALSE OR ay.is_locked IS NULL)
                          AND t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                          AND COALESCE(t.is_current, FALSE) = TRUE
                        LIMIT 1
                    """, (selected_year_id,))
                    if tid is None:
                        tid = _fetch_one_int("""
                            SELECT t.id FROM terms t
                            INNER JOIN academic_years ay ON t.academic_year_id = ay.id
                            WHERE t.academic_year_id = %s
                              AND ay.status = 'active' AND (ay.is_locked = FALSE OR ay.is_locked IS NULL)
                              AND t.status = 'active' AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                            ORDER BY t.start_date ASC, t.id ASC
                            LIMIT 1
                        """, (selected_year_id,))
                    selected_term_id = tid or 0

                if selected_year_id is None:
                    selected_year_id = 0
                if selected_term_id is None:
                    selected_term_id = 0

                # Only selectable years/terms: active and not locked (same idea as fee / registration UIs).
                cursor.execute("""
                    SELECT id, year_name
                    FROM academic_years
                    WHERE status = 'active'
                      AND (is_locked = FALSE OR is_locked IS NULL)
                    ORDER BY start_date DESC
                """)
                for row in cursor.fetchall() or []:
                    academic_years.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'year_name': row.get('year_name', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
                    })
                unlocked_year_ids = {y['id'] for y in academic_years}
                if selected_year_id > 0 and selected_year_id not in unlocked_year_ids:
                    cursor.execute(
                        """
                        SELECT id, year_name
                        FROM academic_years
                        WHERE id = %s
                        LIMIT 1
                        """,
                        (selected_year_id,),
                    )
                    row_merge = cursor.fetchone()
                    if row_merge:
                        yn = row_merge.get('year_name', '') if isinstance(row_merge, dict) else (row_merge[1] if len(row_merge) > 1 else '')
                        academic_years.append({
                            'id': selected_year_id,
                            'year_name': f"{yn} (locked)",
                        })

                cursor.execute("""
                    SELECT t.id, t.term_name, t.academic_year_id,
                           ay.year_name AS academic_year_name
                    FROM terms t
                    INNER JOIN academic_years ay ON t.academic_year_id = ay.id
                    WHERE ay.status = 'active'
                      AND (ay.is_locked = FALSE OR ay.is_locked IS NULL)
                      AND t.status = 'active'
                      AND (t.is_locked = FALSE OR t.is_locked IS NULL)
                    ORDER BY ay.start_date DESC, t.start_date ASC, t.id ASC
                """)
                for row in cursor.fetchall() or []:
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else ''),
                        'academic_year_name': row.get('academic_year_name', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')
                    })
                unlocked_term_ids = {t['id'] for t in terms}
                if selected_term_id > 0 and selected_term_id not in unlocked_term_ids:
                    cursor.execute(
                        """
                        SELECT t.id, t.term_name, ay.year_name AS academic_year_name
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        WHERE t.id = %s
                        LIMIT 1
                        """,
                        (selected_term_id,),
                    )
                    row_merge_t = cursor.fetchone()
                    if row_merge_t:
                        tn = row_merge_t.get('term_name', '') if isinstance(row_merge_t, dict) else (row_merge_t[1] if len(row_merge_t) > 1 else '')
                        yn = row_merge_t.get('academic_year_name', '') if isinstance(row_merge_t, dict) else (row_merge_t[2] if len(row_merge_t) > 2 else '')
                        terms.append({
                            'id': selected_term_id,
                            'term_name': f"{tn} (locked)",
                            'academic_year_name': yn or '',
                        })

                exam_filter_query = """
                    SELECT DISTINCT e.exam_name
                    FROM exams e
                    WHERE TRIM(COALESCE(e.exam_name, '')) <> ''
                """
                exam_filter_params = []
                if selected_year_id > 0:
                    exam_filter_query += " AND e.academic_year_id = %s"
                    exam_filter_params.append(selected_year_id)
                if selected_term_id > 0:
                    exam_filter_query += " AND e.term_id = %s"
                    exam_filter_params.append(selected_term_id)
                if restrict_to_supervisor:
                    if sup_filter_id:
                        exam_filter_query += (
                            " AND (e.supervisor_id = %s OR EXISTS ("
                            "SELECT 1 FROM exam_supervisors es "
                            "WHERE es.exam_id = e.id AND es.supervisor_id = %s))"
                        )
                        exam_filter_params.extend([sup_filter_id, sup_filter_id])
                    else:
                        exam_filter_query += " AND 1 = 0"
                exam_filter_query += " ORDER BY e.exam_name ASC"
                cursor.execute(exam_filter_query, tuple(exam_filter_params))
                for row in cursor.fetchall() or []:
                    exam_name_value = (row.get('exam_name') if isinstance(row, dict) else row[0]) or ''
                    if exam_name_value:
                        exams_for_filter.append(exam_name_value)

                if restrict_to_supervisor and sup_filter_id:
                    cursor.execute("""
                        SELECT DISTINCT al.id, al.level_name, al.level_category
                        FROM exams e
                        INNER JOIN academic_levels al ON e.academic_level_id = al.id
                        WHERE (
                            e.supervisor_id = %s OR EXISTS (
                                SELECT 1 FROM exam_supervisors es
                                WHERE es.exam_id = e.id AND es.supervisor_id = %s
                            )
                        )
                          AND COALESCE(al.level_status, 'active') = 'active'
                        ORDER BY al.level_category ASC, al.level_name ASC
                    """, (sup_filter_id, sup_filter_id))
                elif restrict_to_supervisor:
                    cursor.execute("SELECT 1 WHERE 1 = 0")
                else:
                    cursor.execute("""
                        SELECT id, level_name, level_category
                        FROM academic_levels
                        WHERE level_status = 'active'
                        ORDER BY level_category ASC, level_name ASC
                    """)
                for row in cursor.fetchall() or []:
                    classes_for_filter.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[1],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else ''),
                    })

                timetable_query = f"""
                    SELECT
                        e.id,
                        e.subject_id,
                        e.supervisor_id,
                        e.exam_name,
                        e.exam_type,
                        e.exam_date,
                        e.session_type,
                        e.start_time,
                        e.end_time,
                        e.venue,
                        e.status,
                        al.id AS level_id,
                        al.level_name,
                        al.level_category,
                        s.subject_name,
                        s.subject_code,
                        emp.full_name AS teacher_name,
                        {_employee_staff_identity_sql('emp')} AS teacher_employee_id,
                        ay.year_name,
                        t.term_name,
                        COALESCE(e.is_locked, 0) AS exam_is_locked
                    FROM exams e
                    LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                    LEFT JOIN subjects s ON e.subject_id = s.id
                    LEFT JOIN employees emp ON e.supervisor_id = emp.id
                    LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                    LEFT JOIN terms t ON e.term_id = t.id
                    WHERE 1 = 1
                """
                timetable_params = []
                if selected_year_id > 0:
                    timetable_query += " AND e.academic_year_id = %s"
                    timetable_params.append(selected_year_id)
                if selected_term_id > 0:
                    timetable_query += " AND e.term_id = %s"
                    timetable_params.append(selected_term_id)
                if selected_exam_name:
                    timetable_query += " AND e.exam_name = %s"
                    timetable_params.append(selected_exam_name)
                if selected_class_id > 0:
                    timetable_query += " AND e.academic_level_id = %s"
                    timetable_params.append(selected_class_id)
                if restrict_to_supervisor:
                    if sup_filter_id:
                        timetable_query += (
                            " AND (e.supervisor_id = %s OR EXISTS ("
                            "SELECT 1 FROM exam_supervisors es "
                            "WHERE es.exam_id = e.id AND es.supervisor_id = %s))"
                        )
                        timetable_params.extend([sup_filter_id, sup_filter_id])
                    else:
                        timetable_query += " AND 1 = 0"
                timetable_query += """
                    ORDER BY
                        e.exam_date ASC,
                        al.level_category ASC,
                        al.level_name ASC,
                        e.start_time ASC,
                        e.id ASC
                """
                lock_col_sql = ",\n                        COALESCE(e.is_locked, 0) AS exam_is_locked"
                rows = []
                include_exam_lock = True
                try:
                    cursor.execute(timetable_query, tuple(timetable_params))
                    rows = cursor.fetchall() or []
                except Exception as exec_err:
                    err_s = str(exec_err).lower()
                    if 'is_locked' in err_s or 'unknown column' in err_s:
                        include_exam_lock = False
                        q2 = timetable_query.replace(lock_col_sql, "")
                        cursor.execute(q2, tuple(timetable_params))
                        rows = cursor.fetchall() or []
                    else:
                        raise
                for row in rows:
                    timetable_rows.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'subject_id': row.get('subject_id') if isinstance(row, dict) else (row[1] if len(row) > 1 else None),
                        'supervisor_id': row.get('supervisor_id') if isinstance(row, dict) else (row[2] if len(row) > 2 else None),
                        'exam_name': _coerce_str(row.get('exam_name', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')),
                        'exam_type': _coerce_str(row.get('exam_type', '') if isinstance(row, dict) else (row[4] if len(row) > 4 else '')),
                        'exam_date': _format_date_value(row.get('exam_date') if isinstance(row, dict) else (row[5] if len(row) > 5 else None)),
                        'session_type': _coerce_str(row.get('session_type', '') if isinstance(row, dict) else (row[6] if len(row) > 6 else '')),
                        'start_time': _format_time_value(row.get('start_time') if isinstance(row, dict) else (row[7] if len(row) > 7 else None)),
                        'end_time': _format_time_value(row.get('end_time') if isinstance(row, dict) else (row[8] if len(row) > 8 else None)),
                        'venue': _coerce_str(row.get('venue', '') if isinstance(row, dict) else (row[9] if len(row) > 9 else '')),
                        'status': _coerce_str(row.get('status', 'scheduled') if isinstance(row, dict) else (row[10] if len(row) > 10 else 'scheduled')) or 'scheduled',
                        'level_id': row.get('level_id') if isinstance(row, dict) else (row[11] if len(row) > 11 else None),
                        'level_name': _coerce_str(row.get('level_name', '') if isinstance(row, dict) else (row[12] if len(row) > 12 else '')),
                        'level_category': _coerce_str(row.get('level_category', '') if isinstance(row, dict) else (row[13] if len(row) > 13 else '')),
                        'subject_name': _coerce_str(row.get('subject_name', '') if isinstance(row, dict) else (row[14] if len(row) > 14 else '')),
                        'subject_code': _coerce_str(row.get('subject_code', '') if isinstance(row, dict) else (row[15] if len(row) > 15 else '')),
                        'teacher_name': _coerce_str(row.get('teacher_name', '') if isinstance(row, dict) else (row[16] if len(row) > 16 else '')),
                        'teacher_employee_id': _coerce_str(row.get('teacher_employee_id', '') if isinstance(row, dict) else (row[17] if len(row) > 17 else '')),
                        'year_name': _coerce_str(row.get('year_name', '') if isinstance(row, dict) else (row[18] if len(row) > 18 else '')),
                        'term_name': _coerce_str(row.get('term_name', '') if isinstance(row, dict) else (row[19] if len(row) > 19 else '')),
                        'exam_is_locked': (
                            bool(row.get('exam_is_locked', 0) if isinstance(row, dict) else (row[20] if len(row) > 20 else 0))
                            if include_exam_lock else False
                        ),
                    })

                if ta_filter_id:
                    try:
                        tsa_sql = """
                            SELECT
                                e.id,
                                e.exam_name,
                                e.exam_date,
                                e.session_type,
                                e.start_time,
                                e.end_time,
                                e.venue,
                                e.status,
                                al.level_name,
                                al.level_category,
                                s.subject_name,
                                s.subject_code,
                                COALESCE(sup_primary.full_name, '') AS primary_supervisor_name,
                                (
                                    SELECT GROUP_CONCAT(DISTINCT es2.full_name ORDER BY es2.full_name SEPARATOR ', ')
                                    FROM exam_supervisors exs
                                    INNER JOIN employees es2 ON exs.supervisor_id = es2.id
                                    WHERE exs.exam_id = e.id
                                      AND (e.supervisor_id IS NULL OR exs.supervisor_id <> e.supervisor_id)
                                ) AS extra_supervisor_names
                            FROM exams e
                            INNER JOIN teacher_subject_assignments tsa
                                ON tsa.teacher_id = %s
                               AND tsa.academic_level_id = e.academic_level_id
                               AND (e.subject_id IS NULL OR tsa.subject_id = e.subject_id)
                            LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                            LEFT JOIN subjects s ON e.subject_id = s.id
                            LEFT JOIN employees sup_primary ON e.supervisor_id = sup_primary.id
                            WHERE (e.status IS NULL OR e.status != 'cancelled')
                        """
                        tsa_params = [ta_filter_id]
                        if selected_year_id > 0:
                            tsa_sql += " AND e.academic_year_id = %s"
                            tsa_params.append(selected_year_id)
                        if selected_term_id > 0:
                            tsa_sql += " AND e.term_id = %s"
                            tsa_params.append(selected_term_id)
                        if selected_exam_name:
                            tsa_sql += " AND e.exam_name = %s"
                            tsa_params.append(selected_exam_name)
                        if selected_class_id > 0:
                            tsa_sql += " AND e.academic_level_id = %s"
                            tsa_params.append(selected_class_id)
                        tsa_sql += """
                            ORDER BY e.exam_date ASC, e.start_time ASC, al.level_category ASC, al.level_name ASC, e.id ASC
                        """
                        cursor.execute(tsa_sql, tuple(tsa_params))
                        for trow in cursor.fetchall() or []:
                            pn = _coerce_str(
                                trow.get('primary_supervisor_name', '')
                                if isinstance(trow, dict)
                                else ''
                            )
                            extra_raw = trow.get('extra_supervisor_names', '') if isinstance(trow, dict) else ''
                            extra_csv = _coerce_str(extra_raw) if extra_raw else ''
                            extras = []
                            if extra_csv:
                                for part in extra_csv.split(','):
                                    p = part.strip()
                                    if not p or (pn and p.lower() == pn.lower()):
                                        continue
                                    if p not in extras:
                                        extras.append(p)
                            if pn:
                                supervisor_allocated = pn + ((' · ' + ', '.join(extras)) if extras else '')
                            elif extras:
                                supervisor_allocated = ', '.join(extras)
                            else:
                                supervisor_allocated = '—'
                            ed_iso = _format_date_value(
                                trow.get('exam_date') if isinstance(trow, dict) else None
                            )
                            date_heading = ed_iso or 'No date assigned'
                            weekday = ''
                            if ed_iso:
                                try:
                                    dt = datetime.strptime(ed_iso, '%Y-%m-%d')
                                    weekday = dt.strftime('%A')
                                    date_heading = dt.strftime('%d %B %Y')
                                except ValueError:
                                    date_heading = ed_iso
                            _sess_raw = _coerce_str(
                                trow.get('session_type', '') if isinstance(trow, dict) else ''
                            )
                            _sess_key = _sess_raw.strip().upper() if _sess_raw.strip() else '__OTHER__'
                            _ta_st = _format_time_value(
                                trow.get('start_time') if isinstance(trow, dict) else None
                            )
                            _ta_en = _format_time_value(
                                trow.get('end_time') if isinstance(trow, dict) else None
                            )
                            _ta_sess_bits = []
                            if _sess_raw.strip():
                                _ta_sess_bits.append(_sess_raw.strip())
                            if _ta_st or _ta_en:
                                _ta_sess_bits.append(f"{_ta_st or '—'}–{_ta_en or '—'}")
                            _ta_session_summary = (
                                ' · '.join(_ta_sess_bits) if _ta_sess_bits else '—'
                            )
                            teacher_assignment_exam_rows.append({
                                'id': trow.get('id') if isinstance(trow, dict) else trow[0],
                                'exam_name': _coerce_str(trow.get('exam_name', '') if isinstance(trow, dict) else ''),
                                'exam_date': ed_iso,
                                'weekday': weekday,
                                'date_heading': date_heading,
                                'session_type': _coerce_str(
                                    trow.get('session_type', '') if isinstance(trow, dict) else ''
                                ),
                                'start_time': _ta_st,
                                'end_time': _ta_en,
                                'session_summary': _ta_session_summary,
                                'venue': _coerce_str(trow.get('venue', '') if isinstance(trow, dict) else ''),
                                'status': _coerce_str(
                                    (trow.get('status', 'scheduled') if isinstance(trow, dict) else 'scheduled')
                                    or 'scheduled'
                                ),
                                'level_name': _coerce_str(
                                    trow.get('level_name', '') if isinstance(trow, dict) else ''
                                ),
                                'level_category': _coerce_str(
                                    trow.get('level_category', '') if isinstance(trow, dict) else ''
                                ),
                                'subject_name': _coerce_str(
                                    trow.get('subject_name', '') if isinstance(trow, dict) else ''
                                ),
                                'subject_code': _coerce_str(
                                    trow.get('subject_code', '') if isinstance(trow, dict) else ''
                                ),
                                'supervisor_allocated': supervisor_allocated,
                                'session_key': _sess_key,
                            })
                    except Exception as tsa_err:
                        print(f"Error fetching teacher-assignment exam supervisors: {tsa_err}")

        except Exception as e:
            print(f"Error fetching all exam timetables: {e}")
        finally:
            connection.close()

    from collections import defaultdict

    supervision_duty_summary_rows = []
    if restrict_to_supervisor and timetable_rows:
        for item in timetable_rows:
            dk = item.get('exam_date') or ''
            date_heading = dk or 'No date assigned'
            weekday = ''
            if dk:
                try:
                    dt = datetime.strptime(dk, '%Y-%m-%d')
                    weekday = dt.strftime('%A')
                    date_heading = dt.strftime('%d %B %Y')
                except ValueError:
                    date_heading = dk
            session_bits = []
            st = item.get('session_type') or ''
            if st:
                session_bits.append(st)
            st_t = item.get('start_time') or ''
            en_t = item.get('end_time') or ''
            if st_t or en_t:
                session_bits.append(f"{st_t or '—'}–{en_t or '—'}")
            st_key_raw = (item.get('session_type') or '').strip()
            session_key = st_key_raw.upper() if st_key_raw else '__OTHER__'
            supervision_duty_summary_rows.append({
                'exam_name': item.get('exam_name') or '',
                'exam_date': dk,
                'weekday': weekday,
                'date_heading': date_heading,
                'session_key': session_key,
                'session_summary': ' · '.join(session_bits) if session_bits else '—',
                'start_time': item.get('start_time') or '',
                'end_time': item.get('end_time') or '',
                'subject_name': item.get('subject_name') or '',
                'subject_code': item.get('subject_code') or '',
                'level_name': item.get('level_name') or '',
                'level_category': item.get('level_category') or '',
                'venue': item.get('venue') or '',
            })
        supervision_duty_summary_rows.sort(
            key=lambda r: (
                r.get('exam_date') or '9999-12-31',
                r.get('session_key') or '',
                r.get('session_summary') or '',
                r.get('level_name') or '',
                r.get('subject_name') or '',
            ),
        )

    supervision_duty_matrix = _exam_eg_summary_matrix(supervision_duty_summary_rows)
    teacher_assignment_matrix = _exam_eg_summary_matrix(teacher_assignment_exam_rows)

    timetable_by_date = []
    if timetable_rows:
        by_date = defaultdict(list)
        for item in timetable_rows:
            dk = item.get('exam_date') or ''
            by_date[dk].append(item)

        def _sort_date_key(x):
            if not x:
                return '9999-12-31'
            return x

        ordered_dates = sorted((k for k in by_date.keys() if k), key=_sort_date_key)
        if '' in by_date:
            ordered_dates.append('')

        for dk in ordered_dates:
            slots = sorted(
                by_date[dk],
                key=lambda r: (
                    r.get('start_time') or '99:99',
                    r.get('session_type') or '',
                    r.get('level_name') or '',
                    r.get('exam_name') or '',
                    r.get('id') or 0,
                ),
            )
            weekday = ''
            date_heading = dk or 'No date assigned'
            if dk:
                try:
                    dt = datetime.strptime(dk, '%Y-%m-%d')
                    weekday = dt.strftime('%A')
                    date_heading = dt.strftime('%d %B %Y')
                except ValueError:
                    date_heading = dk

            timetable_by_date.append({
                'date_iso': dk,
                'weekday': weekday,
                'date_heading': date_heading,
                'slots': slots,
            })

    timetable_by_date = _enrich_timetable_days_exam_groups(timetable_by_date)

    return {
        'timetable_rows': timetable_rows,
        'timetable_by_date': timetable_by_date,
        'total_slots': len(timetable_rows),
        'academic_years': academic_years,
        'terms': terms,
        'exams_for_filter': exams_for_filter,
        'classes_for_filter': classes_for_filter,
        'selected_year_id': selected_year_id,
        'selected_term_id': selected_term_id,
        'selected_exam_name': selected_exam_name,
        'selected_class_id': selected_class_id,
        'supervision_duty_summary_rows': supervision_duty_summary_rows,
        'teacher_assignment_exam_rows': teacher_assignment_exam_rows,
        'supervision_duty_matrix': supervision_duty_matrix,
        'teacher_assignment_matrix': teacher_assignment_matrix,
    }


@app.route('/dashboard/employee/exam-timetable')
@login_required
def exam_timetable():
    """Exams timetable: teachers see date × session matrices (supervision + assignments); coordinators/principals see full wall timetable."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')

    if not (is_academic_coordinator or is_technician or is_principal or is_teacher):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    # Signed-in teacher, or technician viewing as teacher → same compact matrices as legacy exams-and-grades.
    teacher_matrix_view = (
        user_role in ('teachers', 'teacher')
        or (user_role == 'technician' and viewing_as_role in ('teachers', 'teacher'))
    )
    if teacher_matrix_view:
        if user_role in ('teachers', 'teacher'):
            emp_matrix_id = session.get('user_id')
        else:
            emp_matrix_id = session.get('viewing_as_employee_id')
        ctx = _compute_exams_assessments_timetable_bundle(
            supervisor_employee_id=emp_matrix_id,
            restrict_to_supervisor=True,
            teacher_assignments_employee_id=emp_matrix_id,
        )
        ctx['role'] = user_role
        ctx['is_technician'] = is_technician
        return render_template('dashboards/exams_and_grades.html', **ctx)

    restrict_sup, sup_id = _session_exam_timetable_supervisor_scope()
    ctx = _compute_exams_assessments_timetable_bundle(
        supervisor_employee_id=sup_id,
        restrict_to_supervisor=restrict_sup,
    )
    ctx['role'] = user_role
    # Defer the heavy wall grid to exam-timetable/api?live=1 (was ~3MB HTML).
    ctx['timetable_by_date'] = []
    ctx['total_slots'] = 0
    ctx['supervision_duty_summary_rows'] = []
    ctx['teacher_assignment_exam_rows'] = []
    ctx['supervision_duty_matrix'] = {'cols': [], 'days': []}
    ctx['teacher_assignment_matrix'] = {'cols': [], 'days': []}
    ctx['defer_timetable_grid'] = True
    return render_template('dashboards/exams_timetable_all.html', **ctx)


@app.route('/dashboard/employee/exam-timetable-management')
@login_required
def exam_timetable_management():
    """Exam timetable management: wall timetable + click-to-edit subject/supervisor."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    restrict_sup, sup_id = _session_exam_timetable_supervisor_scope()
    ctx = _compute_exams_assessments_timetable_bundle(
        supervisor_employee_id=sup_id,
        restrict_to_supervisor=restrict_sup,
    )
    ctx['role'] = user_role
    ctx['management_mode'] = True

    # Default the Exam filter to "current" on first load (no explicit exam_name chosen).
    # We treat the first exam_name returned by the current year/term scope as the default.
    if not (request.args.get('exam_name') or '').strip():
        exam_names = ctx.get('exams_for_filter') or []
        if exam_names:
            default_exam_name = str(exam_names[0] or '').strip()
            if default_exam_name:
                ctx['selected_exam_name'] = default_exam_name
                # Filter the already-built timetable payload to this exam name so the page loads filtered.
                filtered_days = []
                total = 0
                for day in (ctx.get('timetable_by_date') or []):
                    slots = [s for s in (day.get('slots') or []) if str(s.get('exam_name') or '') == default_exam_name]
                    if slots:
                        d2 = dict(day)
                        d2['slots'] = slots
                        filtered_days.append(d2)
                        total += len(slots)
                ctx['timetable_by_date'] = filtered_days
                ctx['total_slots'] = total

    # If the selected exam is locked, disable management UI (view-only).
    ctx['locked_exam_selected'] = False
    selected_exam_name = str(ctx.get('selected_exam_name') or '').strip()
    selected_year_id = int(ctx.get('selected_year_id') or 0)
    selected_term_id = int(ctx.get('selected_term_id') or 0)
    if selected_exam_name:
        _lock_conn = get_db_connection()
        try:
            if _lock_conn:
                with _lock_conn.cursor() as _c:
                    params = [selected_exam_name]
                    sql = """
                        SELECT 1
                        FROM exams e
                        WHERE e.exam_name = %s
                          AND COALESCE(e.is_locked, 0) = 1
                    """
                    if selected_year_id > 0:
                        sql += " AND e.academic_year_id = %s"
                        params.append(selected_year_id)
                    if selected_term_id > 0:
                        sql += " AND e.term_id = %s"
                        params.append(selected_term_id)
                    sql += " LIMIT 1"
                    _c.execute(sql, tuple(params))
                    if _c.fetchone():
                        ctx['locked_exam_selected'] = True
                        ctx['management_mode'] = False
        finally:
            try:
                if _lock_conn:
                    _lock_conn.close()
            except Exception:
                pass

    subjects_for_edit = []
    teachers_for_edit = []
    connection = get_db_connection()
    try:
        if connection:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, COALESCE(subject_name, '') AS subject_name, COALESCE(subject_code, '') AS subject_code
                    FROM subjects
                    WHERE COALESCE(subject_name, '') <> ''
                    ORDER BY subject_name ASC
                """)
                subjects_for_edit = cursor.fetchall() or []

                cursor.execute("""
                    SELECT id, COALESCE(full_name, '') AS full_name, COALESCE(employee_id, '') AS employee_id
                    FROM employees
                    WHERE status = 'active' AND (role = 'teachers' OR role = 'teacher')
                      AND COALESCE(full_name, '') <> ''
                    ORDER BY full_name ASC
                """)
                teachers_for_edit = cursor.fetchall() or []
    finally:
        try:
            if connection:
                connection.close()
        except Exception:
            pass

    ctx['subjects_for_edit'] = subjects_for_edit
    ctx['teachers_for_edit'] = teachers_for_edit
    # Defer wall HTML; client loads via exam-timetable/api?live=1
    ctx['timetable_by_date'] = []
    ctx['total_slots'] = 0
    ctx['defer_timetable_grid'] = True

    return render_template('dashboards/exams_timetable_all.html', **ctx)


@app.route('/dashboard/employee/exam-timetable/api')
@login_required
def exam_timetable_api():
    """JSON for live timetable filtering (requires ``live=1`` plus filter query params)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')

    if not (is_academic_coordinator or is_technician or is_principal or is_teacher):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    if str(request.args.get('live', '')).lower() not in ('1', 'true', 'yes'):
        return jsonify({'success': False, 'message': 'Missing live=1'}), 400

    restrict_sup, sup_id = _session_exam_timetable_supervisor_scope()
    ctx = _compute_exams_assessments_timetable_bundle(
        supervisor_employee_id=sup_id,
        restrict_to_supervisor=restrict_sup,
        teacher_assignments_employee_id=sup_id if restrict_sup else None,
    )
    return jsonify({
        'success': True,
        'timetable_by_date': ctx.get('timetable_by_date') or [],
        'total_slots': ctx.get('total_slots', 0),
        'days_count': len(ctx.get('timetable_by_date') or []),
        'exams_for_filter': ctx.get('exams_for_filter') or [],
        'classes_for_filter': ctx.get('classes_for_filter') or [],
        'selected_year_id': ctx.get('selected_year_id', 0),
        'selected_term_id': ctx.get('selected_term_id', 0),
        'selected_exam_name': ctx.get('selected_exam_name') or '',
        'selected_class_id': ctx.get('selected_class_id', 0),
        'supervision_duty_summary_rows': ctx.get('supervision_duty_summary_rows') or [],
        'teacher_assignment_exam_rows': ctx.get('teacher_assignment_exam_rows') or [],
        'supervision_duty_matrix': ctx.get('supervision_duty_matrix') or {'cols': [], 'days': []},
        'teacher_assignment_matrix': ctx.get('teacher_assignment_matrix') or {'cols': [], 'days': []},
    })


