# Exam Analytics Route
@app.route('/dashboard/employee/exam-analytics')
@login_required
def exam_analytics():
    """Exam analytics page - list all registered exams (one row per exam, latest first)"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_teacher or is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    exams = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT e.id, e.exam_name, e.exam_type, e.exam_date, e.status,
                           e.academic_year_id, e.term_id,
                           ay.year_name, t.term_name
                    FROM exams e
                    LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                    LEFT JOIN terms t ON e.term_id = t.id
                    ORDER BY e.exam_date DESC, e.created_at DESC
                """)
                rows = cursor.fetchall()
                # Unique by exam_name only: keep one row per exam name (most recent by exam_date)
                grouped = {}
                for row in rows:
                    exam_name = (row.get('exam_name', '') or '').strip() if isinstance(row, dict) else (row[1] or '')
                    if not exam_name:
                        continue
                    exam_date_val = row.get('exam_date') if isinstance(row, dict) else row[3]
                    exam_date_str = exam_date_val.strftime('%Y-%m-%d') if exam_date_val and hasattr(exam_date_val, 'strftime') else (str(exam_date_val) if exam_date_val else '')
                    row_id = row.get('id') if isinstance(row, dict) else row[0]
                    if exam_name not in grouped or (exam_date_str and (grouped[exam_name].get('exam_date') or '') < exam_date_str):
                        grouped[exam_name] = {
                            'link_id': row_id,
                            'exam_name': exam_name,
                            'exam_date': exam_date_str,
                            'exam_type': (row.get('exam_type', '') if isinstance(row, dict) else row[2]),
                            'status': row.get('status', 'scheduled') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'scheduled'),
                            'year_name': row.get('year_name', '') if isinstance(row, dict) else (row[7] if len(row) > 7 else ''),
                            'term_name': row.get('term_name', '') if isinstance(row, dict) else (row[8] if len(row) > 8 else ''),
                        }
                exams = list(grouped.values())
                exams.sort(key=lambda x: (x.get('exam_date') or ''), reverse=True)
        except Exception as e:
            print(f"Error fetching exams for analytics: {e}")
        finally:
            connection.close()
    return render_template('dashboards/exam_analytics.html', role=user_role, exams=exams)

# Exam Analytics - single exam detail (all slots for that exam)
@app.route('/dashboard/employee/exam-analytics/exam/<int:exam_id>')
@login_required
def exam_analytics_detail(exam_id):
    """View details for one exam (all subject/supervisor slots for that exam)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_teacher or is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    connection = get_db_connection()
    if not connection:
        flash('Database error.', 'error')
        return redirect(url_for('exam_analytics'))
    top_teachers = []
    levels = []
    level_combinations = []
    level_view = (request.args.get('level_view') or 'individual').strip().lower()
    if level_view not in ('individual', 'combined'):
        level_view = 'individual'
    level_scope = None
    try:
        with connection.cursor() as cursor:
            ensure_academic_level_combination_tables(cursor)
            cursor.execute("""
                SELECT e.id, e.exam_name, e.exam_type, e.exam_date, e.academic_year_id, e.term_id, e.academic_level_id,
                       al.level_name, ay.year_name, t.term_name
                FROM exams e
                LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                LEFT JOIN terms t ON e.term_id = t.id
                WHERE e.id = %s
            """, (exam_id,))
            row = cursor.fetchone()
            if not row:
                flash('Exam not found.', 'error')
                return redirect(url_for('exam_analytics'))
            exam_name = (row.get('exam_name', '') or '').strip() if isinstance(row, dict) else (row[1] or '').strip()
            exam_type_detail = (
                (row.get('exam_type', '') or '').strip() if isinstance(row, dict) else (row[2] or '').strip()
            ) or None
            exam_date_val = row.get('exam_date') if isinstance(row, dict) else row[3]
            exam_date_str = exam_date_val.strftime('%Y-%m-%d') if exam_date_val and hasattr(exam_date_val, 'strftime') else str(exam_date_val) if exam_date_val else ''
            ay_id = row.get('academic_year_id') if isinstance(row, dict) else row[4]
            term_id = row.get('term_id') if isinstance(row, dict) else row[5]
            default_level_id = row.get('academic_level_id') if isinstance(row, dict) else row[6]
            # All academic levels that have this exam (same name, year, term – any date)
            cursor.execute("""
                SELECT DISTINCT e.academic_level_id, al.level_name, al.level_category
                FROM exams e
                LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                WHERE TRIM(COALESCE(e.exam_name,'')) = %s AND e.academic_year_id = %s AND e.term_id = %s AND e.academic_level_id IS NOT NULL
                ORDER BY al.level_name
            """, (exam_name, ay_id, term_id))
            level_rows = cursor.fetchall()
            for lr in level_rows:
                lid = lr.get('academic_level_id') if isinstance(lr, dict) else lr[0]
                lname = lr.get('level_name', '') if isinstance(lr, dict) else (lr[1] if len(lr) > 1 else '')
                lcat = lr.get('level_category', '') if isinstance(lr, dict) else (lr[2] if len(lr) > 2 else '')
                levels.append({'id': lid, 'level_name': lname, 'level_category': lcat})
            selected_level_id = request.args.get('level_id', type=int) or default_level_id
            if not any(l['id'] == selected_level_id for l in levels):
                selected_level_id = default_level_id if levels else None
            if not selected_level_id and levels:
                selected_level_id = levels[0]['id']
            analytics_reg_current = load_registered_current_exam_dict(cursor)
            level_combinations = fetch_academic_level_combinations_for_context(
                cursor, exam_name, ay_id, term_id, selected_level_id,
                registered_current=analytics_reg_current, exam_type=exam_type_detail,
            )
            level_scope = _exam_analytics_resolve_level_scope(
                level_view, selected_level_id, levels, level_combinations
            )
            if level_view == 'combined' and not level_scope.get('is_combined_view'):
                flash(
                    'No combined level group includes the selected class. '
                    'Create groups under Settings → Combined academic levels, or use Individual class view.',
                    'warning',
                )
                level_view = 'individual'
                level_scope = _exam_analytics_resolve_level_scope(
                    'individual', selected_level_id, levels, level_combinations
                )
            scope_level_ids = level_scope.get('level_ids') or []
            rows = []
            if scope_level_ids:
                lvl_ph = ','.join(['%s'] * len(scope_level_ids))
                cursor.execute(
                    f"""
                    SELECT e.id, e.subject_id, e.supervisor_id, e.exam_name, e.exam_type, e.exam_date, e.session_type, e.start_time, e.end_time,
                           e.duration_minutes, e.venue, e.status, e.instructions,
                           al.level_name, al.level_category,
                           s.subject_name, s.subject_code,
                           ay.year_name, t.term_name,
                           emp.full_name as supervisor_name
                    FROM exams e
                    LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                    LEFT JOIN subjects s ON e.subject_id = s.id
                    LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                    LEFT JOIN terms t ON e.term_id = t.id
                    LEFT JOIN employees emp ON e.supervisor_id = emp.id
                    WHERE TRIM(COALESCE(e.exam_name,'')) = %s AND e.academic_year_id = %s AND e.term_id = %s
                      AND e.academic_level_id IN ({lvl_ph})
                    ORDER BY e.exam_date, e.start_time
                    """,
                    (exam_name, ay_id, term_id, *scope_level_ids),
                )
                rows = cursor.fetchall()
        slots = []
        for r in rows:
            start_time_val = r.get('start_time') if isinstance(r, dict) else r[7]
            end_time_val = r.get('end_time') if isinstance(r, dict) else r[8]
            if start_time_val:
                if isinstance(start_time_val, timedelta):
                    sec = int(start_time_val.total_seconds())
                    start_str = f"{sec // 3600:02d}:{(sec % 3600) // 60:02d}"
                elif hasattr(start_time_val, 'strftime'):
                    start_str = start_time_val.strftime('%H:%M')
                else:
                    start_str = str(start_time_val)
            else:
                start_str = ''
            if end_time_val:
                if isinstance(end_time_val, timedelta):
                    sec = int(end_time_val.total_seconds())
                    end_str = f"{sec // 3600:02d}:{(sec % 3600) // 60:02d}"
                elif hasattr(end_time_val, 'strftime'):
                    end_str = end_time_val.strftime('%H:%M')
                else:
                    end_str = str(end_time_val)
            else:
                end_str = ''
            subject_id = r.get('subject_id') if isinstance(r, dict) else (r[1] if len(r) > 1 else None)
            slot_id = r.get('id') if isinstance(r, dict) else r[0]
            subject_name = (r.get('subject_name') or r.get('subject_code') or '') if isinstance(r, dict) else ((r[15] or r[16] or '') if len(r) > 16 else '')
            supervisor_name = r.get('supervisor_name', '') if isinstance(r, dict) else (r[19] if len(r) > 19 else '')
            slots.append({
                'id': slot_id,
                'subject_id': subject_id,
                'subject_name': subject_name,
                'supervisor_id': r.get('supervisor_id') if isinstance(r, dict) else (r[2] if len(r) > 2 else None),
                'supervisor_name': supervisor_name,
                'start_time': start_str,
                'end_time': end_str,
                'duration_minutes': r.get('duration_minutes') if isinstance(r, dict) else r[9],
                'venue': r.get('venue', '') if isinstance(r, dict) else r[10],
                'status': r.get('status', '') if isinstance(r, dict) else (r[11] if len(r) > 11 else ''),
            })
        # Compute mean grade per slot and position (rank by mean descending)
        try:
            with connection.cursor() as cur2:
                ensure_subject_exam_total_marks_column(cur2)
                for slot in slots:
                    cur2.execute("""
                        SELECT COALESCE(AVG(
                            (100 * CAST(sm.marks AS DECIMAL(16,8)))
                            / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)
                        ), 0) AS mean_grade,
                               COUNT(*) AS count_marks
                        FROM student_marks sm
                        INNER JOIN exams ex ON sm.exam_id = ex.id
                        INNER JOIN subjects sub ON ex.subject_id = sub.id
                        WHERE sm.exam_id = %s
                    """, (slot['id'],))
                    m = cur2.fetchone()
                    slot['mean_grade'] = float(m.get('mean_grade', 0) if isinstance(m, dict) else (m[0] if m and len(m) > 0 else 0))
                    slot['count_marks'] = int(m.get('count_marks', 0) if isinstance(m, dict) else (m[1] if m and len(m) > 1 else 0))
                # Sort by mean descending and assign position
                slots_sorted = sorted(slots, key=lambda x: x['mean_grade'], reverse=True)
                for pos, slot in enumerate(slots_sorted, 1):
                    slot['position'] = pos
                # Top ranking teachers (by subject mean grade)
                top_teachers = [{'position': s['position'], 'subject_name': s['subject_name'], 'supervisor_name': s['supervisor_name'] or '—', 'mean_grade': s['mean_grade']} for s in slots_sorted]
        except Exception as e:
            _schema_ignore_existing(e, 'student_marks or mean computation')
            for slot in slots:
                slot['mean_grade'] = 0.0
                slot['count_marks'] = 0
                slot['position'] = 0
            top_teachers = []
        # Distinct subjects (one per subject_id) for display; each may have multiple slot ids (e.g. Paper 1 + Paper 2)
        distinct_subjects = []
        seen_subject_ids = set()
        for slot in slots:
            sid = slot.get('subject_id')
            if sid is not None and sid not in seen_subject_ids:
                seen_subject_ids.add(sid)
                slot_ids_for_subject = [s['id'] for s in slots if s.get('subject_id') == sid]
                distinct_subjects.append({
                    'subject_id': sid,
                    'subject_name': slot.get('subject_name') or '—',
                    'slot_ids': slot_ids_for_subject
                })
        # If no subject_id in slots, keep one column per slot (fallback)
        if not distinct_subjects:
            for slot in slots:
                distinct_subjects.append({
                    'subject_id': slot.get('id'),
                    'subject_name': slot.get('subject_name') or '—',
                    'slot_ids': [slot['id']]
                })

        # For curriculum coordinator, show combined subjects as one converted-mark column (out of 100) on the Students Marks tab.
        # Keep other tabs (subject analytics / teacher analytics) using the original per-subject list.
        distinct_subjects_students = distinct_subjects
        if is_academic_coordinator:
            try:
                with connection.cursor() as cur_combo:
                    ensure_subject_exam_total_marks_column(cur_combo)
                    ensure_subject_exam_combination_tables(cur_combo)
                    subject_ids = [int(s.get('subject_id')) for s in distinct_subjects if s.get('subject_id') is not None]
                    exam_total_by_id = {}
                    if subject_ids:
                        placeholders = ','.join(['%s'] * len(subject_ids))
                        cur_combo.execute(
                            f"""
                            SELECT id, exam_total_marks, subject_code, exam_display_order
                            FROM subjects WHERE id IN ({placeholders})
                            """,
                            tuple(subject_ids),
                        )
                        for rr in (cur_combo.fetchall() or []):
                            sid = rr.get('id') if isinstance(rr, dict) else rr[0]
                            etm = rr.get('exam_total_marks') if isinstance(rr, dict) else (rr[1] if len(rr) > 1 else None)
                            sc = rr.get('subject_code') if isinstance(rr, dict) else (rr[2] if len(rr) > 2 else '')
                            edo = rr.get('exam_display_order') if isinstance(rr, dict) else (rr[3] if len(rr) > 3 else None)
                            if sid is not None:
                                exam_total_by_id[int(sid)] = {
                                    'exam_total_marks': etm,
                                    'subject_code': sc or '',
                                    'exam_display_order': edo,
                                }
                    slot_ids_by_subject = {int(s['subject_id']): list(s.get('slot_ids') or []) for s in distinct_subjects if s.get('subject_id') is not None}

                    subjects_for_merge = []
                    for s in distinct_subjects:
                        sid = s.get('subject_id')
                        if sid is None:
                            continue
                        extra = exam_total_by_id.get(int(sid)) or {}
                        subjects_for_merge.append({
                            'id': int(sid),
                            'subject_name': s.get('subject_name') or '—',
                            'subject_code': extra.get('subject_code') or '',
                            'exam_total_marks': extra.get('exam_total_marks'),
                            'exam_display_order': extra.get('exam_display_order'),
                        })
                    combos_loaded = fetch_subject_exam_combinations_for_context(
                        cur_combo, exam_name, ay_id, term_id,
                        scope_level_ids[0] if scope_level_ids else None,
                        registered_current=load_registered_current_exam_dict(cur_combo),
                        exam_type=exam_type_detail,
                    )
                    id_to_gc, section_order = sort_subjects_list_for_exam_columns_for_context(
                        cur_combo, subjects_for_merge,
                        exam_name, ay_id, term_id,
                        scope_level_ids[0] if scope_level_ids else None,
                        registered_current=load_registered_current_exam_dict(cur_combo),
                        exam_type=exam_type_detail,
                    )
                    merged_rows = (
                        merge_subjects_with_exam_combinations(
                            subjects_for_merge,
                            combos_loaded,
                            id_to_gc=id_to_gc,
                            section_order=section_order,
                        )
                        if subjects_for_merge
                        else distinct_subjects
                    )

                    distinct_subjects_students = []
                    for mr in merged_rows or []:
                        rid = int(mr.get('id'))
                        if rid > 0:
                            distinct_subjects_students.append({
                                'subject_id': rid,
                                'subject_name': mr.get('subject_name') or '—',
                                'slot_ids': slot_ids_by_subject.get(rid) or [],
                                'is_combined': False,
                            })
                        else:
                            member_ids = mr.get('member_subject_ids') or []
                            weights = []
                            for mid in member_ids:
                                extra = exam_total_by_id.get(int(mid)) or {}
                                weights.append(subject_exam_max_raw_marks(extra.get('exam_total_marks')))
                            distinct_subjects_students.append({
                                'subject_id': rid,  # negative synthetic id
                                'subject_name': mr.get('subject_name') or '—',
                                'slot_ids': [],
                                'member_subject_ids': [int(x) for x in member_ids],
                                'member_weights': weights,
                                'is_combined': True,
                            })
            except Exception as ce:
                print(f"Note: combined subject columns skipped in exam_analytics_detail: {ce}")
                distinct_subjects_students = distinct_subjects
        # All slot (exam) ids for this exam name/year/term/level – marks may be stored under any of these (e.g. exams-assessments uses one exam_id per name)
        all_slot_ids = [s['id'] for s in slots]
        # Students Marks: ALL students in this level, one column per subject (look up by subject_id + any exam_id in this exam so all subjects show)
        students_marks = []
        subject_analytics = []
        class_mean = 0.0
        level_names_for_students = list(level_scope.get('level_names') or []) if level_scope else []
        try:
            with connection.cursor() as cur2:
                ensure_subject_exam_total_marks_column(cur2)
                default_grade_bands, _, class_grade_bands = load_grade_bands_for_exam_context(
                    cur2, exam_name, ay_id, term_id,
                    scope_level_ids[0] if scope_level_ids else None,
                    registered_current=load_registered_current_exam_dict(cur2),
                    exam_type=exam_type_detail,
                )
                scope_level_ids = [int(x) for x in (level_scope.get('level_ids') or []) if x is not None]
                level_name_to_id = _level_name_to_id_map(cur2)
                student_level_by_id = {}

                def _grade_for_mark(subject_id, marks_value, level_id=None):
                    if marks_value is None:
                        return ''
                    lid = level_id
                    if lid is None and scope_level_ids:
                        lid = scope_level_ids[0] if len(scope_level_ids) == 1 else None
                    bands = resolve_grade_bands(lid, class_grade_bands, default_grade_bands)
                    band = match_grade_band(marks_value, bands)
                    if not band:
                        return ''
                    code = (band.get('code') or '').strip()
                    label = (band.get('label') or '').strip()
                    return code or label or ''

                all_students_rows = []
                if level_names_for_students:
                    nm_ph = ','.join(['%s'] * len(level_names_for_students))
                    cur2.execute(
                        f"""
                        SELECT student_id, full_name, TRIM(COALESCE(current_grade, '')) AS current_grade
                        FROM students
                        WHERE current_grade IN ({nm_ph}) AND status = 'in session'
                        ORDER BY full_name ASC
                        """,
                        tuple(level_names_for_students),
                    )
                    all_students_rows = cur2.fetchall()
                for srow in all_students_rows:
                    sid = srow.get('student_id') if isinstance(srow, dict) else srow[0]
                    full_name = (srow.get('full_name', '') if isinstance(srow, dict) else (srow[1] if len(srow) > 1 else sid)) if srow else sid
                    cur_grade = (
                        str(srow.get('current_grade') or '').strip()
                        if isinstance(srow, dict)
                        else (str(srow[2]).strip() if len(srow) > 2 and srow[2] is not None else '')
                    )
                    student_level_id = level_name_to_id.get(cur_grade)
                    if student_level_id is None and len(scope_level_ids) == 1:
                        student_level_id = scope_level_ids[0]
                    student_level_by_id[sid] = student_level_id
                    marks_list = []
                    for subj in distinct_subjects_students:
                        total_for_subject = None
                        # Combined synthetic column (curriculum coordinator only): compute final converted combined mark out of 100
                        if subj.get('is_combined'):
                            member_ids = subj.get('member_subject_ids') or []
                            member_weights = subj.get('member_weights') or []
                            pairs = []
                            for idx_m, mid in enumerate(member_ids):
                                w = member_weights[idx_m] if idx_m < len(member_weights) else 0.0
                                if w <= 0:
                                    continue
                                placeholders = ','.join(['%s'] * len(all_slot_ids)) if all_slot_ids else ''
                                pcts_m = []
                                if all_slot_ids:
                                    cur2.execute("""
                                        SELECT sm.marks, sub.exam_total_marks
                                        FROM student_marks sm
                                        INNER JOIN subjects sub ON sm.subject_id = sub.id
                                        WHERE sm.student_id = %s AND sm.subject_id = %s AND sm.exam_id IN (""" + placeholders + """)
                                    """, [sid, mid] + all_slot_ids)
                                    for mrow in (cur2.fetchall() or []):
                                        mval = mrow.get('marks') if isinstance(mrow, dict) else (mrow[0] if mrow and len(mrow) > 0 else None)
                                        etm = mrow.get('exam_total_marks') if isinstance(mrow, dict) else (mrow[1] if mrow and len(mrow) > 1 else None)
                                        if mval is None:
                                            continue
                                        try:
                                            p = raw_mark_to_percentage(float(mval), etm)
                                        except (TypeError, ValueError):
                                            p = None
                                        if p is not None:
                                            pcts_m.append(p)
                                p_avg = round_mark_display(sum(pcts_m) / len(pcts_m)) if pcts_m else None
                                if p_avg is not None:
                                    pairs.append((p_avg, float(w)))
                            # Σ(raw)/Σ(max)×100 via max-weighted mean of per-paper %
                            combo_pct = combined_papers_percentage_from_scaled(pairs)
                            total_for_subject = round_mark_display(combo_pct) if combo_pct is not None else None
                        # Look up by (student_id, subject_id) and exam_id IN all slots – so marks saved under any slot (e.g. same exam_id for all subjects on exams-assessments) are found
                        elif all_slot_ids and subj.get('subject_id') is not None:
                            placeholders = ','.join(['%s'] * len(all_slot_ids))
                            cur2.execute("""
                                SELECT sm.marks, sub.exam_total_marks
                                FROM student_marks sm
                                INNER JOIN subjects sub ON sm.subject_id = sub.id
                                WHERE sm.student_id = %s AND sm.subject_id = %s AND sm.exam_id IN (""" + placeholders + """)
                            """, [sid, subj['subject_id']] + all_slot_ids)
                            pcts = []
                            for mrow in cur2.fetchall():
                                mval = mrow.get('marks') if isinstance(mrow, dict) else (mrow[0] if mrow and len(mrow) > 0 else None)
                                etm = mrow.get('exam_total_marks') if isinstance(mrow, dict) else (mrow[1] if mrow and len(mrow) > 1 else None)
                                if mval is not None:
                                    try:
                                        p = raw_mark_to_percentage(float(mval), etm)
                                    except (TypeError, ValueError):
                                        p = None
                                    if p is not None:
                                        pcts.append(p)
                            total_for_subject = round_mark_display(sum(pcts) / len(pcts)) if pcts else None
                        else:
                            # Fallback: match by exam_id only (one slot per subject)
                            pcts_fb = []
                            for exam_id in subj.get('slot_ids', []):
                                cur2.execute("""
                                    SELECT sm.marks, sub.exam_total_marks
                                    FROM student_marks sm
                                    INNER JOIN subjects sub ON sm.subject_id = sub.id
                                    WHERE sm.student_id = %s AND sm.exam_id = %s
                                """, (sid, exam_id))
                                mrow = cur2.fetchone()
                                if mrow:
                                    mval = mrow.get('marks') if isinstance(mrow, dict) else (mrow[0] if mrow and len(mrow) > 0 else None)
                                    etm = mrow.get('exam_total_marks') if isinstance(mrow, dict) else (mrow[1] if mrow and len(mrow) > 1 else None)
                                    if mval is not None:
                                        try:
                                            p = raw_mark_to_percentage(float(mval), etm)
                                        except (TypeError, ValueError):
                                            p = None
                                        if p is not None:
                                            pcts_fb.append(p)
                            total_for_subject = round_mark_display(sum(pcts_fb) / len(pcts_fb)) if pcts_fb else None
                        grade_value = _grade_for_mark(
                            subj.get('subject_id'), total_for_subject, level_id=student_level_by_id.get(sid)
                        )
                        marks_list.append({
                            'subject_name': subj['subject_name'],
                            'marks': total_for_subject,
                            'grade': grade_value,
                            'is_combined': bool(subj.get('is_combined')),
                        })
                    students_marks.append({'student_id': sid, 'full_name': full_name, 'marks_list': marks_list})
                for sm in students_marks:
                    pct_vals = [
                        m.get('marks')
                        for m in sm['marks_list']
                        if m.get('marks') is not None and not m.get('is_combined')
                    ]
                    scored_subjects = len(pct_vals)
                    if scored_subjects > 0:
                        sm['total_marks'] = round_mark_display(sum(pct_vals) / float(scored_subjects))
                        sm['total_percent'] = sm['total_marks']
                        sm['total_grade'] = _grade_for_mark(
                            None, sm['total_percent'], level_id=student_level_by_id.get(sm.get('student_id'))
                        )
                    else:
                        sm['total_marks'] = 0
                        sm['total_percent'] = None
                        sm['total_grade'] = ''
                students_marks.sort(key=lambda x: x['total_marks'], reverse=True)
                for pos, sm in enumerate(students_marks, 1):
                    sm['position'] = pos
                all_marks_flat = [
                    m.get('marks')
                    for sm in students_marks
                    for m in sm['marks_list']
                    if m.get('marks') is not None and not m.get('is_combined')
                ]
                class_mean = (sum(all_marks_flat) / len(all_marks_flat)) if all_marks_flat else 0.0
                class_mean_grade = _grade_for_mark(None, class_mean) if all_marks_flat else ''
                # Subject Analytics: top 10 students per subject (marks for subject from any slot in this exam)
                for subj in distinct_subjects:
                    subj_id = subj.get('subject_id')
                    if subj_id is None or not all_slot_ids:
                        continue
                    placeholders = ','.join(['%s'] * len(all_slot_ids))
                    cur2.execute("""
                        SELECT sm.student_id,
                               AVG((100 * CAST(sm.marks AS DECIMAL(16,8)))
                                   / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)) AS total_marks,
                               st.full_name
                        FROM student_marks sm
                        INNER JOIN subjects sub ON sm.subject_id = sub.id
                        LEFT JOIN students st ON sm.student_id = st.student_id
                        WHERE sm.subject_id = %s AND sm.exam_id IN (""" + placeholders + """)
                        GROUP BY sm.student_id, st.full_name
                        ORDER BY total_marks DESC
                        LIMIT 10
                    """, [subj_id] + all_slot_ids)
                    top_rows = cur2.fetchall()
                    top_students = []
                    for idx, tr in enumerate(top_rows, 1):
                        sid = tr.get('student_id') if isinstance(tr, dict) else tr[0]
                        marks_val = tr.get('total_marks') if isinstance(tr, dict) else (tr[1] if len(tr) > 1 else None)
                        fn = tr.get('full_name', '') if isinstance(tr, dict) else (tr[2] if len(tr) > 2 else '')
                        top_students.append({
                            'rank': idx,
                            'student_id': sid,
                            'full_name': fn or sid,
                            'marks': marks_val,
                            'grade': _grade_for_mark(
                                subj_id, marks_val, level_id=student_level_by_id.get(sid)
                            )
                        })
                    subject_analytics.append({'subject_id': subj_id, 'subject_name': subj.get('subject_name') or '—', 'top_students': top_students})
                # Teacher Analytics: mean grade per subject (marks from any exam_id in this exam), rank by mean
                teacher_analytics_list = []
                teacher_name_by_subject = {}
                try:
                    subj_ids = [int(s.get('subject_id')) for s in distinct_subjects if s.get('subject_id') is not None]
                    subj_ids = [x for x in subj_ids if x > 0]
                    scope_level_ids = (level_scope.get('level_ids') or []) if level_scope else []
                    scope_level_ids = [int(x) for x in scope_level_ids if x is not None]
                    if subj_ids and scope_level_ids:
                        ph_subj = ','.join(['%s'] * len(subj_ids))
                        ph_lvl = ','.join(['%s'] * len(scope_level_ids))
                        cur2.execute(
                            f"""
                            SELECT tsa.subject_id,
                                   GROUP_CONCAT(DISTINCT UPPER(TRIM(emp.full_name))
                                                ORDER BY emp.full_name SEPARATOR ', ') AS teacher_names
                            FROM teacher_subject_assignments tsa
                            INNER JOIN employees emp ON emp.id = tsa.teacher_id
                            WHERE tsa.academic_level_id IN ({ph_lvl})
                              AND tsa.subject_id IN ({ph_subj})
                            GROUP BY tsa.subject_id
                            """,
                            tuple(scope_level_ids) + tuple(subj_ids),
                        )
                        for trow in (cur2.fetchall() or []):
                            sid = trow.get('subject_id') if isinstance(trow, dict) else trow[0]
                            nm = trow.get('teacher_names') if isinstance(trow, dict) else (trow[1] if len(trow) > 1 else '')
                            if sid is not None:
                                teacher_name_by_subject[int(sid)] = (nm or '').strip()
                except Exception as te:
                    # teacher_subject_assignments may be missing or empty; fall back to exam supervisor names
                    print(f"Note: teacher_name_by_subject mapping skipped: {te}")
                for subj in distinct_subjects:
                    subj_id = subj.get('subject_id')
                    supervisor_name = teacher_name_by_subject.get(int(subj_id)) if subj_id is not None else ''
                    supervisor_name = (supervisor_name or '').strip()
                    if not supervisor_name:
                        # fallback: exam supervisor if no assigned subject teacher
                        supervisor_name = '—'
                        for s in slots:
                            if s.get('subject_id') == subj_id or s.get('id') == subj_id:
                                supervisor_name = s.get('supervisor_name') or '—'
                                break
                    if subj_id is None or not all_slot_ids:
                        teacher_analytics_list.append({
                            'subject_name': subj.get('subject_name') or '—',
                            'supervisor_name': supervisor_name,
                            'mean_grade': 0.0,
                            'grade': ''
                        })
                        continue
                    placeholders = ','.join(['%s'] * len(all_slot_ids))
                    cur2.execute("""
                        SELECT COALESCE(AVG(
                            (100 * CAST(sm.marks AS DECIMAL(16,8)))
                            / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)
                        ), 0) AS mean_grade, COUNT(*) AS cnt
                        FROM student_marks sm
                        INNER JOIN subjects sub ON sm.subject_id = sub.id
                        WHERE sm.subject_id = %s AND sm.exam_id IN (""" + placeholders + """)
                    """, [subj_id] + all_slot_ids)
                    mrow = cur2.fetchone()
                    mean_grade = float(mrow.get('mean_grade', 0) if isinstance(mrow, dict) else (mrow[0] if mrow and len(mrow) > 0 else 0))
                    teacher_analytics_list.append({
                        'subject_name': subj.get('subject_name') or '—',
                        'supervisor_name': supervisor_name,
                        'mean_grade': mean_grade,
                        'grade': _grade_for_mark(subj_id, mean_grade)
                    })
                teacher_analytics_list.sort(key=lambda x: x['mean_grade'], reverse=True)
                top_teachers = [{
                    'position': i,
                    'subject_name': t['subject_name'],
                    'supervisor_name': t['supervisor_name'],
                    'mean_grade': t['mean_grade'],
                    'grade': t.get('grade', '')
                } for i, t in enumerate(teacher_analytics_list, 1)]
        except Exception as e:
            _schema_ignore_existing(e, 'students_marks/subject_analytics')
            students_marks = []
            subject_analytics = []
            class_mean = 0.0
            class_mean_grade = ''
            top_teachers = []
        selected_level_name = (level_scope.get('display_name') or '—') if level_scope else ''
        if level_scope and not level_scope.get('is_combined_view'):
            lcat = level_scope.get('level_category') or ''
            if lcat:
                selected_level_name = f"{selected_level_name} ({lcat})"
        first_row = rows[0] if rows else row
        exam_summary = {
            'exam_name': exam_name,
            'exam_date': exam_date_str,
            'exam_type': first_row.get('exam_type', '') if isinstance(first_row, dict) else (first_row[2] if len(first_row) > 2 else ''),
            'level_name': selected_level_name or (first_row.get('level_name', '') if isinstance(first_row, dict) else (first_row[13] if len(first_row) > 13 else '')),
            'term_name': first_row.get('term_name', '') if isinstance(first_row, dict) else (first_row[18] if len(first_row) > 18 else ''),
            'year_name': first_row.get('year_name', '') if isinstance(first_row, dict) else (first_row[17] if len(first_row) > 17 else ''),
            'status': first_row.get('status', '') if isinstance(first_row, dict) else (first_row[11] if len(first_row) > 11 else ''),
        }
    except Exception as e:
        print(f"Error fetching exam detail: {e}")
        flash('Error loading exam details.', 'error')
        return redirect(url_for('exam_analytics'))
    finally:
        connection.close()
    return render_template(
        'dashboards/exam_analytics_detail.html',
        role=user_role,
        exam=exam_summary,
        slots=slots,
        distinct_subjects=distinct_subjects,
        distinct_subjects_students=distinct_subjects_students,
        top_teachers=top_teachers,
        exam_id=exam_id,
        levels=levels,
        selected_level_id=selected_level_id,
        students_marks=students_marks,
        subject_analytics=subject_analytics,
        class_mean=class_mean,
        class_mean_grade=class_mean_grade,
        is_academic_coordinator=is_academic_coordinator,
        level_view=level_view,
        level_combinations=level_combinations,
        is_combined_level_view=bool(level_scope and level_scope.get('is_combined_view')),
        combined_member_level_names=level_scope.get('level_names') if level_scope and level_scope.get('is_combined_view') else [],
    )

# Exam Analytics - single class/subject analytics (mean grade, position, top teachers)
@app.route('/dashboard/employee/exam-analytics/exam/<int:exam_id>/slot/<int:slot_id>')
@login_required
def exam_analytics_slot(exam_id, slot_id):
    """View analytics for one class (subject): mean grade, position, top ranking teachers."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_teacher = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_teacher or is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    connection = get_db_connection()
    if not connection:
        flash('Database error.', 'error')
        return redirect(url_for('exam_analytics'))
    try:
        with connection.cursor() as cursor:
            ensure_subject_exam_total_marks_column(cursor)
            cursor.execute("""
                SELECT e.id, e.subject_id, e.supervisor_id, e.exam_name, e.exam_date,
                       s.subject_name, s.subject_code, emp.full_name as supervisor_name
                FROM exams e
                LEFT JOIN subjects s ON e.subject_id = s.id
                LEFT JOIN employees emp ON e.supervisor_id = emp.id
                WHERE e.id = %s
            """, (slot_id,))
            row = cursor.fetchone()
            if not row:
                flash('Class/slot not found.', 'error')
                return redirect(url_for('exam_analytics_detail', exam_id=exam_id))
            subject_name = (row.get('subject_name') or row.get('subject_code') or '') if isinstance(row, dict) else (row[5] or row[6] or '')
            exam_name = row.get('exam_name', '') if isinstance(row, dict) else row[3]
            exam_date_val = row.get('exam_date') if isinstance(row, dict) else row[4]
            exam_date_str = exam_date_val.strftime('%Y-%m-%d') if exam_date_val and hasattr(exam_date_val, 'strftime') else str(exam_date_val) if exam_date_val else ''
            supervisor_name = row.get('supervisor_name', '') if isinstance(row, dict) else (row[7] if len(row) > 7 else '')
            cursor.execute("""
                SELECT COALESCE(AVG(
                    (100 * CAST(sm.marks AS DECIMAL(16,8)))
                    / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)
                ), 0) AS mean_grade, COUNT(*) AS count_marks
                FROM student_marks sm
                INNER JOIN exams ex ON sm.exam_id = ex.id
                INNER JOIN subjects sub ON ex.subject_id = sub.id
                WHERE sm.exam_id = %s
            """, (slot_id,))
            m = cursor.fetchone()
            mean_grade = float(m.get('mean_grade', 0) if isinstance(m, dict) else (m[0] if m and len(m) > 0 else 0))
            count_marks = int(m.get('count_marks', 0) if isinstance(m, dict) else (m[1] if m and len(m) > 1 else 0))
            cursor.execute("""
                SELECT e.id, e.subject_id, e.supervisor_id,
                       s.subject_name, s.subject_code, emp.full_name as supervisor_name
                FROM exams e
                LEFT JOIN subjects s ON e.subject_id = s.id
                LEFT JOIN employees emp ON e.supervisor_id = emp.id
                WHERE e.exam_name = %s AND e.exam_date = %s AND e.academic_year_id = (SELECT academic_year_id FROM exams WHERE id = %s)
                  AND e.term_id = (SELECT term_id FROM exams WHERE id = %s) AND e.academic_level_id = (SELECT academic_level_id FROM exams WHERE id = %s)
            """, (exam_name, exam_date_val, slot_id, slot_id, slot_id))
            all_slots = cursor.fetchall()
            slot_means = []
            for r in all_slots:
                sid = r.get('id') if isinstance(r, dict) else r[0]
                cursor.execute("""
                    SELECT COALESCE(AVG(
                        (100 * CAST(sm.marks AS DECIMAL(16,8)))
                        / COALESCE(NULLIF(sub.exam_total_marks, 0), 100)
                    ), 0) AS mean_grade
                    FROM student_marks sm
                    INNER JOIN exams ex ON sm.exam_id = ex.id
                    INNER JOIN subjects sub ON ex.subject_id = sub.id
                    WHERE sm.exam_id = %s
                """, (sid,))
                mm = cursor.fetchone()
                smean = float(mm.get('mean_grade', mm[0] if mm and len(mm) > 0 else 0) if isinstance(mm, dict) else (float(mm[0]) if mm and len(mm) > 0 else 0))
                sname = (r.get('subject_name') or r.get('subject_code') or '') if isinstance(r, dict) else (r[4] or r[5] or '')
                sup_name = r.get('supervisor_name', '') if isinstance(r, dict) else (r[6] if len(r) > 6 else '')
                slot_means.append({'slot_id': sid, 'subject_name': sname, 'supervisor_name': sup_name, 'mean_grade': smean})
            slot_means.sort(key=lambda x: x['mean_grade'], reverse=True)
            position = 0
            for idx, s in enumerate(slot_means, 1):
                if s['slot_id'] == slot_id:
                    position = idx
                    break
            top_teachers = [{'position': i, 'subject_name': s['subject_name'], 'supervisor_name': s['supervisor_name'] or '—', 'mean_grade': s['mean_grade']} for i, s in enumerate(slot_means, 1)]
        exam_summary = {'exam_name': exam_name, 'exam_date': exam_date_str}
    except Exception as e:
        print(f"Error fetching slot analytics: {e}")
        flash('Error loading class analytics.', 'error')
        return redirect(url_for('exam_analytics_detail', exam_id=exam_id))
    finally:
        connection.close()
    return render_template('dashboards/exam_analytics_slot.html', role=user_role, exam=exam_summary, slot_id=slot_id,
                          subject_name=subject_name, supervisor_name=supervisor_name, mean_grade=mean_grade,
                          count_marks=count_marks, position=position, top_teachers=top_teachers, exam_id=exam_id)

# Students by Academic Level Route
@app.route('/dashboard/employee/exams-assessments/level/<int:level_id>/students')
@login_required
def students_by_academic_level(level_id):
    """Display all students for a specific academic level"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_deputy or is_teacher or is_secretary):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get teacher ID for filtering subjects (for teachers)
    teacher_id = None
    if is_teacher:
        if is_technician:
            # Technician viewing as teacher - use viewing_as_employee_id
            teacher_id = session.get('viewing_as_employee_id')
        else:
            # Actual teacher - use their own user_id (database primary key)
            teacher_id = session.get('user_id')
    
    # Fetch academic level details
    connection = get_db_connection()
    academic_level = None
    students = []
    subjects = []
    subjects_for_edit = []
    exams = []
    student_marks = {}
    initial_grade_code_remarks = {}
    academic_years = []
    terms = []
    default_grade_bands = []
    subject_grade_bands = {}
    class_grade_bands = {}
    subject_exam_max_map_base = {}
    combination_column_members = {}
    teacher_editable_subject_ids = set()
    teacher_subject_ids_list = []
    current_year_id = None
    current_term_id = None
    registered_current_exam_pick = None

    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_marks_sheet_schema(cursor)
                registered_current_exam_pick = load_registered_current_exam_dict(cursor)
                # Get academic level information
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description, level_status
                    FROM academic_levels
                    WHERE id = %s
                """, (level_id,))
                level_result = cursor.fetchone()
                
                if not level_result:
                    flash('Academic level not found.', 'error')
                    if is_deputy:
                        return redirect(employee_dashboard_path('exams-overview'))
                    return redirect(url_for('exams_assessments'))
                
                level_name = level_result.get('level_name') if isinstance(level_result, dict) else level_result[2]
                
                academic_level = {
                    'id': level_result.get('id') if isinstance(level_result, dict) else level_result[0],
                    'level_category': level_result.get('level_category') if isinstance(level_result, dict) else level_result[1],
                    'level_name': level_name,
                    'level_description': level_result.get('level_description') if isinstance(level_result, dict) else level_result[3],
                    'level_status': level_result.get('level_status') if isinstance(level_result, dict) else level_result[4]
                }

                if is_teacher and teacher_id:
                    cursor.execute("""
                        SELECT 1 FROM teacher_subject_assignments
                        WHERE teacher_id = %s AND academic_level_id = %s
                        LIMIT 1
                    """, (teacher_id, level_id))
                    if not cursor.fetchone():
                        flash('You are not allocated to this class for exam marks entry.', 'error')
                        return redirect(employee_dashboard_path('exams-assessments'))
                
                # Get all students with current_grade matching the level_name from students table (simplified - only full_name and student_id)
                cursor.execute("""
                    SELECT s.id, s.student_id, s.full_name
                    FROM students s
                    WHERE s.current_grade = %s
                    ORDER BY s.full_name ASC
                """, (level_name,))
                results = cursor.fetchall()
                
                for row in results:
                    students.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'student_id': row.get('student_id') if isinstance(row, dict) else row[1],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[2]
                    })
                
                if is_teacher and teacher_id:
                    cursor.execute("""
                        SELECT DISTINCT subject_id
                        FROM teacher_subject_assignments
                        WHERE teacher_id = %s AND academic_level_id = %s
                    """, (teacher_id, level_id))
                    teacher_subject_ids_list = [
                        row.get('subject_id') if isinstance(row, dict) else row[0]
                        for row in (cursor.fetchall() or [])
                    ]

                # Get only subjects registered for this academic level:
                # Prefer subjects that appear in exams for this level; else subjects allocated via teacher_subject_assignments
                if is_teacher and teacher_id:
                    # Teacher: subjects from exams for this level that they are assigned to, else their assigned subjects
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status, s.exam_total_marks, s.exam_display_order
                        FROM subjects s
                        INNER JOIN exams e ON e.subject_id = s.id AND e.academic_level_id = %s
                        INNER JOIN teacher_subject_assignments tsa ON tsa.subject_id = s.id AND tsa.academic_level_id = %s AND tsa.teacher_id = %s
                        WHERE s.status = 'active'
                        ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                    """, (level_id, level_id, teacher_id))
                    subjects_results = cursor.fetchall()
                    if not subjects_results:
                        cursor.execute("""
                            SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status, s.exam_total_marks, s.exam_display_order
                            FROM subjects s
                            INNER JOIN teacher_subject_assignments tsa ON s.id = tsa.subject_id
                            WHERE tsa.academic_level_id = %s AND tsa.teacher_id = %s AND s.status = 'active'
                            ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                        """, (level_id, teacher_id))
                        subjects_results = cursor.fetchall()
                else:
                    # Non-teacher: subjects that appear in exams for this level (registered for exams)
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status, s.exam_total_marks, s.exam_display_order
                        FROM subjects s
                        INNER JOIN exams e ON e.subject_id = s.id AND e.academic_level_id = %s
                        WHERE s.status = 'active'
                        ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                    """, (level_id,))
                    subjects_results = cursor.fetchall()
                    if not subjects_results:
                        # Fallback: subjects allocated to this level via subject-class allocation
                        cursor.execute("""
                            SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status, s.exam_total_marks, s.exam_display_order
                            FROM subjects s
                            INNER JOIN teacher_subject_assignments tsa ON s.id = tsa.subject_id
                            WHERE tsa.academic_level_id = %s AND s.status = 'active'
                            ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                        """, (level_id,))
                        subjects_results = cursor.fetchall()
                
                for row in subjects_results:
                    subjects.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'subject_name': row.get('subject_name') if isinstance(row, dict) else row[1],
                        'subject_code': row.get('subject_code') if isinstance(row, dict) else row[2],
                        'description': row.get('description') if isinstance(row, dict) else row[3],
                        'status': row.get('status') if isinstance(row, dict) else row[4],
                        'exam_total_marks': row.get('exam_total_marks') if isinstance(row, dict) else (row[5] if len(row) > 5 else None),
                        'exam_display_order': row.get('exam_display_order') if isinstance(row, dict) else (row[6] if len(row) > 6 else None),
                    })

                subjects_flat = [{**s} for s in subjects]
                subjects_for_edit = list(subjects_flat)
                
                # Get exams for this academic level: unique by exam_name only (one row per exam name)
                # For teachers, only show exams for their assigned subjects
                exams = []
                try:
                    # Load academic years and terms for filters
                    cursor.execute("""
                        SELECT id, year_name, is_current
                        FROM academic_years
                        WHERE status = 'active'
                        ORDER BY is_current DESC, start_date DESC
                    """)
                    for yrow in (cursor.fetchall() or []):
                        year_obj = {
                            'id': yrow.get('id') if isinstance(yrow, dict) else yrow[0],
                            'year_name': yrow.get('year_name', '') if isinstance(yrow, dict) else (yrow[1] if len(yrow) > 1 else ''),
                            'is_current': bool(yrow.get('is_current')) if isinstance(yrow, dict) else bool(yrow[2] if len(yrow) > 2 else False)
                        }
                        academic_years.append(year_obj)
                        if year_obj['is_current'] and not current_year_id:
                            current_year_id = year_obj['id']

                    cursor.execute("""
                        SELECT id, term_name, academic_year_id, is_current
                        FROM terms
                        WHERE status = 'active'
                        ORDER BY academic_year_id DESC, is_current DESC, start_date DESC
                    """)
                    for trow in (cursor.fetchall() or []):
                        term_obj = {
                            'id': trow.get('id') if isinstance(trow, dict) else trow[0],
                            'term_name': trow.get('term_name', '') if isinstance(trow, dict) else (trow[1] if len(trow) > 1 else ''),
                            'academic_year_id': trow.get('academic_year_id') if isinstance(trow, dict) else (trow[2] if len(trow) > 2 else None),
                            'is_current': bool(trow.get('is_current')) if isinstance(trow, dict) else bool(trow[3] if len(trow) > 3 else False)
                        }
                        terms.append(term_obj)
                        if term_obj['is_current'] and not current_term_id:
                            current_term_id = term_obj['id']

                    try:
                        if is_teacher and teacher_id:
                            cursor.execute("""
                                SELECT e.exam_name, MIN(e.id) AS id,
                                       e.academic_year_id, e.term_id,
                                       MAX(e.exam_date) AS exam_date,
                                       MAX(COALESCE(e.is_locked, 0)) AS is_locked,
                                       MAX(e.marks_lock_at) AS marks_lock_at,
                                       MAX(e.exam_type) AS exam_type
                                FROM exams e
                                INNER JOIN teacher_subject_assignments tsa ON e.academic_level_id = tsa.academic_level_id 
                                    AND e.subject_id = tsa.subject_id
                                WHERE e.academic_level_id = %s 
                                  AND tsa.teacher_id = %s
                                GROUP BY e.exam_name, e.academic_year_id, e.term_id
                                ORDER BY e.academic_year_id DESC, e.term_id DESC, e.exam_name ASC
                            """, (level_id, teacher_id))
                        else:
                            cursor.execute("""
                                SELECT exam_name, MIN(id) AS id, academic_year_id, term_id, MAX(exam_date) AS exam_date,
                                       MAX(COALESCE(is_locked, 0)) AS is_locked,
                                       MAX(marks_lock_at) AS marks_lock_at,
                                       MAX(exam_type) AS exam_type
                                FROM exams
                                WHERE academic_level_id = %s
                                GROUP BY exam_name, academic_year_id, term_id
                                ORDER BY academic_year_id DESC, term_id DESC, exam_name ASC
                            """, (level_id,))
                    except Exception:
                        # Backward compatibility when exams.is_locked / marks_lock_at is missing.
                        if is_teacher and teacher_id:
                            cursor.execute("""
                                SELECT e.exam_name, MIN(e.id) AS id,
                                       e.academic_year_id, e.term_id,
                                       MAX(e.exam_date) AS exam_date,
                                       0 AS is_locked, NULL AS marks_lock_at
                                FROM exams e
                                INNER JOIN teacher_subject_assignments tsa ON e.academic_level_id = tsa.academic_level_id 
                                    AND e.subject_id = tsa.subject_id
                                WHERE e.academic_level_id = %s 
                                  AND tsa.teacher_id = %s
                                GROUP BY e.exam_name, e.academic_year_id, e.term_id
                                ORDER BY e.academic_year_id DESC, e.term_id DESC, e.exam_name ASC
                            """, (level_id, teacher_id))
                        else:
                            cursor.execute("""
                                SELECT exam_name, MIN(id) AS id, academic_year_id, term_id, MAX(exam_date) AS exam_date,
                                       0 AS is_locked, NULL AS marks_lock_at
                                FROM exams
                                WHERE academic_level_id = %s
                                GROUP BY exam_name, academic_year_id, term_id
                                ORDER BY academic_year_id DESC, term_id DESC, exam_name ASC
                            """, (level_id,))
                    exams_results = cursor.fetchall()
                    for row in exams_results:
                        exam_name = (row.get('exam_name', '') or '').strip() if isinstance(row, dict) else (row[0] or '').strip()
                        if not exam_name:
                            continue
                        mla_raw = row.get('marks_lock_at') if isinstance(row, dict) else (row[6] if len(row) > 6 else None)
                        if mla_raw and hasattr(mla_raw, 'strftime'):
                            marks_lock_at_str = mla_raw.strftime('%Y-%m-%dT%H:%M:%S')
                        else:
                            marks_lock_at_str = str(mla_raw) if mla_raw else None
                        exams.append({
                            'id': row.get('id') if isinstance(row, dict) else row[1],
                            'exam_name': exam_name,
                            'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else (row[2] if len(row) > 2 else None),
                            'term_id': row.get('term_id') if isinstance(row, dict) else (row[3] if len(row) > 3 else None),
                            'exam_date': str(row.get('exam_date')) if isinstance(row, dict) and row.get('exam_date') else (str(row[4]) if len(row) > 4 and row[4] else ''),
                            'is_locked': bool(row.get('is_locked')) if isinstance(row, dict) else bool(row[5] if len(row) > 5 else False),
                            'marks_lock_at': marks_lock_at_str,
                            'exam_type': (row.get('exam_type') if isinstance(row, dict) else (row[7] if len(row) > 7 else None)) or '',
                        })
                except Exception as e:
                    print(f"Error fetching exams: {e}")
                    exams = []

                # Resolve selected exam inside DB block so subject columns use frozen per-exam settings.
                sheet_year_id = request.args.get('year', type=int)
                sheet_term_id = request.args.get('term', type=int)
                sheet_exam_id = request.args.get('exam', type=int)
                sheet_year_default = current_year_id
                sheet_term_default = current_term_id
                sheet_exam_default = None
                if exams or registered_current_exam_pick:
                    sheet_year_default, sheet_term_default, sheet_exam_default = (
                        _resolve_marks_sheet_filter_defaults(
                            exams, registered_current_exam_pick, current_year_id, current_term_id,
                        )
                    )
                sheet_year_id = sheet_year_id if sheet_year_id is not None else sheet_year_default
                sheet_term_id = sheet_term_id if sheet_term_id is not None else sheet_term_default
                sheet_exam_id = sheet_exam_id if sheet_exam_id is not None else sheet_exam_default
                sheet_exam_name = None
                sheet_exam_type = None
                if sheet_exam_id and exams:
                    for ex in exams:
                        if str(ex.get('id')) == str(sheet_exam_id):
                            sheet_exam_name = (ex.get('exam_name') or '').strip()
                            sheet_exam_type = (ex.get('exam_type') or '').strip() or None
                            sheet_year_id = ex.get('academic_year_id') or sheet_year_id
                            sheet_term_id = ex.get('term_id') or sheet_term_id
                            break

                # One snapshot read for all subjects (avoids N identical context queries).
                sheet_use_live = _should_use_live_exam_settings(
                    sheet_exam_name, sheet_year_id, sheet_term_id,
                    registered_current_exam_pick, sheet_exam_type,
                )
                sheet_totals_snap = None
                if (
                    not sheet_use_live
                    and sheet_exam_name and sheet_year_id and sheet_term_id
                ):
                    sheet_totals_snap = get_exam_context_settings_snapshot(
                        cursor, sheet_exam_name, sheet_year_id, sheet_term_id, level_id,
                    )
                sheet_totals_map = (
                    (sheet_totals_snap or {}).get('subject_exam_totals') or {}
                ) if sheet_totals_snap else {}
                for s in subjects_flat:
                    sid = int(s['id'])
                    if sheet_totals_map:
                        snap_val = sheet_totals_map.get(str(sid))
                        if snap_val is not None:
                            s['exam_total_marks'] = snap_val

                combinations_loaded = fetch_subject_exam_combinations_for_context(
                    cursor, sheet_exam_name, sheet_year_id, sheet_term_id, level_id,
                    registered_current=registered_current_exam_pick,
                    exam_type=sheet_exam_type,
                )
                level_cat = (academic_level.get('level_category') or '').strip() or 'Uncategorized'
                id_to_gc, section_order = sort_subjects_list_for_exam_columns_for_context(
                    cursor, subjects_flat,
                    sheet_exam_name, sheet_year_id, sheet_term_id, level_id,
                    registered_current=registered_current_exam_pick,
                    exam_type=sheet_exam_type,
                    force_group_category=level_cat,
                )
                # Keep the subject picker / edit list in the same set column order.
                subjects_for_edit = [{**s} for s in subjects_flat]
                subject_exam_max_map_base = {
                    int(s['id']): subject_exam_max_raw_marks(s.get('exam_total_marks'))
                    for s in subjects_flat
                }
                if is_teacher and teacher_id:
                    subjects, combination_column_members, teacher_editable_subject_ids = (
                        expand_teacher_marks_sheet_subjects(
                            subjects_flat, combinations_loaded, teacher_subject_ids_list, cursor,
                        )
                    )
                elif is_principal:
                    # Principals enter each paper separately. Live Σ% =
                    # Σ(pct×max)/Σ(max) so /30 + /50 combine correctly. Do not collapse to one
                    # editable % cell (that blanked inputs and overwrote both papers).
                    all_subject_ids = [int(s['id']) for s in subjects_flat]
                    subjects, combination_column_members, teacher_editable_subject_ids = (
                        expand_teacher_marks_sheet_subjects(
                            subjects_flat, combinations_loaded, all_subject_ids, cursor,
                        )
                    )
                else:
                    subjects = merge_subjects_with_exam_combinations(
                        subjects_flat,
                        combinations_loaded,
                        id_to_gc=id_to_gc,
                        section_order=section_order,
                    )
                
                # Marks load via AJAX (get-marks) for the selected exam only —
                # do not preload all-exam marks into the HTML response.
                student_marks = {}

                # Grade-code remarks for the selected exam (same connection).
                initial_grade_code_remarks = {}
                try:
                    if sheet_exam_name:
                        ensure_grade_code_remarks_table(cursor)
                        initial_grade_code_remarks = fetch_grade_code_remarks_map(
                            cursor,
                            academic_year_id=sheet_year_id,
                            term_id=sheet_term_id,
                            academic_level_ids=[level_id],
                            exam_name=sheet_exam_name,
                        )
                except Exception as e:
                    _schema_ignore_existing(e, 'initial grade remarks skipped')
                    initial_grade_code_remarks = {}

        except Exception as e:
            print(f"Error fetching students by academic level: {e}")
            flash('Error loading students. Please try again.', 'error')
        finally:
            connection.close()
    else:
        flash('Database connection failed.', 'error')
        return redirect(url_for('exams_assessments'))
    
    # Resolve year/term/exam defaults — school registered current exam takes priority.
    if not current_year_id and academic_years:
        current_year_id = academic_years[0].get('id')

    if not current_term_id:
        if current_year_id:
            year_terms = [t for t in terms if str(t.get('academic_year_id')) == str(current_year_id)]
            current_term = next((t for t in year_terms if t.get('is_current')), None)
            if current_term:
                current_term_id = current_term.get('id')
            elif year_terms:
                current_term_id = year_terms[0].get('id')
        if not current_term_id and terms:
            current_term_id = terms[0].get('id')

    selected_exam_id = None
    if exams or registered_current_exam_pick:
        current_year_id, current_term_id, selected_exam_id = _resolve_marks_sheet_filter_defaults(
            exams, registered_current_exam_pick, current_year_id, current_term_id,
        )

    year_q = request.args.get('year', type=int)
    term_q = request.args.get('term', type=int)
    exam_q = request.args.get('exam', type=int)
    if year_q is not None:
        current_year_id = year_q
    if term_q is not None:
        current_term_id = term_q
    if exam_q is not None:
        selected_exam_id = exam_q

    marks_filters_from_url = year_q is not None or term_q is not None or exam_q is not None

    # Teachers and principals may enter/edit marks inline on the full sheet.
    # Curriculum coordinators edit one subject at a time on a dedicated page.
    is_cc = is_academic_coordinator
    can_edit = is_teacher or is_principal

    subject_exam_max_map = dict(subject_exam_max_map_base)
    for s in subjects:
        if s.get('combination_role') == 'total' or s.get('combination_id') and int(s.get('id') or 0) < 0:
            subject_exam_max_map[int(s['id'])] = 100.0
            combination_column_members[str(int(s['id']))] = [int(x) for x in (s.get('member_subject_ids') or [])]
        elif s.get('combination_id') and s.get('combination_role') != 'total':
            pass
        elif s.get('combination_id'):
            subject_exam_max_map[int(s['id'])] = 100.0
            combination_column_members[str(int(s['id']))] = [int(x) for x in (s.get('member_subject_ids') or [])]

    # View-only roles (e.g. curriculum coordinator): scaled /100 cells + total of converted marks.
    marks_display_scaled = not can_edit
    marks_summary_column = 'total_scaled' if marks_display_scaled else 'avg_pct'

    selected_exam_name = ''
    selected_exam_type = None
    if selected_exam_id and exams:
        for ex in exams:
            if str(ex.get('id')) == str(selected_exam_id):
                selected_exam_name = (ex.get('exam_name') or '').strip()
                selected_exam_type = (ex.get('exam_type') or '').strip() or None
                break

    (
        active_grade_bands,
        default_grade_bands,
        subject_grade_bands,
        class_grade_bands,
        uses_class_grading_setting,
        grading_setting_name,
    ) = fetch_grade_bands_for_marks_sheet(
        level_id, selected_exam_name, current_year_id, current_term_id, selected_exam_type,
    )

    return render_template('dashboards/students_by_level.html', 
                         role=user_role,
                         viewing_as_employee_role=viewing_as_role,
                         academic_level=academic_level, 
                         students=students,
                         subjects=subjects,
                         exams=exams,
                         academic_years=academic_years,
                         terms=terms,
                         selected_academic_year_id=current_year_id,
                         selected_term_id=current_term_id,
                         selected_exam_id=selected_exam_id,
                         student_marks=student_marks,
                         default_grade_bands=default_grade_bands,
                         subject_grade_bands=subject_grade_bands,
                         class_grade_bands=class_grade_bands,
                         active_grade_bands=active_grade_bands,
                         uses_class_grading_setting=uses_class_grading_setting,
                         grading_setting_name=grading_setting_name,
                         academic_level_id=level_id,
                         subject_exam_max_map=subject_exam_max_map,
                         combination_column_members=combination_column_members,
                         initial_grade_code_remarks={(f"{k[0]}::{k[1]}"): v for k, v in (initial_grade_code_remarks or {}).items()},
                         can_edit=can_edit,
                         is_cc=is_cc,
                         subjects_for_edit=subjects_for_edit,
                         marks_summary_column=marks_summary_column,
                         marks_display_scaled=marks_display_scaled,
                         is_teacher=is_teacher,
                         teacher_editable_subject_ids=sorted(teacher_editable_subject_ids),
                         registered_current_exam=registered_current_exam_pick,
                         marks_filters_from_url=marks_filters_from_url)


@app.route('/dashboard/employee/exams-assessments/level/<int:level_id>/subject/<int:subject_id>/edit')
@login_required
def students_by_level_subject_edit(level_id, subject_id):
    """Curriculum coordinator: edit marks for one subject on a dedicated page."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_cc = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    if not is_cc:
        flash('You do not have permission to edit marks on this page.', 'error')
        return redirect(employee_dashboard_path(f'exams-assessments/level/{level_id}/students'))

    connection = get_db_connection()
    if not connection:
        flash('Database connection failed.', 'error')
        return redirect(employee_dashboard_path(f'exams-assessments/level/{level_id}/students'))

    academic_level = None
    subject = None
    students = []
    exams = []
    academic_years = []
    terms = []
    student_marks = {}
    current_year_id = None
    current_term_id = None
    selected_exam_id = None
    registered_current_exam_pick = None
    selected_subject_id = None
    subject_exam_max = 100.0

    year_q = request.args.get('year', type=int)
    term_q = request.args.get('term', type=int)
    exam_q = request.args.get('exam', type=int)

    try:
        with connection.cursor() as cursor:
            ensure_subject_exam_total_marks_column(cursor)
            ensure_subject_exam_display_order_columns(cursor)
            ensure_exams_marks_lock_at_column(cursor)
            registered_current_exam_pick = load_registered_current_exam_dict(cursor)

            cursor.execute(
                "SELECT id, level_category, level_name, level_description, level_status FROM academic_levels WHERE id = %s",
                (level_id,),
            )
            level_result = cursor.fetchone()
            if not level_result:
                flash('Academic level not found.', 'error')
                return redirect(employee_dashboard_path('exams-assessments'))
            level_name = level_result.get('level_name') if isinstance(level_result, dict) else level_result[2]
            academic_level = {
                'id': level_result.get('id') if isinstance(level_result, dict) else level_result[0],
                'level_category': level_result.get('level_category') if isinstance(level_result, dict) else level_result[1],
                'level_name': level_name,
                'level_description': level_result.get('level_description') if isinstance(level_result, dict) else level_result[3],
                'level_status': level_result.get('level_status') if isinstance(level_result, dict) else level_result[4],
            }

            cursor.execute(
                """
                SELECT id, subject_name, subject_code, description, status, exam_total_marks, exam_display_order
                FROM subjects
                WHERE id = %s AND status = 'active'
                """,
                (subject_id,),
            )
            sub_row = cursor.fetchone()
            if not sub_row:
                flash('Subject not found.', 'error')
                return redirect(employee_dashboard_path(f'exams-assessments/level/{level_id}/students'))
            subject = {
                'id': sub_row.get('id') if isinstance(sub_row, dict) else sub_row[0],
                'subject_name': sub_row.get('subject_name') if isinstance(sub_row, dict) else sub_row[1],
                'subject_code': sub_row.get('subject_code') if isinstance(sub_row, dict) else sub_row[2],
                'description': sub_row.get('description') if isinstance(sub_row, dict) else sub_row[3],
                'status': sub_row.get('status') if isinstance(sub_row, dict) else sub_row[4],
                'exam_total_marks': sub_row.get('exam_total_marks') if isinstance(sub_row, dict) else sub_row[5],
                'exam_display_order': sub_row.get('exam_display_order') if isinstance(sub_row, dict) else (sub_row[6] if len(sub_row) > 6 else None),
            }
            subjects = [subject]
            subject_exam_max = subject_exam_max_raw_marks(subject.get('exam_total_marks'))
            subject_exam_max_map = {int(subject_id): subject_exam_max}
            combination_column_members = {}
            subjects_for_edit = []

            cursor.execute(
                """
                SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status,
                       s.exam_total_marks, s.exam_display_order
                FROM subjects s
                INNER JOIN exams e ON e.subject_id = s.id AND e.academic_level_id = %s
                WHERE s.status = 'active'
                ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                """,
                (level_id,),
            )
            subjects_for_edit_results = cursor.fetchall() or []
            if not subjects_for_edit_results:
                cursor.execute(
                    """
                    SELECT DISTINCT s.id, s.subject_name, s.subject_code, s.description, s.status,
                           s.exam_total_marks, s.exam_display_order
                    FROM subjects s
                    INNER JOIN teacher_subject_assignments tsa ON s.id = tsa.subject_id
                    WHERE tsa.academic_level_id = %s AND s.status = 'active'
                    ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC, s.subject_name ASC
                    """,
                    (level_id,),
                )
                subjects_for_edit_results = cursor.fetchall() or []
            for row in subjects_for_edit_results:
                subjects_for_edit.append({
                    'id': row.get('id') if isinstance(row, dict) else row[0],
                    'subject_name': row.get('subject_name') if isinstance(row, dict) else row[1],
                    'subject_code': row.get('subject_code') if isinstance(row, dict) else row[2],
                    'description': row.get('description') if isinstance(row, dict) else row[3],
                    'status': row.get('status') if isinstance(row, dict) else row[4],
                    'exam_total_marks': row.get('exam_total_marks') if isinstance(row, dict) else row[5],
                    'exam_display_order': row.get('exam_display_order') if isinstance(row, dict) else (row[6] if len(row) > 6 else None),
                })

            cursor.execute(
                """
                SELECT 1 FROM exams
                WHERE academic_level_id = %s AND subject_id = %s
                LIMIT 1
                """,
                (level_id, subject_id),
            )
            if not cursor.fetchone():
                cursor.execute(
                    """
                    SELECT 1 FROM teacher_subject_assignments
                    WHERE academic_level_id = %s AND subject_id = %s
                    LIMIT 1
                    """,
                    (level_id, subject_id),
                )
                if not cursor.fetchone():
                    flash('This subject is not registered for this class.', 'error')
                    return redirect(employee_dashboard_path(f'exams-assessments/level/{level_id}/students'))

            cursor.execute(
                """
                SELECT s.id, s.student_id, s.full_name
                FROM students s
                WHERE s.current_grade = %s
                ORDER BY s.full_name ASC
                """,
                (level_name,),
            )
            for row in cursor.fetchall() or []:
                students.append({
                    'id': row.get('id') if isinstance(row, dict) else row[0],
                    'student_id': row.get('student_id') if isinstance(row, dict) else row[1],
                    'full_name': row.get('full_name') if isinstance(row, dict) else row[2],
                })

            cursor.execute(
                """
                SELECT id, year_name, is_current FROM academic_years
                WHERE status = 'active'
                ORDER BY is_current DESC, start_date DESC
                """
            )
            for yrow in cursor.fetchall() or []:
                year_obj = {
                    'id': yrow.get('id') if isinstance(yrow, dict) else yrow[0],
                    'year_name': yrow.get('year_name', '') if isinstance(yrow, dict) else (yrow[1] if len(yrow) > 1 else ''),
                    'is_current': bool(yrow.get('is_current')) if isinstance(yrow, dict) else bool(yrow[2] if len(yrow) > 2 else False),
                }
                academic_years.append(year_obj)
                if year_obj['is_current'] and not current_year_id:
                    current_year_id = year_obj['id']

            cursor.execute(
                """
                SELECT id, term_name, academic_year_id, is_current FROM terms
                WHERE status = 'active'
                ORDER BY academic_year_id DESC, is_current DESC, start_date DESC
                """
            )
            for trow in cursor.fetchall() or []:
                term_obj = {
                    'id': trow.get('id') if isinstance(trow, dict) else trow[0],
                    'term_name': trow.get('term_name', '') if isinstance(trow, dict) else (trow[1] if len(trow) > 1 else ''),
                    'academic_year_id': trow.get('academic_year_id') if isinstance(trow, dict) else (trow[2] if len(trow) > 2 else None),
                    'is_current': bool(trow.get('is_current')) if isinstance(trow, dict) else bool(trow[3] if len(trow) > 3 else False),
                }
                terms.append(term_obj)
                if term_obj['is_current'] and not current_term_id:
                    current_term_id = term_obj['id']

            try:
                cursor.execute(
                    """
                    SELECT exam_name, MIN(id) AS id, academic_year_id, term_id, MAX(exam_date) AS exam_date,
                           MAX(COALESCE(is_locked, 0)) AS is_locked,
                           MAX(marks_lock_at) AS marks_lock_at,
                           MAX(exam_type) AS exam_type
                    FROM exams
                    WHERE academic_level_id = %s
                    GROUP BY exam_name, academic_year_id, term_id
                    ORDER BY academic_year_id DESC, term_id DESC, exam_name ASC
                    """,
                    (level_id,),
                )
            except Exception:
                cursor.execute(
                    """
                    SELECT exam_name, MIN(id) AS id, academic_year_id, term_id, MAX(exam_date) AS exam_date,
                           0 AS is_locked, NULL AS marks_lock_at, NULL AS exam_type
                    FROM exams
                    WHERE academic_level_id = %s
                    GROUP BY exam_name, academic_year_id, term_id
                    ORDER BY academic_year_id DESC, term_id DESC, exam_name ASC
                    """,
                    (level_id,),
                )
            for row in cursor.fetchall() or []:
                exam_name = (row.get('exam_name', '') or '').strip() if isinstance(row, dict) else (row[0] or '').strip()
                if not exam_name:
                    continue
                mla_raw = row.get('marks_lock_at') if isinstance(row, dict) else (row[6] if len(row) > 6 else None)
                if mla_raw and hasattr(mla_raw, 'strftime'):
                    marks_lock_at_str = mla_raw.strftime('%Y-%m-%dT%H:%M:%S')
                else:
                    marks_lock_at_str = str(mla_raw) if mla_raw else None
                exams.append({
                    'id': row.get('id') if isinstance(row, dict) else row[1],
                    'exam_name': exam_name,
                    'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else (row[2] if len(row) > 2 else None),
                    'term_id': row.get('term_id') if isinstance(row, dict) else (row[3] if len(row) > 3 else None),
                    'exam_date': str(row.get('exam_date')) if isinstance(row, dict) and row.get('exam_date') else (str(row[4]) if len(row) > 4 and row[4] else ''),
                    'is_locked': bool(row.get('is_locked')) if isinstance(row, dict) else bool(row[5] if len(row) > 5 else False),
                    'marks_lock_at': marks_lock_at_str,
                    'exam_type': (row.get('exam_type') if isinstance(row, dict) else (row[7] if len(row) > 7 else None)) or '',
                })

            try:
                cursor.execute(
                    """
                    SELECT sm.student_id, sm.subject_id, sm.marks, sm.exam_id
                    FROM student_marks sm
                    INNER JOIN students s ON sm.student_id = s.student_id
                    WHERE s.current_grade = %s AND sm.subject_id = %s
                    """,
                    (level_name, subject_id),
                )
                for mark_row in cursor.fetchall() or []:
                    sid = mark_row.get('student_id') if isinstance(mark_row, dict) else mark_row[0]
                    sub_id = mark_row.get('subject_id') if isinstance(mark_row, dict) else mark_row[1]
                    marks_val = mark_row.get('marks') if isinstance(mark_row, dict) else mark_row[2]
                    ex_id = mark_row.get('exam_id') if isinstance(mark_row, dict) else mark_row[3]
                    if sid not in student_marks:
                        student_marks[sid] = {}
                    if sub_id not in student_marks[sid]:
                        student_marks[sid][sub_id] = {}
                    student_marks[sid][sub_id][ex_id] = marks_val
            except Exception as e:
                print(f"subject edit marks load: {e}")
    except Exception as e:
        print(f"students_by_level_subject_edit: {e}")
        flash('Error loading marks editor.', 'error')
        return redirect(employee_dashboard_path(f'exams-assessments/level/{level_id}/students'))
    finally:
        connection.close()

    if not current_year_id and academic_years:
        current_year_id = academic_years[0].get('id')
    if not current_term_id:
        if current_year_id:
            year_terms = [t for t in terms if str(t.get('academic_year_id')) == str(current_year_id)]
            current_term = next((t for t in year_terms if t.get('is_current')), None)
            current_term_id = (current_term or (year_terms[0] if year_terms else {})).get('id')
        if not current_term_id and terms:
            current_term_id = terms[0].get('id')

    if exams or registered_current_exam_pick:
        current_year_id, current_term_id, selected_exam_id = _resolve_marks_sheet_filter_defaults(
            exams, registered_current_exam_pick, current_year_id, current_term_id,
        )

    if year_q is not None:
        current_year_id = year_q
    if term_q is not None:
        current_term_id = term_q
    if exam_q is not None:
        selected_exam_id = exam_q

    marks_filters_from_url = year_q is not None or term_q is not None or exam_q is not None

    sheet_back_url = employee_dashboard_path(f'exams-assessments/level/{level_id}/students')
    sheet_back_qs = []
    if current_year_id is not None:
        sheet_back_qs.append(f'year={current_year_id}')
    if current_term_id is not None:
        sheet_back_qs.append(f'term={current_term_id}')
    if selected_exam_id is not None:
        sheet_back_qs.append(f'exam={selected_exam_id}')
    if sheet_back_qs:
        sheet_back_url += '?' + '&'.join(sheet_back_qs)

    selected_exam_name = ''
    selected_exam_type = None
    if selected_exam_id and exams:
        for ex in exams:
            if str(ex.get('id')) == str(selected_exam_id):
                selected_exam_name = (ex.get('exam_name') or '').strip()
                selected_exam_type = (ex.get('exam_type') or '').strip() or None
                break

    (
        active_grade_bands,
        default_grade_bands,
        subject_grade_bands,
        class_grade_bands,
        uses_class_grading_setting,
        grading_setting_name,
    ) = fetch_grade_bands_for_marks_sheet(
        level_id, selected_exam_name, current_year_id, current_term_id, selected_exam_type,
    )

    initial_grade_code_remarks = {}
    try:
        if selected_exam_name:
            connection2 = get_db_connection()
            if connection2:
                try:
                    with connection2.cursor() as cur2:
                        ensure_grade_code_remarks_table(cur2)
                        initial_grade_code_remarks = fetch_grade_code_remarks_map(
                            cur2,
                            academic_year_id=current_year_id,
                            term_id=current_term_id,
                            academic_level_ids=[level_id],
                            exam_name=selected_exam_name,
                        )
                finally:
                    connection2.close()
    except Exception as e:
        _schema_ignore_existing(e, 'initial grade remarks skipped')

    return render_template(
        'dashboards/students_by_level.html',
        role=user_role,
        viewing_as_employee_role=viewing_as_role,
        academic_level=academic_level,
        students=students,
        subjects=subjects,
        exams=exams,
        academic_years=academic_years,
        terms=terms,
        selected_academic_year_id=current_year_id,
        selected_term_id=current_term_id,
        selected_exam_id=selected_exam_id,
        student_marks=student_marks,
        default_grade_bands=default_grade_bands,
        active_grade_bands=active_grade_bands,
        subject_grade_bands=subject_grade_bands,
        class_grade_bands=class_grade_bands,
        uses_class_grading_setting=uses_class_grading_setting,
        grading_setting_name=grading_setting_name,
        academic_level_id=level_id,
        subject_exam_max_map=subject_exam_max_map,
        combination_column_members=combination_column_members,
        initial_grade_code_remarks={(f"{k[0]}::{k[1]}"): v for k, v in (initial_grade_code_remarks or {}).items()},
        can_edit=True,
        is_cc=True,
        is_teacher=False,
        subjects_for_edit=subjects_for_edit,
        marks_summary_column='avg_pct',
        marks_display_scaled=False,
        registered_current_exam=registered_current_exam_pick,
        cc_single_subject_edit=True,
        cc_selected_subject_id=subject_id,
        edit_subject=subject,
        edit_subject_exam_max=subject_exam_max,
        sheet_back_url=sheet_back_url,
        marks_filters_from_url=marks_filters_from_url,
    )


@app.route('/dashboard/employee/exams-assessments/grade-remarks/get', methods=['POST'])
@login_required
def exams_assessments_get_grade_remarks():
    """Fetch saved grade-code remarks for a given exam context."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    if not (is_academic_coordinator or is_technician or is_principal or is_deputy or is_teacher or is_secretary):
        return jsonify({'success': False, 'message': 'Forbidden'}), 403

    data = request.get_json(silent=True) or {}
    academic_level_id = _coerce_int_or_none(data.get('academic_level_id'))
    academic_year_id = _coerce_int_or_none(data.get('academic_year_id'))
    term_id = _coerce_int_or_none(data.get('term_id'))
    exam_name = (data.get('exam_name') or '').strip()
    if not academic_level_id or not exam_name:
        return jsonify({'success': False, 'message': 'academic_level_id and exam_name are required'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500
    try:
        with connection.cursor() as cursor:
            ensure_grade_code_remarks_table(cursor)
            mp = fetch_grade_code_remarks_map(
                cursor,
                academic_year_id=academic_year_id,
                term_id=term_id,
                academic_level_ids=[academic_level_id],
                exam_name=exam_name,
            )
            out = {f"{k[0]}::{k[1]}": v for k, v in (mp or {}).items()}
            return jsonify({'success': True, 'remarks': out})
    except Exception as e:
        print(f"exams_assessments_get_grade_remarks: {e}")
        return jsonify({'success': False, 'message': 'Could not load remarks'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/exams-assessments/grade-remarks/save', methods=['POST'])
@login_required
def exams_assessments_save_grade_remarks():
    """Upsert grade-code remarks for a given exam context."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    if not (is_technician or is_principal or is_teacher or is_academic_coordinator):
        return jsonify({'success': False, 'message': 'Forbidden'}), 403

    data = request.get_json(silent=True) or {}
    academic_level_id = _coerce_int_or_none(data.get('academic_level_id'))
    academic_year_id = _coerce_int_or_none(data.get('academic_year_id'))
    term_id = _coerce_int_or_none(data.get('term_id'))
    exam_name = (data.get('exam_name') or '').strip()
    remarks = data.get('remarks') or {}
    if not academic_level_id or not exam_name:
        return jsonify({'success': False, 'message': 'academic_level_id and exam_name are required'}), 400
    if not isinstance(remarks, dict):
        return jsonify({'success': False, 'message': 'remarks must be an object'}), 400

    updated_by = session.get('user_id')
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500
    try:
        with connection.cursor() as cursor:
            ensure_grade_code_remarks_table(cursor)
            for grade_code_raw, remark_raw in remarks.items():
                gc = (str(grade_code_raw or '').strip().upper())[:32]
                if not gc:
                    continue
                txt = str(remark_raw or '').strip()
                cursor.execute(
                    """
                    INSERT INTO grade_code_remarks
                        (academic_year_id, term_id, academic_level_id, exam_name, grade_code, remark_text, updated_by_employee_id)
                    VALUES (%s, %s, %s, %s, %s, %s, %s)
                    ON DUPLICATE KEY UPDATE
                        remark_text = VALUES(remark_text),
                        updated_by_employee_id = VALUES(updated_by_employee_id),
                        updated_at = CURRENT_TIMESTAMP
                    """,
                    (academic_year_id, term_id, academic_level_id, exam_name, gc, txt, updated_by),
                )
            connection.commit()
        return jsonify({'success': True})
    except Exception as e:
        print(f"exams_assessments_save_grade_remarks: {e}")
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': 'Could not save remarks'}), 500
    finally:
        connection.close()


# API Endpoint to fetch marks filtered by exam
@app.route('/dashboard/employee/exams-assessments/get-marks', methods=['POST'])
@login_required
def get_marks_by_exam():
    """Get marks for students filtered by exam"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_deputy or is_teacher or is_secretary):
        return jsonify({'success': False, 'message': 'You do not have permission to access this.'}), 403
    
    # Get teacher ID for filtering marks (for teachers)
    teacher_id = None
    if is_teacher:
        if is_technician:
            # Technician viewing as teacher - use viewing_as_employee_id
            teacher_id = session.get('viewing_as_employee_id')
        else:
            # Actual teacher - use their own user_id (database primary key)
            teacher_id = session.get('user_id')
    
    try:
        data = request.get_json()
        level_id = data.get('level_id')
        exam_id = data.get('exam_id')  # Can be None for all exams
        
        if not level_id:
            return jsonify({'success': False, 'message': 'Academic level ID is required.'}), 400
        
        connection = get_db_connection()
        student_marks = {}
        
        if connection:
            try:
                with connection.cursor() as cursor:
                    # Get academic level name
                    cursor.execute("""
                        SELECT level_name
                        FROM academic_levels
                        WHERE id = %s
                    """, (level_id,))
                    level_result = cursor.fetchone()
                    
                    if not level_result:
                        return jsonify({'success': False, 'message': 'Academic level not found.'}), 404
                    
                    level_name = level_result.get('level_name') if isinstance(level_result, dict) else level_result[0]
                    
                    # Get teacher's assigned subject IDs for this level (if teacher)
                    teacher_subject_ids = []
                    if is_teacher and teacher_id:
                        cursor.execute("""
                            SELECT DISTINCT subject_id
                            FROM teacher_subject_assignments
                            WHERE teacher_id = %s AND academic_level_id = %s
                        """, (teacher_id, level_id))
                        teacher_subjects = cursor.fetchall()
                        for subj_row in teacher_subjects:
                            teacher_subject_ids.append(subj_row.get('subject_id') if isinstance(subj_row, dict) else subj_row[0])

                    marks_load_subject_ids = teacher_subject_ids
                    if is_teacher and teacher_subject_ids:
                        try:
                            ensure_subject_exam_combination_tables(cursor)
                            combos_live = _fetch_live_subject_exam_combinations_full(cursor)
                            marks_load_subject_ids = _teacher_marks_subject_ids_for_load(
                                teacher_subject_ids, combos_live,
                            )
                        except Exception as _tl:
                            print(f"teacher combo marks subjects: {_tl}")
                            marks_load_subject_ids = teacher_subject_ids
                    
                    teacher_marks_readonly = False
                    marks_lock_at_str = None
                    # Build query based on whether exam_id is provided
                    if exam_id:
                        ensure_exams_marks_lock_at_column(cursor)
                        max_il, mla = _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id)
                        cursor.execute("SELECT 1 FROM exams WHERE id = %s LIMIT 1", (exam_id,))
                        if not cursor.fetchone():
                            return jsonify({'success': False, 'message': 'Exam not found.'}), 404
                        exam_allocations_locked = bool(max_il)
                        teacher_marks_readonly = bool(is_teacher and _marks_lock_deadline_passed(mla))
                        if mla and hasattr(mla, 'strftime'):
                            marks_lock_at_str = mla.strftime('%Y-%m-%dT%H:%M:%S')
                        elif mla:
                            marks_lock_at_str = str(mla)
                        # Resolve all exam row IDs belonging to the same logical exam group
                        # (same level + name + year + term). Different roles can receive a different
                        # representative ID for the same group, so we must load by group IDs.
                        cursor.execute("""
                            SELECT academic_level_id, exam_name, academic_year_id, term_id
                            FROM exams
                            WHERE id = %s
                        """, (exam_id,))
                        selected_exam_row = cursor.fetchone()
                        if not selected_exam_row:
                            return jsonify({'success': False, 'message': 'Exam not found.'}), 404

                        selected_level_id = selected_exam_row.get('academic_level_id') if isinstance(selected_exam_row, dict) else selected_exam_row[0]
                        selected_exam_name = selected_exam_row.get('exam_name') if isinstance(selected_exam_row, dict) else selected_exam_row[1]
                        selected_year_id = selected_exam_row.get('academic_year_id') if isinstance(selected_exam_row, dict) else selected_exam_row[2]
                        selected_term_id = selected_exam_row.get('term_id') if isinstance(selected_exam_row, dict) else selected_exam_row[3]

                        cursor.execute("""
                            SELECT id
                            FROM exams
                            WHERE academic_level_id = %s
                              AND exam_name = %s
                              AND academic_year_id = %s
                              AND term_id = %s
                        """, (selected_level_id, selected_exam_name, selected_year_id, selected_term_id))
                        exam_group_ids = [r.get('id') if isinstance(r, dict) else r[0] for r in (cursor.fetchall() or [])]
                        if not exam_group_ids:
                            exam_group_ids = [exam_id]
                        # Get marks filtered by exam
                        try:
                            exam_placeholders = ','.join(['%s'] * len(exam_group_ids))
                            if is_teacher and teacher_id and marks_load_subject_ids:
                                # Filter by teacher's subjects and combination partners
                                subject_placeholders = ','.join(['%s'] * len(marks_load_subject_ids))
                                cursor.execute(f"""
                                    SELECT sm.student_id, sm.subject_id, sm.marks, sm.exam_id
                                    FROM student_marks sm
                                    INNER JOIN students s
                                        ON sm.student_id = s.student_id
                                       AND s.current_grade = %s
                                    WHERE sm.exam_id IN ({exam_placeholders})
                                      AND sm.subject_id IN ({subject_placeholders})
                                """, [level_name] + exam_group_ids + marks_load_subject_ids)
                            else:
                                cursor.execute(f"""
                                    SELECT sm.student_id, sm.subject_id, sm.marks, sm.exam_id
                                    FROM student_marks sm
                                    INNER JOIN students s
                                        ON sm.student_id = s.student_id
                                       AND s.current_grade = %s
                                    WHERE sm.exam_id IN ({exam_placeholders})
                                """, [level_name] + exam_group_ids)
                            marks_results = cursor.fetchall()
                            
                            for mark_row in marks_results:
                                student_id = mark_row.get('student_id') if isinstance(mark_row, dict) else mark_row[0]
                                subject_id = mark_row.get('subject_id') if isinstance(mark_row, dict) else mark_row[1]
                                marks = mark_row.get('marks') if isinstance(mark_row, dict) else mark_row[2]
                                
                                if student_id not in student_marks:
                                    student_marks[student_id] = {}
                                if subject_id not in student_marks[student_id]:
                                    student_marks[student_id][subject_id] = {}
                                # Normalize to requested exam_id so UI can render consistently
                                # even if subject rows use different underlying exam IDs.
                                student_marks[student_id][subject_id][exam_id] = marks
                        except Exception as e:
                            print(f"Marks table not found or error: {e}")
                            pass
                    else:
                        # Get all marks (no filter)
                        try:
                            if is_teacher and teacher_id and marks_load_subject_ids:
                                placeholders = ','.join(['%s'] * len(marks_load_subject_ids))
                                cursor.execute(f"""
                                    SELECT sm.student_id, sm.subject_id, sm.marks, sm.exam_id
                                    FROM student_marks sm
                                    INNER JOIN students s
                                        ON sm.student_id = s.student_id
                                       AND s.current_grade = %s
                                    WHERE sm.subject_id IN ({placeholders})
                                """, [level_name] + marks_load_subject_ids)
                            else:
                                cursor.execute("""
                                    SELECT sm.student_id, sm.subject_id, sm.marks, sm.exam_id
                                    FROM student_marks sm
                                    INNER JOIN students s
                                        ON sm.student_id = s.student_id
                                       AND s.current_grade = %s
                                """, (level_name,))
                            marks_results = cursor.fetchall()
                            
                            for mark_row in marks_results:
                                student_id = mark_row.get('student_id') if isinstance(mark_row, dict) else mark_row[0]
                                subject_id = mark_row.get('subject_id') if isinstance(mark_row, dict) else mark_row[1]
                                marks = mark_row.get('marks') if isinstance(mark_row, dict) else mark_row[2]
                                exam_id_from_db = mark_row.get('exam_id') if isinstance(mark_row, dict) else mark_row[3]
                                
                                if student_id not in student_marks:
                                    student_marks[student_id] = {}
                                if subject_id not in student_marks[student_id]:
                                    student_marks[student_id][subject_id] = {}
                                student_marks[student_id][subject_id][exam_id_from_db] = marks
                        except Exception as e:
                            print(f"Marks table not found or error: {e}")
                            pass

                    subject_exam_max_payload = {}
                    try:
                        ensure_subject_exam_total_marks_column(cursor)
                        if is_teacher and teacher_id and marks_load_subject_ids:
                            ph = ','.join(['%s'] * len(marks_load_subject_ids))
                            cursor.execute(
                                f"SELECT id, exam_total_marks FROM subjects WHERE id IN ({ph})",
                                tuple(marks_load_subject_ids),
                            )
                        else:
                            cursor.execute("""
                                SELECT DISTINCT s.id, s.exam_total_marks
                                FROM subjects s
                                INNER JOIN exams e ON e.subject_id = s.id AND e.academic_level_id = %s
                                WHERE s.status = 'active'
                            """, (level_id,))
                        for srow in cursor.fetchall() or []:
                            sid = srow.get('id') if isinstance(srow, dict) else srow[0]
                            etm = srow.get('exam_total_marks') if isinstance(srow, dict) else srow[1]
                            subject_exam_max_payload[str(int(sid))] = float(subject_exam_max_raw_marks(etm))
                    except Exception as _sem:
                        print(f"subject_exam_max for get-marks: {_sem}")
                    
                    payload = {
                        'success': True,
                        'marks': student_marks,
                        'subject_exam_max': subject_exam_max_payload,
                        'message': 'Marks fetched successfully',
                    }
                    if exam_id:
                        payload['teacher_marks_readonly'] = teacher_marks_readonly
                        if marks_lock_at_str:
                            payload['marks_lock_at'] = marks_lock_at_str
                        if exam_allocations_locked:
                            payload['exam_allocations_locked'] = True
                    return jsonify(payload)
            except Exception as e:
                print(f"Error fetching marks: {e}")
                return jsonify({'success': False, 'message': f'Error fetching marks: {str(e)}'}), 500
            finally:
                connection.close()
        else:
            return jsonify({'success': False, 'message': 'Database connection failed.'}), 500
            
    except Exception as e:
        print(f"Error in get_marks_by_exam: {e}")
        return jsonify({'success': False, 'message': 'An error occurred.'}), 500

@app.route('/dashboard/employee/exams-assessments/get-exams', methods=['POST'])
@login_required
def get_exams_for_filters():
    """Get exams for selected academic level, year and term."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'

    if not (is_academic_coordinator or is_technician or is_principal or is_teacher or is_secretary):
        return jsonify({'success': False, 'message': 'You do not have permission to access this.'}), 403

    teacher_id = None
    if is_teacher:
        if is_technician:
            teacher_id = session.get('viewing_as_employee_id')
        else:
            teacher_id = session.get('user_id')

    try:
        data = request.get_json() or {}
        level_id = data.get('level_id')
        academic_year_id = data.get('academic_year_id')
        term_id = data.get('term_id')

        if not level_id or not academic_year_id or not term_id:
            return jsonify({'success': False, 'message': 'Missing required filters.'}), 400

        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed.'}), 500

        try:
            exams = []
            with connection.cursor() as cursor:
                ensure_exams_marks_lock_at_column(cursor)
                try:
                    if is_teacher and teacher_id:
                        cursor.execute("""
                            SELECT e.exam_name, MIN(e.id) AS id, e.academic_year_id, e.term_id,
                                   MAX(e.exam_date) AS exam_date, MAX(COALESCE(e.is_locked, 0)) AS is_locked,
                                   MAX(e.marks_lock_at) AS marks_lock_at,
                                   MAX(e.exam_type) AS exam_type
                            FROM exams e
                            INNER JOIN teacher_subject_assignments tsa ON e.academic_level_id = tsa.academic_level_id
                                AND e.subject_id = tsa.subject_id
                            WHERE e.academic_level_id = %s
                              AND e.academic_year_id = %s
                              AND e.term_id = %s
                              AND tsa.teacher_id = %s
                            GROUP BY e.exam_name, e.academic_year_id, e.term_id
                            ORDER BY MAX(e.exam_date) DESC, e.exam_name ASC
                        """, (level_id, academic_year_id, term_id, teacher_id))
                    else:
                        cursor.execute("""
                            SELECT exam_name, MIN(id) AS id, academic_year_id, term_id,
                                   MAX(exam_date) AS exam_date, MAX(COALESCE(is_locked, 0)) AS is_locked,
                                   MAX(marks_lock_at) AS marks_lock_at,
                                   MAX(exam_type) AS exam_type
                            FROM exams
                            WHERE academic_level_id = %s
                              AND academic_year_id = %s
                              AND term_id = %s
                            GROUP BY exam_name, academic_year_id, term_id
                            ORDER BY MAX(exam_date) DESC, exam_name ASC
                        """, (level_id, academic_year_id, term_id))
                except Exception:
                    # Backward compatibility: older DBs may not have marks_lock_at yet.
                    if is_teacher and teacher_id:
                        cursor.execute("""
                            SELECT e.exam_name, MIN(e.id) AS id, e.academic_year_id, e.term_id,
                                   MAX(e.exam_date) AS exam_date, MAX(COALESCE(e.is_locked, 0)) AS is_locked,
                                   NULL AS marks_lock_at
                            FROM exams e
                            INNER JOIN teacher_subject_assignments tsa ON e.academic_level_id = tsa.academic_level_id
                                AND e.subject_id = tsa.subject_id
                            WHERE e.academic_level_id = %s
                              AND e.academic_year_id = %s
                              AND e.term_id = %s
                              AND tsa.teacher_id = %s
                            GROUP BY e.exam_name, e.academic_year_id, e.term_id
                            ORDER BY MAX(e.exam_date) DESC, e.exam_name ASC
                        """, (level_id, academic_year_id, term_id, teacher_id))
                    else:
                        cursor.execute("""
                            SELECT exam_name, MIN(id) AS id, academic_year_id, term_id,
                                   MAX(exam_date) AS exam_date, MAX(COALESCE(is_locked, 0)) AS is_locked,
                                   NULL AS marks_lock_at
                            FROM exams
                            WHERE academic_level_id = %s
                              AND academic_year_id = %s
                              AND term_id = %s
                            GROUP BY exam_name, academic_year_id, term_id
                            ORDER BY MAX(exam_date) DESC, exam_name ASC
                        """, (level_id, academic_year_id, term_id))

                for row in (cursor.fetchall() or []):
                    exam_name = (row.get('exam_name', '') if isinstance(row, dict) else row[0]) or ''
                    if not exam_name.strip():
                        continue
                    mla_raw = row.get('marks_lock_at') if isinstance(row, dict) else (row[6] if len(row) > 6 else None)
                    if mla_raw and hasattr(mla_raw, 'strftime'):
                        marks_lock_at_str = mla_raw.strftime('%Y-%m-%dT%H:%M:%S')
                    else:
                        marks_lock_at_str = str(mla_raw) if mla_raw else None
                    exams.append({
                        'id': row.get('id') if isinstance(row, dict) else row[1],
                        'exam_name': exam_name.strip(),
                        'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else (row[2] if len(row) > 2 else None),
                        'term_id': row.get('term_id') if isinstance(row, dict) else (row[3] if len(row) > 3 else None),
                        'exam_date': str(row.get('exam_date')) if isinstance(row, dict) and row.get('exam_date') else (str(row[4]) if len(row) > 4 and row[4] else ''),
                        'is_locked': bool(row.get('is_locked')) if isinstance(row, dict) else bool(row[5] if len(row) > 5 else False),
                        'marks_lock_at': marks_lock_at_str,
                        'exam_type': (row.get('exam_type') if isinstance(row, dict) else (row[7] if len(row) > 7 else None)) or '',
                    })

            return jsonify({'success': True, 'exams': exams})
        finally:
            connection.close()
    except Exception as e:
        print(f"Error in get_exams_for_filters: {e}")
        return jsonify({'success': False, 'message': 'An error occurred while fetching exams.'}), 500

# API Endpoint to save marks
@app.route('/dashboard/employee/exams-assessments/exam-audits')
@login_required
def exam_audits():
    """Show exam marks changes made by staff who are not the allocated teacher for that subject."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'

    if not (is_academic_coordinator or is_technician or is_principal or is_secretary):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    audit_logs = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_exam_marks_audit_table(cursor)
                connection.commit()
                cursor.execute("""
                    SELECT
                        a.id,
                        a.student_id,
                        s.full_name AS student_name,
                        a.subject_id,
                        sub.subject_name,
                        sub.subject_code,
                        a.academic_level_id,
                        al.level_name,
                        a.exam_id,
                        a.exam_name,
                        a.action_type,
                        a.old_marks,
                        a.new_marks,
                        a.changed_by,
                        a.changed_by_role,
                        a.changed_by_name,
                        a.created_at,
                        (
                            SELECT GROUP_CONCAT(DISTINCT e.full_name ORDER BY e.full_name SEPARATOR ', ')
                            FROM teacher_subject_assignments tsa2
                            JOIN employees e ON e.id = tsa2.teacher_id
                            WHERE tsa2.subject_id = a.subject_id
                              AND tsa2.academic_level_id = a.academic_level_id
                        ) AS allocated_teachers
                    FROM exam_marks_audit a
                    LEFT JOIN students s ON s.student_id = a.student_id
                    LEFT JOIN subjects sub ON sub.id = a.subject_id
                    LEFT JOIN academic_levels al ON al.id = a.academic_level_id
                    LEFT JOIN teacher_subject_assignments tsa_match
                        ON tsa_match.subject_id = a.subject_id
                        AND tsa_match.academic_level_id = a.academic_level_id
                        AND tsa_match.teacher_id = a.changed_by
                    WHERE tsa_match.id IS NULL
                    ORDER BY a.created_at DESC
                    LIMIT 1000
                """)
                results = cursor.fetchall()
                for row in results:
                    created_at = row.get('created_at')
                    if created_at and hasattr(created_at, 'strftime'):
                        created_at_str = created_at.strftime('%Y-%m-%d %H:%M:%S')
                    else:
                        created_at_str = str(created_at) if created_at else ''

                    subject_name = row.get('subject_name') or row.get('subject_code') or ''
                    old_marks = row.get('old_marks')
                    new_marks = row.get('new_marks')

                    audit_logs.append({
                        'id': row.get('id'),
                        'student_id': row.get('student_id'),
                        'student_name': row.get('student_name') or 'Unknown',
                        'subject_id': row.get('subject_id'),
                        'subject_name': subject_name,
                        'level_name': row.get('level_name') or '',
                        'exam_id': row.get('exam_id'),
                        'exam_name': row.get('exam_name') or '',
                        'action_type': row.get('action_type') or '',
                        'old_marks': float(old_marks) if old_marks is not None else None,
                        'new_marks': float(new_marks) if new_marks is not None else None,
                        'changed_by_name': row.get('changed_by_name') or 'Unknown',
                        'changed_by_role': row.get('changed_by_role') or '',
                        'allocated_teachers': row.get('allocated_teachers') or '',
                        'created_at': created_at_str,
                    })
        except Exception as e:
            print(f"Error loading exam audits: {e}")
            import traceback
            traceback.print_exc()
            flash('Could not load exam audit log.', 'error')
        finally:
            connection.close()

    return render_template(
        'dashboards/exam_audits.html',
        audit_logs=audit_logs,
        dashboard_content_role='curriculum coordinator' if is_academic_coordinator else (
            'head of institution' if is_principal else (
                'secretary' if is_secretary else session.get('role')
            )
        ),
    )


def _save_marks_batch_core(cursor, entries, exam_id, level_id, is_teacher, teacher_id):
    """
    Persist many mark cells in one DB transaction.
    entries: list of {student_id, subject_id, marks}
    Returns (ok: bool, payload: dict, http_status: int)
    """
    if not entries:
        return True, {'success': True, 'message': 'Nothing to save.', 'saved': 0, 'results': []}, 200

    ensure_subject_exam_total_marks_column(cursor)
    cursor.execute("SELECT 1 FROM exams WHERE id = %s LIMIT 1", (exam_id,))
    if not cursor.fetchone():
        return False, {'success': False, 'message': 'Exam not found.'}, 404

    ensure_exams_marks_lock_at_column(cursor)
    max_il, mla = _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id)
    if max_il:
        return False, {
            'success': False,
            'message': 'This exam is locked. Marks cannot be changed.',
            'locked': True,
        }, 403
    if is_teacher and _marks_lock_deadline_passed(mla):
        return False, {
            'success': False,
            'message': 'The marks entry period for this exam is over. Contact the curriculum office if you need changes.',
            'marks_period_closed': True,
        }, 403

    registered_current = load_registered_current_exam_dict(cursor)
    cursor.execute("""
        SELECT academic_level_id, exam_name, academic_year_id, term_id, exam_type
        FROM exams
        WHERE id = %s
    """, (exam_id,))
    exam_scope_row = cursor.fetchone()
    if not exam_scope_row:
        return False, {'success': False, 'message': 'Exam not found.'}, 404

    exam_scope_level_id = exam_scope_row.get('academic_level_id') if isinstance(exam_scope_row, dict) else exam_scope_row[0]
    exam_scope_name = exam_scope_row.get('exam_name') if isinstance(exam_scope_row, dict) else exam_scope_row[1]
    exam_scope_year_id = exam_scope_row.get('academic_year_id') if isinstance(exam_scope_row, dict) else exam_scope_row[2]
    exam_scope_term_id = exam_scope_row.get('term_id') if isinstance(exam_scope_row, dict) else exam_scope_row[3]
    exam_scope_type = (
        exam_scope_row.get('exam_type') if isinstance(exam_scope_row, dict)
        else (exam_scope_row[4] if len(exam_scope_row) > 4 else None)
    )

    ensure_exam_context_snapshot_if_missing(
        cursor,
        exam_scope_name,
        exam_scope_year_id,
        exam_scope_term_id,
        exam_scope_level_id,
        registered_current=registered_current,
        exam_type=exam_scope_type,
    )

    subject_ids = []
    student_ids = []
    normalized = []
    for item in entries:
        if not isinstance(item, dict):
            continue
        sid = item.get('student_id')
        sub_id = item.get('subject_id')
        if sid is None or sub_id is None:
            continue
        try:
            sid_i = int(sid)
            sub_i = int(sub_id)
        except (TypeError, ValueError):
            continue
        if sub_i < 0:
            # Combo total columns are derived live — never persist them.
            continue
        marks_raw = item.get('marks')
        marks_value = None
        if marks_raw is not None and str(marks_raw).strip() != '':
            try:
                marks_value = float(marks_raw)
            except (TypeError, ValueError):
                return False, {
                    'success': False,
                    'message': f'Invalid marks value for student {sid_i}, subject {sub_i}.',
                }, 400
            if marks_value < 0:
                return False, {'success': False, 'message': 'Marks cannot be negative.'}, 400
        subject_ids.append(sub_i)
        student_ids.append(sid_i)
        normalized.append((sid_i, sub_i, marks_value))

    if not normalized:
        return True, {'success': True, 'message': 'Nothing to save.', 'saved': 0, 'results': []}, 200

    uniq_subjects = sorted(set(subject_ids))
    allowed_subjects = set(uniq_subjects)
    if is_teacher and teacher_id:
        ph = ','.join(['%s'] * len(uniq_subjects))
        cursor.execute(
            f"""
            SELECT subject_id
            FROM teacher_subject_assignments
            WHERE teacher_id = %s
              AND academic_level_id = %s
              AND subject_id IN ({ph})
            """,
            tuple([teacher_id, level_id] + uniq_subjects),
        )
        allowed_subjects = set()
        for row in cursor.fetchall() or []:
            sid = row.get('subject_id') if isinstance(row, dict) else row[0]
            try:
                allowed_subjects.add(int(sid))
            except (TypeError, ValueError):
                continue
        denied = [s for s in uniq_subjects if s not in allowed_subjects]
        if denied:
            return False, {
                'success': False,
                'message': 'You are not assigned to one or more subjects for this level.',
            }, 403

    # Resolve subject exam row + max once per subject
    resolved_exam_by_subject = {}
    max_raw_by_subject = {}
    for sub_i in uniq_subjects:
        cursor.execute("""
            SELECT id
            FROM exams
            WHERE academic_level_id = %s
              AND exam_name = %s
              AND academic_year_id = %s
              AND term_id = %s
              AND subject_id = %s
            ORDER BY id ASC
            LIMIT 1
        """, (exam_scope_level_id, exam_scope_name, exam_scope_year_id, exam_scope_term_id, sub_i))
        subject_exam_row = cursor.fetchone()
        if subject_exam_row:
            resolved_exam_by_subject[sub_i] = (
                subject_exam_row.get('id') if isinstance(subject_exam_row, dict) else subject_exam_row[0]
            )
        else:
            resolved_exam_by_subject[sub_i] = exam_id

        cursor.execute("SELECT exam_total_marks FROM subjects WHERE id = %s LIMIT 1", (sub_i,))
        sub_max_row = cursor.fetchone()
        if not sub_max_row:
            return False, {'success': False, 'message': f'Subject {sub_i} not found.'}, 404
        etm = sub_max_row.get('exam_total_marks') if isinstance(sub_max_row, dict) else sub_max_row[0]
        etm = subject_exam_total_for_context(
            cursor, sub_i,
            exam_scope_name, exam_scope_year_id, exam_scope_term_id, exam_scope_level_id,
            live_fallback=etm,
            registered_current=registered_current,
            exam_type=exam_scope_type,
        )
        max_raw_by_subject[sub_i] = min(subject_exam_max_raw_marks(etm), 100.0)

    for _, sub_i, marks_value in normalized:
        max_raw = max_raw_by_subject.get(sub_i, 100.0)
        if marks_value is not None and marks_value > max_raw + 1e-9:
            return False, {
                'success': False,
                'message': f'Marks cannot exceed {max_raw:g} (maximum 100).',
            }, 400

    changed_by, changed_by_role, changed_by_name = _exam_marks_audit_actor()
    audit_level_id = exam_scope_level_id or level_id
    audit_exam_name = exam_scope_name or ''
    results = []
    saved = 0

    for sid_i, sub_i, marks_value in normalized:
        resolved_exam_id = resolved_exam_by_subject[sub_i]
        cursor.execute("""
            SELECT id, marks FROM student_marks
            WHERE student_id = %s AND subject_id = %s AND exam_id = %s
        """, (sid_i, sub_i, resolved_exam_id))
        existing = cursor.fetchone()
        old_marks = None
        if existing:
            old_marks = existing.get('marks') if isinstance(existing, dict) else existing[1]

        if existing:
            if marks_value is not None:
                if not _marks_audit_values_equal(old_marks, marks_value):
                    cursor.execute("""
                        UPDATE student_marks
                        SET marks = %s, updated_at = CURRENT_TIMESTAMP
                        WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                    """, (marks_value, sid_i, sub_i, resolved_exam_id))
                    _log_exam_marks_audit(
                        cursor,
                        student_id=sid_i,
                        subject_id=sub_i,
                        exam_id=resolved_exam_id,
                        academic_level_id=audit_level_id,
                        exam_name=audit_exam_name,
                        action_type='UPDATE',
                        old_marks=old_marks,
                        new_marks=marks_value,
                        changed_by=changed_by,
                        changed_by_role=changed_by_role,
                        changed_by_name=changed_by_name,
                    )
            else:
                cursor.execute("""
                    DELETE FROM student_marks
                    WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                """, (sid_i, sub_i, resolved_exam_id))
                _log_exam_marks_audit(
                    cursor,
                    student_id=sid_i,
                    subject_id=sub_i,
                    exam_id=resolved_exam_id,
                    academic_level_id=audit_level_id,
                    exam_name=audit_exam_name,
                    action_type='DELETE',
                    old_marks=old_marks,
                    new_marks=None,
                    changed_by=changed_by,
                    changed_by_role=changed_by_role,
                    changed_by_name=changed_by_name,
                )
        else:
            if marks_value is not None:
                cursor.execute("""
                    INSERT INTO student_marks (student_id, subject_id, exam_id, marks, created_at, updated_at)
                    VALUES (%s, %s, %s, %s, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                """, (sid_i, sub_i, resolved_exam_id, marks_value))
                _log_exam_marks_audit(
                    cursor,
                    student_id=sid_i,
                    subject_id=sub_i,
                    exam_id=resolved_exam_id,
                    academic_level_id=audit_level_id,
                    exam_name=audit_exam_name,
                    action_type='INSERT',
                    old_marks=None,
                    new_marks=marks_value,
                    changed_by=changed_by,
                    changed_by_role=changed_by_role,
                    changed_by_name=changed_by_name,
                )

        saved += 1
        results.append({
            'student_id': sid_i,
            'subject_id': sub_i,
            'marks': marks_value,
            'success': True,
        })

    return True, {
        'success': True,
        'message': f'Saved {saved} mark(s).',
        'saved': saved,
        'results': results,
    }, 200


@app.route('/dashboard/employee/exams-assessments/save-marks', methods=['POST'])
@login_required
def save_marks():
    """Save marks for a student in a subject for an exam (or a batch via entries[])."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role == 'teachers' or viewing_as_role == 'teacher'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_cc = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    
    if not (is_teacher or is_principal or is_cc):
        return jsonify({'success': False, 'message': 'You do not have permission to save marks.'}), 403
    
    # Get teacher ID (only used when user is a teacher, for assignment check)
    teacher_id = None
    if is_teacher:
        is_technician = user_role == 'technician'
        if is_technician:
            teacher_id = session.get('viewing_as_employee_id')
        else:
            teacher_id = session.get('user_id')
        if not teacher_id:
            return jsonify({'success': False, 'message': 'Teacher ID not found.'}), 400
    
    try:
        data = request.get_json() or {}
        # Bulk path: one request / one transaction for all dirty cells
        if isinstance(data.get('entries'), list):
            exam_id = data.get('exam_id')
            level_id = data.get('level_id')
            if exam_id is None or level_id is None:
                return jsonify({'success': False, 'message': 'Missing required fields.'}), 400
            connection = get_db_connection()
            if not connection:
                return jsonify({'success': False, 'message': 'Database connection failed.'}), 500
            try:
                with connection.cursor() as cursor:
                    ok, payload, status = _save_marks_batch_core(
                        cursor,
                        data.get('entries') or [],
                        exam_id,
                        level_id,
                        is_teacher,
                        teacher_id,
                    )
                    if ok:
                        connection.commit()
                    else:
                        try:
                            connection.rollback()
                        except Exception:
                            pass
                    return jsonify(payload), status
            except Exception as e:
                try:
                    connection.rollback()
                except Exception:
                    pass
                # Dead / overloaded MySQL — one reconnect retry for transient disconnects
                if _is_mysql_disconnect_error(e) or _is_mysql_capacity_error(e):
                    try:
                        connection.close()
                    except Exception:
                        pass
                    connection = get_db_connection()
                    if connection:
                        try:
                            with connection.cursor() as cursor:
                                ok, payload, status = _save_marks_batch_core(
                                    cursor,
                                    data.get('entries') or [],
                                    exam_id,
                                    level_id,
                                    is_teacher,
                                    teacher_id,
                                )
                                if ok:
                                    connection.commit()
                                else:
                                    try:
                                        connection.rollback()
                                    except Exception:
                                        pass
                                return jsonify(payload), status
                        except Exception as e2:
                            try:
                                connection.rollback()
                            except Exception:
                                pass
                            import traceback
                            print(f"Error saving marks batch (retry): {e2}")
                            print(traceback.format_exc())
                            return jsonify({
                                'success': False,
                                'message': 'Database busy or disconnected. Please try saving again in a moment.',
                            }), 503
                        finally:
                            try:
                                connection.close()
                            except Exception:
                                pass
                            connection = None
                import traceback
                print(f"Error saving marks batch: {e}")
                print(traceback.format_exc())
                return jsonify({
                    'success': False,
                    'message': 'Database busy or disconnected. Please try saving again in a moment.',
                }), 503
            finally:
                if connection:
                    try:
                        connection.close()
                    except Exception:
                        pass

        student_id = data.get('student_id')
        subject_id = data.get('subject_id')
        exam_id = data.get('exam_id')
        marks = data.get('marks')
        level_id = data.get('level_id')
        
        # Validate required fields
        if not all([student_id, subject_id, exam_id is not None, level_id]):
            return jsonify({'success': False, 'message': 'Missing required fields.'}), 400
        
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed.'}), 500
        
        try:
            with connection.cursor() as cursor:
                ensure_subject_exam_total_marks_column(cursor)
                cursor.execute("SELECT 1 FROM exams WHERE id = %s LIMIT 1", (exam_id,))
                if not cursor.fetchone():
                    return jsonify({'success': False, 'message': 'Exam not found.'}), 404
                ensure_exams_marks_lock_at_column(cursor)
                max_il, mla = _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id)
                if max_il:
                    return jsonify({
                        'success': False,
                        'message': 'This exam is locked. Marks cannot be changed.',
                        'locked': True
                    }), 403
                if is_teacher and _marks_lock_deadline_passed(mla):
                    return jsonify({
                        'success': False,
                        'message': 'The marks entry period for this exam is over. Contact the curriculum office if you need changes.',
                        'marks_period_closed': True,
                    }), 403

                # Teachers must be assigned to this subject and level; coordinators and principals can save any
                if is_teacher and teacher_id:
                    cursor.execute("""
                        SELECT id FROM teacher_subject_assignments
                        WHERE teacher_id = %s AND subject_id = %s AND academic_level_id = %s
                    """, (teacher_id, subject_id, level_id))
                    assignment = cursor.fetchone()
                    if not assignment:
                        return jsonify({'success': False, 'message': 'You are not assigned to this subject for this level.'}), 403

                # Resolve the subject-specific exam row ID for this logical exam
                # (same level + exam_name + year + term + subject). This ensures marks entered by
                # teachers are visible to other roles that may use a different representative exam ID.
                resolved_exam_id = exam_id
                registered_current = load_registered_current_exam_dict(cursor)
                cursor.execute("""
                    SELECT academic_level_id, exam_name, academic_year_id, term_id, exam_type
                    FROM exams
                    WHERE id = %s
                """, (exam_id,))
                exam_scope_row = cursor.fetchone()
                if not exam_scope_row:
                    return jsonify({'success': False, 'message': 'Exam not found.'}), 404
                exam_scope_level_id = exam_scope_row.get('academic_level_id') if isinstance(exam_scope_row, dict) else exam_scope_row[0]
                exam_scope_name = exam_scope_row.get('exam_name') if isinstance(exam_scope_row, dict) else exam_scope_row[1]
                exam_scope_year_id = exam_scope_row.get('academic_year_id') if isinstance(exam_scope_row, dict) else exam_scope_row[2]
                exam_scope_term_id = exam_scope_row.get('term_id') if isinstance(exam_scope_row, dict) else exam_scope_row[3]
                exam_scope_type = (
                    exam_scope_row.get('exam_type') if isinstance(exam_scope_row, dict) else (exam_scope_row[4] if len(exam_scope_row) > 4 else None)
                )

                ensure_exam_context_snapshot_if_missing(
                    cursor,
                    exam_scope_name,
                    exam_scope_year_id,
                    exam_scope_term_id,
                    exam_scope_level_id,
                    registered_current=registered_current,
                    exam_type=exam_scope_type,
                )

                cursor.execute("""
                    SELECT id
                    FROM exams
                    WHERE academic_level_id = %s
                      AND exam_name = %s
                      AND academic_year_id = %s
                      AND term_id = %s
                      AND subject_id = %s
                    ORDER BY id ASC
                    LIMIT 1
                """, (exam_scope_level_id, exam_scope_name, exam_scope_year_id, exam_scope_term_id, subject_id))
                subject_exam_row = cursor.fetchone()
                if subject_exam_row:
                    resolved_exam_id = subject_exam_row.get('id') if isinstance(subject_exam_row, dict) else subject_exam_row[0]
                
                # Validate marks (should be numeric or empty/null)
                marks_value = None
                if marks and str(marks).strip():
                    try:
                        marks_value = float(marks)
                        if marks_value < 0:
                            return jsonify({'success': False, 'message': 'Marks cannot be negative.'}), 400
                    except ValueError:
                        return jsonify({'success': False, 'message': 'Invalid marks value. Must be a number.'}), 400

                cursor.execute(
                    "SELECT exam_total_marks FROM subjects WHERE id = %s LIMIT 1",
                    (subject_id,),
                )
                sub_max_row = cursor.fetchone()
                if not sub_max_row:
                    return jsonify({'success': False, 'message': 'Subject not found.'}), 404
                etm = sub_max_row.get('exam_total_marks') if isinstance(sub_max_row, dict) else sub_max_row[0]
                etm = subject_exam_total_for_context(
                    cursor, subject_id,
                    exam_scope_name, exam_scope_year_id, exam_scope_term_id, exam_scope_level_id,
                    live_fallback=etm,
                    registered_current=registered_current,
                    exam_type=exam_scope_type,
                )
                max_raw = min(subject_exam_max_raw_marks(etm), 100.0)
                if marks_value is not None and marks_value > max_raw + 1e-9:
                    return jsonify({
                        'success': False,
                        'message': f'Marks cannot exceed {max_raw:g} (maximum 100).',
                    }), 400
                
                # Check if mark already exists
                cursor.execute("""
                    SELECT id, marks FROM student_marks
                    WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                """, (student_id, subject_id, resolved_exam_id))
                existing = cursor.fetchone()
                old_marks = None
                if existing:
                    old_marks = existing.get('marks') if isinstance(existing, dict) else existing[1]

                changed_by, changed_by_role, changed_by_name = _exam_marks_audit_actor()
                audit_level_id = exam_scope_level_id or level_id
                audit_exam_name = exam_scope_name or ''

                if existing:
                    # Update existing mark
                    if marks_value is not None:
                        if not _marks_audit_values_equal(old_marks, marks_value):
                            cursor.execute("""
                                UPDATE student_marks
                                SET marks = %s, updated_at = CURRENT_TIMESTAMP
                                WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                            """, (marks_value, student_id, subject_id, resolved_exam_id))
                            _log_exam_marks_audit(
                                cursor,
                                student_id=student_id,
                                subject_id=subject_id,
                                exam_id=resolved_exam_id,
                                academic_level_id=audit_level_id,
                                exam_name=audit_exam_name,
                                action_type='UPDATE',
                                old_marks=old_marks,
                                new_marks=marks_value,
                                changed_by=changed_by,
                                changed_by_role=changed_by_role,
                                changed_by_name=changed_by_name,
                            )
                    else:
                        # Delete mark if empty
                        cursor.execute("""
                            DELETE FROM student_marks
                            WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                        """, (student_id, subject_id, resolved_exam_id))
                        _log_exam_marks_audit(
                            cursor,
                            student_id=student_id,
                            subject_id=subject_id,
                            exam_id=resolved_exam_id,
                            academic_level_id=audit_level_id,
                            exam_name=audit_exam_name,
                            action_type='DELETE',
                            old_marks=old_marks,
                            new_marks=None,
                            changed_by=changed_by,
                            changed_by_role=changed_by_role,
                            changed_by_name=changed_by_name,
                        )
                else:
                    # Insert new mark (only if marks value is provided)
                    if marks_value is not None:
                        cursor.execute("""
                            INSERT INTO student_marks (student_id, subject_id, exam_id, marks, created_at, updated_at)
                            VALUES (%s, %s, %s, %s, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                        """, (student_id, subject_id, resolved_exam_id, marks_value))
                        _log_exam_marks_audit(
                            cursor,
                            student_id=student_id,
                            subject_id=subject_id,
                            exam_id=resolved_exam_id,
                            academic_level_id=audit_level_id,
                            exam_name=audit_exam_name,
                            action_type='INSERT',
                            old_marks=None,
                            new_marks=marks_value,
                            changed_by=changed_by,
                            changed_by_role=changed_by_role,
                            changed_by_name=changed_by_name,
                        )
                
                connection.commit()
                return jsonify({
                    'success': True,
                    'message': 'Marks saved successfully.',
                    'marks': marks_value
                })
        except Exception as e:
            connection.rollback()
            import traceback
            error_trace = traceback.format_exc()
            print(f"Error saving marks: {e}")
            print(f"Traceback: {error_trace}")
            return jsonify({'success': False, 'message': f'Error saving marks: {str(e)}'}), 500
        finally:
            connection.close()
    except Exception as e:
        import traceback
        error_trace = traceback.format_exc()
        print(f"Error in save_marks endpoint: {e}")
        print(f"Traceback: {error_trace}")
        return jsonify({'success': False, 'message': f'Error: {str(e)}'}), 500


@app.route('/dashboard/employee/exams-assessments/save-combination-marks', methods=['POST'])
@login_required
def save_combination_marks():
    """Apply one unified percentage (0–100) across every paper in a combination (raw per subject from each exam total)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_teacher = user_role == 'teachers' or user_role == 'teacher' or viewing_as_role in ('teachers', 'teacher')
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_teacher or is_principal):
        return jsonify({'success': False, 'message': 'You do not have permission to save marks.'}), 403

    teacher_id = None
    if is_teacher:
        is_technician = user_role == 'technician'
        if is_technician:
            teacher_id = session.get('viewing_as_employee_id')
        else:
            teacher_id = session.get('user_id')
        if not teacher_id:
            return jsonify({'success': False, 'message': 'Teacher ID not found.'}), 400

    try:
        data = request.get_json()
        combination_id = data.get('combination_id')
        student_id = data.get('student_id')
        exam_id = data.get('exam_id')
        marks = data.get('marks')
        level_id = data.get('level_id')

        if not all([combination_id is not None, student_id, exam_id is not None, level_id]):
            return jsonify({'success': False, 'message': 'Missing required fields.'}), 400
        try:
            combination_id = int(combination_id)
        except (TypeError, ValueError):
            return jsonify({'success': False, 'message': 'Invalid combination.'}), 400

        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection failed.'}), 500

        try:
            with connection.cursor() as cursor:
                ensure_subject_exam_total_marks_column(cursor)
                ensure_subject_exam_display_order_columns(cursor)
                ensure_subject_exam_combination_tables(cursor)

                cursor.execute("SELECT 1 FROM exams WHERE id = %s LIMIT 1", (exam_id,))
                if not cursor.fetchone():
                    return jsonify({'success': False, 'message': 'Exam not found.'}), 404
                ensure_exams_marks_lock_at_column(cursor)
                max_il, mla = _exam_group_max_is_locked_and_marks_lock_at(cursor, exam_id)
                if max_il:
                    return jsonify({
                        'success': False,
                        'message': 'This exam is locked. Marks cannot be changed.',
                        'locked': True,
                    }), 403
                if is_teacher and _marks_lock_deadline_passed(mla):
                    return jsonify({
                        'success': False,
                        'message': 'The marks entry period for this exam is over. Contact the curriculum office if you need changes.',
                        'marks_period_closed': True,
                    }), 403

                cursor.execute("""
                    SELECT academic_level_id, exam_name, academic_year_id, term_id
                    FROM exams WHERE id = %s
                """, (exam_id,))
                exam_scope_row = cursor.fetchone()
                if not exam_scope_row:
                    return jsonify({'success': False, 'message': 'Exam not found.'}), 404
                exam_scope_level_id = exam_scope_row.get('academic_level_id') if isinstance(exam_scope_row, dict) else exam_scope_row[0]
                exam_scope_name = exam_scope_row.get('exam_name') if isinstance(exam_scope_row, dict) else exam_scope_row[1]
                exam_scope_year_id = exam_scope_row.get('academic_year_id') if isinstance(exam_scope_row, dict) else exam_scope_row[2]
                exam_scope_term_id = exam_scope_row.get('term_id') if isinstance(exam_scope_row, dict) else exam_scope_row[3]

                cursor.execute("""
                    SELECT subject_id FROM subject_exam_combination_members
                    WHERE combination_id = %s
                    ORDER BY sort_order ASC, subject_id ASC
                """, (combination_id,))
                mem_rows = cursor.fetchall() or []
                member_ids = []
                for r in mem_rows:
                    sid = r.get('subject_id') if isinstance(r, dict) else r[0]
                    if sid is not None:
                        member_ids.append(int(sid))
                if len(member_ids) < 2:
                    return jsonify({'success': False, 'message': 'Combination not found or incomplete.'}), 404

                pct_val = None
                if marks is not None and str(marks).strip():
                    try:
                        pct_val = float(marks)
                        if pct_val < 0 or pct_val > 100 + 1e-9:
                            return jsonify({'success': False, 'message': 'Enter a percentage between 0 and 100.'}), 400
                    except ValueError:
                        return jsonify({'success': False, 'message': 'Invalid percentage.'}), 400

                changed_by, changed_by_role, changed_by_name = _exam_marks_audit_actor()
                audit_level_id = exam_scope_level_id or level_id
                audit_exam_name = exam_scope_name or ''

                for subject_id in member_ids:
                    if is_teacher and teacher_id:
                        cursor.execute("""
                            SELECT id FROM teacher_subject_assignments
                            WHERE teacher_id = %s AND subject_id = %s AND academic_level_id = %s
                        """, (teacher_id, subject_id, level_id))
                        if not cursor.fetchone():
                            return jsonify({
                                'success': False,
                                'message': 'You are not assigned to all subjects in this combination for this level.',
                            }), 403

                    resolved_exam_id = exam_id
                    cursor.execute("""
                        SELECT id FROM exams
                        WHERE academic_level_id = %s AND exam_name = %s
                          AND academic_year_id = %s AND term_id = %s AND subject_id = %s
                        ORDER BY id ASC LIMIT 1
                    """, (exam_scope_level_id, exam_scope_name, exam_scope_year_id, exam_scope_term_id, subject_id))
                    subject_exam_row = cursor.fetchone()
                    if subject_exam_row:
                        resolved_exam_id = subject_exam_row.get('id') if isinstance(subject_exam_row, dict) else subject_exam_row[0]

                    cursor.execute(
                        "SELECT exam_total_marks FROM subjects WHERE id = %s LIMIT 1",
                        (subject_id,),
                    )
                    sub_max_row = cursor.fetchone()
                    if not sub_max_row:
                        return jsonify({'success': False, 'message': 'Subject not found.'}), 404
                    etm = sub_max_row.get('exam_total_marks') if isinstance(sub_max_row, dict) else sub_max_row[0]
                    max_raw = subject_exam_max_raw_marks(etm)

                    marks_value = None
                    if pct_val is not None:
                        marks_value = round((pct_val / 100.0) * max_raw, 2)

                    cursor.execute("""
                        SELECT id, marks FROM student_marks
                        WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                    """, (student_id, subject_id, resolved_exam_id))
                    existing = cursor.fetchone()
                    old_marks = None
                    if existing:
                        old_marks = existing.get('marks') if isinstance(existing, dict) else existing[1]

                    if existing:
                        if marks_value is not None:
                            if not _marks_audit_values_equal(old_marks, marks_value):
                                cursor.execute("""
                                    UPDATE student_marks
                                    SET marks = %s, updated_at = CURRENT_TIMESTAMP
                                    WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                                """, (marks_value, student_id, subject_id, resolved_exam_id))
                                _log_exam_marks_audit(
                                    cursor,
                                    student_id=student_id,
                                    subject_id=subject_id,
                                    exam_id=resolved_exam_id,
                                    academic_level_id=audit_level_id,
                                    exam_name=audit_exam_name,
                                    action_type='UPDATE',
                                    old_marks=old_marks,
                                    new_marks=marks_value,
                                    changed_by=changed_by,
                                    changed_by_role=changed_by_role,
                                    changed_by_name=changed_by_name,
                                )
                        else:
                            cursor.execute("""
                                DELETE FROM student_marks
                                WHERE student_id = %s AND subject_id = %s AND exam_id = %s
                            """, (student_id, subject_id, resolved_exam_id))
                            _log_exam_marks_audit(
                                cursor,
                                student_id=student_id,
                                subject_id=subject_id,
                                exam_id=resolved_exam_id,
                                academic_level_id=audit_level_id,
                                exam_name=audit_exam_name,
                                action_type='DELETE',
                                old_marks=old_marks,
                                new_marks=None,
                                changed_by=changed_by,
                                changed_by_role=changed_by_role,
                                changed_by_name=changed_by_name,
                            )
                    elif marks_value is not None:
                        cursor.execute("""
                            INSERT INTO student_marks (student_id, subject_id, exam_id, marks, created_at, updated_at)
                            VALUES (%s, %s, %s, %s, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
                        """, (student_id, subject_id, resolved_exam_id, marks_value))
                        _log_exam_marks_audit(
                            cursor,
                            student_id=student_id,
                            subject_id=subject_id,
                            exam_id=resolved_exam_id,
                            academic_level_id=audit_level_id,
                            exam_name=audit_exam_name,
                            action_type='INSERT',
                            old_marks=None,
                            new_marks=marks_value,
                            changed_by=changed_by,
                            changed_by_role=changed_by_role,
                            changed_by_name=changed_by_name,
                        )

                connection.commit()
                return jsonify({
                    'success': True,
                    'message': 'Combination marks saved.',
                    'marks_percent': pct_val,
                })
        except Exception as e:
            connection.rollback()
            import traceback
            print(f"Error saving combination marks: {e}")
            print(traceback.format_exc())
            return jsonify({'success': False, 'message': f'Error saving marks: {str(e)}'}), 500
        finally:
            connection.close()
    except Exception as e:
        import traceback
        print(f"Error in save_combination_marks: {e}")
        print(traceback.format_exc())
        return jsonify({'success': False, 'message': f'Error: {str(e)}'}), 500


# API Endpoint to fetch students by academic level
@app.route('/dashboard/employee/exams-assessments/get-students', methods=['POST'])
@login_required
def get_students_by_academic_level():
    """Get all students for a specific academic level"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_secretary):
        return jsonify({'success': False, 'message': 'You do not have permission to access this.'}), 403
    
    try:
        data = request.get_json()
        academic_level_id = data.get('academic_level_id')
        
        if not academic_level_id:
            return jsonify({'success': False, 'message': 'Academic level ID is required.'}), 400
        
        connection = get_db_connection()
        students = []
        
        if connection:
            try:
                with connection.cursor() as cursor:
                    # First get the academic level name
                    cursor.execute("""
                        SELECT level_name
                        FROM academic_levels
                        WHERE id = %s
                    """, (academic_level_id,))
                    level_result = cursor.fetchone()
                    
                    if not level_result:
                        return jsonify({'success': False, 'message': 'Academic level not found.'}), 404
                    
                    level_name = level_result.get('level_name') if isinstance(level_result, dict) else level_result[0]
                    
                    # Get all students with current_grade matching the level_name
                    cursor.execute("""
                        SELECT s.id, s.student_id, s.full_name, s.date_of_birth, s.gender, 
                               s.current_grade, s.status, s.student_category,
                               p.full_name as parent_name, p.phone as parent_phone, 
                               p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE s.current_grade = %s
                        ORDER BY s.full_name ASC
                    """, (level_name,))
                    results = cursor.fetchall()
                    
                    for row in results:
                        date_of_birth = row.get('date_of_birth') if isinstance(row, dict) else row[3]
                        dob_str = date_of_birth.strftime('%Y-%m-%d') if date_of_birth and hasattr(date_of_birth, 'strftime') else (str(date_of_birth) if date_of_birth else None)
                        
                        students.append({
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'student_id': row.get('student_id') if isinstance(row, dict) else row[1],
                            'full_name': row.get('full_name') if isinstance(row, dict) else row[2],
                            'date_of_birth': dob_str,
                            'gender': row.get('gender') if isinstance(row, dict) else row[4],
                            'current_grade': row.get('current_grade') if isinstance(row, dict) else row[5],
                            'status': row.get('status') if isinstance(row, dict) else row[6],
                            'student_category': row.get('student_category') if isinstance(row, dict) else row[7],
                            'parent_name': row.get('parent_name') if isinstance(row, dict) else (row[8] if len(row) > 8 else None),
                            'parent_phone': row.get('parent_phone') if isinstance(row, dict) else (row[9] if len(row) > 9 else None),
                            'parent_email': row.get('parent_email') if isinstance(row, dict) else (row[10] if len(row) > 10 else None)
                        })
                    
                    return jsonify({
                        'success': True,
                        'students': students,
                        'count': len(students)
                    })
            except Exception as e:
                print(f"Error fetching students: {e}")
                return jsonify({'success': False, 'message': f'Error fetching students: {str(e)}'}), 500
            finally:
                connection.close()
        else:
            return jsonify({'success': False, 'message': 'Database connection failed.'}), 500
            
    except Exception as e:
        print(f"Error in get_students_by_academic_level: {e}")
        return jsonify({'success': False, 'message': 'An error occurred.'}), 500

def _level_combo_display_row(combo, level_by_id):
    """Build label fields for a combined academic level group."""
    mids = combo.get('member_level_ids') or []
    names = []
    codes = []
    cats = []
    for mid in mids:
        lv = level_by_id.get(int(mid)) or {}
        names.append((lv.get('level_name') or '—').strip())
        codes.append((lv.get('level_code') or '').strip())
        cat = (lv.get('level_category') or '').strip()
        if cat:
            cats.append(cat)
    label_name = ' / '.join(names) if names else '—'
    label_code = ' / '.join(c for c in codes if c) or '—'
    if cats and len(set(cats)) == 1:
        level_category = cats[0]
    else:
        level_category = ', '.join(sorted(set(cats))) if cats else ''
    return {
        'combo_id': int(combo['id']),
        'level_ids': [int(x) for x in mids],
        'level_names': names,
        'level_name': label_name,
        'level_category': level_category,
        'level_code': label_code,
    }


def _exam_analytics_resolve_level_scope(level_view, selected_level_id, levels, level_combinations):
    """Resolve which academic level(s) to include for exam analytics detail."""
    level_by_id = {int(l['id']): l for l in (levels or []) if l.get('id') is not None}
    combo_by_member = {}
    for combo in level_combinations or []:
        disp = _level_combo_display_row(combo, level_by_id)
        for mid in disp.get('level_ids') or []:
            combo_by_member[int(mid)] = disp

    lv = level_by_id.get(int(selected_level_id)) if selected_level_id else None
    single_name = (lv.get('level_name') or '').strip() if lv else ''

    if (level_view or '').strip().lower() == 'combined':
        disp = combo_by_member.get(int(selected_level_id)) if selected_level_id else None
        if not disp and level_combinations:
            disp = _level_combo_display_row(level_combinations[0], level_by_id)
        if disp and disp.get('level_ids'):
            return {
                'level_ids': list(disp['level_ids']),
                'level_names': list(disp['level_names']),
                'display_name': disp['level_name'],
                'level_category': disp.get('level_category') or '',
                'is_combined_view': True,
                'combo_id': disp.get('combo_id'),
            }

    return {
        'level_ids': [int(selected_level_id)] if selected_level_id else [],
        'level_names': [single_name] if single_name else [],
        'display_name': single_name or '—',
        'level_category': (lv.get('level_category') or '') if lv else '',
        'is_combined_view': False,
        'combo_id': None,
    }


def _build_exam_class_report(
    cursor,
    level_ids,
    level_names,
    display_name,
    level_category,
    term_id,
    academic_year_id,
    exam_extra_sql,
    exam_extra_params,
    default_grade_bands,
    subject_grade_bands,
    class_grade_bands=None,
    *,
    is_combined=False,
    combo_id=None,
    primary_level_id=None,
    subject_exam_totals_override=None,
    subject_exam_display_order_override=None,
):
    """Build one exam performance report card for one level or a combined level group."""
    level_ids = [int(x) for x in (level_ids or []) if x is not None]
    level_names = [str(n).strip() for n in (level_names or []) if n and str(n).strip()]
    if not level_ids or not level_names:
        return None

    level_placeholders = ','.join(['%s'] * len(level_ids))
    name_placeholders = ','.join(['%s'] * len(level_names))

    cursor.execute(
        f"""
        SELECT e.id, e.exam_name, e.subject_id, e.exam_date,
               s.subject_name, s.subject_code, s.exam_total_marks, s.exam_display_order,
               ay.year_name, t.term_name
        FROM exams e
        LEFT JOIN subjects s ON e.subject_id = s.id
        LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
        LEFT JOIN terms t ON e.term_id = t.id
        WHERE e.academic_level_id IN ({level_placeholders})
        AND (%s IS NULL OR e.term_id = %s)
        AND (%s IS NULL OR e.academic_year_id = %s)
        {exam_extra_sql}
        ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC,
                 s.subject_name ASC,
                 e.exam_name ASC
        """,
        tuple(level_ids) + (term_id, term_id, academic_year_id, academic_year_id) + tuple(exam_extra_params),
    )
    exam_rows = cursor.fetchall() or []

    subject_stats = {}
    all_marks_for_class = []
    students_in_class = set()
    student_subject_scaled = defaultdict(lambda: defaultdict(list))

    for ex in exam_rows:
        exam_id = ex.get('id') if isinstance(ex, dict) else ex[0]
        subject_id = ex.get('subject_id') if isinstance(ex, dict) else ex[2]
        if isinstance(ex, dict):
            subject_name = ex.get('subject_name') or ex.get('subject_code') or 'N/A'
            subject_etm = ex.get('exam_total_marks')
            subject_edo = ex.get('exam_display_order')
        else:
            subject_name = ex[4] or ex[5] or 'N/A'
            subject_etm = ex[6] if len(ex) > 6 else None
            subject_edo = ex[7] if len(ex) > 7 else None

        if not subject_id:
            continue
        if subject_id not in subject_stats:
            try:
                edo_n = int(subject_edo) if subject_edo is not None and str(subject_edo).strip().isdigit() else (
                    int(subject_edo) if isinstance(subject_edo, int) else 10**9
                )
            except (TypeError, ValueError):
                edo_n = 10**9
            if subject_exam_display_order_override:
                ov_edo = subject_exam_display_order_override.get(str(subject_id))
                if ov_edo is None:
                    ov_edo = subject_exam_display_order_override.get(int(subject_id))
                if ov_edo is not None:
                    try:
                        edo_n = int(ov_edo)
                    except (TypeError, ValueError):
                        pass
            subject_stats[subject_id] = {
                'subject_name': subject_name,
                'exam_total_marks': subject_etm,
                'exam_display_order': edo_n,
                'exam_ids': [],
                'marks': [],
                'mean': 0,
                'min': None,
                'max': None,
                'count': 0,
                'pass_count': 0,
                'pass_rate': 0,
            }
        subject_stats[subject_id]['exam_ids'].append(exam_id)

        cursor.execute(
            f"""
            SELECT sm.student_id, sm.marks, sub.exam_total_marks
            FROM student_marks sm
            INNER JOIN students st ON sm.student_id = st.student_id
            INNER JOIN subjects sub ON sm.subject_id = sub.id
            WHERE sm.exam_id = %s AND st.current_grade IN ({name_placeholders})
            """,
            [exam_id] + level_names,
        )
        mark_rows = cursor.fetchall() or []
        for mr in mark_rows:
            sid = mr.get('student_id') if isinstance(mr, dict) else mr[0]
            mval = mr.get('marks') if isinstance(mr, dict) else mr[1]
            etm = mr.get('exam_total_marks') if isinstance(mr, dict) else (mr[2] if len(mr) > 2 else None)
            if etm is None:
                etm = subject_stats[subject_id].get('exam_total_marks')
            if subject_exam_totals_override:
                ov = subject_exam_totals_override.get(str(subject_id))
                if ov is None:
                    ov = subject_exam_totals_override.get(int(subject_id))
                if ov is not None:
                    etm = ov
            scaled = raw_mark_to_percentage(mval, etm)
            if scaled is not None:
                subject_stats[subject_id]['marks'].append(scaled)
                all_marks_for_class.append(scaled)
                students_in_class.add(sid)
                student_subject_scaled[sid][subject_id].append(scaled)
                if scaled >= 50:
                    subject_stats[subject_id]['pass_count'] += 1

    registered_subject_ids = set()
    for lid in level_ids:
        for _sub in _library_subjects_for_level(cursor, lid):
            try:
                registered_subject_ids.add(int(_sub.get('id') or 0))
            except (TypeError, ValueError):
                pass
    if registered_subject_ids:
        subject_stats = {
            sid: sd for sid, sd in subject_stats.items() if sid in registered_subject_ids
        }

    subject_list = []

    def _report_subject_sort_key(kv):
        sid_i, sd = kv
        try:
            eo = int(sd.get('exam_display_order') or 10**9)
        except (TypeError, ValueError):
            eo = 10**9
        try:
            sid_key = int(sid_i)
        except (TypeError, ValueError):
            sid_key = 0
        return (eo, str(sd.get('subject_name') or '').lower(), sid_key)

    for sid, sdata in sorted(subject_stats.items(), key=_report_subject_sort_key):
        marks = sdata['marks']
        if marks:
            sdata['mean'] = round_mark_display(sum(marks) / len(marks)) or 0
            sdata['min'] = round_mark_display(min(marks))
            sdata['max'] = round_mark_display(max(marks))
            sdata['count'] = len(marks)
            sdata['pass_rate'] = round_mark_display(100 * sdata['pass_count'] / len(marks)) if marks else 0
        else:
            sdata['mean'] = 0
            sdata['min'] = None
            sdata['max'] = None
            sdata['count'] = 0
            sdata['pass_rate'] = 0
        try:
            sid_int = int(sid)
        except (TypeError, ValueError):
            sid_int = 0
        subj_bands = resolve_grade_bands(
            primary_level_id, class_grade_bands or {}, default_grade_bands
        )
        grade_code, grade_points = grade_code_and_points_from_pct(
            sdata['mean'] if marks else None, subj_bands
        )
        subject_list.append({
            'subject_name': sdata['subject_name'],
            'mean': sdata['mean'],
            'min': sdata['min'],
            'max': sdata['max'],
            'count': sdata['count'],
            'pass_rate': sdata['pass_rate'],
            'grade_code': grade_code or '—',
            'grade_points': grade_points if grade_points is not None else '—',
        })

    student_overall_means = []
    for _sid, submap in student_subject_scaled.items():
        sub_avgs = []
        for _vals in submap.values():
            if _vals:
                sub_avgs.append(sum(_vals) / len(_vals))
        if sub_avgs:
            student_overall_means.append(sum(sub_avgs) / len(sub_avgs))
    class_grade_mean = (
        round_mark_display(sum(student_overall_means) / len(student_overall_means))
        if student_overall_means else None
    )
    class_bands = resolve_grade_bands(
        primary_level_id, class_grade_bands or {}, default_grade_bands
    )
    class_grade_code, class_grade_points = grade_code_and_points_from_pct(
        class_grade_mean, class_bands
    )

    class_mean = round_mark_display(sum(all_marks_for_class) / len(all_marks_for_class)) if all_marks_for_class else 0
    pass_n = sum(1 for m in all_marks_for_class if m >= 50)
    class_pass_rate = (
        round_mark_display(100 * pass_n / len(all_marks_for_class)) if all_marks_for_class else 0
    )
    class_max = round_mark_display(max(all_marks_for_class)) if all_marks_for_class else None
    class_min = round_mark_display(min(all_marks_for_class)) if all_marks_for_class else None

    out_level_id = primary_level_id if primary_level_id is not None else (level_ids[0] if level_ids else None)
    return {
        'level_id': out_level_id,
        'combo_id': combo_id,
        'is_combined': bool(is_combined),
        'member_level_ids': list(level_ids) if is_combined else [],
        'member_level_names': list(level_names) if is_combined else [],
        'level_name': display_name,
        'level_category': level_category or '',
        'subjects': subject_list,
        'class_mean': class_mean,
        'class_max': class_max,
        'class_min': class_min,
        'class_pass_rate': class_pass_rate,
        'class_grade_mean': class_grade_mean,
        'class_grade_code': class_grade_code or '—',
        'class_grade_points': class_grade_points if class_grade_points is not None else '—',
        'student_count': len(students_in_class),
        'total_marks_entries': len(all_marks_for_class),
    }


# Reports Route (for academic coordinators)
@app.route('/dashboard/employee/reports')
@login_required
def reports():
    """Exam reports for staff; secretary sees class overview + school snapshot on this route."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_secretary):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Secretary: class overview cards + school snapshot
    if is_secretary:
        class_analytics = []
        stats_snapshot = {'active_students': 0, 'teachers': 0, 'subjects': 0}
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    ensure_subject_exam_display_order_columns(cursor)
                    stats_snapshot = _fetch_reports_snapshot_counts(cursor)
                    cursor.execute("""
                        SELECT al.id, al.level_name, al.level_category,
                            (SELECT COUNT(*) FROM students s
                             WHERE s.status = 'in session' AND s.current_grade = al.level_name) AS student_count,
                            (SELECT COUNT(DISTINCT tsa.teacher_id) FROM teacher_subject_assignments tsa
                             WHERE tsa.academic_level_id = al.id) AS teacher_count,
                            (SELECT COUNT(DISTINCT tsa.subject_id) FROM teacher_subject_assignments tsa
                             WHERE tsa.academic_level_id = al.id) AS subject_count
                        FROM academic_levels al
                        WHERE al.level_status = 'active'
                        ORDER BY al.level_name
                    """)
                    for row in cursor.fetchall() or []:
                        class_analytics.append({
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
                            'level_category': row.get('level_category') if isinstance(row, dict) else row[2],
                            'student_count': int(row.get('student_count') or 0) if isinstance(row, dict) else int(row[3] or 0),
                            'teacher_count': int(row.get('teacher_count') or 0) if isinstance(row, dict) else int(row[4] or 0),
                            'subject_count': int(row.get('subject_count') or 0) if isinstance(row, dict) else int(row[5] or 0),
                        })
            except Exception as e:
                print(f"Error in reports class analytics: {e}")
                import traceback
                traceback.print_exc()
                flash('Error loading class overview.', 'error')
            finally:
                connection.close()
        return render_template(
            'dashboards/reports_class_analytics.html',
            role=user_role,
            class_analytics=class_analytics,
            stats_snapshot=stats_snapshot,
        )
    
    level_id = request.args.get('level_id', type=int)
    term_id = request.args.get('term_id', type=int)
    academic_year_id = request.args.get('academic_year_id', type=int)
    has_term_param = 'term_id' in request.args
    has_year_param = 'academic_year_id' in request.args
    has_exam_i_param = 'exam_i' in request.args
    report_view = (request.args.get('report_view') or 'all').strip().lower()
    if report_view not in ('all', 'combined', 'individual'):
        report_view = 'all'

    academic_levels = []
    terms = []
    academic_years = []
    report_data = None
    combined_report_data = None
    level_combinations = []
    stats_snapshot = {'active_students': 0, 'teachers': 0, 'subjects': 0}
    exam_group_options = []
    selected_exam_i = -1
    registered_current_exam = None
    exam_filter_name_only = False

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_subject_exam_display_order_columns(cursor)
                ensure_subject_exam_total_marks_column(cursor)
                ensure_academic_level_combination_tables(cursor)
                stats_snapshot = _fetch_reports_snapshot_counts(cursor)
                level_combinations = fetch_academic_level_combinations(cursor)
                # Get academic levels
                cursor.execute("""
                    SELECT id, level_name, level_category, level_description
                    FROM academic_levels WHERE level_status = 'active'
                    ORDER BY level_name
                """)
                for row in cursor.fetchall() or []:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
                        'level_category': row.get('level_category') if isinstance(row, dict) else row[2],
                        'level_description': row.get('level_description') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                    })
                
                # Get terms
                cursor.execute("""
                    SELECT id, term_name, academic_year_id, status
                    FROM terms ORDER BY id DESC
                """)
                for row in cursor.fetchall() or []:
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name') if isinstance(row, dict) else row[1],
                        'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else row[2],
                        'status': row.get('status') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                    })
                
                # Get academic years
                cursor.execute("""
                    SELECT id, year_name, is_current
                    FROM academic_years ORDER BY id DESC
                """)
                for row in cursor.fetchall() or []:
                    academic_years.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'year_name': row.get('year_name') if isinstance(row, dict) else row[1],
                        'is_current': row.get('is_current') if isinstance(row, dict) else (row[2] if len(row) > 2 else False),
                    })

                # Default filters for first page load:
                # current academic year + current term (scoped to that year when possible).
                if not has_year_param and not academic_year_id and academic_years:
                    current_year = next((y for y in academic_years if y.get('is_current')), None)
                    academic_year_id = (current_year or academic_years[0]).get('id')

                if not has_term_param and not term_id and terms:
                    terms_for_year = [t for t in terms if not academic_year_id or t.get('academic_year_id') == academic_year_id]
                    if not terms_for_year:
                        terms_for_year = list(terms)
                    current_term = next((t for t in terms_for_year if str(t.get('status') or '').strip().lower() == 'current'), None)
                    term_id = (current_term or terms_for_year[0]).get('id')

                registered_current_exam = load_registered_current_exam_dict(cursor)
                exam_group_options = []
                try:
                    cursor.execute("""
                        SELECT DISTINCT TRIM(e.exam_name) AS en, TRIM(COALESCE(e.exam_type, '')) AS et
                        FROM exams e
                        WHERE (%s IS NULL OR e.academic_year_id = %s)
                          AND (%s IS NULL OR e.term_id = %s)
                          AND TRIM(COALESCE(e.exam_name, '')) <> ''
                        ORDER BY en ASC, et ASC
                    """, (academic_year_id, academic_year_id, term_id, term_id))
                    for row in cursor.fetchall() or []:
                        en = (row.get('en') if isinstance(row, dict) else row[0]) or ''
                        et = (row.get('et') if isinstance(row, dict) else row[1]) or ''
                        exam_group_options.append({
                            'exam_name': str(en).strip(),
                            'exam_type': str(et).strip(),
                        })
                except Exception as _eg:
                    print(f"reports exam_group_options: {_eg}")
                    exam_group_options = []

                reg = registered_current_exam
                if has_exam_i_param:
                    try:
                        selected_exam_i = int((request.args.get('exam_i') or '-1').strip())
                    except (TypeError, ValueError):
                        selected_exam_i = -1
                    if selected_exam_i < -1 or selected_exam_i >= len(exam_group_options):
                        selected_exam_i = -1
                    exam_filter_name_only = False
                else:
                    selected_exam_i = -1
                    exam_filter_name_only = False
                    if reg and academic_year_id and term_id:
                        try:
                            if int(reg.get('academic_year_id') or 0) == int(academic_year_id) and int(reg.get('term_id') or 0) == int(term_id):
                                want_n = (reg.get('exam_name') or '').strip().upper()
                                want_typ = reg.get('exam_type')
                                for i, opt in enumerate(exam_group_options):
                                    on = (opt.get('exam_name') or '').strip().upper()
                                    ot = (opt.get('exam_type') or '').strip().upper()
                                    if on != want_n:
                                        continue
                                    if want_typ is None:
                                        selected_exam_i = i
                                        exam_filter_name_only = True
                                        break
                                    if ot == (want_typ or '').strip().upper():
                                        selected_exam_i = i
                                        exam_filter_name_only = False
                                        break
                        except (TypeError, ValueError):
                            pass

                if reg:
                    rn = (reg.get('exam_name') or '').strip().upper()
                    rt = reg.get('exam_type')
                    for opt in exam_group_options:
                        on = (opt.get('exam_name') or '').strip().upper()
                        ot = (opt.get('exam_type') or '').strip().upper()
                        if on != rn:
                            opt['is_school_current'] = False
                            continue
                        if rt is None:
                            opt['is_school_current'] = True
                        else:
                            opt['is_school_current'] = (ot == (rt or '').strip().upper())
                else:
                    for opt in exam_group_options:
                        opt['is_school_current'] = False

                exam_extra_sql = ""
                exam_extra_params = []
                if 0 <= selected_exam_i < len(exam_group_options):
                    opt = exam_group_options[selected_exam_i]
                    nm = (opt.get('exam_name') or '').strip().upper()
                    exam_extra_sql = " AND UPPER(TRIM(e.exam_name)) = %s "
                    exam_extra_params.append(nm)
                    if not exam_filter_name_only:
                        tt = (opt.get('exam_type') or '').strip().upper()
                        exam_extra_sql += " AND UPPER(TRIM(COALESCE(e.exam_type, ''))) = %s "
                        exam_extra_params.append(tt)

                # Build report if filters provided
                if level_id or term_id or academic_year_id:
                    level_by_id = {int(l['id']): l for l in academic_levels if l.get('id') is not None}

                    report_data = []
                    combined_report_data = []
                    report_exam_name = None
                    report_exam_type = None
                    if exam_extra_params:
                        report_exam_name = (exam_extra_params[0] or '').strip().upper() or None
                        if len(exam_extra_params) > 1 and not exam_filter_name_only:
                            report_exam_type = (exam_extra_params[1] or '').strip().upper() or None

                    report_reg_current = load_registered_current_exam_dict(cursor)

                    report_level_combinations = level_combinations
                    if report_exam_name and academic_year_id and term_id:
                        snap_level_id = level_id
                        if not snap_level_id and academic_levels:
                            snap_level_id = academic_levels[0].get('id')
                        if snap_level_id and not _should_use_live_exam_settings(
                            report_exam_name, academic_year_id, term_id,
                            report_reg_current, report_exam_type,
                        ):
                            report_level_combinations = fetch_academic_level_combinations_for_context(
                                cursor, report_exam_name, academic_year_id, term_id, snap_level_id,
                                registered_current=report_reg_current, exam_type=report_exam_type,
                            )

                    member_level_ids_set = set()
                    combo_by_member = {}
                    for combo in report_level_combinations:
                        disp = _level_combo_display_row(combo, level_by_id)
                        for mid in disp.get('level_ids') or []:
                            member_level_ids_set.add(int(mid))
                            combo_by_member[int(mid)] = disp

                    combos_to_build = []
                    for combo in report_level_combinations:
                        disp = _level_combo_display_row(combo, level_by_id)
                        if not disp.get('level_ids'):
                            continue
                        if level_id:
                            if level_id not in disp['level_ids']:
                                continue
                        combos_to_build.append(disp)

                    if report_view in ('all', 'combined'):
                        for disp in combos_to_build:
                            plid = disp['level_ids'][0] if disp.get('level_ids') else None
                            default_grade_bands, subject_grade_bands, class_grade_bands = (
                                load_grade_bands_for_exam_context(
                                    cursor, report_exam_name, academic_year_id, term_id, plid,
                                    registered_current=report_reg_current, exam_type=report_exam_type,
                                )
                            )
                            totals_ov = None
                            edo_ov = None
                            if not _should_use_live_exam_settings(
                                report_exam_name, academic_year_id, term_id,
                                report_reg_current, report_exam_type,
                            ):
                                snap = get_exam_context_settings_snapshot(
                                    cursor, report_exam_name, academic_year_id, term_id, plid,
                                )
                                totals_ov = (snap or {}).get('subject_exam_totals')
                                edo_ov = (snap or {}).get('subject_exam_display_order')
                            row = _build_exam_class_report(
                                cursor,
                                disp['level_ids'],
                                disp['level_names'],
                                disp['level_name'],
                                disp.get('level_category') or '',
                                term_id,
                                academic_year_id,
                                exam_extra_sql,
                                exam_extra_params,
                                default_grade_bands,
                                subject_grade_bands,
                                class_grade_bands,
                                is_combined=True,
                                combo_id=disp['combo_id'],
                                primary_level_id=plid,
                                subject_exam_totals_override=totals_ov,
                                subject_exam_display_order_override=edo_ov,
                            )
                            if row:
                                combined_report_data.append(row)

                    if report_view in ('all', 'individual'):
                        if level_id:
                            levels_to_report = [l for l in academic_levels if l['id'] == level_id]
                            if report_view == 'all' and int(level_id) in member_level_ids_set:
                                levels_to_report = []
                        else:
                            levels_to_report = [
                                l for l in academic_levels
                                if int(l['id']) not in member_level_ids_set
                            ]
                        for lev in levels_to_report:
                            default_grade_bands, subject_grade_bands, class_grade_bands = (
                                load_grade_bands_for_exam_context(
                                    cursor, report_exam_name, academic_year_id, term_id, lev['id'],
                                    registered_current=report_reg_current, exam_type=report_exam_type,
                                )
                            )
                            totals_ov = None
                            edo_ov = None
                            if not _should_use_live_exam_settings(
                                report_exam_name, academic_year_id, term_id,
                                report_reg_current, report_exam_type,
                            ):
                                snap = get_exam_context_settings_snapshot(
                                    cursor, report_exam_name, academic_year_id, term_id, lev['id'],
                                )
                                totals_ov = (snap or {}).get('subject_exam_totals')
                                edo_ov = (snap or {}).get('subject_exam_display_order')
                            row = _build_exam_class_report(
                                cursor,
                                [lev['id']],
                                [lev['level_name']],
                                lev['level_name'],
                                lev.get('level_category') or '',
                                term_id,
                                academic_year_id,
                                exam_extra_sql,
                                exam_extra_params,
                                default_grade_bands,
                                subject_grade_bands,
                                class_grade_bands,
                                is_combined=False,
                                primary_level_id=lev['id'],
                                subject_exam_totals_override=totals_ov,
                                subject_exam_display_order_override=edo_ov,
                            )
                            if row:
                                report_data.append(row)
        except Exception as e:
            print(f"Error in reports: {e}")
            import traceback
            traceback.print_exc()
            flash(f'Error loading report: {str(e)}', 'error')
        finally:
            connection.close()
    
    return render_template('dashboards/reports.html',
        role=user_role,
        academic_levels=academic_levels,
        terms=terms,
        academic_years=academic_years,
        report_data=report_data,
        combined_report_data=combined_report_data,
        level_combinations=level_combinations,
        selected_report_view=report_view,
        selected_level_id=level_id,
        selected_term_id=term_id,
        selected_academic_year_id=academic_year_id,
        selected_exam_i=selected_exam_i,
        exam_group_options=exam_group_options,
        registered_current_exam=registered_current_exam,
        stats_snapshot=stats_snapshot,
        sidebar_hide_accounts_fees=is_academic_coordinator,
    )


def _reports_access_roles_ok():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    return (
        user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
        or user_role == 'technician'
        or user_role == 'head of institution' or viewing_as_role == 'head of institution'
        or user_role == 'secretary' or viewing_as_role == 'secretary'
    )


@app.route('/dashboard/employee/reports/class/<int:level_id>')
@login_required
def reports_class_detail(level_id):
    """Per-class hub: register (attendance) analytics, exam performance, and fee accounts."""
    if not _reports_access_roles_ok():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'

    connection = get_db_connection()
    if not connection:
        flash('Database connection error.', 'error')
        return redirect(url_for('reports'))

    level = None
    attendance_summary = {}
    exam_bundle = {}
    fees_bundle = {'student_rows': [], 'total_outstanding': 0.0}
    enrolled_count = 0

    try:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT id, level_name, level_category, level_description
                FROM academic_levels
                WHERE id = %s AND level_status = 'active'
                """,
                (level_id,),
            )
            row = cursor.fetchone()
            if not row:
                flash('That class was not found or is inactive.', 'error')
                return redirect(url_for('reports'))
            level = {
                'id': row.get('id') if isinstance(row, dict) else row[0],
                'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
                'level_category': row.get('level_category') if isinstance(row, dict) else row[2],
                'level_description': (row.get('level_description') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')) or '',
            }
            cursor.execute(
                """
                SELECT COUNT(*) AS c FROM students
                WHERE current_grade = %s AND status = 'in session'
                """,
                (level['level_name'],),
            )
            er = cursor.fetchone()
            enrolled_count = int((er.get('c') if isinstance(er, dict) else er[0]) or 0)

            attendance_summary = _class_attendance_register_summary(cursor, level['level_name'])
            exam_bundle = _build_class_exam_performance_bundle(cursor, level, None, None)
            fees_bundle = _class_fees_accounts_bundle(cursor, level_id, level['level_name'])
    except Exception as e:
        print(f"reports_class_detail: {e}")
        import traceback
        traceback.print_exc()
        flash('Could not load class analytics.', 'error')
        return redirect(url_for('reports'))
    finally:
        connection.close()

    return render_template(
        'dashboards/reports_class_detail.html',
        role=user_role,
        is_secretary_finance=is_secretary,
        level=level,
        enrolled_count=enrolled_count,
        attendance_summary=attendance_summary,
        exam_bundle=exam_bundle,
        fees_bundle=fees_bundle,
    )


def _fetch_reports_snapshot_counts(cursor):
    """School-wide figures for the reports hub: enrolled students, teaching staff, active subjects."""
    out = {'active_students': 0, 'teachers': 0, 'subjects': 0}
    try:
        cursor.execute("SELECT COUNT(*) as c FROM students WHERE status = 'in session'")
        r = cursor.fetchone()
        out['active_students'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
    except Exception:
        pass
    try:
        cursor.execute("""
            SELECT COUNT(*) as c FROM employees
            WHERE status = 'active' AND (role = 'teachers' OR role = 'teacher')
        """)
        r = cursor.fetchone()
        out['teachers'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
    except Exception:
        pass
    try:
        cursor.execute("SELECT COUNT(*) as c FROM subjects WHERE status = 'active'")
        r = cursor.fetchone()
        out['subjects'] = int((r.get('c') if isinstance(r, dict) else r[0]) or 0)
    except Exception:
        pass
    return out


def _class_attendance_register_summary(cursor, level_name):
    """Attendance register analytics for students in this class (current_grade match, in session)."""
    out = {
        'total_records': 0,
        'present_count': 0,
        'absent_count': 0,
        'students_with_records': 0,
        'rate_pct': None,
    }
    if not level_name:
        return out
    try:
        cursor.execute(
            """
            SELECT COUNT(*) AS n,
                   COALESCE(SUM(CASE WHEN sar.present THEN 1 ELSE 0 END), 0) AS pn
            FROM student_attendance_records sar
            INNER JOIN students s ON s.student_id = sar.student_id
            WHERE s.current_grade = %s AND s.status = 'in session'
            """,
            (level_name,),
        )
        r = cursor.fetchone()
        if r:
            n = int((r.get('n') if isinstance(r, dict) else r[0]) or 0)
            pn = int((r.get('pn') if isinstance(r, dict) else r[1]) or 0)
            out['total_records'] = n
            out['present_count'] = pn
            out['absent_count'] = max(0, n - pn)
            if n:
                out['rate_pct'] = round(100.0 * pn / n, 1)
        cursor.execute(
            """
            SELECT COUNT(DISTINCT sar.student_id) AS c
            FROM student_attendance_records sar
            INNER JOIN students s ON s.student_id = sar.student_id
            WHERE s.current_grade = %s AND s.status = 'in session'
            """,
            (level_name,),
        )
        r2 = cursor.fetchone()
        if r2:
            out['students_with_records'] = int((r2.get('c') if isinstance(r2, dict) else r2[0]) or 0)
    except Exception as e:
        print(f"_class_attendance_register_summary: {e}")
    return out


def _reports_current_year_term_ids(cursor):
    """Same current year/term resolution as student_fees."""
    current_academic_year_id = None
    current_term_id = None
    try:
        cursor.execute(
            """
            SELECT id FROM academic_years
            WHERE is_current = TRUE AND status = 'active'
            LIMIT 1
            """
        )
        r = cursor.fetchone()
        if r:
            current_academic_year_id = r.get('id') if isinstance(r, dict) else r[0]
        if current_academic_year_id:
            cursor.execute(
                """
                SELECT id FROM terms
                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                LIMIT 1
                """,
                (current_academic_year_id,),
            )
            r2 = cursor.fetchone()
            if r2:
                current_term_id = r2.get('id') if isinstance(r2, dict) else r2[0]
    except Exception as e:
        print(f"_reports_current_year_term_ids: {e}")
    return current_academic_year_id, current_term_id


def _fee_structure_batch_key_parts(fee_name, academic_year_id, term_id, category, finance_account_id):
    fa = finance_account_id
    return (
        str(fee_name or '').strip().lower(),
        str(academic_year_id or ''),
        str(term_id or ''),
        str(category or 'both').strip().lower(),
        '' if fa is None or fa == '' else str(fa),
    )


def _fee_structure_category_sql_parts(student_category):
    """Category filter + ORDER BY CASE for active fee structure selection."""
    student_category = (student_category or '').lower().strip()
    if student_category == 'self sponsored':
        return (
            " AND (fs.category = 'self sponsored' OR fs.category = 'both')",
            """CASE
                WHEN fs.category = 'self sponsored' THEN 1
                WHEN fs.category = 'both' THEN 2
                ELSE 3
            END""",
        )
    if student_category == 'sponsored':
        return (
            " AND (fs.category = 'sponsored' OR fs.category = 'both')",
            """CASE
                WHEN fs.category = 'sponsored' THEN 1
                WHEN fs.category = 'both' THEN 2
                ELSE 3
            END""",
        )
    if student_category == 'both':
        return (
            '',
            """CASE
                WHEN fs.category = 'both' THEN 1
                WHEN fs.category = 'self sponsored' THEN 2
                WHEN fs.category = 'sponsored' THEN 3
                WHEN fs.category IS NULL THEN 4
                ELSE 5
            END""",
        )
    return (
        " AND fs.category = 'both'",
        '1',
    )


def _active_fee_structure_select_from_clause():
    return """
        FROM fee_structures fs
        LEFT JOIN finance_accounts fa ON fa.id = fs.finance_account_id
        LEFT JOIN terms t ON t.id = fs.term_id
        LEFT JOIN academic_years ay ON ay.id = fs.academic_year_id
    """


def _select_active_fee_structure_for_level(
    cursor, academic_level_id, student_category,
    current_academic_year_id=None, current_term_id=None,
):
    """One active fee structure row for a level (current year/term, category rules, prefers finance-linked)."""
    category_filter_sql, order_category_sql = _fee_structure_category_sql_parts(student_category)
    params = [academic_level_id]
    year_term_sql = ''
    if current_academic_year_id and current_term_id:
        year_term_sql = ' AND fs.academic_year_id = %s AND fs.term_id = %s'
        params.extend([current_academic_year_id, current_term_id])
    sql = f"""
        SELECT fs.id, fs.fee_name, fs.start_date, fs.end_date,
               fs.payment_deadline, fs.total_amount, fs.status, fs.category,
               fs.finance_account_id, fs.academic_year_id, fs.term_id,
               fa.account_name AS finance_account_name,
               t.term_name, ay.year_name AS academic_year_name
        {_active_fee_structure_select_from_clause()}
        WHERE fs.academic_level_id = %s
          AND fs.status = 'active'
          {year_term_sql}
          {category_filter_sql}
        ORDER BY
          (fs.finance_account_id IS NOT NULL) DESC,
          {order_category_sql},
          fs.created_at DESC
        LIMIT 1
    """
    try:
        cursor.execute(sql, tuple(params))
        row = cursor.fetchone()
    except Exception as e:
        print(f"_select_active_fee_structure_for_level: {e}")
        return None
    return _reports_fee_structure_dict_from_row(row)


def _group_fee_structure_rows_into_batches(rows):
    """Group per-level fee structure rows into batched display groups (fee structures page model)."""
    buckets = {}
    for row in rows or []:
        if not isinstance(row, dict):
            continue
        key = _fee_structure_batch_key_parts(
            row.get('fee_name'),
            row.get('academic_year_id'),
            row.get('term_id'),
            row.get('category'),
            row.get('finance_account_id'),
        )
        buckets.setdefault(key, []).append(row)

    batches = []
    for group in buckets.values():
        if not group:
            continue
        first = group[0]
        level_names = []
        structure_ids = []
        for r in group:
            sid = r.get('id')
            if sid is not None:
                structure_ids.append(sid)
            ln = (r.get('level_name') or '').strip()
            if ln and not any(n.lower() == ln.lower() for n in level_names):
                level_names.append(ln)
        level_names.sort(key=lambda n: n.lower())

        payment_deadline = first.get('payment_deadline')
        if payment_deadline and hasattr(payment_deadline, 'strftime'):
            payment_deadline = payment_deadline.strftime('%Y-%m-%d')
        elif payment_deadline:
            payment_deadline = str(payment_deadline).split(' ')[0]

        batches.append({
            'id': first.get('id'),
            'structure_ids': structure_ids,
            'fee_name': first.get('fee_name', ''),
            'category': first.get('category', 'both'),
            'finance_account_id': first.get('finance_account_id'),
            'finance_account_name': first.get('finance_account_name') or '',
            'academic_year_id': first.get('academic_year_id'),
            'academic_year_name': first.get('academic_year_name') or '',
            'term_id': first.get('term_id'),
            'term_name': first.get('term_name') or '',
            'total_amount': float(first.get('total_amount') or 0),
            'payment_deadline': payment_deadline,
            'level_names': level_names,
            'levels_label': ', '.join(level_names),
            'level_count': len(level_names),
            'status': first.get('status', 'active'),
        })
    batches.sort(key=lambda b: (b.get('fee_name') or '').lower())
    return batches


def _fetch_fee_structure_batches_for_display(cursor, academic_year_id=None, term_id=None):
    """Active fee structure batches for the current year/term (student fees page summary)."""
    ensure_fee_structures_finance_account_column(cursor)
    where = ["fs.status = 'active'"]
    params = []
    if academic_year_id and term_id:
        where.append('fs.academic_year_id = %s AND fs.term_id = %s')
        params.extend([academic_year_id, term_id])
    cursor.execute(
        f"""
        SELECT fs.id, fs.fee_name, fs.category, fs.total_amount, fs.status,
               fs.finance_account_id, fs.academic_year_id, fs.term_id,
               fs.payment_deadline,
               al.level_name,
               ay.year_name AS academic_year_name,
               t.term_name,
               fa.account_name AS finance_account_name
        FROM fee_structures fs
        LEFT JOIN academic_levels al ON al.id = fs.academic_level_id
        LEFT JOIN academic_years ay ON ay.id = fs.academic_year_id
        LEFT JOIN terms t ON t.id = fs.term_id
        LEFT JOIN finance_accounts fa ON fa.id = fs.finance_account_id
        WHERE {' AND '.join(where)}
        ORDER BY fs.fee_name ASC, al.level_name ASC
        """,
        tuple(params),
    )
    return _group_fee_structure_rows_into_batches(cursor.fetchall() or [])


def _reports_fee_structure_dict_from_row(fee_structure_result):
    """Normalize fee_structure row to dict with string dates (matches student_fees)."""
    if not fee_structure_result:
        return None
    start_date = fee_structure_result.get('start_date')
    end_date = fee_structure_result.get('end_date')
    payment_deadline = fee_structure_result.get('payment_deadline')
    if start_date and hasattr(start_date, 'strftime'):
        start_date = start_date.strftime('%Y-%m-%d')
    elif start_date:
        start_date = str(start_date).split(' ')[0]
    if end_date and hasattr(end_date, 'strftime'):
        end_date = end_date.strftime('%Y-%m-%d')
    elif end_date:
        end_date = str(end_date).split(' ')[0]
    if payment_deadline and hasattr(payment_deadline, 'strftime'):
        payment_deadline = payment_deadline.strftime('%Y-%m-%d')
    elif payment_deadline:
        payment_deadline = str(payment_deadline).split(' ')[0]
    return {
        'id': fee_structure_result.get('id'),
        'fee_name': fee_structure_result.get('fee_name', ''),
        'category': fee_structure_result.get('category', 'both'),
        'start_date': start_date,
        'end_date': end_date,
        'payment_deadline': payment_deadline,
        'total_amount': float(fee_structure_result.get('total_amount', 0)),
        'status': fee_structure_result.get('status', 'active'),
        'finance_account_id': fee_structure_result.get('finance_account_id'),
        'finance_account_name': fee_structure_result.get('finance_account_name') or '',
        'academic_year_id': fee_structure_result.get('academic_year_id'),
        'term_id': fee_structure_result.get('term_id'),
        'term_name': fee_structure_result.get('term_name') or '',
        'academic_year_name': fee_structure_result.get('academic_year_name') or '',
    }


def _reports_select_fee_structure_for_student(cursor, academic_level_id, student_category, current_academic_year_id, current_term_id):
    """Pick the same active fee structure as student_fees for this level + category."""
    return _select_active_fee_structure_for_level(
        cursor, academic_level_id, student_category,
        current_academic_year_id, current_term_id,
    )


def _reports_compute_student_fee_balance(
    cursor, student_id, student_category, academic_level_id, fee_structure,
    paid_amount_override=None,
):
    """Amounts for current structure + carry/previous terms — mirrors student_fees.

    Returns dict: total_amount (due), paid_amount (payments on current structure + carry-forward credits), balance.
    """
    if not fee_structure:
        return None
    total_paid = 0.0
    carry_forward = 0.0
    previous_term_balance = 0.0
    student_category = (student_category or '').lower().strip() if student_category else ''
    try:
        if paid_amount_override is not None:
            total_paid = float(paid_amount_override or 0)
        else:
            cursor.execute(
                """
                SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                FROM student_payments
                WHERE student_id = %s AND fee_structure_id = %s
                """,
                (student_id, fee_structure.get('id')),
            )
            payment_result = cursor.fetchone()
            if payment_result:
                total_paid = float(payment_result.get('total_paid', 0) if isinstance(payment_result, dict) else payment_result[0] or 0)

        if academic_level_id:
            current_start_date = fee_structure.get('start_date')
            if student_category == 'self sponsored':
                if current_start_date:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND (fs.end_date < CURDATE() OR (fs.end_date IS NOT NULL AND fs.end_date < %s))
                        AND (fs.category = 'self sponsored' OR fs.category = 'both')
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id'), current_start_date),
                    )
                else:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND fs.end_date < CURDATE()
                        AND (fs.category = 'self sponsored' OR fs.category = 'both')
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id')),
                    )
            elif student_category == 'sponsored':
                if current_start_date:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND (fs.end_date < CURDATE() OR (fs.end_date IS NOT NULL AND fs.end_date < %s))
                        AND (fs.category = 'sponsored' OR fs.category = 'both')
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id'), current_start_date),
                    )
                else:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND fs.end_date < CURDATE()
                        AND (fs.category = 'sponsored' OR fs.category = 'both')
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id')),
                    )
            elif student_category == 'both':
                if current_start_date:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND (fs.end_date < CURDATE() OR (fs.end_date IS NOT NULL AND fs.end_date < %s))
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id'), current_start_date),
                    )
                else:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND fs.end_date < CURDATE()
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id')),
                    )
            else:
                if current_start_date:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND (fs.end_date < CURDATE() OR (fs.end_date IS NOT NULL AND fs.end_date < %s))
                        AND fs.category = 'both'
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id'), current_start_date),
                    )
                else:
                    cursor.execute(
                        """
                        SELECT fs.id, fs.total_amount,
                               COALESCE(SUM(sp.amount_paid), 0) as total_paid
                        FROM fee_structures fs
                        LEFT JOIN student_payments sp ON fs.id = sp.fee_structure_id AND sp.student_id = %s
                        WHERE fs.academic_level_id = %s
                        AND fs.id != %s
                        AND fs.status = 'active'
                        AND fs.end_date < CURDATE()
                        AND fs.category = 'both'
                        GROUP BY fs.id, fs.total_amount
                        """,
                        (student_id, academic_level_id, fee_structure.get('id')),
                    )

            previous_structures = cursor.fetchall()
            for prev_struct in previous_structures:
                if isinstance(prev_struct, dict):
                    prev_total = float(prev_struct.get('total_amount', 0) or 0)
                    prev_paid = float(prev_struct.get('total_paid', 0) or 0)
                else:
                    prev_total = float(prev_struct[1] or 0) if len(prev_struct) > 1 else 0
                    prev_paid = float(prev_struct[2] or 0) if len(prev_struct) > 2 else 0
                prev_balance = prev_total - prev_paid
                if prev_balance < 0:
                    carry_forward += abs(prev_balance)
                elif prev_balance > 0:
                    previous_term_balance += prev_balance

        total_amount_due = float(fee_structure.get('total_amount', 0)) + previous_term_balance
        paid_applied = total_paid + carry_forward
        balance = total_amount_due - paid_applied
        return {
            'total_amount': total_amount_due,
            'paid_amount': paid_applied,
            'balance': balance,
            'carry_forward': carry_forward,
            'previous_term_balance': previous_term_balance,
            'total_paid_current': total_paid,
        }
    except Exception as e:
        print(f"_reports_compute_student_fee_balance: {e}")
        ta = float(fee_structure.get('total_amount', 0))
        return {
            'total_amount': ta,
            'paid_amount': 0.0,
            'balance': ta,
            'carry_forward': 0.0,
            'previous_term_balance': 0.0,
            'total_paid_current': 0.0,
        }


def _class_fees_accounts_bundle(cursor, level_id, level_name):
    """Per-student fee balances for this class + payment ids for receipt links (same logic as student_fees)."""
    student_rows = []
    total_outstanding = 0.0
    if not level_name:
        return {'student_rows': [], 'total_outstanding': 0.0}

    try:
        cy, ct = _reports_current_year_term_ids(cursor)
        cursor.execute(
            """
            SELECT student_id, full_name, student_category
            FROM students
            WHERE current_grade = %s AND status = 'in session'
            ORDER BY full_name ASC
            """,
            (level_name,),
        )
        students = cursor.fetchall() or []
        sids = []
        for r in students:
            sid = r.get('student_id') if isinstance(r, dict) else r[0]
            if sid:
                sids.append(sid)

        payment_counts = {}
        latest_payment = {}
        if sids:
            ph = ','.join(['%s'] * len(sids))
            try:
                cursor.execute(
                    f"""
                    SELECT student_id, COUNT(*) AS c
                    FROM student_payments
                    WHERE student_id IN ({ph})
                    GROUP BY student_id
                    """,
                    sids,
                )
                for row in cursor.fetchall() or []:
                    payment_counts[row.get('student_id') if isinstance(row, dict) else row[0]] = int(
                        (row.get('c') if isinstance(row, dict) else row[1]) or 0
                    )
            except Exception as e:
                print(f"_class_fees_accounts_bundle counts: {e}")

            try:
                cursor.execute(
                    f"""
                    SELECT id, student_id, payment_date
                    FROM student_payments
                    WHERE student_id IN ({ph})
                    ORDER BY payment_date DESC, id DESC
                    """,
                    sids,
                )
                for row in cursor.fetchall() or []:
                    sid = row.get('student_id') if isinstance(row, dict) else row[1]
                    pid = row.get('id') if isinstance(row, dict) else row[0]
                    if sid not in latest_payment:
                        latest_payment[sid] = pid
            except Exception as e:
                print(f"_class_fees_accounts_bundle latest payment: {e}")

        for row in students:
            student_id = row.get('student_id') if isinstance(row, dict) else row[0]
            full_name = row.get('full_name') if isinstance(row, dict) else row[1]
            student_category = row.get('student_category') if isinstance(row, dict) else (row[2] if len(row) > 2 else '')
            fs = _reports_select_fee_structure_for_student(cursor, level_id, student_category, cy, ct)
            amounts = _reports_compute_student_fee_balance(cursor, student_id, student_category, level_id, fs)
            if amounts:
                bal = amounts['balance']
                total_amt = amounts['total_amount']
                paid_amt = amounts['paid_amount']
            else:
                bal = None
                total_amt = None
                paid_amt = None
            if bal is not None and bal > 0:
                total_outstanding += bal
            pc = payment_counts.get(student_id, 0)
            lp = latest_payment.get(student_id)
            student_rows.append(
                {
                    'student_id': student_id,
                    'full_name': full_name or '—',
                    'total_amount': total_amt,
                    'paid_amount': paid_amt,
                    'balance': bal,
                    'payment_count': pc,
                    'latest_payment_id': lp,
                }
            )
    except Exception as e:
        print(f"_class_fees_accounts_bundle: {e}")
        import traceback

        traceback.print_exc()

    return {'student_rows': student_rows, 'total_outstanding': total_outstanding}


