def _fetch_academic_reports_shell_context():
    """Shared filter data for academic report hub pages."""
    academic_levels = []
    terms = []
    academic_years = []
    teachers = []
    exam_names = []
    registered_current_exam = None
    level_combinations = []

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_academic_level_combination_tables(cursor)
                cursor.execute("""
                    SELECT id, level_name, level_category, level_code FROM academic_levels
                    WHERE level_status = 'active' ORDER BY level_name
                """)
                for row in cursor.fetchall() or []:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
                        'level_category': row.get('level_category') if isinstance(row, dict) else row[2],
                        'level_code': row.get('level_code') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                    })
                level_by_id = {int(l['id']): l for l in academic_levels if l.get('id') is not None}
                for combo in fetch_academic_level_combinations(cursor):
                    level_combinations.append(_level_combo_display_row(combo, level_by_id))
                cursor.execute("""
                    SELECT t.id, t.term_name, t.academic_year_id, ay.year_name, t.is_current
                    FROM terms t
                    LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                    ORDER BY t.academic_year_id DESC, t.id DESC
                """)
                for row in cursor.fetchall() or []:
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name') if isinstance(row, dict) else row[1],
                        'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else row[2],
                        'year_name': row.get('year_name') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                        'is_current': bool(row.get('is_current')) if isinstance(row, dict) else (bool(row[4]) if len(row) > 4 else False),
                    })
                cursor.execute("""
                    SELECT id, year_name, is_current FROM academic_years ORDER BY id DESC
                """)
                for row in cursor.fetchall() or []:
                    academic_years.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'year_name': row.get('year_name') if isinstance(row, dict) else row[1],
                        'is_current': row.get('is_current') if isinstance(row, dict) else (row[2] if len(row) > 2 else False),
                    })
                cursor.execute("""
                    SELECT id, full_name FROM employees
                    WHERE status = 'active' AND (role = 'teachers' OR role = 'teacher')
                    ORDER BY full_name
                """)
                for row in cursor.fetchall() or []:
                    teachers.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                    })
                registered_current_exam = load_registered_current_exam_dict(cursor)
                cursor.execute("""
                    SELECT DISTINCT TRIM(e.exam_name) AS exam_name,
                           TRIM(COALESCE(e.exam_type, '')) AS exam_type,
                           e.academic_year_id, e.term_id, e.academic_level_id
                    FROM exams e
                    WHERE TRIM(COALESCE(e.exam_name, '')) <> ''
                    ORDER BY exam_name ASC, exam_type ASC
                """)
                for row in cursor.fetchall() or []:
                    exam_names.append({
                        'exam_name': row.get('exam_name') if isinstance(row, dict) else row[0],
                        'exam_type': row.get('exam_type') if isinstance(row, dict) else (row[1] if len(row) > 1 else ''),
                        'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else (row[2] if len(row) > 2 else None),
                        'term_id': row.get('term_id') if isinstance(row, dict) else (row[3] if len(row) > 3 else None),
                        'academic_level_id': row.get('academic_level_id') if isinstance(row, dict) else (row[4] if len(row) > 4 else None),
                    })
        except Exception as e:
            print(f"Error loading academic_reports shell: {e}")
            flash('Error loading report options.', 'error')
        finally:
            connection.close()

    ar_user_role = session.get('role', '').lower()
    ar_viewing_as = session.get('viewing_as_employee_role', '').lower()
    ar_is_curriculum_coordinator = (
        ar_user_role == 'curriculum coordinator' or ar_viewing_as == 'curriculum coordinator'
    )
    can_manage_level_combinations = (
        ar_is_curriculum_coordinator
        or ar_user_role == 'technician'
        or ar_user_role == 'head of institution'
        or ar_viewing_as == 'head of institution'
    )
    parent_login_url = public_portal_url('login', role='parent')

    return {
        'academic_levels': academic_levels,
        'terms': terms,
        'academic_years': academic_years,
        'teachers': teachers,
        'exam_names': exam_names,
        'registered_current_exam': registered_current_exam,
        'level_combinations': level_combinations,
        'can_manage_level_combinations': can_manage_level_combinations,
        'sidebar_hide_accounts_fees': ar_is_curriculum_coordinator,
        'parent_login_url': parent_login_url,
        'parent_login_qr_data_url': _portal_qr_data_url(parent_login_url),
    }


def _render_academic_reports_hub(hub_slug):
    if not _reports_access_roles_ok():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    hub = ACADEMIC_REPORT_HUBS.get(hub_slug)
    if not hub:
        flash('Report page not found.', 'error')
        return redirect(employee_dashboard_path('academic-reports/class-list'))
    ctx = _fetch_academic_reports_shell_context()
    ctx.update({
        'ar_hub_slug': hub_slug,
        'ar_hub_section': hub['section'],
        'ar_page_title': hub['title'],
        'ar_page_subtitle': hub.get('subtitle', ''),
        'ar_hero_icon': hub.get('hero_icon', 'fa-chalkboard'),
    })
    return render_template(
        'dashboards/academic_reports.html',
        role=session.get('role', '').lower(),
        **ctx,
    )


