@app.route('/dashboard/employee/academic-reports/calendar')
@login_required
def academic_calendar_report():
    """Printable academic calendar report for the selected year/term."""
    if not _reports_access_roles_ok():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    requested_year_id = request.args.get('academic_year_id', type=int)
    if 'term_id' in request.args:
        raw_term_id = request.args.get('term_id', type=int)
        requested_term_id = 0 if raw_term_id in (None, 0) else raw_term_id
    else:
        requested_term_id = None

    academic_years = []
    calendar_terms = []
    selected_year_id = None
    selected_year = None
    selected_term_id = None
    selected_term = None
    calendar_activities = []
    calendar_year_label = ''
    report_terms = []
    fee_payment_methods = []
    fee_payment_method_groups = []
    fee_deadlines = []
    year_start_display = ''
    year_end_display = ''
    generated_at = datetime.now().strftime('%d %b %Y, %H:%M')

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_academic_calendar_activities_table(cursor)
                ensure_academic_calendar_activity_levels_table(cursor)
                connection.commit()
                selected_year_id, academic_years = _resolve_calendar_year_id(cursor, requested_year_id)
                if selected_year_id:
                    for y in academic_years:
                        if int(y.get('id')) == int(selected_year_id):
                            selected_year = y
                            break
                    selected_term_id, calendar_terms, selected_term = _resolve_calendar_term_id(
                        cursor, selected_year_id, requested_term_id, default_to_current=True,
                    )
                    report_terms = _enrich_calendar_report_term_rows(calendar_terms)
                    if selected_year:
                        year_start_display = _format_date_short(selected_year.get('start_date')) or '—'
                        year_end_display = _format_date_short(selected_year.get('end_date')) or '—'
                    fee_sections = _fetch_academic_calendar_report_fee_sections(
                        cursor, selected_year_id, selected_term_id,
                    )
                    fee_payment_methods = fee_sections.get('payment_methods') or []
                    fee_payment_method_groups = fee_sections.get('payment_method_groups') or []
                    fee_deadlines = fee_sections.get('fee_deadlines') or []
                    activities = _fetch_academic_calendar_activities(
                        cursor, selected_year_id, selected_term_id,
                    )
                    activities = _attach_calendar_activity_levels(cursor, activities)
                    calendar_view = _prepare_academic_calendar_view(
                        activities, selected_year, selected_term,
                    )
                    calendar_activities = calendar_view['activities']
                    calendar_year_label = calendar_view.get('year_label') or ''
        except Exception as e:
            print(f"academic_calendar_report: {e}")
            flash('Could not load academic calendar report.', 'error')
        finally:
            connection.close()

    term_label = 'All terms'
    if selected_term and selected_term.get('term_name'):
        term_label = selected_term['term_name']
    elif selected_term_id:
        term_label = 'Selected term'

    parent_login_url = public_portal_url('login', role='parent')
    parent_login_qr_data_url = _portal_qr_data_url(parent_login_url)

    return render_template(
        'dashboards/academic_calendar_report.html',
        role=session.get('role', '').lower(),
        academic_years=academic_years,
        calendar_terms=calendar_terms,
        selected_year_id=selected_year_id,
        selected_year=selected_year,
        selected_term_id=selected_term_id,
        selected_term=selected_term,
        calendar_activities=calendar_activities,
        calendar_year_label=calendar_year_label,
        report_terms=report_terms,
        year_start_display=year_start_display,
        year_end_display=year_end_display,
        fee_payment_methods=fee_payment_methods,
        fee_payment_method_groups=fee_payment_method_groups,
        fee_deadlines=fee_deadlines,
        term_label=term_label,
        generated_at=generated_at,
        parent_login_url=parent_login_url,
        parent_login_qr_data_url=parent_login_qr_data_url,
        category_labels=ACADEMIC_CALENDAR_CATEGORY_LABELS,
        category_colors=ACADEMIC_CALENDAR_CATEGORY_COLORS,
    )


@app.route('/dashboard/employee/academic-reports/preview')
@login_required
def academic_report_preview():
    """Full-page report preview (GET); add format=csv to download."""
    from urllib.parse import urlencode

    if not _reports_access_roles_ok():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    report_type = (request.args.get('report_type') or '').strip()
    if not report_type:
        flash('Missing report type.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))

    fmt = (request.args.get('format') or '').strip().lower()
    arg_dict = {k: v for k, v in request.args.items() if k not in ('format', 'report_type')}
    filters = _coerce_academic_report_filters(arg_dict)

    connection = get_db_connection()
    if not connection:
        flash('Database unavailable.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))

    bundle = None
    try:
        with connection.cursor() as cursor:
            bundle = _build_academic_report_payload(cursor, report_type, filters)
    except Exception as e:
        print(f"academic_report_preview: {e}")
        import traceback
        traceback.print_exc()
        flash('Could not load this report.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))
    finally:
        connection.close()

    if not bundle or bundle.get('error'):
        flash((bundle or {}).get('error') or 'Could not build this report.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))

    bundle = _expand_exam_student_card_rows(bundle, report_type)

    if fmt == 'csv':
        return _make_academic_report_csv_response(bundle, report_type)
    if fmt in ('excel', 'xls', 'xlsx'):
        return _make_academic_report_excel_response(bundle, report_type)

    args_flat = request.args.to_dict(flat=True)
    args_flat['format'] = 'excel'
    download_url = employee_dashboard_path('academic-reports/preview') + '?' + urlencode(args_flat)

    display = _preview_display_context(report_type, bundle)
    simple_view = (request.args.get('simple') or '').strip().lower() in ('1', 'true', 'yes')
    pv_user_role = session.get('role', '').lower()
    pv_viewing_as = session.get('viewing_as_employee_role', '').lower()
    pv_hide_fees = pv_user_role == 'curriculum coordinator' or pv_viewing_as == 'curriculum coordinator'
    return render_template(
        'dashboards/academic_report_preview.html',
        role=session.get('role', '').lower(),
        report_type=report_type,
        title=bundle.get('title', 'Report'),
        columns=bundle.get('columns') or [],
        rows=bundle.get('rows') or [],
        meta=bundle.get('meta') or {},
        download_url=download_url,
        layout=display['layout'],
        timetable=display.get('timetable'),
        timetable_sections=display.get('timetable_sections'),
        exam_schedule=display.get('exam_schedule'),
        exam_timetable_grid=display.get('exam_timetable_grid'),
        exam_timetable_sections=display.get('exam_timetable_sections'),
        attendance_register=display.get('attendance_register'),
        exam_by_student=display.get('exam_by_student'),
        class_sections=display.get('class_sections'),
        simple_view=simple_view,
        sidebar_hide_accounts_fees=pv_hide_fees,
    )


@app.route('/api/employee/academic-reports/generate', methods=['POST'])
@login_required
def api_academic_reports_generate():
    """Generate or export academic report data (no auto-run on page load)."""
    if not _reports_access_roles_ok():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403

    payload = request.get_json(silent=True) or {}
    report_type = (payload.get('report_type') or '').strip()
    fmt = (payload.get('format') or 'json').strip().lower()
    filters = payload.get('filters') or {}
    export_cache_key = (
        (payload.get('export_cache_key') or payload.get('cache_key') or '').strip()
    )
    if not report_type:
        return jsonify({'success': False, 'message': 'report_type is required'}), 400

    owner_key = str(session.get('user_id') or session.get('employee_id') or '')

    # Heavy Excel builds run in a background thread so other users keep browsing.
    if fmt in ('excel', 'xls', 'xlsx'):
        job_id = secrets.token_hex(8)
        _set_export_job(job_id, status='queued', message='Export queued…', progress=5)
        thread = threading.Thread(
            target=_run_academic_excel_export_job,
            args=(
                current_app._get_current_object(),
                job_id,
                report_type,
                filters,
                export_cache_key,
                owner_key,
            ),
            daemon=True,
            name=f'academic-excel-{job_id}',
        )
        thread.start()
        return jsonify({
            'success': True,
            'async': True,
            'job_id': job_id,
            'status_url': url_for('api_academic_reports_export_status', job_id=job_id),
            'message': 'Excel export started in the background.',
        })

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500

    try:
        with connection.cursor() as cursor:
            filters = _coerce_academic_report_filters(filters)

            bundle = _build_academic_report_payload(cursor, report_type, filters)
            if bundle.get('error'):
                return jsonify({'success': False, 'message': bundle['error']}), 400

            # Cache full payload so Spreadsheet reuse skips a second DB rebuild.
            cache_key = _store_academic_report_payload_cache(
                owner_key, report_type, filters, bundle,
            )

            title = bundle.get('title', 'Report')
            columns = bundle.get('columns') or []
            rows = bundle.get('rows') or []
            meta = bundle.get('meta') or {}

            if fmt == 'csv':
                return _make_academic_report_csv_response(bundle, report_type)

            bundle = _trim_academic_report_json_bundle(bundle, report_type)
            title = bundle.get('title', 'Report')
            columns = bundle.get('columns') or []
            rows = bundle.get('rows') or []
            meta = bundle.get('meta') or {}

            return jsonify({
                'success': True,
                'title': title,
                'columns': columns,
                'rows': rows,
                'meta': meta,
                'export_cache_key': cache_key,
            })
    except Exception as e:
        print(f"api_academic_reports_generate: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500
    finally:
        connection.close()


# Academic report Excel export jobs (background)
_EXPORT_JOBS = {}
_EXPORT_JOBS_LOCK = threading.Lock()

# Short-lived report payloads so Excel export reuses the last Generate result.
_ACADEMIC_REPORT_PAYLOAD_CACHE = {}
_ACADEMIC_REPORT_PAYLOAD_CACHE_LOCK = threading.Lock()
_ACADEMIC_REPORT_PAYLOAD_CACHE_TTL = 600  # seconds
_ACADEMIC_REPORT_PAYLOAD_CACHE_MAX = 32


def _academic_report_payload_cache_fingerprint(owner_key, report_type, filters):
    import hashlib
    import json as _json
    raw = _json.dumps(
        {'o': str(owner_key or ''), 't': str(report_type or ''), 'f': filters or {}},
        sort_keys=True,
        default=str,
        separators=(',', ':'),
    )
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()[:40]


def _prune_academic_report_payload_cache(now=None):
    now = time.time() if now is None else now
    stale = [
        k for k, v in _ACADEMIC_REPORT_PAYLOAD_CACHE.items()
        if (v.get('expires_at') or 0) < now
    ]
    for k in stale:
        _ACADEMIC_REPORT_PAYLOAD_CACHE.pop(k, None)
    while len(_ACADEMIC_REPORT_PAYLOAD_CACHE) > _ACADEMIC_REPORT_PAYLOAD_CACHE_MAX:
        oldest = min(
            _ACADEMIC_REPORT_PAYLOAD_CACHE.items(),
            key=lambda kv: kv[1].get('expires_at') or 0,
        )[0]
        _ACADEMIC_REPORT_PAYLOAD_CACHE.pop(oldest, None)


def _store_academic_report_payload_cache(owner_key, report_type, filters, bundle):
    """Store full (untrimmed) report bundle for fast Excel reuse. Returns cache key."""
    if not isinstance(bundle, dict) or bundle.get('error'):
        return ''
    key = secrets.token_hex(12)
    fp = _academic_report_payload_cache_fingerprint(owner_key, report_type, filters)
    now = time.time()
    with _ACADEMIC_REPORT_PAYLOAD_CACHE_LOCK:
        _prune_academic_report_payload_cache(now)
        _ACADEMIC_REPORT_PAYLOAD_CACHE[key] = {
            'owner': str(owner_key or ''),
            'report_type': str(report_type or ''),
            'fingerprint': fp,
            'bundle': bundle,
            'expires_at': now + _ACADEMIC_REPORT_PAYLOAD_CACHE_TTL,
        }
    return key


def _get_academic_report_payload_cache(cache_key, owner_key, report_type, filters):
    """Return cached bundle when key + owner + filters match; else None."""
    key = (cache_key or '').strip()
    if not key:
        return None
    now = time.time()
    with _ACADEMIC_REPORT_PAYLOAD_CACHE_LOCK:
        entry = _ACADEMIC_REPORT_PAYLOAD_CACHE.get(key)
        if not entry:
            return None
        if (entry.get('expires_at') or 0) < now:
            _ACADEMIC_REPORT_PAYLOAD_CACHE.pop(key, None)
            return None
        if str(entry.get('owner') or '') != str(owner_key or ''):
            return None
        if str(entry.get('report_type') or '') != str(report_type or ''):
            return None
        fp = _academic_report_payload_cache_fingerprint(owner_key, report_type, filters)
        if entry.get('fingerprint') != fp:
            return None
        return entry.get('bundle')


def _export_job_snapshot(job_id):
    with _EXPORT_JOBS_LOCK:
        job = _EXPORT_JOBS.get(job_id)
        return dict(job) if job else None


def _set_export_job(job_id, **fields):
    with _EXPORT_JOBS_LOCK:
        job = _EXPORT_JOBS.setdefault(job_id, {'id': job_id})
        job.update(fields)
        job['updated_at'] = time.time()


def _run_academic_excel_export_job(
    flask_app, job_id, report_type, filters, export_cache_key='', owner_key='',
):
    with flask_app.app_context():
        _set_export_job(job_id, status='running', message='Preparing Excel…', progress=15)
        connection = None
        try:
            filters = _coerce_academic_report_filters(filters or {})
            bundle = _get_academic_report_payload_cache(
                export_cache_key, owner_key, report_type, filters,
            )
            if bundle:
                _set_export_job(
                    job_id, status='running', message='Writing Excel (cached report)…', progress=55,
                )
            else:
                _set_export_job(job_id, status='running', message='Building report…', progress=25)
                connection = get_db_connection()
                if not connection:
                    _set_export_job(job_id, status='error', message='Database unavailable', progress=100)
                    return
                with connection.cursor() as cursor:
                    bundle = _build_academic_report_payload(cursor, report_type, filters)
                if not bundle or bundle.get('error'):
                    _set_export_job(
                        job_id,
                        status='error',
                        message=(bundle or {}).get('error') or 'Could not build report',
                        progress=100,
                    )
                    return
                # Refresh cache for subsequent exports of the same report.
                _store_academic_report_payload_cache(owner_key, report_type, filters, bundle)
                _set_export_job(job_id, status='running', message='Writing Excel file…', progress=70)

            safe_job = re.sub(r'[^a-zA-Z0-9_-]+', '', job_id)[:32]
            out_name = f'{safe_job}_{re.sub(r"[^a-zA-Z0-9_-]+", "_", report_type)[:60]}.xlsx'
            filepath = os.path.join(EXPORT_FOLDER, out_name)
            built = _build_academic_report_excel_bytes(bundle, report_type, filepath=filepath)
            if not (
                isinstance(built, tuple)
                and len(built) == 2
                and isinstance(built[0], str)
                and os.path.isfile(built[0])
            ):
                _set_export_job(job_id, status='error', message='Excel export failed', progress=100)
                return
            filepath, filename = built
            # Background thread has app_context but no HTTP request; url_for needs a
            # request context (or SERVER_NAME). Use a test request for a relative path.
            with flask_app.test_request_context('/'):
                download_url = url_for(
                    'api_academic_reports_export_download',
                    job_id=job_id,
                )
            _set_export_job(
                job_id,
                status='success',
                message='Excel ready',
                progress=100,
                filepath=filepath,
                filename=filename,
                download_url=download_url,
            )
        except Exception as e:
            print(f'_run_academic_excel_export_job: {e}')
            import traceback
            traceback.print_exc()
            _set_export_job(job_id, status='error', message=str(e), progress=100)
        finally:
            if connection is not None:
                try:
                    connection.close()
                except Exception:
                    pass


@app.route('/api/employee/academic-reports/export-status/<job_id>', methods=['GET'])
@login_required
def api_academic_reports_export_status(job_id):
    if not _reports_access_roles_ok():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403
    job = _export_job_snapshot((job_id or '').strip())
    if not job:
        return jsonify({'success': False, 'message': 'Unknown export job.', 'status': 'unknown'}), 404
    return jsonify({
        'success': True,
        'id': job.get('id'),
        'status': job.get('status'),
        'message': job.get('message') or '',
        'progress': job.get('progress') or 0,
        'download_url': job.get('download_url') or '',
        'filename': job.get('filename') or '',
    })


@app.route('/api/employee/academic-reports/export-download/<job_id>', methods=['GET'])
@login_required
def api_academic_reports_export_download(job_id):
    if not _reports_access_roles_ok():
        flash('You do not have permission to download this file.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))
    job = _export_job_snapshot((job_id or '').strip())
    if not job or job.get('status') != 'success':
        flash('Export is not ready yet.', 'warning')
        return redirect(employee_dashboard_path('academic-reports'))
    filepath = job.get('filepath') or ''
    filename = job.get('filename') or 'report.xlsx'
    if not filepath or not os.path.isfile(filepath):
        flash('Export file missing.', 'error')
        return redirect(employee_dashboard_path('academic-reports'))
    return send_from_directory(
        os.path.dirname(os.path.abspath(filepath)),
        os.path.basename(filepath),
        as_attachment=True,
        download_name=filename,
    )


@app.route('/api/employee/academic-reports/search-students', methods=['POST'])
@login_required
def api_academic_reports_search_students():
    """Typeahead for academic reports: search learners by name or admission/student id."""
    if not _reports_access_roles_ok():
        return jsonify({'success': False, 'message': 'Forbidden'}), 403

    data = request.get_json(silent=True) or {}
    q = (data.get('q') or '').strip()
    list_all = data.get('list_all') in (True, 'true', '1', 1, 'yes')

    def _int_or_none(v):
        if v is None or v == '' or v == 'null':
            return None
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    lid = _int_or_none(data.get('level_id'))
    level_view = (data.get('level_view') or 'individual').strip().lower()
    if level_view not in ('individual', 'combined'):
        level_view = 'individual'

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database unavailable'}), 500

    level_ids = []
    try:
        with connection.cursor() as cursor:
            scope = _resolve_academic_report_level_scope(cursor, level_view, lid)
            if level_view == 'combined' and lid and not scope.get('is_combined_view'):
                return jsonify({
                    'success': False,
                    'message': 'Selected class is not in a combined level group.',
                }), 400
            level_ids = list(scope.get('level_ids') or [])
    except Exception as e:
        print(f"api_academic_reports_search_students scope: {e}")
        level_ids = [lid] if lid else []

    if list_all and level_ids:
        sql = """
            SELECT s.student_id, s.full_name, COALESCE(s.current_grade, '') AS level_name,
                   (
                       SELECT al.id FROM academic_levels al
                       WHERE al.level_status = 'active'
                         AND TRIM(COALESCE(al.level_name, '')) = TRIM(COALESCE(s.current_grade, ''))
                       ORDER BY al.id ASC
                       LIMIT 1
                   ) AS academic_level_id
            FROM students s
            WHERE 1=1
        """
        params = []
        sql, params = _sql_filter_student_current_grade(sql, params, level_ids, table_alias='s')
        sql += " ORDER BY s.full_name ASC LIMIT 500"
    else:
        if len(q) < 1:
            connection.close()
            return jsonify({'success': True, 'students': []})

        like_pat = '%' + q + '%'

        sql = """
            SELECT s.student_id, s.full_name, COALESCE(s.current_grade, '') AS level_name,
                   (
                       SELECT al.id FROM academic_levels al
                       WHERE al.level_status = 'active'
                         AND TRIM(COALESCE(al.level_name, '')) = TRIM(COALESCE(s.current_grade, ''))
                       ORDER BY al.id ASC
                       LIMIT 1
                   ) AS academic_level_id
            FROM students s
            WHERE (s.full_name LIKE %s OR s.student_id LIKE %s)
        """
        params = [like_pat, like_pat]
        sql, params = _sql_filter_student_current_grade(sql, params, level_ids, table_alias='s')
        sql += " ORDER BY s.full_name ASC LIMIT 40"

    students = []

    def _lid_as_int(v):
        if v is None:
            return None
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    try:
        with connection.cursor() as cursor:
            cursor.execute(sql, params)
            for r in cursor.fetchall() or []:
                if isinstance(r, dict):
                    sid = r.get('student_id')
                    students.append({
                        'student_id': sid,
                        'admission_number': sid,
                        'full_name': r.get('full_name'),
                        'level_name': r.get('level_name') or '',
                        'academic_level_id': _lid_as_int(r.get('academic_level_id')),
                    })
                else:
                    lid_row = r[3] if len(r) > 3 else None
                    sid = r[0]
                    students.append({
                        'student_id': sid,
                        'admission_number': sid,
                        'full_name': r[1],
                        'level_name': r[2] if len(r) > 2 else '',
                        'academic_level_id': _lid_as_int(lid_row),
                    })
        return jsonify({'success': True, 'students': students})
    except Exception as e:
        print(f"api_academic_reports_search_students: {e}")
        return jsonify({'success': False, 'message': str(e)}), 500
    finally:
        connection.close()


def _user_can_access_communication():
    ur = session.get('role', '').lower()
    vr = session.get('viewing_as_employee_role', '').lower()
    allowed = (
        'curriculum coordinator',
        'technician',
        'head of institution',
        'deputy head of institution',
        'secretary',
        'super admin',
    )
    return ur in allowed or vr in allowed


def _communication_recipient_rows(
    cursor, audience, q=None, role_filter=None, level_filter=None, page=1, per_page=50,
):
    """Load employees, parents, or students for the communication centre (paginated, optional search/filters)."""
    audience = (audience or 'parents').lower().strip()
    if audience not in ('employees', 'parents', 'students'):
        audience = 'parents'
    q_norm = (q or '').strip().lower()
    like = f'%{q_norm}%' if q_norm else None
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    out = []
    total = 0

    if audience == 'employees':
        base = """
            FROM employees
            WHERE status = 'active'
        """
        params = []
        filters = ''
        if role_filter:
            filters += ' AND LOWER(TRIM(role)) = %s'
            params.append(str(role_filter).strip().lower())
        if like:
            filters += (
                " AND (LOWER(full_name) LIKE %s OR LOWER(COALESCE(phone,'')) LIKE %s"
                " OR LOWER(COALESCE(email,'')) LIKE %s OR LOWER(COALESCE(employee_id,'')) LIKE %s)"
            )
            params.extend([like, like, like, like])
        cursor.execute('SELECT COUNT(*) AS c ' + base + filters, tuple(params))
        crow = cursor.fetchone()
        total = int((crow.get('c') if isinstance(crow, dict) else crow[0]) or 0)
        sql = (
            'SELECT id, employee_id, full_name, phone, email, role '
            + base
            + filters
            + ' ORDER BY full_name ASC LIMIT %s OFFSET %s'
        )
        cursor.execute(sql, tuple(params) + (per_page, offset))
        for row in cursor.fetchall() or []:
            rid = row.get('id') if isinstance(row, dict) else row[0]
            eid = row.get('employee_id') if isinstance(row, dict) else row[1]
            fn = row.get('full_name') if isinstance(row, dict) else row[2]
            ph = row.get('phone') if isinstance(row, dict) else row[3]
            em = row.get('email') if isinstance(row, dict) else row[4]
            rl = row.get('role') if isinstance(row, dict) else row[5]
            out.append({
                'id': rid,
                'kind': 'employee',
                'employee_id': eid,
                'name': fn or '',
                'phone': ph or '',
                'email': em or '',
                'role': (rl or '').lower(),
                'search': f"{fn} {ph} {em} {eid} {rl}".lower(),
            })
    elif audience == 'students':
        params = []
        where = ["s.status = 'in session'"]
        if level_filter:
            where.append('TRIM(s.current_grade) = %s')
            params.append(str(level_filter).strip())
        if like:
            where.append(
                "(LOWER(s.full_name) LIKE %s OR LOWER(COALESCE(s.student_id,'')) LIKE %s"
                " OR LOWER(COALESCE(u.email,'')) LIKE %s OR LOWER(COALESCE(s.sponsor_email,'')) LIKE %s"
                " OR LOWER(COALESCE(s.sponsor_phone,'')) LIKE %s OR LOWER(COALESCE(p.phone,'')) LIKE %s)"
            )
            params.extend([like, like, like, like, like, like])
        base_from = """
            FROM students s
            LEFT JOIN users u ON u.role = 'student'
                AND UPPER(TRIM(CAST(u.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))
            LEFT JOIN parents p ON UPPER(TRIM(CAST(p.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))
        """
        where_sql = ' WHERE ' + ' AND '.join(where)
        count_sql = 'SELECT COUNT(DISTINCT s.id) AS c ' + base_from + where_sql
        list_sql = (
            """
            SELECT s.id, s.student_id, s.full_name, s.current_grade,
                   MAX(COALESCE(NULLIF(TRIM(u.email), ''), NULLIF(TRIM(s.sponsor_email), ''))) AS email,
                   MAX(COALESCE(NULLIF(TRIM(s.sponsor_phone), ''), NULLIF(TRIM(p.phone), ''))) AS phone
            """
            + base_from
            + where_sql
            + ' GROUP BY s.id, s.student_id, s.full_name, s.current_grade'
            + ' ORDER BY s.full_name ASC LIMIT %s OFFSET %s'
        )
        cursor.execute(count_sql, tuple(params))
        crow = cursor.fetchone()
        total = int((crow.get('c') if isinstance(crow, dict) else crow[0]) or 0)
        cursor.execute(list_sql, tuple(params) + (per_page, offset))
        for row in cursor.fetchall() or []:
            rid = row.get('id') if isinstance(row, dict) else row[0]
            sid = row.get('student_id') if isinstance(row, dict) else row[1]
            fn = row.get('full_name') if isinstance(row, dict) else row[2]
            grade = row.get('current_grade') if isinstance(row, dict) else row[3]
            em = row.get('email') if isinstance(row, dict) else row[4]
            ph = row.get('phone') if isinstance(row, dict) else row[5]
            out.append({
                'id': rid,
                'kind': 'student',
                'student_id': sid or '',
                'name': fn or '',
                'phone': ph or '',
                'email': em or '',
                'grade': grade or '',
                'search': f"{fn} {sid} {ph} {em} {grade}".lower(),
            })
    else:
        params = []
        where = []
        if level_filter:
            where.append("TRIM(s.current_grade) = %s")
            params.append(str(level_filter).strip())
        if like:
            where.append(
                "(LOWER(p.full_name) LIKE %s OR LOWER(COALESCE(p.phone,'')) LIKE %s"
                " OR LOWER(COALESCE(p.email,'')) LIKE %s)"
            )
            params.extend([like, like, like])
        base_from = """
            FROM parents p
            INNER JOIN students s ON s.student_id = p.student_id AND s.status = 'in session'
        """
        if where:
            count_sql = (
                'SELECT COUNT(DISTINCT p.id) AS c ' + base_from + ' WHERE ' + ' AND '.join(where)
            )
            list_sql = (
                """
            SELECT p.id, p.full_name, p.phone, p.email,
                   GROUP_CONCAT(DISTINCT s.current_grade ORDER BY s.current_grade SEPARATOR ', ') AS grades,
                   GROUP_CONCAT(DISTINCT s.full_name ORDER BY s.full_name SEPARATOR ' | ') AS children
            """
                + base_from
                + ' WHERE '
                + ' AND '.join(where)
                + ' GROUP BY p.id, p.full_name, p.phone, p.email ORDER BY p.full_name ASC LIMIT %s OFFSET %s'
            )
        else:
            count_sql = 'SELECT COUNT(DISTINCT p.id) AS c ' + base_from
            list_sql = (
                """
            SELECT p.id, p.full_name, p.phone, p.email,
                   GROUP_CONCAT(DISTINCT s.current_grade ORDER BY s.current_grade SEPARATOR ', ') AS grades,
                   GROUP_CONCAT(DISTINCT s.full_name ORDER BY s.full_name SEPARATOR ' | ') AS children
            """
                + base_from
                + ' GROUP BY p.id, p.full_name, p.phone, p.email ORDER BY p.full_name ASC LIMIT %s OFFSET %s'
            )
        cursor.execute(count_sql, tuple(params))
        crow = cursor.fetchone()
        total = int((crow.get('c') if isinstance(crow, dict) else crow[0]) or 0)
        cursor.execute(list_sql, tuple(params) + (per_page, offset))
        for row in cursor.fetchall() or []:
            rid = row.get('id') if isinstance(row, dict) else row[0]
            fn = row.get('full_name') if isinstance(row, dict) else row[1]
            ph = row.get('phone') if isinstance(row, dict) else row[2]
            em = row.get('email') if isinstance(row, dict) else row[3]
            grades = row.get('grades') if isinstance(row, dict) else row[4]
            children = row.get('children') if isinstance(row, dict) else row[5]
            out.append({
                'id': rid,
                'kind': 'parent',
                'name': fn or '',
                'phone': ph or '',
                'email': em or '',
                'grades': grades or '',
                'children': children or '',
                'search': f"{fn} {ph} {em} {grades} {children}".lower(),
            })
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    return {
        'recipients': out,
        'meta': {'page': page, 'per_page': per_page, 'total': total, 'pages': pages},
    }


def _communication_resolve_targets(cursor, audience, recipient_ids, send_to_all, role_filter=None, level_filter=None):
    """Resolve recipient rows for sending (by ids or entire filtered audience)."""
    audience = (audience or 'parents').lower().strip()
    if audience not in ('employees', 'parents', 'students'):
        audience = 'parents'
    kind_map = {'employees': 'employee', 'parents': 'parent', 'students': 'student'}
    kind = kind_map.get(audience, 'parent')

    def _row_to_target(r):
        target = {
            'id': r.get('id'),
            'kind': r.get('kind') or kind,
            'name': r.get('name') or '',
            'phone': r.get('phone') or '',
            'email': r.get('email') or '',
        }
        if r.get('student_id'):
            target['student_id'] = r.get('student_id')
        return target

    if send_to_all:
        all_rows = []
        page = 1
        while True:
            batch = _communication_recipient_rows(
                cursor, audience, role_filter=role_filter, level_filter=level_filter,
                page=page, per_page=100,
            )
            all_rows.extend(batch.get('recipients') or [])
            meta = batch.get('meta') or {}
            if page >= int(meta.get('pages') or 1):
                break
            page += 1
        return [_row_to_target(r) for r in all_rows]
    ids = []
    for x in recipient_ids or []:
        try:
            ids.append(int(x))
        except (TypeError, ValueError):
            pass
    if not ids:
        return None
    targets = []
    ph = ','.join(['%s'] * len(ids))
    if audience == 'employees':
        cursor.execute(
            f"SELECT id, full_name, phone, email FROM employees WHERE id IN ({ph}) AND status = 'active'",
            ids,
        )
    elif audience == 'students':
        cursor.execute(
            f"""
            SELECT s.id, s.student_id, s.full_name,
                   MAX(COALESCE(NULLIF(TRIM(u.email), ''), NULLIF(TRIM(s.sponsor_email), ''))) AS email,
                   MAX(COALESCE(NULLIF(TRIM(s.sponsor_phone), ''), NULLIF(TRIM(p.phone), ''))) AS phone
            FROM students s
            LEFT JOIN users u ON u.role = 'student'
                AND UPPER(TRIM(CAST(u.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))
            LEFT JOIN parents p ON UPPER(TRIM(CAST(p.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))
            WHERE s.id IN ({ph}) AND s.status = 'in session'
            GROUP BY s.id, s.student_id, s.full_name
            """,
            ids,
        )
    else:
        cursor.execute(
            f"SELECT id, full_name, phone, email FROM parents WHERE id IN ({ph})",
            ids,
        )
    for row in cursor.fetchall() or []:
        if audience == 'students':
            targets.append({
                'id': row.get('id') if isinstance(row, dict) else row[0],
                'kind': kind,
                'student_id': row.get('student_id') if isinstance(row, dict) else row[1],
                'name': row.get('full_name') if isinstance(row, dict) else row[2],
                'email': row.get('email') if isinstance(row, dict) else row[3],
                'phone': row.get('phone') if isinstance(row, dict) else row[4],
            })
        else:
            targets.append({
                'id': row.get('id') if isinstance(row, dict) else row[0],
                'kind': kind,
                'name': row.get('full_name') if isinstance(row, dict) else row[1],
                'phone': row.get('phone') if isinstance(row, dict) else row[2],
                'email': row.get('email') if isinstance(row, dict) else row[3],
            })
    return targets


def _communication_build_audiences_config(payload):
    """Normalize send payload into per-audience config rows."""
    send_to_all = bool(payload.get('send_to_all'))
    raw_list = payload.get('audiences')
    if isinstance(raw_list, list) and raw_list:
        configs = []
        for item in raw_list:
            if not isinstance(item, dict):
                continue
            aud = (item.get('audience') or '').lower().strip()
            if aud not in ('employees', 'parents', 'students'):
                continue
            cfg = {
                'audience': aud,
                'role_filter': (item.get('role_filter') or '').strip().lower() or None,
                'level_filter': (item.get('level_filter') or '').strip() or None,
                'recipient_ids': item.get('recipient_ids') or [],
            }
            if aud != 'employees':
                cfg['role_filter'] = None
            if aud not in ('parents', 'students'):
                cfg['level_filter'] = None
            configs.append(cfg)
        if configs:
            return send_to_all, configs

    aud = (payload.get('audience') or 'parents').lower().strip()
    if aud not in ('employees', 'parents', 'students', 'multi'):
        aud = 'parents'
    if aud == 'multi':
        aud = 'parents'
    return send_to_all, [{
        'audience': aud,
        'role_filter': (payload.get('role_filter') or '').strip().lower() or None,
        'level_filter': (payload.get('level_filter') or '').strip() or None,
        'recipient_ids': payload.get('recipient_ids') or [],
    }]


def _communication_resolve_multi_targets(cursor, audiences_config, send_to_all):
    """Resolve recipients across one or more audiences."""
    all_targets = []
    for cfg in audiences_config or []:
        aud = cfg.get('audience')
        ids = cfg.get('recipient_ids') or []
        if send_to_all:
            batch = _communication_resolve_targets(
                cursor,
                aud,
                [],
                True,
                role_filter=cfg.get('role_filter'),
                level_filter=cfg.get('level_filter'),
            )
        else:
            if not ids:
                continue
            batch = _communication_resolve_targets(
                cursor,
                aud,
                ids,
                False,
                role_filter=cfg.get('role_filter'),
                level_filter=cfg.get('level_filter'),
            )
        if batch is None:
            return None
        for t in batch or []:
            tagged = dict(t)
            tagged['audience'] = aud
            all_targets.append(tagged)
    return all_targets


def ensure_communication_broadcast_tables(cursor):
    """Log communication centre broadcasts and per-recipient delivery/read state."""
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS communication_broadcasts (
            id INT AUTO_INCREMENT PRIMARY KEY,
            sender_user_id INT NULL,
            sender_name VARCHAR(255) NULL,
            audience VARCHAR(20) NOT NULL DEFAULT 'employees',
            department VARCHAR(120) NULL,
            subject VARCHAR(255) NOT NULL,
            message TEXT NULL,
            attachment_name VARCHAR(255) NULL,
            channels_json TEXT NULL,
            send_to_all TINYINT(1) NOT NULL DEFAULT 0,
            role_filter VARCHAR(80) NULL,
            level_filter VARCHAR(120) NULL,
            recipient_count INT NOT NULL DEFAULT 0,
            delivered_count INT NOT NULL DEFAULT 0,
            read_count INT NOT NULL DEFAULT 0,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_comm_broadcast_created (created_at),
            INDEX idx_comm_broadcast_sender (sender_user_id)
        )
        """
    )
    cursor.execute(
        """
        CREATE TABLE IF NOT EXISTS communication_broadcast_recipients (
            id INT AUTO_INCREMENT PRIMARY KEY,
            broadcast_id INT NOT NULL,
            recipient_kind VARCHAR(20) NOT NULL DEFAULT 'employee',
            recipient_ref_id INT NULL,
            recipient_name VARCHAR(255) NULL,
            email VARCHAR(255) NULL,
            phone VARCHAR(80) NULL,
            email_status VARCHAR(20) NOT NULL DEFAULT 'none',
            sms_status VARCHAR(20) NOT NULL DEFAULT 'none',
            whatsapp_status VARCHAR(20) NOT NULL DEFAULT 'none',
            app_status VARCHAR(20) NOT NULL DEFAULT 'none',
            portal_notification_id INT NULL,
            delivered_at TIMESTAMP NULL DEFAULT NULL,
            read_at TIMESTAMP NULL DEFAULT NULL,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_comm_recip_broadcast (broadcast_id),
            INDEX idx_comm_recip_portal (portal_notification_id),
            CONSTRAINT fk_comm_recip_broadcast
                FOREIGN KEY (broadcast_id) REFERENCES communication_broadcasts(id) ON DELETE CASCADE
        )
        """
    )
    try:
        cursor.execute(
            """
            ALTER TABLE communication_broadcast_recipients
            ADD COLUMN app_status VARCHAR(20) NOT NULL DEFAULT 'none' AFTER whatsapp_status
            """
        )
    except Exception:
        pass


def _communication_student_portal_user_id(cursor, student_id_str):
    sid = (student_id_str or '').strip()
    if not sid:
        return None
    cursor.execute(
        """
        SELECT id FROM users
        WHERE role = 'student'
          AND UPPER(TRIM(CAST(student_id AS CHAR(64)))) = UPPER(TRIM(CAST(%s AS CHAR(64))))
        LIMIT 1
        """,
        (sid,),
    )
    row = cursor.fetchone()
    if not row:
        return None
    return row.get('id') if isinstance(row, dict) else row[0]


def _communication_portal_user_id(cursor, email):
    em = (email or '').strip().lower()
    if not em:
        return None
    cursor.execute(
        "SELECT id FROM users WHERE LOWER(TRIM(email)) = %s LIMIT 1",
        (em,),
    )
    row = cursor.fetchone()
    if not row:
        return None
    return row.get('id') if isinstance(row, dict) else row[0]


def _communication_create_broadcast_log(
    cursor, *, sender_user_id, sender_name, audience, department, subject, message,
    attachment_name, channels, send_to_all, role_filter, level_filter, targets,
):
    ensure_communication_broadcast_tables(cursor)
    ensure_portal_notifications_table(cursor)
    cursor.execute(
        """
        INSERT INTO communication_broadcasts
            (sender_user_id, sender_name, audience, department, subject, message,
             attachment_name, channels_json, send_to_all, role_filter, level_filter, recipient_count)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            int(sender_user_id) if sender_user_id else None,
            (sender_name or '')[:255] or None,
            (audience or 'employees')[:20],
            (department or '')[:120] or None,
            (subject or '')[:255],
            (message or '').strip() or None,
            (attachment_name or '')[:255] or None,
            json.dumps(channels or {}),
            1 if send_to_all else 0,
            (role_filter or '')[:80] or None,
            (level_filter or '')[:120] or None,
            len(targets or []),
        ),
    )
    broadcast_id = cursor.lastrowid
    recipient_rows = []
    app_enabled = bool((channels or {}).get('app')) and notification_mode_active('app')
    aud = (audience or 'parents').lower().strip()
    if aud == 'employees':
        portal_type = 'employee'
    elif aud == 'students':
        portal_type = 'student'
    else:
        portal_type = 'parent'
    preview_body = (message or '')[:500]

    for t in targets or []:
        em = (t.get('email') or '').strip()
        ph = (t.get('phone') or '').strip()
        app_status = 'none'
        cursor.execute(
            """
            INSERT INTO communication_broadcast_recipients
                (broadcast_id, recipient_kind, recipient_ref_id, recipient_name, email, phone,
                 email_status, sms_status, whatsapp_status, app_status)
            VALUES (%s, %s, %s, %s, %s, %s, 'none', 'none', 'none', %s)
            """,
            (
                broadcast_id,
                (t.get('kind') or portal_type)[:20],
                int(t['id']) if t.get('id') else None,
                (t.get('name') or '')[:255] or None,
                em[:255] if em else None,
                ph[:80] if ph else None,
                app_status,
            ),
        )
        recip_id = cursor.lastrowid
        portal_notif_id = None
        if app_enabled:
            target_aud = (t.get('audience') or aud or 'parents').lower().strip()
            if target_aud == 'students':
                uid = _communication_student_portal_user_id(cursor, t.get('student_id'))
            else:
                uid = _communication_portal_user_id(cursor, em)
            if target_aud == 'employees':
                recip_portal_type = 'employee'
            elif target_aud == 'students':
                recip_portal_type = 'student'
            else:
                recip_portal_type = 'parent'
            if uid:
                _insert_portal_notification(
                    cursor,
                    recipient_type=recip_portal_type,
                    recipient_email=em or None,
                    recipient_user_id=int(uid),
                    title=subject,
                    body=preview_body,
                    link_url=None,
                )
                portal_notif_id = cursor.lastrowid
                app_status = 'sent'
                cursor.execute(
                    "UPDATE communication_broadcast_recipients SET portal_notification_id = %s, app_status = %s WHERE id = %s",
                    (portal_notif_id, app_status, recip_id),
                )
                cursor.execute(
                    """
                    UPDATE communication_broadcast_recipients
                    SET delivered_at = COALESCE(delivered_at, NOW())
                    WHERE id = %s
                    """,
                    (recip_id,),
                )
            else:
                app_status = 'skipped'
                cursor.execute(
                    "UPDATE communication_broadcast_recipients SET app_status = %s WHERE id = %s",
                    (app_status, recip_id),
                )
        recipient_rows.append({
            'db_id': recip_id,
            'target': t,
            'portal_notification_id': portal_notif_id,
        })
    return broadcast_id, recipient_rows


def _communication_update_recipient_channel(cursor, recip_db_id, channel, status):
    col = {
        'email': 'email_status',
        'sms': 'sms_status',
        'whatsapp': 'whatsapp_status',
        'app': 'app_status',
    }.get(channel)
    if not col:
        return
    cursor.execute(
        f"UPDATE communication_broadcast_recipients SET {col} = %s WHERE id = %s",
        ((status or 'none')[:20], int(recip_db_id)),
    )
    if status == 'sent':
        cursor.execute(
            """
            UPDATE communication_broadcast_recipients
            SET delivered_at = COALESCE(delivered_at, NOW())
            WHERE id = %s
            """,
            (int(recip_db_id),),
        )


def _communication_finalize_broadcast_counts(cursor, broadcast_id):
    ensure_communication_broadcast_tables(cursor)
    ensure_portal_notifications_table(cursor)
    cursor.execute(
        """
        UPDATE communication_broadcast_recipients cbr
        INNER JOIN portal_notifications pn ON pn.id = cbr.portal_notification_id
        SET cbr.read_at = COALESCE(cbr.read_at, pn.read_at)
        WHERE cbr.broadcast_id = %s AND pn.read_at IS NOT NULL
        """,
        (int(broadcast_id),),
    )
    cursor.execute(
        """
        SELECT
            COUNT(*) AS total,
            SUM(CASE WHEN delivered_at IS NOT NULL THEN 1 ELSE 0 END) AS delivered,
            SUM(CASE WHEN read_at IS NOT NULL THEN 1 ELSE 0 END) AS read_cnt
        FROM communication_broadcast_recipients
        WHERE broadcast_id = %s
        """,
        (int(broadcast_id),),
    )
    row = cursor.fetchone()
    if not row:
        return
    total = int(row.get('total') if isinstance(row, dict) else row[0] or 0)
    delivered = int(row.get('delivered') if isinstance(row, dict) else row[1] or 0)
    read_cnt = int(row.get('read_cnt') if isinstance(row, dict) else row[2] or 0)
    cursor.execute(
        """
        UPDATE communication_broadcasts
        SET recipient_count = %s, delivered_count = %s, read_count = %s
        WHERE id = %s
        """,
        (total, delivered, read_cnt, int(broadcast_id)),
    )


def _communication_fetch_sent_broadcasts(cursor, page=1, per_page=20):
    ensure_communication_broadcast_tables(cursor)
    page = max(1, int(page or 1))
    per_page = max(1, min(int(per_page or 20), 50))
    offset = (page - 1) * per_page
    cursor.execute("SELECT COUNT(*) AS c FROM communication_broadcasts")
    crow = cursor.fetchone()
    total = int((crow.get('c') if isinstance(crow, dict) else crow[0]) or 0)
    cursor.execute(
        """
        SELECT id, sender_name, audience, department, subject, attachment_name,
               channels_json, recipient_count, delivered_count, read_count, created_at
        FROM communication_broadcasts
        ORDER BY created_at DESC
        LIMIT %s OFFSET %s
        """,
        (per_page, offset),
    )
    items = []
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            items.append({
                'id': row.get('id'),
                'sender_name': row.get('sender_name') or '',
                'audience': row.get('audience') or '',
                'department': row.get('department') or '',
                'subject': row.get('subject') or '',
                'attachment_name': row.get('attachment_name') or '',
                'channels': json.loads(row.get('channels_json') or '{}'),
                'recipient_count': int(row.get('recipient_count') or 0),
                'delivered_count': int(row.get('delivered_count') or 0),
                'read_count': int(row.get('read_count') or 0),
                'created_at': row.get('created_at'),
            })
        else:
            items.append({
                'id': row[0],
                'sender_name': row[1] or '',
                'audience': row[2] or '',
                'department': row[3] or '',
                'subject': row[4] or '',
                'attachment_name': row[5] or '',
                'channels': json.loads(row[6] or '{}'),
                'recipient_count': int(row[7] or 0),
                'delivered_count': int(row[8] or 0),
                'read_count': int(row[9] or 0),
                'created_at': row[10],
            })
    for item in items:
        ca = item.get('created_at')
        if ca and hasattr(ca, 'strftime'):
            item['created_at_display'] = ca.strftime('%d %b %Y, %H:%M')
        elif ca:
            item['created_at_display'] = str(ca)[:16]
        else:
            item['created_at_display'] = ''
        ch = item.get('channels') or {}
        labels = []
        if ch.get('email'):
            labels.append('Email')
        if ch.get('sms'):
            labels.append('SMS')
        if ch.get('whatsapp'):
            labels.append('WhatsApp')
        if ch.get('app'):
            labels.append('App')
        aud_meta = ch.get('_audiences') or []
        if aud_meta:
            aud_names = {'parents': 'Parents', 'students': 'Students', 'employees': 'Staff'}
            labels.extend([aud_names.get(a, a) for a in aud_meta if a in aud_names])
        elif (item.get('audience') or '').lower() == 'multi':
            labels.append('Mixed groups')
        item['channel_labels'] = labels
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    return {'items': items, 'meta': {'page': page, 'per_page': per_page, 'total': total, 'pages': pages}}


def _communication_fetch_broadcast_detail(cursor, broadcast_id):
    ensure_communication_broadcast_tables(cursor)
    ensure_portal_notifications_table(cursor)
    bid = int(broadcast_id)
    _communication_finalize_broadcast_counts(cursor, bid)
    cursor.execute(
        """
        SELECT id, sender_name, audience, department, subject, message, attachment_name,
               channels_json, recipient_count, delivered_count, read_count, created_at
        FROM communication_broadcasts WHERE id = %s LIMIT 1
        """,
        (bid,),
    )
    brow = cursor.fetchone()
    if not brow:
        return None
    if isinstance(brow, dict):
        broadcast = {
            'id': brow.get('id'),
            'sender_name': brow.get('sender_name') or '',
            'audience': brow.get('audience') or '',
            'department': brow.get('department') or '',
            'subject': brow.get('subject') or '',
            'message': brow.get('message') or '',
            'attachment_name': brow.get('attachment_name') or '',
            'channels': json.loads(brow.get('channels_json') or '{}'),
            'recipient_count': int(brow.get('recipient_count') or 0),
            'delivered_count': int(brow.get('delivered_count') or 0),
            'read_count': int(brow.get('read_count') or 0),
            'created_at': brow.get('created_at'),
        }
    else:
        broadcast = {
            'id': brow[0],
            'sender_name': brow[1] or '',
            'audience': brow[2] or '',
            'department': brow[3] or '',
            'subject': brow[4] or '',
            'message': brow[5] or '',
            'attachment_name': brow[6] or '',
            'channels': json.loads(brow[7] or '{}'),
            'recipient_count': int(brow[8] or 0),
            'delivered_count': int(brow[9] or 0),
            'read_count': int(brow[10] or 0),
            'created_at': brow[11],
        }
    ca = broadcast.get('created_at')
    if ca and hasattr(ca, 'strftime'):
        broadcast['created_at_display'] = ca.strftime('%d %b %Y, %H:%M')
    elif ca:
        broadcast['created_at_display'] = str(ca)[:16]
    else:
        broadcast['created_at_display'] = ''

    cursor.execute(
        """
        SELECT cbr.id, cbr.recipient_kind, cbr.recipient_ref_id, cbr.recipient_name,
               cbr.email, cbr.phone, cbr.email_status, cbr.sms_status, cbr.whatsapp_status,
               cbr.app_status, cbr.delivered_at, cbr.read_at, cbr.portal_notification_id,
               pn.read_at AS portal_read_at
        FROM communication_broadcast_recipients cbr
        LEFT JOIN portal_notifications pn ON pn.id = cbr.portal_notification_id
        WHERE cbr.broadcast_id = %s
        ORDER BY cbr.recipient_name ASC
        """,
        (bid,),
    )
    recipients = []
    for row in cursor.fetchall() or []:
        if isinstance(row, dict):
            r = {
                'id': row.get('id'),
                'kind': row.get('recipient_kind') or '',
                'ref_id': row.get('recipient_ref_id'),
                'name': row.get('recipient_name') or '',
                'email': row.get('email') or '',
                'phone': row.get('phone') or '',
                'email_status': row.get('email_status') or 'none',
                'sms_status': row.get('sms_status') or 'none',
                'whatsapp_status': row.get('whatsapp_status') or 'none',
                'app_status': row.get('app_status') or 'none',
                'delivered_at': row.get('delivered_at'),
                'read_at': row.get('read_at') or row.get('portal_read_at'),
                'has_portal': bool(row.get('portal_notification_id')),
            }
        else:
            r = {
                'id': row[0],
                'kind': row[1] or '',
                'ref_id': row[2],
                'name': row[3] or '',
                'email': row[4] or '',
                'phone': row[5] or '',
                'email_status': row[6] or 'none',
                'sms_status': row[7] or 'none',
                'whatsapp_status': row[8] or 'none',
                'app_status': row[9] or 'none',
                'delivered_at': row[10],
                'read_at': row[11] or row[13],
                'has_portal': bool(row[12]),
            }
        r['delivered'] = (
            r['email_status'] == 'sent'
            or r['sms_status'] == 'sent'
            or r['whatsapp_status'] == 'sent'
            or r.get('app_status') == 'sent'
        )
        r['read'] = bool(r.get('read_at'))
        recipients.append(r)
    broadcast['recipients'] = recipients
    return broadcast


def _save_communication_attachment(upload_file):
    """Persist uploaded broadcast attachment; return (path, original_name, mime) or (None, err)."""
    if not upload_file or not getattr(upload_file, 'filename', None):
        return None, None, None
    fn = secure_filename(upload_file.filename)
    if not fn or not allowed_communication_attachment(fn):
        return None, None, 'Invalid attachment type. Use PDF, Word, Excel, image, or text files.'
    ext = fn.rsplit('.', 1)[1].lower()
    if is_image_filename(fn):
        rel = _save_optimized_image(
            upload_file,
            COMMUNICATION_ATTACHMENT_FOLDER,
            f'comm_{secrets.token_hex(8)}',
            preset='attachment',
        )
        if not rel:
            return None, None, 'Could not save image attachment.'
        path = os.path.join('static', rel)
        mime = 'image/png' if rel.lower().endswith('.png') else 'image/jpeg'
        return path, fn, mime
    stored = f"comm_{secrets.token_hex(8)}.{ext}"
    path = os.path.join(COMMUNICATION_ATTACHMENT_FOLDER, stored)
    upload_file.save(path)
    mime_map = {
        'pdf': 'application/pdf',
        'png': 'image/png',
        'jpg': 'image/jpeg',
        'jpeg': 'image/jpeg',
        'gif': 'image/gif',
        'doc': 'application/msword',
        'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'xls': 'application/vnd.ms-excel',
        'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'txt': 'text/plain',
        'csv': 'text/csv',
    }
    return path, fn, mime_map.get(ext, 'application/octet-stream')


def _load_integration_data_communication():
    """Same shape as integration_settings page — for channel availability hints."""
    data = {
        'whatsapp': {'enabled': False, 'api_key': '', 'phone_number': ''},
        'email': {'enabled': False, 'smtp_username': '', 'smtp_password': '', 'from_email': ''},
        'sms': {'enabled': False, 'provider': '', 'api_key': '', 'username': '', 'sender_id': ''},
    }
    connection = get_db_connection()
    if not connection:
        return data
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                "SELECT integration_type, settings_json FROM integration_settings"
            )
            for row in cursor.fetchall() or []:
                it = row.get('integration_type') if isinstance(row, dict) else row[0]
                js = row.get('settings_json') if isinstance(row, dict) else row[1]
                try:
                    parsed = json.loads(js or '{}')
                except Exception:
                    parsed = {}
                if it in data and isinstance(parsed, dict):
                    data[it].update(parsed)
    except Exception as e:
        print(f"_load_integration_data_communication: {e}")
    finally:
        connection.close()
    return data


def _communication_channel_flags(integ):
    """Which channels appear configured (for UI + send)."""
    em = integ.get('email') or {}
    sm = integ.get('sms') or {}
    wa = integ.get('whatsapp') or {}
    email_ok = bool((em.get('smtp_username') or '').strip() and (em.get('smtp_password') or '').strip()) or bool(
        (os.environ.get('MAIL_USERNAME') or '').strip()
    )
    prov = (sm.get('provider') or '').lower()
    api_key = (sm.get('api_key') or '').strip()
    sms_ok = bool(sm.get('enabled')) and bool(api_key)
    if sms_ok and ('africa' in prov or prov == 'africastalking'):
        sms_ok = bool((sm.get('username') or sm.get('account_username') or '').strip())
    wa_ok = bool(wa.get('enabled')) and bool(
        (wa.get('api_key') or wa.get('access_token') or '').strip()
    ) and bool((wa.get('phone_number_id') or wa.get('phone_number') or '').strip())
    return {'email': email_ok, 'sms': sms_ok, 'whatsapp': wa_ok, 'app': notification_mode_active('app')}


def _render_communication_centre(tpad_mode=False):
    """Communication centre — broadcast to staff or parents (optional TPAD context)."""
    if tpad_mode:
        denied = _employee_tpad_access_guard()
        if denied:
            return denied
    elif not _user_can_access_communication():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    user_role = session.get('role', '').lower()
    integ = _load_integration_data_communication()
    channels = _communication_channel_flags(integ)

    academic_levels = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute(
                    """
                    SELECT id, level_name, level_category
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_name
                    """
                )
                for row in cursor.fetchall() or []:
                    academic_levels.append(
                        {
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
                            'level_category': row.get('level_category') if isinstance(row, dict) else row[2],
                        }
                    )
        except Exception as e:
            print(f"communication academic_levels: {e}")
        finally:
            connection.close()

    departments = [
        'Front office',
        'Administration',
        'Academics',
        'Finance',
        'ICT',
        'Sports & co-curricular',
        'Other',
    ]

    return render_template(
        'dashboards/communication.html',
        role=user_role,
        integration_data=integ,
        channel_flags=channels,
        academic_levels=academic_levels,
        departments=departments,
        tpad_mode=tpad_mode,
        communication_sent_list_url='/api/employee/communication/sent',
        communication_sent_detail_base='/api/employee/communication/sent',
    )


