@app.route('/dashboard/employee/accounts/register', methods=['POST'])
@login_required
def register_finance_account():
    """Save a finance account record."""
    redir = _accountant_guard()
    if redir:
        return redir

    def _accounts_redirect(open_form=False):
        after = (request.form.get('after_register') or '').strip().lower()
        if after == 'petty-cash-book':
            url = employee_dash_url('accounts/petty-cash-book')
            if open_form:
                url += '?register=1'
            return url
        url = employee_dash_url('accounts')
        if open_form:
            url += '?register=1'
        return url

    redirect_url = _accounts_redirect()
    redirect_url_open = _accounts_redirect(open_form=True)

    after_register = (request.form.get('after_register') or '').strip().lower()
    existing_account_id = request.form.get('existing_finance_account_id', type=int)
    category_raw_early = (request.form.get('account_category') or '').strip().lower()
    if (
        after_register == 'petty-cash-book'
        and category_raw_early == 'petty cash'
        and existing_account_id
    ):
        petty_cash_vote_names = _parse_expense_vote_names_from_form(request.form)
        if not petty_cash_vote_names:
            flash('Please select at least one expense vote for this petty cash account.', 'error')
            return redirect(redirect_url_open)
        selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
        payment_records, payment_err = _prepare_finance_account_payment_records(
            request.form, selected_payment_modes
        )
        if payment_err:
            flash(payment_err, 'error')
            return redirect(redirect_url_open)
        description = normalize_text(
            request.form.get('account_description'), allow_empty=True
        )
        connection = get_db_connection()
        if not connection:
            flash('Could not connect to the database.', 'error')
            return redirect(redirect_url_open)
        try:
            with connection.cursor() as cursor:
                ok, message = _link_existing_account_to_petty_cash_book(
                    cursor,
                    existing_account_id,
                    description,
                    petty_cash_vote_names,
                    payment_records,
                )
                if ok:
                    connection.commit()
                    flash(message, 'success')
                    return redirect(
                        employee_dash_url('accounts/petty-cash-book')
                        + f'?finance_account_id={int(existing_account_id)}'
                    )
                connection.rollback()
                flash(message or 'Could not link account.', 'error')
                return redirect(redirect_url_open)
        except Exception as e:
            connection.rollback()
            print(f"register_finance_account link petty cash: {e}")
            flash('Could not link the account to the petty cash book.', 'error')
            return redirect(redirect_url_open)
        finally:
            connection.close()

    fields, field_err = _prepare_finance_account_fields_from_form(request.form)
    if field_err:
        flash(field_err, 'error')
        return redirect(redirect_url_open)
    category = fields['category']
    name = fields['name']
    description = fields['description']
    level_ids_raw = fields['level_ids_raw']
    selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
    payment_records, payment_err = _prepare_finance_account_payment_records(
        request.form, selected_payment_modes
    )
    if payment_err:
        flash(payment_err, 'error')
        return redirect(redirect_url_open)

    fields = _apply_finance_account_company_from_bank(
        fields, payment_records, selected_payment_modes
    )
    company_name = fields.get('company_name')
    company_number = fields.get('company_number')

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url_open)

    level_ids = []
    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            level_ids = _filter_valid_academic_level_ids(cursor, level_ids_raw)
    finally:
        connection.close()

    is_petty_cash = _finance_account_category_is_petty_cash(category)
    petty_cash_vote_names = []
    if is_petty_cash:
        # Petty cash accounts are managed from the Petty cash book page (votes are chosen there).
        # Prevent registering them from the general accounts page where the UI does not show votes.
        if after_register != 'petty-cash-book':
            flash('Petty cash accounts must be registered from the Petty cash book page.', 'error')
            return redirect(
                employee_dash_url('accounts/petty-cash-book') + '?register=1'
            )
        petty_cash_vote_names = _parse_expense_vote_names_from_form(request.form)
        if not petty_cash_vote_names:
            flash('Please select at least one expense vote for this petty cash account.', 'error')
            return redirect(redirect_url_open)
    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url_open)

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            recorded_by = (
                session.get('full_name') or session.get('username') or ''
            ).strip()
            cursor.execute(
                """
                INSERT INTO finance_accounts
                    (account_category, account_name, account_description,
                     company_name, company_number, recorded_by_name)
                VALUES (%s, %s, %s, %s, %s, %s)
                """,
                (
                    category,
                    name,
                    description or None,
                    company_name,
                    company_number,
                    recorded_by or None,
                ),
            )
            account_id = cursor.lastrowid
            if is_petty_cash:
                _save_finance_account_expense_votes(cursor, account_id, petty_cash_vote_names)
            elif level_ids:
                _save_finance_account_academic_levels(cursor, account_id, level_ids)
            _save_finance_account_payment_methods(cursor, account_id, payment_records)
            connection.commit()
            invalidate_finance_portal_caches()
            if is_petty_cash:
                flash(f'Petty cash account "{name}" registered.', 'success')
            elif level_ids:
                level_count = len(level_ids)
                flash(
                    f'Account "{name}" ({category}) registered and linked to '
                    f'{level_count} class{"es" if level_count != 1 else ""}.',
                    'success',
                )
            else:
                flash(f'Account "{name}" ({category}) registered.', 'success')
    except Exception as e:
        print(f"register_finance_account: {e}")
        flash('Could not save the account. Please try again.', 'error')
        return redirect(redirect_url_open)
    finally:
        connection.close()

    return redirect(redirect_url)


@app.route('/dashboard/employee/accounts/edit', methods=['POST'])
@app.route('/dashboard/employee/accounts/<int:account_id>/edit', methods=['POST'])
@login_required
def edit_finance_account(account_id=None):
    """Update a registered finance account."""
    redir = _accountant_guard()
    if redir:
        return redir

    account_id = request.form.get('finance_account_id', type=int) or account_id
    if not account_id:
        flash('Invalid account.', 'error')
        return redirect(employee_dash_url('accounts'))

    redirect_url = employee_dash_url('accounts')
    edit_url = redirect_url + f'?edit={account_id}'

    fields, field_err = _prepare_finance_account_fields_from_form(request.form)
    if field_err:
        flash(field_err, 'error')
        return redirect(edit_url)

    category = fields['category']
    name = fields['name']
    description = fields['description']
    level_ids_raw = fields['level_ids_raw']
    selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
    payment_records, payment_err = _prepare_finance_account_payment_records(
        request.form, selected_payment_modes
    )
    if payment_err:
        flash(payment_err, 'error')
        return redirect(edit_url)

    fields = _apply_finance_account_company_from_bank(
        fields, payment_records, selected_payment_modes
    )
    company_name = fields.get('company_name')
    company_number = fields.get('company_number')

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(edit_url)

    level_ids = []
    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            if not _finance_account_exists(cursor, account_id):
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            level_ids = _filter_valid_academic_level_ids(cursor, level_ids_raw)
            cursor.execute(
                """
                UPDATE finance_accounts
                SET account_category = %s,
                    account_name = %s,
                    account_description = %s,
                    company_name = %s,
                    company_number = %s
                WHERE id = %s
                """,
                (
                    category,
                    name,
                    description,
                    company_name,
                    company_number,
                    account_id,
                ),
            )
            if not _finance_account_exists(cursor, account_id):
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            _save_finance_account_academic_levels(cursor, account_id, level_ids)
            _save_finance_account_payment_methods(cursor, account_id, payment_records)
            connection.commit()
            invalidate_finance_portal_caches()
            flash(f'Account "{name}" updated successfully.', 'success')
    except Exception as e:
        print(f"edit_finance_account: {e}")
        connection.rollback()
        flash('Could not update the account. Please try again.', 'error')
        return redirect(edit_url)
    finally:
        connection.close()

    return redirect(redirect_url)


@app.route('/dashboard/employee/accounts/<int:account_id>/toggle-suspend', methods=['POST'])
@login_required
def toggle_finance_account_suspend(account_id):
    """Suspend or unsuspend a finance account."""
    redir = _accountant_guard()
    if redir:
        return redir

    redirect_url = employee_dash_url('accounts')
    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url)

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            connection.commit()
            existing = _fetch_finance_account_by_id(cursor, account_id)
            if not existing:
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            was_suspended = (existing.get('account_status') or 'active') == 'suspended'
            cursor.execute(
                """
                UPDATE finance_accounts
                SET account_status = IF(account_status = 'suspended', 'active', 'suspended')
                WHERE id = %s
                """,
                (account_id,),
            )
            connection.commit()
            label = existing.get('account_name') or 'Account'
            if was_suspended:
                flash(f'"{label}" is active again.', 'success')
            else:
                flash(f'"{label}" has been suspended.', 'success')
    except Exception as e:
        print(f"toggle_finance_account_suspend: {e}")
        connection.rollback()
        flash('Could not update account status.', 'error')
    finally:
        connection.close()

    return redirect(redirect_url)


def _purge_finance_account_related_records(cursor, account_id):
    """Remove ledger transactions and other dependents before deleting a finance account."""
    try:
        account_id = int(account_id)
    except (TypeError, ValueError):
        return 0
    if account_id <= 0:
        return 0

    ensure_finance_account_transactions_table(cursor)
    ensure_petty_cash_expenses_table(cursor)
    ensure_finance_account_expense_votes_table(cursor)
    ensure_fee_structures_finance_account_column(cursor)
    ensure_fee_items_finance_account_column(cursor)
    ensure_accountant_revenue_finance_account_column(cursor)
    ensure_student_pocket_money_tables(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)
    ensure_mpesa_stk_transactions_table(cursor)

    txn_count = 0
    try:
        cursor.execute(
            """
            SELECT COUNT(*) AS c FROM finance_account_transactions
            WHERE finance_account_id = %s
            """,
            (account_id,),
        )
        row = cursor.fetchone()
        if isinstance(row, dict):
            txn_count = int(row.get('c') or 0)
        elif row:
            txn_count = int(row[0] or 0)
    except Exception as e:
        print(f"_purge_finance_account_related_records count: {e}")

    cursor.execute(
        "DELETE FROM finance_account_transactions WHERE finance_account_id = %s",
        (account_id,),
    )
    cursor.execute(
        "DELETE FROM petty_cash_expenses WHERE finance_account_id = %s",
        (account_id,),
    )

    for stmt in (
        "UPDATE fee_structures SET finance_account_id = NULL WHERE finance_account_id = %s",
        "UPDATE fee_items SET finance_account_id = NULL WHERE finance_account_id = %s",
        "UPDATE accountant_revenue SET finance_account_id = NULL WHERE finance_account_id = %s",
        "UPDATE student_pocket_money_transactions SET finance_account_id = NULL WHERE finance_account_id = %s",
        "UPDATE store_stock_in_payment_lines SET finance_account_id = NULL WHERE finance_account_id = %s",
        "UPDATE mpesa_stk_transactions SET finance_account_id = NULL WHERE finance_account_id = %s",
    ):
        try:
            cursor.execute(stmt, (account_id,))
        except Exception as e:
            print(f"_purge_finance_account_related_records clear ref: {e}")

    return txn_count


@app.route('/dashboard/employee/accounts/<int:account_id>/delete/request-code', methods=['POST'])
@login_required
def request_finance_account_delete_code(account_id):
    """Email a 6-digit code before deleting a finance account."""
    redir = _accountant_guard()
    if redir:
        return jsonify({'success': False, 'message': 'Unauthorized.'}), 403

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Could not connect to the database.'}), 500

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            existing = _fetch_finance_account_by_id(cursor, account_id)
            if not existing:
                return jsonify({'success': False, 'message': 'Account not found.'}), 404
            label = existing.get('account_name') or 'Account'
            target_key = _finance_delete_verification_target_key('finance_account', [account_id])
            ok, message, dev_code = _issue_finance_delete_verification_code(
                cursor,
                'finance_account',
                target_key,
                f'finance account "{label}"',
            )
            if not ok:
                return jsonify({'success': False, 'message': message}), 400
            payload = {'success': True, 'message': message}
            if dev_code:
                payload['delivery'] = 'onscreen'
                payload['dev_code'] = dev_code
            return jsonify(payload), 200
    except Exception as e:
        print(f"request_finance_account_delete_code: {e}")
        return jsonify({'success': False, 'message': 'Could not send confirmation code.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/accounts/<int:account_id>/delete', methods=['POST'])
@login_required
def delete_finance_account(account_id):
    """Permanently delete a finance account and its ledger transactions."""
    redir = _accountant_guard()
    if redir:
        return redir

    redirect_url = employee_dash_url('accounts')
    wants_json = (
        request.is_json or
        (request.headers.get('X-Requested-With') or '').lower() == 'xmlhttprequest'
    )
    data = request.get_json(silent=True) if wants_json else {}
    confirmation_code = (
        (data.get('confirmation_code') if isinstance(data, dict) else None) or
        request.form.get('confirmation_code')
    )
    target_key = _finance_delete_verification_target_key('finance_account', [account_id])
    code_ok, code_message = _validate_finance_delete_verification_code(
        'finance_account', target_key, confirmation_code,
    )
    if not code_ok:
        if wants_json:
            return jsonify({'success': False, 'message': code_message}), 401
        flash(code_message, 'error')
        return redirect(redirect_url)

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url)

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            connection.commit()
            existing = _fetch_finance_account_by_id(cursor, account_id)
            if not existing:
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            label = existing.get('account_name') or 'Account'
            txn_deleted = _purge_finance_account_related_records(cursor, account_id)
            cursor.execute("DELETE FROM finance_accounts WHERE id = %s", (account_id,))
            connection.commit()
            if txn_deleted:
                message = (
                    f'Account "{label}" and {txn_deleted} related transaction(s) deleted.'
                )
            else:
                message = f'Account "{label}" deleted.'
            if wants_json:
                return jsonify({'success': True, 'message': message, 'redirect': redirect_url})
            flash(message, 'success')
    except Exception as e:
        print(f"delete_finance_account: {e}")
        connection.rollback()
        if wants_json:
            return jsonify({'success': False, 'message': 'Could not delete the account. Please try again.'}), 500
        flash('Could not delete the account. Please try again.', 'error')
    finally:
        connection.close()

    return redirect(redirect_url)


@app.route('/dashboard/employee/revenue')
@login_required
def accountant_revenue():
    """Register and view school revenue (government or private)."""
    redir = _accountant_guard()
    if redir:
        return redir

    user_role = session.get('role', '').lower()
    source_filter = (request.args.get('source') or 'all').strip().lower()
    if source_filter not in ('all', 'government', 'private', 'fees', 'income'):
        source_filter = 'all'
    finance_account_id = None
    raw_account = (request.args.get('account') or '').strip()
    if raw_account.isdigit():
        finance_account_id = int(raw_account)
    if finance_account_id:
        return _render_finance_account_revenue_page(finance_account_id)

    revenue_rows = []
    fee_payment_rows = []
    manual_revenue_rows = []
    fees_paid_breakdown = []
    revenue_summary = {}
    income_accounts_picker = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_accountant_revenue_table(cursor)
                ensure_accountant_revenue_finance_account_column(cursor)
                ensure_accountant_revenue_items_table(cursor)
                ensure_finance_accounts_table(cursor)
                connection.commit()
                income_accounts_picker = _fetch_finance_accounts_for_revenue_picker(cursor)
                revenue_lists = _fetch_revenue_lists_for_page(
                    cursor,
                    source_filter=source_filter,
                    finance_account_id=finance_account_id,
                )
                revenue_rows = revenue_lists.get('display_rows') or []
                fee_payment_rows = revenue_lists.get('fee_rows') or []
                manual_revenue_rows = revenue_lists.get('manual_rows') or []
                fees_paid_breakdown = _fetch_student_fees_paid_breakdown(
                    cursor, finance_account_id=finance_account_id,
                )
                revenue_summary = _fetch_accountant_revenue_summary(cursor)
        except Exception as e:
            print(f"accountant_revenue: {e}")
        finally:
            connection.close()
    else:
        flash('Could not connect to the database.', 'error')

    rs = revenue_summary or {}
    filtered_total_display = rs.get('total_display', '0.00')
    filtered_label = 'All sources'
    if source_filter == 'fees':
        filtered_total_display = rs.get('fees_display', '0.00')
        filtered_label = 'Student fees'
    elif source_filter == 'government':
        filtered_total_display = rs.get('government_display', '0.00')
        filtered_label = 'Government income'
    elif source_filter == 'private':
        filtered_total_display = rs.get('private_display', '0.00')
        filtered_label = 'Private income'
    elif source_filter == 'income':
        filtered_total_display = rs.get('income_account_display', '0.00')
        filtered_label = 'Income accounts'
    selected_account_summary = None
    if finance_account_id:
        filtered_label = 'Selected account'
        for ia in rs.get('account_totals') or rs.get('income_accounts') or []:
            if int(ia.get('id') or 0) == int(finance_account_id):
                filtered_total_display = ia.get(
                    'registered_display',
                    ia.get('total_display', filtered_total_display),
                )
                filtered_label = ia.get('account_name') or filtered_label
                selected_account_summary = {
                    'id': ia.get('id'),
                    'account_name': ia.get('account_name'),
                    'registered_display': ia.get(
                        'registered_display', ia.get('total_display'),
                    ),
                }
                break

    show_student_fees_section = source_filter in ('all', 'fees') or bool(
        finance_account_id and fee_payment_rows,
    )
    show_other_income_section = source_filter in (
        'all', 'income', 'government', 'private',
    )

    return render_template(
        'dashboards/accountant_revenue.html',
        role=user_role,
        revenue_rows=revenue_rows,
        fee_payment_rows=fee_payment_rows,
        manual_revenue_rows=manual_revenue_rows,
        fees_paid_breakdown=fees_paid_breakdown,
        revenue_summary=rs,
        source_filter=source_filter,
        finance_account_filter=finance_account_id,
        income_accounts_picker=income_accounts_picker,
        record_count=len(revenue_rows),
        fee_payment_count=len(fee_payment_rows),
        filtered_total_display=filtered_total_display,
        filtered_label=filtered_label,
        selected_account_summary=selected_account_summary,
        show_student_fees_section=show_student_fees_section,
        show_other_income_section=show_other_income_section,
    )


