@app.route(
    '/dashboard/employee/payments-invoices/supplier/pay-all',
    methods=['POST'],
)
@login_required
def record_supplier_pay_all():
    """Pay one or all outstanding stock-in invoices for a supplier (by phone)."""
    redir = _accountant_guard()
    if redir:
        return redir

    from decimal import Decimal, InvalidOperation

    payment_filter = (request.args.get('payment') or 'outstanding').strip().lower()
    if payment_filter not in ('all', 'pending', 'partial', 'paid', 'outstanding'):
        payment_filter = 'outstanding'
    redirect_url = employee_dash_url('payments-invoices') + f'?payment={payment_filter}'
    wants_ajax = _payments_invoices_wants_ajax()

    def _pay_fail(message):
        print(f"record_supplier_pay_all: {message}")
        if wants_ajax:
            return jsonify({'success': False, 'message': message}), 400
        flash(message, 'error')
        return redirect(redirect_url)

    def _pay_ok(message, cursor):
        if wants_ajax:
            payload = {'success': True, 'message': message}
            payload.update(_fetch_payments_invoices_live_payload(cursor, payment_filter))
            return jsonify(payload)
        flash(message, 'success')
        return redirect(redirect_url)

    raw_amount = (request.form.get('amount_paid') or '').strip().replace(',', '')
    company_name = (request.form.get('paid_to_company_name') or '').strip().upper()
    supplier_phone_raw = (request.form.get('supplier_phone') or '').strip()
    paid_to_phone_raw = (request.form.get('paid_to_company_phone') or '').strip()
    if supplier_phone_raw.startswith('__no_phone_'):
        company_phone_raw = paid_to_phone_raw
    else:
        company_phone_raw = supplier_phone_raw or paid_to_phone_raw
    phone_norm = _normalize_store_supplier_phone(company_phone_raw)
    company_phone = phone_norm or _normalize_store_supplier_phone(paid_to_phone_raw)

    try:
        pay_amount = Decimal(raw_amount).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        pay_amount = None

    if pay_amount is None or pay_amount <= 0:
        return _pay_fail('Enter a valid payment amount greater than zero.')
    if not company_name:
        return _pay_fail('Enter the company name paid to.')
    movement_ids = request.form.getlist('movement_ids')
    if not movement_ids and (not phone_norm or phone_norm.startswith('__no_phone_')):
        return _pay_fail('A valid supplier phone number is required to pay all invoices.')
    if not company_phone:
        return _pay_fail('Enter a valid company contact number (at least 9 digits).')
    if len(company_name) > 255:
        company_name = company_name[:255]

    connection = get_db_connection()
    if not connection:
        return _pay_fail('Could not connect to the database.')

    try:
        with connection.cursor() as cursor:
            funding, fund_err = _parse_expense_payment_funding(request.form, cursor)
            if fund_err:
                return _pay_fail(fund_err)
            paid_by = (
                session.get('full_name') or session.get('username') or ''
            ).strip()
            if movement_ids:
                ok, message = _record_supplier_pay_selected_invoices(
                    cursor, movement_ids, company_name, company_phone, paid_by,
                    payment_method=funding['payment_method'],
                    finance_account_id=funding['finance_account_id'],
                    payment_reference=funding['payment_reference'],
                    expected_amount=pay_amount,
                    vote_name=funding.get('vote_name'),
                )
            else:
                ok, message = _record_supplier_pay_all(
                    cursor, phone_norm, pay_amount, company_name, company_phone, paid_by,
                    payment_method=funding['payment_method'],
                    finance_account_id=funding['finance_account_id'],
                    payment_reference=funding['payment_reference'],
                    vote_name=funding.get('vote_name'),
                )
            if ok:
                connection.commit()
                return _pay_ok(message, cursor)
            connection.rollback()
            return _pay_fail(message)
    except Exception as e:
        print(f"record_supplier_pay_all: {e}")
        connection.rollback()
        return _pay_fail('Could not record payment.')
    finally:
        connection.close()


@app.route(
    '/dashboard/employee/payments-invoices/stock-in/<int:movement_id>/pay',
    methods=['POST'],
)
@login_required
def record_stock_in_payment(movement_id):
    """Record a full or partial payment against a stock-in movement."""
    redir = _accountant_guard()
    if redir:
        return redir

    from decimal import Decimal, InvalidOperation

    payment_filter = (request.args.get('payment') or 'outstanding').strip().lower()
    if payment_filter not in ('all', 'pending', 'partial', 'paid', 'outstanding'):
        payment_filter = 'outstanding'
    redirect_url = employee_dash_url('payments-invoices') + f'?payment={payment_filter}'
    wants_ajax = _payments_invoices_wants_ajax()

    def _pay_fail(message):
        if wants_ajax:
            return jsonify({'success': False, 'message': message}), 400
        flash(message, 'error')
        return redirect(redirect_url)

    def _pay_ok(message, cursor):
        if wants_ajax:
            payload = {'success': True, 'message': message}
            payload.update(_fetch_payments_invoices_live_payload(cursor, payment_filter))
            return jsonify(payload)
        flash(message, 'success')
        return redirect(redirect_url)

    raw_amount = (request.form.get('amount_paid') or '').strip().replace(',', '')
    company_name = (request.form.get('paid_to_company_name') or '').strip().upper()
    company_phone_raw = (request.form.get('paid_to_company_phone') or '').strip()
    company_phone = _normalize_store_supplier_phone(company_phone_raw)

    try:
        pay_amount = Decimal(raw_amount).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        pay_amount = None

    if pay_amount is None or pay_amount <= 0:
        return _pay_fail('Enter a valid payment amount greater than zero.')
    if not company_name:
        return _pay_fail('Enter the company name paid to.')
    if not company_phone:
        return _pay_fail('Enter a valid company contact number (at least 9 digits).')
    if len(company_name) > 255:
        company_name = company_name[:255]

    connection = get_db_connection()
    if not connection:
        return _pay_fail('Could not connect to the database.')

    try:
        with connection.cursor() as cursor:
            funding, fund_err = _parse_expense_payment_funding(request.form, cursor)
            if fund_err:
                return _pay_fail(fund_err)
            paid_by = (
                session.get('full_name') or session.get('username') or ''
            ).strip()
            ok, message = _apply_stock_in_payment(
                cursor, movement_id, pay_amount, company_name, company_phone, paid_by,
                payment_method=funding['payment_method'],
                finance_account_id=funding['finance_account_id'],
                payment_reference=funding['payment_reference'],
                vote_name=funding.get('vote_name'),
            )
            if ok:
                connection.commit()
                return _pay_ok(message, cursor)
            connection.rollback()
            return _pay_fail(message)
    except Exception as e:
        print(f"record_stock_in_payment: {e}")
        connection.rollback()
        return _pay_fail('Could not record payment.')
    finally:
        connection.close()


@app.route(
    '/dashboard/employee/payments-invoices/register-payment',
    methods=['POST'],
)
@login_required
def register_misc_payment():
    """Register a payment not tied to an existing stock-in record."""
    redir = _accountant_guard()
    if redir:
        return redir

    from decimal import Decimal, InvalidOperation

    payment_filter = (request.args.get('payment') or 'outstanding').strip().lower()
    if payment_filter not in ('all', 'pending', 'partial', 'paid', 'outstanding'):
        payment_filter = 'outstanding'
    redirect_url = employee_dash_url('payments-invoices') + f'?payment={payment_filter}'
    wants_ajax = _payments_invoices_wants_ajax()

    def _pay_fail(message):
        if wants_ajax:
            return jsonify({'success': False, 'message': message}), 400
        flash(message, 'error')
        return redirect(redirect_url)

    def _pay_ok(message, cursor):
        if wants_ajax:
            payload = {'success': True, 'message': message}
            payload.update(_fetch_payments_invoices_live_payload(cursor, payment_filter))
            return jsonify(payload)
        flash(message, 'success')
        return redirect(redirect_url)

    raw_amount = (request.form.get('amount_paid') or '').strip().replace(',', '')
    company_name = (request.form.get('paid_to_company_name') or '').strip().upper()
    company_phone_raw = (request.form.get('paid_to_company_phone') or '').strip()
    company_phone = _normalize_store_supplier_phone(company_phone_raw)
    description = _normalize_payment_description_text(request.form.get('description') or '')
    if len(description) > 500:
        description = description[:500]

    try:
        pay_amount = Decimal(raw_amount).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        pay_amount = None

    if pay_amount is None or pay_amount <= 0:
        return _pay_fail('Enter a valid payment amount greater than zero.')
    if not company_name:
        return _pay_fail('Enter the company name paid to.')
    if not company_phone:
        return _pay_fail('Enter a valid company contact number (at least 9 digits).')
    if len(company_name) > 255:
        company_name = company_name[:255]

    connection = get_db_connection()
    if not connection:
        return _pay_fail('Could not connect to the database.')

    try:
        with connection.cursor() as cursor:
            ensure_accountant_misc_payments_table(cursor)
            ensure_accountant_payment_descriptions_table(cursor)
            supplier_id = None
            sup_id, sup_err = _store_upsert_supplier_for_stock_in(
                cursor, company_phone, company_name,
            )
            if sup_id:
                supplier_id = sup_id
            elif sup_err:
                print(f"register_misc_payment supplier upsert: {sup_err}")
            if description:
                _upsert_payment_description(cursor, description)
            ref_no = _generate_accountant_misc_payment_reference(cursor)
            recorded_by = (
                session.get('full_name') or session.get('username') or ''
            ).strip()
            cursor.execute(
                """
                INSERT INTO accountant_misc_payments
                    (reference_number, amount, paid_to_company_name,
                     paid_to_company_phone, description, supplier_id, recorded_by_name)
                VALUES (%s, %s, %s, %s, %s, %s, %s)
                """,
                (
                    ref_no, pay_amount, company_name, company_phone,
                    description or None, supplier_id, recorded_by or None,
                ),
            )
            connection.commit()
            return _pay_ok(
                f'Payment {ref_no} of KES {pay_amount:,.2f} recorded for {company_name}.',
                cursor,
            )
    except Exception as e:
        print(f"register_misc_payment: {e}")
        connection.rollback()
        return _pay_fail('Could not register payment.')
    finally:
        connection.close()


