# Logs & Audit Trails Route
@app.route('/database/logs-audit-trails')
@login_required
def logs_audit_trails():
    """Logs and audit trails page for technicians and principals"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access
    has_access = check_permission_or_role('view_audit_logs', 
                                         allowed_roles=['technician', 'head of institution'])
    
    if not has_access:
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    connection = get_db_connection()
    salary_audits = []
    migrations = []
    backups = []
    audit_summary = {
        'salary_audits_count': 0,
        'migrations_count': 0,
        'backups_count': 0,
        'total_records': 0
    }
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get salary audits
                try:
                    cursor.execute("""
                        SELECT 
                            esa.id,
                            esa.salary_id,
                            esa.employee_id,
                            esa.field_name,
                            esa.old_value,
                            esa.new_value,
                            esa.edited_by,
                            esa.edited_by_name,
                            esa.edited_at,
                            e.full_name as employee_name,
                            e.employee_id as employee_code
                        FROM employee_salary_audits esa
                        LEFT JOIN employees e ON esa.employee_id = e.id
                        ORDER BY esa.edited_at DESC
                        LIMIT 500
                    """)
                    salary_audits = cursor.fetchall()
                    audit_summary['salary_audits_count'] = len(salary_audits)
                except Exception as e:
                    print(f"Error fetching salary audits: {e}")
                    salary_audits = []
                
                # Get migrations
                try:
                    cursor.execute("""
                        SELECT 
                            id,
                            migration_name,
                            status,
                            applied_at,
                            execution_time_ms,
                            applied_by,
                            error_message
                        FROM migrations
                        ORDER BY applied_at DESC
                        LIMIT 100
                    """)
                    migrations = cursor.fetchall()
                    audit_summary['migrations_count'] = len(migrations)
                except Exception as e:
                    print(f"Error fetching migrations: {e}")
                    migrations = []
                
                # Get backup history
                try:
                    cursor.execute("""
                        SELECT 
                            id,
                            filename,
                            file_path,
                            file_size,
                            table_count,
                            record_count,
                            created_at,
                            created_by
                        FROM backup_history
                        ORDER BY created_at DESC
                        LIMIT 50
                    """)
                    backups = cursor.fetchall()
                    audit_summary['backups_count'] = len(backups)
                except Exception as e:
                    print(f"Error fetching backup history: {e}")
                    backups = []
                
                audit_summary['total_records'] = len(salary_audits) + len(migrations) + len(backups)
                
        except Exception as e:
            print(f"Error fetching audit trails: {e}")
            import traceback
            traceback.print_exc()
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass
    
    return render_template('dashboards/logs_audit_trails.html', 
                         salary_audits=salary_audits,
                         migrations=migrations,
                         backups=backups,
                         audit_summary=audit_summary)

def can_manage_employee_permissions():
    """Technician, head of institution, deputy head, or super admin (incl. view-as)."""
    if not has_request_context():
        return False
    ur = (session.get('role') or '').lower().strip()
    ve = (session.get('viewing_as_employee_role') or '').lower().strip()
    if ur == 'technician':
        return True
    effective = ve if ur == 'technician' and ve else ur
    return effective in ('head of institution', 'deputy head of institution', 'super admin')


# Users & Roles Route
@app.route('/users-roles')
@login_required
def users_roles():
    """Users and roles / staff permissions management."""
    if not can_manage_employee_permissions():
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    connection = get_db_connection()
    employees_by_role = {}
    summary = {
        'total_employees': 0,
        'active_count': 0,
        'pending_count': 0,
        'total_roles': 0
    }
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Fetch all employees
                cursor.execute("""
                    SELECT 
                        id, employee_id, full_name, email, phone, id_number, 
                        role, status, profile_picture, created_at, updated_at
                    FROM employees
                    ORDER BY role ASC, full_name ASC
                """)
                employees = cursor.fetchall()
                
                # Group employees by role
                for employee in employees:
                    role = employee.get('role', 'employee')
                    if role not in employees_by_role:
                        employees_by_role[role] = []
                    employees_by_role[role].append(employee)
                    
                    # Update summary
                    summary['total_employees'] += 1
                    if employee.get('status') == 'active':
                        summary['active_count'] += 1
                    elif employee.get('status') == 'pending approval':
                        summary['pending_count'] += 1
                
                summary['total_roles'] = len(employees_by_role)
                
        except Exception as e:
            print(f"Error fetching users and roles: {e}")
            import traceback
            traceback.print_exc()
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass
    
    return render_template('dashboards/users_roles.html', 
                         employees_by_role=employees_by_role,
                         summary=summary)

