@app.route('/system-settings/term/<int:term_id>/toggle-lock', methods=['POST'])
@login_required
def toggle_term_lock(term_id):
    """Toggle term lock/unlock status"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Allow technicians and accountants
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_technician = user_role == 'technician'
    
    if not (is_technician or is_accountant):
        return jsonify({'success': False, 'message': 'Permission denied.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Get current lock status
            cursor.execute("SELECT is_locked FROM terms WHERE id = %s", (term_id,))
            term_result = cursor.fetchone()
            if not term_result:
                return jsonify({'success': False, 'message': 'Term not found.'}), 404
            
            current_locked = term_result.get('is_locked') if isinstance(term_result, dict) else term_result[0]
            new_locked = not current_locked
            
            # Update lock status
            if new_locked:
                cursor.execute("""
                    UPDATE terms 
                    SET is_locked = TRUE, locked_at = NOW() 
                    WHERE id = %s
                """, (term_id,))
                message = 'Term locked successfully!'
            else:
                cursor.execute("""
                    UPDATE terms 
                    SET is_locked = FALSE, locked_at = NULL 
                    WHERE id = %s
                """, (term_id,))
                message = 'Term unlocked successfully!'
            
            connection.commit()
            return jsonify({
                'success': True, 
                'message': message,
                'is_locked': new_locked
            })
    except Exception as e:
        print(f"Error toggling term lock: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'An error occurred while updating the term lock status.'}), 500
    finally:
        connection.close()


def _safe_startup_log(message):
    """Log startup messages without crashing Passenger (stdout may be closed)."""
    try:
        print(message, flush=True)
    except (BrokenPipeError, OSError):
        pass


def _hosted_core_tables_ready():
    """
    Lightweight hosted check: SELECT 1 + a few required tables.
    Avoids running full init_db/migrations on every worker (causes 1040 Too many connections).
    """
    connection = get_db_connection()
    if not connection:
        return False
    try:
        with connection.cursor() as cursor:
            cursor.execute('SELECT 1 AS ok')
            if not cursor.fetchone():
                return False
            for tbl in ('students', 'student_marks', 'school_settings', 'employees', 'exams'):
                cursor.execute(
                    """
                    SELECT 1
                    FROM information_schema.TABLES
                    WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s
                    LIMIT 1
                    """,
                    (tbl,),
                )
                if not cursor.fetchone():
                    return False
        return True
    except Exception as e:
        _safe_startup_log(f"[DB] Hosted ready-check failed: {e}")
        return False
    finally:
        try:
            connection.close()
        except Exception:
            pass


def _ensure_db_schema():
    """Check DB health and auto-create missing tables. Returns True when done (or safely skipped)."""
    # Hosted shared MySQL: full init_db + migrations on every LSAPI/Passenger worker
    # floods max_connections (1040) and kills live requests (marks save, dashboards).
    # Skip the heavy heal when core tables already exist unless forced.
    if is_hosted():
        force = (os.environ.get('DB_FORCE_SCHEMA_HEAL') or '').strip().lower() in (
            '1', 'true', 'yes', 'on',
        )
        if not force:
            if _hosted_core_tables_ready():
                _safe_startup_log("[DB] Hosted: core tables present; skipping full init_db")
                return True
            _safe_startup_log(
                "[DB] Hosted: core tables missing or DB busy — will retry. "
                "If this persists, set DB_FORCE_SCHEMA_HEAL=1 once, or run: python update_db.py"
            )
            # Do not stampede init_db while MySQL is refusing / over capacity.
            return False
    try:
        from db_health import check_and_heal
        ok, msg = check_and_heal()
        if ok:
            _safe_startup_log(f"[DB] {msg}")
        else:
            _safe_startup_log(f"[DB] Warning: {msg} - run: python update_db.py")
        return bool(ok)
    except Exception as e:
        _safe_startup_log(f"[DB] Check failed: {e}")
        if is_hosted() and _is_mysql_capacity_error(e):
            return False
        try:
            if init_db():
                _safe_startup_log("[DB] Tables created/verified (fallback)")
            from migrations.migration_manager import run_all_migrations
            run_all_migrations()
            return True
        except Exception as e2:
            _safe_startup_log(f"[DB] Fallback failed: {e2}")
            return False


_db_schema_initialized = False
_db_schema_lock = threading.Lock()


def _ensure_db_schema_once():
    global _db_schema_initialized
    if _db_schema_initialized:
        return
    with _db_schema_lock:
        if _db_schema_initialized:
            return
        try:
            ok = _ensure_db_schema()
            _db_schema_initialized = bool(ok)
        except Exception as ex:
            _db_schema_initialized = False
            _safe_startup_log(f"[DB] Schema ensure crashed: {ex}")


# /<role>/… → /dashboard/… ; /dashboard/<role-slug>/… → /dashboard/employee/…
app.wsgi_app = RootRolePathRewriteMiddleware(DashboardRolePathRewriteMiddleware(app.wsgi_app))

# Hosted: defer heavy DB init to first request (avoids Passenger broken-pipe/timeouts on import).
# Local with debug reloader: only init in the child process (WERKZEUG_RUN_MAIN=true) so logs
# and schema work are not duplicated by the reloader parent.
if is_hosted():
    @app.before_request
    def _hosted_deferred_db_schema():
        try:
            _ensure_db_schema_once()
        except Exception as ex:
            _safe_startup_log(f"[DB] Hosted deferred schema error: {ex}")
elif os.environ.get('WERKZEUG_RUN_MAIN') == 'true':
    _ensure_db_schema_once()
else:
    # No reloader child yet (or reloader parent): init on first request.
    # The reloader parent does not serve requests, so it will not run this.
    @app.before_request
    def _local_deferred_db_schema():
        try:
            _ensure_db_schema_once()
        except Exception as ex:
            _safe_startup_log(f"[DB] Local deferred schema error: {ex}")


@app.errorhandler(500)
def _handle_internal_server_error(err):
    """Log 500s to a file on the host so cPanel stderr is not the only clue."""
    try:
        import traceback
        log_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'tmp', 'app_500.log')
        os.makedirs(os.path.dirname(log_path), exist_ok=True)
        with open(log_path, 'a', encoding='utf-8') as fh:
            fh.write('\n==== %s %s %s ====\n' % (
                datetime.now().isoformat(timespec='seconds'),
                getattr(request, 'method', '?'),
                getattr(request, 'path', '?'),
            ))
            fh.write(traceback.format_exc())
            fh.write('\n')
    except Exception:
        pass
    try:
        accept = (request.headers.get('Accept') or '').lower()
        if 'application/json' in accept or request.headers.get('X-Requested-With', '').lower() == 'xmlhttprequest':
            return jsonify({'success': False, 'message': 'Internal server error. Please try again.'}), 500
    except Exception:
        pass
    return (
        '<!DOCTYPE html><html><head><title>Temporary error</title></head>'
        '<body style="font-family:sans-serif;padding:2rem">'
        '<h1>Something went wrong</h1>'
        '<p>Please refresh the page. If this continues, contact the school technician.</p>'
        '<p><a href="/">Back to home</a></p>'
        '</body></html>'
    ), 500


